window.YC_MORE_QBANKS=window.YC_MORE_QBANKS||[];window.YC_MORE_QBANKS.push([{"id":"yy-14323","module":"yanyu","diff":2,"exam":"省考","prompt":"乡村振兴，关键在人。当前不少农村面临「谁来种地」「谁来兴村」的难题，青壮年劳动力外流，懂农业、爱农村、爱农民的人才严重不足。破解人才瓶颈，既要筑巢引凤吸引外来人才，更要就地培养新型职业农民，让本土人才留得住、干得好。这段文字意在强调：","options":["乡村振兴关键在人才","破解乡村振兴人才瓶颈需引育并举","要吸引外来人才下乡","农村面临人才外流难题"],"answer":1,"explanation":"文段先点明人才对乡村振兴的重要性，再指出人才短缺问题，最后用「既要……更要……」提出引进与培养两条路径，主旨为引育并举。干扰项分别对应背景、问题、对策之一。故选B。","__sub":"片段阅读"},{"id":"yy-14324","module":"yanyu","diff":3,"exam":"教师编","prompt":"数字技术为文化遗产保护传承开辟了新路径。通过三维扫描、数字建模，敦煌壁画得以永久保存；借助VR技术，观众足不出户就能「走进」故宫。但数字化不是简单的拍照存档，更要深挖文化内涵，让文物真正「活」起来。这段文字意在说明：","options":["数字技术助力文化遗产保护","VR技术让观众云游故宫","敦煌壁画已实现数字化保存","文化遗产数字化要让文物真正活起来"],"answer":3,"explanation":"文段先举例说明数字化技术的作用，再用「但」转折，指出数字化不能停留在表面，要深挖内涵让文物「活」起来。干扰项均为例证部分，非重点。故选D。","__sub":"片段阅读"},{"id":"yy-14325","module":"yanyu","diff":2,"exam":"国考","prompt":"数字技术为基层治理插上翅膀，但一些地方的「数字治理」变了味：APP打卡代替实地走访，数据报表代替解决实际问题，基层干部成了「表哥表姐」。数字治理的落脚点应是治理效能提升，而不是数字形式主义。这段文字的主旨是：","options":["基层干部被各类报表困扰","治理效能是数字治理的落脚点","数字技术提升了基层治理效率","数字治理要防止陷入形式主义"],"answer":3,"explanation":"文段先肯定数字技术的作用，再通过「变了味」的现象列举数字形式主义的表现，最后点明落脚点在治理效能。干扰项分别对应背景、现象、对策表述。故选D。","__sub":"片段阅读"},{"id":"yy-14326","module":"yanyu","diff":2,"exam":"国考","prompt":"一些毕业生宁愿「慢就业」「缓就业」，也不愿到基层和中小企业去。事实上，基层是青年成长成才的广阔舞台，中小企业是吸纳就业的主渠道。转变就业观念，把个人理想融入国家发展，青年才能在广阔天地中大有作为。对这段文字概括最恰当的是：","options":["就业形势日益严峻","青年应转变观念到基层建功立业","基层和中小企业需要人才","毕业生就业观念存在偏差"],"answer":1,"explanation":"文段先指出部分毕业生就业观的问题，再说明基层和中小企业的价值，最后提出「转变观念、融入国家发展」的对策。干扰项分别对应现象、背景、背景。故选B。","__sub":"片段阅读"},{"id":"yy-14327","module":"yanyu","diff":3,"exam":"事业编","prompt":"绿色金融是推动绿色发展的重要支撑。当前绿色信贷、绿色债券等金融产品快速发展，但存在标准不统一、「洗绿」「漂绿」等问题。完善绿色金融体系，要统一绿色认定标准，强化环境信息披露，让金融活水真正流向绿色领域。这段文字主要讲述了：","options":["绿色金融支撑绿色发展","完善绿色金融体系需统一标准强化披露","金融活水应流向绿色领域","绿色金融产品快速发展"],"answer":1,"explanation":"文段先肯定绿色金融的定位，再指出标准不统一、「洗绿」等问题，最后落脚在「统一标准、强化披露」的对策。干扰项分别对应背景、背景、对策的比喻表述。故选B。","__sub":"片段阅读"},{"id":"yy-14328","module":"yanyu","diff":2,"exam":"省考","prompt":"全民健身是实现全民健康的重要途径。近年来各地体育设施不断完善，但「健身去哪儿」仍是群众反映强烈的问题，特别是群众身边的场地设施仍然不足。解决这一问题，要在盘活存量、扩大增量上下功夫，让体育资源真正惠及群众。这段文字意在强调：","options":["健身场地不足是突出问题","解决健身场地问题需盘活存量扩大增量","全民健身关乎全民健康","体育设施不断完善"],"answer":1,"explanation":"文段先点明全民健身的意义，再指出「健身去哪儿」的问题，最后落脚在「盘活存量、扩大增量」的对策。干扰项分别对应背景、背景、问题。故选B。","__sub":"片段阅读"},{"id":"yy-14329","module":"yanyu","diff":2,"exam":"事业编","prompt":"科技是双刃剑，伦理是方向盘。基因编辑、脑机接口等前沿技术一旦越轨，后果不堪设想。加强科技伦理治理，不是限制创新，而是为创新划定跑道，让科技始终朝着造福人类的方向发展。这段文字意在说明：","options":["科技应造福人类","科技伦理治理限制创新","前沿技术存在巨大风险","科技伦理治理为创新划定跑道"],"answer":3,"explanation":"文段用「双刃剑」「方向盘」的比喻，指出伦理治理的必要性，最后用「不是……而是……」澄清「伦理治理不是限制创新，而是划定跑道」。B项与原文表述相反，A、D项为部分表述。故选D。","__sub":"片段阅读"},{"id":"yy-14330","module":"yanyu","diff":3,"exam":"省考","prompt":"城市人口密集、要素集聚，也意味着风险集聚。极端天气、公共卫生事件等突发情况，考验着城市的应对能力。建设韧性城市，要把防灾减灾纳入城市规划建设全过程，提升基础设施抗风险能力，让城市更安全、更宜居。这段文字的主旨是：","options":["建设韧性城市需将防灾纳入规划全程","城市应更安全更宜居","城市风险集聚需要应对","极端天气考验城市能力"],"answer":0,"explanation":"文段先指出城市风险集聚的特点，再说明突发事件的考验，最后落脚在「把防灾减灾纳入规划建设全过程」的对策。干扰项分别对应背景、背景、目标表述。故选A。","__sub":"片段阅读"},{"id":"yy-14331","module":"yanyu","diff":2,"exam":"国考","prompt":"平台经济是经济发展的新引擎，但垄断和不正当竞争问题也随之而来。规范平台经济发展，不是要「一棍子打死」，而是要设置「红绿灯」，在鼓励创新与防范风险之间找到平衡，促进平台经济规范健康发展。对这段文字概括最恰当的是：","options":["要促进平台经济健康发展","平台垄断问题不容忽视","规范平台经济要在创新与风险间求平衡","平台经济是发展新引擎"],"answer":2,"explanation":"文段先肯定平台经济的作用，再指出垄断问题，最后用「不是……而是……」提出「设置红绿灯、找到平衡」的核心观点。干扰项分别对应背景、问题、对策的笼统表述。故选C。","__sub":"片段阅读"},{"id":"yy-14332","module":"yanyu","diff":2,"exam":"国考","prompt":"粮食安全是「国之大者」，节约粮食同样是保障粮食安全的重要一环。从田间到餐桌，粮食损耗和浪费现象仍然存在。制止餐饮浪费，既要加强立法监管，也要倡导节约风尚，让「光盘行动」成为社会共识。这段文字主要讲述了：","options":["粮食损耗浪费现象存在","粮食安全是国之大者","制止粮食浪费需监管与风尚并举","要倡导节约粮食的风尚"],"answer":2,"explanation":"文段先定位节约粮食的意义，再指出损耗浪费问题，最后用「既要……也要……」提出立法监管与风尚倡导两方面对策。干扰项分别对应背景、问题、对策之一。故选C。","__sub":"片段阅读"},{"id":"yy-14333","module":"yanyu","diff":3,"exam":"医疗编","prompt":"海洋是高质量发展的战略要地。我国海洋经济总量稳步增长，但产业结构偏重传统、新兴产业占比不高的问题仍然存在。壮大海洋经济，要推动传统海洋产业转型升级，培育海洋生物医药、海洋新能源等新兴业态。这段文字意在强调：","options":["海洋经济总量稳步增长","海洋是发展战略要地","壮大海洋经济需推动产业转型升级","要培育海洋新兴产业"],"answer":2,"explanation":"文段先定位海洋的战略地位，再指出产业结构问题，最后落脚在「转型升级、培育新兴业态」的对策。干扰项分别对应背景、背景、对策之一。故选C。","__sub":"片段阅读"},{"id":"yy-14334","module":"yanyu","diff":2,"exam":"教师编","prompt":"家庭是人生的第一所学校，家长是孩子的第一任老师。一些家长要么过度溺爱，要么简单粗暴，家庭教育方法失当的问题不容忽视。家庭教育促进法的实施，标志着家庭教育从「家事」上升为「国事」，家长要依法带娃、科学育儿。这段文字意在说明：","options":["家庭教育需要依法科学育儿","家庭教育方法存在失当","家庭教育促进法已实施","家庭是孩子的第一所学校"],"answer":0,"explanation":"文段先强调家庭教育的地位，再指出方法失当问题，最后落脚在「依法带娃、科学育儿」的对策。干扰项分别对应背景、问题、背景。故选A。","__sub":"片段阅读"},{"id":"yy-14335","module":"yanyu","diff":2,"exam":"事业编","prompt":"城市更新不是大拆大建，而是「绣花功夫」。老街区改造要保留历史文脉和城市记忆，避免千城一面；社区微更新要聚焦「一老一小」需求，完善便民服务设施。让城市留住记忆、让人们记住乡愁，城市更新才有温度。这段文字的主旨是：","options":["城市更新要下绣花功夫保留特色","社区要完善便民设施","老街区改造要保留文脉","城市更新不是大拆大建"],"answer":0,"explanation":"文段开篇用「绣花功夫」点明城市更新的理念，再从老街区和社区两个层面具体阐述，核心是精细化、有温度的更新。干扰项均为分论点表述。故选A。","__sub":"片段阅读"},{"id":"yy-14336","module":"yanyu","diff":3,"exam":"教师编","prompt":"数字乡村是乡村振兴的重要抓手。电商进村、智慧农业等数字化应用，让农产品出村进城更便捷，让农业生产更精准。但数字乡村建设不能搞「一刀切」，要因地制宜、分类推进，避免重复建设和资源浪费。对这段文字概括最恰当的是：","options":["数字应用提升农业精准度","数字乡村建设要因地制宜分类推进","数字乡村是乡村振兴抓手","电商让农产品流通更便捷"],"answer":1,"explanation":"文段先定位数字乡村的意义，再举例说明数字化应用的价值，最后用「但」转折，强调「因地制宜、分类推进」的核心要求。干扰项均为正面例证。故选B。","__sub":"片段阅读"},{"id":"yy-14337","module":"yanyu","diff":2,"exam":"省考","prompt":"产教融合是职业教育的生命线。一些职业院校课程设置与企业需求脱节，学生「学非所用、用非所学」的问题突出。深化产教融合，要推动校企共建实训基地、共编教材、共育人才，让人才培养紧跟产业需求。这段文字主要讲述了：","options":["要共建实训基地共育人才","课程设置与企业需求脱节","产教融合是职业教育生命线","深化产教融合需校企协同育人"],"answer":3,"explanation":"文段先点明产教融合的定位，再指出脱节问题，最后落脚在「共建、共编、共育」的校企协同对策。干扰项分别对应背景、问题、对策之一。故选D。","__sub":"片段阅读"},{"id":"yy-14338","module":"yanyu","diff":2,"exam":"医疗编","prompt":"绿水青山就是金山银山，关键要打通「两山」转化通道。生态产品价值实现机制还不健全，「度量难、抵押难、交易难、变现难」问题突出。要建立生态产品价值核算体系，健全生态补偿机制，让保护者受益、让利用者付费。这段文字意在强调：","options":["绿水青山就是金山银山","健全生态产品价值实现机制势在必行","生态产品价值实现机制不健全","要让保护者受益利用者付费"],"answer":1,"explanation":"文段先点明「两山」转化的关键，再指出「四难」问题，最后落脚在「建立核算体系、健全补偿机制」的对策。干扰项分别对应理念、问题、对策之一。故选B。","__sub":"片段阅读"},{"id":"yy-14339","module":"yanyu","diff":3,"exam":"国考","prompt":"制造业是立国之本、强国之基。当前一些地方「脱实向虚」倾向值得警惕，制造业占比过早过快下降。坚持制造业当家，要保持制造业合理比重，推动传统产业改造升级，培育壮大战略性新兴产业。这段文字意在说明：","options":["制造业占比下降值得警惕","制造业是立国之本强国之基","坚持制造业当家要保持合理比重","要培育战略性新兴产业"],"answer":2,"explanation":"文段先强调制造业的地位，再指出「脱实向虚」的问题，最后落脚在「保持比重、改造升级、培育新兴」的对策。干扰项分别对应背景、问题、对策之一。故选C。","__sub":"片段阅读"},{"id":"yy-14340","module":"yanyu","diff":2,"exam":"事业编","prompt":"基层医疗卫生机构是群众健康的「守门人」。但基层医疗机构普遍存在人才短缺、设备落后、服务能力不足等问题，「小病拖、大病扛」的现象在一些农村地区仍然存在。强基层，要让优质医疗资源下沉，提升基层服务能力。这段文字的主旨是：","options":["要让优质资源下沉基层","基层医疗存在诸多短板","基层医疗机构是健康守门人","提升基层医疗服务能力是强基层关键"],"answer":3,"explanation":"文段先定位基层医疗的角色，再列举问题，最后落脚在「资源下沉、提升能力」的对策。干扰项分别对应背景、问题、对策之一。故选D。","__sub":"片段阅读"},{"id":"yy-14341","module":"yanyu","diff":2,"exam":"省考","prompt":"保护知识产权就是保护创新。近年来知识产权侵权易发多发，维权成本高、举证难等问题突出。强化知识产权保护，要完善法律法规，加大惩罚性赔偿力度，让侵权者付出代价，让创新者安心创新。对这段文字概括最恰当的是：","options":["知识产权侵权易发多发","要让侵权者付出代价","强化知识产权保护需加大惩罚力度","保护知识产权就是保护创新"],"answer":2,"explanation":"文段先点明保护知识产权的意义，再指出侵权维权难的问题，最后落脚在「完善法律、加大惩罚」的对策。干扰项分别对应背景、问题、对策的比喻表述。故选C。","__sub":"片段阅读"},{"id":"yy-14342","module":"yanyu","diff":3,"exam":"医疗编","prompt":"新型城镇化要以人为核心。一些地方重物轻人，楼房建起来了，但农业转移人口市民化进程滞后，教育、医疗、住房等公共服务覆盖不足。推进新型城镇化，要深化户籍制度改革，让进城农民真正融入城市。这段文字主要讲述了：","options":["新型城镇化要推进农业转移人口市民化","新型城镇化以人为核心","公共服务覆盖不足问题存在","要深化户籍制度改革"],"answer":0,"explanation":"文段先点明「以人为核心」的理念，再指出「重物轻人」的问题，最后落脚在「户籍改革、市民化」的对策。干扰项分别对应理念、问题、对策之一。故选A。","__sub":"片段阅读"},{"id":"yy-14343","module":"yanyu","diff":2,"exam":"国考","prompt":"数字经济要与实体经济深度融合。一些企业盲目上系统、上平台，数字化改造流于形式，「为数字化而数字化」。推动数实融合，要立足企业实际需求，分行业分领域施策，让数字技术真正解决实际问题。这段文字意在强调：","options":["数字化改造存在形式主义","数字经济要与实体经济融合","数实融合要立足实际需求","要分行业分领域施策"],"answer":2,"explanation":"文段先提出融合的方向，再指出「为数字化而数字化」的问题，最后落脚在「立足需求、分类施策」的对策。干扰项分别对应方向、问题、对策之一。故选C。","__sub":"片段阅读"},{"id":"yy-14344","module":"yanyu","diff":2,"exam":"省考","prompt":"我国已进入中度老龄化社会，养老服务需求快速增长。居家养老仍是主要方式，但适老化改造滞后，专业照护服务短缺。构建养老服务体系，要以居家为基础、社区为依托、机构为补充，让老年人安享晚年。这段文字意在说明：","options":["要以居家社区机构协同","构建养老服务体系需三方协同","居家养老是主要方式","我国进入中度老龄化社会"],"answer":1,"explanation":"文段先指出老龄化背景，再说明居家养老的现状与短板，最后落脚在「居家为基础、社区为依托、机构为补充」的体系构建。干扰项分别对应背景、现状、对策之一。故选B。","__sub":"片段阅读"},{"id":"yy-14345","module":"yanyu","diff":3,"exam":"国考","prompt":"营商环境是企业生存发展的土壤。一个地区的竞争力，很大程度上取决于营商环境的优劣。优化营商环境，既要深化「放管服」改革，降低制度性交易成本，也要构建亲清政商关系，让企业安心经营、放心投资。这段文字的主旨是：","options":["营商环境是企业发展的土壤","要构建亲清政商关系","优化营商环境需改革与亲清关系并重","要深化放管服改革"],"answer":2,"explanation":"文段先点明营商环境的定位，再从「放管服改革」和「亲清政商关系」两方面提出要求，主旨为两方面对策。干扰项分别对应背景、对策之一、对策之一。故选C。","__sub":"片段阅读"},{"id":"yy-14346","module":"yanyu","diff":2,"exam":"事业编","prompt":"就业是最大的民生。稳就业保就业，既要稳存量，也要拓增量。要支持中小微企业稳岗扩岗，发展新业态创造新岗位，加强职业技能培训，让劳动者端稳就业「饭碗」。对这段文字概括最恰当的是：","options":["稳就业需稳存量拓增量并举","要加强职业技能培训","就业是最大的民生","要支持企业稳岗扩岗"],"answer":0,"explanation":"文段先点明就业的民生意义，再从「稳存量、拓增量」两方面展开，具体包括稳岗扩岗、新业态、技能培训等对策。干扰项分别对应背景、对策之一、对策之一。故选A。","__sub":"片段阅读"},{"id":"yy-14347","module":"yanyu","diff":2,"exam":"事业编","prompt":"「双减」政策落地以来，学科类校外培训明显压减，但部分培训转入「地下」，隐形变异问题仍然存在。巩固「双减」成果，要强化学校教育主阵地作用，提升课堂教学质量，同时加强隐形变异培训的监管。这段文字主要讲述了：","options":["要强化学校主阵地作用","隐形变异培训问题仍存在","双减政策已取得明显成效","巩固双减成果需校内外协同发力"],"answer":3,"explanation":"文段先肯定双减成效，再指出隐形变异问题，最后落脚在「校内提质、校外监管」两方面对策。干扰项分别对应成效、问题、对策之一。故选D。","__sub":"片段阅读"},{"id":"yy-14348","module":"yanyu","diff":3,"exam":"国考","prompt":"食品安全没有「零风险」，但监管必须「零容忍」。从农田到餐桌，链条长、环节多，任何一个环节出问题都可能酿成事故。保障食品安全，要落实「四个最严」要求，压实各方责任，织密食品安全防护网。这段文字意在强调：","options":["食品链条长环节多","食品安全不存在零风险","保障食品安全需落实最严监管","要落实四个最严要求"],"answer":2,"explanation":"文段用「零风险」「零容忍」的对比，指出食品链条的特点，最后落脚在「四个最严、压实责任」的对策。干扰项分别对应背景、背景、对策的笼统表述。故选C。","__sub":"片段阅读"},{"id":"yy-14349","module":"yanyu","diff":2,"exam":"国考","prompt":"能源转型是应对气候变化的必然选择。但能源转型不能「一刀切」地弃煤、弃油，要先立后破，确保能源安全。推动新能源发展，要与传统能源平稳衔接，让能源转型既「快」又「稳」。这段文字意在说明：","options":["能源转型是必然选择","能源转型要先立后破确保安全","不能一刀切地弃煤弃油","新能源要与传统能源衔接"],"answer":1,"explanation":"文段先点明能源转型的必然性，再用「不能……要……」提出「先立后破」的核心要求，最后强调平稳衔接。干扰项分别对应背景、要求之一、要求之一。故选B。","__sub":"语句表达"},{"id":"yy-14350","module":"yanyu","diff":2,"exam":"医疗编","prompt":"产业振兴是乡村振兴的重中之重。一些乡村产业发展存在同质化问题，你种苹果我也种苹果，最终恶性竞争。发展乡村产业，要立足本地资源禀赋，打造「一村一品」「一县一业」，走差异化发展路子。这段文字的主旨是：","options":["乡村产业存在同质化问题","要打造一村一品一县一业","产业振兴是乡村振兴重点","发展乡村产业要走差异化路子"],"answer":3,"explanation":"文段先点明产业振兴的地位，再指出同质化竞争的问题，最后落脚在「立足禀赋、差异化发展」的对策。干扰项分别对应背景、问题、对策的具体表述。故选D。","__sub":"片段阅读"},{"id":"yy-14351","module":"yanyu","diff":3,"exam":"国考","prompt":"关键核心技术是要不来、买不来、讨不来的。面对外部技术封锁，惟有自立自强。要加强基础研究，突破「卡脖子」技术，掌握发展主动权，把创新主动权牢牢掌握在自己手中。对这段文字概括最恰当的是：","options":["突破关键核心技术需自立自强","外部存在技术封锁","关键核心技术无法通过购买获得","要加强基础研究突破瓶颈"],"answer":0,"explanation":"文段开篇用「要不来、买不来、讨不来」强调核心技术的特殊性，再指出外部封锁的现实，最后落脚在「加强基础研究、突破瓶颈」的对策。干扰项分别对应背景、背景、对策之一。故选A。","__sub":"片段阅读"},{"id":"yy-14352","module":"yanyu","diff":2,"exam":"省考","prompt":"文化自信是更基础、更广泛、更深厚的自信。中华优秀传统文化蕴含着丰富的哲学思想、人文精神、道德理念。坚定文化自信，要推动中华优秀传统文化创造性转化、创新性发展，让中华文化展现永久魅力和时代风采。这段文字主要讲述了：","options":["要推动传统文化创新发展","坚定文化自信需推动传统文化创新发展","文化自信是更基础的自信","传统文化蕴含丰富思想"],"answer":1,"explanation":"文段先点明文化自信的地位，再说明传统文化的内涵，最后落脚在「创造性转化、创新性发展」的对策。干扰项分别对应背景、背景、对策之一。故选B。","__sub":"片段阅读"},{"id":"yy-14353","module":"yanyu","diff":2,"exam":"省考","prompt":"共同富裕是社会主义的本质要求。共同富裕不是同步富裕，也不是均贫富，要允许一部分人先富起来，先富带后富。促进共同富裕，要构建初次分配、再分配、三次分配协调配套的制度体系。这段文字意在强调：","options":["要构建三次分配制度体系","共同富裕不是同步富裕","促进共同富裕需完善分配制度体系","共同富裕是本质要求"],"answer":2,"explanation":"文段先点明共同富裕的定位，再用「不是……也不是……」澄清认识误区，最后落脚在「三次分配制度体系」的对策。干扰项分别对应定位、澄清、对策之一。故选C。","__sub":"片段阅读"},{"id":"yy-14354","module":"yanyu","diff":3,"exam":"省考","prompt":"安全生产责任重于泰山。一些事故的发生，往往源于麻痹大意和侥幸心理，「海恩法则」告诉我们，每一起严重事故背后，必然有多次轻微事故和大量事故隐患。抓好安全生产，要把隐患当事故看，防微杜渐、常抓不懈。这段文字意在说明：","options":["安全生产责任重大","事故源于麻痹侥幸心理","安全生产要防微杜渐常抓不懈","要把隐患当事故看"],"answer":2,"explanation":"文段先强调安全生产的重要性，再用「海恩法则」说明隐患与事故的关系，最后落脚在「防微杜渐、常抓不懈」的要求。干扰项分别对应背景、原因分析、对策之一。故选C。","__sub":"片段阅读"},{"id":"yy-14355","module":"yanyu","diff":2,"exam":"国考","prompt":"传统村落是农耕文明的珍贵遗产，承载着大量的历史记忆和地域文化信息。然而随着城镇化进程加快，不少传统村落面临空心化、建筑破损、文化断裂等问题。保护传统村落，不能只靠情怀，更要建立长效机制，让村民在保护中受益，让村落保护与乡村发展相互促进。对这段文字概括最恰当的是：","options":["传统村落面临空心化等诸多问题","传统村落保护需要建立让村民受益的长效机制","城镇化进程加快冲击了传统村落","传统村落承载着历史记忆和文化信息"],"answer":1,"explanation":"文段先说传统村落的价值，再指出问题，最后落脚点在「要建立长效机制，让村民受益、保护与发展相互促进」，主旨为对策句。三个干扰项分别对应背景、问题、价值，均非重点。故选B。","__sub":"片段阅读"},{"id":"yy-14356","module":"yanyu","diff":2,"exam":"事业编","prompt":"数字经济时代，数据成为重要的生产要素。但数据要素市场尚不成熟，存在权属不清、流通不畅、监管滞后等问题。推动数据要素市场化配置，需要完善产权制度、健全流通机制、加强安全监管，多措并举、协同发力。这段文字主要讲述了：","options":["数据要素市场存在权属不清问题","数据已成为重要的生产要素","数字经济时代已经全面到来","发展数据要素市场需要多方面协同推进"],"answer":3,"explanation":"文段先肯定数据要素的地位，再列举问题，最后用「需要……多措并举、协同发力」提出对策，主旨在对策。干扰项分别对应背景、问题之一、背景。故选D。","__sub":"片段阅读"},{"id":"yy-14357","module":"yanyu","diff":3,"exam":"事业编","prompt":"基层减负不能停留在「减」字上。有的地方文山会海压下去了，但「指尖上的形式主义」又冒出来，各类政务APP、工作群反而让基层干部疲于应付。根治形式主义，关键在树立正确政绩观，从源头上改革考核评价体系。这段文字意在强调：","options":["政务APP和工作群加重了基层负担","根治基层形式主义需从考核体系入手","基层减负取得了一定成效","形式主义的表现形式不断变化"],"answer":1,"explanation":"文段通过「文山会海压下去、指尖形式主义冒出来」的现象，引出「关键在树立正确政绩观、从源头改革考核评价体系」这一对策，主旨为对策句。干扰项均为现象描述。故选B。","__sub":"片段阅读"},{"id":"yy-14358","module":"yanyu","diff":2,"exam":"医疗编","prompt":"科学家精神是科技工作者在长期科学实践中积累的宝贵精神财富。爱国、创新、求实、奉献、协同、育人，这六个方面共同构成了新时代科学家精神的核心内涵。弘扬科学家精神，不仅要说，更要做，要在重大科技攻关任务中见真章。这段文字意在说明：","options":["科技工作者要具备爱国奉献精神","弘扬科学家精神要在实践中落实","科学家精神是宝贵的精神财富","科学家精神包含六个方面的内涵"],"answer":1,"explanation":"文段先阐释科学家精神的内涵，最后强调「不仅要说，更要做，要在重大科技攻关任务中见真章」，重点在实践落实。干扰项均为内涵阐释部分。故选B。","__sub":"片段阅读"},{"id":"yy-14359","module":"yanyu","diff":2,"exam":"省考","prompt":"湿地被称为「地球之肾」，具有涵养水源、净化水质、调蓄洪水、调节气候等重要生态功能。近年来一些地方围垦、污染导致湿地面积萎缩、功能退化。保护湿地要处理好发展与保护的关系，划定生态红线，实行最严格的保护制度。这段文字的主旨是：","options":["湿地面积萎缩功能退化","湿地保护需要实行最严格的制度","湿地具有重要的生态功能","发展与环境的关系需要协调"],"answer":1,"explanation":"文段先说明湿地功能，再指出问题，最后落脚在「划定生态红线，实行最严格的保护制度」这一对策。干扰项对应背景与问题。故选B。","__sub":"片段阅读"},{"id":"yy-14360","module":"yanyu","diff":3,"exam":"国考","prompt":"老旧小区改造是城市更新的重要内容。改造不能政府「唱独角戏」，要充分听取居民意见，引导居民出资参与，让改造方案更贴合实际需求。同时要建立后续长效管理机制，避免「改完就乱、前改后坏」。对这段文字概括最恰当的是：","options":["改造方案要贴合居民实际需求","老旧小区改造是城市更新的内容","老旧小区改造需居民参与并长效管理","政府不应独自承担改造责任"],"answer":2,"explanation":"文段先定位老旧小区改造的意义，再从「居民参与」和「长效管理」两方面提出要求，主旨为两方面对策的概括。A项只是背景，B项只覆盖一个方面，C项表述绝对且偏离重点。故选C。","__sub":"片段阅读"},{"id":"yy-14361","module":"yanyu","diff":2,"exam":"国考","prompt":"技能人才是支撑中国制造、中国创造的重要力量。当前技能人才总量不足、结构不优的问题仍然突出，高级技工求人倍率长期保持在2以上。发展职业教育，要破除重学历轻技能的观念，畅通技能人才成长通道，让技能人才有地位、有奔头。这段文字主要讲述了：","options":["技能人才总量不足结构不优","发展职业教育要畅通技能人才成长通道","要破除重学历轻技能的观念","技能人才是重要力量"],"answer":1,"explanation":"文段先肯定技能人才的重要性，再指出问题，最后落脚在「破除观念、畅通通道、让技能人才有地位」这一对策。干扰项分别对应背景、问题、对策之一。故选B。","__sub":"片段阅读"},{"id":"yy-14362","module":"yanyu","diff":2,"exam":"事业编","prompt":"我国老年人口规模庞大，银发经济蕴含巨大发展空间。但当前养老服务供给还存在总量不足、结构失衡、质量不高等问题。发展银发经济，既要发挥政府保基本、兜底线的作用，更要激发市场活力，引导社会力量广泛参与。这段文字意在强调：","options":["发展银发经济需政府市场协同发力","养老服务供给存在诸多问题","政府要保基本兜底线","银发经济蕴含巨大发展空间"],"answer":0,"explanation":"文段先指出银发经济的空间，再列举问题，最后用「既要……更要……」提出政府与市场两方面的要求，主旨为协同发力。干扰项分别对应背景、问题、对策之一。故选A。","__sub":"片段阅读"},{"id":"yy-14363","module":"yanyu","diff":3,"exam":"事业编","prompt":"种子是农业的「芯片」，种业安全关乎粮食安全。当前我国种业自主创新能力与世界先进水平仍有差距，部分领域种子对外依存度高。推进种业振兴，要加强种质资源保护利用，强化企业创新主体地位，推动产学研深度融合。这段文字意在说明：","options":["我国种业自主创新能力有差距","要加强种质资源保护利用","种业安全关乎粮食安全","推进种业振兴需强化自主创新"],"answer":3,"explanation":"文段以「芯片」比喻强调种业重要性，指出创新能力不足的问题，最后落脚在「加强保护利用、强化企业创新、产学研融合」等对策，核心指向自主创新。干扰项分别对应背景、问题、对策之一。故选D。","__sub":"片段阅读"},{"id":"yy-14364","module":"yanyu","diff":2,"exam":"事业编","prompt":"夜间经济是城市消费的新蓝海。发展夜经济不是简单地延长营业时间，而要在业态创新、场景营造、配套服务上下功夫，让消费者愿意来、留得住、玩得好。同时要平衡好繁荣与扰民的关系，让夜经济既有烟火气又有文明范。这段文字的主旨是：","options":["要平衡繁荣与扰民的关系","发展夜经济要注重业态创新与规范引导","夜间经济是城市消费新蓝海","夜经济不只是延长营业时间"],"answer":1,"explanation":"文段先定位夜经济的意义，再从「业态创新、场景营造、配套服务」和「平衡关系」两方面提出要求，主旨为综合对策。干扰项分别对应背景、对策之一、对策之一。故选B。","__sub":"片段阅读"},{"id":"yy-14365","module":"yanyu","diff":2,"exam":"事业编","prompt":"人工智能技术在带来便利的同时，也引发了算法歧视、隐私泄露、深度伪造等风险。治理人工智能，不能等到问题积累后再「亡羊补牢」，要坚持发展与规范并重，在鼓励创新的同时划清伦理和法律底线。对这段文字概括最恰当的是：","options":["算法歧视等问题亟待解决","人工智能治理应坚持发展与规范并重","要鼓励人工智能创新发展","人工智能带来了诸多风险"],"answer":1,"explanation":"文段先指出AI的风险，再用「不能……要……」提出「发展与规范并重」的核心观点。干扰项分别对应问题、对策之一、问题。故选B。","__sub":"片段阅读"},{"id":"yy-14366","module":"yanyu","diff":3,"exam":"国考","prompt":"乡村振兴，关键在人。当前不少农村面临「谁来种地」「谁来兴村」的难题，青壮年劳动力外流，懂农业、爱农村、爱农民的人才严重不足。破解人才瓶颈，既要筑巢引凤吸引外来人才，更要就地培养新型职业农民，让本土人才留得住、干得好。这段文字主要讲述了：","options":["要吸引外来人才下乡","农村面临人才外流难题","乡村振兴关键在人才","破解乡村振兴人才瓶颈需引育并举"],"answer":3,"explanation":"文段先点明人才对乡村振兴的重要性，再指出人才短缺问题，最后用「既要……更要……」提出引进与培养两条路径，主旨为引育并举。干扰项分别对应背景、问题、对策之一。故选D。","__sub":"片段阅读"},{"id":"yy-14367","module":"yanyu","diff":2,"exam":"省考","prompt":"数字技术为文化遗产保护传承开辟了新路径。通过三维扫描、数字建模，敦煌壁画得以永久保存；借助VR技术，观众足不出户就能「走进」故宫。但数字化不是简单的拍照存档，更要深挖文化内涵，让文物真正「活」起来。这段文字意在强调：","options":["数字技术助力文化遗产保护","VR技术让观众云游故宫","敦煌壁画已实现数字化保存","文化遗产数字化要让文物真正活起来"],"answer":3,"explanation":"文段先举例说明数字化技术的作用，再用「但」转折，指出数字化不能停留在表面，要深挖内涵让文物「活」起来。干扰项均为例证部分，非重点。故选D。","__sub":"片段阅读"},{"id":"yy-14368","module":"yanyu","diff":2,"exam":"国考","prompt":"数字技术为基层治理插上翅膀，但一些地方的「数字治理」变了味：APP打卡代替实地走访，数据报表代替解决实际问题，基层干部成了「表哥表姐」。数字治理的落脚点应是治理效能提升，而不是数字形式主义。这段文字意在说明：","options":["数字治理要防止陷入形式主义","治理效能是数字治理的落脚点","数字技术提升了基层治理效率","基层干部被各类报表困扰"],"answer":0,"explanation":"文段先肯定数字技术的作用，再通过「变了味」的现象列举数字形式主义的表现，最后点明落脚点在治理效能。干扰项分别对应背景、现象、对策表述。故选A。","__sub":"片段阅读"},{"id":"yy-14369","module":"yanyu","diff":3,"exam":"省考","prompt":"一些毕业生宁愿「慢就业」「缓就业」，也不愿到基层和中小企业去。事实上，基层是青年成长成才的广阔舞台，中小企业是吸纳就业的主渠道。转变就业观念，把个人理想融入国家发展，青年才能在广阔天地中大有作为。这段文字的主旨是：","options":["毕业生就业观念存在偏差","青年应转变观念到基层建功立业","基层和中小企业需要人才","就业形势日益严峻"],"answer":1,"explanation":"文段先指出部分毕业生就业观的问题，再说明基层和中小企业的价值，最后提出「转变观念、融入国家发展」的对策。干扰项分别对应现象、背景、背景。故选B。","__sub":"片段阅读"},{"id":"yy-14370","module":"yanyu","diff":2,"exam":"医疗编","prompt":"绿色金融是推动绿色发展的重要支撑。当前绿色信贷、绿色债券等金融产品快速发展，但存在标准不统一、「洗绿」「漂绿」等问题。完善绿色金融体系，要统一绿色认定标准，强化环境信息披露，让金融活水真正流向绿色领域。对这段文字概括最恰当的是：","options":["完善绿色金融体系需统一标准强化披露","绿色金融产品快速发展","绿色金融支撑绿色发展","金融活水应流向绿色领域"],"answer":0,"explanation":"文段先肯定绿色金融的定位，再指出标准不统一、「洗绿」等问题，最后落脚在「统一标准、强化披露」的对策。干扰项分别对应背景、背景、对策的比喻表述。故选A。","__sub":"片段阅读"},{"id":"yy-14371","module":"yanyu","diff":2,"exam":"事业编","prompt":"全民健身是实现全民健康的重要途径。近年来各地体育设施不断完善，但「健身去哪儿」仍是群众反映强烈的问题，特别是群众身边的场地设施仍然不足。解决这一问题，要在盘活存量、扩大增量上下功夫，让体育资源真正惠及群众。这段文字主要讲述了：","options":["解决健身场地问题需盘活存量扩大增量","体育设施不断完善","全民健身关乎全民健康","健身场地不足是突出问题"],"answer":0,"explanation":"文段先点明全民健身的意义，再指出「健身去哪儿」的问题，最后落脚在「盘活存量、扩大增量」的对策。干扰项分别对应背景、背景、问题。故选A。","__sub":"片段阅读"},{"id":"yy-14372","module":"yanyu","diff":3,"exam":"国考","prompt":"科技是双刃剑，伦理是方向盘。基因编辑、脑机接口等前沿技术一旦越轨，后果不堪设想。加强科技伦理治理，不是限制创新，而是为创新划定跑道，让科技始终朝着造福人类的方向发展。这段文字意在强调：","options":["科技应造福人类","科技伦理治理为创新划定跑道","科技伦理治理限制创新","前沿技术存在巨大风险"],"answer":1,"explanation":"文段用「双刃剑」「方向盘」的比喻，指出伦理治理的必要性，最后用「不是……而是……」澄清「伦理治理不是限制创新，而是划定跑道」。B项与原文表述相反，A、D项为部分表述。故选B。","__sub":"片段阅读"},{"id":"yy-14373","module":"yanyu","diff":2,"exam":"国考","prompt":"城市人口密集、要素集聚，也意味着风险集聚。极端天气、公共卫生事件等突发情况，考验着城市的应对能力。建设韧性城市，要把防灾减灾纳入城市规划建设全过程，提升基础设施抗风险能力，让城市更安全、更宜居。这段文字意在说明：","options":["城市应更安全更宜居","极端天气考验城市能力","城市风险集聚需要应对","建设韧性城市需将防灾纳入规划全程"],"answer":3,"explanation":"文段先指出城市风险集聚的特点，再说明突发事件的考验，最后落脚在「把防灾减灾纳入规划建设全过程」的对策。干扰项分别对应背景、背景、目标表述。故选D。","__sub":"片段阅读"},{"id":"yy-14374","module":"yanyu","diff":2,"exam":"省考","prompt":"平台经济是经济发展的新引擎，但垄断和不正当竞争问题也随之而来。规范平台经济发展，不是要「一棍子打死」，而是要设置「红绿灯」，在鼓励创新与防范风险之间找到平衡，促进平台经济规范健康发展。这段文字的主旨是：","options":["要促进平台经济健康发展","规范平台经济要在创新与风险间求平衡","平台经济是发展新引擎","平台垄断问题不容忽视"],"answer":1,"explanation":"文段先肯定平台经济的作用，再指出垄断问题，最后用「不是……而是……」提出「设置红绿灯、找到平衡」的核心观点。干扰项分别对应背景、问题、对策的笼统表述。故选B。","__sub":"片段阅读"},{"id":"yy-14375","module":"yanyu","diff":3,"exam":"省考","prompt":"粮食安全是「国之大者」，节约粮食同样是保障粮食安全的重要一环。从田间到餐桌，粮食损耗和浪费现象仍然存在。制止餐饮浪费，既要加强立法监管，也要倡导节约风尚，让「光盘行动」成为社会共识。对这段文字概括最恰当的是：","options":["制止粮食浪费需监管与风尚并举","粮食损耗浪费现象存在","粮食安全是国之大者","要倡导节约粮食的风尚"],"answer":0,"explanation":"文段先定位节约粮食的意义，再指出损耗浪费问题，最后用「既要……也要……」提出立法监管与风尚倡导两方面对策。干扰项分别对应背景、问题、对策之一。故选A。","__sub":"片段阅读"},{"id":"yy-14376","module":"yanyu","diff":2,"exam":"国考","prompt":"海洋是高质量发展的战略要地。我国海洋经济总量稳步增长，但产业结构偏重传统、新兴产业占比不高的问题仍然存在。壮大海洋经济，要推动传统海洋产业转型升级，培育海洋生物医药、海洋新能源等新兴业态。这段文字主要讲述了：","options":["海洋经济总量稳步增长","要培育海洋新兴产业","海洋是发展战略要地","壮大海洋经济需推动产业转型升级"],"answer":3,"explanation":"文段先定位海洋的战略地位，再指出产业结构问题，最后落脚在「转型升级、培育新兴业态」的对策。干扰项分别对应背景、背景、对策之一。故选D。","__sub":"片段阅读"},{"id":"yy-14377","module":"yanyu","diff":2,"exam":"事业编","prompt":"家庭是人生的第一所学校，家长是孩子的第一任老师。一些家长要么过度溺爱，要么简单粗暴，家庭教育方法失当的问题不容忽视。家庭教育促进法的实施，标志着家庭教育从「家事」上升为「国事」，家长要依法带娃、科学育儿。这段文字意在强调：","options":["家庭是孩子的第一所学校","家庭教育促进法已实施","家庭教育需要依法科学育儿","家庭教育方法存在失当"],"answer":2,"explanation":"文段先强调家庭教育的地位，再指出方法失当问题，最后落脚在「依法带娃、科学育儿」的对策。干扰项分别对应背景、问题、背景。故选C。","__sub":"片段阅读"},{"id":"yy-14378","module":"yanyu","diff":3,"exam":"省考","prompt":"城市更新不是大拆大建，而是「绣花功夫」。老街区改造要保留历史文脉和城市记忆，避免千城一面；社区微更新要聚焦「一老一小」需求，完善便民服务设施。让城市留住记忆、让人们记住乡愁，城市更新才有温度。这段文字意在说明：","options":["社区要完善便民设施","城市更新要下绣花功夫保留特色","老街区改造要保留文脉","城市更新不是大拆大建"],"answer":1,"explanation":"文段开篇用「绣花功夫」点明城市更新的理念，再从老街区和社区两个层面具体阐述，核心是精细化、有温度的更新。干扰项均为分论点表述。故选B。","__sub":"片段阅读"},{"id":"yy-14379","module":"yanyu","diff":2,"exam":"医疗编","prompt":"数字乡村是乡村振兴的重要抓手。电商进村、智慧农业等数字化应用，让农产品出村进城更便捷，让农业生产更精准。但数字乡村建设不能搞「一刀切」，要因地制宜、分类推进，避免重复建设和资源浪费。这段文字的主旨是：","options":["电商让农产品流通更便捷","数字乡村建设要因地制宜分类推进","数字乡村是乡村振兴抓手","数字应用提升农业精准度"],"answer":1,"explanation":"文段先定位数字乡村的意义，再举例说明数字化应用的价值，最后用「但」转折，强调「因地制宜、分类推进」的核心要求。干扰项均为正面例证。故选B。","__sub":"片段阅读"},{"id":"yy-14380","module":"yanyu","diff":2,"exam":"国考","prompt":"产教融合是职业教育的生命线。一些职业院校课程设置与企业需求脱节，学生「学非所用、用非所学」的问题突出。深化产教融合，要推动校企共建实训基地、共编教材、共育人才，让人才培养紧跟产业需求。对这段文字概括最恰当的是：","options":["要共建实训基地共育人才","深化产教融合需校企协同育人","产教融合是职业教育生命线","课程设置与企业需求脱节"],"answer":1,"explanation":"文段先点明产教融合的定位，再指出脱节问题，最后落脚在「共建、共编、共育」的校企协同对策。干扰项分别对应背景、问题、对策之一。故选B。","__sub":"片段阅读"},{"id":"yy-14381","module":"yanyu","diff":3,"exam":"省考","prompt":"绿水青山就是金山银山，关键要打通「两山」转化通道。生态产品价值实现机制还不健全，「度量难、抵押难、交易难、变现难」问题突出。要建立生态产品价值核算体系，健全生态补偿机制，让保护者受益、让利用者付费。这段文字主要讲述了：","options":["绿水青山就是金山银山","健全生态产品价值实现机制势在必行","生态产品价值实现机制不健全","要让保护者受益利用者付费"],"answer":1,"explanation":"文段先点明「两山」转化的关键，再指出「四难」问题，最后落脚在「建立核算体系、健全补偿机制」的对策。干扰项分别对应理念、问题、对策之一。故选B。","__sub":"片段阅读"},{"id":"yy-14382","module":"yanyu","diff":2,"exam":"国考","prompt":"制造业是立国之本、强国之基。当前一些地方「脱实向虚」倾向值得警惕，制造业占比过早过快下降。坚持制造业当家，要保持制造业合理比重，推动传统产业改造升级，培育壮大战略性新兴产业。这段文字意在强调：","options":["制造业是立国之本强国之基","要培育战略性新兴产业","制造业占比下降值得警惕","坚持制造业当家要保持合理比重"],"answer":3,"explanation":"文段先强调制造业的地位，再指出「脱实向虚」的问题，最后落脚在「保持比重、改造升级、培育新兴」的对策。干扰项分别对应背景、问题、对策之一。故选D。","__sub":"片段阅读"},{"id":"yy-14383","module":"yanyu","diff":2,"exam":"省考","prompt":"基层医疗卫生机构是群众健康的「守门人」。但基层医疗机构普遍存在人才短缺、设备落后、服务能力不足等问题，「小病拖、大病扛」的现象在一些农村地区仍然存在。强基层，要让优质医疗资源下沉，提升基层服务能力。这段文字意在说明：","options":["提升基层医疗服务能力是强基层关键","基层医疗存在诸多短板","要让优质资源下沉基层","基层医疗机构是健康守门人"],"answer":0,"explanation":"文段先定位基层医疗的角色，再列举问题，最后落脚在「资源下沉、提升能力」的对策。干扰项分别对应背景、问题、对策之一。故选A。","__sub":"片段阅读"},{"id":"yy-14384","module":"yanyu","diff":3,"exam":"事业编","prompt":"保护知识产权就是保护创新。近年来知识产权侵权易发多发，维权成本高、举证难等问题突出。强化知识产权保护，要完善法律法规，加大惩罚性赔偿力度，让侵权者付出代价，让创新者安心创新。这段文字的主旨是：","options":["要让侵权者付出代价","知识产权侵权易发多发","强化知识产权保护需加大惩罚力度","保护知识产权就是保护创新"],"answer":2,"explanation":"文段先点明保护知识产权的意义，再指出侵权维权难的问题，最后落脚在「完善法律、加大惩罚」的对策。干扰项分别对应背景、问题、对策的比喻表述。故选C。","__sub":"片段阅读"},{"id":"yy-14385","module":"yanyu","diff":2,"exam":"事业编","prompt":"新型城镇化要以人为核心。一些地方重物轻人，楼房建起来了，但农业转移人口市民化进程滞后，教育、医疗、住房等公共服务覆盖不足。推进新型城镇化，要深化户籍制度改革，让进城农民真正融入城市。对这段文字概括最恰当的是：","options":["新型城镇化以人为核心","新型城镇化要推进农业转移人口市民化","要深化户籍制度改革","公共服务覆盖不足问题存在"],"answer":1,"explanation":"文段先点明「以人为核心」的理念，再指出「重物轻人」的问题，最后落脚在「户籍改革、市民化」的对策。干扰项分别对应理念、问题、对策之一。故选B。","__sub":"片段阅读"},{"id":"yy-14386","module":"yanyu","diff":2,"exam":"事业编","prompt":"数字经济要与实体经济深度融合。一些企业盲目上系统、上平台，数字化改造流于形式，「为数字化而数字化」。推动数实融合，要立足企业实际需求，分行业分领域施策，让数字技术真正解决实际问题。这段文字主要讲述了：","options":["数字经济要与实体经济融合","要分行业分领域施策","数实融合要立足实际需求","数字化改造存在形式主义"],"answer":2,"explanation":"文段先提出融合的方向，再指出「为数字化而数字化」的问题，最后落脚在「立足需求、分类施策」的对策。干扰项分别对应方向、问题、对策之一。故选C。","__sub":"片段阅读"},{"id":"yy-14387","module":"yanyu","diff":3,"exam":"事业编","prompt":"我国已进入中度老龄化社会，养老服务需求快速增长。居家养老仍是主要方式，但适老化改造滞后，专业照护服务短缺。构建养老服务体系，要以居家为基础、社区为依托、机构为补充，让老年人安享晚年。这段文字意在强调：","options":["我国进入中度老龄化社会","要以居家社区机构协同","构建养老服务体系需三方协同","居家养老是主要方式"],"answer":2,"explanation":"文段先指出老龄化背景，再说明居家养老的现状与短板，最后落脚在「居家为基础、社区为依托、机构为补充」的体系构建。干扰项分别对应背景、现状、对策之一。故选C。","__sub":"片段阅读"},{"id":"yy-14388","module":"yanyu","diff":2,"exam":"省考","prompt":"营商环境是企业生存发展的土壤。一个地区的竞争力，很大程度上取决于营商环境的优劣。优化营商环境，既要深化「放管服」改革，降低制度性交易成本，也要构建亲清政商关系，让企业安心经营、放心投资。这段文字意在说明：","options":["优化营商环境需改革与亲清关系并重","营商环境是企业发展的土壤","要深化放管服改革","要构建亲清政商关系"],"answer":0,"explanation":"文段先点明营商环境的定位，再从「放管服改革」和「亲清政商关系」两方面提出要求，主旨为两方面对策。干扰项分别对应背景、对策之一、对策之一。故选A。","__sub":"片段阅读"},{"id":"yy-14389","module":"yanyu","diff":2,"exam":"国考","prompt":"就业是最大的民生。稳就业保就业，既要稳存量，也要拓增量。要支持中小微企业稳岗扩岗，发展新业态创造新岗位，加强职业技能培训，让劳动者端稳就业「饭碗」。这段文字的主旨是：","options":["要支持企业稳岗扩岗","就业是最大的民生","稳就业需稳存量拓增量并举","要加强职业技能培训"],"answer":2,"explanation":"文段先点明就业的民生意义，再从「稳存量、拓增量」两方面展开，具体包括稳岗扩岗、新业态、技能培训等对策。干扰项分别对应背景、对策之一、对策之一。故选C。","__sub":"片段阅读"},{"id":"yy-14390","module":"yanyu","diff":3,"exam":"省考","prompt":"「双减」政策落地以来，学科类校外培训明显压减，但部分培训转入「地下」，隐形变异问题仍然存在。巩固「双减」成果，要强化学校教育主阵地作用，提升课堂教学质量，同时加强隐形变异培训的监管。对这段文字概括最恰当的是：","options":["双减政策已取得明显成效","要强化学校主阵地作用","巩固双减成果需校内外协同发力","隐形变异培训问题仍存在"],"answer":2,"explanation":"文段先肯定双减成效，再指出隐形变异问题，最后落脚在「校内提质、校外监管」两方面对策。干扰项分别对应成效、问题、对策之一。故选C。","__sub":"片段阅读"},{"id":"yy-14391","module":"yanyu","diff":2,"exam":"国考","prompt":"食品安全没有「零风险」，但监管必须「零容忍」。从农田到餐桌，链条长、环节多，任何一个环节出问题都可能酿成事故。保障食品安全，要落实「四个最严」要求，压实各方责任，织密食品安全防护网。这段文字主要讲述了：","options":["食品链条长环节多","要落实四个最严要求","保障食品安全需落实最严监管","食品安全不存在零风险"],"answer":2,"explanation":"文段用「零风险」「零容忍」的对比，指出食品链条的特点，最后落脚在「四个最严、压实责任」的对策。干扰项分别对应背景、背景、对策的笼统表述。故选C。","__sub":"片段阅读"},{"id":"yy-14392","module":"yanyu","diff":2,"exam":"省考","prompt":"能源转型是应对气候变化的必然选择。但能源转型不能「一刀切」地弃煤、弃油，要先立后破，确保能源安全。推动新能源发展，要与传统能源平稳衔接，让能源转型既「快」又「稳」。这段文字意在强调：","options":["能源转型是必然选择","能源转型要先立后破确保安全","新能源要与传统能源衔接","不能一刀切地弃煤弃油"],"answer":1,"explanation":"文段先点明能源转型的必然性，再用「不能……要……」提出「先立后破」的核心要求，最后强调平稳衔接。干扰项分别对应背景、要求之一、要求之一。故选B。","__sub":"语句表达"},{"id":"yy-14393","module":"yanyu","diff":3,"exam":"事业编","prompt":"产业振兴是乡村振兴的重中之重。一些乡村产业发展存在同质化问题，你种苹果我也种苹果，最终恶性竞争。发展乡村产业，要立足本地资源禀赋，打造「一村一品」「一县一业」，走差异化发展路子。这段文字意在说明：","options":["产业振兴是乡村振兴重点","发展乡村产业要走差异化路子","要打造一村一品一县一业","乡村产业存在同质化问题"],"answer":1,"explanation":"文段先点明产业振兴的地位，再指出同质化竞争的问题，最后落脚在「立足禀赋、差异化发展」的对策。干扰项分别对应背景、问题、对策的具体表述。故选B。","__sub":"片段阅读"},{"id":"yy-14394","module":"yanyu","diff":2,"exam":"事业编","prompt":"关键核心技术是要不来、买不来、讨不来的。面对外部技术封锁，惟有自立自强。要加强基础研究，突破「卡脖子」技术，掌握发展主动权，把创新主动权牢牢掌握在自己手中。这段文字的主旨是：","options":["关键核心技术无法通过购买获得","突破关键核心技术需自立自强","要加强基础研究突破瓶颈","外部存在技术封锁"],"answer":1,"explanation":"文段开篇用「要不来、买不来、讨不来」强调核心技术的特殊性，再指出外部封锁的现实，最后落脚在「加强基础研究、突破瓶颈」的对策。干扰项分别对应背景、背景、对策之一。故选B。","__sub":"片段阅读"},{"id":"yy-14395","module":"yanyu","diff":2,"exam":"省考","prompt":"文化自信是更基础、更广泛、更深厚的自信。中华优秀传统文化蕴含着丰富的哲学思想、人文精神、道德理念。坚定文化自信，要推动中华优秀传统文化创造性转化、创新性发展，让中华文化展现永久魅力和时代风采。对这段文字概括最恰当的是：","options":["坚定文化自信需推动传统文化创新发展","文化自信是更基础的自信","传统文化蕴含丰富思想","要推动传统文化创新发展"],"answer":0,"explanation":"文段先点明文化自信的地位，再说明传统文化的内涵，最后落脚在「创造性转化、创新性发展」的对策。干扰项分别对应背景、背景、对策之一。故选A。","__sub":"片段阅读"},{"id":"yy-14396","module":"yanyu","diff":3,"exam":"省考","prompt":"共同富裕是社会主义的本质要求。共同富裕不是同步富裕，也不是均贫富，要允许一部分人先富起来，先富带后富。促进共同富裕，要构建初次分配、再分配、三次分配协调配套的制度体系。这段文字主要讲述了：","options":["共同富裕不是同步富裕","共同富裕是本质要求","要构建三次分配制度体系","促进共同富裕需完善分配制度体系"],"answer":3,"explanation":"文段先点明共同富裕的定位，再用「不是……也不是……」澄清认识误区，最后落脚在「三次分配制度体系」的对策。干扰项分别对应定位、澄清、对策之一。故选D。","__sub":"片段阅读"},{"id":"yy-14397","module":"yanyu","diff":2,"exam":"省考","prompt":"安全生产责任重于泰山。一些事故的发生，往往源于麻痹大意和侥幸心理，「海恩法则」告诉我们，每一起严重事故背后，必然有多次轻微事故和大量事故隐患。抓好安全生产，要把隐患当事故看，防微杜渐、常抓不懈。这段文字意在强调：","options":["安全生产责任重大","要把隐患当事故看","事故源于麻痹侥幸心理","安全生产要防微杜渐常抓不懈"],"answer":3,"explanation":"文段先强调安全生产的重要性，再用「海恩法则」说明隐患与事故的关系，最后落脚在「防微杜渐、常抓不懈」的要求。干扰项分别对应背景、原因分析、对策之一。故选D。","__sub":"片段阅读"},{"id":"yy-14398","module":"yanyu","diff":2,"exam":"国考","prompt":"传统村落是农耕文明的珍贵遗产，承载着大量的历史记忆和地域文化信息。然而随着城镇化进程加快，不少传统村落面临空心化、建筑破损、文化断裂等问题。保护传统村落，不能只靠情怀，更要建立长效机制，让村民在保护中受益，让村落保护与乡村发展相互促进。这段文字的主旨是：","options":["传统村落承载着历史记忆和文化信息","传统村落保护需要建立让村民受益的长效机制","传统村落面临空心化等诸多问题","城镇化进程加快冲击了传统村落"],"answer":1,"explanation":"文段先说传统村落的价值，再指出问题，最后落脚点在「要建立长效机制，让村民受益、保护与发展相互促进」，主旨为对策句。三个干扰项分别对应背景、问题、价值，均非重点。故选B。","__sub":"片段阅读"},{"id":"yy-14399","module":"yanyu","diff":3,"exam":"国考","prompt":"数字经济时代，数据成为重要的生产要素。但数据要素市场尚不成熟，存在权属不清、流通不畅、监管滞后等问题。推动数据要素市场化配置，需要完善产权制度、健全流通机制、加强安全监管，多措并举、协同发力。对这段文字概括最恰当的是：","options":["发展数据要素市场需要多方面协同推进","数据已成为重要的生产要素","数字经济时代已经全面到来","数据要素市场存在权属不清问题"],"answer":0,"explanation":"文段先肯定数据要素的地位，再列举问题，最后用「需要……多措并举、协同发力」提出对策，主旨在对策。干扰项分别对应背景、问题之一、背景。故选A。","__sub":"片段阅读"},{"id":"yy-14400","module":"yanyu","diff":2,"exam":"省考","prompt":"基层减负不能停留在「减」字上。有的地方文山会海压下去了，但「指尖上的形式主义」又冒出来，各类政务APP、工作群反而让基层干部疲于应付。根治形式主义，关键在树立正确政绩观，从源头上改革考核评价体系。这段文字主要讲述了：","options":["形式主义的表现形式不断变化","根治基层形式主义需从考核体系入手","政务APP和工作群加重了基层负担","基层减负取得了一定成效"],"answer":1,"explanation":"文段通过「文山会海压下去、指尖形式主义冒出来」的现象，引出「关键在树立正确政绩观、从源头改革考核评价体系」这一对策，主旨为对策句。干扰项均为现象描述。故选B。","__sub":"片段阅读"},{"id":"yy-14401","module":"yanyu","diff":2,"exam":"国考","prompt":"科学家精神是科技工作者在长期科学实践中积累的宝贵精神财富。爱国、创新、求实、奉献、协同、育人，这六个方面共同构成了新时代科学家精神的核心内涵。弘扬科学家精神，不仅要说，更要做，要在重大科技攻关任务中见真章。这段文字意在强调：","options":["科学家精神是宝贵的精神财富","科学家精神包含六个方面的内涵","弘扬科学家精神要在实践中落实","科技工作者要具备爱国奉献精神"],"answer":2,"explanation":"文段先阐释科学家精神的内涵，最后强调「不仅要说，更要做，要在重大科技攻关任务中见真章」，重点在实践落实。干扰项均为内涵阐释部分。故选C。","__sub":"片段阅读"},{"id":"yy-14402","module":"yanyu","diff":3,"exam":"省考","prompt":"湿地被称为「地球之肾」，具有涵养水源、净化水质、调蓄洪水、调节气候等重要生态功能。近年来一些地方围垦、污染导致湿地面积萎缩、功能退化。保护湿地要处理好发展与保护的关系，划定生态红线，实行最严格的保护制度。这段文字意在说明：","options":["湿地具有重要的生态功能","发展与环境的关系需要协调","湿地保护需要实行最严格的制度","湿地面积萎缩功能退化"],"answer":2,"explanation":"文段先说明湿地功能，再指出问题，最后落脚在「划定生态红线，实行最严格的保护制度」这一对策。干扰项对应背景与问题。故选C。","__sub":"片段阅读"},{"id":"yy-14403","module":"yanyu","diff":2,"exam":"省考","prompt":"老旧小区改造是城市更新的重要内容。改造不能政府「唱独角戏」，要充分听取居民意见，引导居民出资参与，让改造方案更贴合实际需求。同时要建立后续长效管理机制，避免「改完就乱、前改后坏」。这段文字的主旨是：","options":["老旧小区改造是城市更新的内容","老旧小区改造需居民参与并长效管理","改造方案要贴合居民实际需求","政府不应独自承担改造责任"],"answer":1,"explanation":"文段先定位老旧小区改造的意义，再从「居民参与」和「长效管理」两方面提出要求，主旨为两方面对策的概括。A项只是背景，B项只覆盖一个方面，C项表述绝对且偏离重点。故选B。","__sub":"片段阅读"},{"id":"yy-14404","module":"yanyu","diff":2,"exam":"省考","prompt":"技能人才是支撑中国制造、中国创造的重要力量。当前技能人才总量不足、结构不优的问题仍然突出，高级技工求人倍率长期保持在2以上。发展职业教育，要破除重学历轻技能的观念，畅通技能人才成长通道，让技能人才有地位、有奔头。对这段文字概括最恰当的是：","options":["技能人才总量不足结构不优","要破除重学历轻技能的观念","技能人才是重要力量","发展职业教育要畅通技能人才成长通道"],"answer":3,"explanation":"文段先肯定技能人才的重要性，再指出问题，最后落脚在「破除观念、畅通通道、让技能人才有地位」这一对策。干扰项分别对应背景、问题、对策之一。故选D。","__sub":"片段阅读"},{"id":"yy-14405","module":"yanyu","diff":3,"exam":"省考","prompt":"我国老年人口规模庞大，银发经济蕴含巨大发展空间。但当前养老服务供给还存在总量不足、结构失衡、质量不高等问题。发展银发经济，既要发挥政府保基本、兜底线的作用，更要激发市场活力，引导社会力量广泛参与。这段文字主要讲述了：","options":["银发经济蕴含巨大发展空间","养老服务供给存在诸多问题","发展银发经济需政府市场协同发力","政府要保基本兜底线"],"answer":2,"explanation":"文段先指出银发经济的空间，再列举问题，最后用「既要……更要……」提出政府与市场两方面的要求，主旨为协同发力。干扰项分别对应背景、问题、对策之一。故选C。","__sub":"片段阅读"},{"id":"yy-14406","module":"yanyu","diff":2,"exam":"省考","prompt":"种子是农业的「芯片」，种业安全关乎粮食安全。当前我国种业自主创新能力与世界先进水平仍有差距，部分领域种子对外依存度高。推进种业振兴，要加强种质资源保护利用，强化企业创新主体地位，推动产学研深度融合。这段文字意在强调：","options":["我国种业自主创新能力有差距","要加强种质资源保护利用","推进种业振兴需强化自主创新","种业安全关乎粮食安全"],"answer":2,"explanation":"文段以「芯片」比喻强调种业重要性，指出创新能力不足的问题，最后落脚在「加强保护利用、强化企业创新、产学研融合」等对策，核心指向自主创新。干扰项分别对应背景、问题、对策之一。故选C。","__sub":"片段阅读"},{"id":"yy-14407","module":"yanyu","diff":2,"exam":"省考","prompt":"夜间经济是城市消费的新蓝海。发展夜经济不是简单地延长营业时间，而要在业态创新、场景营造、配套服务上下功夫，让消费者愿意来、留得住、玩得好。同时要平衡好繁荣与扰民的关系，让夜经济既有烟火气又有文明范。这段文字意在说明：","options":["发展夜经济要注重业态创新与规范引导","夜经济不只是延长营业时间","要平衡繁荣与扰民的关系","夜间经济是城市消费新蓝海"],"answer":0,"explanation":"文段先定位夜经济的意义，再从「业态创新、场景营造、配套服务」和「平衡关系」两方面提出要求，主旨为综合对策。干扰项分别对应背景、对策之一、对策之一。故选A。","__sub":"片段阅读"},{"id":"yy-14408","module":"yanyu","diff":3,"exam":"省考","prompt":"人工智能技术在带来便利的同时，也引发了算法歧视、隐私泄露、深度伪造等风险。治理人工智能，不能等到问题积累后再「亡羊补牢」，要坚持发展与规范并重，在鼓励创新的同时划清伦理和法律底线。这段文字的主旨是：","options":["人工智能带来了诸多风险","要鼓励人工智能创新发展","算法歧视等问题亟待解决","人工智能治理应坚持发展与规范并重"],"answer":3,"explanation":"文段先指出AI的风险，再用「不能……要……」提出「发展与规范并重」的核心观点。干扰项分别对应问题、对策之一、问题。故选D。","__sub":"片段阅读"},{"id":"yy-14409","module":"yanyu","diff":2,"exam":"省考","prompt":"乡村振兴，关键在人。当前不少农村面临「谁来种地」「谁来兴村」的难题，青壮年劳动力外流，懂农业、爱农村、爱农民的人才严重不足。破解人才瓶颈，既要筑巢引凤吸引外来人才，更要就地培养新型职业农民，让本土人才留得住、干得好。对这段文字概括最恰当的是：","options":["要吸引外来人才下乡","破解乡村振兴人才瓶颈需引育并举","农村面临人才外流难题","乡村振兴关键在人才"],"answer":1,"explanation":"文段先点明人才对乡村振兴的重要性，再指出人才短缺问题，最后用「既要……更要……」提出引进与培养两条路径，主旨为引育并举。干扰项分别对应背景、问题、对策之一。故选B。","__sub":"片段阅读"},{"id":"yy-14410","module":"yanyu","diff":2,"exam":"省考","prompt":"数字技术为文化遗产保护传承开辟了新路径。通过三维扫描、数字建模，敦煌壁画得以永久保存；借助VR技术，观众足不出户就能「走进」故宫。但数字化不是简单的拍照存档，更要深挖文化内涵，让文物真正「活」起来。这段文字主要讲述了：","options":["VR技术让观众云游故宫","敦煌壁画已实现数字化保存","数字技术助力文化遗产保护","文化遗产数字化要让文物真正活起来"],"answer":3,"explanation":"文段先举例说明数字化技术的作用，再用「但」转折，指出数字化不能停留在表面，要深挖内涵让文物「活」起来。干扰项均为例证部分，非重点。故选D。","__sub":"片段阅读"},{"id":"yy-14411","module":"yanyu","diff":3,"exam":"国考","prompt":"数字技术为基层治理插上翅膀，但一些地方的「数字治理」变了味：APP打卡代替实地走访，数据报表代替解决实际问题，基层干部成了「表哥表姐」。数字治理的落脚点应是治理效能提升，而不是数字形式主义。这段文字意在强调：","options":["数字治理要防止陷入形式主义","治理效能是数字治理的落脚点","基层干部被各类报表困扰","数字技术提升了基层治理效率"],"answer":0,"explanation":"文段先肯定数字技术的作用，再通过「变了味」的现象列举数字形式主义的表现，最后点明落脚点在治理效能。干扰项分别对应背景、现象、对策表述。故选A。","__sub":"片段阅读"},{"id":"yy-14412","module":"yanyu","diff":2,"exam":"事业编","prompt":"一些毕业生宁愿「慢就业」「缓就业」，也不愿到基层和中小企业去。事实上，基层是青年成长成才的广阔舞台，中小企业是吸纳就业的主渠道。转变就业观念，把个人理想融入国家发展，青年才能在广阔天地中大有作为。这段文字意在说明：","options":["基层和中小企业需要人才","就业形势日益严峻","毕业生就业观念存在偏差","青年应转变观念到基层建功立业"],"answer":3,"explanation":"文段先指出部分毕业生就业观的问题，再说明基层和中小企业的价值，最后提出「转变观念、融入国家发展」的对策。干扰项分别对应现象、背景、背景。故选D。","__sub":"片段阅读"},{"id":"yy-14413","module":"yanyu","diff":2,"exam":"国考","prompt":"绿色金融是推动绿色发展的重要支撑。当前绿色信贷、绿色债券等金融产品快速发展，但存在标准不统一、「洗绿」「漂绿」等问题。完善绿色金融体系，要统一绿色认定标准，强化环境信息披露，让金融活水真正流向绿色领域。这段文字的主旨是：","options":["绿色金融支撑绿色发展","完善绿色金融体系需统一标准强化披露","金融活水应流向绿色领域","绿色金融产品快速发展"],"answer":1,"explanation":"文段先肯定绿色金融的定位，再指出标准不统一、「洗绿」等问题，最后落脚在「统一标准、强化披露」的对策。干扰项分别对应背景、背景、对策的比喻表述。故选B。","__sub":"片段阅读"},{"id":"yy-14414","module":"yanyu","diff":3,"exam":"省考","prompt":"全民健身是实现全民健康的重要途径。近年来各地体育设施不断完善，但「健身去哪儿」仍是群众反映强烈的问题，特别是群众身边的场地设施仍然不足。解决这一问题，要在盘活存量、扩大增量上下功夫，让体育资源真正惠及群众。对这段文字概括最恰当的是：","options":["健身场地不足是突出问题","体育设施不断完善","全民健身关乎全民健康","解决健身场地问题需盘活存量扩大增量"],"answer":3,"explanation":"文段先点明全民健身的意义，再指出「健身去哪儿」的问题，最后落脚在「盘活存量、扩大增量」的对策。干扰项分别对应背景、背景、问题。故选D。","__sub":"片段阅读"},{"id":"yy-14415","module":"yanyu","diff":2,"exam":"国考","prompt":"科技是双刃剑，伦理是方向盘。基因编辑、脑机接口等前沿技术一旦越轨，后果不堪设想。加强科技伦理治理，不是限制创新，而是为创新划定跑道，让科技始终朝着造福人类的方向发展。这段文字主要讲述了：","options":["科技伦理治理限制创新","科技伦理治理为创新划定跑道","前沿技术存在巨大风险","科技应造福人类"],"answer":1,"explanation":"文段用「双刃剑」「方向盘」的比喻，指出伦理治理的必要性，最后用「不是……而是……」澄清「伦理治理不是限制创新，而是划定跑道」。B项与原文表述相反，A、D项为部分表述。故选B。","__sub":"片段阅读"},{"id":"yy-14416","module":"yanyu","diff":2,"exam":"国考","prompt":"城市人口密集、要素集聚，也意味着风险集聚。极端天气、公共卫生事件等突发情况，考验着城市的应对能力。建设韧性城市，要把防灾减灾纳入城市规划建设全过程，提升基础设施抗风险能力，让城市更安全、更宜居。这段文字意在强调：","options":["城市风险集聚需要应对","建设韧性城市需将防灾纳入规划全程","城市应更安全更宜居","极端天气考验城市能力"],"answer":1,"explanation":"文段先指出城市风险集聚的特点，再说明突发事件的考验，最后落脚在「把防灾减灾纳入规划建设全过程」的对策。干扰项分别对应背景、背景、目标表述。故选B。","__sub":"片段阅读"},{"id":"yy-14417","module":"yanyu","diff":3,"exam":"国考","prompt":"平台经济是经济发展的新引擎，但垄断和不正当竞争问题也随之而来。规范平台经济发展，不是要「一棍子打死」，而是要设置「红绿灯」，在鼓励创新与防范风险之间找到平衡，促进平台经济规范健康发展。这段文字意在说明：","options":["平台垄断问题不容忽视","规范平台经济要在创新与风险间求平衡","平台经济是发展新引擎","要促进平台经济健康发展"],"answer":1,"explanation":"文段先肯定平台经济的作用，再指出垄断问题，最后用「不是……而是……」提出「设置红绿灯、找到平衡」的核心观点。干扰项分别对应背景、问题、对策的笼统表述。故选B。","__sub":"片段阅读"},{"id":"yy-14418","module":"yanyu","diff":2,"exam":"事业编","prompt":"粮食安全是「国之大者」，节约粮食同样是保障粮食安全的重要一环。从田间到餐桌，粮食损耗和浪费现象仍然存在。制止餐饮浪费，既要加强立法监管，也要倡导节约风尚，让「光盘行动」成为社会共识。这段文字的主旨是：","options":["制止粮食浪费需监管与风尚并举","粮食损耗浪费现象存在","要倡导节约粮食的风尚","粮食安全是国之大者"],"answer":0,"explanation":"文段先定位节约粮食的意义，再指出损耗浪费问题，最后用「既要……也要……」提出立法监管与风尚倡导两方面对策。干扰项分别对应背景、问题、对策之一。故选A。","__sub":"片段阅读"},{"id":"yy-14419","module":"yanyu","diff":2,"exam":"国考","prompt":"海洋是高质量发展的战略要地。我国海洋经济总量稳步增长，但产业结构偏重传统、新兴产业占比不高的问题仍然存在。壮大海洋经济，要推动传统海洋产业转型升级，培育海洋生物医药、海洋新能源等新兴业态。对这段文字概括最恰当的是：","options":["要培育海洋新兴产业","海洋经济总量稳步增长","海洋是发展战略要地","壮大海洋经济需推动产业转型升级"],"answer":3,"explanation":"文段先定位海洋的战略地位，再指出产业结构问题，最后落脚在「转型升级、培育新兴业态」的对策。干扰项分别对应背景、背景、对策之一。故选D。","__sub":"片段阅读"},{"id":"yy-14420","module":"yanyu","diff":3,"exam":"国考","prompt":"家庭是人生的第一所学校，家长是孩子的第一任老师。一些家长要么过度溺爱，要么简单粗暴，家庭教育方法失当的问题不容忽视。家庭教育促进法的实施，标志着家庭教育从「家事」上升为「国事」，家长要依法带娃、科学育儿。这段文字主要讲述了：","options":["家庭教育方法存在失当","家庭是孩子的第一所学校","家庭教育需要依法科学育儿","家庭教育促进法已实施"],"answer":2,"explanation":"文段先强调家庭教育的地位，再指出方法失当问题，最后落脚在「依法带娃、科学育儿」的对策。干扰项分别对应背景、问题、背景。故选C。","__sub":"片段阅读"},{"id":"yy-14421","module":"yanyu","diff":2,"exam":"国考","prompt":"城市更新不是大拆大建，而是「绣花功夫」。老街区改造要保留历史文脉和城市记忆，避免千城一面；社区微更新要聚焦「一老一小」需求，完善便民服务设施。让城市留住记忆、让人们记住乡愁，城市更新才有温度。这段文字意在强调：","options":["城市更新不是大拆大建","城市更新要下绣花功夫保留特色","老街区改造要保留文脉","社区要完善便民设施"],"answer":1,"explanation":"文段开篇用「绣花功夫」点明城市更新的理念，再从老街区和社区两个层面具体阐述，核心是精细化、有温度的更新。干扰项均为分论点表述。故选B。","__sub":"片段阅读"},{"id":"yy-14422","module":"yanyu","diff":2,"exam":"事业编","prompt":"数字乡村是乡村振兴的重要抓手。电商进村、智慧农业等数字化应用，让农产品出村进城更便捷，让农业生产更精准。但数字乡村建设不能搞「一刀切」，要因地制宜、分类推进，避免重复建设和资源浪费。这段文字意在说明：","options":["数字乡村建设要因地制宜分类推进","电商让农产品流通更便捷","数字乡村是乡村振兴抓手","数字应用提升农业精准度"],"answer":0,"explanation":"文段先定位数字乡村的意义，再举例说明数字化应用的价值，最后用「但」转折，强调「因地制宜、分类推进」的核心要求。干扰项均为正面例证。故选A。","__sub":"片段阅读"},{"id":"yy-14423","module":"yanyu","diff":3,"exam":"国考","prompt":"产教融合是职业教育的生命线。一些职业院校课程设置与企业需求脱节，学生「学非所用、用非所学」的问题突出。深化产教融合，要推动校企共建实训基地、共编教材、共育人才，让人才培养紧跟产业需求。这段文字的主旨是：","options":["深化产教融合需校企协同育人","课程设置与企业需求脱节","产教融合是职业教育生命线","要共建实训基地共育人才"],"answer":0,"explanation":"文段先点明产教融合的定位，再指出脱节问题，最后落脚在「共建、共编、共育」的校企协同对策。干扰项分别对应背景、问题、对策之一。故选A。","__sub":"片段阅读"},{"id":"yy-14424","module":"yanyu","diff":2,"exam":"事业编","prompt":"绿水青山就是金山银山，关键要打通「两山」转化通道。生态产品价值实现机制还不健全，「度量难、抵押难、交易难、变现难」问题突出。要建立生态产品价值核算体系，健全生态补偿机制，让保护者受益、让利用者付费。对这段文字概括最恰当的是：","options":["绿水青山就是金山银山","生态产品价值实现机制不健全","健全生态产品价值实现机制势在必行","要让保护者受益利用者付费"],"answer":2,"explanation":"文段先点明「两山」转化的关键，再指出「四难」问题，最后落脚在「建立核算体系、健全补偿机制」的对策。干扰项分别对应理念、问题、对策之一。故选C。","__sub":"片段阅读"},{"id":"yy-14425","module":"yanyu","diff":2,"exam":"医疗编","prompt":"制造业是立国之本、强国之基。当前一些地方「脱实向虚」倾向值得警惕，制造业占比过早过快下降。坚持制造业当家，要保持制造业合理比重，推动传统产业改造升级，培育壮大战略性新兴产业。这段文字主要讲述了：","options":["坚持制造业当家要保持合理比重","制造业是立国之本强国之基","制造业占比下降值得警惕","要培育战略性新兴产业"],"answer":0,"explanation":"文段先强调制造业的地位，再指出「脱实向虚」的问题，最后落脚在「保持比重、改造升级、培育新兴」的对策。干扰项分别对应背景、问题、对策之一。故选A。","__sub":"片段阅读"},{"id":"yy-14426","module":"yanyu","diff":2,"exam":"国考","prompt":"将下列句子组成语意连贯的一段话，排序最恰当的是：\n\n①但与此同时，个人信息泄露事件时有发生\n②随着数字经济的快速发展，个人信息保护问题日益凸显\n③因此，完善个人信息保护法律体系势在必行\n④一些APP过度收集、违规使用用户信息","options":["①②④③","②④①③","②①④③","④②①③"],"answer":2,"explanation":"②先总说背景，①「但与此同时」承接转折引出泄露事件，④具体列举表现，③「因此」总结对策。正确顺序为②①④③。故选C。","__sub":"语句表达"},{"id":"yy-14427","module":"yanyu","diff":2,"exam":"省考","prompt":"将下列句子组成语意连贯的一段话，排序最恰当的是：\n\n①传统工艺面临传承断层的困境\n②许多传统技艺后继乏人\n③为此，各地纷纷探索「非遗+研学」等新模式\n④年轻人对传统技艺缺乏了解和兴趣","options":["①④②③","①②④③","②①④③","④①②③"],"answer":1,"explanation":"①提出困境总起，②具体说后继乏人，④进一步解释原因，③「为此」提出对策。正确顺序为①②④③。故选B。","__sub":"语句表达"},{"id":"yy-14428","module":"yanyu","diff":2,"exam":"医疗编","prompt":"将下列句子组成语意连贯的一段话，排序最恰当的是：\n\n①然而，过度依赖算法推荐可能导致「信息茧房」\n②算法推荐技术极大提高了信息分发效率\n③用户接触的信息越来越同质化\n④平台应根据用户兴趣提供多元内容","options":["②①④③","②①③④","②③①④","①②③④"],"answer":1,"explanation":"②总说算法推荐的积极作用，①「然而」转折指出问题，③具体说明「信息茧房」的表现，④提出对策。正确顺序为②①③④。故选B。","__sub":"语句表达"},{"id":"yy-14429","module":"yanyu","diff":2,"exam":"国考","prompt":"将下列句子组成语意连贯的一段话，排序最恰当的是：\n\n①垃圾分类看似小事，实则关乎生态文明建设大局\n②居民分类习惯的养成需要长期引导\n③各地应完善激励约束机制，让分类成为自觉\n④一些地方推行初期效果不佳，正是缺乏长效机制","options":["②①④③","①②④③","①②③④","①④②③"],"answer":1,"explanation":"①总起点明意义，②指出习惯养成需要引导，④以反面现象佐证，③「应」提出对策。正确顺序为①②④③。故选B。","__sub":"语句表达"},{"id":"yy-14430","module":"yanyu","diff":2,"exam":"国考","prompt":"将下列句子组成语意连贯的一段话，排序最恰当的是：\n\n①数字技术深刻改变了人们的生产生活方式\n②但数字鸿沟问题也日益凸显\n③老年人不会使用智能手机就医、出行受阻的新闻屡见不鲜\n④社会应帮助老年人跨越数字鸿沟","options":["①③②④","①②③④","①②④③","②①③④"],"answer":1,"explanation":"①总说数字技术的改变，②「但」转折引出数字鸿沟，③举例说明表现，④提出对策。正确顺序为①②③④。故选B。","__sub":"语句表达"},{"id":"yy-14431","module":"yanyu","diff":2,"exam":"国考","prompt":"将下列句子组成语意连贯的一段话，排序最恰当的是：\n\n①基层是社会治理的「最后一公里」\n②网格员、志愿者等基层力量发挥了重要作用\n③提升基层治理水平，要充实基层力量、赋能基层治理\n④一些地方基层人少事多、权责不匹配的问题突出","options":["①②④③","①④③②","①④②③","④①②③"],"answer":2,"explanation":"①总说基层的定位，④指出基层的问题，②说明基层力量的作用，③提出对策。正确顺序为①④②③。故选C。","__sub":"语句表达"},{"id":"yy-14432","module":"yanyu","diff":2,"exam":"省考","prompt":"下列句子中没有语病的是：\n\nA\n.\n这\n次\n培\n训\n，\n使\n大\n家\n的\n业\n务\n水\n平\n有\n了\n很\n大\n提\n高\n。\n\n\nB\n.\n这\n次\n培\n训\n使\n大\n家\n提\n高\n了\n业\n务\n水\n平\n。\n\n\nC\n.\n通\n过\n这\n次\n培\n训\n，\n大\n家\n的\n业\n务\n水\n平\n得\n到\n了\n提\n高\n。\n\n\nD\n.\n通\n过\n这\n次\n培\n训\n，\n使\n大\n家\n提\n高\n了\n业\n务\n水\n平\n。","options":["这次培训，使大家的业务水平有了很大提高。","这次培训使大家提高了业务水平。","通过这次培训，大家的业务水平得到了提高。","通过这次培训，使大家提高了业务水平。"],"answer":1,"explanation":"A项「通过……使……」导致主语残缺；B项结构完整、表达清晰；C项「通过……」与「得到了提高」搭配尚可但「得到」较空泛；D项「使」字句主语残缺。故选B。","__sub":"语句表达"},{"id":"yy-14433","module":"yanyu","diff":2,"exam":"国考","prompt":"下列句子中没有语病的是：\n\nA\n.\n为\n了\n防\n止\n此\n类\n事\n故\n发\n生\n，\n学\n校\n加\n强\n了\n安\n全\n管\n理\n。\n\n\nB\n.\n为\n了\n防\n止\n此\n类\n事\n故\n不\n再\n发\n生\n，\n学\n校\n加\n强\n了\n安\n全\n管\n理\n。\n\n\nC\n.\n为\n了\n防\n止\n此\n类\n事\n故\n不\n发\n生\n，\n学\n校\n加\n强\n了\n安\n全\n管\n理\n。\n\n\nD\n.\n为\n了\n防\n止\n此\n类\n事\n故\n再\n次\n发\n生\n，\n学\n校\n加\n强\n了\n安\n全\n管\n理\n。","options":["为了防止此类事故发生，学校加强了安全管理。","为了防止此类事故不再发生，学校加强了安全管理。","为了防止此类事故不发生，学校加强了安全管理。","为了防止此类事故再次发生，学校加强了安全管理。"],"answer":3,"explanation":"A项「防止不再发生」双重否定表意相反；C项「防止不发生」同样表意相反；D项「防止发生」与「加强管理」的目的表述尚可但「防止事故发生」过于绝对；B项「防止再次发生」表意准确。故选D。","__sub":"语句表达"},{"id":"yy-14440","module":"yanyu","diff":2,"exam":"事业编","prompt":"下列句子中没有语病的是：\n\nA\n.\n通\n过\n这\n次\n培\n训\n，\n大\n家\n的\n业\n务\n水\n平\n得\n到\n了\n提\n高\n。\n\n\nB\n.\n这\n次\n培\n训\n使\n大\n家\n提\n高\n了\n业\n务\n水\n平\n。\n\n\nC\n.\n这\n次\n培\n训\n，\n使\n大\n家\n的\n业\n务\n水\n平\n有\n了\n很\n大\n提\n高\n。\n\n\nD\n.\n通\n过\n这\n次\n培\n训\n，\n使\n大\n家\n提\n高\n了\n业\n务\n水\n平\n。","options":["通过这次培训，大家的业务水平得到了提高。","这次培训使大家提高了业务水平。","这次培训，使大家的业务水平有了很大提高。","通过这次培训，使大家提高了业务水平。"],"answer":1,"explanation":"A项「通过……使……」导致主语残缺；B项结构完整、表达清晰；C项「通过……」与「得到了提高」搭配尚可但「得到」较空泛；D项「使」字句主语残缺。故选B。","__sub":"语句表达"},{"id":"yy-14441","module":"yanyu","diff":2,"exam":"教师编","prompt":"下列句子中没有语病的是：\n\nA\n.\n为\n了\n防\n止\n此\n类\n事\n故\n再\n次\n发\n生\n，\n学\n校\n加\n强\n了\n安\n全\n管\n理\n。\n\n\nB\n.\n为\n了\n防\n止\n此\n类\n事\n故\n不\n发\n生\n，\n学\n校\n加\n强\n了\n安\n全\n管\n理\n。\n\n\nC\n.\n为\n了\n防\n止\n此\n类\n事\n故\n发\n生\n，\n学\n校\n加\n强\n了\n安\n全\n管\n理\n。\n\n\nD\n.\n为\n了\n防\n止\n此\n类\n事\n故\n不\n再\n发\n生\n，\n学\n校\n加\n强\n了\n安\n全\n管\n理\n。","options":["为了防止此类事故再次发生，学校加强了安全管理。","为了防止此类事故不发生，学校加强了安全管理。","为了防止此类事故发生，学校加强了安全管理。","为了防止此类事故不再发生，学校加强了安全管理。"],"answer":0,"explanation":"A项「防止不再发生」双重否定表意相反；C项「防止不发生」同样表意相反；D项「防止发生」与「加强管理」的目的表述尚可但「防止事故发生」过于绝对；B项「防止再次发生」表意准确。故选A。","__sub":"语句表达"},{"id":"yy-14449","module":"yanyu","diff":2,"exam":"省考","prompt":"下列句子中没有语病的是：\n\nA\n.\n为\n了\n防\n止\n此\n类\n事\n故\n不\n再\n发\n生\n，\n学\n校\n加\n强\n了\n安\n全\n管\n理\n。\n\n\nB\n.\n为\n了\n防\n止\n此\n类\n事\n故\n不\n发\n生\n，\n学\n校\n加\n强\n了\n安\n全\n管\n理\n。\n\n\nC\n.\n为\n了\n防\n止\n此\n类\n事\n故\n发\n生\n，\n学\n校\n加\n强\n了\n安\n全\n管\n理\n。\n\n\nD\n.\n为\n了\n防\n止\n此\n类\n事\n故\n再\n次\n发\n生\n，\n学\n校\n加\n强\n了\n安\n全\n管\n理\n。","options":["为了防止此类事故不再发生，学校加强了安全管理。","为了防止此类事故不发生，学校加强了安全管理。","为了防止此类事故发生，学校加强了安全管理。","为了防止此类事故再次发生，学校加强了安全管理。"],"answer":3,"explanation":"A项「防止不再发生」双重否定表意相反；C项「防止不发生」同样表意相反；D项「防止发生」与「加强管理」的目的表述尚可但「防止事故发生」过于绝对；B项「防止再次发生」表意准确。故选D。","__sub":"语句表达"},{"id":"yy-14457","module":"yanyu","diff":2,"exam":"国考","prompt":"下列句子中没有语病的是：\n\nA\n.\n为\n了\n防\n止\n此\n类\n事\n故\n不\n再\n发\n生\n，\n学\n校\n加\n强\n了\n安\n全\n管\n理\n。\n\n\nB\n.\n为\n了\n防\n止\n此\n类\n事\n故\n不\n发\n生\n，\n学\n校\n加\n强\n了\n安\n全\n管\n理\n。\n\n\nC\n.\n为\n了\n防\n止\n此\n类\n事\n故\n再\n次\n发\n生\n，\n学\n校\n加\n强\n了\n安\n全\n管\n理\n。\n\n\nD\n.\n为\n了\n防\n止\n此\n类\n事\n故\n发\n生\n，\n学\n校\n加\n强\n了\n安\n全\n管\n理\n。","options":["为了防止此类事故不再发生，学校加强了安全管理。","为了防止此类事故不发生，学校加强了安全管理。","为了防止此类事故再次发生，学校加强了安全管理。","为了防止此类事故发生，学校加强了安全管理。"],"answer":2,"explanation":"A项「防止不再发生」双重否定表意相反；C项「防止不发生」同样表意相反；D项「防止发生」与「加强管理」的目的表述尚可但「防止事故发生」过于绝对；B项「防止再次发生」表意准确。故选C。","__sub":"语句表达"},{"id":"yy-14464","module":"yanyu","diff":2,"exam":"国考","prompt":"下列句子中没有语病的是：\n\nA\n.\n这\n次\n培\n训\n使\n大\n家\n提\n高\n了\n业\n务\n水\n平\n。\n\n\nB\n.\n通\n过\n这\n次\n培\n训\n，\n使\n大\n家\n提\n高\n了\n业\n务\n水\n平\n。\n\n\nC\n.\n这\n次\n培\n训\n，\n使\n大\n家\n的\n业\n务\n水\n平\n有\n了\n很\n大\n提\n高\n。\n\n\nD\n.\n通\n过\n这\n次\n培\n训\n，\n大\n家\n的\n业\n务\n水\n平\n得\n到\n了\n提\n高\n。","options":["这次培训使大家提高了业务水平。","通过这次培训，使大家提高了业务水平。","这次培训，使大家的业务水平有了很大提高。","通过这次培训，大家的业务水平得到了提高。"],"answer":0,"explanation":"A项「通过……使……」导致主语残缺；B项结构完整、表达清晰；C项「通过……」与「得到了提高」搭配尚可但「得到」较空泛；D项「使」字句主语残缺。故选A。","__sub":"语句表达"},{"id":"yy-14465","module":"yanyu","diff":2,"exam":"事业编","prompt":"下列句子中没有语病的是：\n\nA\n.\n为\n了\n防\n止\n此\n类\n事\n故\n不\n发\n生\n，\n学\n校\n加\n强\n了\n安\n全\n管\n理\n。\n\n\nB\n.\n为\n了\n防\n止\n此\n类\n事\n故\n再\n次\n发\n生\n，\n学\n校\n加\n强\n了\n安\n全\n管\n理\n。\n\n\nC\n.\n为\n了\n防\n止\n此\n类\n事\n故\n发\n生\n，\n学\n校\n加\n强\n了\n安\n全\n管\n理\n。\n\n\nD\n.\n为\n了\n防\n止\n此\n类\n事\n故\n不\n再\n发\n生\n，\n学\n校\n加\n强\n了\n安\n全\n管\n理\n。","options":["为了防止此类事故不发生，学校加强了安全管理。","为了防止此类事故再次发生，学校加强了安全管理。","为了防止此类事故发生，学校加强了安全管理。","为了防止此类事故不再发生，学校加强了安全管理。"],"answer":1,"explanation":"A项「防止不再发生」双重否定表意相反；C项「防止不发生」同样表意相反；D项「防止发生」与「加强管理」的目的表述尚可但「防止事故发生」过于绝对；B项「防止再次发生」表意准确。故选B。","__sub":"语句表达"},{"id":"yy-14480","module":"yanyu","diff":2,"exam":"国考","prompt":"下列句子中没有语病的是：\n\nA\n.\n通\n过\n这\n次\n培\n训\n，\n大\n家\n的\n业\n务\n水\n平\n得\n到\n了\n提\n高\n。\n\n\nB\n.\n通\n过\n这\n次\n培\n训\n，\n使\n大\n家\n提\n高\n了\n业\n务\n水\n平\n。\n\n\nC\n.\n这\n次\n培\n训\n使\n大\n家\n提\n高\n了\n业\n务\n水\n平\n。\n\n\nD\n.\n这\n次\n培\n训\n，\n使\n大\n家\n的\n业\n务\n水\n平\n有\n了\n很\n大\n提\n高\n。","options":["通过这次培训，大家的业务水平得到了提高。","通过这次培训，使大家提高了业务水平。","这次培训使大家提高了业务水平。","这次培训，使大家的业务水平有了很大提高。"],"answer":2,"explanation":"A项「通过……使……」导致主语残缺；B项结构完整、表达清晰；C项「通过……」与「得到了提高」搭配尚可但「得到」较空泛；D项「使」字句主语残缺。故选C。","__sub":"语句表达"},{"id":"yy-14481","module":"yanyu","diff":2,"exam":"省考","prompt":"下列句子中没有语病的是：\n\nA\n.\n为\n了\n防\n止\n此\n类\n事\n故\n发\n生\n，\n学\n校\n加\n强\n了\n安\n全\n管\n理\n。\n\n\nB\n.\n为\n了\n防\n止\n此\n类\n事\n故\n不\n发\n生\n，\n学\n校\n加\n强\n了\n安\n全\n管\n理\n。\n\n\nC\n.\n为\n了\n防\n止\n此\n类\n事\n故\n再\n次\n发\n生\n，\n学\n校\n加\n强\n了\n安\n全\n管\n理\n。\n\n\nD\n.\n为\n了\n防\n止\n此\n类\n事\n故\n不\n再\n发\n生\n，\n学\n校\n加\n强\n了\n安\n全\n管\n理\n。","options":["为了防止此类事故发生，学校加强了安全管理。","为了防止此类事故不发生，学校加强了安全管理。","为了防止此类事故再次发生，学校加强了安全管理。","为了防止此类事故不再发生，学校加强了安全管理。"],"answer":2,"explanation":"A项「防止不再发生」双重否定表意相反；C项「防止不发生」同样表意相反；D项「防止发生」与「加强管理」的目的表述尚可但「防止事故发生」过于绝对；B项「防止再次发生」表意准确。故选C。","__sub":"语句表达"},{"id":"yy-14488","module":"yanyu","diff":2,"exam":"医疗编","prompt":"下列句子中没有语病的是：\n\nA\n.\n通\n过\n这\n次\n培\n训\n，\n使\n大\n家\n提\n高\n了\n业\n务\n水\n平\n。\n\n\nB\n.\n这\n次\n培\n训\n使\n大\n家\n提\n高\n了\n业\n务\n水\n平\n。\n\n\nC\n.\n这\n次\n培\n训\n，\n使\n大\n家\n的\n业\n务\n水\n平\n有\n了\n很\n大\n提\n高\n。\n\n\nD\n.\n通\n过\n这\n次\n培\n训\n，\n大\n家\n的\n业\n务\n水\n平\n得\n到\n了\n提\n高\n。","options":["通过这次培训，使大家提高了业务水平。","这次培训使大家提高了业务水平。","这次培训，使大家的业务水平有了很大提高。","通过这次培训，大家的业务水平得到了提高。"],"answer":1,"explanation":"A项「通过……使……」导致主语残缺；B项结构完整、表达清晰；C项「通过……」与「得到了提高」搭配尚可但「得到」较空泛；D项「使」字句主语残缺。故选B。","__sub":"语句表达"},{"id":"yy-14501","module":"yanyu","diff":1,"exam":"省考","prompt":"现实中，方法与态度不同，结果往往截然不同。面对新形势新任务，必须______生产生活生态，牢牢把握发展主动权。看似寻常，实则是长期积累的结果。填入画横线处最恰当的是：","options":["统筹","协调","统率","兼顾"],"answer":0,"explanation":"「统筹」指全面筹划、统一安排，与「推进」搭配且强调全局性；「统率」指率领；「兼顾」只强调同时照顾；「协调」侧重配合关系。故选A。","__sub":"选词填空"},{"id":"yy-14502","module":"yanyu","diff":1,"exam":"事业编","prompt":"干事创业，思路和坚持缺一不可。当前正值关键时期，______城市功能品质刻不容缓，必须抓紧抓实抓出成效。其中的道理值得每个人细细体会。填入画横线处最恰当的是：","options":["增强","拔高","提升","提高"],"answer":2,"explanation":"「提升」与「效能、水平」搭配规范；「提高」语义相近但「提升」更书面；「增强」多与「能力、意识」搭配；「拔高」含贬义。故选C。","__sub":"选词填空"},{"id":"yy-14503","module":"yanyu","diff":1,"exam":"事业编","prompt":"干事创业，思路和坚持缺一不可。各地区各部门要拿出真招实招，______就业促进机制，确保各项部署落地生根。其中的道理值得每个人细细体会。填入画横线处最恰当的是：","options":["完善","构建","搭建","健全"],"answer":3,"explanation":"「健全」强调使完备无缺；「完善」指补足短板；「构建」「搭建」侧重从无到有搭建。故选D。","__sub":"选词填空"},{"id":"yy-14504","module":"yanyu","diff":2,"exam":"事业编","prompt":"观察身边的事不难发现，成败的分野常常藏在细节里。当前正值关键时期，______乡村振兴刻不容缓，必须抓紧抓实抓出成效。说到底，拼的是态度，比的是功夫。填入画横线处最恰当的是：","options":["赋权","助力","赋能","加持"],"answer":2,"explanation":"「赋能」指赋予能力，是数字经济语境的规范表述；「赋权」指赋予权力；「加持」为口语化外来词；「助力」语义宽泛。故选C。","__sub":"选词填空"},{"id":"yy-14505","module":"yanyu","diff":2,"exam":"省考","prompt":"干事创业，思路和坚持缺一不可。只有群众获得感真正______到基层，才能让政策在「最后一公里」落地见效。其中的道理值得每个人细细体会。填入画横线处最恰当的是：","options":["提高","提升","增强","拔高"],"answer":1,"explanation":"「提升」与「效能、水平」搭配规范；「提高」语义相近但「提升」更书面；「增强」多与「能力、意识」搭配；「拔高」含贬义。故选B。","__sub":"选词填空"},{"id":"yy-14506","module":"yanyu","diff":2,"exam":"事业编","prompt":"现实中，方法与态度不同，结果往往截然不同。越是任务艰巨，越要______发展规律，确保方向不偏、力度不减。看似寻常，实则是长期积累的结果。填入画横线处最恰当的是：","options":["把守","把握","把玩","把持"],"answer":1,"explanation":"「把握」与抽象事物（特点、规律、机遇）搭配；「把守」指守卫关口，「把持」含贬义指独揽，「把玩」指赏玩物品。故选B。","__sub":"选词填空"},{"id":"yy-14507","module":"yanyu","diff":2,"exam":"省考","prompt":"干事创业，思路和坚持缺一不可。下一步，将______服务空白，推动各项工作再上新台阶。唯有如此，才能把好事办好、实事办实。填入画横线处最恰当的是：","options":["填补","补足","弥补","补齐"],"answer":3,"explanation":"「补齐」与「短板」为固定搭配，强调使达到应有水平；「补足」多与「差额」搭配；「填补」多与「空白」搭配；「弥补」多与「损失」搭配。故选D。","__sub":"选词填空"},{"id":"yy-14508","module":"yanyu","diff":2,"exam":"省考","prompt":"事物的发展自有其规律，顺应它才能事半功倍。要在______共同思想基础上下更大功夫，让发展成果更多惠及全体人民。这样的要求，放在哪里都不过时。填入画横线处最恰当的是：","options":["筑牢","夯实","打牢","巩固"],"answer":1,"explanation":"「夯实」本义为砸实地基，引申为使稳固，与「基础、根基」搭配；「筑牢」与「防线」搭配；「打牢」语体稍口语；「巩固」侧重使已有的更牢固。故选B。","__sub":"选词填空"},{"id":"yy-14509","module":"yanyu","diff":3,"exam":"医疗编","prompt":"任何工作要见成效，都离不开科学的方法和踏实的作风。面对新形势新任务，必须______社会保障体系，牢牢把握发展主动权。唯有如此，才能把好事办好、实事办实。填入画横线处最恰当的是：","options":["健全","构建","建立","完善"],"answer":0,"explanation":"「健全」强调使完备无缺，与「体系」搭配规范；「建立」指从无到有，「完善」指补足短板，「构建」侧重搭建框架。故选A。","__sub":"选词填空"},{"id":"yy-14511","module":"yanyu","diff":1,"exam":"教师编","prompt":"现实中，方法与态度不同，结果往往截然不同。越是任务艰巨，越要______人才流动渠道，确保方向不偏、力度不减。看似寻常，实则是长期积累的结果。填入画横线处最恰当的是：","options":["畅通","开拓","疏通","打通"],"answer":0,"explanation":"「畅通」强调使通畅无阻，与「渠道」为固定搭配；「打通」侧重突破障碍；「疏通」多用于管道或疏导矛盾；「开拓」指开辟新领域。故选A。","__sub":"选词填空"},{"id":"yy-14512","module":"yanyu","diff":1,"exam":"医疗编","prompt":"现实中，方法与态度不同，结果往往截然不同。面对新形势新任务，必须______创新土壤，牢牢把握发展主动权。看似寻常，实则是长期积累的结果。填入画横线处最恰当的是：","options":["营造","培养","养护","涵养"],"answer":3,"explanation":"「涵养」指蓄积并养护，与「生态、水源」搭配；「培养」对象为人或能力；「营造」多与「氛围、环境」搭配；「养护」不含培育之义。故选D。","__sub":"选词填空"},{"id":"yy-14513","module":"yanyu","diff":1,"exam":"国考","prompt":"干事创业，思路和坚持缺一不可。各地区各部门要拿出真招实招，______本领，确保各项部署落地生根。其中的道理值得每个人细细体会。填入画横线处最恰当的是：","options":["磨砺","锻炼","砥砺","锤炼"],"answer":2,"explanation":"「砥砺」本义为磨刀石，引申为磨炼，与「意志」搭配且语体庄重；「磨砺」与之近义但「砥砺」更常用于「砥砺前行、砥砺意志」。故选C。","__sub":"选词填空"},{"id":"yy-14514","module":"yanyu","diff":2,"exam":"事业编","prompt":"很多事看起来简单，真要做扎实并不容易。下一步，将______区域协调发展的新格局，推动各项工作再上新台阶。道理虽朴素，真正做到并不容易。填入画横线处最恰当的是：","options":["描绘","勾画","擘画","规划"],"answer":2,"explanation":"「擘画」指筹划布置，多用于宏观蓝图，书面色彩浓；「描绘」「勾画」偏具体画面；「规划」语体色彩不足。故选C。","__sub":"选词填空"},{"id":"yy-14515","module":"yanyu","diff":2,"exam":"省考","prompt":"一个朴素的道理反复被验证：方向对了，努力才不会白费。面对新形势新任务，必须______改革红利，牢牢把握发展主动权。这也正是成事的关键所在。填入画横线处最恰当的是：","options":["释放","散发","发挥","爆发"],"answer":0,"explanation":"「释放」与「潜力、红利、活力」搭配；「散发」指分散发出；「发挥」与「作用」搭配；「爆发」指突然发作。故选A。","__sub":"选词填空"},{"id":"yy-14516","module":"yanyu","diff":2,"exam":"事业编","prompt":"很多事看起来简单，真要做扎实并不容易。要在______经济社会发展全过程上下更大功夫，让发展成果更多惠及全体人民。道理虽朴素，真正做到并不容易。填入画横线处最恰当的是：","options":["贯穿","经过","穿过","贯串"],"answer":0,"explanation":"「贯穿」指从头到尾通贯，与「全过程」搭配规范；「穿过」「经过」仅指空间或时间经过，不含通贯始终之义。故选A。","__sub":"选词填空"},{"id":"yy-14517","module":"yanyu","diff":2,"exam":"事业编","prompt":"各地区各部门要拿出真招实招，______碳达峰碳中和目标，确保各项部署落地生根。填入画横线处最恰当的是：","options":["锚定","盯住","锁定","瞄准"],"answer":0,"explanation":"「锚定」比喻像锚一样固定住目标，多用于宏观战略语境；「锁定」「瞄准」「盯住」语体偏口语，庄重色彩不足。故选A。","__sub":"选词填空"},{"id":"yy-14518","module":"yanyu","diff":2,"exam":"医疗编","prompt":"事物的发展自有其规律，顺应它才能事半功倍。越是任务艰巨，越要______群众需求，确保方向不偏、力度不减。这样的要求，放在哪里都不过时。填入画横线处最恰当的是：","options":["把握","把玩","把守","把持"],"answer":0,"explanation":"「把握」与抽象事物（特点、规律、机遇）搭配；「把守」指守卫关口，「把持」含贬义指独揽，「把玩」指赏玩物品。故选A。","__sub":"选词填空"},{"id":"yy-14519","module":"yanyu","diff":3,"exam":"国考","prompt":"观察身边的事不难发现，成败的分野常常藏在细节里。面对新形势新任务，必须______城市文化气质，牢牢把握发展主动权。说到底，拼的是态度，比的是功夫。填入画横线处最恰当的是：","options":["营造","养护","涵养","培养"],"answer":2,"explanation":"「涵养」指蓄积并养护，与「生态、水源」搭配；「培养」对象为人或能力；「营造」多与「氛围、环境」搭配；「养护」不含培育之义。故选C。","__sub":"选词填空"},{"id":"yy-14521","module":"yanyu","diff":1,"exam":"教师编","prompt":"现实中，方法与态度不同，结果往往截然不同。越是任务艰巨，越要______发展与安全，确保方向不偏、力度不减。看似寻常，实则是长期积累的结果。填入画横线处最恰当的是：","options":["兼顾","统率","统筹","协调"],"answer":2,"explanation":"「统筹」指全面筹划、统一安排，与「推进」搭配且强调全局性；「统率」指率领；「兼顾」只强调同时照顾；「协调」侧重配合关系。故选C。","__sub":"选词填空"},{"id":"yy-14522","module":"yanyu","diff":1,"exam":"省考","prompt":"事物的发展自有其规律，顺应它才能事半功倍。面对新形势新任务，必须______爱国情怀，牢牢把握发展主动权。这样的要求，放在哪里都不过时。填入画横线处最恰当的是：","options":["培植","筑牢","加深","厚植"],"answer":3,"explanation":"「厚植」指深厚培育，与「优势、底色、根基」搭配；「培植」多用于培育动植物或扶植势力；「加深」与「底色」搭配不当。故选D。","__sub":"选词填空"},{"id":"yy-14523","module":"yanyu","diff":1,"exam":"省考","prompt":"现实中，方法与态度不同，结果往往截然不同。面对新形势新任务，必须______各方合力，牢牢把握发展主动权。看似寻常，实则是长期积累的结果。填入画横线处最恰当的是：","options":["汇聚","凝聚","聚集","集中"],"answer":1,"explanation":"「凝聚」多与「共识、人心、力量」搭配，强调由分散到统一；「聚集」侧重物理集合；「集中」侧重把分散的集中起来。故选B。","__sub":"选词填空"},{"id":"yy-14524","module":"yanyu","diff":2,"exam":"国考","prompt":"很多事看起来简单，真要做扎实并不容易。要在______监督机制上下更大功夫，让发展成果更多惠及全体人民。道理虽朴素，真正做到并不容易。填入画横线处最恰当的是：","options":["完善","建立","健全","构建"],"answer":2,"explanation":"「健全」强调使完备无缺，与「体系」搭配规范；「建立」指从无到有，「完善」指补足短板，「构建」侧重搭建框架。故选C。","__sub":"选词填空"},{"id":"yy-14525","module":"yanyu","diff":2,"exam":"事业编","prompt":"任何工作要见成效，都离不开科学的方法和踏实的作风。越是任务艰巨，越要______就业服务体系，确保方向不偏、力度不减。唯有如此，才能把好事办好、实事办实。填入画横线处最恰当的是：","options":["建立","健全","完善","构建"],"answer":1,"explanation":"「健全」强调使完备无缺，与「体系」搭配规范；「建立」指从无到有，「完善」指补足短板，「构建」侧重搭建框架。故选B。","__sub":"选词填空"},{"id":"yy-14526","module":"yanyu","diff":2,"exam":"国考","prompt":"任何工作要见成效，都离不开科学的方法和踏实的作风。要在______人才流动渠道上下更大功夫，让发展成果更多惠及全体人民。唯有如此，才能把好事办好、实事办实。填入画横线处最恰当的是：","options":["疏通","开拓","畅通","打通"],"answer":2,"explanation":"「畅通」强调使通畅无阻，与「渠道」为固定搭配；「打通」侧重突破障碍；「疏通」多用于管道或疏导矛盾；「开拓」指开辟新领域。故选C。","__sub":"选词填空"},{"id":"yy-14527","module":"yanyu","diff":2,"exam":"省考","prompt":"现实中，方法与态度不同，结果往往截然不同。越是任务艰巨，越要______违规行为的苗头，确保方向不偏、力度不减。看似寻常，实则是长期积累的结果。填入画横线处最恰当的是：","options":["制止","遏止","控制","遏制"],"answer":3,"explanation":"「遏制」强调压制住势头、多与「势头/态势」搭配；「遏止」侧重使之停止，多用于具体行为；「控制」「制止」语义宽泛。故选D。","__sub":"选词填空"},{"id":"yy-14528","module":"yanyu","diff":2,"exam":"事业编","prompt":"无论时代如何变化，把事情做实做细始终是成事的基础。下一步，将______高质量发展的生态底色，推动各项工作再上新台阶。这背后考验的正是把握分寸的智慧。填入画横线处最恰当的是：","options":["培植","加深","厚植","筑牢"],"answer":2,"explanation":"「厚植」指深厚培育，与「优势、底色、根基」搭配；「培植」多用于培育动植物或扶植势力；「加深」与「底色」搭配不当。故选C。","__sub":"选词填空"},{"id":"yy-14529","module":"yanyu","diff":3,"exam":"省考","prompt":"观察身边的事不难发现，成败的分野常常藏在细节里。回顾这些年走过的路，______各类资源配置始终是我们攻坚克难的重要法宝。说到底，拼的是态度，比的是功夫。填入画横线处最恰当的是：","options":["兼顾","统率","统筹","协调"],"answer":2,"explanation":"「统筹」指全面筹划、统一安排，与「推进」搭配且强调全局性；「统率」指率领；「兼顾」只强调同时照顾；「协调」侧重配合关系。故选C。","__sub":"选词填空"},{"id":"yy-14530","module":"yanyu","diff":3,"exam":"事业编","prompt":"无论时代如何变化，把事情做实做细始终是成事的基础。回顾这些年走过的路，______资源配置始终是我们攻坚克难的重要法宝。这背后考验的正是把握分寸的智慧。填入画横线处最恰当的是：","options":["改进","调整","改善","优化"],"answer":3,"explanation":"「优化」指加以改变使其优良，与「环境、结构」搭配规范；「改善」多与「条件、生活」搭配；「改进」多与「方法、工作」搭配；「调整」不含变优之义。故选D。","__sub":"选词填空"},{"id":"yy-14532","module":"yanyu","diff":1,"exam":"省考","prompt":"无论时代如何变化，把事情做实做细始终是成事的基础。要在______时代脉搏上下更大功夫，让发展成果更多惠及全体人民。道理虽朴素，真正做到并不容易。填入画横线处最恰当的是：","options":["把玩","把握","把守","把持"],"answer":1,"explanation":"「把握」与抽象事物（特点、规律、机遇）搭配；「把守」指守卫关口，「把持」含贬义指独揽，「把玩」指赏玩物品。故选B。","__sub":"选词填空"},{"id":"yy-14533","module":"yanyu","diff":1,"exam":"国考","prompt":"各级政府要持续______沉睡的资源要素，不断增强群众的获得感、幸福感、安全感。填入画横线处最恰当的是：","options":["启动","激活","驱动","唤醒"],"answer":1,"explanation":"「激活」指刺激使之活跃，与「动力、要素」搭配；「唤醒」指使之觉醒；「启动」指开始进行；「驱动」指推动运转。故选B。","__sub":"选词填空"},{"id":"yy-14534","module":"yanyu","diff":2,"exam":"教师编","prompt":"事物的发展自有其规律，顺应它才能事半功倍。越是任务艰巨，越要______本领，确保方向不偏、力度不减。这样的要求，放在哪里都不过时。填入画横线处最恰当的是：","options":["砥砺","锤炼","磨砺","锻炼"],"answer":0,"explanation":"「砥砺」本义为磨刀石，引申为磨炼，与「意志」搭配且语体庄重；「磨砺」与之近义但「砥砺」更常用于「砥砺前行、砥砺意志」。故选A。","__sub":"选词填空"},{"id":"yy-14535","module":"yanyu","diff":2,"exam":"事业编","prompt":"一个朴素的道理反复被验证：方向对了，努力才不会白费。面对新形势新任务，必须______农村物流最后一公里，牢牢把握发展主动权。这也正是成事的关键所在。填入画横线处最恰当的是：","options":["打通","贯通","开辟","畅通"],"answer":3,"explanation":"「畅通」强调使通畅无阻，与「渠道、通道」搭配；「打通」侧重突破障碍；「贯通」指连接相通；「开辟」指新开路径。故选D。","__sub":"选词填空"},{"id":"yy-14536","module":"yanyu","diff":2,"exam":"事业编","prompt":"无论时代如何变化，把事情做实做细始终是成事的基础。面对新形势新任务，必须______生态恶化的趋势，牢牢把握发展主动权。这背后考验的正是把握分寸的智慧。填入画横线处最恰当的是：","options":["遏止","遏制","控制","制止"],"answer":1,"explanation":"「遏制」强调压制住势头、多与「势头/态势」搭配；「遏止」侧重使之停止，多用于具体行为；「控制」「制止」语义宽泛。故选B。","__sub":"选词填空"},{"id":"yy-14540","module":"yanyu","diff":3,"exam":"省考","prompt":"干事创业，思路和坚持缺一不可。当前正值关键时期，______品格刻不容缓，必须抓紧抓实抓出成效。其中的道理值得每个人细细体会。填入画横线处最恰当的是：","options":["锤炼","砥砺","锻炼","磨砺"],"answer":1,"explanation":"「砥砺」本义为磨刀石，引申为磨炼，与「意志」搭配且语体庄重；「磨砺」与之近义但「砥砺」更常用于「砥砺前行、砥砺意志」。故选B。","__sub":"选词填空"},{"id":"yy-14541","module":"yanyu","diff":1,"exam":"事业编","prompt":"事物的发展自有其规律，顺应它才能事半功倍。回顾这些年走过的路，______改革任务书始终是我们攻坚克难的重要法宝。这样的要求，放在哪里都不过时。填入画横线处最恰当的是：","options":["瞄准","锁定","锚定","盯住"],"answer":2,"explanation":"「锚定」比喻像锚一样固定住目标，多用于宏观战略语境；「锁定」「瞄准」「盯住」语体偏口语，庄重色彩不足。故选C。","__sub":"选词填空"},{"id":"yy-14542","module":"yanyu","diff":1,"exam":"省考","prompt":"现实中，方法与态度不同，结果往往截然不同。回顾这些年走过的路，______发展合力始终是我们攻坚克难的重要法宝。看似寻常，实则是长期积累的结果。填入画横线处最恰当的是：","options":["汇聚","凝聚","集中","聚集"],"answer":1,"explanation":"「凝聚」多与「共识、人心、力量」搭配，强调由分散到统一；「聚集」侧重物理集合；「集中」侧重把分散的集中起来。故选B。","__sub":"选词填空"},{"id":"yy-14543","module":"yanyu","diff":1,"exam":"省考","prompt":"任何工作要见成效，都离不开科学的方法和踏实的作风。当前正值关键时期，______服务空白刻不容缓，必须抓紧抓实抓出成效。唯有如此，才能把好事办好、实事办实。填入画横线处最恰当的是：","options":["补齐","填补","弥补","补足"],"answer":0,"explanation":"「补齐」与「短板」为固定搭配，强调使达到应有水平；「补足」多与「差额」搭配；「填补」多与「空白」搭配；「弥补」多与「损失」搭配。故选A。","__sub":"选词填空"},{"id":"yy-14545","module":"yanyu","diff":2,"exam":"国考","prompt":"一个朴素的道理反复被验证：方向对了，努力才不会白费。下一步，将______文明乡风，推动各项工作再上新台阶。这也正是成事的关键所在。填入画横线处最恰当的是：","options":["培养","营造","涵养","养护"],"answer":2,"explanation":"「涵养」指蓄积并养护，与「生态、水源」搭配；「培养」对象为人或能力；「营造」多与「氛围、环境」搭配；「养护」不含培育之义。故选C。","__sub":"选词填空"},{"id":"yy-14546","module":"yanyu","diff":2,"exam":"省考","prompt":"现实中，方法与态度不同，结果往往截然不同。各级政府要持续______专精特新企业，不断增强群众的获得感、幸福感、安全感。看似寻常，实则是长期积累的结果。填入画横线处最恰当的是：","options":["培育","孕育","培养","培植"],"answer":0,"explanation":"「培育」与「产业、企业、市场」搭配；「培养」对象为人或能力；「培植」多用于动植物或含贬义；「孕育」强调正在形成。故选A。","__sub":"选词填空"},{"id":"yy-14547","module":"yanyu","diff":2,"exam":"事业编","prompt":"任何工作要见成效，都离不开科学的方法和踏实的作风。新征程上，要继续______安全生产责任，以实干实绩回应人民期盼。唯有如此，才能把好事办好、实事办实。填入画横线处最恰当的是：","options":["压紧","落实","压实","强化"],"answer":2,"explanation":"「压实」与「责任」搭配，强调责任层层落实到位；「落实」为通用动词；「压紧」常作「压紧压实」；「强化」不如「压实」精准体现层级传导。故选C。","__sub":"选词填空"},{"id":"yy-14548","module":"yanyu","diff":2,"exam":"医疗编","prompt":"现实中，方法与态度不同，结果往往截然不同。要坚持问题导向，______底线思维，切实解决群众急难愁盼问题。看似寻常，实则是长期积累的结果。填入画横线处最恰当的是：","options":["加强","强化","深化","增强"],"answer":1,"explanation":"「强化」与「意识、思维」搭配，强调使之更牢固；「增强」语义相近但搭配习惯不同；「加强」为通用动词；「深化」指向深处发展。故选B。","__sub":"选词填空"},{"id":"yy-14549","module":"yanyu","diff":3,"exam":"事业编","prompt":"一个朴素的道理反复被验证：方向对了，努力才不会白费。实践证明，______改革红利是推动高质量发展的关键一招。这也正是成事的关键所在。填入画横线处最恰当的是：","options":["发挥","释放","散发","爆发"],"answer":1,"explanation":"「释放」与「潜力、红利、活力」搭配；「散发」指分散发出；「发挥」与「作用」搭配；「爆发」指突然发作。故选B。","__sub":"选词填空"},{"id":"yy-14550","module":"yanyu","diff":3,"exam":"省考","prompt":"一个朴素的道理反复被验证：方向对了，努力才不会白费。下一步，将______创新根基，推动各项工作再上新台阶。这也正是成事的关键所在。填入画横线处最恰当的是：","options":["培植","厚植","筑牢","加深"],"answer":1,"explanation":"「厚植」指深厚培育，与「优势、底色、根基」搭配；「培植」多用于培育动植物或扶植势力；「加深」与「底色」搭配不当。故选B。","__sub":"选词填空"},{"id":"yy-14551","module":"yanyu","diff":1,"exam":"国考","prompt":"任何工作要见成效，都离不开科学的方法和踏实的作风。回顾这些年走过的路，______消费市场一池春水始终是我们攻坚克难的重要法宝。唯有如此，才能把好事办好、实事办实。填入画横线处最恰当的是：","options":["启动","唤醒","驱动","激活"],"answer":3,"explanation":"「激活」指刺激使之活跃，与「动力、要素」搭配；「唤醒」指使之觉醒；「启动」指开始进行；「驱动」指推动运转。故选D。","__sub":"选词填空"},{"id":"yy-14553","module":"yanyu","diff":1,"exam":"国考","prompt":"事物的发展自有其规律，顺应它才能事半功倍。各地区各部门要拿出真招实招，______教育资源配置，确保各项部署落地生根。这样的要求，放在哪里都不过时。填入画横线处最恰当的是：","options":["下坠","下沉","下探","下潜"],"answer":1,"explanation":"「下沉」指治理资源向基层倾斜，是规范表述；「下潜」指潜水，「下探」多指价格或行动试探，「下坠」指物体坠落。故选B。","__sub":"选词填空"},{"id":"yy-14554","module":"yanyu","diff":2,"exam":"国考","prompt":"干事创业，思路和坚持缺一不可。各地区各部门要拿出真招实招，______乡村振兴始终，确保各项部署落地生根。其中的道理值得每个人细细体会。填入画横线处最恰当的是：","options":["贯穿","经过","穿过","贯串"],"answer":0,"explanation":"「贯穿」指从头到尾通贯，与「全过程」搭配规范；「穿过」「经过」仅指空间或时间经过，不含通贯始终之义。故选A。","__sub":"选词填空"},{"id":"yy-14555","module":"yanyu","diff":2,"exam":"事业编","prompt":"事物的发展自有其规律，顺应它才能事半功倍。面对新形势新任务，必须______乡村振兴的壮美画卷，牢牢把握发展主动权。这样的要求，放在哪里都不过时。填入画横线处最恰当的是：","options":["擘画","勾画","描绘","规划"],"answer":0,"explanation":"「擘画」指筹划布置，多用于宏观蓝图，书面色彩浓；「描绘」「勾画」偏具体画面；「规划」语体色彩不足。故选A。","__sub":"选词填空"},{"id":"yy-14558","module":"yanyu","diff":2,"exam":"省考","prompt":"干事创业，思路和坚持缺一不可。要在______违规行为的苗头上下更大功夫，让发展成果更多惠及全体人民。其中的道理值得每个人细细体会。填入画横线处最恰当的是：","options":["制止","遏制","遏止","控制"],"answer":1,"explanation":"「遏制」强调压制住势头、多与「势头/态势」搭配；「遏止」侧重使之停止，多用于具体行为；「控制」「制止」语义宽泛。故选B。","__sub":"选词填空"},{"id":"yy-14559","module":"yanyu","diff":3,"exam":"省考","prompt":"观察身边的事不难发现，成败的分野常常藏在细节里。越是任务艰巨，越要______放管服改革，确保方向不偏、力度不减。说到底，拼的是态度，比的是功夫。填入画横线处最恰当的是：","options":["加强","深入","推进","深化"],"answer":3,"explanation":"「深化」指向更深阶段发展，与「改革」为固定搭配；「深入」多作形容词或「深入调查」；「加强」「推进」语义宽泛。故选D。","__sub":"选词填空"},{"id":"yy-14560","module":"yanyu","diff":3,"exam":"事业编","prompt":"一个朴素的道理反复被验证：方向对了，努力才不会白费。越是任务艰巨，越要______供给侧结构性改革，确保方向不偏、力度不减。这也正是成事的关键所在。填入画横线处最恰当的是：","options":["深化","推进","深入","加强"],"answer":0,"explanation":"「深化」指向更深阶段发展，与「改革」为固定搭配；「深入」多作形容词或「深入调查」；「加强」「推进」语义宽泛。故选A。","__sub":"选词填空"},{"id":"yy-14561","module":"yanyu","diff":1,"exam":"国考","prompt":"任何工作要见成效，都离不开科学的方法和踏实的作风。回顾这些年走过的路，______违规行为的苗头始终是我们攻坚克难的重要法宝。唯有如此，才能把好事办好、实事办实。填入画横线处最恰当的是：","options":["遏制","控制","遏止","制止"],"answer":0,"explanation":"「遏制」强调压制住势头、多与「势头/态势」搭配；「遏止」侧重使之停止，多用于具体行为；「控制」「制止」语义宽泛。故选A。","__sub":"选词填空"},{"id":"yy-14562","module":"yanyu","diff":1,"exam":"事业编","prompt":"现实中，方法与态度不同，结果往往截然不同。回顾这些年走过的路，______经营主体信心始终是我们攻坚克难的重要法宝。看似寻常，实则是长期积累的结果。填入画横线处最恰当的是：","options":["激发","点燃","引发","调动"],"answer":0,"explanation":"「激发」与「活力、热情、潜能」为固定搭配；「引发」多与「关注、争议」搭配；「点燃」为比喻用法；「调动」多与「积极性」搭配。故选A。","__sub":"选词填空"},{"id":"yy-14563","module":"yanyu","diff":1,"exam":"国考","prompt":"观察身边的事不难发现，成败的分野常常藏在细节里。回顾这些年走过的路，______安全屏障始终是我们攻坚克难的重要法宝。说到底，拼的是态度，比的是功夫。填入画横线处最恰当的是：","options":["筑造","夯实","构建","筑牢"],"answer":3,"explanation":"「筑牢」与「防线」为固定搭配，强调使牢固；「筑造」指建造实体；「构建」侧重搭建体系；「夯实」多与「基础」搭配。故选D。","__sub":"选词填空"},{"id":"yy-14564","module":"yanyu","diff":2,"exam":"省考","prompt":"观察身边的事不难发现，成败的分野常常藏在细节里。要在______法治体系上下更大功夫，让发展成果更多惠及全体人民。说到底，拼的是态度，比的是功夫。填入画横线处最恰当的是：","options":["建立","完善","健全","构建"],"answer":2,"explanation":"「健全」强调使完备无缺，与「体系」搭配规范；「建立」指从无到有，「完善」指补足短板，「构建」侧重搭建框架。故选C。","__sub":"选词填空"},{"id":"yy-14565","module":"yanyu","diff":2,"exam":"事业编","prompt":"一个朴素的道理反复被验证：方向对了，努力才不会白费。越是任务艰巨，越要______新兴产业，确保方向不偏、力度不减。这也正是成事的关键所在。填入画横线处最恰当的是：","options":["培养","培育","孕育","培植"],"answer":1,"explanation":"「培育」与「产业、企业、市场」搭配；「培养」对象为人或能力；「培植」多用于动植物或含贬义；「孕育」强调正在形成。故选B。","__sub":"选词填空"},{"id":"yy-14566","module":"yanyu","diff":2,"exam":"事业编","prompt":"现实中，方法与态度不同，结果往往截然不同。要坚持问题导向，______新时代发展的宏伟蓝图，切实解决群众急难愁盼问题。看似寻常，实则是长期积累的结果。填入画横线处最恰当的是：","options":["规划","擘画","描绘","勾画"],"answer":1,"explanation":"「擘画」指筹划布置，多用于宏观蓝图，书面色彩浓；「描绘」「勾画」偏具体画面；「规划」语体色彩不足。故选B。","__sub":"选词填空"},{"id":"yy-14567","module":"yanyu","diff":2,"exam":"教师编","prompt":"干事创业，思路和坚持缺一不可。下一步，将______志愿服务体系，推动各项工作再上新台阶。其中的道理值得每个人细细体会。填入画横线处最恰当的是：","options":["完善","搭建","健全","构建"],"answer":2,"explanation":"「健全」强调使完备无缺；「完善」指补足短板；「构建」「搭建」侧重从无到有搭建。故选C。","__sub":"选词填空"},{"id":"yy-14568","module":"yanyu","diff":2,"exam":"事业编","prompt":"无论时代如何变化，把事情做实做细始终是成事的基础。要坚持问题导向，______农产品上行通道，切实解决群众急难愁盼问题。这背后考验的正是把握分寸的智慧。填入画横线处最恰当的是：","options":["畅通","开拓","疏通","打通"],"answer":0,"explanation":"「畅通」强调使通畅无阻，与「渠道」为固定搭配；「打通」侧重突破障碍；「疏通」多用于管道或疏导矛盾；「开拓」指开辟新领域。故选A。","__sub":"选词填空"},{"id":"yy-14569","module":"yanyu","diff":3,"exam":"医疗编","prompt":"任何工作要见成效，都离不开科学的方法和踏实的作风。面对新形势新任务，必须______意志，牢牢把握发展主动权。唯有如此，才能把好事办好、实事办实。填入画横线处最恰当的是：","options":["砥砺","锤炼","磨砺","锻炼"],"answer":0,"explanation":"「砥砺」本义为磨刀石，引申为磨炼，与「意志」搭配且语体庄重；「磨砺」与之近义但「砥砺」更常用于「砥砺前行、砥砺意志」。故选A。","__sub":"选词填空"},{"id":"yy-14571","module":"yanyu","diff":1,"exam":"省考","prompt":"干事创业，思路和坚持缺一不可。新征程上，要继续______消费潜力，以实干实绩回应人民期盼。其中的道理值得每个人细细体会。填入画横线处最恰当的是：","options":["发挥","爆发","散发","释放"],"answer":3,"explanation":"「释放」与「潜力、红利、活力」搭配；「散发」指分散发出；「发挥」与「作用」搭配；「爆发」指突然发作。故选D。","__sub":"选词填空"},{"id":"yy-14572","module":"yanyu","diff":1,"exam":"国考","prompt":"无论时代如何变化，把事情做实做细始终是成事的基础。越是任务艰巨，越要______创新土壤，确保方向不偏、力度不减。这背后考验的正是把握分寸的智慧。填入画横线处最恰当的是：","options":["培养","养护","涵养","营造"],"answer":2,"explanation":"「涵养」指蓄积并养护，与「生态、水源」搭配；「培养」对象为人或能力；「营造」多与「氛围、环境」搭配；「养护」不含培育之义。故选C。","__sub":"选词填空"},{"id":"yy-14573","module":"yanyu","diff":1,"exam":"事业编","prompt":"观察身边的事不难发现，成败的分野常常藏在细节里。各地区各部门要拿出真招实招，______思想防线，确保各项部署落地生根。说到底，拼的是态度，比的是功夫。填入画横线处最恰当的是：","options":["筑牢","夯实","构建","筑造"],"answer":0,"explanation":"「筑牢」与「防线」为固定搭配，强调使牢固；「筑造」指建造实体；「构建」侧重搭建体系；「夯实」多与「基础」搭配。故选A。","__sub":"选词填空"},{"id":"yy-14574","module":"yanyu","diff":2,"exam":"省考","prompt":"观察身边的事不难发现，成败的分野常常藏在细节里。越是任务艰巨，越要______生态环保责任，确保方向不偏、力度不减。说到底，拼的是态度，比的是功夫。填入画横线处最恰当的是：","options":["压紧","强化","落实","压实"],"answer":3,"explanation":"「压实」与「责任」搭配，强调责任层层落实到位；「落实」为通用动词；「压紧」常作「压紧压实」；「强化」不如「压实」精准体现层级传导。故选D。","__sub":"选词填空"},{"id":"yy-14575","module":"yanyu","diff":2,"exam":"医疗编","prompt":"事物的发展自有其规律，顺应它才能事半功倍。当前正值关键时期，______数据要素价值刻不容缓，必须抓紧抓实抓出成效。这样的要求，放在哪里都不过时。填入画横线处最恰当的是：","options":["发挥","爆发","释放","散发"],"answer":2,"explanation":"「释放」与「潜力、红利、活力」搭配；「散发」指分散发出；「发挥」与「作用」搭配；「爆发」指突然发作。故选C。","__sub":"选词填空"},{"id":"yy-14576","module":"yanyu","diff":2,"exam":"国考","prompt":"观察身边的事不难发现，成败的分野常常藏在细节里。要在______消费新增长点上下更大功夫，让发展成果更多惠及全体人民。说到底，拼的是态度，比的是功夫。填入画横线处最恰当的是：","options":["培育","孕育","培植","培养"],"answer":0,"explanation":"「培育」与「产业、企业、市场」搭配；「培养」对象为人或能力；「培植」多用于动植物或含贬义；「孕育」强调正在形成。故选A。","__sub":"选词填空"},{"id":"yy-14577","module":"yanyu","diff":2,"exam":"国考","prompt":"现实中，方法与态度不同，结果往往截然不同。要坚持问题导向，______新型农业经营主体，切实解决群众急难愁盼问题。看似寻常，实则是长期积累的结果。填入画横线处最恰当的是：","options":["培育","培植","培养","孕育"],"answer":0,"explanation":"「培育」与「产业、企业、市场」搭配；「培养」对象为人或能力；「培植」多用于动植物或含贬义；「孕育」强调正在形成。故选A。","__sub":"选词填空"},{"id":"yy-14578","module":"yanyu","diff":2,"exam":"省考","prompt":"事物的发展自有其规律，顺应它才能事半功倍。实践证明，______发展与安全是推动高质量发展的关键一招。这样的要求，放在哪里都不过时。填入画横线处最恰当的是：","options":["协调","统筹","统率","兼顾"],"answer":1,"explanation":"「统筹」指全面筹划、统一安排，与「推进」搭配且强调全局性；「统率」指率领；「兼顾」只强调同时照顾；「协调」侧重配合关系。故选B。","__sub":"选词填空"},{"id":"yy-14580","module":"yanyu","diff":3,"exam":"教师编","prompt":"无论时代如何变化，把事情做实做细始终是成事的基础。新征程上，要继续______传统产业转型升级，以实干实绩回应人民期盼。这背后考验的正是把握分寸的智慧。填入画横线处最恰当的是：","options":["加持","赋权","赋能","助力"],"answer":2,"explanation":"「赋能」指赋予能力，是数字经济语境的规范表述；「赋权」指赋予权力；「加持」为口语化外来词；「助力」语义宽泛。故选C。","__sub":"选词填空"},{"id":"yy-14581","module":"yanyu","diff":1,"exam":"教师编","prompt":"一个朴素的道理反复被验证：方向对了，努力才不会白费。要在______耕地保护红线上下更大功夫，让发展成果更多惠及全体人民。这也正是成事的关键所在。填入画横线处最恰当的是：","options":["把牢","守住","守牢","防住"],"answer":2,"explanation":"「守牢」与「底线」搭配，强调牢牢守住；「守住」程度稍弱；「把牢」多与「关口」搭配；「防住」为口语。故选C。","__sub":"选词填空"},{"id":"yy-14582","module":"yanyu","diff":1,"exam":"事业编","prompt":"事物的发展自有其规律，顺应它才能事半功倍。新征程上，要继续______底线思维，以实干实绩回应人民期盼。这样的要求，放在哪里都不过时。填入画横线处最恰当的是：","options":["深化","增强","加强","强化"],"answer":3,"explanation":"「强化」与「意识、思维」搭配，强调使之更牢固；「增强」语义相近但搭配习惯不同；「加强」为通用动词；「深化」指向深处发展。故选D。","__sub":"选词填空"},{"id":"yy-14583","module":"yanyu","diff":1,"exam":"国考","prompt":"无论时代如何变化，把事情做实做细始终是成事的基础。要坚持问题导向，______人才流动渠道，切实解决群众急难愁盼问题。这背后考验的正是把握分寸的智慧。填入画横线处最恰当的是：","options":["打通","疏通","开拓","畅通"],"answer":3,"explanation":"「畅通」强调使通畅无阻，与「渠道」为固定搭配；「打通」侧重突破障碍；「疏通」多用于管道或疏导矛盾；「开拓」指开辟新领域。故选D。","__sub":"选词填空"},{"id":"yy-14584","module":"yanyu","diff":2,"exam":"事业编","prompt":"事物的发展自有其规律，顺应它才能事半功倍。面对新形势新任务，必须______基层治理效能，牢牢把握发展主动权。这样的要求，放在哪里都不过时。填入画横线处最恰当的是：","options":["提升","提高","拔高","增强"],"answer":0,"explanation":"「提升」与「效能、水平」搭配规范；「提高」语义相近但「提升」更书面；「增强」多与「能力、意识」搭配；「拔高」含贬义。故选A。","__sub":"选词填空"},{"id":"yy-14585","module":"yanyu","diff":2,"exam":"省考","prompt":"事物的发展自有其规律，顺应它才能事半功倍。当前正值关键时期，______改革红利刻不容缓，必须抓紧抓实抓出成效。这样的要求，放在哪里都不过时。填入画横线处最恰当的是：","options":["释放","发挥","爆发","散发"],"answer":0,"explanation":"「释放」与「潜力、红利、活力」搭配；「散发」指分散发出；「发挥」与「作用」搭配；「爆发」指突然发作。故选A。","__sub":"选词填空"},{"id":"yy-14586","module":"yanyu","diff":2,"exam":"教师编","prompt":"很多事看起来简单，真要做扎实并不容易。实践证明，______视野和思路是推动高质量发展的关键一招。道理虽朴素，真正做到并不容易。填入画横线处最恰当的是：","options":["开拓","扩大","拓宽","延伸"],"answer":2,"explanation":"「拓宽」与「渠道、门路、视野」搭配；「开拓」指开辟新领域；「扩大」多与「规模、范围」搭配；「延伸」侧重长度延长。故选C。","__sub":"选词填空"},{"id":"yy-14588","module":"yanyu","diff":2,"exam":"教师编","prompt":"任何工作要见成效，都离不开科学的方法和踏实的作风。当前正值关键时期，______市场主体活力刻不容缓，必须抓紧抓实抓出成效。唯有如此，才能把好事办好、实事办实。填入画横线处最恰当的是：","options":["引发","激发","点燃","调动"],"answer":1,"explanation":"「激发」与「活力、热情、潜能」为固定搭配；「引发」多与「关注、争议」搭配；「点燃」为比喻用法；「调动」多与「积极性」搭配。故选B。","__sub":"选词填空"},{"id":"yy-14589","module":"yanyu","diff":3,"exam":"事业编","prompt":"无论时代如何变化，把事情做实做细始终是成事的基础。实践证明，______资源配置是推动高质量发展的关键一招。这背后考验的正是把握分寸的智慧。填入画横线处最恰当的是：","options":["改进","优化","改善","调整"],"answer":1,"explanation":"「优化」指加以改变使其优良，与「环境、结构」搭配规范；「改善」多与「条件、生活」搭配；「改进」多与「方法、工作」搭配；「调整」不含变优之义。故选B。","__sub":"选词填空"},{"id":"yy-14590","module":"yanyu","diff":3,"exam":"国考","prompt":"任何工作要见成效，都离不开科学的方法和踏实的作风。各级政府要持续______能源结构，不断增强群众的获得感、幸福感、安全感。唯有如此，才能把好事办好、实事办实。填入画横线处最恰当的是：","options":["调整","改进","改善","优化"],"answer":3,"explanation":"「优化」指加以改变使其优良，与「环境、结构」搭配规范；「改善」多与「条件、生活」搭配；「改进」多与「方法、工作」搭配；「调整」不含变优之义。故选D。","__sub":"选词填空"},{"id":"yy-14591","module":"yanyu","diff":1,"exam":"事业编","prompt":"干事创业，思路和坚持缺一不可。越是任务艰巨，越要______高质量发展的生态底色，确保方向不偏、力度不减。其中的道理值得每个人细细体会。填入画横线处最恰当的是：","options":["筑牢","培植","厚植","加深"],"answer":2,"explanation":"「厚植」指深厚培育，与「优势、底色、根基」搭配；「培植」多用于培育动植物或扶植势力；「加深」与「底色」搭配不当。故选C。","__sub":"选词填空"},{"id":"yy-14592","module":"yanyu","diff":1,"exam":"国考","prompt":"很多事看起来简单，真要做扎实并不容易。实践证明，______群众获得感是推动高质量发展的关键一招。道理虽朴素，真正做到并不容易。填入画横线处最恰当的是：","options":["拔高","提升","提高","增强"],"answer":1,"explanation":"「提升」与「效能、水平」搭配规范；「提高」语义相近但「提升」更书面；「增强」多与「能力、意识」搭配；「拔高」含贬义。故选B。","__sub":"选词填空"},{"id":"yy-14593","module":"yanyu","diff":1,"exam":"国考","prompt":"很多事看起来简单，真要做扎实并不容易。各地区各部门要拿出真招实招，______城市功能品质，确保各项部署落地生根。道理虽朴素，真正做到并不容易。填入画横线处最恰当的是：","options":["提高","增强","拔高","提升"],"answer":3,"explanation":"「提升」与「效能、水平」搭配规范；「提高」语义相近但「提升」更书面；「增强」多与「能力、意识」搭配；「拔高」含贬义。故选D。","__sub":"选词填空"},{"id":"yy-14594","module":"yanyu","diff":2,"exam":"医疗编","prompt":"任何工作要见成效，都离不开科学的方法和踏实的作风。当前正值关键时期，______覆盖范围刻不容缓，必须抓紧抓实抓出成效。唯有如此，才能把好事办好、实事办实。填入画横线处最恰当的是：","options":["延伸","开拓","拓宽","扩大"],"answer":2,"explanation":"「拓宽」与「渠道、门路、视野」搭配；「开拓」指开辟新领域；「扩大」多与「规模、范围」搭配；「延伸」侧重长度延长。故选C。","__sub":"选词填空"},{"id":"yy-14595","module":"yanyu","diff":2,"exam":"国考","prompt":"很多事看起来简单，真要做扎实并不容易。要在______责任担当上下更大功夫，让发展成果更多惠及全体人民。道理虽朴素，真正做到并不容易。填入画横线处最恰当的是：","options":["加强","强化","增强","深化"],"answer":1,"explanation":"「强化」与「意识、思维」搭配，强调使之更牢固；「增强」语义相近但搭配习惯不同；「加强」为通用动词；「深化」指向深处发展。故选B。","__sub":"选词填空"},{"id":"yy-14596","module":"yanyu","diff":2,"exam":"省考","prompt":"任何工作要见成效，都离不开科学的方法和踏实的作风。实践证明，______教育资源配置是推动高质量发展的关键一招。唯有如此，才能把好事办好、实事办实。填入画横线处最恰当的是：","options":["下坠","下探","下潜","下沉"],"answer":3,"explanation":"「下沉」指治理资源向基层倾斜，是规范表述；「下潜」指潜水，「下探」多指价格或行动试探，「下坠」指物体坠落。故选D。","__sub":"选词填空"},{"id":"yy-14597","module":"yanyu","diff":2,"exam":"省考","prompt":"一个朴素的道理反复被验证：方向对了，努力才不会白费。越是任务艰巨，越要______人才结构，确保方向不偏、力度不减。这也正是成事的关键所在。填入画横线处最恰当的是：","options":["改进","调整","改善","优化"],"answer":3,"explanation":"「优化」指加以改变使其优良，与「环境、结构」搭配规范；「改善」多与「条件、生活」搭配；「改进」多与「方法、工作」搭配；「调整」不含变优之义。故选D。","__sub":"选词填空"},{"id":"yy-14598","module":"yanyu","diff":2,"exam":"省考","prompt":"干事创业，思路和坚持缺一不可。要在______市场主体活力上下更大功夫，让发展成果更多惠及全体人民。其中的道理值得每个人细细体会。填入画横线处最恰当的是：","options":["点燃","引发","调动","激发"],"answer":3,"explanation":"「激发」与「活力、热情、潜能」为固定搭配；「引发」多与「关注、争议」搭配；「点燃」为比喻用法；「调动」多与「积极性」搭配。故选D。","__sub":"选词填空"},{"id":"yy-14599","module":"yanyu","diff":3,"exam":"国考","prompt":"任何工作要见成效，都离不开科学的方法和踏实的作风。实践证明，______乡村发展内生动力是推动高质量发展的关键一招。唯有如此，才能把好事办好、实事办实。填入画横线处最恰当的是：","options":["启动","驱动","激活","唤醒"],"answer":2,"explanation":"「激活」指刺激使之活跃，与「动力、要素」搭配；「唤醒」指使之觉醒；「启动」指开始进行；「驱动」指推动运转。故选C。","__sub":"选词填空"},{"id":"yy-14600","module":"yanyu","diff":3,"exam":"省考","prompt":"一个朴素的道理反复被验证：方向对了，努力才不会白费。各地区各部门要拿出真招实招，______腐败蔓延的态势，确保各项部署落地生根。这也正是成事的关键所在。填入画横线处最恰当的是：","options":["控制","遏止","制止","遏制"],"answer":3,"explanation":"「遏制」强调压制住势头、多与「势头/态势」搭配；「遏止」侧重使之停止，多用于具体行为；「控制」「制止」语义宽泛。故选D。","__sub":"选词填空"},{"id":"yy-14601","module":"yanyu","diff":1,"exam":"国考","prompt":"事物的发展自有其规律，顺应它才能事半功倍。越是任务艰巨，越要______监管责任，确保方向不偏、力度不减。这样的要求，放在哪里都不过时。填入画横线处最恰当的是：","options":["强化","压实","落实","压紧"],"answer":1,"explanation":"「压实」与「责任」搭配，强调责任层层落实到位；「落实」为通用动词；「压紧」常作「压紧压实」；「强化」不如「压实」精准体现层级传导。故选B。","__sub":"选词填空"},{"id":"yy-14602","module":"yanyu","diff":1,"exam":"事业编","prompt":"各级政府要持续______新型农业经营主体，不断增强群众的获得感、幸福感、安全感。填入画横线处最恰当的是：","options":["培育","培养","培植","孕育"],"answer":0,"explanation":"「培育」与「产业、企业、市场」搭配；「培养」对象为人或能力；「培植」多用于动植物或含贬义；「孕育」强调正在形成。故选A。","__sub":"选词填空"},{"id":"yy-14603","module":"yanyu","diff":1,"exam":"国考","prompt":"干事创业，思路和坚持缺一不可。下一步，将______企业主体责任，推动各项工作再上新台阶。其中的道理值得每个人细细体会。填入画横线处最恰当的是：","options":["强化","压紧","压实","落实"],"answer":2,"explanation":"「压实」与「责任」搭配，强调责任层层落实到位；「落实」为通用动词；「压紧」常作「压紧压实」；「强化」不如「压实」精准体现层级传导。故选C。","__sub":"选词填空"},{"id":"yy-14604","module":"yanyu","diff":2,"exam":"教师编","prompt":"很多事看起来简单，真要做扎实并不容易。各地区各部门要拿出真招实招，______民生短板，确保各项部署落地生根。道理虽朴素，真正做到并不容易。填入画横线处最恰当的是：","options":["补足","补齐","填补","弥补"],"answer":1,"explanation":"「补齐」与「短板」为固定搭配，强调使达到应有水平；「补足」多与「差额」搭配；「填补」多与「空白」搭配；「弥补」多与「损失」搭配。故选B。","__sub":"选词填空"},{"id":"yy-14605","module":"yanyu","diff":2,"exam":"国考","prompt":"无论时代如何变化，把事情做实做细始终是成事的基础。要在______生产生活生态上下更大功夫，让发展成果更多惠及全体人民。这背后考验的正是把握分寸的智慧。填入画横线处最恰当的是：","options":["统筹","兼顾","统率","协调"],"answer":0,"explanation":"「统筹」指全面筹划、统一安排，与「推进」搭配且强调全局性；「统率」指率领；「兼顾」只强调同时照顾；「协调」侧重配合关系。故选A。","__sub":"选词填空"},{"id":"yy-14606","module":"yanyu","diff":2,"exam":"教师编","prompt":"很多事看起来简单，真要做扎实并不容易。新征程上，要继续______就业门路，以实干实绩回应人民期盼。道理虽朴素，真正做到并不容易。填入画横线处最恰当的是：","options":["拓宽","开拓","扩大","延伸"],"answer":0,"explanation":"「拓宽」与「渠道、门路、视野」搭配；「开拓」指开辟新领域；「扩大」多与「规模、范围」搭配；「延伸」侧重长度延长。故选A。","__sub":"选词填空"},{"id":"yy-14607","module":"yanyu","diff":2,"exam":"国考","prompt":"很多事看起来简单，真要做扎实并不容易。要坚持问题导向，______思想防线，切实解决群众急难愁盼问题。道理虽朴素，真正做到并不容易。填入画横线处最恰当的是：","options":["构建","筑牢","夯实","筑造"],"answer":1,"explanation":"「筑牢」与「防线」为固定搭配，强调使牢固；「筑造」指建造实体；「构建」侧重搭建体系；「夯实」多与「基础」搭配。故选B。","__sub":"选词填空"},{"id":"yy-14608","module":"yanyu","diff":2,"exam":"事业编","prompt":"干事创业，思路和坚持缺一不可。要在______发展优势上下更大功夫，让发展成果更多惠及全体人民。其中的道理值得每个人细细体会。填入画横线处最恰当的是：","options":["筑牢","加深","厚植","培植"],"answer":2,"explanation":"「厚植」指深厚培育，与「优势、底色、根基」搭配；「培植」多用于培育动植物或扶植势力；「加深」与「底色」搭配不当。故选C。","__sub":"选词填空"},{"id":"yy-14609","module":"yanyu","diff":3,"exam":"医疗编","prompt":"一个朴素的道理反复被验证：方向对了，努力才不会白费。要在______安全屏障上下更大功夫，让发展成果更多惠及全体人民。这也正是成事的关键所在。填入画横线处最恰当的是：","options":["筑造","筑牢","构建","夯实"],"answer":1,"explanation":"「筑牢」与「防线」为固定搭配，强调使牢固；「筑造」指建造实体；「构建」侧重搭建体系；「夯实」多与「基础」搭配。故选B。","__sub":"选词填空"},{"id":"yy-14610","module":"yanyu","diff":3,"exam":"医疗编","prompt":"很多事看起来简单，真要做扎实并不容易。只有沉睡的资源要素真正______到基层，才能让政策在「最后一公里」落地见效。道理虽朴素，真正做到并不容易。填入画横线处最恰当的是：","options":["激活","驱动","启动","唤醒"],"answer":0,"explanation":"「激活」指刺激使之活跃，与「动力、要素」搭配；「唤醒」指使之觉醒；「启动」指开始进行；「驱动」指推动运转。故选A。","__sub":"选词填空"},{"id":"yy-14612","module":"yanyu","diff":1,"exam":"事业编","prompt":"各级政府要持续______现代化建设全局，不断增强群众的获得感、幸福感、安全感。填入画横线处最恰当的是：","options":["贯穿","经过","穿过","贯串"],"answer":0,"explanation":"「贯穿」指从头到尾通贯，与「全过程」搭配规范；「穿过」「经过」仅指空间或时间经过，不含通贯始终之义。故选A。","__sub":"选词填空"},{"id":"yy-14613","module":"yanyu","diff":1,"exam":"国考","prompt":"无论时代如何变化，把事情做实做细始终是成事的基础。越是任务艰巨，越要______资源配置，确保方向不偏、力度不减。这背后考验的正是把握分寸的智慧。填入画横线处最恰当的是：","options":["改进","改善","优化","调整"],"answer":2,"explanation":"「优化」指加以改变使其优良，与「环境、结构」搭配规范；「改善」多与「条件、生活」搭配；「改进」多与「方法、工作」搭配；「调整」不含变优之义。故选C。","__sub":"选词填空"},{"id":"yy-14614","module":"yanyu","diff":2,"exam":"事业编","prompt":"当前正值关键时期，______不发生系统性风险的底线刻不容缓，必须抓紧抓实抓出成效。填入画横线处最恰当的是：","options":["防住","守牢","守住","把牢"],"answer":1,"explanation":"「守牢」与「底线」搭配，强调牢牢守住；「守住」程度稍弱；「把牢」多与「关口」搭配；「防住」为口语。故选B。","__sub":"选词填空"},{"id":"yy-14615","module":"yanyu","diff":2,"exam":"省考","prompt":"干事创业，思路和坚持缺一不可。各级政府要持续______乡村振兴，不断增强群众的获得感、幸福感、安全感。其中的道理值得每个人细细体会。填入画横线处最恰当的是：","options":["赋能","助力","加持","赋权"],"answer":0,"explanation":"「赋能」指赋予能力，是数字经济语境的规范表述；「赋权」指赋予权力；「加持」为口语化外来词；「助力」语义宽泛。故选A。","__sub":"选词填空"},{"id":"yy-14616","module":"yanyu","diff":2,"exam":"事业编","prompt":"事物的发展自有其规律，顺应它才能事半功倍。越是任务艰巨，越要______能源结构，确保方向不偏、力度不减。这样的要求，放在哪里都不过时。填入画横线处最恰当的是：","options":["优化","调整","改善","改进"],"answer":0,"explanation":"「优化」指加以改变使其优良，与「环境、结构」搭配规范；「改善」多与「条件、生活」搭配；「改进」多与「方法、工作」搭配；「调整」不含变优之义。故选A。","__sub":"选词填空"},{"id":"yy-14617","module":"yanyu","diff":2,"exam":"教师编","prompt":"各地区各部门要拿出真招实招，______不发生系统性风险的底线，确保各项部署落地生根。填入画横线处最恰当的是：","options":["守牢","守住","防住","把牢"],"answer":0,"explanation":"「守牢」与「底线」搭配，强调牢牢守住；「守住」程度稍弱；「把牢」多与「关口」搭配；「防住」为口语。故选A。","__sub":"选词填空"},{"id":"yy-14618","module":"yanyu","diff":2,"exam":"国考","prompt":"观察身边的事不难发现，成败的分野常常藏在细节里。各地区各部门要拿出真招实招，______城乡发展布局，确保各项部署落地生根。说到底，拼的是态度，比的是功夫。填入画横线处最恰当的是：","options":["兼顾","协调","统筹","统率"],"answer":2,"explanation":"「统筹」指全面筹划、统一安排，与「推进」搭配且强调全局性；「统率」指率领；「兼顾」只强调同时照顾；「协调」侧重配合关系。故选C。","__sub":"选词填空"},{"id":"yy-14619","module":"yanyu","diff":3,"exam":"国考","prompt":"各级政府要持续______区域协调发展的新格局，不断增强群众的获得感、幸福感、安全感。填入画横线处最恰当的是：","options":["描绘","擘画","勾画","规划"],"answer":1,"explanation":"「擘画」指筹划布置，多用于宏观蓝图，书面色彩浓；「描绘」「勾画」偏具体画面；「规划」语体色彩不足。故选B。","__sub":"选词填空"},{"id":"yy-14621","module":"yanyu","diff":1,"exam":"医疗编","prompt":"很多事看起来简单，真要做扎实并不容易。当前正值关键时期，______消费新增长点刻不容缓，必须抓紧抓实抓出成效。道理虽朴素，真正做到并不容易。填入画横线处最恰当的是：","options":["培育","培植","培养","孕育"],"answer":0,"explanation":"「培育」与「产业、企业、市场」搭配；「培养」对象为人或能力；「培植」多用于动植物或含贬义；「孕育」强调正在形成。故选A。","__sub":"选词填空"},{"id":"yy-14622","module":"yanyu","diff":1,"exam":"省考","prompt":"干事创业，思路和坚持缺一不可。要在______民意反映渠道上下更大功夫，让发展成果更多惠及全体人民。其中的道理值得每个人细细体会。填入画横线处最恰当的是：","options":["开拓","延伸","扩大","拓宽"],"answer":3,"explanation":"「拓宽」与「渠道、门路、视野」搭配；「开拓」指开辟新领域；「扩大」多与「规模、范围」搭配；「延伸」侧重长度延长。故选D。","__sub":"选词填空"},{"id":"yy-14625","module":"yanyu","diff":2,"exam":"国考","prompt":"干事创业，思路和坚持缺一不可。只有本领真正______到基层，才能让政策在「最后一公里」落地见效。其中的道理值得每个人细细体会。填入画横线处最恰当的是：","options":["砥砺","锤炼","锻炼","磨砺"],"answer":0,"explanation":"「砥砺」本义为磨刀石，引申为磨炼，与「意志」搭配且语体庄重；「磨砺」与之近义但「砥砺」更常用于「砥砺前行、砥砺意志」。故选A。","__sub":"选词填空"},{"id":"yy-14626","module":"yanyu","diff":2,"exam":"事业编","prompt":"一个朴素的道理反复被验证：方向对了，努力才不会白费。下一步，将______爱国情怀，推动各项工作再上新台阶。这也正是成事的关键所在。填入画横线处最恰当的是：","options":["筑牢","培植","加深","厚植"],"answer":3,"explanation":"「厚植」指深厚培育，与「优势、底色、根基」搭配；「培植」多用于培育动植物或扶植势力；「加深」与「底色」搭配不当。故选D。","__sub":"选词填空"},{"id":"yy-14627","module":"yanyu","diff":2,"exam":"国考","prompt":"观察身边的事不难发现，成败的分野常常藏在细节里。各地区各部门要拿出真招实招，______视野和思路，确保各项部署落地生根。说到底，拼的是态度，比的是功夫。填入画横线处最恰当的是：","options":["扩大","延伸","拓宽","开拓"],"answer":2,"explanation":"「拓宽」与「渠道、门路、视野」搭配；「开拓」指开辟新领域；「扩大」多与「规模、范围」搭配；「延伸」侧重长度延长。故选C。","__sub":"选词填空"},{"id":"yy-14628","module":"yanyu","diff":2,"exam":"医疗编","prompt":"事物的发展自有其规律，顺应它才能事半功倍。新征程上，要继续______安全稳定底线，以实干实绩回应人民期盼。这样的要求，放在哪里都不过时。填入画横线处最恰当的是：","options":["守牢","把牢","守住","防住"],"answer":0,"explanation":"「守牢」与「底线」搭配，强调牢牢守住；「守住」程度稍弱；「把牢」多与「关口」搭配；「防住」为口语。故选A。","__sub":"选词填空"},{"id":"yy-14629","module":"yanyu","diff":3,"exam":"事业编","prompt":"干事创业，思路和坚持缺一不可。当前正值关键时期，______矛盾调解体系刻不容缓，必须抓紧抓实抓出成效。其中的道理值得每个人细细体会。填入画横线处最恰当的是：","options":["构建","搭建","健全","完善"],"answer":2,"explanation":"「健全」强调使完备无缺；「完善」指补足短板；「构建」「搭建」侧重从无到有搭建。故选C。","__sub":"选词填空"},{"id":"yy-14630","module":"yanyu","diff":3,"exam":"省考","prompt":"任何工作要见成效，都离不开科学的方法和踏实的作风。只有制度堤坝真正______到基层，才能让政策在「最后一公里」落地见效。唯有如此，才能把好事办好、实事办实。填入画横线处最恰当的是：","options":["筑造","筑牢","构建","夯实"],"answer":1,"explanation":"「筑牢」与「防线」为固定搭配，强调使牢固；「筑造」指建造实体；「构建」侧重搭建体系；「夯实」多与「基础」搭配。故选B。","__sub":"选词填空"},{"id":"yy-14631","module":"yanyu","diff":1,"exam":"省考","prompt":"事物的发展自有其规律，顺应它才能事半功倍。要坚持问题导向，______意志，切实解决群众急难愁盼问题。这样的要求，放在哪里都不过时。填入画横线处最恰当的是：","options":["砥砺","锻炼","锤炼","磨砺"],"answer":0,"explanation":"「砥砺」本义为磨刀石，引申为磨炼，与「意志」搭配且语体庄重；「磨砺」与之近义但「砥砺」更常用于「砥砺前行、砥砺意志」。故选A。","__sub":"选词填空"},{"id":"yy-14632","module":"yanyu","diff":1,"exam":"国考","prompt":"无论时代如何变化，把事情做实做细始终是成事的基础。要坚持问题导向，______改革任务书，切实解决群众急难愁盼问题。这背后考验的正是把握分寸的智慧。填入画横线处最恰当的是：","options":["锁定","锚定","盯住","瞄准"],"answer":1,"explanation":"「锚定」比喻像锚一样固定住目标，多用于宏观战略语境；「锁定」「瞄准」「盯住」语体偏口语，庄重色彩不足。故选B。","__sub":"选词填空"},{"id":"yy-14633","module":"yanyu","diff":1,"exam":"省考","prompt":"现实中，方法与态度不同，结果往往截然不同。新征程上，要继续______就业服务体系，以实干实绩回应人民期盼。看似寻常，实则是长期积累的结果。填入画横线处最恰当的是：","options":["完善","健全","建立","构建"],"answer":1,"explanation":"「健全」强调使完备无缺，与「体系」搭配规范；「建立」指从无到有，「完善」指补足短板，「构建」侧重搭建框架。故选B。","__sub":"选词填空"},{"id":"yy-14634","module":"yanyu","diff":2,"exam":"国考","prompt":"观察身边的事不难发现，成败的分野常常藏在细节里。要在______志愿服务体系上下更大功夫，让发展成果更多惠及全体人民。说到底，拼的是态度，比的是功夫。填入画横线处最恰当的是：","options":["构建","健全","完善","搭建"],"answer":1,"explanation":"「健全」强调使完备无缺；「完善」指补足短板；「构建」「搭建」侧重从无到有搭建。故选B。","__sub":"选词填空"},{"id":"yy-14635","module":"yanyu","diff":2,"exam":"医疗编","prompt":"任何工作要见成效，都离不开科学的方法和踏实的作风。各级政府要持续______区域协作机制，不断增强群众的获得感、幸福感、安全感。唯有如此，才能把好事办好、实事办实。填入画横线处最恰当的是：","options":["推进","深入","深化","加强"],"answer":2,"explanation":"「深化」指向更深阶段发展，与「改革」为固定搭配；「深入」多作形容词或「深入调查」；「加强」「推进」语义宽泛。故选C。","__sub":"选词填空"},{"id":"yy-14636","module":"yanyu","diff":2,"exam":"国考","prompt":"观察身边的事不难发现，成败的分野常常藏在细节里。新征程上，要继续______城市功能品质，以实干实绩回应人民期盼。说到底，拼的是态度，比的是功夫。填入画横线处最恰当的是：","options":["提高","增强","拔高","提升"],"answer":3,"explanation":"「提升」与「效能、水平」搭配规范；「提高」语义相近但「提升」更书面；「增强」多与「能力、意识」搭配；「拔高」含贬义。故选D。","__sub":"选词填空"},{"id":"yy-14637","module":"yanyu","diff":2,"exam":"省考","prompt":"事物的发展自有其规律，顺应它才能事半功倍。当前正值关键时期，______文明乡风刻不容缓，必须抓紧抓实抓出成效。这样的要求，放在哪里都不过时。填入画横线处最恰当的是：","options":["涵养","养护","营造","培养"],"answer":0,"explanation":"「涵养」指蓄积并养护，与「生态、水源」搭配；「培养」对象为人或能力；「营造」多与「氛围、环境」搭配；「养护」不含培育之义。故选A。","__sub":"选词填空"},{"id":"yy-14638","module":"yanyu","diff":2,"exam":"国考","prompt":"很多事看起来简单，真要做扎实并不容易。越是任务艰巨，越要______公共服务体系，确保方向不偏、力度不减。道理虽朴素，真正做到并不容易。填入画横线处最恰当的是：","options":["建立","健全","完善","构建"],"answer":1,"explanation":"「健全」强调使完备无缺，与「体系」搭配规范；「建立」指从无到有，「完善」指补足短板，「构建」侧重搭建框架。故选B。","__sub":"选词填空"},{"id":"yy-14640","module":"yanyu","diff":3,"exam":"省考","prompt":"干事创业，思路和坚持缺一不可。实践证明，______公共服务是推动高质量发展的关键一招。看似寻常，实则是长期积累的结果。填入画横线处最恰当的是：","options":["下坠","下沉","下探","下潜"],"answer":1,"explanation":"「下沉」指治理资源向基层倾斜，是规范表述；「下潜」指潜水，「下探」多指价格或行动试探，「下坠」指物体坠落。故选B。","__sub":"选词填空"},{"id":"yy-14641","module":"yanyu","diff":1,"exam":"省考","prompt":"观察身边的事不难发现，成败的分野常常藏在细节里。面对新形势新任务，必须______人才结构，牢牢把握发展主动权。说到底，拼的是态度，比的是功夫。填入画横线处最恰当的是：","options":["改进","优化","改善","调整"],"answer":1,"explanation":"「优化」指加以改变使其优良，与「环境、结构」搭配规范；「改善」多与「条件、生活」搭配；「改进」多与「方法、工作」搭配；「调整」不含变优之义。故选B。","__sub":"选词填空"},{"id":"yy-14644","module":"yanyu","diff":2,"exam":"事业编","prompt":"现实中，方法与态度不同，结果往往截然不同。越是任务艰巨，越要______基层治理神经末梢，确保方向不偏、力度不减。看似寻常，实则是长期积累的结果。填入画横线处最恰当的是：","options":["激活","唤醒","启动","驱动"],"answer":0,"explanation":"「激活」指刺激使之活跃，与「动力、要素」搭配；「唤醒」指使之觉醒；「启动」指开始进行；「驱动」指推动运转。故选A。","__sub":"选词填空"},{"id":"yy-14645","module":"yanyu","diff":2,"exam":"教师编","prompt":"现实中，方法与态度不同，结果往往截然不同。实践证明，______改革开放各领域是推动高质量发展的关键一招。看似寻常，实则是长期积累的结果。填入画横线处最恰当的是：","options":["贯串","贯穿","经过","穿过"],"answer":1,"explanation":"「贯穿」指从头到尾通贯，与「全过程」搭配规范；「穿过」「经过」仅指空间或时间经过，不含通贯始终之义。故选B。","__sub":"选词填空"},{"id":"yy-14646","module":"yanyu","diff":2,"exam":"省考","prompt":"只有现代化建设的宏伟篇章真正______到基层，才能让政策在「最后一公里」落地见效。填入画横线处最恰当的是：","options":["勾画","描绘","擘画","规划"],"answer":2,"explanation":"「擘画」指筹划布置，多用于宏观蓝图，书面色彩浓；「描绘」「勾画」偏具体画面；「规划」语体色彩不足。故选C。","__sub":"选词填空"},{"id":"yy-14647","module":"yanyu","diff":2,"exam":"医疗编","prompt":"观察身边的事不难发现，成败的分野常常藏在细节里。面对新形势新任务，必须______智慧和力量，牢牢把握发展主动权。说到底，拼的是态度，比的是功夫。填入画横线处最恰当的是：","options":["凝聚","集中","汇聚","聚集"],"answer":0,"explanation":"「凝聚」多与「共识、人心、力量」搭配，强调由分散到统一；「聚集」侧重物理集合；「集中」侧重把分散的集中起来。故选A。","__sub":"选词填空"},{"id":"yy-14648","module":"yanyu","diff":2,"exam":"省考","prompt":"现实中，方法与态度不同，结果往往截然不同。各级政府要持续______政企沟通机制，不断增强群众的获得感、幸福感、安全感。看似寻常，实则是长期积累的结果。填入画横线处最恰当的是：","options":["开拓","打通","畅通","疏通"],"answer":2,"explanation":"「畅通」强调使通畅无阻，与「渠道」为固定搭配；「打通」侧重突破障碍；「疏通」多用于管道或疏导矛盾；「开拓」指开辟新领域。故选C。","__sub":"选词填空"},{"id":"yy-14649","module":"yanyu","diff":3,"exam":"国考","prompt":"事物的发展自有其规律，顺应它才能事半功倍。实践证明，______风险意识是推动高质量发展的关键一招。这样的要求，放在哪里都不过时。填入画横线处最恰当的是：","options":["加强","深化","强化","增强"],"answer":2,"explanation":"「强化」与「意识、思维」搭配，强调使之更牢固；「增强」语义相近但搭配习惯不同；「加强」为通用动词；「深化」指向深处发展。故选C。","__sub":"选词填空"},{"id":"yy-14650","module":"yanyu","diff":3,"exam":"省考","prompt":"观察身边的事不难发现，成败的分野常常藏在细节里。当前正值关键时期，______发展优势刻不容缓，必须抓紧抓实抓出成效。说到底，拼的是态度，比的是功夫。填入画横线处最恰当的是：","options":["培植","筑牢","加深","厚植"],"answer":3,"explanation":"「厚植」指深厚培育，与「优势、底色、根基」搭配；「培植」多用于培育动植物或扶植势力；「加深」与「底色」搭配不当。故选D。","__sub":"选词填空"},{"id":"yy-14651","module":"yanyu","diff":1,"exam":"国考","prompt":"现实中，方法与态度不同，结果往往截然不同。只有经营主体信心真正______到基层，才能让政策在「最后一公里」落地见效。看似寻常，实则是长期积累的结果。填入画横线处最恰当的是：","options":["激发","点燃","调动","引发"],"answer":0,"explanation":"「激发」与「活力、热情、潜能」为固定搭配；「引发」多与「关注、争议」搭配；「点燃」为比喻用法；「调动」多与「积极性」搭配。故选A。","__sub":"选词填空"},{"id":"yy-14652","module":"yanyu","diff":1,"exam":"省考","prompt":"事物的发展自有其规律，顺应它才能事半功倍。只有智慧和力量真正______到基层，才能让政策在「最后一公里」落地见效。这样的要求，放在哪里都不过时。填入画横线处最恰当的是：","options":["集中","聚集","汇聚","凝聚"],"answer":3,"explanation":"「凝聚」多与「共识、人心、力量」搭配，强调由分散到统一；「聚集」侧重物理集合；「集中」侧重把分散的集中起来。故选D。","__sub":"选词填空"},{"id":"yy-14653","module":"yanyu","diff":1,"exam":"国考","prompt":"一个朴素的道理反复被验证：方向对了，努力才不会白费。越是任务艰巨，越要______基层治理效能，确保方向不偏、力度不减。这也正是成事的关键所在。填入画横线处最恰当的是：","options":["提升","提高","拔高","增强"],"answer":0,"explanation":"「提升」与「效能、水平」搭配规范；「提高」语义相近但「提升」更书面；「增强」多与「能力、意识」搭配；「拔高」含贬义。故选A。","__sub":"选词填空"},{"id":"yy-14655","module":"yanyu","diff":2,"exam":"国考","prompt":"事物的发展自有其规律，顺应它才能事半功倍。越是任务艰巨，越要______群众增收渠道，确保方向不偏、力度不减。这样的要求，放在哪里都不过时。填入画横线处最恰当的是：","options":["扩大","开拓","延伸","拓宽"],"answer":3,"explanation":"「拓宽」与「渠道、门路、视野」搭配；「开拓」指开辟新领域；「扩大」多与「规模、范围」搭配；「延伸」侧重长度延长。故选D。","__sub":"选词填空"},{"id":"yy-14656","module":"yanyu","diff":2,"exam":"医疗编","prompt":"任何工作要见成效，都离不开科学的方法和踏实的作风。新征程上，要继续______腐败蔓延的态势，以实干实绩回应人民期盼。唯有如此，才能把好事办好、实事办实。填入画横线处最恰当的是：","options":["遏制","控制","制止","遏止"],"answer":0,"explanation":"「遏制」强调压制住势头、多与「势头/态势」搭配；「遏止」侧重使之停止，多用于具体行为；「控制」「制止」语义宽泛。故选A。","__sub":"选词填空"},{"id":"yy-14658","module":"yanyu","diff":2,"exam":"教师编","prompt":"任何工作要见成效，都离不开科学的方法和踏实的作风。越是任务艰巨，越要______数据要素价值，确保方向不偏、力度不减。唯有如此，才能把好事办好、实事办实。填入画横线处最恰当的是：","options":["爆发","发挥","散发","释放"],"answer":3,"explanation":"「释放」与「潜力、红利、活力」搭配；「散发」指分散发出；「发挥」与「作用」搭配；「爆发」指突然发作。故选D。","__sub":"选词填空"},{"id":"yy-14659","module":"yanyu","diff":3,"exam":"国考","prompt":"现实中，方法与态度不同，结果往往截然不同。实践证明，______全年经济增长目标是推动高质量发展的关键一招。看似寻常，实则是长期积累的结果。填入画横线处最恰当的是：","options":["瞄准","锁定","盯住","锚定"],"answer":3,"explanation":"「锚定」比喻像锚一样固定住目标，多用于宏观战略语境；「锁定」「瞄准」「盯住」语体偏口语，庄重色彩不足。故选D。","__sub":"选词填空"},{"id":"yy-14660","module":"yanyu","diff":3,"exam":"医疗编","prompt":"干事创业，思路和坚持缺一不可。越是任务艰巨，越要______乡村振兴的壮美画卷，确保方向不偏、力度不减。其中的道理值得每个人细细体会。填入画横线处最恰当的是：","options":["擘画","勾画","规划","描绘"],"answer":0,"explanation":"「擘画」指筹划布置，多用于宏观蓝图，书面色彩浓；「描绘」「勾画」偏具体画面；「规划」语体色彩不足。故选A。","__sub":"选词填空"},{"id":"yy-14661","module":"yanyu","diff":1,"exam":"国考","prompt":"观察身边的事不难发现，成败的分野常常藏在细节里。要坚持问题导向，______发展规律，切实解决群众急难愁盼问题。说到底，拼的是态度，比的是功夫。填入画横线处最恰当的是：","options":["把守","把持","把握","把玩"],"answer":2,"explanation":"「把握」与抽象事物（特点、规律、机遇）搭配；「把守」指守卫关口，「把持」含贬义指独揽，「把玩」指赏玩物品。故选C。","__sub":"选词填空"},{"id":"yy-14662","module":"yanyu","diff":1,"exam":"教师编","prompt":"任何工作要见成效，都离不开科学的方法和踏实的作风。要在______安全底线上下更大功夫，让发展成果更多惠及全体人民。唯有如此，才能把好事办好、实事办实。填入画横线处最恰当的是：","options":["筑牢","筑造","夯实","构建"],"answer":0,"explanation":"「筑牢」与「防线」为固定搭配，强调使牢固；「筑造」指建造实体；「构建」侧重搭建体系；「夯实」多与「基础」搭配。故选A。","__sub":"选词填空"},{"id":"yy-14664","module":"yanyu","diff":2,"exam":"事业编","prompt":"一个朴素的道理反复被验证：方向对了，努力才不会白费。实践证明，______内生动力是推动高质量发展的关键一招。这也正是成事的关键所在。填入画横线处最恰当的是：","options":["点燃","激发","引发","调动"],"answer":1,"explanation":"「激发」与「活力、热情、潜能」为固定搭配；「引发」多与「关注、争议」搭配；「点燃」为比喻用法；「调动」多与「积极性」搭配。故选B。","__sub":"选词填空"},{"id":"yy-14665","module":"yanyu","diff":2,"exam":"医疗编","prompt":"事物的发展自有其规律，顺应它才能事半功倍。回顾这些年走过的路，______食品安全监管始终是我们攻坚克难的重要法宝。这样的要求，放在哪里都不过时。填入画横线处最恰当的是：","options":["增强","加强","深化","强化"],"answer":3,"explanation":"「强化」与「意识、思维」搭配，强调使之更牢固；「增强」语义相近但搭配习惯不同；「加强」为通用动词；「深化」指向深处发展。故选D。","__sub":"选词填空"},{"id":"yy-14666","module":"yanyu","diff":2,"exam":"国考","prompt":"回顾这些年走过的路，______高质量发展的生态底色始终是我们攻坚克难的重要法宝。填入画横线处最恰当的是：","options":["加深","厚植","培植","筑牢"],"answer":1,"explanation":"「厚植」指深厚培育，与「优势、底色、根基」搭配；「培植」多用于培育动植物或扶植势力；「加深」与「底色」搭配不当。故选B。","__sub":"选词填空"},{"id":"yy-14667","module":"yanyu","diff":2,"exam":"事业编","prompt":"无论时代如何变化，把事情做实做细始终是成事的基础。要在______优质医疗资源上下更大功夫，让发展成果更多惠及全体人民。这背后考验的正是把握分寸的智慧。填入画横线处最恰当的是：","options":["下潜","下沉","下坠","下探"],"answer":1,"explanation":"「下沉」指治理资源向基层倾斜，是规范表述；「下潜」指潜水，「下探」多指价格或行动试探，「下坠」指物体坠落。故选B。","__sub":"选词填空"},{"id":"yy-14668","module":"yanyu","diff":2,"exam":"国考","prompt":"事物的发展自有其规律，顺应它才能事半功倍。越是任务艰巨，越要______科技成果转化通道，确保方向不偏、力度不减。这样的要求，放在哪里都不过时。填入画横线处最恰当的是：","options":["畅通","开辟","打通","贯通"],"answer":0,"explanation":"「畅通」强调使通畅无阻，与「渠道、通道」搭配；「打通」侧重突破障碍；「贯通」指连接相通；「开辟」指新开路径。故选A。","__sub":"选词填空"},{"id":"yy-14669","module":"yanyu","diff":3,"exam":"事业编","prompt":"干事创业，思路和坚持缺一不可。实践证明，______新型农业经营主体是推动高质量发展的关键一招。其中的道理值得每个人细细体会。填入画横线处最恰当的是：","options":["培植","培养","孕育","培育"],"answer":3,"explanation":"「培育」与「产业、企业、市场」搭配；「培养」对象为人或能力；「培植」多用于动植物或含贬义；「孕育」强调正在形成。故选D。","__sub":"选词填空"},{"id":"yy-14670","module":"yanyu","diff":3,"exam":"省考","prompt":"无论时代如何变化，把事情做实做细始终是成事的基础。实践证明，______资源、服务、管理是推动高质量发展的关键一招。这背后考验的正是把握分寸的智慧。填入画横线处最恰当的是：","options":["下沉","下坠","下探","下潜"],"answer":0,"explanation":"「下沉」指治理资源向基层倾斜，是规范表述；「下潜」指潜水，「下探」多指价格或行动试探，「下坠」指物体坠落。故选A。","__sub":"选词填空"},{"id":"yy-14671","module":"yanyu","diff":1,"exam":"教师编","prompt":"一个朴素的道理反复被验证：方向对了，努力才不会白费。新征程上，要继续______人才流动渠道，以实干实绩回应人民期盼。这也正是成事的关键所在。填入画横线处最恰当的是：","options":["开拓","疏通","畅通","打通"],"answer":2,"explanation":"「畅通」强调使通畅无阻，与「渠道」为固定搭配；「打通」侧重突破障碍；「疏通」多用于管道或疏导矛盾；「开拓」指开辟新领域。故选C。","__sub":"选词填空"},{"id":"yy-14672","module":"yanyu","diff":1,"exam":"省考","prompt":"一个朴素的道理反复被验证：方向对了，努力才不会白费。要坚持问题导向，______房价过快上涨的势头，切实解决群众急难愁盼问题。这也正是成事的关键所在。填入画横线处最恰当的是：","options":["遏制","控制","制止","遏止"],"answer":0,"explanation":"「遏制」强调压制住势头、多与「势头/态势」搭配；「遏止」侧重使之停止，多用于具体行为；「控制」「制止」语义宽泛。故选A。","__sub":"选词填空"},{"id":"yy-14673","module":"yanyu","diff":1,"exam":"省考","prompt":"干事创业，思路和坚持缺一不可。要在______城乡发展布局上下更大功夫，让发展成果更多惠及全体人民。其中的道理值得每个人细细体会。填入画横线处最恰当的是：","options":["协调","兼顾","统率","统筹"],"answer":3,"explanation":"「统筹」指全面筹划、统一安排，与「推进」搭配且强调全局性；「统率」指率领；「兼顾」只强调同时照顾；「协调」侧重配合关系。故选D。","__sub":"选词填空"},{"id":"yy-14674","module":"yanyu","diff":2,"exam":"国考","prompt":"很多事看起来简单，真要做扎实并不容易。各地区各部门要拿出真招实招，______制度漏洞，确保各项部署落地生根。道理虽朴素，真正做到并不容易。填入画横线处最恰当的是：","options":["补齐","弥补","填补","补足"],"answer":0,"explanation":"「补齐」与「短板」为固定搭配，强调使达到应有水平；「补足」多与「差额」搭配；「填补」多与「空白」搭配；「弥补」多与「损失」搭配。故选A。","__sub":"选词填空"},{"id":"yy-14675","module":"yanyu","diff":2,"exam":"国考","prompt":"现实中，方法与态度不同，结果往往截然不同。下一步，将______新型农业经营主体，推动各项工作再上新台阶。看似寻常，实则是长期积累的结果。填入画横线处最恰当的是：","options":["孕育","培育","培养","培植"],"answer":1,"explanation":"「培育」与「产业、企业、市场」搭配；「培养」对象为人或能力；「培植」多用于动植物或含贬义；「孕育」强调正在形成。故选B。","__sub":"选词填空"},{"id":"yy-14676","module":"yanyu","diff":2,"exam":"国考","prompt":"现实中，方法与态度不同，结果往往截然不同。越是任务艰巨，越要______安全生产责任，确保方向不偏、力度不减。看似寻常，实则是长期积累的结果。填入画横线处最恰当的是：","options":["压紧","压实","落实","强化"],"answer":1,"explanation":"「压实」与「责任」搭配，强调责任层层落实到位；「落实」为通用动词；「压紧」常作「压紧压实」；「强化」不如「压实」精准体现层级传导。故选B。","__sub":"选词填空"},{"id":"yy-14677","module":"yanyu","diff":2,"exam":"省考","prompt":"现实中，方法与态度不同，结果往往截然不同。新征程上，要继续______各方合力，以实干实绩回应人民期盼。看似寻常，实则是长期积累的结果。填入画横线处最恰当的是：","options":["集中","汇聚","聚集","凝聚"],"answer":3,"explanation":"「凝聚」多与「共识、人心、力量」搭配，强调由分散到统一；「聚集」侧重物理集合；「集中」侧重把分散的集中起来。故选D。","__sub":"选词填空"},{"id":"yy-14678","module":"yanyu","diff":2,"exam":"省考","prompt":"事物的发展自有其规律，顺应它才能事半功倍。越是任务艰巨，越要______覆盖范围，确保方向不偏、力度不减。这样的要求，放在哪里都不过时。填入画横线处最恰当的是：","options":["扩大","拓宽","开拓","延伸"],"answer":1,"explanation":"「拓宽」与「渠道、门路、视野」搭配；「开拓」指开辟新领域；「扩大」多与「规模、范围」搭配；「延伸」侧重长度延长。故选B。","__sub":"选词填空"},{"id":"yy-14679","module":"yanyu","diff":3,"exam":"省考","prompt":"无论时代如何变化，把事情做实做细始终是成事的基础。要坚持问题导向，______乡村振兴始终，切实解决群众急难愁盼问题。这背后考验的正是把握分寸的智慧。填入画横线处最恰当的是：","options":["穿过","经过","贯穿","贯串"],"answer":2,"explanation":"「贯穿」指从头到尾通贯，与「全过程」搭配规范；「穿过」「经过」仅指空间或时间经过，不含通贯始终之义。故选C。","__sub":"选词填空"},{"id":"yy-14680","module":"yanyu","diff":3,"exam":"国考","prompt":"很多事看起来简单，真要做扎实并不容易。各级政府要持续______改革红利，不断增强群众的获得感、幸福感、安全感。道理虽朴素，真正做到并不容易。填入画横线处最恰当的是：","options":["发挥","爆发","散发","释放"],"answer":3,"explanation":"「释放」与「潜力、红利、活力」搭配；「散发」指分散发出；「发挥」与「作用」搭配；「爆发」指突然发作。故选D。","__sub":"选词填空"},{"id":"yy-14681","module":"yanyu","diff":1,"exam":"国考","prompt":"事物的发展自有其规律，顺应它才能事半功倍。只有能源结构真正______到基层，才能让政策在「最后一公里」落地见效。这样的要求，放在哪里都不过时。填入画横线处最恰当的是：","options":["调整","改进","优化","改善"],"answer":2,"explanation":"「优化」指加以改变使其优良，与「环境、结构」搭配规范；「改善」多与「条件、生活」搭配；「改进」多与「方法、工作」搭配；「调整」不含变优之义。故选C。","__sub":"选词填空"},{"id":"yy-14682","module":"yanyu","diff":1,"exam":"国考","prompt":"事物的发展自有其规律，顺应它才能事半功倍。各地区各部门要拿出真招实招，______资源配置，确保各项部署落地生根。这样的要求，放在哪里都不过时。填入画横线处最恰当的是：","options":["改善","优化","改进","调整"],"answer":1,"explanation":"「优化」指加以改变使其优良，与「环境、结构」搭配规范；「改善」多与「条件、生活」搭配；「改进」多与「方法、工作」搭配；「调整」不含变优之义。故选B。","__sub":"选词填空"},{"id":"yy-14685","module":"yanyu","diff":2,"exam":"国考","prompt":"事物的发展自有其规律，顺应它才能事半功倍。只有城乡发展布局真正______到基层，才能让政策在「最后一公里」落地见效。这样的要求，放在哪里都不过时。填入画横线处最恰当的是：","options":["统率","协调","兼顾","统筹"],"answer":3,"explanation":"「统筹」指全面筹划、统一安排，与「推进」搭配且强调全局性；「统率」指率领；「兼顾」只强调同时照顾；「协调」侧重配合关系。故选D。","__sub":"选词填空"},{"id":"yy-14686","module":"yanyu","diff":2,"exam":"事业编","prompt":"干事创业，思路和坚持缺一不可。要坚持问题导向，______廉洁底线，切实解决群众急难愁盼问题。其中的道理值得每个人细细体会。填入画横线处最恰当的是：","options":["筑造","夯实","筑牢","构建"],"answer":2,"explanation":"「筑牢」与「防线」为固定搭配，强调使牢固；「筑造」指建造实体；「构建」侧重搭建体系；「夯实」多与「基础」搭配。故选C。","__sub":"选词填空"},{"id":"yy-14688","module":"yanyu","diff":2,"exam":"国考","prompt":"观察身边的事不难发现，成败的分野常常藏在细节里。新征程上，要继续______矛盾调解体系，以实干实绩回应人民期盼。说到底，拼的是态度，比的是功夫。填入画横线处最恰当的是：","options":["健全","搭建","构建","完善"],"answer":0,"explanation":"「健全」强调使完备无缺；「完善」指补足短板；「构建」「搭建」侧重从无到有搭建。故选A。","__sub":"选词填空"},{"id":"yy-14690","module":"yanyu","diff":3,"exam":"省考","prompt":"很多事看起来简单，真要做扎实并不容易。要在______各方合力上下更大功夫，让发展成果更多惠及全体人民。道理虽朴素，真正做到并不容易。填入画横线处最恰当的是：","options":["凝聚","集中","聚集","汇聚"],"answer":0,"explanation":"「凝聚」多与「共识、人心、力量」搭配，强调由分散到统一；「聚集」侧重物理集合；「集中」侧重把分散的集中起来。故选A。","__sub":"选词填空"},{"id":"yy-14691","module":"yanyu","diff":1,"exam":"省考","prompt":"现实中，方法与态度不同，结果往往截然不同。只有服务空白真正______到基层，才能让政策在「最后一公里」落地见效。看似寻常，实则是长期积累的结果。填入画横线处最恰当的是：","options":["补齐","弥补","补足","填补"],"answer":0,"explanation":"「补齐」与「短板」为固定搭配，强调使达到应有水平；「补足」多与「差额」搭配；「填补」多与「空白」搭配；「弥补」多与「损失」搭配。故选A。","__sub":"选词填空"},{"id":"yy-14693","module":"yanyu","diff":1,"exam":"省考","prompt":"现实中，方法与态度不同，结果往往截然不同。各地区各部门要拿出真招实招，______违规行为的苗头，确保各项部署落地生根。看似寻常，实则是长期积累的结果。填入画横线处最恰当的是：","options":["遏止","遏制","制止","控制"],"answer":1,"explanation":"「遏制」强调压制住势头、多与「势头/态势」搭配；「遏止」侧重使之停止，多用于具体行为；「控制」「制止」语义宽泛。故选B。","__sub":"选词填空"},{"id":"yy-14694","module":"yanyu","diff":2,"exam":"国考","prompt":"无论时代如何变化，把事情做实做细始终是成事的基础。各地区各部门要拿出真招实招，______基础设施弱项，确保各项部署落地生根。这背后考验的正是把握分寸的智慧。填入画横线处最恰当的是：","options":["补足","弥补","填补","补齐"],"answer":3,"explanation":"「补齐」与「短板」为固定搭配，强调使达到应有水平；「补足」多与「差额」搭配；「填补」多与「空白」搭配；「弥补」多与「损失」搭配。故选D。","__sub":"选词填空"},{"id":"yy-14695","module":"yanyu","diff":2,"exam":"事业编","prompt":"无论时代如何变化，把事情做实做细始终是成事的基础。面对新形势新任务，必须______高质量发展的生态底色，牢牢把握发展主动权。这背后考验的正是把握分寸的智慧。填入画横线处最恰当的是：","options":["厚植","培植","筑牢","加深"],"answer":0,"explanation":"「厚植」指深厚培育，与「优势、底色、根基」搭配；「培植」多用于培育动植物或扶植势力；「加深」与「底色」搭配不当。故选A。","__sub":"选词填空"},{"id":"yy-14696","module":"yanyu","diff":2,"exam":"教师编","prompt":"现实中，方法与态度不同，结果往往截然不同。面对新形势新任务，必须______就业门路，牢牢把握发展主动权。看似寻常，实则是长期积累的结果。填入画横线处最恰当的是：","options":["拓宽","开拓","扩大","延伸"],"answer":0,"explanation":"「拓宽」与「渠道、门路、视野」搭配；「开拓」指开辟新领域；「扩大」多与「规模、范围」搭配；「延伸」侧重长度延长。故选A。","__sub":"选词填空"},{"id":"yy-14697","module":"yanyu","diff":2,"exam":"国考","prompt":"现实中，方法与态度不同，结果往往截然不同。当前正值关键时期，______安全底线刻不容缓，必须抓紧抓实抓出成效。看似寻常，实则是长期积累的结果。填入画横线处最恰当的是：","options":["构建","筑牢","夯实","筑造"],"answer":1,"explanation":"「筑牢」与「防线」为固定搭配，强调使牢固；「筑造」指建造实体；「构建」侧重搭建体系；「夯实」多与「基础」搭配。故选B。","__sub":"选词填空"},{"id":"yy-14698","module":"yanyu","diff":2,"exam":"国考","prompt":"事物的发展自有其规律，顺应它才能事半功倍。越是任务艰巨，越要______城市文化气质，确保方向不偏、力度不减。这样的要求，放在哪里都不过时。填入画横线处最恰当的是：","options":["养护","营造","涵养","培养"],"answer":2,"explanation":"「涵养」指蓄积并养护，与「生态、水源」搭配；「培养」对象为人或能力；「营造」多与「氛围、环境」搭配；「养护」不含培育之义。故选C。","__sub":"选词填空"},{"id":"yy-14699","module":"yanyu","diff":3,"exam":"省考","prompt":"现实中，方法与态度不同，结果往往截然不同。要坚持问题导向，______乡村振兴，切实解决群众急难愁盼问题。看似寻常，实则是长期积累的结果。填入画横线处最恰当的是：","options":["助力","加持","赋能","赋权"],"answer":2,"explanation":"「赋能」指赋予能力，是数字经济语境的规范表述；「赋权」指赋予权力；「加持」为口语化外来词；「助力」语义宽泛。故选C。","__sub":"选词填空"},{"id":"yy-14701","module":"yanyu","diff":1,"exam":"国考","prompt":"一个朴素的道理反复被验证：方向对了，努力才不会白费。实践证明，______民生短板是推动高质量发展的关键一招。这也正是成事的关键所在。填入画横线处最恰当的是：","options":["填补","弥补","补足","补齐"],"answer":3,"explanation":"「补齐」与「短板」为固定搭配，强调使达到应有水平；「补足」多与「差额」搭配；「填补」多与「空白」搭配；「弥补」多与「损失」搭配。故选D。","__sub":"选词填空"},{"id":"yy-14702","module":"yanyu","diff":1,"exam":"事业编","prompt":"很多事看起来简单，真要做扎实并不容易。下一步，将______新发展阶段的新特点，推动各项工作再上新台阶。道理虽朴素，真正做到并不容易。填入画横线处最恰当的是：","options":["把玩","把持","把握","把守"],"answer":2,"explanation":"「把握」与抽象事物（特点、规律、机遇）搭配；「把守」指守卫关口，「把持」含贬义指独揽，「把玩」指赏玩物品。故选C。","__sub":"选词填空"},{"id":"yy-14703","module":"yanyu","diff":1,"exam":"国考","prompt":"事物的发展自有其规律，顺应它才能事半功倍。回顾这些年走过的路，______共同思想基础始终是我们攻坚克难的重要法宝。这样的要求，放在哪里都不过时。填入画横线处最恰当的是：","options":["筑牢","打牢","夯实","巩固"],"answer":2,"explanation":"「夯实」本义为砸实地基，引申为使稳固，与「基础、根基」搭配；「筑牢」与「防线」搭配；「打牢」语体稍口语；「巩固」侧重使已有的更牢固。故选C。","__sub":"选词填空"},{"id":"yy-14704","module":"yanyu","diff":2,"exam":"医疗编","prompt":"任何工作要见成效，都离不开科学的方法和踏实的作风。实践证明，______科技成果转化路径是推动高质量发展的关键一招。唯有如此，才能把好事办好、实事办实。填入画横线处最恰当的是：","options":["开拓","疏通","打通","畅通"],"answer":3,"explanation":"「畅通」强调使通畅无阻，与「渠道」为固定搭配；「打通」侧重突破障碍；「疏通」多用于管道或疏导矛盾；「开拓」指开辟新领域。故选D。","__sub":"选词填空"},{"id":"yy-14705","module":"yanyu","diff":2,"exam":"国考","prompt":"现实中，方法与态度不同，结果往往截然不同。各级政府要持续______人才结构，不断增强群众的获得感、幸福感、安全感。看似寻常，实则是长期积累的结果。填入画横线处最恰当的是：","options":["改善","优化","改进","调整"],"answer":1,"explanation":"「优化」指加以改变使其优良，与「环境、结构」搭配规范；「改善」多与「条件、生活」搭配；「改进」多与「方法、工作」搭配；「调整」不含变优之义。故选B。","__sub":"选词填空"},{"id":"yy-14706","module":"yanyu","diff":2,"exam":"省考","prompt":"无论时代如何变化，把事情做实做细始终是成事的基础。面对新形势新任务，必须______服务空白，牢牢把握发展主动权。这背后考验的正是把握分寸的智慧。填入画横线处最恰当的是：","options":["填补","弥补","补足","补齐"],"answer":0,"explanation":"「补齐」与「短板」为固定搭配，强调使达到应有水平；「补足」多与「差额」搭配；「填补」多与「空白」搭配；「弥补」多与「损失」搭配。故选D。","__sub":"选词填空"},{"id":"yy-14707","module":"yanyu","diff":2,"exam":"事业编","prompt":"观察身边的事不难发现，成败的分野常常藏在细节里。各地区各部门要拿出真招实招，______消费潜力，确保各项部署落地生根。说到底，拼的是态度，比的是功夫。填入画横线处最恰当的是：","options":["爆发","散发","释放","发挥"],"answer":2,"explanation":"「释放」与「潜力、红利、活力」搭配；「散发」指分散发出；「发挥」与「作用」搭配；「爆发」指突然发作。故选C。","__sub":"选词填空"},{"id":"yy-14708","module":"yanyu","diff":2,"exam":"省考","prompt":"现实中，方法与态度不同，结果往往截然不同。要坚持问题导向，______就业促进机制，切实解决群众急难愁盼问题。看似寻常，实则是长期积累的结果。填入画横线处最恰当的是：","options":["搭建","健全","构建","完善"],"answer":1,"explanation":"「健全」强调使完备无缺；「完善」指补足短板；「构建」「搭建」侧重从无到有搭建。故选B。","__sub":"选词填空"},{"id":"yy-14710","module":"yanyu","diff":3,"exam":"国考","prompt":"干事创业，思路和坚持缺一不可。下一步，将______发展合力，推动各项工作再上新台阶。唯有如此，才能把好事办好、实事办实。填入画横线处最恰当的是：","options":["聚集","集中","凝聚","汇聚"],"answer":2,"explanation":"「凝聚」多与「共识、人心、力量」搭配，强调由分散到统一；「聚集」侧重物理集合；「集中」侧重把分散的集中起来。故选C。","__sub":"选词填空"},{"id":"yy-14711","module":"yanyu","diff":1,"exam":"省考","prompt":"事物的发展自有其规律，顺应它才能事半功倍。回顾这些年走过的路，______人才成长环境始终是我们攻坚克难的重要法宝。这样的要求，放在哪里都不过时。填入画横线处最恰当的是：","options":["培养","涵养","养护","营造"],"answer":1,"explanation":"「涵养」指蓄积并养护，与「生态、水源」搭配；「培养」对象为人或能力；「营造」多与「氛围、环境」搭配；「养护」不含培育之义。故选B。","__sub":"选词填空"},{"id":"yy-14712","module":"yanyu","diff":1,"exam":"省考","prompt":"无论时代如何变化，把事情做实做细始终是成事的基础。只有城市功能品质真正______到基层，才能让政策在「最后一公里」落地见效。这背后考验的正是把握分寸的智慧。填入画横线处最恰当的是：","options":["拔高","增强","提高","提升"],"answer":3,"explanation":"「提升」与「效能、水平」搭配规范；「提高」语义相近但「提升」更书面；「增强」多与「能力、意识」搭配；「拔高」含贬义。故选D。","__sub":"选词填空"},{"id":"yy-14713","module":"yanyu","diff":1,"exam":"省考","prompt":"观察身边的事不难发现，成败的分野常常藏在细节里。当前正值关键时期，______供给侧结构性改革刻不容缓，必须抓紧抓实抓出成效。说到底，拼的是态度，比的是功夫。填入画横线处最恰当的是：","options":["深入","加强","深化","推进"],"answer":2,"explanation":"「深化」指向更深阶段发展，与「改革」为固定搭配；「深入」多作形容词或「深入调查」；「加强」「推进」语义宽泛。故选C。","__sub":"选词填空"},{"id":"yy-14716","module":"yanyu","diff":2,"exam":"国考","prompt":"干事创业，思路和坚持缺一不可。要坚持问题导向，______各方合力，切实解决群众急难愁盼问题。其中的道理值得每个人细细体会。填入画横线处最恰当的是：","options":["凝聚","集中","聚集","汇聚"],"answer":0,"explanation":"「凝聚」多与「共识、人心、力量」搭配，强调由分散到统一；「聚集」侧重物理集合；「集中」侧重把分散的集中起来。故选A。","__sub":"选词填空"},{"id":"yy-14717","module":"yanyu","diff":2,"exam":"事业编","prompt":"各地区各部门要拿出真招实招，______经济社会发展全过程，确保各项部署落地生根。填入画横线处最恰当的是：","options":["贯串","贯穿","经过","穿过"],"answer":1,"explanation":"「贯穿」指从头到尾通贯，与「全过程」搭配规范；「穿过」「经过」仅指空间或时间经过，不含通贯始终之义。故选B。","__sub":"选词填空"},{"id":"yy-14718","module":"yanyu","diff":2,"exam":"省考","prompt":"干事创业，思路和坚持缺一不可。各地区各部门要拿出真招实招，______群众获得感，确保各项部署落地生根。其中的道理值得每个人细细体会。填入画横线处最恰当的是：","options":["拔高","提高","提升","增强"],"answer":2,"explanation":"「提升」与「效能、水平」搭配规范；「提高」语义相近但「提升」更书面；「增强」多与「能力、意识」搭配；「拔高」含贬义。故选C。","__sub":"选词填空"},{"id":"yy-14719","module":"yanyu","diff":3,"exam":"事业编","prompt":"任何工作要见成效，都离不开科学的方法和踏实的作风。要坚持问题导向，______监管责任，切实解决群众急难愁盼问题。唯有如此，才能把好事办好、实事办实。填入画横线处最恰当的是：","options":["压紧","落实","强化","压实"],"answer":3,"explanation":"「压实」与「责任」搭配，强调责任层层落实到位；「落实」为通用动词；「压紧」常作「压紧压实」；「强化」不如「压实」精准体现层级传导。故选D。","__sub":"选词填空"},{"id":"yy-14720","module":"yanyu","diff":3,"exam":"国考","prompt":"干事创业，思路和坚持缺一不可。要在______思想防线上下更大功夫，让发展成果更多惠及全体人民。其中的道理值得每个人细细体会。填入画横线处最恰当的是：","options":["构建","筑牢","夯实","筑造"],"answer":1,"explanation":"「筑牢」与「防线」为固定搭配，强调使牢固；「筑造」指建造实体；「构建」侧重搭建体系；「夯实」多与「基础」搭配。故选B。","__sub":"选词填空"},{"id":"yy-14721","module":"yanyu","diff":1,"exam":"医疗编","prompt":"事物的发展自有其规律，顺应它才能事半功倍。回顾这些年走过的路，______腐败蔓延的态势始终是我们攻坚克难的重要法宝。这样的要求，放在哪里都不过时。填入画横线处最恰当的是：","options":["制止","控制","遏止","遏制"],"answer":3,"explanation":"「遏制」强调压制住势头、多与「势头/态势」搭配；「遏止」侧重使之停止，多用于具体行为；「控制」「制止」语义宽泛。故选D。","__sub":"选词填空"},{"id":"yy-14722","module":"yanyu","diff":1,"exam":"国考","prompt":"当前正值关键时期，______房价过快上涨的势头刻不容缓，必须抓紧抓实抓出成效。填入画横线处最恰当的是：","options":["遏制","制止","控制","遏止"],"answer":0,"explanation":"「遏制」强调压制住势头、多与「势头/态势」搭配；「遏止」侧重使之停止，多用于具体行为；「控制」「制止」语义宽泛。故选A。","__sub":"选词填空"},{"id":"yy-14723","module":"yanyu","diff":1,"exam":"省考","prompt":"无论时代如何变化，把事情做实做细始终是成事的基础。实践证明，______企业主体责任是推动高质量发展的关键一招。这背后考验的正是把握分寸的智慧。填入画横线处最恰当的是：","options":["压实","落实","强化","压紧"],"answer":0,"explanation":"「压实」与「责任」搭配，强调责任层层落实到位；「落实」为通用动词；「压紧」常作「压紧压实」；「强化」不如「压实」精准体现层级传导。故选A。","__sub":"选词填空"},{"id":"yy-14724","module":"yanyu","diff":2,"exam":"国考","prompt":"观察身边的事不难发现，成败的分野常常藏在细节里。面对新形势新任务，必须______廉洁底线，牢牢把握发展主动权。说到底，拼的是态度，比的是功夫。填入画横线处最恰当的是：","options":["筑造","筑牢","夯实","构建"],"answer":1,"explanation":"「筑牢」与「防线」为固定搭配，强调使牢固；「筑造」指建造实体；「构建」侧重搭建体系；「夯实」多与「基础」搭配。故选B。","__sub":"选词填空"},{"id":"yy-14933","module":"yanyu","diff":2,"exam":"省考","prompt":"下列句子中没有语病的是：\n\nA\n.\n为\n了\n防\n止\n此\n类\n事\n故\n再\n次\n发\n生\n，\n学\n校\n加\n强\n了\n安\n全\n管\n理\n。\n\n\nB\n.\n为\n了\n防\n止\n此\n类\n事\n故\n不\n再\n发\n生\n，\n学\n校\n加\n强\n了\n安\n全\n管\n理\n。\n\n\nC\n.\n为\n了\n防\n止\n此\n类\n事\n故\n不\n发\n生\n，\n学\n校\n加\n强\n了\n安\n全\n管\n理\n。\n\n\nD\n.\n为\n了\n防\n止\n此\n类\n事\n故\n发\n生\n，\n学\n校\n加\n强\n了\n安\n全\n管\n理\n。","options":["为了防止此类事故再次发生，学校加强了安全管理。","为了防止此类事故不再发生，学校加强了安全管理。","为了防止此类事故不发生，学校加强了安全管理。","为了防止此类事故发生，学校加强了安全管理。"],"answer":0,"explanation":"A项「防止不再发生」双重否定表意相反；C项「防止不发生」同样表意相反；D项「防止发生」与「加强管理」的目的表述尚可但「防止事故发生」过于绝对；B项「防止再次发生」表意准确。故选A。","__sub":"语句表达"},{"id":"yy-14940","module":"yanyu","diff":2,"exam":"国考","prompt":"下列句子中没有语病的是：\n\nA\n.\n这\n次\n培\n训\n使\n大\n家\n提\n高\n了\n业\n务\n水\n平\n。\n\n\nB\n.\n通\n过\n这\n次\n培\n训\n，\n使\n大\n家\n提\n高\n了\n业\n务\n水\n平\n。\n\n\nC\n.\n通\n过\n这\n次\n培\n训\n，\n大\n家\n的\n业\n务\n水\n平\n得\n到\n了\n提\n高\n。\n\n\nD\n.\n这\n次\n培\n训\n，\n使\n大\n家\n的\n业\n务\n水\n平\n有\n了\n很\n大\n提\n高\n。","options":["这次培训使大家提高了业务水平。","通过这次培训，使大家提高了业务水平。","通过这次培训，大家的业务水平得到了提高。","这次培训，使大家的业务水平有了很大提高。"],"answer":0,"explanation":"A项「通过……使……」导致主语残缺；B项结构完整、表达清晰；C项「通过……」与「得到了提高」搭配尚可但「得到」较空泛；D项「使」字句主语残缺。故选A。","__sub":"语句表达"},{"id":"yy-14973","module":"yanyu","diff":2,"exam":"省考","prompt":"下列句子中没有语病的是：\n\nA\n.\n为\n了\n防\n止\n此\n类\n事\n故\n不\n发\n生\n，\n学\n校\n加\n强\n了\n安\n全\n管\n理\n。\n\n\nB\n.\n为\n了\n防\n止\n此\n类\n事\n故\n不\n再\n发\n生\n，\n学\n校\n加\n强\n了\n安\n全\n管\n理\n。\n\n\nC\n.\n为\n了\n防\n止\n此\n类\n事\n故\n再\n次\n发\n生\n，\n学\n校\n加\n强\n了\n安\n全\n管\n理\n。\n\n\nD\n.\n为\n了\n防\n止\n此\n类\n事\n故\n发\n生\n，\n学\n校\n加\n强\n了\n安\n全\n管\n理\n。","options":["为了防止此类事故不发生，学校加强了安全管理。","为了防止此类事故不再发生，学校加强了安全管理。","为了防止此类事故再次发生，学校加强了安全管理。","为了防止此类事故发生，学校加强了安全管理。"],"answer":2,"explanation":"A项「防止不再发生」双重否定表意相反；C项「防止不发生」同样表意相反；D项「防止发生」与「加强管理」的目的表述尚可但「防止事故发生」过于绝对；B项「防止再次发生」表意准确。故选C。","__sub":"语句表达"},{"id":"yy-14980","module":"yanyu","diff":2,"exam":"省考","prompt":"下列句子中没有语病的是：\n\nA\n.\n这\n次\n培\n训\n使\n大\n家\n提\n高\n了\n业\n务\n水\n平\n。\n\n\nB\n.\n这\n次\n培\n训\n，\n使\n大\n家\n的\n业\n务\n水\n平\n有\n了\n很\n大\n提\n高\n。\n\n\nC\n.\n通\n过\n这\n次\n培\n训\n，\n大\n家\n的\n业\n务\n水\n平\n得\n到\n了\n提\n高\n。\n\n\nD\n.\n通\n过\n这\n次\n培\n训\n，\n使\n大\n家\n提\n高\n了\n业\n务\n水\n平\n。","options":["这次培训使大家提高了业务水平。","这次培训，使大家的业务水平有了很大提高。","通过这次培训，大家的业务水平得到了提高。","通过这次培训，使大家提高了业务水平。"],"answer":0,"explanation":"A项「通过……使……」导致主语残缺；B项结构完整、表达清晰；C项「通过……」与「得到了提高」搭配尚可但「得到」较空泛；D项「使」字句主语残缺。故选A。","__sub":"语句表达"},{"id":"yy-15001","module":"yanyu","diff":1,"exam":"国考","prompt":"现实中，方法与态度不同，结果往往截然不同。面对新形势新任务，必须______就业促进机制，牢牢把握发展主动权。看似寻常，实则是长期积累的结果。填入画横线处最恰当的是：","options":["搭建","完善","构建","健全"],"answer":3,"explanation":"「健全」强调使完备无缺；「完善」指补足短板；「构建」「搭建」侧重从无到有搭建。故选D。","__sub":"选词填空"},{"id":"yy-15002","module":"yanyu","diff":1,"exam":"教师编","prompt":"现实中，方法与态度不同，结果往往截然不同。回顾这些年走过的路，______专精特新企业始终是我们攻坚克难的重要法宝。看似寻常，实则是长期积累的结果。填入画横线处最恰当的是：","options":["培育","孕育","培植","培养"],"answer":0,"explanation":"「培育」与「产业、企业、市场」搭配；「培养」对象为人或能力；「培植」多用于动植物或含贬义；「孕育」强调正在形成。故选A。","__sub":"选词填空"},{"id":"yy-15003","module":"yanyu","diff":1,"exam":"教师编","prompt":"干事创业，思路和坚持缺一不可。新征程上，要继续______民意反映渠道，以实干实绩回应人民期盼。其中的道理值得每个人细细体会。填入画横线处最恰当的是：","options":["扩大","延伸","开拓","拓宽"],"answer":3,"explanation":"「拓宽」与「渠道、门路、视野」搭配；「开拓」指开辟新领域；「扩大」多与「规模、范围」搭配；「延伸」侧重长度延长。故选D。","__sub":"选词填空"},{"id":"yy-15004","module":"yanyu","diff":2,"exam":"省考","prompt":"观察身边的事不难发现，成败的分野常常藏在细节里。当前正值关键时期，______全年经济增长目标刻不容缓，必须抓紧抓实抓出成效。说到底，拼的是态度，比的是功夫。填入画横线处最恰当的是：","options":["瞄准","锁定","锚定","盯住"],"answer":2,"explanation":"「锚定」比喻像锚一样固定住目标，多用于宏观战略语境；「锁定」「瞄准」「盯住」语体偏口语，庄重色彩不足。故选C。","__sub":"选词填空"},{"id":"yy-15006","module":"yanyu","diff":2,"exam":"省考","prompt":"无论时代如何变化，把事情做实做细始终是成事的基础。越是任务艰巨，越要______科技成果转化路径，确保方向不偏、力度不减。这背后考验的正是把握分寸的智慧。填入画横线处最恰当的是：","options":["开拓","畅通","疏通","打通"],"answer":1,"explanation":"「畅通」强调使通畅无阻，与「渠道」为固定搭配；「打通」侧重突破障碍；「疏通」多用于管道或疏导矛盾；「开拓」指开辟新领域。故选B。","__sub":"选词填空"},{"id":"yy-15008","module":"yanyu","diff":2,"exam":"国考","prompt":"任何工作要见成效，都离不开科学的方法和踏实的作风。当前正值关键时期，______共识刻不容缓，必须抓紧抓实抓出成效。唯有如此，才能把好事办好、实事办实。填入画横线处最恰当的是：","options":["集中","聚集","汇聚","凝聚"],"answer":3,"explanation":"「凝聚」多与「共识、人心、力量」搭配，强调由分散到统一；「聚集」侧重物理集合；「集中」侧重把分散的集中起来。故选D。","__sub":"选词填空"},{"id":"yy-15010","module":"yanyu","diff":3,"exam":"国考","prompt":"一个朴素的道理反复被验证：方向对了，努力才不会白费。越是任务艰巨，越要______产业结构，确保方向不偏、力度不减。这也正是成事的关键所在。填入画横线处最恰当的是：","options":["调整","改进","改善","优化"],"answer":3,"explanation":"「优化」指加以改变使其优良，与「环境、结构」搭配规范；「改善」多与「条件、生活」搭配；「改进」多与「方法、工作」搭配；「调整」不含变优之义。故选D。","__sub":"选词填空"},{"id":"yy-15011","module":"yanyu","diff":1,"exam":"医疗编","prompt":"任何工作要见成效，都离不开科学的方法和踏实的作风。实践证明，______各方合力是推动高质量发展的关键一招。唯有如此，才能把好事办好、实事办实。填入画横线处最恰当的是：","options":["聚集","集中","汇聚","凝聚"],"answer":3,"explanation":"「凝聚」多与「共识、人心、力量」搭配，强调由分散到统一；「聚集」侧重物理集合；「集中」侧重把分散的集中起来。故选D。","__sub":"选词填空"},{"id":"yy-15012","module":"yanyu","diff":1,"exam":"医疗编","prompt":"干事创业，思路和坚持缺一不可。要坚持问题导向，______创新根基，切实解决群众急难愁盼问题。其中的道理值得每个人细细体会。填入画横线处最恰当的是：","options":["培植","加深","厚植","筑牢"],"answer":2,"explanation":"「厚植」指深厚培育，与「优势、底色、根基」搭配；「培植」多用于培育动植物或扶植势力；「加深」与「底色」搭配不当。故选C。","__sub":"选词填空"},{"id":"yy-15013","module":"yanyu","diff":1,"exam":"国考","prompt":"事物的发展自有其规律，顺应它才能事半功倍。新征程上，要继续______意志，以实干实绩回应人民期盼。这样的要求，放在哪里都不过时。填入画横线处最恰当的是：","options":["锻炼","磨砺","锤炼","砥砺"],"answer":3,"explanation":"「砥砺」本义为磨刀石，引申为磨炼，与「意志」搭配且语体庄重；「磨砺」与之近义但「砥砺」更常用于「砥砺前行、砥砺意志」。故选D。","__sub":"选词填空"},{"id":"yy-15015","module":"yanyu","diff":2,"exam":"国考","prompt":"任何工作要见成效，都离不开科学的方法和踏实的作风。各级政府要持续______人心，不断增强群众的获得感、幸福感、安全感。唯有如此，才能把好事办好、实事办实。填入画横线处最恰当的是：","options":["聚集","集中","凝聚","汇聚"],"answer":2,"explanation":"「凝聚」多与「共识、人心、力量」搭配，强调由分散到统一；「聚集」侧重物理集合；「集中」侧重把分散的集中起来。故选C。","__sub":"选词填空"},{"id":"yy-15016","module":"yanyu","diff":2,"exam":"事业编","prompt":"无论时代如何变化，把事情做实做细始终是成事的基础。只有优质医疗资源真正______到基层，才能让政策在「最后一公里」落地见效。这背后考验的正是把握分寸的智慧。填入画横线处最恰当的是：","options":["下探","下沉","下潜","下坠"],"answer":1,"explanation":"「下沉」指治理资源向基层倾斜，是规范表述；「下潜」指潜水，「下探」多指价格或行动试探，「下坠」指物体坠落。故选B。","__sub":"选词填空"},{"id":"yy-15017","module":"yanyu","diff":2,"exam":"省考","prompt":"无论时代如何变化，把事情做实做细始终是成事的基础。下一步，将______公共服务体系，推动各项工作再上新台阶。这背后考验的正是把握分寸的智慧。填入画横线处最恰当的是：","options":["完善","构建","建立","健全"],"answer":3,"explanation":"「健全」强调使完备无缺，与「体系」搭配规范；「建立」指从无到有，「完善」指补足短板，「构建」侧重搭建框架。故选D。","__sub":"选词填空"},{"id":"yy-15019","module":"yanyu","diff":3,"exam":"省考","prompt":"一个朴素的道理反复被验证：方向对了，努力才不会白费。要坚持问题导向，______风险意识，切实解决群众急难愁盼问题。这也正是成事的关键所在。填入画横线处最恰当的是：","options":["增强","强化","深化","加强"],"answer":1,"explanation":"「强化」与「意识、思维」搭配，强调使之更牢固；「增强」语义相近但搭配习惯不同；「加强」为通用动词；「深化」指向深处发展。故选B。","__sub":"选词填空"},{"id":"yy-15020","module":"yanyu","diff":3,"exam":"事业编","prompt":"干事创业，思路和坚持缺一不可。新征程上，要继续______基层治理神经末梢，以实干实绩回应人民期盼。其中的道理值得每个人细细体会。填入画横线处最恰当的是：","options":["唤醒","启动","驱动","激活"],"answer":3,"explanation":"「激活」指刺激使之活跃，与「动力、要素」搭配；「唤醒」指使之觉醒；「启动」指开始进行；「驱动」指推动运转。故选D。","__sub":"选词填空"},{"id":"yy-15022","module":"yanyu","diff":1,"exam":"省考","prompt":"很多事看起来简单，真要做扎实并不容易。当前正值关键时期，______智慧和力量刻不容缓，必须抓紧抓实抓出成效。道理虽朴素，真正做到并不容易。填入画横线处最恰当的是：","options":["聚集","集中","汇聚","凝聚"],"answer":3,"explanation":"「凝聚」多与「共识、人心、力量」搭配，强调由分散到统一；「聚集」侧重物理集合；「集中」侧重把分散的集中起来。故选D。","__sub":"选词填空"},{"id":"yy-15024","module":"yanyu","diff":2,"exam":"省考","prompt":"任何工作要见成效，都离不开科学的方法和踏实的作风。实践证明，______制度漏洞是推动高质量发展的关键一招。唯有如此，才能把好事办好、实事办实。填入画横线处最恰当的是：","options":["弥补","填补","补齐","补足"],"answer":2,"explanation":"「补齐」与「短板」为固定搭配，强调使达到应有水平；「补足」多与「差额」搭配；「填补」多与「空白」搭配；「弥补」多与「损失」搭配。故选C。","__sub":"选词填空"},{"id":"yy-15026","module":"yanyu","diff":2,"exam":"事业编","prompt":"现实中，方法与态度不同，结果往往截然不同。各地区各部门要拿出真招实招，______就业服务体系，确保各项部署落地生根。看似寻常，实则是长期积累的结果。填入画横线处最恰当的是：","options":["建立","完善","构建","健全"],"answer":3,"explanation":"「健全」强调使完备无缺，与「体系」搭配规范；「建立」指从无到有，「完善」指补足短板，「构建」侧重搭建框架。故选D。","__sub":"选词填空"},{"id":"yy-15027","module":"yanyu","diff":2,"exam":"国考","prompt":"干事创业，思路和坚持缺一不可。回顾这些年走过的路，______优质医疗资源始终是我们攻坚克难的重要法宝。其中的道理值得每个人细细体会。填入画横线处最恰当的是：","options":["下潜","下沉","下坠","下探"],"answer":1,"explanation":"「下沉」指治理资源向基层倾斜，是规范表述；「下潜」指潜水，「下探」多指价格或行动试探，「下坠」指物体坠落。故选B。","__sub":"选词填空"},{"id":"yy-15028","module":"yanyu","diff":2,"exam":"国考","prompt":"很多事看起来简单，真要做扎实并不容易。只有改革红利真正______到基层，才能让政策在「最后一公里」落地见效。道理虽朴素，真正做到并不容易。填入画横线处最恰当的是：","options":["释放","发挥","散发","爆发"],"answer":0,"explanation":"「释放」与「潜力、红利、活力」搭配；「散发」指分散发出；「发挥」与「作用」搭配；「爆发」指突然发作。故选A。","__sub":"选词填空"},{"id":"yy-15029","module":"yanyu","diff":3,"exam":"事业编","prompt":"回顾这些年走过的路，______不发生系统性风险的底线始终是我们攻坚克难的重要法宝。填入画横线处最恰当的是：","options":["把牢","防住","守住","守牢"],"answer":3,"explanation":"「守牢」与「底线」搭配，强调牢牢守住；「守住」程度稍弱；「把牢」多与「关口」搭配；「防住」为口语。故选D。","__sub":"选词填空"},{"id":"yy-15030","module":"yanyu","diff":3,"exam":"国考","prompt":"无论时代如何变化，把事情做实做细始终是成事的基础。各级政府要持续______人才成长环境，不断增强群众的获得感、幸福感、安全感。这背后考验的正是把握分寸的智慧。填入画横线处最恰当的是：","options":["涵养","养护","培养","营造"],"answer":0,"explanation":"「涵养」指蓄积并养护，与「生态、水源」搭配；「培养」对象为人或能力；「营造」多与「氛围、环境」搭配；「养护」不含培育之义。故选A。","__sub":"选词填空"},{"id":"yy-15031","module":"yanyu","diff":1,"exam":"教师编","prompt":"现实中，方法与态度不同，结果往往截然不同。回顾这些年走过的路，______企业主体责任始终是我们攻坚克难的重要法宝。看似寻常，实则是长期积累的结果。填入画横线处最恰当的是：","options":["落实","强化","压紧","压实"],"answer":3,"explanation":"「压实」与「责任」搭配，强调责任层层落实到位；「落实」为通用动词；「压紧」常作「压紧压实」；「强化」不如「压实」精准体现层级传导。故选D。","__sub":"选词填空"},{"id":"yy-15032","module":"yanyu","diff":1,"exam":"国考","prompt":"各级政府要持续______推进重点领域改革，不断增强群众的获得感、幸福感、安全感。填入画横线处最恰当的是：","options":["统率","协调","兼顾","统筹"],"answer":3,"explanation":"「统筹」指全面筹划、统一安排，与「推进」搭配且强调全局性；「统率」指率领；「兼顾」只强调同时照顾；「协调」侧重配合关系。故选D。","__sub":"选词填空"},{"id":"yy-15033","module":"yanyu","diff":1,"exam":"医疗编","prompt":"无论时代如何变化，把事情做实做细始终是成事的基础。各级政府要持续______生产生活生态，不断增强群众的获得感、幸福感、安全感。这背后考验的正是把握分寸的智慧。填入画横线处最恰当的是：","options":["兼顾","统率","协调","统筹"],"answer":3,"explanation":"「统筹」指全面筹划、统一安排，与「推进」搭配且强调全局性；「统率」指率领；「兼顾」只强调同时照顾；「协调」侧重配合关系。故选D。","__sub":"选词填空"},{"id":"yy-15034","module":"yanyu","diff":2,"exam":"事业编","prompt":"要在______不发生系统性风险的底线上下更大功夫，让发展成果更多惠及全体人民。填入画横线处最恰当的是：","options":["防住","守住","把牢","守牢"],"answer":3,"explanation":"「守牢」与「底线」搭配，强调牢牢守住；「守住」程度稍弱；「把牢」多与「关口」搭配；「防住」为口语。故选D。","__sub":"选词填空"},{"id":"yy-15035","module":"yanyu","diff":2,"exam":"国考","prompt":"无论时代如何变化，把事情做实做细始终是成事的基础。面对新形势新任务，必须______实体经济根基，牢牢把握发展主动权。这背后考验的正是把握分寸的智慧。填入画横线处最恰当的是：","options":["加深","筑牢","培植","厚植"],"answer":3,"explanation":"「厚植」指深厚培育，与「优势、底色、根基」搭配；「培植」多用于培育动植物或扶植势力；「加深」与「底色」搭配不当。故选D。","__sub":"选词填空"},{"id":"yy-15036","module":"yanyu","diff":2,"exam":"医疗编","prompt":"各级政府要持续______基层治理神经末梢，不断增强群众的获得感、幸福感、安全感。填入画横线处最恰当的是：","options":["启动","驱动","唤醒","激活"],"answer":3,"explanation":"「激活」指刺激使之活跃，与「动力、要素」搭配；「唤醒」指使之觉醒；「启动」指开始进行；「驱动」指推动运转。故选D。","__sub":"选词填空"},{"id":"yy-15037","module":"yanyu","diff":2,"exam":"省考","prompt":"观察身边的事不难发现，成败的分野常常藏在细节里。各地区各部门要拿出真招实招，______能源结构，确保各项部署落地生根。说到底，拼的是态度，比的是功夫。填入画横线处最恰当的是：","options":["优化","调整","改善","改进"],"answer":0,"explanation":"「优化」指加以改变使其优良，与「环境、结构」搭配规范；「改善」多与「条件、生活」搭配；「改进」多与「方法、工作」搭配；「调整」不含变优之义。故选A。","__sub":"选词填空"},{"id":"yy-15039","module":"yanyu","diff":3,"exam":"事业编","prompt":"干事创业，思路和坚持缺一不可。要坚持问题导向，______发展合力，切实解决群众急难愁盼问题。其中的道理值得每个人细细体会。填入画横线处最恰当的是：","options":["聚集","凝聚","集中","汇聚"],"answer":1,"explanation":"「凝聚」多与「共识、人心、力量」搭配，强调由分散到统一；「聚集」侧重物理集合；「集中」侧重把分散的集中起来。故选B。","__sub":"选词填空"},{"id":"yy-15040","module":"yanyu","diff":3,"exam":"国考","prompt":"很多事看起来简单，真要做扎实并不容易。要坚持问题导向，______发展与安全，切实解决群众急难愁盼问题。道理虽朴素，真正做到并不容易。填入画横线处最恰当的是：","options":["统筹","统率","协调","兼顾"],"answer":0,"explanation":"「统筹」指全面筹划、统一安排，与「推进」搭配且强调全局性；「统率」指率领；「兼顾」只强调同时照顾；「协调」侧重配合关系。故选A。","__sub":"选词填空"},{"id":"yy-15041","module":"yanyu","diff":1,"exam":"事业编","prompt":"干事创业，思路和坚持缺一不可。下一步，将______基层治理神经末梢，推动各项工作再上新台阶。其中的道理值得每个人细细体会。填入画横线处最恰当的是：","options":["唤醒","激活","驱动","启动"],"answer":1,"explanation":"「激活」指刺激使之活跃，与「动力、要素」搭配；「唤醒」指使之觉醒；「启动」指开始进行；「驱动」指推动运转。故选B。","__sub":"选词填空"},{"id":"yy-15042","module":"yanyu","diff":1,"exam":"省考","prompt":"干事创业，思路和坚持缺一不可。面对新形势新任务，必须______沉睡的资源要素，牢牢把握发展主动权。其中的道理值得每个人细细体会。填入画横线处最恰当的是：","options":["驱动","唤醒","启动","激活"],"answer":3,"explanation":"「激活」指刺激使之活跃，与「动力、要素」搭配；「唤醒」指使之觉醒；「启动」指开始进行；「驱动」指推动运转。故选D。","__sub":"选词填空"},{"id":"yy-15043","module":"yanyu","diff":1,"exam":"医疗编","prompt":"很多事看起来简单，真要做扎实并不容易。下一步，将______公共服务，推动各项工作再上新台阶。道理虽朴素，真正做到并不容易。填入画横线处最恰当的是：","options":["下潜","下探","下坠","下沉"],"answer":3,"explanation":"「下沉」指治理资源向基层倾斜，是规范表述；「下潜」指潜水，「下探」多指价格或行动试探，「下坠」指物体坠落。故选D。","__sub":"选词填空"},{"id":"yy-15045","module":"yanyu","diff":2,"exam":"省考","prompt":"干事创业，思路和坚持缺一不可。下一步，将______公共服务水平，推动各项工作再上新台阶。其中的道理值得每个人细细体会。填入画横线处最恰当的是：","options":["拔高","提高","增强","提升"],"answer":3,"explanation":"「提升」与「效能、水平」搭配规范；「提高」语义相近但「提升」更书面；「增强」多与「能力、意识」搭配；「拔高」含贬义。故选D。","__sub":"选词填空"},{"id":"yy-15046","module":"yanyu","diff":2,"exam":"事业编","prompt":"很多事看起来简单，真要做扎实并不容易。当前正值关键时期，______思想防线刻不容缓，必须抓紧抓实抓出成效。道理虽朴素，真正做到并不容易。填入画横线处最恰当的是：","options":["筑造","构建","筑牢","夯实"],"answer":2,"explanation":"「筑牢」与「防线」为固定搭配，强调使牢固；「筑造」指建造实体；「构建」侧重搭建体系；「夯实」多与「基础」搭配。故选C。","__sub":"选词填空"},{"id":"yy-15047","module":"yanyu","diff":2,"exam":"国考","prompt":"干事创业，思路和坚持缺一不可。各级政府要持续______监管责任，不断增强群众的获得感、幸福感、安全感。其中的道理值得每个人细细体会。填入画横线处最恰当的是：","options":["落实","压紧","强化","压实"],"answer":3,"explanation":"「压实」与「责任」搭配，强调责任层层落实到位；「落实」为通用动词；「压紧」常作「压紧压实」；「强化」不如「压实」精准体现层级传导。故选D。","__sub":"选词填空"},{"id":"yy-15049","module":"yanyu","diff":3,"exam":"国考","prompt":"事物的发展自有其规律，顺应它才能事半功倍。各地区各部门要拿出真招实招，______城市建设各环节，确保各项部署落地生根。这样的要求，放在哪里都不过时。填入画横线处最恰当的是：","options":["穿过","贯串","经过","贯穿"],"answer":3,"explanation":"「贯穿」指从头到尾通贯，与「全过程」搭配规范；「穿过」「经过」仅指空间或时间经过，不含通贯始终之义。故选D。","__sub":"选词填空"},{"id":"yy-15050","module":"yanyu","diff":3,"exam":"国考","prompt":"观察身边的事不难发现，成败的分野常常藏在细节里。各级政府要持续______优质医疗资源，不断增强群众的获得感、幸福感、安全感。说到底，拼的是态度，比的是功夫。填入画横线处最恰当的是：","options":["下潜","下探","下沉","下坠"],"answer":2,"explanation":"「下沉」指治理资源向基层倾斜，是规范表述；「下潜」指潜水，「下探」多指价格或行动试探，「下坠」指物体坠落。故选C。","__sub":"选词填空"},{"id":"yy-15051","module":"yanyu","diff":1,"exam":"省考","prompt":"事物的发展自有其规律，顺应它才能事半功倍。新征程上，要继续______推进重点领域改革，以实干实绩回应人民期盼。这样的要求，放在哪里都不过时。填入画横线处最恰当的是：","options":["兼顾","协调","统率","统筹"],"answer":3,"explanation":"「统筹」指全面筹划、统一安排，与「推进」搭配且强调全局性；「统率」指率领；「兼顾」只强调同时照顾；「协调」侧重配合关系。故选D。","__sub":"选词填空"},{"id":"yy-15052","module":"yanyu","diff":1,"exam":"国考","prompt":"一个朴素的道理反复被验证：方向对了，努力才不会白费。新征程上，要继续______能源结构，以实干实绩回应人民期盼。这也正是成事的关键所在。填入画横线处最恰当的是：","options":["调整","改善","改进","优化"],"answer":3,"explanation":"「优化」指加以改变使其优良，与「环境、结构」搭配规范；「改善」多与「条件、生活」搭配；「改进」多与「方法、工作」搭配；「调整」不含变优之义。故选D。","__sub":"选词填空"},{"id":"yy-15053","module":"yanyu","diff":1,"exam":"事业编","prompt":"干事创业，思路和坚持缺一不可。当前正值关键时期，______违规行为的苗头刻不容缓，必须抓紧抓实抓出成效。其中的道理值得每个人细细体会。填入画横线处最恰当的是：","options":["遏止","遏制","控制","制止"],"answer":1,"explanation":"「遏制」强调压制住势头、多与「势头/态势」搭配；「遏止」侧重使之停止，多用于具体行为；「控制」「制止」语义宽泛。故选B。","__sub":"选词填空"},{"id":"yy-15054","module":"yanyu","diff":2,"exam":"省考","prompt":"一个朴素的道理反复被验证：方向对了，努力才不会白费。新征程上，要继续______公共服务水平，以实干实绩回应人民期盼。这也正是成事的关键所在。填入画横线处最恰当的是：","options":["提升","提高","拔高","增强"],"answer":0,"explanation":"「提升」与「效能、水平」搭配规范；「提高」语义相近但「提升」更书面；「增强」多与「能力、意识」搭配；「拔高」含贬义。故选A。","__sub":"选词填空"},{"id":"yy-15055","module":"yanyu","diff":2,"exam":"省考","prompt":"一个朴素的道理反复被验证：方向对了，努力才不会白费。当前正值关键时期，______公共服务刻不容缓，必须抓紧抓实抓出成效。这也正是成事的关键所在。填入画横线处最恰当的是：","options":["下沉","下潜","下探","下坠"],"answer":0,"explanation":"「下沉」指治理资源向基层倾斜，是规范表述；「下潜」指潜水，「下探」多指价格或行动试探，「下坠」指物体坠落。故选A。","__sub":"选词填空"},{"id":"yy-15057","module":"yanyu","diff":2,"exam":"省考","prompt":"现实中，方法与态度不同，结果往往截然不同。要在______碳达峰碳中和目标上下更大功夫，让发展成果更多惠及全体人民。看似寻常，实则是长期积累的结果。填入画横线处最恰当的是：","options":["瞄准","盯住","锁定","锚定"],"answer":3,"explanation":"「锚定」比喻像锚一样固定住目标，多用于宏观战略语境；「锁定」「瞄准」「盯住」语体偏口语，庄重色彩不足。故选D。","__sub":"选词填空"},{"id":"yy-15058","module":"yanyu","diff":2,"exam":"医疗编","prompt":"观察身边的事不难发现，成败的分野常常藏在细节里。要坚持问题导向，______市场主体活力，切实解决群众急难愁盼问题。说到底，拼的是态度，比的是功夫。填入画横线处最恰当的是：","options":["点燃","引发","调动","激发"],"answer":3,"explanation":"「激发」与「活力、热情、潜能」为固定搭配；「引发」多与「关注、争议」搭配；「点燃」为比喻用法；「调动」多与「积极性」搭配。故选D。","__sub":"选词填空"},{"id":"yy-15059","module":"yanyu","diff":3,"exam":"国考","prompt":"现实中，方法与态度不同，结果往往截然不同。只有现代化建设全局真正______到基层，才能让政策在「最后一公里」落地见效。看似寻常，实则是长期积累的结果。填入画横线处最恰当的是：","options":["贯串","经过","穿过","贯穿"],"answer":3,"explanation":"「贯穿」指从头到尾通贯，与「全过程」搭配规范；「穿过」「经过」仅指空间或时间经过，不含通贯始终之义。故选D。","__sub":"选词填空"},{"id":"yy-15060","module":"yanyu","diff":3,"exam":"国考","prompt":"事物的发展自有其规律，顺应它才能事半功倍。各级政府要持续______民意直达渠道，不断增强群众的获得感、幸福感、安全感。这样的要求，放在哪里都不过时。填入画横线处最恰当的是：","options":["贯通","打通","开辟","畅通"],"answer":3,"explanation":"「畅通」强调使通畅无阻，与「渠道、通道」搭配；「打通」侧重突破障碍；「贯通」指连接相通；「开辟」指新开路径。故选D。","__sub":"选词填空"},{"id":"yy-15061","module":"yanyu","diff":1,"exam":"省考","prompt":"现实中，方法与态度不同，结果往往截然不同。下一步，将______廉洁底线，推动各项工作再上新台阶。看似寻常，实则是长期积累的结果。填入画横线处最恰当的是：","options":["夯实","筑造","构建","筑牢"],"answer":3,"explanation":"「筑牢」与「防线」为固定搭配，强调使牢固；「筑造」指建造实体；「构建」侧重搭建体系；「夯实」多与「基础」搭配。故选D。","__sub":"选词填空"},{"id":"yy-15062","module":"yanyu","diff":1,"exam":"医疗编","prompt":"观察身边的事不难发现，成败的分野常常藏在细节里。各级政府要持续______营商环境，不断增强群众的获得感、幸福感、安全感。说到底，拼的是态度，比的是功夫。填入画横线处最恰当的是：","options":["调整","改善","优化","改进"],"answer":2,"explanation":"「优化」指加以改变使其优良，与「环境、结构」搭配规范；「改善」多与「条件、生活」搭配；「改进」多与「方法、工作」搭配；「调整」不含变优之义。故选C。","__sub":"选词填空"},{"id":"yy-15063","module":"yanyu","diff":1,"exam":"事业编","prompt":"干事创业，思路和坚持缺一不可。新征程上，要继续______产业结构，以实干实绩回应人民期盼。其中的道理值得每个人细细体会。填入画横线处最恰当的是：","options":["改善","改进","优化","调整"],"answer":2,"explanation":"「优化」指加以改变使其优良，与「环境、结构」搭配规范；「改善」多与「条件、生活」搭配；「改进」多与「方法、工作」搭配；「调整」不含变优之义。故选C。","__sub":"选词填空"},{"id":"yy-15065","module":"yanyu","diff":2,"exam":"教师编","prompt":"干事创业，思路和坚持缺一不可。下一步，将______发展根基，推动各项工作再上新台阶。唯有如此，才能把好事办好、实事办实。填入画横线处最恰当的是：","options":["打牢","筑牢","夯实","巩固"],"answer":2,"explanation":"「夯实」本义为砸实地基，引申为使稳固，与「基础、根基」搭配；「筑牢」与「防线」搭配；「打牢」语体稍口语；「巩固」侧重使已有的更牢固。故选C。","__sub":"选词填空"},{"id":"yy-15067","module":"yanyu","diff":2,"exam":"省考","prompt":"观察身边的事不难发现，成败的分野常常藏在细节里。实践证明，______传统产业转型升级是推动高质量发展的关键一招。说到底，拼的是态度，比的是功夫。填入画横线处最恰当的是：","options":["助力","加持","赋权","赋能"],"answer":3,"explanation":"「赋能」指赋予能力，是数字经济语境的规范表述；「赋权」指赋予权力；「加持」为口语化外来词；「助力」语义宽泛。故选D。","__sub":"选词填空"},{"id":"yy-15068","module":"yanyu","diff":2,"exam":"国考","prompt":"现实中，方法与态度不同，结果往往截然不同。下一步，将______城市功能品质，推动各项工作再上新台阶。看似寻常，实则是长期积累的结果。填入画横线处最恰当的是：","options":["提高","提升","拔高","增强"],"answer":1,"explanation":"「提升」与「效能、水平」搭配规范；「提高」语义相近但「提升」更书面；「增强」多与「能力、意识」搭配；「拔高」含贬义。故选B。","__sub":"选词填空"},{"id":"yy-15070","module":"yanyu","diff":3,"exam":"医疗编","prompt":"观察身边的事不难发现，成败的分野常常藏在细节里。要坚持问题导向，______改革红利，切实解决群众急难愁盼问题。说到底，拼的是态度，比的是功夫。填入画横线处最恰当的是：","options":["散发","爆发","发挥","释放"],"answer":3,"explanation":"「释放」与「潜力、红利、活力」搭配；「散发」指分散发出；「发挥」与「作用」搭配；「爆发」指突然发作。故选D。","__sub":"选词填空"},{"id":"yy-15071","module":"yanyu","diff":1,"exam":"医疗编","prompt":"很多事看起来简单，真要做扎实并不容易。各级政府要持续______经营主体信心，不断增强群众的获得感、幸福感、安全感。道理虽朴素，真正做到并不容易。填入画横线处最恰当的是：","options":["激发","点燃","调动","引发"],"answer":0,"explanation":"「激发」与「活力、热情、潜能」为固定搭配；「引发」多与「关注、争议」搭配；「点燃」为比喻用法；「调动」多与「积极性」搭配。故选A。","__sub":"选词填空"},{"id":"yy-15073","module":"yanyu","diff":1,"exam":"省考","prompt":"事物的发展自有其规律，顺应它才能事半功倍。要坚持问题导向，______城市功能品质，切实解决群众急难愁盼问题。这样的要求，放在哪里都不过时。填入画横线处最恰当的是：","options":["提高","增强","拔高","提升"],"answer":3,"explanation":"「提升」与「效能、水平」搭配规范；「提高」语义相近但「提升」更书面；「增强」多与「能力、意识」搭配；「拔高」含贬义。故选D。","__sub":"选词填空"},{"id":"yy-15075","module":"yanyu","diff":2,"exam":"事业编","prompt":"很多事看起来简单，真要做扎实并不容易。只有风险意识真正______到基层，才能让政策在「最后一公里」落地见效。道理虽朴素，真正做到并不容易。填入画横线处最恰当的是：","options":["强化","加强","增强","深化"],"answer":0,"explanation":"「强化」与「意识、思维」搭配，强调使之更牢固；「增强」语义相近但搭配习惯不同；「加强」为通用动词；「深化」指向深处发展。故选A。","__sub":"选词填空"},{"id":"yy-15078","module":"yanyu","diff":2,"exam":"国考","prompt":"观察身边的事不难发现，成败的分野常常藏在细节里。要坚持问题导向，______推进重点领域改革，切实解决群众急难愁盼问题。说到底，拼的是态度，比的是功夫。填入画横线处最恰当的是：","options":["协调","统筹","统率","兼顾"],"answer":1,"explanation":"「统筹」指全面筹划、统一安排，与「推进」搭配且强调全局性；「统率」指率领；「兼顾」只强调同时照顾；「协调」侧重配合关系。故选B。","__sub":"选词填空"},{"id":"yy-15079","module":"yanyu","diff":3,"exam":"省考","prompt":"一个朴素的道理反复被验证：方向对了，努力才不会白费。要坚持问题导向，______基层治理，切实解决群众急难愁盼问题。这也正是成事的关键所在。填入画横线处最恰当的是：","options":["助力","赋能","赋权","加持"],"answer":1,"explanation":"「赋能」指赋予能力，是数字经济语境的规范表述；「赋权」指赋予权力；「加持」为口语化外来词；「助力」语义宽泛。故选B。","__sub":"选词填空"},{"id":"yy-15080","module":"yanyu","diff":3,"exam":"国考","prompt":"很多事看起来简单，真要做扎实并不容易。下一步，将______实体经济根基，推动各项工作再上新台阶。道理虽朴素，真正做到并不容易。填入画横线处最恰当的是：","options":["筑牢","厚植","培植","加深"],"answer":1,"explanation":"「厚植」指深厚培育，与「优势、底色、根基」搭配；「培植」多用于培育动植物或扶植势力；「加深」与「底色」搭配不当。故选B。","__sub":"选词填空"},{"id":"yy-15081","module":"yanyu","diff":1,"exam":"国考","prompt":"事物的发展自有其规律，顺应它才能事半功倍。下一步，将______优质医疗资源，推动各项工作再上新台阶。这样的要求，放在哪里都不过时。填入画横线处最恰当的是：","options":["下坠","下沉","下探","下潜"],"answer":1,"explanation":"「下沉」指治理资源向基层倾斜，是规范表述；「下潜」指潜水，「下探」多指价格或行动试探，「下坠」指物体坠落。故选B。","__sub":"选词填空"},{"id":"yy-15082","module":"yanyu","diff":1,"exam":"省考","prompt":"只有全年经济增长目标真正______到基层，才能让政策在「最后一公里」落地见效。填入画横线处最恰当的是：","options":["锚定","盯住","锁定","瞄准"],"answer":0,"explanation":"「锚定」比喻像锚一样固定住目标，多用于宏观战略语境；「锁定」「瞄准」「盯住」语体偏口语，庄重色彩不足。故选A。","__sub":"选词填空"},{"id":"yy-15083","module":"yanyu","diff":1,"exam":"教师编","prompt":"观察身边的事不难发现，成败的分野常常藏在细节里。当前正值关键时期，______资源配置刻不容缓，必须抓紧抓实抓出成效。说到底，拼的是态度，比的是功夫。填入画横线处最恰当的是：","options":["改善","改进","优化","调整"],"answer":2,"explanation":"「优化」指加以改变使其优良，与「环境、结构」搭配规范；「改善」多与「条件、生活」搭配；「改进」多与「方法、工作」搭配；「调整」不含变优之义。故选C。","__sub":"选词填空"},{"id":"yy-15086","module":"yanyu","diff":2,"exam":"国考","prompt":"无论时代如何变化，把事情做实做细始终是成事的基础。要坚持问题导向，______生态恶化的趋势，切实解决群众急难愁盼问题。这背后考验的正是把握分寸的智慧。填入画横线处最恰当的是：","options":["制止","遏止","遏制","控制"],"answer":2,"explanation":"「遏制」强调压制住势头、多与「势头/态势」搭配；「遏止」侧重使之停止，多用于具体行为；「控制」「制止」语义宽泛。故选C。","__sub":"选词填空"},{"id":"yy-15087","module":"yanyu","diff":2,"exam":"国考","prompt":"很多事看起来简单，真要做扎实并不容易。各级政府要持续______市场变化，不断增强群众的获得感、幸福感、安全感。道理虽朴素，真正做到并不容易。填入画横线处最恰当的是：","options":["把玩","把持","把守","把握"],"answer":3,"explanation":"「把握」与抽象事物（特点、规律、机遇）搭配；「把守」指守卫关口，「把持」含贬义指独揽，「把玩」指赏玩物品。故选D。","__sub":"选词填空"},{"id":"yy-15089","module":"yanyu","diff":3,"exam":"省考","prompt":"现实中，方法与态度不同，结果往往截然不同。回顾这些年走过的路，______公共服务水平始终是我们攻坚克难的重要法宝。看似寻常，实则是长期积累的结果。填入画横线处最恰当的是：","options":["提升","增强","提高","拔高"],"answer":0,"explanation":"「提升」与「效能、水平」搭配规范；「提高」语义相近但「提升」更书面；「增强」多与「能力、意识」搭配；「拔高」含贬义。故选A。","__sub":"选词填空"},{"id":"yy-15090","module":"yanyu","diff":3,"exam":"国考","prompt":"一个朴素的道理反复被验证：方向对了，努力才不会白费。下一步，将______底线思维，推动各项工作再上新台阶。这也正是成事的关键所在。填入画横线处最恰当的是：","options":["深化","加强","增强","强化"],"answer":3,"explanation":"「强化」与「意识、思维」搭配，强调使之更牢固；「增强」语义相近但搭配习惯不同；「加强」为通用动词；「深化」指向深处发展。故选D。","__sub":"选词填空"},{"id":"yy-15091","module":"yanyu","diff":1,"exam":"事业编","prompt":"无论时代如何变化，把事情做实做细始终是成事的基础。实践证明，______创新根基是推动高质量发展的关键一招。这背后考验的正是把握分寸的智慧。填入画横线处最恰当的是：","options":["筑牢","加深","厚植","培植"],"answer":2,"explanation":"「厚植」指深厚培育，与「优势、底色、根基」搭配；「培植」多用于培育动植物或扶植势力；「加深」与「底色」搭配不当。故选C。","__sub":"选词填空"},{"id":"yy-15092","module":"yanyu","diff":1,"exam":"省考","prompt":"事物的发展自有其规律，顺应它才能事半功倍。各级政府要持续______品格，不断增强群众的获得感、幸福感、安全感。这样的要求，放在哪里都不过时。填入画横线处最恰当的是：","options":["砥砺","磨砺","锤炼","锻炼"],"answer":0,"explanation":"「砥砺」本义为磨刀石，引申为磨炼，与「意志」搭配且语体庄重；「磨砺」与之近义但「砥砺」更常用于「砥砺前行、砥砺意志」。故选A。","__sub":"选词填空"},{"id":"yy-15093","module":"yanyu","diff":1,"exam":"省考","prompt":"观察身边的事不难发现，成败的分野常常藏在细节里。当前正值关键时期，______群众需求刻不容缓，必须抓紧抓实抓出成效。说到底，拼的是态度，比的是功夫。填入画横线处最恰当的是：","options":["把玩","把持","把握","把守"],"answer":2,"explanation":"「把握」与抽象事物（特点、规律、机遇）搭配；「把守」指守卫关口，「把持」含贬义指独揽，「把玩」指赏玩物品。故选C。","__sub":"选词填空"},{"id":"yy-15094","module":"yanyu","diff":2,"exam":"省考","prompt":"一个朴素的道理反复被验证：方向对了，努力才不会白费。各级政府要持续______公共服务，不断增强群众的获得感、幸福感、安全感。这也正是成事的关键所在。填入画横线处最恰当的是：","options":["下沉","下潜","下探","下坠"],"answer":0,"explanation":"「下沉」指治理资源向基层倾斜，是规范表述；「下潜」指潜水，「下探」多指价格或行动试探，「下坠」指物体坠落。故选A。","__sub":"选词填空"},{"id":"yy-15095","module":"yanyu","diff":2,"exam":"国考","prompt":"无论时代如何变化，把事情做实做细始终是成事的基础。实践证明，______监管责任是推动高质量发展的关键一招。这背后考验的正是把握分寸的智慧。填入画横线处最恰当的是：","options":["压紧","压实","落实","强化"],"answer":1,"explanation":"「压实」与「责任」搭配，强调责任层层落实到位；「落实」为通用动词；「压紧」常作「压紧压实」；「强化」不如「压实」精准体现层级传导。故选B。","__sub":"选词填空"},{"id":"yy-15097","module":"yanyu","diff":2,"exam":"国考","prompt":"干事创业，思路和坚持缺一不可。各地区各部门要拿出真招实招，______中小企业发展，确保各项部署落地生根。其中的道理值得每个人细细体会。填入画横线处最恰当的是：","options":["赋能","赋权","助力","加持"],"answer":0,"explanation":"「赋能」指赋予能力，是数字经济语境的规范表述；「赋权」指赋予权力；「加持」为口语化外来词；「助力」语义宽泛。故选A。","__sub":"选词填空"},{"id":"yy-15098","module":"yanyu","diff":2,"exam":"省考","prompt":"一个朴素的道理反复被验证：方向对了，努力才不会白费。当前正值关键时期，______数字化底座刻不容缓，必须抓紧抓实抓出成效。这也正是成事的关键所在。填入画横线处最恰当的是：","options":["打牢","夯实","巩固","筑牢"],"answer":1,"explanation":"「夯实」本义为砸实地基，引申为使稳固，与「基础、根基」搭配；「筑牢」与「防线」搭配；「打牢」语体稍口语；「巩固」侧重使已有的更牢固。故选B。","__sub":"选词填空"},{"id":"yy-15099","module":"yanyu","diff":3,"exam":"省考","prompt":"现实中，方法与态度不同，结果往往截然不同。要在______创新土壤上下更大功夫，让发展成果更多惠及全体人民。看似寻常，实则是长期积累的结果。填入画横线处最恰当的是：","options":["培养","养护","涵养","营造"],"answer":2,"explanation":"「涵养」指蓄积并养护，与「生态、水源」搭配；「培养」对象为人或能力；「营造」多与「氛围、环境」搭配；「养护」不含培育之义。故选C。","__sub":"选词填空"},{"id":"yy-15100","module":"yanyu","diff":3,"exam":"省考","prompt":"任何工作要见成效，都离不开科学的方法和踏实的作风。当前正值关键时期，______斗争精神刻不容缓，必须抓紧抓实抓出成效。唯有如此，才能把好事办好、实事办实。填入画横线处最恰当的是：","options":["锤炼","磨砺","锻炼","砥砺"],"answer":3,"explanation":"「砥砺」本义为磨刀石，引申为磨炼，与「意志」搭配且语体庄重；「磨砺」与之近义但「砥砺」更常用于「砥砺前行、砥砺意志」。故选D。","__sub":"选词填空"},{"id":"yy-15101","module":"yanyu","diff":1,"exam":"国考","prompt":"很多事看起来简单，真要做扎实并不容易。只有基础设施弱项真正______到基层，才能让政策在「最后一公里」落地见效。道理虽朴素，真正做到并不容易。填入画横线处最恰当的是：","options":["补齐","补足","弥补","填补"],"answer":0,"explanation":"「补齐」与「短板」为固定搭配，强调使达到应有水平；「补足」多与「差额」搭配；「填补」多与「空白」搭配；「弥补」多与「损失」搭配。故选A。","__sub":"选词填空"},{"id":"yy-15102","module":"yanyu","diff":1,"exam":"省考","prompt":"观察身边的事不难发现，成败的分野常常藏在细节里。新征程上，要继续______风险意识，以实干实绩回应人民期盼。说到底，拼的是态度，比的是功夫。填入画横线处最恰当的是：","options":["深化","加强","强化","增强"],"answer":2,"explanation":"「强化」与「意识、思维」搭配，强调使之更牢固；「增强」语义相近但搭配习惯不同；「加强」为通用动词；「深化」指向深处发展。故选C。","__sub":"选词填空"},{"id":"yy-15103","module":"yanyu","diff":1,"exam":"事业编","prompt":"干事创业，思路和坚持缺一不可。各地区各部门要拿出真招实招，______民意直达渠道，确保各项部署落地生根。其中的道理值得每个人细细体会。填入画横线处最恰当的是：","options":["开辟","畅通","打通","贯通"],"answer":1,"explanation":"「畅通」强调使通畅无阻，与「渠道、通道」搭配；「打通」侧重突破障碍；「贯通」指连接相通；「开辟」指新开路径。故选B。","__sub":"选词填空"},{"id":"yy-15105","module":"yanyu","diff":2,"exam":"国考","prompt":"事物的发展自有其规律，顺应它才能事半功倍。越是任务艰巨，越要______发展根基，确保方向不偏、力度不减。这样的要求，放在哪里都不过时。填入画横线处最恰当的是：","options":["巩固","打牢","夯实","筑牢"],"answer":2,"explanation":"「夯实」本义为砸实地基，引申为使稳固，与「基础、根基」搭配；「筑牢」与「防线」搭配；「打牢」语体稍口语；「巩固」侧重使已有的更牢固。故选C。","__sub":"选词填空"},{"id":"yy-15107","module":"yanyu","diff":2,"exam":"省考","prompt":"现实中，方法与态度不同，结果往往截然不同。新征程上，要继续______营商环境，以实干实绩回应人民期盼。看似寻常，实则是长期积累的结果。填入画横线处最恰当的是：","options":["改善","改进","调整","优化"],"answer":3,"explanation":"「优化」指加以改变使其优良，与「环境、结构」搭配规范；「改善」多与「条件、生活」搭配；「改进」多与「方法、工作」搭配；「调整」不含变优之义。故选D。","__sub":"选词填空"},{"id":"yy-15108","module":"yanyu","diff":2,"exam":"省考","prompt":"各级政府要持续______建设农业强国的目标，不断增强群众的获得感、幸福感、安全感。填入画横线处最恰当的是：","options":["锁定","盯住","瞄准","锚定"],"answer":3,"explanation":"「锚定」比喻像锚一样固定住目标，多用于宏观战略语境；「锁定」「瞄准」「盯住」语体偏口语，庄重色彩不足。故选D。","__sub":"选词填空"},{"id":"yy-15109","module":"yanyu","diff":3,"exam":"国考","prompt":"观察身边的事不难发现，成败的分野常常藏在细节里。各级政府要持续______资源配置，不断增强群众的获得感、幸福感、安全感。说到底，拼的是态度，比的是功夫。填入画横线处最恰当的是：","options":["改善","调整","改进","优化"],"answer":3,"explanation":"「优化」指加以改变使其优良，与「环境、结构」搭配规范；「改善」多与「条件、生活」搭配；「改进」多与「方法、工作」搭配；「调整」不含变优之义。故选D。","__sub":"选词填空"},{"id":"yy-15111","module":"yanyu","diff":1,"exam":"教师编","prompt":"无论时代如何变化，把事情做实做细始终是成事的基础。要在______改革红利上下更大功夫，让发展成果更多惠及全体人民。这背后考验的正是把握分寸的智慧。填入画横线处最恰当的是：","options":["发挥","释放","散发","爆发"],"answer":1,"explanation":"「释放」与「潜力、红利、活力」搭配；「散发」指分散发出；「发挥」与「作用」搭配；「爆发」指突然发作。故选B。","__sub":"选词填空"},{"id":"yy-15112","module":"yanyu","diff":1,"exam":"国考","prompt":"很多事看起来简单，真要做扎实并不容易。只有群众需求真正______到基层，才能让政策在「最后一公里」落地见效。道理虽朴素，真正做到并不容易。填入画横线处最恰当的是：","options":["把持","把握","把守","把玩"],"answer":1,"explanation":"「把握」与抽象事物（特点、规律、机遇）搭配；「把守」指守卫关口，「把持」含贬义指独揽，「把玩」指赏玩物品。故选B。","__sub":"选词填空"},{"id":"yy-15113","module":"yanyu","diff":1,"exam":"国考","prompt":"干事创业，思路和坚持缺一不可。新征程上，要继续______社会保障体系，以实干实绩回应人民期盼。其中的道理值得每个人细细体会。填入画横线处最恰当的是：","options":["建立","健全","构建","完善"],"answer":1,"explanation":"「健全」强调使完备无缺，与「体系」搭配规范；「建立」指从无到有，「完善」指补足短板，「构建」侧重搭建框架。故选B。","__sub":"选词填空"},{"id":"yy-15114","module":"yanyu","diff":2,"exam":"省考","prompt":"无论时代如何变化，把事情做实做细始终是成事的基础。回顾这些年走过的路，______安全稳定底线始终是我们攻坚克难的重要法宝。这背后考验的正是把握分寸的智慧。填入画横线处最恰当的是：","options":["防住","守住","守牢","把牢"],"answer":2,"explanation":"「守牢」与「底线」搭配，强调牢牢守住；「守住」程度稍弱；「把牢」多与「关口」搭配；「防住」为口语。故选C。","__sub":"选词填空"},{"id":"yy-15117","module":"yanyu","diff":2,"exam":"国考","prompt":"现实中，方法与态度不同，结果往往截然不同。面对新形势新任务，必须______市场变化，牢牢把握发展主动权。看似寻常，实则是长期积累的结果。填入画横线处最恰当的是：","options":["把守","把玩","把持","把握"],"answer":3,"explanation":"「把握」与抽象事物（特点、规律、机遇）搭配；「把守」指守卫关口，「把持」含贬义指独揽，「把玩」指赏玩物品。故选D。","__sub":"选词填空"},{"id":"yy-15119","module":"yanyu","diff":3,"exam":"省考","prompt":"事物的发展自有其规律，顺应它才能事半功倍。要坚持问题导向，______公共服务，切实解决群众急难愁盼问题。这样的要求，放在哪里都不过时。填入画横线处最恰当的是：","options":["下沉","下探","下潜","下坠"],"answer":0,"explanation":"「下沉」指治理资源向基层倾斜，是规范表述；「下潜」指潜水，「下探」多指价格或行动试探，「下坠」指物体坠落。故选A。","__sub":"选词填空"},{"id":"yy-15120","module":"yanyu","diff":3,"exam":"事业编","prompt":"现实中，方法与态度不同，结果往往截然不同。下一步，将______政策导向，推动各项工作再上新台阶。看似寻常，实则是长期积累的结果。填入画横线处最恰当的是：","options":["把玩","把守","把握","把持"],"answer":2,"explanation":"「把握」与抽象事物（特点、规律、机遇）搭配；「把守」指守卫关口，「把持」含贬义指独揽，「把玩」指赏玩物品。故选C。","__sub":"选词填空"},{"id":"yy-15123","module":"yanyu","diff":1,"exam":"国考","prompt":"一个朴素的道理反复被验证：方向对了，努力才不会白费。面对新形势新任务，必须______共同思想基础，牢牢把握发展主动权。这也正是成事的关键所在。填入画横线处最恰当的是：","options":["筑牢","夯实","打牢","巩固"],"answer":1,"explanation":"「夯实」本义为砸实地基，引申为使稳固，与「基础、根基」搭配；「筑牢」与「防线」搭配；「打牢」语体稍口语；「巩固」侧重使已有的更牢固。故选B。","__sub":"选词填空"},{"id":"yy-15125","module":"yanyu","diff":2,"exam":"省考","prompt":"无论时代如何变化，把事情做实做细始终是成事的基础。实践证明，______基层治理是推动高质量发展的关键一招。这背后考验的正是把握分寸的智慧。填入画横线处最恰当的是：","options":["助力","赋权","加持","赋能"],"answer":3,"explanation":"「赋能」指赋予能力，是数字经济语境的规范表述；「赋权」指赋予权力；「加持」为口语化外来词；「助力」语义宽泛。故选D。","__sub":"选词填空"},{"id":"yy-15126","module":"yanyu","diff":2,"exam":"省考","prompt":"无论时代如何变化，把事情做实做细始终是成事的基础。回顾这些年走过的路，______服务空白始终是我们攻坚克难的重要法宝。这背后考验的正是把握分寸的智慧。填入画横线处最恰当的是：","options":["填补","补足","弥补","补齐"],"answer":3,"explanation":"「补齐」与「短板」为固定搭配，强调使达到应有水平；「补足」多与「差额」搭配；「填补」多与「空白」搭配；「弥补」多与「损失」搭配。故选D。","__sub":"选词填空"},{"id":"yy-15127","module":"yanyu","diff":2,"exam":"事业编","prompt":"无论时代如何变化，把事情做实做细始终是成事的基础。当前正值关键时期，______腐败蔓延的态势刻不容缓，必须抓紧抓实抓出成效。这背后考验的正是把握分寸的智慧。填入画横线处最恰当的是：","options":["遏止","制止","遏制","控制"],"answer":2,"explanation":"「遏制」强调压制住势头、多与「势头/态势」搭配；「遏止」侧重使之停止，多用于具体行为；「控制」「制止」语义宽泛。故选C。","__sub":"选词填空"},{"id":"yy-15128","module":"yanyu","diff":2,"exam":"国考","prompt":"事物的发展自有其规律，顺应它才能事半功倍。要在______群众需求上下更大功夫，让发展成果更多惠及全体人民。这样的要求，放在哪里都不过时。填入画横线处最恰当的是：","options":["把玩","把守","把握","把持"],"answer":2,"explanation":"「把握」与抽象事物（特点、规律、机遇）搭配；「把守」指守卫关口，「把持」含贬义指独揽，「把玩」指赏玩物品。故选C。","__sub":"选词填空"},{"id":"yy-15129","module":"yanyu","diff":3,"exam":"医疗编","prompt":"各地区各部门要拿出真招实招，______现代化建设的宏伟篇章，确保各项部署落地生根。填入画横线处最恰当的是：","options":["擘画","描绘","勾画","规划"],"answer":0,"explanation":"「擘画」指筹划布置，多用于宏观蓝图，书面色彩浓；「描绘」「勾画」偏具体画面；「规划」语体色彩不足。故选A。","__sub":"选词填空"},{"id":"yy-15130","module":"yanyu","diff":3,"exam":"国考","prompt":"观察身边的事不难发现，成败的分野常常藏在细节里。面对新形势新任务，必须______资源、服务、管理，牢牢把握发展主动权。说到底，拼的是态度，比的是功夫。填入画横线处最恰当的是：","options":["下沉","下坠","下探","下潜"],"answer":0,"explanation":"「下沉」指治理资源向基层倾斜，是规范表述；「下潜」指潜水，「下探」多指价格或行动试探，「下坠」指物体坠落。故选A。","__sub":"选词填空"},{"id":"yy-15131","module":"yanyu","diff":1,"exam":"省考","prompt":"观察身边的事不难发现，成败的分野常常藏在细节里。实践证明，______推进重点领域改革是推动高质量发展的关键一招。说到底，拼的是态度，比的是功夫。填入画横线处最恰当的是：","options":["统率","兼顾","统筹","协调"],"answer":2,"explanation":"「统筹」指全面筹划、统一安排，与「推进」搭配且强调全局性；「统率」指率领；「兼顾」只强调同时照顾；「协调」侧重配合关系。故选C。","__sub":"选词填空"},{"id":"yy-15134","module":"yanyu","diff":2,"exam":"国考","prompt":"无论时代如何变化，把事情做实做细始终是成事的基础。只有政企沟通机制真正______到基层，才能让政策在「最后一公里」落地见效。这背后考验的正是把握分寸的智慧。填入画横线处最恰当的是：","options":["打通","开拓","畅通","疏通"],"answer":2,"explanation":"「畅通」强调使通畅无阻，与「渠道」为固定搭配；「打通」侧重突破障碍；「疏通」多用于管道或疏导矛盾；「开拓」指开辟新领域。故选C。","__sub":"选词填空"},{"id":"yy-15135","module":"yanyu","diff":2,"exam":"省考","prompt":"无论时代如何变化，把事情做实做细始终是成事的基础。各级政府要持续______基层治理，不断增强群众的获得感、幸福感、安全感。这背后考验的正是把握分寸的智慧。填入画横线处最恰当的是：","options":["助力","加持","赋权","赋能"],"answer":3,"explanation":"「赋能」指赋予能力，是数字经济语境的规范表述；「赋权」指赋予权力；「加持」为口语化外来词；「助力」语义宽泛。故选D。","__sub":"选词填空"},{"id":"yy-15136","module":"yanyu","diff":2,"exam":"教师编","prompt":"任何工作要见成效，都离不开科学的方法和踏实的作风。下一步，将______就业促进机制，推动各项工作再上新台阶。唯有如此，才能把好事办好、实事办实。填入画横线处最恰当的是：","options":["构建","完善","健全","搭建"],"answer":2,"explanation":"「健全」强调使完备无缺；「完善」指补足短板；「构建」「搭建」侧重从无到有搭建。故选C。","__sub":"选词填空"},{"id":"yy-15137","module":"yanyu","diff":2,"exam":"省考","prompt":"一个朴素的道理反复被验证：方向对了，努力才不会白费。只有视野和思路真正______到基层，才能让政策在「最后一公里」落地见效。这也正是成事的关键所在。填入画横线处最恰当的是：","options":["延伸","开拓","拓宽","扩大"],"answer":2,"explanation":"「拓宽」与「渠道、门路、视野」搭配；「开拓」指开辟新领域；「扩大」多与「规模、范围」搭配；「延伸」侧重长度延长。故选C。","__sub":"选词填空"},{"id":"yy-15138","module":"yanyu","diff":2,"exam":"国考","prompt":"观察身边的事不难发现，成败的分野常常藏在细节里。各地区各部门要拿出真招实招，______发展规律，确保各项部署落地生根。说到底，拼的是态度，比的是功夫。填入画横线处最恰当的是：","options":["把持","把握","把玩","把守"],"answer":1,"explanation":"「把握」与抽象事物（特点、规律、机遇）搭配；「把守」指守卫关口，「把持」含贬义指独揽，「把玩」指赏玩物品。故选B。","__sub":"选词填空"},{"id":"yy-15139","module":"yanyu","diff":3,"exam":"医疗编","prompt":"各地区各部门要拿出真招实招，______区域协调发展的新格局，确保各项部署落地生根。填入画横线处最恰当的是：","options":["规划","描绘","擘画","勾画"],"answer":2,"explanation":"「擘画」指筹划布置，多用于宏观蓝图，书面色彩浓；「描绘」「勾画」偏具体画面；「规划」语体色彩不足。故选C。","__sub":"选词填空"},{"id":"yy-15140","module":"yanyu","diff":3,"exam":"省考","prompt":"事物的发展自有其规律，顺应它才能事半功倍。下一步，将______市场变化，推动各项工作再上新台阶。这样的要求，放在哪里都不过时。填入画横线处最恰当的是：","options":["把玩","把守","把握","把持"],"answer":2,"explanation":"「把握」与抽象事物（特点、规律、机遇）搭配；「把守」指守卫关口，「把持」含贬义指独揽，「把玩」指赏玩物品。故选C。","__sub":"选词填空"},{"id":"yy-15141","module":"yanyu","diff":1,"exam":"国考","prompt":"一个朴素的道理反复被验证：方向对了，努力才不会白费。实践证明，______新时代发展的宏伟蓝图是推动高质量发展的关键一招。这也正是成事的关键所在。填入画横线处最恰当的是：","options":["勾画","规划","擘画","描绘"],"answer":2,"explanation":"「擘画」指筹划布置，多用于宏观蓝图，书面色彩浓；「描绘」「勾画」偏具体画面；「规划」语体色彩不足。故选C。","__sub":"选词填空"},{"id":"yy-15142","module":"yanyu","diff":1,"exam":"省考","prompt":"现实中，方法与态度不同，结果往往截然不同。各地区各部门要拿出真招实招，______生态保护红线，确保各项部署落地生根。看似寻常，实则是长期积累的结果。填入画横线处最恰当的是：","options":["把牢","守住","守牢","防住"],"answer":2,"explanation":"「守牢」与「底线」搭配，强调牢牢守住；「守住」程度稍弱；「把牢」多与「关口」搭配；「防住」为口语。故选C。","__sub":"选词填空"},{"id":"yy-15144","module":"yanyu","diff":2,"exam":"国考","prompt":"观察身边的事不难发现，成败的分野常常藏在细节里。下一步，将______制度漏洞，推动各项工作再上新台阶。说到底，拼的是态度，比的是功夫。填入画横线处最恰当的是：","options":["补齐","填补","补足","弥补"],"answer":0,"explanation":"「补齐」与「短板」为固定搭配，强调使达到应有水平；「补足」多与「差额」搭配；「填补」多与「空白」搭配；「弥补」多与「损失」搭配。故选A。","__sub":"选词填空"},{"id":"yy-15145","module":"yanyu","diff":2,"exam":"教师编","prompt":"现实中，方法与态度不同，结果往往截然不同。当前正值关键时期，______创新创造潜能刻不容缓，必须抓紧抓实抓出成效。看似寻常，实则是长期积累的结果。填入画横线处最恰当的是：","options":["点燃","激发","引发","调动"],"answer":1,"explanation":"「激发」与「活力、热情、潜能」为固定搭配；「引发」多与「关注、争议」搭配；「点燃」为比喻用法；「调动」多与「积极性」搭配。故选B。","__sub":"选词填空"},{"id":"yy-15146","module":"yanyu","diff":2,"exam":"事业编","prompt":"现实中，方法与态度不同，结果往往截然不同。当前正值关键时期，______资源、服务、管理刻不容缓，必须抓紧抓实抓出成效。看似寻常，实则是长期积累的结果。填入画横线处最恰当的是：","options":["下坠","下潜","下探","下沉"],"answer":3,"explanation":"「下沉」指治理资源向基层倾斜，是规范表述；「下潜」指潜水，「下探」多指价格或行动试探，「下坠」指物体坠落。故选D。","__sub":"选词填空"},{"id":"yy-15147","module":"yanyu","diff":2,"exam":"省考","prompt":"一个朴素的道理反复被验证：方向对了，努力才不会白费。当前正值关键时期，______底线思维刻不容缓，必须抓紧抓实抓出成效。这也正是成事的关键所在。填入画横线处最恰当的是：","options":["增强","加强","强化","深化"],"answer":2,"explanation":"「强化」与「意识、思维」搭配，强调使之更牢固；「增强」语义相近但搭配习惯不同；「加强」为通用动词；「深化」指向深处发展。故选C。","__sub":"选词填空"},{"id":"yy-15148","module":"yanyu","diff":2,"exam":"国考","prompt":"很多事看起来简单，真要做扎实并不容易。越是任务艰巨，越要______安全事故多发的势头，确保方向不偏、力度不减。道理虽朴素，真正做到并不容易。填入画横线处最恰当的是：","options":["控制","遏止","遏制","制止"],"answer":2,"explanation":"「遏制」强调压制住势头、多与「势头/态势」搭配；「遏止」侧重使之停止，多用于具体行为；「控制」「制止」语义宽泛。故选C。","__sub":"选词填空"},{"id":"yy-15149","module":"yanyu","diff":3,"exam":"国考","prompt":"一个朴素的道理反复被验证：方向对了，努力才不会白费。越是任务艰巨，越要______营商环境，确保方向不偏、力度不减。这也正是成事的关键所在。填入画横线处最恰当的是：","options":["优化","调整","改善","改进"],"answer":0,"explanation":"「优化」指加以改变使其优良，与「环境、结构」搭配规范；「改善」多与「条件、生活」搭配；「改进」多与「方法、工作」搭配；「调整」不含变优之义。故选A。","__sub":"选词填空"},{"id":"yy-15151","module":"yanyu","diff":1,"exam":"国考","prompt":"任何工作要见成效，都离不开科学的方法和踏实的作风。要坚持问题导向，______监督机制，切实解决群众急难愁盼问题。唯有如此，才能把好事办好、实事办实。填入画横线处最恰当的是：","options":["完善","健全","建立","构建"],"answer":1,"explanation":"「健全」强调使完备无缺，与「体系」搭配规范；「建立」指从无到有，「完善」指补足短板，「构建」侧重搭建框架。故选B。","__sub":"选词填空"},{"id":"yy-15152","module":"yanyu","diff":1,"exam":"国考","prompt":"任何工作要见成效，都离不开科学的方法和踏实的作风。要在______科技成果转化路径上下更大功夫，让发展成果更多惠及全体人民。唯有如此，才能把好事办好、实事办实。填入画横线处最恰当的是：","options":["打通","畅通","开拓","疏通"],"answer":1,"explanation":"「畅通」强调使通畅无阻，与「渠道」为固定搭配；「打通」侧重突破障碍；「疏通」多用于管道或疏导矛盾；「开拓」指开辟新领域。故选B。","__sub":"选词填空"},{"id":"yy-15154","module":"yanyu","diff":2,"exam":"事业编","prompt":"很多事看起来简单，真要做扎实并不容易。当前正值关键时期，______基层基础刻不容缓，必须抓紧抓实抓出成效。道理虽朴素，真正做到并不容易。填入画横线处最恰当的是：","options":["打牢","巩固","筑牢","夯实"],"answer":3,"explanation":"「夯实」本义为砸实地基，引申为使稳固，与「基础、根基」搭配；「筑牢」与「防线」搭配；「打牢」语体稍口语；「巩固」侧重使已有的更牢固。故选D。","__sub":"选词填空"},{"id":"yy-15155","module":"yanyu","diff":2,"exam":"事业编","prompt":"任何工作要见成效，都离不开科学的方法和踏实的作风。回顾这些年走过的路，______发展规律始终是我们攻坚克难的重要法宝。唯有如此，才能把好事办好、实事办实。填入画横线处最恰当的是：","options":["把握","把守","把持","把玩"],"answer":0,"explanation":"「把握」与抽象事物（特点、规律、机遇）搭配；「把守」指守卫关口，「把持」含贬义指独揽，「把玩」指赏玩物品。故选A。","__sub":"选词填空"},{"id":"yy-15157","module":"yanyu","diff":2,"exam":"省考","prompt":"任何工作要见成效，都离不开科学的方法和踏实的作风。当前正值关键时期，______专精特新企业刻不容缓，必须抓紧抓实抓出成效。唯有如此，才能把好事办好、实事办实。填入画横线处最恰当的是：","options":["培养","培植","培育","孕育"],"answer":2,"explanation":"「培育」与「产业、企业、市场」搭配；「培养」对象为人或能力；「培植」多用于动植物或含贬义；「孕育」强调正在形成。故选C。","__sub":"选词填空"},{"id":"yy-15158","module":"yanyu","diff":2,"exam":"事业编","prompt":"事物的发展自有其规律，顺应它才能事半功倍。越是任务艰巨，越要______房价过快上涨的势头，确保方向不偏、力度不减。这样的要求，放在哪里都不过时。填入画横线处最恰当的是：","options":["遏止","遏制","制止","控制"],"answer":1,"explanation":"「遏制」强调压制住势头、多与「势头/态势」搭配；「遏止」侧重使之停止，多用于具体行为；「控制」「制止」语义宽泛。故选B。","__sub":"选词填空"},{"id":"yy-15159","module":"yanyu","diff":3,"exam":"省考","prompt":"任何工作要见成效，都离不开科学的方法和踏实的作风。要在______政企沟通机制上下更大功夫，让发展成果更多惠及全体人民。唯有如此，才能把好事办好、实事办实。填入画横线处最恰当的是：","options":["疏通","畅通","开拓","打通"],"answer":1,"explanation":"「畅通」强调使通畅无阻，与「渠道」为固定搭配；「打通」侧重突破障碍；「疏通」多用于管道或疏导矛盾；「开拓」指开辟新领域。故选B。","__sub":"选词填空"},{"id":"yy-15160","module":"yanyu","diff":3,"exam":"省考","prompt":"一个朴素的道理反复被验证：方向对了，努力才不会白费。新征程上，要继续______公共服务，以实干实绩回应人民期盼。这也正是成事的关键所在。填入画横线处最恰当的是：","options":["下探","下潜","下坠","下沉"],"answer":3,"explanation":"「下沉」指治理资源向基层倾斜，是规范表述；「下潜」指潜水，「下探」多指价格或行动试探，「下坠」指物体坠落。故选D。","__sub":"选词填空"},{"id":"yy-15162","module":"yanyu","diff":1,"exam":"省考","prompt":"干事创业，思路和坚持缺一不可。新征程上，要继续______城市文化气质，以实干实绩回应人民期盼。其中的道理值得每个人细细体会。填入画横线处最恰当的是：","options":["培养","养护","营造","涵养"],"answer":3,"explanation":"「涵养」指蓄积并养护，与「生态、水源」搭配；「培养」对象为人或能力；「营造」多与「氛围、环境」搭配；「养护」不含培育之义。故选D。","__sub":"选词填空"},{"id":"yy-15163","module":"yanyu","diff":1,"exam":"事业编","prompt":"观察身边的事不难发现，成败的分野常常藏在细节里。越是任务艰巨，越要______文明乡风，确保方向不偏、力度不减。说到底，拼的是态度，比的是功夫。填入画横线处最恰当的是：","options":["营造","养护","培养","涵养"],"answer":3,"explanation":"「涵养」指蓄积并养护，与「生态、水源」搭配；「培养」对象为人或能力；「营造」多与「氛围、环境」搭配；「养护」不含培育之义。故选D。","__sub":"选词填空"},{"id":"yy-15164","module":"yanyu","diff":2,"exam":"国考","prompt":"事物的发展自有其规律，顺应它才能事半功倍。各地区各部门要拿出真招实招，______优质医疗资源，确保各项部署落地生根。这样的要求，放在哪里都不过时。填入画横线处最恰当的是：","options":["下坠","下潜","下沉","下探"],"answer":2,"explanation":"「下沉」指治理资源向基层倾斜，是规范表述；「下潜」指潜水，「下探」多指价格或行动试探，「下坠」指物体坠落。故选C。","__sub":"选词填空"},{"id":"yy-15165","module":"yanyu","diff":2,"exam":"事业编","prompt":"现实中，方法与态度不同，结果往往截然不同。要坚持问题导向，______实体经济根基，切实解决群众急难愁盼问题。看似寻常，实则是长期积累的结果。填入画横线处最恰当的是：","options":["培植","筑牢","加深","厚植"],"answer":3,"explanation":"「厚植」指深厚培育，与「优势、底色、根基」搭配；「培植」多用于培育动植物或扶植势力；「加深」与「底色」搭配不当。故选D。","__sub":"选词填空"},{"id":"yy-15166","module":"yanyu","diff":2,"exam":"省考","prompt":"任何工作要见成效，都离不开科学的方法和踏实的作风。越是任务艰巨，越要______资源、服务、管理，确保方向不偏、力度不减。唯有如此，才能把好事办好、实事办实。填入画横线处最恰当的是：","options":["下坠","下潜","下探","下沉"],"answer":3,"explanation":"「下沉」指治理资源向基层倾斜，是规范表述；「下潜」指潜水，「下探」多指价格或行动试探，「下坠」指物体坠落。故选D。","__sub":"选词填空"},{"id":"yy-15167","module":"yanyu","diff":2,"exam":"国考","prompt":"干事创业，思路和坚持缺一不可。各地区各部门要拿出真招实招，______就业门路，确保各项部署落地生根。其中的道理值得每个人细细体会。填入画横线处最恰当的是：","options":["拓宽","延伸","扩大","开拓"],"answer":0,"explanation":"「拓宽」与「渠道、门路、视野」搭配；「开拓」指开辟新领域；「扩大」多与「规模、范围」搭配；「延伸」侧重长度延长。故选A。","__sub":"选词填空"},{"id":"yy-15168","module":"yanyu","diff":2,"exam":"省考","prompt":"干事创业，思路和坚持缺一不可。要坚持问题导向，______专精特新企业，切实解决群众急难愁盼问题。其中的道理值得每个人细细体会。填入画横线处最恰当的是：","options":["培养","孕育","培育","培植"],"answer":2,"explanation":"「培育」与「产业、企业、市场」搭配；「培养」对象为人或能力；「培植」多用于动植物或含贬义；「孕育」强调正在形成。故选C。","__sub":"选词填空"},{"id":"yy-15169","module":"yanyu","diff":3,"exam":"省考","prompt":"各级政府要持续______房价过快上涨的势头，不断增强群众的获得感、幸福感、安全感。填入画横线处最恰当的是：","options":["遏止","控制","遏制","制止"],"answer":2,"explanation":"「遏制」强调压制住势头、多与「势头/态势」搭配；「遏止」侧重使之停止，多用于具体行为；「控制」「制止」语义宽泛。故选C。","__sub":"选词填空"},{"id":"yy-15170","module":"yanyu","diff":3,"exam":"国考","prompt":"现实中，方法与态度不同，结果往往截然不同。实践证明，______沉睡的资源要素是推动高质量发展的关键一招。看似寻常，实则是长期积累的结果。填入画横线处最恰当的是：","options":["启动","唤醒","激活","驱动"],"answer":2,"explanation":"「激活」指刺激使之活跃，与「动力、要素」搭配；「唤醒」指使之觉醒；「启动」指开始进行；「驱动」指推动运转。故选C。","__sub":"选词填空"},{"id":"yy-15171","module":"yanyu","diff":1,"exam":"省考","prompt":"事物的发展自有其规律，顺应它才能事半功倍。下一步，将______区域协作机制，推动各项工作再上新台阶。这样的要求，放在哪里都不过时。填入画横线处最恰当的是：","options":["加强","深化","推进","深入"],"answer":1,"explanation":"「深化」指向更深阶段发展，与「改革」为固定搭配；「深入」多作形容词或「深入调查」；「加强」「推进」语义宽泛。故选B。","__sub":"选词填空"},{"id":"yy-15173","module":"yanyu","diff":1,"exam":"省考","prompt":"观察身边的事不难发现，成败的分野常常藏在细节里。各地区各部门要拿出真招实招，______属地管理责任，确保各项部署落地生根。说到底，拼的是态度，比的是功夫。填入画横线处最恰当的是：","options":["压紧","落实","压实","强化"],"answer":2,"explanation":"「压实」与「责任」搭配，强调责任层层落实到位；「落实」为通用动词；「压紧」常作「压紧压实」；「强化」不如「压实」精准体现层级传导。故选C。","__sub":"选词填空"},{"id":"yy-15174","module":"yanyu","diff":2,"exam":"省考","prompt":"无论时代如何变化，把事情做实做细始终是成事的基础。回顾这些年走过的路，______市场变化始终是我们攻坚克难的重要法宝。道理虽朴素，真正做到并不容易。填入画横线处最恰当的是：","options":["把握","把持","把玩","把守"],"answer":0,"explanation":"「把握」与抽象事物（特点、规律、机遇）搭配；「把守」指守卫关口，「把持」含贬义指独揽，「把玩」指赏玩物品。故选A。","__sub":"选词填空"},{"id":"yy-15179","module":"yanyu","diff":3,"exam":"事业编","prompt":"观察身边的事不难发现，成败的分野常常藏在细节里。回顾这些年走过的路，______廉洁底线始终是我们攻坚克难的重要法宝。说到底，拼的是态度，比的是功夫。填入画横线处最恰当的是：","options":["夯实","构建","筑造","筑牢"],"answer":3,"explanation":"「筑牢」与「防线」为固定搭配，强调使牢固；「筑造」指建造实体；「构建」侧重搭建体系；「夯实」多与「基础」搭配。故选D。","__sub":"选词填空"},{"id":"yy-15180","module":"yanyu","diff":3,"exam":"国考","prompt":"无论时代如何变化，把事情做实做细始终是成事的基础。各地区各部门要拿出真招实招，______政策导向，确保各项部署落地生根。道理虽朴素，真正做到并不容易。填入画横线处最恰当的是：","options":["把握","把守","把玩","把持"],"answer":0,"explanation":"「把握」与抽象事物（特点、规律、机遇）搭配；「把守」指守卫关口，「把持」含贬义指独揽，「把玩」指赏玩物品。故选A。","__sub":"选词填空"},{"id":"yy-15181","module":"yanyu","diff":1,"exam":"省考","prompt":"现实中，方法与态度不同，结果往往截然不同。面对新形势新任务，必须______安全底线，牢牢把握发展主动权。看似寻常，实则是长期积累的结果。填入画横线处最恰当的是：","options":["筑牢","筑造","构建","夯实"],"answer":0,"explanation":"「筑牢」与「防线」为固定搭配，强调使牢固；「筑造」指建造实体；「构建」侧重搭建体系；「夯实」多与「基础」搭配。故选A。","__sub":"选词填空"},{"id":"yy-15182","module":"yanyu","diff":1,"exam":"国考","prompt":"事物的发展自有其规律，顺应它才能事半功倍。新征程上，要继续______政策效应，以实干实绩回应人民期盼。这样的要求，放在哪里都不过时。填入画横线处最恰当的是：","options":["释放","爆发","散发","发挥"],"answer":0,"explanation":"「释放」与「潜力、红利、活力」搭配；「散发」指分散发出；「发挥」与「作用」搭配；「爆发」指突然发作。故选A。","__sub":"选词填空"},{"id":"yy-15183","module":"yanyu","diff":1,"exam":"医疗编","prompt":"观察身边的事不难发现，成败的分野常常藏在细节里。要坚持问题导向，______公共服务水平，切实解决群众急难愁盼问题。说到底，拼的是态度，比的是功夫。填入画横线处最恰当的是：","options":["增强","提高","拔高","提升"],"answer":3,"explanation":"「提升」与「效能、水平」搭配规范；「提高」语义相近但「提升」更书面；「增强」多与「能力、意识」搭配；「拔高」含贬义。故选D。","__sub":"选词填空"},{"id":"yy-15185","module":"yanyu","diff":2,"exam":"国考","prompt":"一个朴素的道理反复被验证：方向对了，努力才不会白费。要在______改革任务书上下更大功夫，让发展成果更多惠及全体人民。这也正是成事的关键所在。填入画横线处最恰当的是：","options":["瞄准","锚定","盯住","锁定"],"answer":1,"explanation":"「锚定」比喻像锚一样固定住目标，多用于宏观战略语境；「锁定」「瞄准」「盯住」语体偏口语，庄重色彩不足。故选B。","__sub":"选词填空"},{"id":"yy-15187","module":"yanyu","diff":2,"exam":"医疗编","prompt":"现实中，方法与态度不同，结果往往截然不同。要在______社会保障体系上下更大功夫，让发展成果更多惠及全体人民。看似寻常，实则是长期积累的结果。填入画横线处最恰当的是：","options":["建立","完善","健全","构建"],"answer":2,"explanation":"「健全」强调使完备无缺，与「体系」搭配规范；「建立」指从无到有，「完善」指补足短板，「构建」侧重搭建框架。故选C。","__sub":"选词填空"},{"id":"yy-15188","module":"yanyu","diff":2,"exam":"省考","prompt":"干事创业，思路和坚持缺一不可。要在______城市建设各环节上下更大功夫，让发展成果更多惠及全体人民。其中的道理值得每个人细细体会。填入画横线处最恰当的是：","options":["贯穿","经过","穿过","贯串"],"answer":0,"explanation":"「贯穿」指从头到尾通贯，与「全过程」搭配规范；「穿过」「经过」仅指空间或时间经过，不含通贯始终之义。故选A。","__sub":"选词填空"},{"id":"yy-15189","module":"yanyu","diff":3,"exam":"事业编","prompt":"很多事看起来简单，真要做扎实并不容易。新征程上，要继续______共同思想基础，以实干实绩回应人民期盼。道理虽朴素，真正做到并不容易。填入画横线处最恰当的是：","options":["筑牢","夯实","巩固","打牢"],"answer":1,"explanation":"「夯实」本义为砸实地基，引申为使稳固，与「基础、根基」搭配；「筑牢」与「防线」搭配；「打牢」语体稍口语；「巩固」侧重使已有的更牢固。故选B。","__sub":"选词填空"},{"id":"yy-15190","module":"yanyu","diff":3,"exam":"国考","prompt":"各地区各部门要拿出真招实招，______全年经济增长目标，确保各项部署落地生根。填入画横线处最恰当的是：","options":["锁定","盯住","锚定","瞄准"],"answer":2,"explanation":"「锚定」比喻像锚一样固定住目标，多用于宏观战略语境；「锁定」「瞄准」「盯住」语体偏口语，庄重色彩不足。故选C。","__sub":"选词填空"},{"id":"yy-15192","module":"yanyu","diff":1,"exam":"事业编","prompt":"干事创业，思路和坚持缺一不可。要在______就业服务体系上下更大功夫，让发展成果更多惠及全体人民。其中的道理值得每个人细细体会。填入画横线处最恰当的是：","options":["健全","构建","完善","建立"],"answer":0,"explanation":"「健全」强调使完备无缺，与「体系」搭配规范；「建立」指从无到有，「完善」指补足短板，「构建」侧重搭建框架。故选A。","__sub":"选词填空"},{"id":"yy-15193","module":"yanyu","diff":1,"exam":"国考","prompt":"干事创业，思路和坚持缺一不可。下一步，将______科技成果转化路径，推动各项工作再上新台阶。其中的道理值得每个人细细体会。填入画横线处最恰当的是：","options":["打通","疏通","开拓","畅通"],"answer":3,"explanation":"「畅通」强调使通畅无阻，与「渠道」为固定搭配；「打通」侧重突破障碍；「疏通」多用于管道或疏导矛盾；「开拓」指开辟新领域。故选D。","__sub":"选词填空"},{"id":"yy-15195","module":"yanyu","diff":2,"exam":"国考","prompt":"任何工作要见成效，都离不开科学的方法和踏实的作风。各级政府要持续______爱国情怀，不断增强群众的获得感、幸福感、安全感。唯有如此，才能把好事办好、实事办实。填入画横线处最恰当的是：","options":["加深","厚植","培植","筑牢"],"answer":1,"explanation":"「厚植」指深厚培育，与「优势、底色、根基」搭配；「培植」多用于培育动植物或扶植势力；「加深」与「底色」搭配不当。故选B。","__sub":"选词填空"},{"id":"yy-15197","module":"yanyu","diff":2,"exam":"省考","prompt":"回顾这些年走过的路，______乡村振兴的壮美画卷始终是我们攻坚克难的重要法宝。填入画横线处最恰当的是：","options":["规划","擘画","勾画","描绘"],"answer":1,"explanation":"「擘画」指筹划布置，多用于宏观蓝图，书面色彩浓；「描绘」「勾画」偏具体画面；「规划」语体色彩不足。故选B。","__sub":"选词填空"},{"id":"yy-15198","module":"yanyu","diff":2,"exam":"省考","prompt":"任何工作要见成效，都离不开科学的方法和踏实的作风。下一步，将______城市建设各环节，推动各项工作再上新台阶。唯有如此，才能把好事办好、实事办实。填入画横线处最恰当的是：","options":["贯穿","经过","穿过","贯串"],"answer":0,"explanation":"「贯穿」指从头到尾通贯，与「全过程」搭配规范；「穿过」「经过」仅指空间或时间经过，不含通贯始终之义。故选A。","__sub":"选词填空"},{"id":"yy-15199","module":"yanyu","diff":3,"exam":"省考","prompt":"事物的发展自有其规律，顺应它才能事半功倍。各级政府要持续______覆盖范围，不断增强群众的获得感、幸福感、安全感。这样的要求，放在哪里都不过时。填入画横线处最恰当的是：","options":["扩大","延伸","拓宽","开拓"],"answer":2,"explanation":"「拓宽」与「渠道、门路、视野」搭配；「开拓」指开辟新领域；「扩大」多与「规模、范围」搭配；「延伸」侧重长度延长。故选C。","__sub":"选词填空"},{"id":"yy-15200","module":"yanyu","diff":3,"exam":"省考","prompt":"很多事看起来简单，真要做扎实并不容易。要在______各类资源配置上下更大功夫，让发展成果更多惠及全体人民。道理虽朴素，真正做到并不容易。填入画横线处最恰当的是：","options":["统筹","统率","兼顾","协调"],"answer":0,"explanation":"「统筹」指全面筹划、统一安排，与「推进」搭配且强调全局性；「统率」指率领；「兼顾」只强调同时照顾；「协调」侧重配合关系。故选A。","__sub":"选词填空"},{"id":"yy-15203","module":"yanyu","diff":1,"exam":"事业编","prompt":"事物的发展自有其规律，顺应它才能事半功倍。各级政府要持续______改革任务书，不断增强群众的获得感、幸福感、安全感。这样的要求，放在哪里都不过时。填入画横线处最恰当的是：","options":["锚定","盯住","瞄准","锁定"],"answer":0,"explanation":"「锚定」比喻像锚一样固定住目标，多用于宏观战略语境；「锁定」「瞄准」「盯住」语体偏口语，庄重色彩不足。故选A。","__sub":"选词填空"},{"id":"yy-15205","module":"yanyu","diff":2,"exam":"事业编","prompt":"干事创业，思路和坚持缺一不可。各级政府要持续______安全底线，不断增强群众的获得感、幸福感、安全感。其中的道理值得每个人细细体会。填入画横线处最恰当的是：","options":["筑造","筑牢","夯实","构建"],"answer":1,"explanation":"「筑牢」与「防线」为固定搭配，强调使牢固；「筑造」指建造实体；「构建」侧重搭建体系；「夯实」多与「基础」搭配。故选B。","__sub":"选词填空"},{"id":"yy-15208","module":"yanyu","diff":2,"exam":"省考","prompt":"任何工作要见成效，都离不开科学的方法和踏实的作风。回顾这些年走过的路，______创新创造潜能始终是我们攻坚克难的重要法宝。唯有如此，才能把好事办好、实事办实。填入画横线处最恰当的是：","options":["调动","引发","激发","点燃"],"answer":2,"explanation":"「激发」与「活力、热情、潜能」为固定搭配；「引发」多与「关注、争议」搭配；「点燃」为比喻用法；「调动」多与「积极性」搭配。故选C。","__sub":"选词填空"},{"id":"yy-15209","module":"yanyu","diff":3,"exam":"国考","prompt":"事物的发展自有其规律，顺应它才能事半功倍。下一步，将______农产品上行通道，推动各项工作再上新台阶。这样的要求，放在哪里都不过时。填入画横线处最恰当的是：","options":["打通","畅通","开拓","疏通"],"answer":1,"explanation":"「畅通」强调使通畅无阻，与「渠道」为固定搭配；「打通」侧重突破障碍；「疏通」多用于管道或疏导矛盾；「开拓」指开辟新领域。故选B。","__sub":"选词填空"},{"id":"yy-15212","module":"yanyu","diff":1,"exam":"省考","prompt":"无论时代如何变化，把事情做实做细始终是成事的基础。当前正值关键时期，______产业结构刻不容缓，必须抓紧抓实抓出成效。这背后考验的正是把握分寸的智慧。填入画横线处最恰当的是：","options":["改进","调整","优化","改善"],"answer":2,"explanation":"「优化」指加以改变使其优良，与「环境、结构」搭配规范；「改善」多与「条件、生活」搭配；「改进」多与「方法、工作」搭配；「调整」不含变优之义。故选C。","__sub":"选词填空"},{"id":"yy-15213","module":"yanyu","diff":1,"exam":"省考","prompt":"干事创业，思路和坚持缺一不可。越是任务艰巨，越要______城市功能品质，确保方向不偏、力度不减。其中的道理值得每个人细细体会。填入画横线处最恰当的是：","options":["提升","提高","拔高","增强"],"answer":0,"explanation":"「提升」与「效能、水平」搭配规范；「提高」语义相近但「提升」更书面；「增强」多与「能力、意识」搭配；「拔高」含贬义。故选A。","__sub":"选词填空"},{"id":"yy-15214","module":"yanyu","diff":2,"exam":"医疗编","prompt":"现实中，方法与态度不同，结果往往截然不同。要在______乡村振兴始终上下更大功夫，让发展成果更多惠及全体人民。看似寻常，实则是长期积累的结果。填入画横线处最恰当的是：","options":["贯串","穿过","经过","贯穿"],"answer":3,"explanation":"「贯穿」指从头到尾通贯，与「全过程」搭配规范；「穿过」「经过」仅指空间或时间经过，不含通贯始终之义。故选D。","__sub":"选词填空"},{"id":"yy-15215","module":"yanyu","diff":2,"exam":"事业编","prompt":"只有推进重点领域改革真正______到基层，才能让政策在「最后一公里」落地见效。填入画横线处最恰当的是：","options":["统筹","协调","统率","兼顾"],"answer":0,"explanation":"「统筹」指全面筹划、统一安排，与「推进」搭配且强调全局性；「统率」指率领；「兼顾」只强调同时照顾；「协调」侧重配合关系。故选A。","__sub":"选词填空"},{"id":"yy-15216","module":"yanyu","diff":2,"exam":"国考","prompt":"各地区各部门要拿出真招实招，______科技成果转化通道，确保各项部署落地生根。填入画横线处最恰当的是：","options":["打通","贯通","畅通","开辟"],"answer":2,"explanation":"「畅通」强调使通畅无阻，与「渠道、通道」搭配；「打通」侧重突破障碍；「贯通」指连接相通；「开辟」指新开路径。故选C。","__sub":"选词填空"},{"id":"yy-15217","module":"yanyu","diff":2,"exam":"国考","prompt":"很多事看起来简单，真要做扎实并不容易。越是任务艰巨，越要______制度堤坝，确保方向不偏、力度不减。道理虽朴素，真正做到并不容易。填入画横线处最恰当的是：","options":["筑牢","筑造","夯实","构建"],"answer":0,"explanation":"「筑牢」与「防线」为固定搭配，强调使牢固；「筑造」指建造实体；「构建」侧重搭建体系；「夯实」多与「基础」搭配。故选A。","__sub":"选词填空"},{"id":"yy-15218","module":"yanyu","diff":2,"exam":"国考","prompt":"回顾这些年走过的路，______农村物流最后一公里始终是我们攻坚克难的重要法宝。填入画横线处最恰当的是：","options":["畅通","贯通","开辟","打通"],"answer":0,"explanation":"「畅通」强调使通畅无阻，与「渠道、通道」搭配；「打通」侧重突破障碍；「贯通」指连接相通；「开辟」指新开路径。故选A。","__sub":"选词填空"},{"id":"yy-15220","module":"yanyu","diff":3,"exam":"国考","prompt":"现实中，方法与态度不同，结果往往截然不同。越是任务艰巨，越要______安全底线，确保方向不偏、力度不减。看似寻常，实则是长期积累的结果。填入画横线处最恰当的是：","options":["夯实","筑造","构建","筑牢"],"answer":3,"explanation":"「筑牢」与「防线」为固定搭配，强调使牢固；「筑造」指建造实体；「构建」侧重搭建体系；「夯实」多与「基础」搭配。故选D。","__sub":"选词填空"},{"id":"yy-15221","module":"yanyu","diff":1,"exam":"事业编","prompt":"无论时代如何变化，把事情做实做细始终是成事的基础。各级政府要持续______共识，不断增强群众的获得感、幸福感、安全感。这背后考验的正是把握分寸的智慧。填入画横线处最恰当的是：","options":["凝聚","汇聚","聚集","集中"],"answer":0,"explanation":"「凝聚」多与「共识、人心、力量」搭配，强调由分散到统一；「聚集」侧重物理集合；「集中」侧重把分散的集中起来。故选A。","__sub":"选词填空"},{"id":"yy-15222","module":"yanyu","diff":1,"exam":"省考","prompt":"无论时代如何变化，把事情做实做细始终是成事的基础。面对新形势新任务，必须______发展合力，牢牢把握发展主动权。这背后考验的正是把握分寸的智慧。填入画横线处最恰当的是：","options":["汇聚","凝聚","聚集","集中"],"answer":1,"explanation":"「凝聚」多与「共识、人心、力量」搭配，强调由分散到统一；「聚集」侧重物理集合；「集中」侧重把分散的集中起来。故选B。","__sub":"选词填空"},{"id":"yy-15223","module":"yanyu","diff":1,"exam":"事业编","prompt":"观察身边的事不难发现，成败的分野常常藏在细节里。各地区各部门要拿出真招实招，______安全底线，确保各项部署落地生根。说到底，拼的是态度，比的是功夫。填入画横线处最恰当的是：","options":["筑造","夯实","构建","筑牢"],"answer":3,"explanation":"「筑牢」与「防线」为固定搭配，强调使牢固；「筑造」指建造实体；「构建」侧重搭建体系；「夯实」多与「基础」搭配。故选D。","__sub":"选词填空"},{"id":"yy-15224","module":"yanyu","diff":2,"exam":"国考","prompt":"很多事看起来简单，真要做扎实并不容易。越是任务艰巨，越要______监督机制，确保方向不偏、力度不减。道理虽朴素，真正做到并不容易。填入画横线处最恰当的是：","options":["完善","构建","建立","健全"],"answer":3,"explanation":"「健全」强调使完备无缺，与「体系」搭配规范；「建立」指从无到有，「完善」指补足短板，「构建」侧重搭建框架。故选D。","__sub":"选词填空"},{"id":"yy-15225","module":"yanyu","diff":2,"exam":"省考","prompt":"事物的发展自有其规律，顺应它才能事半功倍。各级政府要持续______基层基础，不断增强群众的获得感、幸福感、安全感。这样的要求，放在哪里都不过时。填入画横线处最恰当的是：","options":["打牢","夯实","巩固","筑牢"],"answer":1,"explanation":"「夯实」本义为砸实地基，引申为使稳固，与「基础、根基」搭配；「筑牢」与「防线」搭配；「打牢」语体稍口语；「巩固」侧重使已有的更牢固。故选B。","__sub":"选词填空"},{"id":"yy-15501","module":"yanyu","diff":1,"exam":"教师编","prompt":"干事创业，思路和坚持缺一不可。各地区各部门要拿出真招实招，______放管服改革，确保各项部署落地生根。其中的道理值得每个人细细体会。填入画横线处最恰当的是：","options":["深化","推进","深入","加强"],"answer":0,"explanation":"「深化」指向更深阶段发展，与「改革」为固定搭配；「深入」多作形容词或「深入调查」；「加强」「推进」语义宽泛。故选A。","__sub":"选词填空"},{"id":"yy-15504","module":"yanyu","diff":2,"exam":"国考","prompt":"一个朴素的道理反复被验证：方向对了，努力才不会白费。越是任务艰巨，越要______传统产业转型升级，确保方向不偏、力度不减。这也正是成事的关键所在。填入画横线处最恰当的是：","options":["助力","赋权","赋能","加持"],"answer":2,"explanation":"「赋能」指赋予能力，是数字经济语境的规范表述；「赋权」指赋予权力；「加持」为口语化外来词；「助力」语义宽泛。故选C。","__sub":"选词填空"},{"id":"yy-15507","module":"yanyu","diff":2,"exam":"国考","prompt":"一个朴素的道理反复被验证：方向对了，努力才不会白费。面对新形势新任务，必须______农产品上行通道，牢牢把握发展主动权。这也正是成事的关键所在。填入画横线处最恰当的是：","options":["疏通","开拓","打通","畅通"],"answer":3,"explanation":"「畅通」强调使通畅无阻，与「渠道」为固定搭配；「打通」侧重突破障碍；「疏通」多用于管道或疏导矛盾；「开拓」指开辟新领域。故选D。","__sub":"选词填空"},{"id":"yy-15508","module":"yanyu","diff":2,"exam":"省考","prompt":"事物的发展自有其规律，顺应它才能事半功倍。实践证明，______创新创造潜能是推动高质量发展的关键一招。这样的要求，放在哪里都不过时。填入画横线处最恰当的是：","options":["激发","调动","引发","点燃"],"answer":0,"explanation":"「激发」与「活力、热情、潜能」为固定搭配；「引发」多与「关注、争议」搭配；「点燃」为比喻用法；「调动」多与「积极性」搭配。故选A。","__sub":"选词填空"},{"id":"yy-15513","module":"yanyu","diff":1,"exam":"事业编","prompt":"很多事看起来简单，真要做扎实并不容易。各级政府要持续______企业主体责任，不断增强群众的获得感、幸福感、安全感。道理虽朴素，真正做到并不容易。填入画横线处最恰当的是：","options":["压紧","压实","落实","强化"],"answer":1,"explanation":"「压实」与「责任」搭配，强调责任层层落实到位；「落实」为通用动词；「压紧」常作「压紧压实」；「强化」不如「压实」精准体现层级传导。故选B。","__sub":"选词填空"},{"id":"yy-15514","module":"yanyu","diff":2,"exam":"省考","prompt":"事物的发展自有其规律，顺应它才能事半功倍。面对新形势新任务，必须______群众需求，牢牢把握发展主动权。这样的要求，放在哪里都不过时。填入画横线处最恰当的是：","options":["把持","把守","把玩","把握"],"answer":3,"explanation":"「把握」与抽象事物（特点、规律、机遇）搭配；「把守」指守卫关口，「把持」含贬义指独揽，「把玩」指赏玩物品。故选D。","__sub":"选词填空"},{"id":"yy-15515","module":"yanyu","diff":2,"exam":"事业编","prompt":"干事创业，思路和坚持缺一不可。面对新形势新任务，必须______新型农业经营主体，牢牢把握发展主动权。其中的道理值得每个人细细体会。填入画横线处最恰当的是：","options":["孕育","培育","培植","培养"],"answer":1,"explanation":"「培育」与「产业、企业、市场」搭配；「培养」对象为人或能力；「培植」多用于动植物或含贬义；「孕育」强调正在形成。故选B。","__sub":"选词填空"},{"id":"yy-15516","module":"yanyu","diff":2,"exam":"医疗编","prompt":"一个朴素的道理反复被验证：方向对了，努力才不会白费。回顾这些年走过的路，______就业服务体系始终是我们攻坚克难的重要法宝。这也正是成事的关键所在。填入画横线处最恰当的是：","options":["建立","构建","完善","健全"],"answer":3,"explanation":"「健全」强调使完备无缺，与「体系」搭配规范；「建立」指从无到有，「完善」指补足短板，「构建」侧重搭建框架。故选D。","__sub":"选词填空"},{"id":"yy-15522","module":"yanyu","diff":1,"exam":"国考","prompt":"干事创业，思路和坚持缺一不可。下一步，将______民生短板，推动各项工作再上新台阶。唯有如此，才能把好事办好、实事办实。填入画横线处最恰当的是：","options":["补齐","填补","弥补","补足"],"answer":0,"explanation":"「补齐」与「短板」为固定搭配，强调使达到应有水平；「补足」多与「差额」搭配；「填补」多与「空白」搭配；「弥补」多与「损失」搭配。故选A。","__sub":"选词填空"},{"id":"yy-15523","module":"yanyu","diff":1,"exam":"医疗编","prompt":"一个朴素的道理反复被验证：方向对了，努力才不会白费。下一步，将______斗争精神，推动各项工作再上新台阶。这也正是成事的关键所在。填入画横线处最恰当的是：","options":["砥砺","磨砺","锻炼","锤炼"],"answer":0,"explanation":"「砥砺」本义为磨刀石，引申为磨炼，与「意志」搭配且语体庄重；「磨砺」与之近义但「砥砺」更常用于「砥砺前行、砥砺意志」。故选A。","__sub":"选词填空"},{"id":"yy-15524","module":"yanyu","diff":2,"exam":"国考","prompt":"干事创业，思路和坚持缺一不可。实践证明，______安全底线是推动高质量发展的关键一招。看似寻常，实则是长期积累的结果。填入画横线处最恰当的是：","options":["筑造","构建","夯实","筑牢"],"answer":3,"explanation":"「筑牢」与「防线」为固定搭配，强调使牢固；「筑造」指建造实体；「构建」侧重搭建体系；「夯实」多与「基础」搭配。故选D。","__sub":"选词填空"},{"id":"yy-15525","module":"yanyu","diff":2,"exam":"省考","prompt":"一个朴素的道理反复被验证：方向对了，努力才不会白费。当前正值关键时期，______发展根基刻不容缓，必须抓紧抓实抓出成效。这也正是成事的关键所在。填入画横线处最恰当的是：","options":["筑牢","夯实","打牢","巩固"],"answer":1,"explanation":"「夯实」本义为砸实地基，引申为使稳固，与「基础、根基」搭配；「筑牢」与「防线」搭配；「打牢」语体稍口语；「巩固」侧重使已有的更牢固。故选B。","__sub":"选词填空"},{"id":"yy-15526","module":"yanyu","diff":2,"exam":"省考","prompt":"任何工作要见成效，都离不开科学的方法和踏实的作风。下一步，将______东西部协作，推动各项工作再上新台阶。唯有如此，才能把好事办好、实事办实。填入画横线处最恰当的是：","options":["推进","深化","加强","深入"],"answer":1,"explanation":"「深化」指向更深阶段发展，与「改革」为固定搭配；「深入」多作形容词或「深入调查」；「加强」「推进」语义宽泛。故选B。","__sub":"选词填空"},{"id":"yy-15530","module":"yanyu","diff":3,"exam":"国考","prompt":"任何工作要见成效，都离不开科学的方法和踏实的作风。要坚持问题导向，______公共服务体系，切实解决群众急难愁盼问题。唯有如此，才能把好事办好、实事办实。填入画横线处最恰当的是：","options":["构建","完善","健全","建立"],"answer":2,"explanation":"「健全」强调使完备无缺，与「体系」搭配规范；「建立」指从无到有，「完善」指补足短板，「构建」侧重搭建框架。故选C。","__sub":"选词填空"},{"id":"yy-15533","module":"yanyu","diff":1,"exam":"国考","prompt":"任何工作要见成效，都离不开科学的方法和踏实的作风。各级政府要持续______人才和资金，不断增强群众的获得感、幸福感、安全感。唯有如此，才能把好事办好、实事办实。填入画横线处最恰当的是：","options":["下探","下沉","下潜","下坠"],"answer":1,"explanation":"「下沉」指治理资源向基层倾斜，是规范表述；「下潜」指潜水，「下探」多指价格或行动试探，「下坠」指物体坠落。故选B。","__sub":"选词填空"},{"id":"yy-15535","module":"yanyu","diff":2,"exam":"国考","prompt":"事物的发展自有其规律，顺应它才能事半功倍。新征程上，要继续______食品安全监管，以实干实绩回应人民期盼。这样的要求，放在哪里都不过时。填入画横线处最恰当的是：","options":["加强","深化","增强","强化"],"answer":3,"explanation":"「强化」与「意识、思维」搭配，强调使之更牢固；「增强」语义相近但搭配习惯不同；「加强」为通用动词；「深化」指向深处发展。故选D。","__sub":"选词填空"},{"id":"yy-15537","module":"yanyu","diff":2,"exam":"省考","prompt":"一个朴素的道理反复被验证：方向对了，努力才不会白费。实践证明，______志愿服务体系是推动高质量发展的关键一招。这也正是成事的关键所在。填入画横线处最恰当的是：","options":["完善","搭建","构建","健全"],"answer":3,"explanation":"「健全」强调使完备无缺；「完善」指补足短板；「构建」「搭建」侧重从无到有搭建。故选D。","__sub":"选词填空"},{"id":"yy-15541","module":"yanyu","diff":1,"exam":"医疗编","prompt":"无论时代如何变化，把事情做实做细始终是成事的基础。要坚持问题导向，______安全生产责任，切实解决群众急难愁盼问题。这背后考验的正是把握分寸的智慧。填入画横线处最恰当的是：","options":["落实","压紧","强化","压实"],"answer":3,"explanation":"「压实」与「责任」搭配，强调责任层层落实到位；「落实」为通用动词；「压紧」常作「压紧压实」；「强化」不如「压实」精准体现层级传导。故选D。","__sub":"选词填空"},{"id":"yy-15545","module":"yanyu","diff":2,"exam":"教师编","prompt":"各级政府要持续______新时代发展的宏伟蓝图，不断增强群众的获得感、幸福感、安全感。填入画横线处最恰当的是：","options":["勾画","规划","描绘","擘画"],"answer":3,"explanation":"「擘画」指筹划布置，多用于宏观蓝图，书面色彩浓；「描绘」「勾画」偏具体画面；「规划」语体色彩不足。故选D。","__sub":"选词填空"},{"id":"yy-15546","module":"yanyu","diff":2,"exam":"省考","prompt":"任何工作要见成效，都离不开科学的方法和踏实的作风。要坚持问题导向，______乡村振兴的壮美画卷，切实解决群众急难愁盼问题。唯有如此，才能把好事办好、实事办实。填入画横线处最恰当的是：","options":["描绘","擘画","规划","勾画"],"answer":1,"explanation":"「擘画」指筹划布置，多用于宏观蓝图，书面色彩浓；「描绘」「勾画」偏具体画面；「规划」语体色彩不足。故选B。","__sub":"选词填空"},{"id":"yy-15549","module":"yanyu","diff":3,"exam":"教师编","prompt":"一个朴素的道理反复被验证：方向对了，努力才不会白费。回顾这些年走过的路，______基层治理始终是我们攻坚克难的重要法宝。这也正是成事的关键所在。填入画横线处最恰当的是：","options":["赋能","赋权","加持","助力"],"answer":0,"explanation":"「赋能」指赋予能力，是数字经济语境的规范表述；「赋权」指赋予权力；「加持」为口语化外来词；「助力」语义宽泛。故选A。","__sub":"选词填空"},{"id":"yy-15551","module":"yanyu","diff":1,"exam":"省考","prompt":"只有新发展阶段的新特点真正______到基层，才能让政策在「最后一公里」落地见效。填入画横线处最恰当的是：","options":["把玩","把握","把持","把守"],"answer":1,"explanation":"「把握」与抽象事物（特点、规律、机遇）搭配；「把守」指守卫关口，「把持」含贬义指独揽，「把玩」指赏玩物品。故选B。","__sub":"选词填空"},{"id":"yy-15553","module":"yanyu","diff":1,"exam":"省考","prompt":"事物的发展自有其规律，顺应它才能事半功倍。回顾这些年走过的路，______基层治理神经末梢始终是我们攻坚克难的重要法宝。这样的要求，放在哪里都不过时。填入画横线处最恰当的是：","options":["启动","激活","唤醒","驱动"],"answer":1,"explanation":"「激活」指刺激使之活跃，与「动力、要素」搭配；「唤醒」指使之觉醒；「启动」指开始进行；「驱动」指推动运转。故选B。","__sub":"选词填空"},{"id":"yy-15554","module":"yanyu","diff":2,"exam":"事业编","prompt":"干事创业，思路和坚持缺一不可。下一步，将______共同思想基础，推动各项工作再上新台阶。其中的道理值得每个人细细体会。填入画横线处最恰当的是：","options":["夯实","巩固","打牢","筑牢"],"answer":0,"explanation":"「夯实」本义为砸实地基，引申为使稳固，与「基础、根基」搭配；「筑牢」与「防线」搭配；「打牢」语体稍口语；「巩固」侧重使已有的更牢固。故选A。","__sub":"选词填空"},{"id":"yy-15556","module":"yanyu","diff":2,"exam":"医疗编","prompt":"现实中，方法与态度不同，结果往往截然不同。越是任务艰巨，越要______农村物流最后一公里，确保方向不偏、力度不减。看似寻常，实则是长期积累的结果。填入画横线处最恰当的是：","options":["贯通","开辟","畅通","打通"],"answer":2,"explanation":"「畅通」强调使通畅无阻，与「渠道、通道」搭配；「打通」侧重突破障碍；「贯通」指连接相通；「开辟」指新开路径。故选C。","__sub":"选词填空"},{"id":"yy-15560","module":"yanyu","diff":3,"exam":"教师编","prompt":"一个朴素的道理反复被验证：方向对了，努力才不会白费。实践证明，______公共服务体系是推动高质量发展的关键一招。这也正是成事的关键所在。填入画横线处最恰当的是：","options":["完善","构建","建立","健全"],"answer":3,"explanation":"「健全」强调使完备无缺，与「体系」搭配规范；「建立」指从无到有，「完善」指补足短板，「构建」侧重搭建框架。故选D。","__sub":"选词填空"},{"id":"yy-15562","module":"yanyu","diff":1,"exam":"省考","prompt":"干事创业，思路和坚持缺一不可。只有群众增收渠道真正______到基层，才能让政策在「最后一公里」落地见效。其中的道理值得每个人细细体会。填入画横线处最恰当的是：","options":["开拓","延伸","拓宽","扩大"],"answer":2,"explanation":"「拓宽」与「渠道、门路、视野」搭配；「开拓」指开辟新领域；「扩大」多与「规模、范围」搭配；「延伸」侧重长度延长。故选C。","__sub":"选词填空"},{"id":"yy-15563","module":"yanyu","diff":1,"exam":"事业编","prompt":"事物的发展自有其规律，顺应它才能事半功倍。各地区各部门要拿出真招实招，______现代化建设全局，确保各项部署落地生根。这样的要求，放在哪里都不过时。填入画横线处最恰当的是：","options":["经过","贯串","贯穿","穿过"],"answer":2,"explanation":"「贯穿」指从头到尾通贯，与「全过程」搭配规范；「穿过」「经过」仅指空间或时间经过，不含通贯始终之义。故选C。","__sub":"选词填空"},{"id":"yy-15564","module":"yanyu","diff":2,"exam":"教师编","prompt":"一个朴素的道理反复被验证：方向对了，努力才不会白费。要坚持问题导向，______消费市场一池春水，切实解决群众急难愁盼问题。这也正是成事的关键所在。填入画横线处最恰当的是：","options":["唤醒","驱动","激活","启动"],"answer":2,"explanation":"「激活」指刺激使之活跃，与「动力、要素」搭配；「唤醒」指使之觉醒；「启动」指开始进行；「驱动」指推动运转。故选C。","__sub":"选词填空"},{"id":"yy-15565","module":"yanyu","diff":2,"exam":"国考","prompt":"干事创业，思路和坚持缺一不可。回顾这些年走过的路，______改革开放各领域始终是我们攻坚克难的重要法宝。其中的道理值得每个人细细体会。填入画横线处最恰当的是：","options":["贯穿","贯串","经过","穿过"],"answer":0,"explanation":"「贯穿」指从头到尾通贯，与「全过程」搭配规范；「穿过」「经过」仅指空间或时间经过，不含通贯始终之义。故选A。","__sub":"选词填空"},{"id":"yy-15567","module":"yanyu","diff":2,"exam":"医疗编","prompt":"现实中，方法与态度不同，结果往往截然不同。下一步，将______智慧和力量，推动各项工作再上新台阶。看似寻常，实则是长期积累的结果。填入画横线处最恰当的是：","options":["集中","汇聚","聚集","凝聚"],"answer":3,"explanation":"「凝聚」多与「共识、人心、力量」搭配，强调由分散到统一；「聚集」侧重物理集合；「集中」侧重把分散的集中起来。故选D。","__sub":"选词填空"},{"id":"yy-15569","module":"yanyu","diff":3,"exam":"国考","prompt":"一个朴素的道理反复被验证：方向对了，努力才不会白费。要在______企业主体责任上下更大功夫，让发展成果更多惠及全体人民。这也正是成事的关键所在。填入画横线处最恰当的是：","options":["压实","压紧","落实","强化"],"answer":0,"explanation":"「压实」与「责任」搭配，强调责任层层落实到位；「落实」为通用动词；「压紧」常作「压紧压实」；「强化」不如「压实」精准体现层级传导。故选A。","__sub":"选词填空"},{"id":"yy-15571","module":"yanyu","diff":1,"exam":"医疗编","prompt":"无论时代如何变化，把事情做实做细始终是成事的基础。各级政府要持续______内生动力，不断增强群众的获得感、幸福感、安全感。这背后考验的正是把握分寸的智慧。填入画横线处最恰当的是：","options":["调动","引发","点燃","激发"],"answer":3,"explanation":"「激发」与「活力、热情、潜能」为固定搭配；「引发」多与「关注、争议」搭配；「点燃」为比喻用法；「调动」多与「积极性」搭配。故选D。","__sub":"选词填空"},{"id":"yy-15572","module":"yanyu","diff":1,"exam":"国考","prompt":"任何工作要见成效，都离不开科学的方法和踏实的作风。越是任务艰巨，越要______底线思维，确保方向不偏、力度不减。唯有如此，才能把好事办好、实事办实。填入画横线处最恰当的是：","options":["增强","深化","加强","强化"],"answer":3,"explanation":"「强化」与「意识、思维」搭配，强调使之更牢固；「增强」语义相近但搭配习惯不同；「加强」为通用动词；「深化」指向深处发展。故选D。","__sub":"选词填空"},{"id":"yy-15573","module":"yanyu","diff":1,"exam":"省考","prompt":"事物的发展自有其规律，顺应它才能事半功倍。下一步，将______人才流动渠道，推动各项工作再上新台阶。这样的要求，放在哪里都不过时。填入画横线处最恰当的是：","options":["疏通","开拓","畅通","打通"],"answer":2,"explanation":"「畅通」强调使通畅无阻，与「渠道」为固定搭配；「打通」侧重突破障碍；「疏通」多用于管道或疏导矛盾；「开拓」指开辟新领域。故选C。","__sub":"选词填空"},{"id":"yy-15574","module":"yanyu","diff":2,"exam":"国考","prompt":"干事创业，思路和坚持缺一不可。面对新形势新任务，必须______城市建设各环节，牢牢把握发展主动权。其中的道理值得每个人细细体会。填入画横线处最恰当的是：","options":["贯串","经过","贯穿","穿过"],"answer":2,"explanation":"「贯穿」指从头到尾通贯，与「全过程」搭配规范；「穿过」「经过」仅指空间或时间经过，不含通贯始终之义。故选C。","__sub":"选词填空"},{"id":"yy-15576","module":"yanyu","diff":2,"exam":"省考","prompt":"一个朴素的道理反复被验证：方向对了，努力才不会白费。各地区各部门要拿出真招实招，______品格，确保各项部署落地生根。这也正是成事的关键所在。填入画横线处最恰当的是：","options":["锤炼","锻炼","砥砺","磨砺"],"answer":2,"explanation":"「砥砺」本义为磨刀石，引申为磨炼，与「意志」搭配且语体庄重；「磨砺」与之近义但「砥砺」更常用于「砥砺前行、砥砺意志」。故选C。","__sub":"选词填空"},{"id":"yy-15577","module":"yanyu","diff":2,"exam":"国考","prompt":"干事创业，思路和坚持缺一不可。各级政府要持续______社会保障网络，不断增强群众的获得感、幸福感、安全感。其中的道理值得每个人细细体会。填入画横线处最恰当的是：","options":["搭建","完善","构建","健全"],"answer":3,"explanation":"「健全」强调使完备无缺；「完善」指补足短板；「构建」「搭建」侧重从无到有搭建。故选D。","__sub":"选词填空"},{"id":"yy-15578","module":"yanyu","diff":2,"exam":"省考","prompt":"无论时代如何变化，把事情做实做细始终是成事的基础。实践证明，______放管服改革是推动高质量发展的关键一招。这背后考验的正是把握分寸的智慧。填入画横线处最恰当的是：","options":["深化","推进","加强","深入"],"answer":0,"explanation":"「深化」指向更深阶段发展，与「改革」为固定搭配；「深入」多作形容词或「深入调查」；「加强」「推进」语义宽泛。故选A。","__sub":"选词填空"},{"id":"yy-15579","module":"yanyu","diff":3,"exam":"事业编","prompt":"无论时代如何变化，把事情做实做细始终是成事的基础。回顾这些年走过的路，______监督机制始终是我们攻坚克难的重要法宝。这背后考验的正是把握分寸的智慧。填入画横线处最恰当的是：","options":["健全","构建","建立","完善"],"answer":0,"explanation":"「健全」强调使完备无缺，与「体系」搭配规范；「建立」指从无到有，「完善」指补足短板，「构建」侧重搭建框架。故选A。","__sub":"选词填空"},{"id":"yy-15580","module":"yanyu","diff":3,"exam":"国考","prompt":"当前正值关键时期，______区域协调发展的新格局刻不容缓，必须抓紧抓实抓出成效。填入画横线处最恰当的是：","options":["描绘","勾画","规划","擘画"],"answer":3,"explanation":"「擘画」指筹划布置，多用于宏观蓝图，书面色彩浓；「描绘」「勾画」偏具体画面；「规划」语体色彩不足。故选D。","__sub":"选词填空"},{"id":"yy-15581","module":"yanyu","diff":1,"exam":"教师编","prompt":"现实中，方法与态度不同，结果往往截然不同。新征程上，要继续______乡村振兴始终，以实干实绩回应人民期盼。看似寻常，实则是长期积累的结果。填入画横线处最恰当的是：","options":["贯穿","穿过","经过","贯串"],"answer":0,"explanation":"「贯穿」指从头到尾通贯，与「全过程」搭配规范；「穿过」「经过」仅指空间或时间经过，不含通贯始终之义。故选A。","__sub":"选词填空"},{"id":"yy-15582","module":"yanyu","diff":1,"exam":"国考","prompt":"干事创业，思路和坚持缺一不可。要坚持问题导向，______就业服务体系，切实解决群众急难愁盼问题。其中的道理值得每个人细细体会。填入画横线处最恰当的是：","options":["健全","建立","构建","完善"],"answer":0,"explanation":"「健全」强调使完备无缺，与「体系」搭配规范；「建立」指从无到有，「完善」指补足短板，「构建」侧重搭建框架。故选A。","__sub":"选词填空"},{"id":"yy-15584","module":"yanyu","diff":2,"exam":"国考","prompt":"任何工作要见成效，都离不开科学的方法和踏实的作风。各级政府要持续______服务空白，不断增强群众的获得感、幸福感、安全感。唯有如此，才能把好事办好、实事办实。填入画横线处最恰当的是：","options":["补齐","补足","弥补","填补"],"answer":0,"explanation":"「补齐」与「短板」为固定搭配，强调使达到应有水平；「补足」多与「差额」搭配；「填补」多与「空白」搭配；「弥补」多与「损失」搭配。故选A。","__sub":"选词填空"},{"id":"yy-15585","module":"yanyu","diff":2,"exam":"省考","prompt":"一个朴素的道理反复被验证：方向对了，努力才不会白费。越是任务艰巨，越要______新发展阶段的新特点，确保方向不偏、力度不减。这也正是成事的关键所在。填入画横线处最恰当的是：","options":["把守","把玩","把持","把握"],"answer":3,"explanation":"「把握」与抽象事物（特点、规律、机遇）搭配；「把守」指守卫关口，「把持」含贬义指独揽，「把玩」指赏玩物品。故选D。","__sub":"选词填空"},{"id":"yy-15586","module":"yanyu","diff":2,"exam":"教师编","prompt":"事物的发展自有其规律，顺应它才能事半功倍。下一步，将______人才结构，推动各项工作再上新台阶。这样的要求，放在哪里都不过时。填入画横线处最恰当的是：","options":["调整","改进","改善","优化"],"answer":3,"explanation":"「优化」指加以改变使其优良，与「环境、结构」搭配规范；「改善」多与「条件、生活」搭配；「改进」多与「方法、工作」搭配；「调整」不含变优之义。故选D。","__sub":"选词填空"},{"id":"yy-15587","module":"yanyu","diff":2,"exam":"事业编","prompt":"干事创业，思路和坚持缺一不可。要在______腐败蔓延的态势上下更大功夫，让发展成果更多惠及全体人民。其中的道理值得每个人细细体会。填入画横线处最恰当的是：","options":["遏止","控制","遏制","制止"],"answer":2,"explanation":"「遏制」强调压制住势头、多与「势头/态势」搭配；「遏止」侧重使之停止，多用于具体行为；「控制」「制止」语义宽泛。故选C。","__sub":"选词填空"},{"id":"yy-15588","module":"yanyu","diff":2,"exam":"省考","prompt":"很多事看起来简单，真要做扎实并不容易。要坚持问题导向，______社会保障体系，切实解决群众急难愁盼问题。道理虽朴素，真正做到并不容易。填入画横线处最恰当的是：","options":["构建","完善","建立","健全"],"answer":3,"explanation":"「健全」强调使完备无缺，与「体系」搭配规范；「建立」指从无到有，「完善」指补足短板，「构建」侧重搭建框架。故选D。","__sub":"选词填空"},{"id":"yy-15591","module":"yanyu","diff":1,"exam":"事业编","prompt":"任何工作要见成效，都离不开科学的方法和踏实的作风。新征程上，要继续______房价过快上涨的势头，以实干实绩回应人民期盼。唯有如此，才能把好事办好、实事办实。填入画横线处最恰当的是：","options":["制止","遏制","遏止","控制"],"answer":1,"explanation":"「遏制」强调压制住势头、多与「势头/态势」搭配；「遏止」侧重使之停止，多用于具体行为；「控制」「制止」语义宽泛。故选B。","__sub":"选词填空"},{"id":"yy-15592","module":"yanyu","diff":1,"exam":"省考","prompt":"干事创业，思路和坚持缺一不可。面对新形势新任务，必须______诉求表达渠道，牢牢把握发展主动权。其中的道理值得每个人细细体会。填入画横线处最恰当的是：","options":["疏通","畅通","开拓","打通"],"answer":1,"explanation":"「畅通」强调使通畅无阻，与「渠道」为固定搭配；「打通」侧重突破障碍；「疏通」多用于管道或疏导矛盾；「开拓」指开辟新领域。故选B。","__sub":"选词填空"},{"id":"yy-15593","module":"yanyu","diff":1,"exam":"医疗编","prompt":"干事创业，思路和坚持缺一不可。要坚持问题导向，______创新创造潜能，切实解决群众急难愁盼问题。其中的道理值得每个人细细体会。填入画横线处最恰当的是：","options":["引发","调动","点燃","激发"],"answer":3,"explanation":"「激发」与「活力、热情、潜能」为固定搭配；「引发」多与「关注、争议」搭配；「点燃」为比喻用法；「调动」多与「积极性」搭配。故选D。","__sub":"选词填空"},{"id":"yy-15596","module":"yanyu","diff":2,"exam":"省考","prompt":"无论时代如何变化，把事情做实做细始终是成事的基础。新征程上，要继续______中小企业发展，以实干实绩回应人民期盼。这背后考验的正是把握分寸的智慧。填入画横线处最恰当的是：","options":["加持","赋能","赋权","助力"],"answer":1,"explanation":"「赋能」指赋予能力，是数字经济语境的规范表述；「赋权」指赋予权力；「加持」为口语化外来词；「助力」语义宽泛。故选B。","__sub":"选词填空"},{"id":"yy-15597","module":"yanyu","diff":2,"exam":"省考","prompt":"无论时代如何变化，把事情做实做细始终是成事的基础。越是任务艰巨，越要______乡村发展内生动力，确保方向不偏、力度不减。这背后考验的正是把握分寸的智慧。填入画横线处最恰当的是：","options":["启动","激活","驱动","唤醒"],"answer":1,"explanation":"「激活」指刺激使之活跃，与「动力、要素」搭配；「唤醒」指使之觉醒；「启动」指开始进行；「驱动」指推动运转。故选B。","__sub":"选词填空"},{"id":"yy-15598","module":"yanyu","diff":2,"exam":"国考","prompt":"很多事看起来简单，真要做扎实并不容易。当前正值关键时期，______爱国情怀刻不容缓，必须抓紧抓实抓出成效。道理虽朴素，真正做到并不容易。填入画横线处最恰当的是：","options":["加深","筑牢","培植","厚植"],"answer":3,"explanation":"「厚植」指深厚培育，与「优势、底色、根基」搭配；「培植」多用于培育动植物或扶植势力；「加深」与「底色」搭配不当。故选D。","__sub":"选词填空"},{"id":"yy-15599","module":"yanyu","diff":3,"exam":"国考","prompt":"观察身边的事不难发现，成败的分野常常藏在细节里。面对新形势新任务，必须______内生动力，牢牢把握发展主动权。说到底，拼的是态度，比的是功夫。填入画横线处最恰当的是：","options":["引发","点燃","激发","调动"],"answer":2,"explanation":"「激发」与「活力、热情、潜能」为固定搭配；「引发」多与「关注、争议」搭配；「点燃」为比喻用法；「调动」多与「积极性」搭配。故选C。","__sub":"选词填空"},{"id":"yy-15600","module":"yanyu","diff":3,"exam":"国考","prompt":"很多事看起来简单，真要做扎实并不容易。各地区各部门要拿出真招实招，______群众增收渠道，确保各项部署落地生根。道理虽朴素，真正做到并不容易。填入画横线处最恰当的是：","options":["拓宽","扩大","开拓","延伸"],"answer":0,"explanation":"「拓宽」与「渠道、门路、视野」搭配；「开拓」指开辟新领域；「扩大」多与「规模、范围」搭配；「延伸」侧重长度延长。故选A。","__sub":"选词填空"},{"id":"yy-15601","module":"yanyu","diff":1,"exam":"国考","prompt":"现实中，方法与态度不同，结果往往截然不同。新征程上，要继续______科技成果转化通道，以实干实绩回应人民期盼。看似寻常，实则是长期积累的结果。填入画横线处最恰当的是：","options":["打通","贯通","畅通","开辟"],"answer":2,"explanation":"「畅通」强调使通畅无阻，与「渠道、通道」搭配；「打通」侧重突破障碍；「贯通」指连接相通；「开辟」指新开路径。故选C。","__sub":"选词填空"},{"id":"yy-15602","module":"yanyu","diff":1,"exam":"医疗编","prompt":"很多事看起来简单，真要做扎实并不容易。回顾这些年走过的路，______发展优势始终是我们攻坚克难的重要法宝。道理虽朴素，真正做到并不容易。填入画横线处最恰当的是：","options":["加深","厚植","培植","筑牢"],"answer":1,"explanation":"「厚植」指深厚培育，与「优势、底色、根基」搭配；「培植」多用于培育动植物或扶植势力；「加深」与「底色」搭配不当。故选B。","__sub":"选词填空"},{"id":"yy-15605","module":"yanyu","diff":2,"exam":"国考","prompt":"无论时代如何变化，把事情做实做细始终是成事的基础。实践证明，______生态环保责任是推动高质量发展的关键一招。这背后考验的正是把握分寸的智慧。填入画横线处最恰当的是：","options":["落实","压实","压紧","强化"],"answer":1,"explanation":"「压实」与「责任」搭配，强调责任层层落实到位；「落实」为通用动词；「压紧」常作「压紧压实」；「强化」不如「压实」精准体现层级传导。故选B。","__sub":"选词填空"},{"id":"yy-15606","module":"yanyu","diff":2,"exam":"省考","prompt":"事物的发展自有其规律，顺应它才能事半功倍。下一步，将______沉睡的资源要素，推动各项工作再上新台阶。这样的要求，放在哪里都不过时。填入画横线处最恰当的是：","options":["启动","激活","唤醒","驱动"],"answer":1,"explanation":"「激活」指刺激使之活跃，与「动力、要素」搭配；「唤醒」指使之觉醒；「启动」指开始进行；「驱动」指推动运转。故选B。","__sub":"选词填空"},{"id":"yy-15608","module":"yanyu","diff":2,"exam":"事业编","prompt":"各级政府要持续______现代化建设的宏伟篇章，不断增强群众的获得感、幸福感、安全感。填入画横线处最恰当的是：","options":["规划","描绘","勾画","擘画"],"answer":3,"explanation":"「擘画」指筹划布置，多用于宏观蓝图，书面色彩浓；「描绘」「勾画」偏具体画面；「规划」语体色彩不足。故选D。","__sub":"选词填空"},{"id":"yy-15609","module":"yanyu","diff":3,"exam":"教师编","prompt":"无论时代如何变化，把事情做实做细始终是成事的基础。各地区各部门要拿出真招实招，______智慧和力量，确保各项部署落地生根。这背后考验的正是把握分寸的智慧。填入画横线处最恰当的是：","options":["聚集","凝聚","汇聚","集中"],"answer":1,"explanation":"「凝聚」多与「共识、人心、力量」搭配，强调由分散到统一；「聚集」侧重物理集合；「集中」侧重把分散的集中起来。故选B。","__sub":"选词填空"},{"id":"yy-15610","module":"yanyu","diff":3,"exam":"国考","prompt":"一个朴素的道理反复被验证：方向对了，努力才不会白费。面对新形势新任务，必须______产业结构，牢牢把握发展主动权。这也正是成事的关键所在。填入画横线处最恰当的是：","options":["改进","优化","改善","调整"],"answer":1,"explanation":"「优化」指加以改变使其优良，与「环境、结构」搭配规范；「改善」多与「条件、生活」搭配；「改进」多与「方法、工作」搭配；「调整」不含变优之义。故选B。","__sub":"选词填空"},{"id":"yy-15611","module":"yanyu","diff":1,"exam":"省考","prompt":"事物的发展自有其规律，顺应它才能事半功倍。下一步，将______执法力量，推动各项工作再上新台阶。这样的要求，放在哪里都不过时。填入画横线处最恰当的是：","options":["下沉","下潜","下坠","下探"],"answer":0,"explanation":"「下沉」指治理资源向基层倾斜，是规范表述；「下潜」指潜水，「下探」多指价格或行动试探，「下坠」指物体坠落。故选A。","__sub":"选词填空"},{"id":"yy-15613","module":"yanyu","diff":1,"exam":"教师编","prompt":"事物的发展自有其规律，顺应它才能事半功倍。只有责任担当真正______到基层，才能让政策在「最后一公里」落地见效。这样的要求，放在哪里都不过时。填入画横线处最恰当的是：","options":["深化","增强","强化","加强"],"answer":2,"explanation":"「强化」与「意识、思维」搭配，强调使之更牢固；「增强」语义相近但搭配习惯不同；「加强」为通用动词；「深化」指向深处发展。故选C。","__sub":"选词填空"},{"id":"yy-15614","module":"yanyu","diff":2,"exam":"国考","prompt":"现实中，方法与态度不同，结果往往截然不同。只有城市建设各环节真正______到基层，才能让政策在「最后一公里」落地见效。看似寻常，实则是长期积累的结果。填入画横线处最恰当的是：","options":["穿过","经过","贯穿","贯串"],"answer":2,"explanation":"「贯穿」指从头到尾通贯，与「全过程」搭配规范；「穿过」「经过」仅指空间或时间经过，不含通贯始终之义。故选C。","__sub":"选词填空"},{"id":"yy-15615","module":"yanyu","diff":2,"exam":"医疗编","prompt":"任何工作要见成效，都离不开科学的方法和踏实的作风。各级政府要持续______初心，不断增强群众的获得感、幸福感、安全感。唯有如此，才能把好事办好、实事办实。填入画横线处最恰当的是：","options":["砥砺","锤炼","锻炼","磨砺"],"answer":0,"explanation":"「砥砺」本义为磨刀石，引申为磨炼，与「意志」搭配且语体庄重；「磨砺」与之近义但「砥砺」更常用于「砥砺前行、砥砺意志」。故选A。","__sub":"选词填空"},{"id":"yy-15616","module":"yanyu","diff":2,"exam":"省考","prompt":"很多事看起来简单，真要做扎实并不容易。下一步，将______资源、服务、管理，推动各项工作再上新台阶。道理虽朴素，真正做到并不容易。填入画横线处最恰当的是：","options":["下沉","下探","下坠","下潜"],"answer":0,"explanation":"「下沉」指治理资源向基层倾斜，是规范表述；「下潜」指潜水，「下探」多指价格或行动试探，「下坠」指物体坠落。故选A。","__sub":"选词填空"},{"id":"yy-15617","module":"yanyu","diff":2,"exam":"教师编","prompt":"事物的发展自有其规律，顺应它才能事半功倍。下一步，将______产业结构，推动各项工作再上新台阶。这样的要求，放在哪里都不过时。填入画横线处最恰当的是：","options":["优化","调整","改进","改善"],"answer":0,"explanation":"「优化」指加以改变使其优良，与「环境、结构」搭配规范；「改善」多与「条件、生活」搭配；「改进」多与「方法、工作」搭配；「调整」不含变优之义。故选A。","__sub":"选词填空"},{"id":"yy-15618","module":"yanyu","diff":2,"exam":"省考","prompt":"无论时代如何变化，把事情做实做细始终是成事的基础。回顾这些年走过的路，______智慧和力量始终是我们攻坚克难的重要法宝。这背后考验的正是把握分寸的智慧。填入画横线处最恰当的是：","options":["凝聚","聚集","集中","汇聚"],"answer":0,"explanation":"「凝聚」多与「共识、人心、力量」搭配，强调由分散到统一；「聚集」侧重物理集合；「集中」侧重把分散的集中起来。故选A。","__sub":"选词填空"},{"id":"yy-15619","module":"yanyu","diff":3,"exam":"国考","prompt":"无论时代如何变化，把事情做实做细始终是成事的基础。面对新形势新任务，必须______制造业高质量发展，牢牢把握发展主动权。这背后考验的正是把握分寸的智慧。填入画横线处最恰当的是：","options":["赋能","助力","加持","赋权"],"answer":0,"explanation":"「赋能」指赋予能力，是数字经济语境的规范表述；「赋权」指赋予权力；「加持」为口语化外来词；「助力」语义宽泛。故选A。","__sub":"选词填空"},{"id":"yy-15620","module":"yanyu","diff":3,"exam":"教师编","prompt":"很多事看起来简单，真要做扎实并不容易。下一步，将______能源结构，推动各项工作再上新台阶。道理虽朴素，真正做到并不容易。填入画横线处最恰当的是：","options":["调整","改进","改善","优化"],"answer":3,"explanation":"「优化」指加以改变使其优良，与「环境、结构」搭配规范；「改善」多与「条件、生活」搭配；「改进」多与「方法、工作」搭配；「调整」不含变优之义。故选D。","__sub":"选词填空"},{"id":"yy-15621","module":"yanyu","diff":1,"exam":"国考","prompt":"任何工作要见成效，都离不开科学的方法和踏实的作风。只有时代脉搏真正______到基层，才能让政策在「最后一公里」落地见效。唯有如此，才能把好事办好、实事办实。填入画横线处最恰当的是：","options":["把握","把守","把玩","把持"],"answer":0,"explanation":"「把握」与抽象事物（特点、规律、机遇）搭配；「把守」指守卫关口，「把持」含贬义指独揽，「把玩」指赏玩物品。故选A。","__sub":"选词填空"},{"id":"yy-15622","module":"yanyu","diff":1,"exam":"事业编","prompt":"一个朴素的道理反复被验证：方向对了，努力才不会白费。要在______中小企业发展上下更大功夫，让发展成果更多惠及全体人民。这也正是成事的关键所在。填入画横线处最恰当的是：","options":["赋权","赋能","助力","加持"],"answer":1,"explanation":"「赋能」指赋予能力，是数字经济语境的规范表述；「赋权」指赋予权力；「加持」为口语化外来词；「助力」语义宽泛。故选B。","__sub":"选词填空"},{"id":"yy-15627","module":"yanyu","diff":2,"exam":"省考","prompt":"各级政府要持续______资源、服务、管理，不断增强群众的获得感、幸福感、安全感。填入画横线处最恰当的是：","options":["下沉","下探","下潜","下坠"],"answer":0,"explanation":"「下沉」指治理资源向基层倾斜，是规范表述；「下潜」指潜水，「下探」多指价格或行动试探，「下坠」指物体坠落。故选A。","__sub":"选词填空"},{"id":"yy-15629","module":"yanyu","diff":3,"exam":"国考","prompt":"只有不发生系统性风险的底线真正______到基层，才能让政策在「最后一公里」落地见效。填入画横线处最恰当的是：","options":["防住","守牢","把牢","守住"],"answer":1,"explanation":"「守牢」与「底线」搭配，强调牢牢守住；「守住」程度稍弱；「把牢」多与「关口」搭配；「防住」为口语。故选B。","__sub":"选词填空"},{"id":"yy-15633","module":"yanyu","diff":1,"exam":"教师编","prompt":"干事创业，思路和坚持缺一不可。回顾这些年走过的路，______法治体系始终是我们攻坚克难的重要法宝。其中的道理值得每个人细细体会。填入画横线处最恰当的是：","options":["完善","构建","健全","建立"],"answer":2,"explanation":"「健全」强调使完备无缺，与「体系」搭配规范；「建立」指从无到有，「完善」指补足短板，「构建」侧重搭建框架。故选C。","__sub":"选词填空"},{"id":"yy-15634","module":"yanyu","diff":2,"exam":"国考","prompt":"当前正值关键时期，______经济社会发展全过程刻不容缓，必须抓紧抓实抓出成效。填入画横线处最恰当的是：","options":["贯串","贯穿","经过","穿过"],"answer":1,"explanation":"「贯穿」指从头到尾通贯，与「全过程」搭配规范；「穿过」「经过」仅指空间或时间经过，不含通贯始终之义。故选B。","__sub":"选词填空"},{"id":"yy-15637","module":"yanyu","diff":2,"exam":"省考","prompt":"事物的发展自有其规律，顺应它才能事半功倍。面对新形势新任务，必须______新时代发展的宏伟蓝图，牢牢把握发展主动权。这样的要求，放在哪里都不过时。填入画横线处最恰当的是：","options":["描绘","勾画","规划","擘画"],"answer":3,"explanation":"「擘画」指筹划布置，多用于宏观蓝图，书面色彩浓；「描绘」「勾画」偏具体画面；「规划」语体色彩不足。故选D。","__sub":"选词填空"},{"id":"yy-15638","module":"yanyu","diff":2,"exam":"省考","prompt":"任何工作要见成效，都离不开科学的方法和踏实的作风。下一步，将______改革任务书，推动各项工作再上新台阶。唯有如此，才能把好事办好、实事办实。填入画横线处最恰当的是：","options":["锁定","盯住","锚定","瞄准"],"answer":2,"explanation":"「锚定」比喻像锚一样固定住目标，多用于宏观战略语境；「锁定」「瞄准」「盯住」语体偏口语，庄重色彩不足。故选C。","__sub":"选词填空"},{"id":"yy-15639","module":"yanyu","diff":3,"exam":"省考","prompt":"现实中，方法与态度不同，结果往往截然不同。下一步，将______安全事故多发的势头，推动各项工作再上新台阶。看似寻常，实则是长期积累的结果。填入画横线处最恰当的是：","options":["控制","遏制","遏止","制止"],"answer":1,"explanation":"「遏制」强调压制住势头、多与「势头/态势」搭配；「遏止」侧重使之停止，多用于具体行为；「控制」「制止」语义宽泛。故选B。","__sub":"选词填空"},{"id":"yy-15640","module":"yanyu","diff":3,"exam":"国考","prompt":"现实中，方法与态度不同，结果往往截然不同。只有耕地保护红线真正______到基层，才能让政策在「最后一公里」落地见效。看似寻常，实则是长期积累的结果。填入画横线处最恰当的是：","options":["守牢","把牢","防住","守住"],"answer":0,"explanation":"「守牢」与「底线」搭配，强调牢牢守住；「守住」程度稍弱；「把牢」多与「关口」搭配；「防住」为口语。故选A。","__sub":"选词填空"},{"id":"yy-15641","module":"yanyu","diff":1,"exam":"医疗编","prompt":"观察身边的事不难发现，成败的分野常常藏在细节里。下一步，将______乡村发展内生动力，推动各项工作再上新台阶。说到底，拼的是态度，比的是功夫。填入画横线处最恰当的是：","options":["启动","驱动","激活","唤醒"],"answer":2,"explanation":"「激活」指刺激使之活跃，与「动力、要素」搭配；「唤醒」指使之觉醒；「启动」指开始进行；「驱动」指推动运转。故选C。","__sub":"选词填空"},{"id":"yy-15642","module":"yanyu","diff":1,"exam":"国考","prompt":"任何工作要见成效，都离不开科学的方法和踏实的作风。要在______人心上下更大功夫，让发展成果更多惠及全体人民。唯有如此，才能把好事办好、实事办实。填入画横线处最恰当的是：","options":["凝聚","汇聚","集中","聚集"],"answer":0,"explanation":"「凝聚」多与「共识、人心、力量」搭配，强调由分散到统一；「聚集」侧重物理集合；「集中」侧重把分散的集中起来。故选A。","__sub":"选词填空"},{"id":"yy-15643","module":"yanyu","diff":1,"exam":"省考","prompt":"现实中，方法与态度不同，结果往往截然不同。面对新形势新任务，必须______建设农业强国的目标，牢牢把握发展主动权。看似寻常，实则是长期积累的结果。填入画横线处最恰当的是：","options":["瞄准","盯住","锁定","锚定"],"answer":3,"explanation":"「锚定」比喻像锚一样固定住目标，多用于宏观战略语境；「锁定」「瞄准」「盯住」语体偏口语，庄重色彩不足。故选D。","__sub":"选词填空"},{"id":"yy-15648","module":"yanyu","diff":2,"exam":"省考","prompt":"任何工作要见成效，都离不开科学的方法和踏实的作风。下一步，将______视野和思路，推动各项工作再上新台阶。唯有如此，才能把好事办好、实事办实。填入画横线处最恰当的是：","options":["开拓","拓宽","扩大","延伸"],"answer":1,"explanation":"「拓宽」与「渠道、门路、视野」搭配；「开拓」指开辟新领域；「扩大」多与「规模、范围」搭配；「延伸」侧重长度延长。故选B。","__sub":"选词填空"},{"id":"yy-15649","module":"yanyu","diff":3,"exam":"省考","prompt":"一个朴素的道理反复被验证：方向对了，努力才不会白费。要坚持问题导向，______文明乡风，切实解决群众急难愁盼问题。这也正是成事的关键所在。填入画横线处最恰当的是：","options":["营造","涵养","培养","养护"],"answer":1,"explanation":"「涵养」指蓄积并养护，与「生态、水源」搭配；「培养」对象为人或能力；「营造」多与「氛围、环境」搭配；「养护」不含培育之义。故选B。","__sub":"选词填空"},{"id":"yy-15651","module":"yanyu","diff":1,"exam":"教师编","prompt":"事物的发展自有其规律，顺应它才能事半功倍。要在______监管责任上下更大功夫，让发展成果更多惠及全体人民。这样的要求，放在哪里都不过时。填入画横线处最恰当的是：","options":["强化","压紧","落实","压实"],"answer":3,"explanation":"「压实」与「责任」搭配，强调责任层层落实到位；「落实」为通用动词；「压紧」常作「压紧压实」；「强化」不如「压实」精准体现层级传导。故选D。","__sub":"选词填空"},{"id":"yy-15653","module":"yanyu","diff":1,"exam":"省考","prompt":"任何工作要见成效，都离不开科学的方法和踏实的作风。要坚持问题导向，______制度堤坝，切实解决群众急难愁盼问题。唯有如此，才能把好事办好、实事办实。填入画横线处最恰当的是：","options":["构建","筑牢","筑造","夯实"],"answer":1,"explanation":"「筑牢」与「防线」为固定搭配，强调使牢固；「筑造」指建造实体；「构建」侧重搭建体系；「夯实」多与「基础」搭配。故选B。","__sub":"选词填空"},{"id":"yy-15654","module":"yanyu","diff":2,"exam":"教师编","prompt":"观察身边的事不难发现，成败的分野常常藏在细节里。下一步，将______市场主体活力，推动各项工作再上新台阶。说到底，拼的是态度，比的是功夫。填入画横线处最恰当的是：","options":["引发","点燃","调动","激发"],"answer":3,"explanation":"「激发」与「活力、热情、潜能」为固定搭配；「引发」多与「关注、争议」搭配；「点燃」为比喻用法；「调动」多与「积极性」搭配。故选D。","__sub":"选词填空"},{"id":"yy-15656","module":"yanyu","diff":2,"exam":"国考","prompt":"任何工作要见成效，都离不开科学的方法和踏实的作风。各地区各部门要拿出真招实招，______志愿服务体系，确保各项部署落地生根。唯有如此，才能把好事办好、实事办实。填入画横线处最恰当的是：","options":["搭建","完善","构建","健全"],"answer":3,"explanation":"「健全」强调使完备无缺；「完善」指补足短板；「构建」「搭建」侧重从无到有搭建。故选D。","__sub":"选词填空"},{"id":"yy-15657","module":"yanyu","diff":2,"exam":"省考","prompt":"事物的发展自有其规律，顺应它才能事半功倍。面对新形势新任务，必须______创新创造潜能，牢牢把握发展主动权。这样的要求，放在哪里都不过时。填入画横线处最恰当的是：","options":["引发","点燃","激发","调动"],"answer":2,"explanation":"「激发」与「活力、热情、潜能」为固定搭配；「引发」多与「关注、争议」搭配；「点燃」为比喻用法；「调动」多与「积极性」搭配。故选C。","__sub":"选词填空"},{"id":"yy-15658","module":"yanyu","diff":2,"exam":"国考","prompt":"一个朴素的道理反复被验证：方向对了，努力才不会白费。要坚持问题导向，______制度漏洞，切实解决群众急难愁盼问题。这也正是成事的关键所在。填入画横线处最恰当的是：","options":["补足","补齐","填补","弥补"],"answer":1,"explanation":"「补齐」与「短板」为固定搭配，强调使达到应有水平；「补足」多与「差额」搭配；「填补」多与「空白」搭配；「弥补」多与「损失」搭配。故选B。","__sub":"选词填空"},{"id":"yy-15659","module":"yanyu","diff":3,"exam":"教师编","prompt":"干事创业，思路和坚持缺一不可。下一步，将______消费潜力，推动各项工作再上新台阶。唯有如此，才能把好事办好、实事办实。填入画横线处最恰当的是：","options":["爆发","发挥","释放","散发"],"answer":2,"explanation":"「释放」与「潜力、红利、活力」搭配；「散发」指分散发出；「发挥」与「作用」搭配；「爆发」指突然发作。故选C。","__sub":"选词填空"},{"id":"yy-15661","module":"yanyu","diff":1,"exam":"国考","prompt":"现实中，方法与态度不同，结果往往截然不同。越是任务艰巨，越要______腐败蔓延的态势，确保方向不偏、力度不减。看似寻常，实则是长期积累的结果。填入画横线处最恰当的是：","options":["控制","制止","遏制","遏止"],"answer":2,"explanation":"「遏制」强调压制住势头、多与「势头/态势」搭配；「遏止」侧重使之停止，多用于具体行为；「控制」「制止」语义宽泛。故选C。","__sub":"选词填空"},{"id":"yy-15662","module":"yanyu","diff":1,"exam":"事业编","prompt":"现实中，方法与态度不同，结果往往截然不同。新征程上，要继续______民生短板，以实干实绩回应人民期盼。看似寻常，实则是长期积累的结果。填入画横线处最恰当的是：","options":["补齐","补足","填补","弥补"],"answer":0,"explanation":"「补齐」与「短板」为固定搭配，强调使达到应有水平；「补足」多与「差额」搭配；「填补」多与「空白」搭配；「弥补」多与「损失」搭配。故选A。","__sub":"选词填空"},{"id":"yy-15664","module":"yanyu","diff":2,"exam":"教师编","prompt":"事物的发展自有其规律，顺应它才能事半功倍。当前正值关键时期，______乡村振兴始终刻不容缓，必须抓紧抓实抓出成效。这样的要求，放在哪里都不过时。填入画横线处最恰当的是：","options":["经过","贯串","穿过","贯穿"],"answer":3,"explanation":"「贯穿」指从头到尾通贯，与「全过程」搭配规范；「穿过」「经过」仅指空间或时间经过，不含通贯始终之义。故选D。","__sub":"选词填空"},{"id":"yy-15665","module":"yanyu","diff":2,"exam":"国考","prompt":"无论时代如何变化，把事情做实做细始终是成事的基础。各地区各部门要拿出真招实招，______服务空白，确保各项部署落地生根。这背后考验的正是把握分寸的智慧。填入画横线处最恰当的是：","options":["弥补","补足","填补","补齐"],"answer":3,"explanation":"「补齐」与「短板」为固定搭配，强调使达到应有水平；「补足」多与「差额」搭配；「填补」多与「空白」搭配；「弥补」多与「损失」搭配。故选D。","__sub":"选词填空"},{"id":"yy-15666","module":"yanyu","diff":2,"exam":"国考","prompt":"干事创业，思路和坚持缺一不可。新征程上，要继续______企业主体责任，以实干实绩回应人民期盼。其中的道理值得每个人细细体会。填入画横线处最恰当的是：","options":["落实","压实","强化","压紧"],"answer":1,"explanation":"「压实」与「责任」搭配，强调责任层层落实到位；「落实」为通用动词；「压紧」常作「压紧压实」；「强化」不如「压实」精准体现层级传导。故选B。","__sub":"选词填空"},{"id":"yy-15667","module":"yanyu","diff":2,"exam":"教师编","prompt":"任何工作要见成效，都离不开科学的方法和踏实的作风。回顾这些年走过的路，______供给侧结构性改革始终是我们攻坚克难的重要法宝。唯有如此，才能把好事办好、实事办实。填入画横线处最恰当的是：","options":["深化","推进","深入","加强"],"answer":0,"explanation":"「深化」指向更深阶段发展，与「改革」为固定搭配；「深入」多作形容词或「深入调查」；「加强」「推进」语义宽泛。故选A。","__sub":"选词填空"},{"id":"yy-15669","module":"yanyu","diff":3,"exam":"医疗编","prompt":"干事创业，思路和坚持缺一不可。下一步，将______城市文化气质，推动各项工作再上新台阶。其中的道理值得每个人细细体会。填入画横线处最恰当的是：","options":["养护","涵养","营造","培养"],"answer":1,"explanation":"「涵养」指蓄积并养护，与「生态、水源」搭配；「培养」对象为人或能力；「营造」多与「氛围、环境」搭配；「养护」不含培育之义。故选B。","__sub":"选词填空"},{"id":"yy-15671","module":"yanyu","diff":1,"exam":"国考","prompt":"干事创业，思路和坚持缺一不可。各级政府要持续______放管服改革，不断增强群众的获得感、幸福感、安全感。其中的道理值得每个人细细体会。填入画横线处最恰当的是：","options":["深入","推进","深化","加强"],"answer":2,"explanation":"「深化」指向更深阶段发展，与「改革」为固定搭配；「深入」多作形容词或「深入调查」；「加强」「推进」语义宽泛。故选C。","__sub":"选词填空"},{"id":"yy-15672","module":"yanyu","diff":1,"exam":"省考","prompt":"一个朴素的道理反复被验证：方向对了，努力才不会白费。新征程上，要继续______放管服改革，以实干实绩回应人民期盼。这也正是成事的关键所在。填入画横线处最恰当的是：","options":["深化","加强","深入","推进"],"answer":0,"explanation":"「深化」指向更深阶段发展，与「改革」为固定搭配；「深入」多作形容词或「深入调查」；「加强」「推进」语义宽泛。故选A。","__sub":"选词填空"},{"id":"yy-15673","module":"yanyu","diff":1,"exam":"国考","prompt":"观察身边的事不难发现，成败的分野常常藏在细节里。下一步，将______创新土壤，推动各项工作再上新台阶。说到底，拼的是态度，比的是功夫。填入画横线处最恰当的是：","options":["涵养","养护","培养","营造"],"answer":0,"explanation":"「涵养」指蓄积并养护，与「生态、水源」搭配；「培养」对象为人或能力；「营造」多与「氛围、环境」搭配；「养护」不含培育之义。故选A。","__sub":"选词填空"},{"id":"yy-15674","module":"yanyu","diff":2,"exam":"国考","prompt":"现实中，方法与态度不同，结果往往截然不同。新征程上，要继续______群众增收渠道，以实干实绩回应人民期盼。看似寻常，实则是长期积累的结果。填入画横线处最恰当的是：","options":["延伸","扩大","开拓","拓宽"],"answer":3,"explanation":"「拓宽」与「渠道、门路、视野」搭配；「开拓」指开辟新领域；「扩大」多与「规模、范围」搭配；「延伸」侧重长度延长。故选D。","__sub":"选词填空"},{"id":"yy-15675","module":"yanyu","diff":2,"exam":"教师编","prompt":"事物的发展自有其规律，顺应它才能事半功倍。只有就业服务体系真正______到基层，才能让政策在「最后一公里」落地见效。这样的要求，放在哪里都不过时。填入画横线处最恰当的是：","options":["健全","构建","建立","完善"],"answer":0,"explanation":"「健全」强调使完备无缺，与「体系」搭配规范；「建立」指从无到有，「完善」指补足短板，「构建」侧重搭建框架。故选A。","__sub":"选词填空"},{"id":"yy-15676","module":"yanyu","diff":2,"exam":"教师编","prompt":"一个朴素的道理反复被验证：方向对了，努力才不会白费。下一步，将______新时代发展的宏伟蓝图，推动各项工作再上新台阶。这也正是成事的关键所在。填入画横线处最恰当的是：","options":["擘画","描绘","勾画","规划"],"answer":0,"explanation":"「擘画」指筹划布置，多用于宏观蓝图，书面色彩浓；「描绘」「勾画」偏具体画面；「规划」语体色彩不足。故选A。","__sub":"选词填空"},{"id":"yy-15679","module":"yanyu","diff":3,"exam":"事业编","prompt":"一个朴素的道理反复被验证：方向对了，努力才不会白费。只有安全屏障真正______到基层，才能让政策在「最后一公里」落地见效。这也正是成事的关键所在。填入画横线处最恰当的是：","options":["夯实","构建","筑牢","筑造"],"answer":2,"explanation":"「筑牢」与「防线」为固定搭配，强调使牢固；「筑造」指建造实体；「构建」侧重搭建体系；「夯实」多与「基础」搭配。故选C。","__sub":"选词填空"},{"id":"yy-15680","module":"yanyu","diff":3,"exam":"国考","prompt":"很多事看起来简单，真要做扎实并不容易。下一步，将______安全稳定底线，推动各项工作再上新台阶。道理虽朴素，真正做到并不容易。填入画横线处最恰当的是：","options":["守牢","守住","把牢","防住"],"answer":0,"explanation":"「守牢」与「底线」搭配，强调牢牢守住；「守住」程度稍弱；「把牢」多与「关口」搭配；「防住」为口语。故选A。","__sub":"选词填空"},{"id":"yy-15681","module":"yanyu","diff":1,"exam":"教师编","prompt":"无论时代如何变化，把事情做实做细始终是成事的基础。要坚持问题导向，______不发生系统性风险的底线，切实解决群众急难愁盼问题。这背后考验的正是把握分寸的智慧。填入画横线处最恰当的是：","options":["守住","把牢","防住","守牢"],"answer":3,"explanation":"「守牢」与「底线」搭配，强调牢牢守住；「守住」程度稍弱；「把牢」多与「关口」搭配；「防住」为口语。故选D。","__sub":"选词填空"},{"id":"yy-15682","module":"yanyu","diff":1,"exam":"国考","prompt":"一个朴素的道理反复被验证：方向对了，努力才不会白费。回顾这些年走过的路，______碳达峰碳中和目标始终是我们攻坚克难的重要法宝。这也正是成事的关键所在。填入画横线处最恰当的是：","options":["锁定","锚定","盯住","瞄准"],"answer":1,"explanation":"「锚定」比喻像锚一样固定住目标，多用于宏观战略语境；「锁定」「瞄准」「盯住」语体偏口语，庄重色彩不足。故选B。","__sub":"选词填空"},{"id":"yy-15683","module":"yanyu","diff":1,"exam":"国考","prompt":"只有碳达峰碳中和目标真正______到基层，才能让政策在「最后一公里」落地见效。填入画横线处最恰当的是：","options":["瞄准","盯住","锁定","锚定"],"answer":3,"explanation":"「锚定」比喻像锚一样固定住目标，多用于宏观战略语境；「锁定」「瞄准」「盯住」语体偏口语，庄重色彩不足。故选D。","__sub":"选词填空"},{"id":"yy-15684","module":"yanyu","diff":2,"exam":"医疗编","prompt":"观察身边的事不难发现，成败的分野常常藏在细节里。各级政府要持续______发展与安全，不断增强群众的获得感、幸福感、安全感。说到底，拼的是态度，比的是功夫。填入画横线处最恰当的是：","options":["协调","兼顾","统率","统筹"],"answer":3,"explanation":"「统筹」指全面筹划、统一安排，与「推进」搭配且强调全局性；「统率」指率领；「兼顾」只强调同时照顾；「协调」侧重配合关系。故选D。","__sub":"选词填空"},{"id":"yy-15685","module":"yanyu","diff":2,"exam":"省考","prompt":"观察身边的事不难发现，成败的分野常常藏在细节里。面对新形势新任务，必须______视野和思路，牢牢把握发展主动权。说到底，拼的是态度，比的是功夫。填入画横线处最恰当的是：","options":["开拓","拓宽","延伸","扩大"],"answer":1,"explanation":"「拓宽」与「渠道、门路、视野」搭配；「开拓」指开辟新领域；「扩大」多与「规模、范围」搭配；「延伸」侧重长度延长。故选B。","__sub":"选词填空"},{"id":"yy-15686","module":"yanyu","diff":2,"exam":"医疗编","prompt":"现实中，方法与态度不同，结果往往截然不同。实践证明，______政企沟通机制是推动高质量发展的关键一招。看似寻常，实则是长期积累的结果。填入画横线处最恰当的是：","options":["打通","开拓","畅通","疏通"],"answer":2,"explanation":"「畅通」强调使通畅无阻，与「渠道」为固定搭配；「打通」侧重突破障碍；「疏通」多用于管道或疏导矛盾；「开拓」指开辟新领域。故选C。","__sub":"选词填空"},{"id":"yy-15691","module":"yanyu","diff":1,"exam":"省考","prompt":"观察身边的事不难发现，成败的分野常常藏在细节里。当前正值关键时期，______教育资源配置刻不容缓，必须抓紧抓实抓出成效。说到底，拼的是态度，比的是功夫。填入画横线处最恰当的是：","options":["下潜","下沉","下坠","下探"],"answer":1,"explanation":"「下沉」指治理资源向基层倾斜，是规范表述；「下潜」指潜水，「下探」多指价格或行动试探，「下坠」指物体坠落。故选B。","__sub":"选词填空"},{"id":"yy-15692","module":"yanyu","diff":1,"exam":"事业编","prompt":"观察身边的事不难发现，成败的分野常常藏在细节里。要在______安全生产责任上下更大功夫，让发展成果更多惠及全体人民。说到底，拼的是态度，比的是功夫。填入画横线处最恰当的是：","options":["压实","压紧","落实","强化"],"answer":0,"explanation":"「压实」与「责任」搭配，强调责任层层落实到位；「落实」为通用动词；「压紧」常作「压紧压实」；「强化」不如「压实」精准体现层级传导。故选A。","__sub":"选词填空"},{"id":"yy-15694","module":"yanyu","diff":2,"exam":"省考","prompt":"事物的发展自有其规律，顺应它才能事半功倍。回顾这些年走过的路，______爱国情怀始终是我们攻坚克难的重要法宝。这样的要求，放在哪里都不过时。填入画横线处最恰当的是：","options":["加深","厚植","培植","筑牢"],"answer":1,"explanation":"「厚植」指深厚培育，与「优势、底色、根基」搭配；「培植」多用于培育动植物或扶植势力；「加深」与「底色」搭配不当。故选B。","__sub":"选词填空"},{"id":"yy-15695","module":"yanyu","diff":2,"exam":"事业编","prompt":"现实中，方法与态度不同，结果往往截然不同。实践证明，______不发生系统性风险的底线是推动高质量发展的关键一招。看似寻常，实则是长期积累的结果。填入画横线处最恰当的是：","options":["防住","守住","守牢","把牢"],"answer":2,"explanation":"「守牢」与「底线」搭配，强调牢牢守住；「守住」程度稍弱；「把牢」多与「关口」搭配；「防住」为口语。故选C。","__sub":"选词填空"},{"id":"yy-15696","module":"yanyu","diff":2,"exam":"医疗编","prompt":"事物的发展自有其规律，顺应它才能事半功倍。当前正值关键时期，______政企沟通机制刻不容缓，必须抓紧抓实抓出成效。这样的要求，放在哪里都不过时。填入画横线处最恰当的是：","options":["疏通","开拓","打通","畅通"],"answer":3,"explanation":"「畅通」强调使通畅无阻，与「渠道」为固定搭配；「打通」侧重突破障碍；「疏通」多用于管道或疏导矛盾；「开拓」指开辟新领域。故选D。","__sub":"选词填空"},{"id":"yy-15698","module":"yanyu","diff":2,"exam":"省考","prompt":"事物的发展自有其规律，顺应它才能事半功倍。各地区各部门要拿出真招实招，______意志，确保各项部署落地生根。这样的要求，放在哪里都不过时。填入画横线处最恰当的是：","options":["砥砺","锤炼","磨砺","锻炼"],"answer":0,"explanation":"「砥砺」本义为磨刀石，引申为磨炼，与「意志」搭配且语体庄重；「磨砺」与之近义但「砥砺」更常用于「砥砺前行、砥砺意志」。故选A。","__sub":"选词填空"},{"id":"yy-15699","module":"yanyu","diff":3,"exam":"省考","prompt":"任何工作要见成效，都离不开科学的方法和踏实的作风。各级政府要持续______城市文化气质，不断增强群众的获得感、幸福感、安全感。唯有如此，才能把好事办好、实事办实。填入画横线处最恰当的是：","options":["培养","营造","养护","涵养"],"answer":3,"explanation":"「涵养」指蓄积并养护，与「生态、水源」搭配；「培养」对象为人或能力；「营造」多与「氛围、环境」搭配；「养护」不含培育之义。故选D。","__sub":"选词填空"},{"id":"yy-15701","module":"yanyu","diff":1,"exam":"事业编","prompt":"无论时代如何变化，把事情做实做细始终是成事的基础。要坚持问题导向，______基层基础，切实解决群众急难愁盼问题。这背后考验的正是把握分寸的智慧。填入画横线处最恰当的是：","options":["夯实","巩固","筑牢","打牢"],"answer":0,"explanation":"「夯实」本义为砸实地基，引申为使稳固，与「基础、根基」搭配；「筑牢」与「防线」搭配；「打牢」语体稍口语；「巩固」侧重使已有的更牢固。故选A。","__sub":"选词填空"},{"id":"yy-15702","module":"yanyu","diff":1,"exam":"国考","prompt":"一个朴素的道理反复被验证：方向对了，努力才不会白费。面对新形势新任务，必须______现代化建设的宏伟篇章，牢牢把握发展主动权。这也正是成事的关键所在。填入画横线处最恰当的是：","options":["勾画","规划","擘画","描绘"],"answer":2,"explanation":"「擘画」指筹划布置，多用于宏观蓝图，书面色彩浓；「描绘」「勾画」偏具体画面；「规划」语体色彩不足。故选C。","__sub":"选词填空"},{"id":"yy-15705","module":"yanyu","diff":2,"exam":"事业编","prompt":"一个朴素的道理反复被验证：方向对了，努力才不会白费。下一步，将______意志，推动各项工作再上新台阶。其中的道理值得每个人细细体会。填入画横线处最恰当的是：","options":["锻炼","砥砺","锤炼","磨砺"],"answer":1,"explanation":"「砥砺」本义为磨刀石，引申为磨炼，与「意志」搭配且语体庄重；「磨砺」与之近义但「砥砺」更常用于「砥砺前行、砥砺意志」。故选B。","__sub":"选词填空"},{"id":"yy-15708","module":"yanyu","diff":2,"exam":"教师编","prompt":"很多事看起来简单，真要做扎实并不容易。实践证明，______民意直达渠道是推动高质量发展的关键一招。道理虽朴素，真正做到并不容易。填入画横线处最恰当的是：","options":["开辟","贯通","打通","畅通"],"answer":3,"explanation":"「畅通」强调使通畅无阻，与「渠道、通道」搭配；「打通」侧重突破障碍；「贯通」指连接相通；「开辟」指新开路径。故选D。","__sub":"选词填空"},{"id":"yy-15709","module":"yanyu","diff":3,"exam":"国考","prompt":"任何工作要见成效，都离不开科学的方法和踏实的作风。当前正值关键时期，______群众增收渠道刻不容缓，必须抓紧抓实抓出成效。唯有如此，才能把好事办好、实事办实。填入画横线处最恰当的是：","options":["拓宽","延伸","扩大","开拓"],"answer":0,"explanation":"「拓宽」与「渠道、门路、视野」搭配；「开拓」指开辟新领域；「扩大」多与「规模、范围」搭配；「延伸」侧重长度延长。故选A。","__sub":"选词填空"},{"id":"yy-15710","module":"yanyu","diff":3,"exam":"事业编","prompt":"各地区各部门要拿出真招实招，______安全事故多发的势头，确保各项部署落地生根。填入画横线处最恰当的是：","options":["遏止","遏制","控制","制止"],"answer":1,"explanation":"「遏制」强调压制住势头、多与「势头/态势」搭配；「遏止」侧重使之停止，多用于具体行为；「控制」「制止」语义宽泛。故选B。","__sub":"选词填空"},{"id":"yy-15714","module":"yanyu","diff":2,"exam":"省考","prompt":"很多事看起来简单，真要做扎实并不容易。新征程上，要继续______供给侧结构性改革，以实干实绩回应人民期盼。道理虽朴素，真正做到并不容易。填入画横线处最恰当的是：","options":["推进","加强","深入","深化"],"answer":3,"explanation":"「深化」指向更深阶段发展，与「改革」为固定搭配；「深入」多作形容词或「深入调查」；「加强」「推进」语义宽泛。故选D。","__sub":"选词填空"},{"id":"yy-15715","module":"yanyu","diff":2,"exam":"省考","prompt":"无论时代如何变化，把事情做实做细始终是成事的基础。各地区各部门要拿出真招实招，______耕地保护红线，确保各项部署落地生根。这背后考验的正是把握分寸的智慧。填入画横线处最恰当的是：","options":["守住","守牢","防住","把牢"],"answer":1,"explanation":"「守牢」与「底线」搭配，强调牢牢守住；「守住」程度稍弱；「把牢」多与「关口」搭配；「防住」为口语。故选B。","__sub":"选词填空"},{"id":"yy-15716","module":"yanyu","diff":2,"exam":"教师编","prompt":"一个朴素的道理反复被验证：方向对了，努力才不会白费。要坚持问题导向，______城市建设各环节，切实解决群众急难愁盼问题。这也正是成事的关键所在。填入画横线处最恰当的是：","options":["贯穿","经过","贯串","穿过"],"answer":0,"explanation":"「贯穿」指从头到尾通贯，与「全过程」搭配规范；「穿过」「经过」仅指空间或时间经过，不含通贯始终之义。故选A。","__sub":"选词填空"},{"id":"yy-15717","module":"yanyu","diff":2,"exam":"国考","prompt":"很多事看起来简单，真要做扎实并不容易。越是任务艰巨，越要______社会保障网络，确保方向不偏、力度不减。道理虽朴素，真正做到并不容易。填入画横线处最恰当的是：","options":["构建","完善","健全","搭建"],"answer":2,"explanation":"「健全」强调使完备无缺；「完善」指补足短板；「构建」「搭建」侧重从无到有搭建。故选C。","__sub":"选词填空"},{"id":"yy-15718","module":"yanyu","diff":2,"exam":"省考","prompt":"任何工作要见成效，都离不开科学的方法和踏实的作风。新征程上，要继续______消费新增长点，以实干实绩回应人民期盼。唯有如此，才能把好事办好、实事办实。填入画横线处最恰当的是：","options":["培养","孕育","培植","培育"],"answer":3,"explanation":"「培育」与「产业、企业、市场」搭配；「培养」对象为人或能力；「培植」多用于动植物或含贬义；「孕育」强调正在形成。故选D。","__sub":"选词填空"},{"id":"yy-15719","module":"yanyu","diff":3,"exam":"国考","prompt":"任何工作要见成效，都离不开科学的方法和踏实的作风。要坚持问题导向，______产业结构，切实解决群众急难愁盼问题。唯有如此，才能把好事办好、实事办实。填入画横线处最恰当的是：","options":["改进","优化","调整","改善"],"answer":1,"explanation":"「优化」指加以改变使其优良，与「环境、结构」搭配规范；「改善」多与「条件、生活」搭配；「改进」多与「方法、工作」搭配；「调整」不含变优之义。故选B。","__sub":"选词填空"},{"id":"yy-15720","module":"yanyu","diff":3,"exam":"省考","prompt":"任何工作要见成效，都离不开科学的方法和踏实的作风。各级政府要持续______安全稳定底线，不断增强群众的获得感、幸福感、安全感。唯有如此，才能把好事办好、实事办实。填入画横线处最恰当的是：","options":["防住","把牢","守牢","守住"],"answer":2,"explanation":"「守牢」与「底线」搭配，强调牢牢守住；「守住」程度稍弱；「把牢」多与「关口」搭配；「防住」为口语。故选C。","__sub":"选词填空"},{"id":"yy-15722","module":"yanyu","diff":1,"exam":"省考","prompt":"任何工作要见成效，都离不开科学的方法和踏实的作风。新征程上，要继续______现代化建设的宏伟篇章，以实干实绩回应人民期盼。唯有如此，才能把好事办好、实事办实。填入画横线处最恰当的是：","options":["勾画","规划","擘画","描绘"],"answer":2,"explanation":"「擘画」指筹划布置，多用于宏观蓝图，书面色彩浓；「描绘」「勾画」偏具体画面；「规划」语体色彩不足。故选C。","__sub":"选词填空"},{"id":"yy-16002","module":"yanyu","diff":1,"exam":"国考","prompt":"事物的发展自有其规律，顺应它才能事半功倍。实践证明，______中小企业发展是推动高质量发展的关键一招。这样的要求，放在哪里都不过时。填入画横线处最恰当的是：","options":["赋权","助力","加持","赋能"],"answer":3,"explanation":"「赋能」指赋予能力，是数字经济语境的规范表述；「赋权」指赋予权力；「加持」为口语化外来词；「助力」语义宽泛。故选D。","__sub":"选词填空"},{"id":"yy-16003","module":"yanyu","diff":1,"exam":"医疗编","prompt":"很多事看起来简单，真要做扎实并不容易。越是任务艰巨，越要______制度漏洞，确保方向不偏、力度不减。道理虽朴素，真正做到并不容易。填入画横线处最恰当的是：","options":["补齐","弥补","填补","补足"],"answer":0,"explanation":"「补齐」与「短板」为固定搭配，强调使达到应有水平；「补足」多与「差额」搭配；「填补」多与「空白」搭配；「弥补」多与「损失」搭配。故选A。","__sub":"选词填空"},{"id":"yy-16008","module":"yanyu","diff":2,"exam":"事业编","prompt":"各级政府要持续______乡村振兴的壮美画卷，不断增强群众的获得感、幸福感、安全感。填入画横线处最恰当的是：","options":["勾画","擘画","规划","描绘"],"answer":1,"explanation":"「擘画」指筹划布置，多用于宏观蓝图，书面色彩浓；「描绘」「勾画」偏具体画面；「规划」语体色彩不足。故选B。","__sub":"选词填空"},{"id":"yy-16010","module":"yanyu","diff":3,"exam":"事业编","prompt":"任何工作要见成效，都离不开科学的方法和踏实的作风。各级政府要持续______创新土壤，不断增强群众的获得感、幸福感、安全感。唯有如此，才能把好事办好、实事办实。填入画横线处最恰当的是：","options":["培养","营造","涵养","养护"],"answer":2,"explanation":"「涵养」指蓄积并养护，与「生态、水源」搭配；「培养」对象为人或能力；「营造」多与「氛围、环境」搭配；「养护」不含培育之义。故选C。","__sub":"选词填空"},{"id":"yy-16013","module":"yanyu","diff":1,"exam":"国考","prompt":"各地区各部门要拿出真招实招，______建设农业强国的目标，确保各项部署落地生根。填入画横线处最恰当的是：","options":["锁定","锚定","瞄准","盯住"],"answer":1,"explanation":"「锚定」比喻像锚一样固定住目标，多用于宏观战略语境；「锁定」「瞄准」「盯住」语体偏口语，庄重色彩不足。故选B。","__sub":"选词填空"},{"id":"yy-16015","module":"yanyu","diff":2,"exam":"事业编","prompt":"无论时代如何变化，把事情做实做细始终是成事的基础。只有新兴产业真正______到基层，才能让政策在「最后一公里」落地见效。这背后考验的正是把握分寸的智慧。填入画横线处最恰当的是：","options":["培育","培植","孕育","培养"],"answer":0,"explanation":"「培育」与「产业、企业、市场」搭配；「培养」对象为人或能力；「培植」多用于动植物或含贬义；「孕育」强调正在形成。故选A。","__sub":"选词填空"},{"id":"yy-16016","module":"yanyu","diff":2,"exam":"国考","prompt":"很多事看起来简单，真要做扎实并不容易。要在______公共卫生体系短板上下更大功夫，让发展成果更多惠及全体人民。道理虽朴素，真正做到并不容易。填入画横线处最恰当的是：","options":["弥补","补足","补齐","填补"],"answer":2,"explanation":"「补齐」与「短板」为固定搭配，强调使达到应有水平；「补足」多与「差额」搭配；「填补」多与「空白」搭配；「弥补」多与「损失」搭配。故选C。","__sub":"选词填空"},{"id":"yy-16018","module":"yanyu","diff":2,"exam":"事业编","prompt":"任何工作要见成效，都离不开科学的方法和踏实的作风。当前正值关键时期，______就业服务体系刻不容缓，必须抓紧抓实抓出成效。唯有如此，才能把好事办好、实事办实。填入画横线处最恰当的是：","options":["健全","建立","完善","构建"],"answer":0,"explanation":"「健全」强调使完备无缺，与「体系」搭配规范；「建立」指从无到有，「完善」指补足短板，「构建」侧重搭建框架。故选A。","__sub":"选词填空"},{"id":"yy-16019","module":"yanyu","diff":3,"exam":"省考","prompt":"一个朴素的道理反复被验证：方向对了，努力才不会白费。当前正值关键时期，______初心刻不容缓，必须抓紧抓实抓出成效。这也正是成事的关键所在。填入画横线处最恰当的是：","options":["锻炼","锤炼","砥砺","磨砺"],"answer":2,"explanation":"「砥砺」本义为磨刀石，引申为磨炼，与「意志」搭配且语体庄重；「磨砺」与之近义但「砥砺」更常用于「砥砺前行、砥砺意志」。故选C。","__sub":"选词填空"},{"id":"yy-16020","module":"yanyu","diff":3,"exam":"教师编","prompt":"事物的发展自有其规律，顺应它才能事半功倍。要坚持问题导向，______安全底线，切实解决群众急难愁盼问题。这样的要求，放在哪里都不过时。填入画横线处最恰当的是：","options":["构建","夯实","筑牢","筑造"],"answer":2,"explanation":"「筑牢」与「防线」为固定搭配，强调使牢固；「筑造」指建造实体；「构建」侧重搭建体系；「夯实」多与「基础」搭配。故选C。","__sub":"选词填空"},{"id":"yy-16021","module":"yanyu","diff":1,"exam":"医疗编","prompt":"任何工作要见成效，都离不开科学的方法和踏实的作风。要在______生态恶化的趋势上下更大功夫，让发展成果更多惠及全体人民。唯有如此，才能把好事办好、实事办实。填入画横线处最恰当的是：","options":["控制","遏制","制止","遏止"],"answer":1,"explanation":"「遏制」强调压制住势头、多与「势头/态势」搭配；「遏止」侧重使之停止，多用于具体行为；「控制」「制止」语义宽泛。故选B。","__sub":"选词填空"},{"id":"yy-16023","module":"yanyu","diff":1,"exam":"事业编","prompt":"一个朴素的道理反复被验证：方向对了，努力才不会白费。各地区各部门要拿出真招实招，______发展根基，确保各项部署落地生根。这也正是成事的关键所在。填入画横线处最恰当的是：","options":["打牢","巩固","筑牢","夯实"],"answer":3,"explanation":"「夯实」本义为砸实地基，引申为使稳固，与「基础、根基」搭配；「筑牢」与「防线」搭配；「打牢」语体稍口语；「巩固」侧重使已有的更牢固。故选D。","__sub":"选词填空"},{"id":"yy-16024","module":"yanyu","diff":2,"exam":"事业编","prompt":"任何工作要见成效，都离不开科学的方法和踏实的作风。面对新形势新任务，必须______安全稳定底线，牢牢把握发展主动权。唯有如此，才能把好事办好、实事办实。填入画横线处最恰当的是：","options":["守牢","把牢","守住","防住"],"answer":0,"explanation":"「守牢」与「底线」搭配，强调牢牢守住；「守住」程度稍弱；「把牢」多与「关口」搭配；「防住」为口语。故选A。","__sub":"选词填空"},{"id":"yy-16025","module":"yanyu","diff":2,"exam":"教师编","prompt":"很多事看起来简单，真要做扎实并不容易。实践证明，______基层治理神经末梢是推动高质量发展的关键一招。道理虽朴素，真正做到并不容易。填入画横线处最恰当的是：","options":["启动","激活","驱动","唤醒"],"answer":1,"explanation":"「激活」指刺激使之活跃，与「动力、要素」搭配；「唤醒」指使之觉醒；「启动」指开始进行；「驱动」指推动运转。故选B。","__sub":"选词填空"},{"id":"yy-16026","module":"yanyu","diff":2,"exam":"国考","prompt":"一个朴素的道理反复被验证：方向对了，努力才不会白费。只有共同思想基础真正______到基层，才能让政策在「最后一公里」落地见效。这也正是成事的关键所在。填入画横线处最恰当的是：","options":["夯实","筑牢","巩固","打牢"],"answer":0,"explanation":"「夯实」本义为砸实地基，引申为使稳固，与「基础、根基」搭配；「筑牢」与「防线」搭配；「打牢」语体稍口语；「巩固」侧重使已有的更牢固。故选A。","__sub":"选词填空"},{"id":"yy-16029","module":"yanyu","diff":3,"exam":"省考","prompt":"事物的发展自有其规律，顺应它才能事半功倍。回顾这些年走过的路，______共识始终是我们攻坚克难的重要法宝。这样的要求，放在哪里都不过时。填入画横线处最恰当的是：","options":["集中","聚集","汇聚","凝聚"],"answer":3,"explanation":"「凝聚」多与「共识、人心、力量」搭配，强调由分散到统一；「聚集」侧重物理集合；「集中」侧重把分散的集中起来。故选D。","__sub":"选词填空"},{"id":"yy-16031","module":"yanyu","diff":1,"exam":"事业编","prompt":"现实中，方法与态度不同，结果往往截然不同。当前正值关键时期，______人才结构刻不容缓，必须抓紧抓实抓出成效。看似寻常，实则是长期积累的结果。填入画横线处最恰当的是：","options":["改进","调整","改善","优化"],"answer":3,"explanation":"「优化」指加以改变使其优良，与「环境、结构」搭配规范；「改善」多与「条件、生活」搭配；「改进」多与「方法、工作」搭配；「调整」不含变优之义。故选D。","__sub":"选词填空"},{"id":"yy-16032","module":"yanyu","diff":1,"exam":"事业编","prompt":"事物的发展自有其规律，顺应它才能事半功倍。要在______能源结构上下更大功夫，让发展成果更多惠及全体人民。这样的要求，放在哪里都不过时。填入画横线处最恰当的是：","options":["改进","优化","改善","调整"],"answer":1,"explanation":"「优化」指加以改变使其优良，与「环境、结构」搭配规范；「改善」多与「条件、生活」搭配；「改进」多与「方法、工作」搭配；「调整」不含变优之义。故选B。","__sub":"选词填空"},{"id":"yy-16035","module":"yanyu","diff":2,"exam":"省考","prompt":"无论时代如何变化，把事情做实做细始终是成事的基础。新征程上，要继续______廉洁底线，以实干实绩回应人民期盼。这背后考验的正是把握分寸的智慧。填入画横线处最恰当的是：","options":["筑牢","构建","夯实","筑造"],"answer":0,"explanation":"「筑牢」与「防线」为固定搭配，强调使牢固；「筑造」指建造实体；「构建」侧重搭建体系；「夯实」多与「基础」搭配。故选A。","__sub":"选词填空"},{"id":"yy-16036","module":"yanyu","diff":2,"exam":"事业编","prompt":"现实中，方法与态度不同，结果往往截然不同。新征程上，要继续______生产生活生态，以实干实绩回应人民期盼。看似寻常，实则是长期积累的结果。填入画横线处最恰当的是：","options":["兼顾","统率","协调","统筹"],"answer":3,"explanation":"「统筹」指全面筹划、统一安排，与「推进」搭配且强调全局性；「统率」指率领；「兼顾」只强调同时照顾；「协调」侧重配合关系。故选D。","__sub":"选词填空"},{"id":"yy-16037","module":"yanyu","diff":2,"exam":"国考","prompt":"无论时代如何变化，把事情做实做细始终是成事的基础。要坚持问题导向，______生态环保责任，切实解决群众急难愁盼问题。这背后考验的正是把握分寸的智慧。填入画横线处最恰当的是：","options":["压实","落实","强化","压紧"],"answer":0,"explanation":"「压实」与「责任」搭配，强调责任层层落实到位；「落实」为通用动词；「压紧」常作「压紧压实」；「强化」不如「压实」精准体现层级传导。故选A。","__sub":"选词填空"},{"id":"yy-16038","module":"yanyu","diff":2,"exam":"省考","prompt":"现实中，方法与态度不同，结果往往截然不同。越是任务艰巨，越要______消费潜力，确保方向不偏、力度不减。看似寻常，实则是长期积累的结果。填入画横线处最恰当的是：","options":["调动","激发","点燃","引发"],"answer":1,"explanation":"「激发」与「活力、热情、潜能」为固定搭配；「引发」多与「关注、争议」搭配；「点燃」为比喻用法；「调动」多与「积极性」搭配。故选B。","__sub":"选词填空"},{"id":"yy-16039","module":"yanyu","diff":3,"exam":"国考","prompt":"无论时代如何变化，把事情做实做细始终是成事的基础。越是任务艰巨，越要______建设农业强国的目标，确保方向不偏、力度不减。这背后考验的正是把握分寸的智慧。填入画横线处最恰当的是：","options":["锁定","瞄准","盯住","锚定"],"answer":3,"explanation":"「锚定」比喻像锚一样固定住目标，多用于宏观战略语境；「锁定」「瞄准」「盯住」语体偏口语，庄重色彩不足。故选D。","__sub":"选词填空"},{"id":"yy-16040","module":"yanyu","diff":3,"exam":"教师编","prompt":"无论时代如何变化，把事情做实做细始终是成事的基础。新征程上，要继续______发展合力，以实干实绩回应人民期盼。这背后考验的正是把握分寸的智慧。填入画横线处最恰当的是：","options":["汇聚","聚集","凝聚","集中"],"answer":2,"explanation":"「凝聚」多与「共识、人心、力量」搭配，强调由分散到统一；「聚集」侧重物理集合；「集中」侧重把分散的集中起来。故选C。","__sub":"选词填空"},{"id":"yy-16041","module":"yanyu","diff":1,"exam":"事业编","prompt":"事物的发展自有其规律，顺应它才能事半功倍。要在______爱国情怀上下更大功夫，让发展成果更多惠及全体人民。这样的要求，放在哪里都不过时。填入画横线处最恰当的是：","options":["培植","加深","筑牢","厚植"],"answer":3,"explanation":"「厚植」指深厚培育，与「优势、底色、根基」搭配；「培植」多用于培育动植物或扶植势力；「加深」与「底色」搭配不当。故选D。","__sub":"选词填空"},{"id":"yy-16042","module":"yanyu","diff":1,"exam":"国考","prompt":"各地区各部门要拿出真招实招，______乡村发展内生动力，确保各项部署落地生根。填入画横线处最恰当的是：","options":["激活","驱动","唤醒","启动"],"answer":0,"explanation":"「激活」指刺激使之活跃，与「动力、要素」搭配；「唤醒」指使之觉醒；「启动」指开始进行；「驱动」指推动运转。故选A。","__sub":"选词填空"},{"id":"yy-16043","module":"yanyu","diff":1,"exam":"国考","prompt":"回顾这些年走过的路，______现代化建设的宏伟篇章始终是我们攻坚克难的重要法宝。填入画横线处最恰当的是：","options":["擘画","规划","描绘","勾画"],"answer":0,"explanation":"「擘画」指筹划布置，多用于宏观蓝图，书面色彩浓；「描绘」「勾画」偏具体画面；「规划」语体色彩不足。故选A。","__sub":"选词填空"},{"id":"yy-16044","module":"yanyu","diff":2,"exam":"省考","prompt":"任何工作要见成效，都离不开科学的方法和踏实的作风。回顾这些年走过的路，______监管责任始终是我们攻坚克难的重要法宝。唯有如此，才能把好事办好、实事办实。填入画横线处最恰当的是：","options":["压紧","落实","强化","压实"],"answer":3,"explanation":"「压实」与「责任」搭配，强调责任层层落实到位；「落实」为通用动词；「压紧」常作「压紧压实」；「强化」不如「压实」精准体现层级传导。故选D。","__sub":"选词填空"},{"id":"yy-16045","module":"yanyu","diff":2,"exam":"事业编","prompt":"很多事看起来简单，真要做扎实并不容易。要在______资源配置上下更大功夫，让发展成果更多惠及全体人民。道理虽朴素，真正做到并不容易。填入画横线处最恰当的是：","options":["调整","优化","改善","改进"],"answer":1,"explanation":"「优化」指加以改变使其优良，与「环境、结构」搭配规范；「改善」多与「条件、生活」搭配；「改进」多与「方法、工作」搭配；「调整」不含变优之义。故选B。","__sub":"选词填空"},{"id":"yy-16046","module":"yanyu","diff":2,"exam":"医疗编","prompt":"无论时代如何变化，把事情做实做细始终是成事的基础。下一步，将______制造业高质量发展，推动各项工作再上新台阶。这背后考验的正是把握分寸的智慧。填入画横线处最恰当的是：","options":["加持","赋能","赋权","助力"],"answer":1,"explanation":"「赋能」指赋予能力，是数字经济语境的规范表述；「赋权」指赋予权力；「加持」为口语化外来词；「助力」语义宽泛。故选B。","__sub":"选词填空"},{"id":"yy-16047","module":"yanyu","diff":2,"exam":"省考","prompt":"很多事看起来简单，真要做扎实并不容易。各地区各部门要拿出真招实招，______政策效应，确保各项部署落地生根。道理虽朴素，真正做到并不容易。填入画横线处最恰当的是：","options":["散发","爆发","释放","发挥"],"answer":2,"explanation":"「释放」与「潜力、红利、活力」搭配；「散发」指分散发出；「发挥」与「作用」搭配；「爆发」指突然发作。故选C。","__sub":"选词填空"},{"id":"yy-16048","module":"yanyu","diff":2,"exam":"国考","prompt":"现实中，方法与态度不同，结果往往截然不同。面对新形势新任务，必须______改革开放各领域，牢牢把握发展主动权。看似寻常，实则是长期积累的结果。填入画横线处最恰当的是：","options":["贯串","穿过","经过","贯穿"],"answer":3,"explanation":"「贯穿」指从头到尾通贯，与「全过程」搭配规范；「穿过」「经过」仅指空间或时间经过，不含通贯始终之义。故选D。","__sub":"选词填空"},{"id":"yy-16049","module":"yanyu","diff":3,"exam":"省考","prompt":"干事创业，思路和坚持缺一不可。下一步，将______属地管理责任，推动各项工作再上新台阶。其中的道理值得每个人细细体会。填入画横线处最恰当的是：","options":["压紧","强化","落实","压实"],"answer":3,"explanation":"「压实」与「责任」搭配，强调责任层层落实到位；「落实」为通用动词；「压紧」常作「压紧压实」；「强化」不如「压实」精准体现层级传导。故选D。","__sub":"选词填空"},{"id":"yy-16052","module":"yanyu","diff":1,"exam":"教师编","prompt":"很多事看起来简单，真要做扎实并不容易。越是任务艰巨，越要______区域协调发展的新格局，确保方向不偏、力度不减。道理虽朴素，真正做到并不容易。填入画横线处最恰当的是：","options":["描绘","擘画","规划","勾画"],"answer":1,"explanation":"「擘画」指筹划布置，多用于宏观蓝图，书面色彩浓；「描绘」「勾画」偏具体画面；「规划」语体色彩不足。故选B。","__sub":"选词填空"},{"id":"yy-16055","module":"yanyu","diff":2,"exam":"省考","prompt":"很多事看起来简单，真要做扎实并不容易。实践证明，______市场主体活力是推动高质量发展的关键一招。道理虽朴素，真正做到并不容易。填入画横线处最恰当的是：","options":["激发","调动","引发","点燃"],"answer":0,"explanation":"「激发」与「活力、热情、潜能」为固定搭配；「引发」多与「关注、争议」搭配；「点燃」为比喻用法；「调动」多与「积极性」搭配。故选A。","__sub":"选词填空"},{"id":"yy-16056","module":"yanyu","diff":2,"exam":"事业编","prompt":"事物的发展自有其规律，顺应它才能事半功倍。越是任务艰巨，越要______全年经济增长目标，确保方向不偏、力度不减。这样的要求，放在哪里都不过时。填入画横线处最恰当的是：","options":["锚定","瞄准","锁定","盯住"],"answer":0,"explanation":"「锚定」比喻像锚一样固定住目标，多用于宏观战略语境；「锁定」「瞄准」「盯住」语体偏口语，庄重色彩不足。故选A。","__sub":"选词填空"},{"id":"yy-16057","module":"yanyu","diff":2,"exam":"事业编","prompt":"各级政府要持续______农村物流最后一公里，不断增强群众的获得感、幸福感、安全感。填入画横线处最恰当的是：","options":["畅通","贯通","开辟","打通"],"answer":0,"explanation":"「畅通」强调使通畅无阻，与「渠道、通道」搭配；「打通」侧重突破障碍；「贯通」指连接相通；「开辟」指新开路径。故选A。","__sub":"选词填空"},{"id":"yy-16058","module":"yanyu","diff":2,"exam":"国考","prompt":"无论时代如何变化，把事情做实做细始终是成事的基础。当前正值关键时期，______发展合力刻不容缓，必须抓紧抓实抓出成效。这背后考验的正是把握分寸的智慧。填入画横线处最恰当的是：","options":["聚集","集中","凝聚","汇聚"],"answer":2,"explanation":"「凝聚」多与「共识、人心、力量」搭配，强调由分散到统一；「聚集」侧重物理集合；「集中」侧重把分散的集中起来。故选C。","__sub":"选词填空"},{"id":"yy-16059","module":"yanyu","diff":3,"exam":"国考","prompt":"干事创业，思路和坚持缺一不可。只有农产品上行通道真正______到基层，才能让政策在「最后一公里」落地见效。其中的道理值得每个人细细体会。填入画横线处最恰当的是：","options":["畅通","开拓","疏通","打通"],"answer":0,"explanation":"「畅通」强调使通畅无阻，与「渠道」为固定搭配；「打通」侧重突破障碍；「疏通」多用于管道或疏导矛盾；「开拓」指开辟新领域。故选A。","__sub":"选词填空"},{"id":"yy-16065","module":"yanyu","diff":2,"exam":"事业编","prompt":"无论时代如何变化，把事情做实做细始终是成事的基础。实践证明，______爱国情怀是推动高质量发展的关键一招。这背后考验的正是把握分寸的智慧。填入画横线处最恰当的是：","options":["培植","加深","筑牢","厚植"],"answer":3,"explanation":"「厚植」指深厚培育，与「优势、底色、根基」搭配；「培植」多用于培育动植物或扶植势力；「加深」与「底色」搭配不当。故选D。","__sub":"选词填空"},{"id":"yy-16066","module":"yanyu","diff":2,"exam":"医疗编","prompt":"很多事看起来简单，真要做扎实并不容易。面对新形势新任务，必须______区域协调发展的新格局，牢牢把握发展主动权。道理虽朴素，真正做到并不容易。填入画横线处最恰当的是：","options":["规划","描绘","擘画","勾画"],"answer":2,"explanation":"「擘画」指筹划布置，多用于宏观蓝图，书面色彩浓；「描绘」「勾画」偏具体画面；「规划」语体色彩不足。故选C。","__sub":"选词填空"},{"id":"yy-16068","module":"yanyu","diff":2,"exam":"事业编","prompt":"任何工作要见成效，都离不开科学的方法和踏实的作风。回顾这些年走过的路，______视野和思路始终是我们攻坚克难的重要法宝。唯有如此，才能把好事办好、实事办实。填入画横线处最恰当的是：","options":["延伸","拓宽","扩大","开拓"],"answer":1,"explanation":"「拓宽」与「渠道、门路、视野」搭配；「开拓」指开辟新领域；「扩大」多与「规模、范围」搭配；「延伸」侧重长度延长。故选B。","__sub":"选词填空"},{"id":"yy-16070","module":"yanyu","diff":3,"exam":"省考","prompt":"事物的发展自有其规律，顺应它才能事半功倍。下一步，将______安全底线，推动各项工作再上新台阶。这样的要求，放在哪里都不过时。填入画横线处最恰当的是：","options":["筑造","夯实","筑牢","构建"],"answer":2,"explanation":"「筑牢」与「防线」为固定搭配，强调使牢固；「筑造」指建造实体；「构建」侧重搭建体系；「夯实」多与「基础」搭配。故选C。","__sub":"选词填空"},{"id":"yy-16071","module":"yanyu","diff":1,"exam":"省考","prompt":"干事创业，思路和坚持缺一不可。越是任务艰巨，越要______不发生系统性风险的底线，确保方向不偏、力度不减。其中的道理值得每个人细细体会。填入画横线处最恰当的是：","options":["守牢","守住","防住","把牢"],"answer":0,"explanation":"「守牢」与「底线」搭配，强调牢牢守住；「守住」程度稍弱；「把牢」多与「关口」搭配；「防住」为口语。故选A。","__sub":"选词填空"},{"id":"yy-16073","module":"yanyu","diff":1,"exam":"省考","prompt":"观察身边的事不难发现，成败的分野常常藏在细节里。越是任务艰巨，越要______生态保护红线，确保方向不偏、力度不减。说到底，拼的是态度，比的是功夫。填入画横线处最恰当的是：","options":["守住","守牢","防住","把牢"],"answer":1,"explanation":"「守牢」与「底线」搭配，强调牢牢守住；「守住」程度稍弱；「把牢」多与「关口」搭配；「防住」为口语。故选B。","__sub":"选词填空"},{"id":"yy-16074","module":"yanyu","diff":2,"exam":"事业编","prompt":"现实中，方法与态度不同，结果往往截然不同。只有乡村振兴真正______到基层，才能让政策在「最后一公里」落地见效。看似寻常，实则是长期积累的结果。填入画横线处最恰当的是：","options":["加持","助力","赋权","赋能"],"answer":3,"explanation":"「赋能」指赋予能力，是数字经济语境的规范表述；「赋权」指赋予权力；「加持」为口语化外来词；「助力」语义宽泛。故选D。","__sub":"选词填空"},{"id":"yy-16076","module":"yanyu","diff":2,"exam":"事业编","prompt":"无论时代如何变化，把事情做实做细始终是成事的基础。各地区各部门要拿出真招实招，______农产品上行通道，确保各项部署落地生根。这背后考验的正是把握分寸的智慧。填入画横线处最恰当的是：","options":["开拓","打通","畅通","疏通"],"answer":2,"explanation":"「畅通」强调使通畅无阻，与「渠道」为固定搭配；「打通」侧重突破障碍；「疏通」多用于管道或疏导矛盾；「开拓」指开辟新领域。故选C。","__sub":"选词填空"},{"id":"yy-16078","module":"yanyu","diff":2,"exam":"事业编","prompt":"一个朴素的道理反复被验证：方向对了，努力才不会白费。越是任务艰巨，越要______制造业高质量发展，确保方向不偏、力度不减。这也正是成事的关键所在。填入画横线处最恰当的是：","options":["赋权","加持","助力","赋能"],"answer":3,"explanation":"「赋能」指赋予能力，是数字经济语境的规范表述；「赋权」指赋予权力；「加持」为口语化外来词；「助力」语义宽泛。故选D。","__sub":"选词填空"},{"id":"yy-16079","module":"yanyu","diff":3,"exam":"省考","prompt":"很多事看起来简单，真要做扎实并不容易。新征程上，要继续______法治体系，以实干实绩回应人民期盼。道理虽朴素，真正做到并不容易。填入画横线处最恰当的是：","options":["完善","构建","健全","建立"],"answer":2,"explanation":"「健全」强调使完备无缺，与「体系」搭配规范；「建立」指从无到有，「完善」指补足短板，「构建」侧重搭建框架。故选C。","__sub":"选词填空"},{"id":"yy-16080","module":"yanyu","diff":3,"exam":"医疗编","prompt":"观察身边的事不难发现，成败的分野常常藏在细节里。各级政府要持续______生态环保责任，不断增强群众的获得感、幸福感、安全感。说到底，拼的是态度，比的是功夫。填入画横线处最恰当的是：","options":["压紧","落实","强化","压实"],"answer":3,"explanation":"「压实」与「责任」搭配，强调责任层层落实到位；「落实」为通用动词；「压紧」常作「压紧压实」；「强化」不如「压实」精准体现层级传导。故选D。","__sub":"选词填空"},{"id":"yy-16082","module":"yanyu","diff":1,"exam":"事业编","prompt":"干事创业，思路和坚持缺一不可。各级政府要持续______各类资源配置，不断增强群众的获得感、幸福感、安全感。其中的道理值得每个人细细体会。填入画横线处最恰当的是：","options":["兼顾","协调","统筹","统率"],"answer":2,"explanation":"「统筹」指全面筹划、统一安排，与「推进」搭配且强调全局性；「统率」指率领；「兼顾」只强调同时照顾；「协调」侧重配合关系。故选C。","__sub":"选词填空"},{"id":"yy-16083","module":"yanyu","diff":1,"exam":"国考","prompt":"任何工作要见成效，都离不开科学的方法和踏实的作风。新征程上，要继续______市场变化，以实干实绩回应人民期盼。唯有如此，才能把好事办好、实事办实。填入画横线处最恰当的是：","options":["把持","把握","把守","把玩"],"answer":1,"explanation":"「把握」与抽象事物（特点、规律、机遇）搭配；「把守」指守卫关口，「把持」含贬义指独揽，「把玩」指赏玩物品。故选B。","__sub":"选词填空"},{"id":"yy-16084","module":"yanyu","diff":2,"exam":"医疗编","prompt":"干事创业，思路和坚持缺一不可。回顾这些年走过的路，______消费潜力始终是我们攻坚克难的重要法宝。其中的道理值得每个人细细体会。填入画横线处最恰当的是：","options":["调动","引发","点燃","激发"],"answer":3,"explanation":"「激发」与「活力、热情、潜能」为固定搭配；「引发」多与「关注、争议」搭配；「点燃」为比喻用法；「调动」多与「积极性」搭配。故选D。","__sub":"选词填空"},{"id":"yy-16085","module":"yanyu","diff":2,"exam":"教师编","prompt":"干事创业，思路和坚持缺一不可。回顾这些年走过的路，______内生动力始终是我们攻坚克难的重要法宝。其中的道理值得每个人细细体会。填入画横线处最恰当的是：","options":["调动","激发","引发","点燃"],"answer":1,"explanation":"「激发」与「活力、热情、潜能」为固定搭配；「引发」多与「关注、争议」搭配；「点燃」为比喻用法；「调动」多与「积极性」搭配。故选B。","__sub":"选词填空"},{"id":"yy-16086","module":"yanyu","diff":2,"exam":"省考","prompt":"无论时代如何变化，把事情做实做细始终是成事的基础。面对新形势新任务，必须______文明乡风，牢牢把握发展主动权。这背后考验的正是把握分寸的智慧。填入画横线处最恰当的是：","options":["营造","培养","涵养","养护"],"answer":2,"explanation":"「涵养」指蓄积并养护，与「生态、水源」搭配；「培养」对象为人或能力；「营造」多与「氛围、环境」搭配；「养护」不含培育之义。故选C。","__sub":"选词填空"},{"id":"yy-16088","module":"yanyu","diff":2,"exam":"国考","prompt":"事物的发展自有其规律，顺应它才能事半功倍。下一步，将______法治体系，推动各项工作再上新台阶。这样的要求，放在哪里都不过时。填入画横线处最恰当的是：","options":["完善","健全","建立","构建"],"answer":1,"explanation":"「健全」强调使完备无缺，与「体系」搭配规范；「建立」指从无到有，「完善」指补足短板，「构建」侧重搭建框架。故选B。","__sub":"选词填空"},{"id":"yy-16090","module":"yanyu","diff":3,"exam":"省考","prompt":"事物的发展自有其规律，顺应它才能事半功倍。回顾这些年走过的路，______人才流动渠道始终是我们攻坚克难的重要法宝。这样的要求，放在哪里都不过时。填入画横线处最恰当的是：","options":["打通","疏通","开拓","畅通"],"answer":3,"explanation":"「畅通」强调使通畅无阻，与「渠道」为固定搭配；「打通」侧重突破障碍；「疏通」多用于管道或疏导矛盾；「开拓」指开辟新领域。故选D。","__sub":"选词填空"},{"id":"yy-16093","module":"yanyu","diff":1,"exam":"国考","prompt":"观察身边的事不难发现，成败的分野常常藏在细节里。要在______数据要素价值上下更大功夫，让发展成果更多惠及全体人民。说到底，拼的是态度，比的是功夫。填入画横线处最恰当的是：","options":["散发","爆发","释放","发挥"],"answer":2,"explanation":"「释放」与「潜力、红利、活力」搭配；「散发」指分散发出；「发挥」与「作用」搭配；「爆发」指突然发作。故选C。","__sub":"选词填空"},{"id":"yy-16094","module":"yanyu","diff":2,"exam":"事业编","prompt":"现实中，方法与态度不同，结果往往截然不同。面对新形势新任务，必须______风险意识，牢牢把握发展主动权。看似寻常，实则是长期积累的结果。填入画横线处最恰当的是：","options":["深化","增强","强化","加强"],"answer":2,"explanation":"「强化」与「意识、思维」搭配，强调使之更牢固；「增强」语义相近但搭配习惯不同；「加强」为通用动词；「深化」指向深处发展。故选C。","__sub":"选词填空"},{"id":"yy-16096","module":"yanyu","diff":2,"exam":"省考","prompt":"事物的发展自有其规律，顺应它才能事半功倍。要在______视野和思路上下更大功夫，让发展成果更多惠及全体人民。这样的要求，放在哪里都不过时。填入画横线处最恰当的是：","options":["延伸","扩大","开拓","拓宽"],"answer":3,"explanation":"「拓宽」与「渠道、门路、视野」搭配；「开拓」指开辟新领域；「扩大」多与「规模、范围」搭配；「延伸」侧重长度延长。故选D。","__sub":"选词填空"},{"id":"yy-16099","module":"yanyu","diff":3,"exam":"省考","prompt":"观察身边的事不难发现，成败的分野常常藏在细节里。新征程上，要继续______生态保护红线，以实干实绩回应人民期盼。说到底，拼的是态度，比的是功夫。填入画横线处最恰当的是：","options":["把牢","守住","守牢","防住"],"answer":2,"explanation":"「守牢」与「底线」搭配，强调牢牢守住；「守住」程度稍弱；「把牢」多与「关口」搭配；「防住」为口语。故选C。","__sub":"选词填空"},{"id":"yy-16102","module":"yanyu","diff":1,"exam":"事业编","prompt":"现实中，方法与态度不同，结果往往截然不同。要坚持问题导向，______资源配置，切实解决群众急难愁盼问题。看似寻常，实则是长期积累的结果。填入画横线处最恰当的是：","options":["调整","优化","改进","改善"],"answer":1,"explanation":"「优化」指加以改变使其优良，与「环境、结构」搭配规范；「改善」多与「条件、生活」搭配；「改进」多与「方法、工作」搭配；「调整」不含变优之义。故选B。","__sub":"选词填空"},{"id":"yy-16106","module":"yanyu","diff":2,"exam":"医疗编","prompt":"任何工作要见成效，都离不开科学的方法和踏实的作风。新征程上，要继续______安全底线，以实干实绩回应人民期盼。唯有如此，才能把好事办好、实事办实。填入画横线处最恰当的是：","options":["筑牢","构建","筑造","夯实"],"answer":0,"explanation":"「筑牢」与「防线」为固定搭配，强调使牢固；「筑造」指建造实体；「构建」侧重搭建体系；「夯实」多与「基础」搭配。故选A。","__sub":"选词填空"},{"id":"yy-16107","module":"yanyu","diff":2,"exam":"国考","prompt":"干事创业，思路和坚持缺一不可。回顾这些年走过的路，______社会保障体系始终是我们攻坚克难的重要法宝。其中的道理值得每个人细细体会。填入画横线处最恰当的是：","options":["构建","完善","建立","健全"],"answer":3,"explanation":"「健全」强调使完备无缺，与「体系」搭配规范；「建立」指从无到有，「完善」指补足短板，「构建」侧重搭建框架。故选D。","__sub":"选词填空"},{"id":"yy-16108","module":"yanyu","diff":2,"exam":"教师编","prompt":"很多事看起来简单，真要做扎实并不容易。面对新形势新任务，必须______发展与安全，牢牢把握发展主动权。道理虽朴素，真正做到并不容易。填入画横线处最恰当的是：","options":["统率","兼顾","协调","统筹"],"answer":3,"explanation":"「统筹」指全面筹划、统一安排，与「推进」搭配且强调全局性；「统率」指率领；「兼顾」只强调同时照顾；「协调」侧重配合关系。故选D。","__sub":"选词填空"},{"id":"yy-16112","module":"yanyu","diff":1,"exam":"省考","prompt":"各级政府要持续______新发展阶段的新特点，不断增强群众的获得感、幸福感、安全感。填入画横线处最恰当的是：","options":["把持","把玩","把守","把握"],"answer":3,"explanation":"「把握」与抽象事物（特点、规律、机遇）搭配；「把守」指守卫关口，「把持」含贬义指独揽，「把玩」指赏玩物品。故选D。","__sub":"选词填空"},{"id":"yy-16113","module":"yanyu","diff":1,"exam":"国考","prompt":"一个朴素的道理反复被验证：方向对了，努力才不会白费。新征程上，要继续______就业促进机制，以实干实绩回应人民期盼。这也正是成事的关键所在。填入画横线处最恰当的是：","options":["搭建","构建","完善","健全"],"answer":3,"explanation":"「健全」强调使完备无缺；「完善」指补足短板；「构建」「搭建」侧重从无到有搭建。故选D。","__sub":"选词填空"},{"id":"yy-16114","module":"yanyu","diff":2,"exam":"教师编","prompt":"现实中，方法与态度不同，结果往往截然不同。面对新形势新任务，必须______城市功能品质，牢牢把握发展主动权。看似寻常，实则是长期积累的结果。填入画横线处最恰当的是：","options":["提高","提升","增强","拔高"],"answer":1,"explanation":"「提升」与「效能、水平」搭配规范；「提高」语义相近但「提升」更书面；「增强」多与「能力、意识」搭配；「拔高」含贬义。故选B。","__sub":"选词填空"},{"id":"yy-16115","module":"yanyu","diff":2,"exam":"国考","prompt":"很多事看起来简单，真要做扎实并不容易。回顾这些年走过的路，______时代脉搏始终是我们攻坚克难的重要法宝。道理虽朴素，真正做到并不容易。填入画横线处最恰当的是：","options":["把玩","把守","把持","把握"],"answer":3,"explanation":"「把握」与抽象事物（特点、规律、机遇）搭配；「把守」指守卫关口，「把持」含贬义指独揽，「把玩」指赏玩物品。故选D。","__sub":"选词填空"},{"id":"yy-16116","module":"yanyu","diff":2,"exam":"省考","prompt":"很多事看起来简单，真要做扎实并不容易。越是任务艰巨，越要______责任担当，确保方向不偏、力度不减。道理虽朴素，真正做到并不容易。填入画横线处最恰当的是：","options":["深化","强化","增强","加强"],"answer":1,"explanation":"「强化」与「意识、思维」搭配，强调使之更牢固；「增强」语义相近但搭配习惯不同；「加强」为通用动词；「深化」指向深处发展。故选B。","__sub":"选词填空"},{"id":"yy-16117","module":"yanyu","diff":2,"exam":"国考","prompt":"干事创业，思路和坚持缺一不可。各级政府要持续______消费潜力，不断增强群众的获得感、幸福感、安全感。其中的道理值得每个人细细体会。填入画横线处最恰当的是：","options":["调动","点燃","激发","引发"],"answer":2,"explanation":"「激发」与「活力、热情、潜能」为固定搭配；「引发」多与「关注、争议」搭配；「点燃」为比喻用法；「调动」多与「积极性」搭配。故选C。","__sub":"选词填空"},{"id":"yy-16120","module":"yanyu","diff":3,"exam":"省考","prompt":"现实中，方法与态度不同，结果往往截然不同。要坚持问题导向，______覆盖范围，切实解决群众急难愁盼问题。看似寻常，实则是长期积累的结果。填入画横线处最恰当的是：","options":["开拓","扩大","延伸","拓宽"],"answer":3,"explanation":"「拓宽」与「渠道、门路、视野」搭配；「开拓」指开辟新领域；「扩大」多与「规模、范围」搭配；「延伸」侧重长度延长。故选D。","__sub":"选词填空"},{"id":"yy-16121","module":"yanyu","diff":1,"exam":"国考","prompt":"无论时代如何变化，把事情做实做细始终是成事的基础。各地区各部门要拿出真招实招，______各方合力，确保各项部署落地生根。这背后考验的正是把握分寸的智慧。填入画横线处最恰当的是：","options":["集中","聚集","凝聚","汇聚"],"answer":2,"explanation":"「凝聚」多与「共识、人心、力量」搭配，强调由分散到统一；「聚集」侧重物理集合；「集中」侧重把分散的集中起来。故选C。","__sub":"选词填空"},{"id":"yy-16122","module":"yanyu","diff":1,"exam":"省考","prompt":"现实中，方法与态度不同，结果往往截然不同。实践证明，______城市功能品质是推动高质量发展的关键一招。看似寻常，实则是长期积累的结果。填入画横线处最恰当的是：","options":["提升","增强","提高","拔高"],"answer":0,"explanation":"「提升」与「效能、水平」搭配规范；「提高」语义相近但「提升」更书面；「增强」多与「能力、意识」搭配；「拔高」含贬义。故选A。","__sub":"选词填空"},{"id":"yy-16123","module":"yanyu","diff":1,"exam":"事业编","prompt":"任何工作要见成效，都离不开科学的方法和踏实的作风。只有消费潜力真正______到基层，才能让政策在「最后一公里」落地见效。唯有如此，才能把好事办好、实事办实。填入画横线处最恰当的是：","options":["爆发","发挥","散发","释放"],"answer":3,"explanation":"「释放」与「潜力、红利、活力」搭配；「散发」指分散发出；「发挥」与「作用」搭配；「爆发」指突然发作。故选D。","__sub":"选词填空"},{"id":"yy-16124","module":"yanyu","diff":2,"exam":"国考","prompt":"事物的发展自有其规律，顺应它才能事半功倍。新征程上，要继续______创新创造潜能，以实干实绩回应人民期盼。这样的要求，放在哪里都不过时。填入画横线处最恰当的是：","options":["激发","调动","引发","点燃"],"answer":0,"explanation":"「激发」与「活力、热情、潜能」为固定搭配；「引发」多与「关注、争议」搭配；「点燃」为比喻用法；「调动」多与「积极性」搭配。故选A。","__sub":"选词填空"},{"id":"yy-16125","module":"yanyu","diff":2,"exam":"省考","prompt":"事物的发展自有其规律，顺应它才能事半功倍。面对新形势新任务，必须______覆盖范围，牢牢把握发展主动权。这样的要求，放在哪里都不过时。填入画横线处最恰当的是：","options":["延伸","扩大","拓宽","开拓"],"answer":2,"explanation":"「拓宽」与「渠道、门路、视野」搭配；「开拓」指开辟新领域；「扩大」多与「规模、范围」搭配；「延伸」侧重长度延长。故选C。","__sub":"选词填空"},{"id":"yy-16127","module":"yanyu","diff":2,"exam":"事业编","prompt":"一个朴素的道理反复被验证：方向对了，努力才不会白费。实践证明，______意志是推动高质量发展的关键一招。这也正是成事的关键所在。填入画横线处最恰当的是：","options":["砥砺","锻炼","磨砺","锤炼"],"answer":0,"explanation":"「砥砺」本义为磨刀石，引申为磨炼，与「意志」搭配且语体庄重；「磨砺」与之近义但「砥砺」更常用于「砥砺前行、砥砺意志」。故选A。","__sub":"选词填空"},{"id":"yy-16128","module":"yanyu","diff":2,"exam":"国考","prompt":"一个朴素的道理反复被验证：方向对了，努力才不会白费。新征程上，要继续______区域协调发展的新格局，以实干实绩回应人民期盼。这也正是成事的关键所在。填入画横线处最恰当的是：","options":["擘画","规划","勾画","描绘"],"answer":0,"explanation":"「擘画」指筹划布置，多用于宏观蓝图，书面色彩浓；「描绘」「勾画」偏具体画面；「规划」语体色彩不足。故选A。","__sub":"选词填空"},{"id":"yy-16133","module":"yanyu","diff":1,"exam":"国考","prompt":"无论时代如何变化，把事情做实做细始终是成事的基础。下一步，将______社会保障网络，推动各项工作再上新台阶。这背后考验的正是把握分寸的智慧。填入画横线处最恰当的是：","options":["搭建","完善","构建","健全"],"answer":3,"explanation":"「健全」强调使完备无缺；「完善」指补足短板；「构建」「搭建」侧重从无到有搭建。故选D。","__sub":"选词填空"},{"id":"yy-16134","module":"yanyu","diff":2,"exam":"国考","prompt":"任何工作要见成效，都离不开科学的方法和踏实的作风。各级政府要持续______民意反映渠道，不断增强群众的获得感、幸福感、安全感。唯有如此，才能把好事办好、实事办实。填入画横线处最恰当的是：","options":["开拓","拓宽","延伸","扩大"],"answer":1,"explanation":"「拓宽」与「渠道、门路、视野」搭配；「开拓」指开辟新领域；「扩大」多与「规模、范围」搭配；「延伸」侧重长度延长。故选B。","__sub":"选词填空"},{"id":"yy-16135","module":"yanyu","diff":2,"exam":"省考","prompt":"一个朴素的道理反复被验证：方向对了，努力才不会白费。各级政府要持续______群众需求，不断增强群众的获得感、幸福感、安全感。这也正是成事的关键所在。填入画横线处最恰当的是：","options":["把握","把守","把持","把玩"],"answer":0,"explanation":"「把握」与抽象事物（特点、规律、机遇）搭配；「把守」指守卫关口，「把持」含贬义指独揽，「把玩」指赏玩物品。故选A。","__sub":"选词填空"},{"id":"yy-16136","module":"yanyu","diff":2,"exam":"国考","prompt":"一个朴素的道理反复被验证：方向对了，努力才不会白费。实践证明，______属地管理责任是推动高质量发展的关键一招。这也正是成事的关键所在。填入画横线处最恰当的是：","options":["强化","压紧","落实","压实"],"answer":3,"explanation":"「压实」与「责任」搭配，强调责任层层落实到位；「落实」为通用动词；「压紧」常作「压紧压实」；「强化」不如「压实」精准体现层级传导。故选D。","__sub":"选词填空"},{"id":"yy-16137","module":"yanyu","diff":2,"exam":"国考","prompt":"事物的发展自有其规律，顺应它才能事半功倍。实践证明，______区域协作机制是推动高质量发展的关键一招。这样的要求，放在哪里都不过时。填入画横线处最恰当的是：","options":["深入","深化","加强","推进"],"answer":1,"explanation":"「深化」指向更深阶段发展，与「改革」为固定搭配；「深入」多作形容词或「深入调查」；「加强」「推进」语义宽泛。故选B。","__sub":"选词填空"},{"id":"yy-16138","module":"yanyu","diff":2,"exam":"国考","prompt":"很多事看起来简单，真要做扎实并不容易。回顾这些年走过的路，______矛盾调解体系始终是我们攻坚克难的重要法宝。道理虽朴素，真正做到并不容易。填入画横线处最恰当的是：","options":["健全","搭建","完善","构建"],"answer":0,"explanation":"「健全」强调使完备无缺；「完善」指补足短板；「构建」「搭建」侧重从无到有搭建。故选A。","__sub":"选词填空"},{"id":"yy-16139","module":"yanyu","diff":3,"exam":"事业编","prompt":"现实中，方法与态度不同，结果往往截然不同。面对新形势新任务，必须______民生短板，牢牢把握发展主动权。看似寻常，实则是长期积累的结果。填入画横线处最恰当的是：","options":["填补","补足","补齐","弥补"],"answer":2,"explanation":"「补齐」与「短板」为固定搭配，强调使达到应有水平；「补足」多与「差额」搭配；「填补」多与「空白」搭配；「弥补」多与「损失」搭配。故选C。","__sub":"选词填空"},{"id":"yy-16141","module":"yanyu","diff":1,"exam":"国考","prompt":"只有农村物流最后一公里真正______到基层，才能让政策在「最后一公里」落地见效。填入画横线处最恰当的是：","options":["开辟","畅通","打通","贯通"],"answer":1,"explanation":"「畅通」强调使通畅无阻，与「渠道、通道」搭配；「打通」侧重突破障碍；「贯通」指连接相通；「开辟」指新开路径。故选B。","__sub":"选词填空"},{"id":"yy-16143","module":"yanyu","diff":1,"exam":"国考","prompt":"无论时代如何变化，把事情做实做细始终是成事的基础。各级政府要持续______文明乡风，不断增强群众的获得感、幸福感、安全感。这背后考验的正是把握分寸的智慧。填入画横线处最恰当的是：","options":["养护","营造","培养","涵养"],"answer":3,"explanation":"「涵养」指蓄积并养护，与「生态、水源」搭配；「培养」对象为人或能力；「营造」多与「氛围、环境」搭配；「养护」不含培育之义。故选D。","__sub":"选词填空"},{"id":"yy-16144","module":"yanyu","diff":2,"exam":"医疗编","prompt":"很多事看起来简单，真要做扎实并不容易。当前正值关键时期，______乡村发展内生动力刻不容缓，必须抓紧抓实抓出成效。道理虽朴素，真正做到并不容易。填入画横线处最恰当的是：","options":["激活","驱动","启动","唤醒"],"answer":0,"explanation":"「激活」指刺激使之活跃，与「动力、要素」搭配；「唤醒」指使之觉醒；「启动」指开始进行；「驱动」指推动运转。故选A。","__sub":"选词填空"},{"id":"yy-16145","module":"yanyu","diff":2,"exam":"国考","prompt":"一个朴素的道理反复被验证：方向对了，努力才不会白费。当前正值关键时期，______就业促进机制刻不容缓，必须抓紧抓实抓出成效。这也正是成事的关键所在。填入画横线处最恰当的是：","options":["构建","健全","完善","搭建"],"answer":1,"explanation":"「健全」强调使完备无缺；「完善」指补足短板；「构建」「搭建」侧重从无到有搭建。故选B。","__sub":"选词填空"},{"id":"yy-16146","module":"yanyu","diff":2,"exam":"省考","prompt":"事物的发展自有其规律，顺应它才能事半功倍。要在______初心上下更大功夫，让发展成果更多惠及全体人民。这样的要求，放在哪里都不过时。填入画横线处最恰当的是：","options":["锤炼","锻炼","磨砺","砥砺"],"answer":3,"explanation":"「砥砺」本义为磨刀石，引申为磨炼，与「意志」搭配且语体庄重；「磨砺」与之近义但「砥砺」更常用于「砥砺前行、砥砺意志」。故选D。","__sub":"选词填空"},{"id":"yy-16147","module":"yanyu","diff":2,"exam":"教师编","prompt":"很多事看起来简单，真要做扎实并不容易。只有生态环保责任真正______到基层，才能让政策在「最后一公里」落地见效。道理虽朴素，真正做到并不容易。填入画横线处最恰当的是：","options":["强化","落实","压紧","压实"],"answer":3,"explanation":"「压实」与「责任」搭配，强调责任层层落实到位；「落实」为通用动词；「压紧」常作「压紧压实」；「强化」不如「压实」精准体现层级传导。故选D。","__sub":"选词填空"},{"id":"yy-16148","module":"yanyu","diff":2,"exam":"省考","prompt":"干事创业，思路和坚持缺一不可。要在______公共服务体系上下更大功夫，让发展成果更多惠及全体人民。其中的道理值得每个人细细体会。填入画横线处最恰当的是：","options":["建立","健全","构建","完善"],"answer":1,"explanation":"「健全」强调使完备无缺，与「体系」搭配规范；「建立」指从无到有，「完善」指补足短板，「构建」侧重搭建框架。故选B。","__sub":"选词填空"},{"id":"yy-16155","module":"yanyu","diff":2,"exam":"省考","prompt":"一个朴素的道理反复被验证：方向对了，努力才不会白费。回顾这些年走过的路，______放管服改革始终是我们攻坚克难的重要法宝。这也正是成事的关键所在。填入画横线处最恰当的是：","options":["推进","加强","深入","深化"],"answer":3,"explanation":"「深化」指向更深阶段发展，与「改革」为固定搭配；「深入」多作形容词或「深入调查」；「加强」「推进」语义宽泛。故选D。","__sub":"选词填空"},{"id":"yy-16156","module":"yanyu","diff":2,"exam":"医疗编","prompt":"任何工作要见成效，都离不开科学的方法和踏实的作风。只有生态恶化的趋势真正______到基层，才能让政策在「最后一公里」落地见效。唯有如此，才能把好事办好、实事办实。填入画横线处最恰当的是：","options":["遏制","制止","遏止","控制"],"answer":0,"explanation":"「遏制」强调压制住势头、多与「势头/态势」搭配；「遏止」侧重使之停止，多用于具体行为；「控制」「制止」语义宽泛。故选A。","__sub":"选词填空"},{"id":"yy-16158","module":"yanyu","diff":2,"exam":"教师编","prompt":"任何工作要见成效，都离不开科学的方法和踏实的作风。实践证明，______消费新增长点是推动高质量发展的关键一招。唯有如此，才能把好事办好、实事办实。填入画横线处最恰当的是：","options":["培植","培养","培育","孕育"],"answer":2,"explanation":"「培育」与「产业、企业、市场」搭配；「培养」对象为人或能力；「培植」多用于动植物或含贬义；「孕育」强调正在形成。故选C。","__sub":"选词填空"},{"id":"yy-16162","module":"yanyu","diff":1,"exam":"省考","prompt":"任何工作要见成效，都离不开科学的方法和踏实的作风。实践证明，______城乡发展布局是推动高质量发展的关键一招。唯有如此，才能把好事办好、实事办实。填入画横线处最恰当的是：","options":["统筹","协调","统率","兼顾"],"answer":0,"explanation":"「统筹」指全面筹划、统一安排，与「推进」搭配且强调全局性；「统率」指率领；「兼顾」只强调同时照顾；「协调」侧重配合关系。故选A。","__sub":"选词填空"},{"id":"yy-16163","module":"yanyu","diff":1,"exam":"国考","prompt":"任何工作要见成效，都离不开科学的方法和踏实的作风。面对新形势新任务，必须______消费市场一池春水，牢牢把握发展主动权。唯有如此，才能把好事办好、实事办实。填入画横线处最恰当的是：","options":["唤醒","激活","启动","驱动"],"answer":1,"explanation":"「激活」指刺激使之活跃，与「动力、要素」搭配；「唤醒」指使之觉醒；「启动」指开始进行；「驱动」指推动运转。故选B。","__sub":"选词填空"},{"id":"yy-16164","module":"yanyu","diff":2,"exam":"教师编","prompt":"观察身边的事不难发现，成败的分野常常藏在细节里。各级政府要持续______视野和思路，不断增强群众的获得感、幸福感、安全感。说到底，拼的是态度，比的是功夫。填入画横线处最恰当的是：","options":["扩大","延伸","开拓","拓宽"],"answer":3,"explanation":"「拓宽」与「渠道、门路、视野」搭配；「开拓」指开辟新领域；「扩大」多与「规模、范围」搭配；「延伸」侧重长度延长。故选D。","__sub":"选词填空"},{"id":"yy-16166","module":"yanyu","diff":2,"exam":"省考","prompt":"无论时代如何变化，把事情做实做细始终是成事的基础。回顾这些年走过的路，______政企沟通机制始终是我们攻坚克难的重要法宝。这背后考验的正是把握分寸的智慧。填入画横线处最恰当的是：","options":["疏通","畅通","打通","开拓"],"answer":1,"explanation":"「畅通」强调使通畅无阻，与「渠道」为固定搭配；「打通」侧重突破障碍；「疏通」多用于管道或疏导矛盾；「开拓」指开辟新领域。故选B。","__sub":"选词填空"},{"id":"yy-16167","module":"yanyu","diff":2,"exam":"省考","prompt":"任何工作要见成效，都离不开科学的方法和踏实的作风。要在______安全事故多发的势头上下更大功夫，让发展成果更多惠及全体人民。唯有如此，才能把好事办好、实事办实。填入画横线处最恰当的是：","options":["制止","遏止","控制","遏制"],"answer":3,"explanation":"「遏制」强调压制住势头、多与「势头/态势」搭配；「遏止」侧重使之停止，多用于具体行为；「控制」「制止」语义宽泛。故选D。","__sub":"选词填空"},{"id":"yy-16168","module":"yanyu","diff":2,"exam":"医疗编","prompt":"任何工作要见成效，都离不开科学的方法和踏实的作风。下一步，将______内生动力，推动各项工作再上新台阶。唯有如此，才能把好事办好、实事办实。填入画横线处最恰当的是：","options":["引发","调动","激发","点燃"],"answer":2,"explanation":"「激发」与「活力、热情、潜能」为固定搭配；「引发」多与「关注、争议」搭配；「点燃」为比喻用法；「调动」多与「积极性」搭配。故选C。","__sub":"选词填空"},{"id":"yy-16169","module":"yanyu","diff":3,"exam":"教师编","prompt":"观察身边的事不难发现，成败的分野常常藏在细节里。当前正值关键时期，______廉洁底线刻不容缓，必须抓紧抓实抓出成效。说到底，拼的是态度，比的是功夫。填入画横线处最恰当的是：","options":["筑造","夯实","筑牢","构建"],"answer":2,"explanation":"「筑牢」与「防线」为固定搭配，强调使牢固；「筑造」指建造实体；「构建」侧重搭建体系；「夯实」多与「基础」搭配。故选C。","__sub":"选词填空"},{"id":"yy-16170","module":"yanyu","diff":3,"exam":"省考","prompt":"观察身边的事不难发现，成败的分野常常藏在细节里。面对新形势新任务，必须______基层基础，牢牢把握发展主动权。说到底，拼的是态度，比的是功夫。填入画横线处最恰当的是：","options":["夯实","筑牢","打牢","巩固"],"answer":0,"explanation":"「夯实」本义为砸实地基，引申为使稳固，与「基础、根基」搭配；「筑牢」与「防线」搭配；「打牢」语体稍口语；「巩固」侧重使已有的更牢固。故选A。","__sub":"选词填空"},{"id":"yy-16171","module":"yanyu","diff":1,"exam":"医疗编","prompt":"干事创业，思路和坚持缺一不可。要在______全年经济增长目标上下更大功夫，让发展成果更多惠及全体人民。其中的道理值得每个人细细体会。填入画横线处最恰当的是：","options":["瞄准","锚定","锁定","盯住"],"answer":1,"explanation":"「锚定」比喻像锚一样固定住目标，多用于宏观战略语境；「锁定」「瞄准」「盯住」语体偏口语，庄重色彩不足。故选B。","__sub":"选词填空"},{"id":"yy-16172","module":"yanyu","diff":1,"exam":"国考","prompt":"现实中，方法与态度不同，结果往往截然不同。实践证明，______品格是推动高质量发展的关键一招。看似寻常，实则是长期积累的结果。填入画横线处最恰当的是：","options":["锻炼","磨砺","锤炼","砥砺"],"answer":3,"explanation":"「砥砺」本义为磨刀石，引申为磨炼，与「意志」搭配且语体庄重；「磨砺」与之近义但「砥砺」更常用于「砥砺前行、砥砺意志」。故选D。","__sub":"选词填空"},{"id":"yy-16174","module":"yanyu","diff":2,"exam":"省考","prompt":"很多事看起来简单，真要做扎实并不容易。实践证明，______基层基础是推动高质量发展的关键一招。道理虽朴素，真正做到并不容易。填入画横线处最恰当的是：","options":["夯实","巩固","筑牢","打牢"],"answer":0,"explanation":"「夯实」本义为砸实地基，引申为使稳固，与「基础、根基」搭配；「筑牢」与「防线」搭配；「打牢」语体稍口语；「巩固」侧重使已有的更牢固。故选A。","__sub":"选词填空"},{"id":"yy-16175","module":"yanyu","diff":2,"exam":"医疗编","prompt":"观察身边的事不难发现，成败的分野常常藏在细节里。越是任务艰巨，越要______斗争精神，确保方向不偏、力度不减。说到底，拼的是态度，比的是功夫。填入画横线处最恰当的是：","options":["锻炼","磨砺","砥砺","锤炼"],"answer":2,"explanation":"「砥砺」本义为磨刀石，引申为磨炼，与「意志」搭配且语体庄重；「磨砺」与之近义但「砥砺」更常用于「砥砺前行、砥砺意志」。故选C。","__sub":"选词填空"},{"id":"yy-16176","module":"yanyu","diff":2,"exam":"国考","prompt":"无论时代如何变化，把事情做实做细始终是成事的基础。回顾这些年走过的路，______属地管理责任始终是我们攻坚克难的重要法宝。这背后考验的正是把握分寸的智慧。填入画横线处最恰当的是：","options":["强化","落实","压实","压紧"],"answer":2,"explanation":"「压实」与「责任」搭配，强调责任层层落实到位；「落实」为通用动词；「压紧」常作「压紧压实」；「强化」不如「压实」精准体现层级传导。故选C。","__sub":"选词填空"},{"id":"yy-16177","module":"yanyu","diff":2,"exam":"国考","prompt":"现实中，方法与态度不同，结果往往截然不同。越是任务艰巨，越要______就业促进机制，确保方向不偏、力度不减。看似寻常，实则是长期积累的结果。填入画横线处最恰当的是：","options":["健全","构建","搭建","完善"],"answer":0,"explanation":"「健全」强调使完备无缺；「完善」指补足短板；「构建」「搭建」侧重从无到有搭建。故选A。","__sub":"选词填空"},{"id":"yy-16179","module":"yanyu","diff":3,"exam":"事业编","prompt":"任何工作要见成效，都离不开科学的方法和踏实的作风。新征程上，要继续______属地管理责任，以实干实绩回应人民期盼。唯有如此，才能把好事办好、实事办实。填入画横线处最恰当的是：","options":["强化","落实","压实","压紧"],"answer":2,"explanation":"「压实」与「责任」搭配，强调责任层层落实到位；「落实」为通用动词；「压紧」常作「压紧压实」；「强化」不如「压实」精准体现层级传导。故选C。","__sub":"选词填空"},{"id":"yy-16180","module":"yanyu","diff":3,"exam":"国考","prompt":"事物的发展自有其规律，顺应它才能事半功倍。要在______制度漏洞上下更大功夫，让发展成果更多惠及全体人民。这样的要求，放在哪里都不过时。填入画横线处最恰当的是：","options":["弥补","补足","填补","补齐"],"answer":3,"explanation":"「补齐」与「短板」为固定搭配，强调使达到应有水平；「补足」多与「差额」搭配；「填补」多与「空白」搭配；「弥补」多与「损失」搭配。故选D。","__sub":"选词填空"},{"id":"yy-16181","module":"yanyu","diff":1,"exam":"国考","prompt":"现实中，方法与态度不同，结果往往截然不同。要坚持问题导向，______时代脉搏，切实解决群众急难愁盼问题。看似寻常，实则是长期积累的结果。填入画横线处最恰当的是：","options":["把玩","把握","把持","把守"],"answer":1,"explanation":"「把握」与抽象事物（特点、规律、机遇）搭配；「把守」指守卫关口，「把持」含贬义指独揽，「把玩」指赏玩物品。故选B。","__sub":"选词填空"},{"id":"yy-16182","module":"yanyu","diff":1,"exam":"事业编","prompt":"很多事看起来简单，真要做扎实并不容易。只有监管责任真正______到基层，才能让政策在「最后一公里」落地见效。道理虽朴素，真正做到并不容易。填入画横线处最恰当的是：","options":["压实","强化","落实","压紧"],"answer":0,"explanation":"「压实」与「责任」搭配，强调责任层层落实到位；「落实」为通用动词；「压紧」常作「压紧压实」；「强化」不如「压实」精准体现层级传导。故选A。","__sub":"选词填空"},{"id":"yy-16183","module":"yanyu","diff":1,"exam":"事业编","prompt":"很多事看起来简单，真要做扎实并不容易。下一步，将______发展与安全，推动各项工作再上新台阶。道理虽朴素，真正做到并不容易。填入画横线处最恰当的是：","options":["协调","统筹","统率","兼顾"],"answer":1,"explanation":"「统筹」指全面筹划、统一安排，与「推进」搭配且强调全局性；「统率」指率领；「兼顾」只强调同时照顾；「协调」侧重配合关系。故选B。","__sub":"选词填空"},{"id":"yy-16184","module":"yanyu","diff":2,"exam":"省考","prompt":"任何工作要见成效，都离不开科学的方法和踏实的作风。新征程上，要继续______生态环保责任，以实干实绩回应人民期盼。唯有如此，才能把好事办好、实事办实。填入画横线处最恰当的是：","options":["落实","强化","压紧","压实"],"answer":3,"explanation":"「压实」与「责任」搭配，强调责任层层落实到位；「落实」为通用动词；「压紧」常作「压紧压实」；「强化」不如「压实」精准体现层级传导。故选D。","__sub":"选词填空"},{"id":"yy-16185","module":"yanyu","diff":2,"exam":"国考","prompt":"观察身边的事不难发现，成败的分野常常藏在细节里。实践证明，______文明乡风是推动高质量发展的关键一招。说到底，拼的是态度，比的是功夫。填入画横线处最恰当的是：","options":["营造","培养","养护","涵养"],"answer":3,"explanation":"「涵养」指蓄积并养护，与「生态、水源」搭配；「培养」对象为人或能力；「营造」多与「氛围、环境」搭配；「养护」不含培育之义。故选D。","__sub":"选词填空"},{"id":"yy-16190","module":"yanyu","diff":3,"exam":"国考","prompt":"现实中，方法与态度不同，结果往往截然不同。各级政府要持续______智慧和力量，不断增强群众的获得感、幸福感、安全感。看似寻常，实则是长期积累的结果。填入画横线处最恰当的是：","options":["汇聚","集中","聚集","凝聚"],"answer":3,"explanation":"「凝聚」多与「共识、人心、力量」搭配，强调由分散到统一；「聚集」侧重物理集合；「集中」侧重把分散的集中起来。故选D。","__sub":"选词填空"},{"id":"yy-16192","module":"yanyu","diff":1,"exam":"教师编","prompt":"很多事看起来简单，真要做扎实并不容易。要在______意志上下更大功夫，让发展成果更多惠及全体人民。道理虽朴素，真正做到并不容易。填入画横线处最恰当的是：","options":["锻炼","砥砺","磨砺","锤炼"],"answer":1,"explanation":"「砥砺」本义为磨刀石，引申为磨炼，与「意志」搭配且语体庄重；「磨砺」与之近义但「砥砺」更常用于「砥砺前行、砥砺意志」。故选B。","__sub":"选词填空"},{"id":"yy-16193","module":"yanyu","diff":1,"exam":"教师编","prompt":"无论时代如何变化，把事情做实做细始终是成事的基础。面对新形势新任务，必须______全年经济增长目标，牢牢把握发展主动权。这背后考验的正是把握分寸的智慧。填入画横线处最恰当的是：","options":["盯住","锁定","瞄准","锚定"],"answer":3,"explanation":"「锚定」比喻像锚一样固定住目标，多用于宏观战略语境；「锁定」「瞄准」「盯住」语体偏口语，庄重色彩不足。故选D。","__sub":"选词填空"},{"id":"yy-16194","module":"yanyu","diff":2,"exam":"事业编","prompt":"事物的发展自有其规律，顺应它才能事半功倍。要坚持问题导向，______食品安全监管，切实解决群众急难愁盼问题。这样的要求，放在哪里都不过时。填入画横线处最恰当的是：","options":["增强","深化","加强","强化"],"answer":3,"explanation":"「强化」与「意识、思维」搭配，强调使之更牢固；「增强」语义相近但搭配习惯不同；「加强」为通用动词；「深化」指向深处发展。故选D。","__sub":"选词填空"},{"id":"yy-16195","module":"yanyu","diff":2,"exam":"国考","prompt":"任何工作要见成效，都离不开科学的方法和踏实的作风。当前正值关键时期，______城乡发展布局刻不容缓，必须抓紧抓实抓出成效。唯有如此，才能把好事办好、实事办实。填入画横线处最恰当的是：","options":["兼顾","协调","统筹","统率"],"answer":2,"explanation":"「统筹」指全面筹划、统一安排，与「推进」搭配且强调全局性；「统率」指率领；「兼顾」只强调同时照顾；「协调」侧重配合关系。故选C。","__sub":"选词填空"},{"id":"yy-16198","module":"yanyu","diff":2,"exam":"事业编","prompt":"观察身边的事不难发现，成败的分野常常藏在细节里。只有爱国情怀真正______到基层，才能让政策在「最后一公里」落地见效。说到底，拼的是态度，比的是功夫。填入画横线处最恰当的是：","options":["筑牢","培植","厚植","加深"],"answer":2,"explanation":"「厚植」指深厚培育，与「优势、底色、根基」搭配；「培植」多用于培育动植物或扶植势力；「加深」与「底色」搭配不当。故选C。","__sub":"选词填空"},{"id":"yy-16199","module":"yanyu","diff":3,"exam":"教师编","prompt":"各地区各部门要拿出真招实招，______制造业高质量发展，确保各项部署落地生根。填入画横线处最恰当的是：","options":["加持","赋能","助力","赋权"],"answer":1,"explanation":"「赋能」指赋予能力，是数字经济语境的规范表述；「赋权」指赋予权力；「加持」为口语化外来词；「助力」语义宽泛。故选B。","__sub":"选词填空"},{"id":"yy-16200","module":"yanyu","diff":3,"exam":"国考","prompt":"事物的发展自有其规律，顺应它才能事半功倍。越是任务艰巨，越要______沉睡的资源要素，确保方向不偏、力度不减。这样的要求，放在哪里都不过时。填入画横线处最恰当的是：","options":["驱动","激活","唤醒","启动"],"answer":1,"explanation":"「激活」指刺激使之活跃，与「动力、要素」搭配；「唤醒」指使之觉醒；「启动」指开始进行；「驱动」指推动运转。故选B。","__sub":"选词填空"},{"id":"yy-16201","module":"yanyu","diff":1,"exam":"国考","prompt":"任何工作要见成效，都离不开科学的方法和踏实的作风。下一步，将______食品安全监管，推动各项工作再上新台阶。唯有如此，才能把好事办好、实事办实。填入画横线处最恰当的是：","options":["深化","增强","强化","加强"],"answer":2,"explanation":"「强化」与「意识、思维」搭配，强调使之更牢固；「增强」语义相近但搭配习惯不同；「加强」为通用动词；「深化」指向深处发展。故选C。","__sub":"选词填空"},{"id":"yy-16203","module":"yanyu","diff":1,"exam":"事业编","prompt":"观察身边的事不难发现，成败的分野常常藏在细节里。要坚持问题导向，______数字化底座，切实解决群众急难愁盼问题。说到底，拼的是态度，比的是功夫。填入画横线处最恰当的是：","options":["筑牢","夯实","打牢","巩固"],"answer":1,"explanation":"「夯实」本义为砸实地基，引申为使稳固，与「基础、根基」搭配；「筑牢」与「防线」搭配；「打牢」语体稍口语；「巩固」侧重使已有的更牢固。故选B。","__sub":"选词填空"},{"id":"yy-16204","module":"yanyu","diff":2,"exam":"国考","prompt":"很多事看起来简单，真要做扎实并不容易。下一步，将______消费市场一池春水，推动各项工作再上新台阶。道理虽朴素，真正做到并不容易。填入画横线处最恰当的是：","options":["驱动","启动","激活","唤醒"],"answer":2,"explanation":"「激活」指刺激使之活跃，与「动力、要素」搭配；「唤醒」指使之觉醒；「启动」指开始进行；「驱动」指推动运转。故选C。","__sub":"选词填空"},{"id":"yy-16205","module":"yanyu","diff":2,"exam":"国考","prompt":"无论时代如何变化，把事情做实做细始终是成事的基础。各地区各部门要拿出真招实招，______社会保障网络，确保各项部署落地生根。这背后考验的正是把握分寸的智慧。填入画横线处最恰当的是：","options":["搭建","构建","健全","完善"],"answer":2,"explanation":"「健全」强调使完备无缺；「完善」指补足短板；「构建」「搭建」侧重从无到有搭建。故选C。","__sub":"选词填空"},{"id":"yy-16206","module":"yanyu","diff":2,"exam":"医疗编","prompt":"事物的发展自有其规律，顺应它才能事半功倍。下一步，将______覆盖范围，推动各项工作再上新台阶。这样的要求，放在哪里都不过时。填入画横线处最恰当的是：","options":["开拓","扩大","拓宽","延伸"],"answer":2,"explanation":"「拓宽」与「渠道、门路、视野」搭配；「开拓」指开辟新领域；「扩大」多与「规模、范围」搭配；「延伸」侧重长度延长。故选C。","__sub":"选词填空"},{"id":"yy-16208","module":"yanyu","diff":2,"exam":"国考","prompt":"只有供给侧结构性改革真正______到基层，才能让政策在「最后一公里」落地见效。填入画横线处最恰当的是：","options":["推进","深入","深化","加强"],"answer":2,"explanation":"「深化」指向更深阶段发展，与「改革」为固定搭配；「深入」多作形容词或「深入调查」；「加强」「推进」语义宽泛。故选C。","__sub":"选词填空"},{"id":"yy-16209","module":"yanyu","diff":3,"exam":"医疗编","prompt":"事物的发展自有其规律，顺应它才能事半功倍。只有社会保障体系真正______到基层，才能让政策在「最后一公里」落地见效。这样的要求，放在哪里都不过时。填入画横线处最恰当的是：","options":["健全","建立","构建","完善"],"answer":0,"explanation":"「健全」强调使完备无缺，与「体系」搭配规范；「建立」指从无到有，「完善」指补足短板，「构建」侧重搭建框架。故选A。","__sub":"选词填空"},{"id":"yy-16210","module":"yanyu","diff":3,"exam":"国考","prompt":"无论时代如何变化，把事情做实做细始终是成事的基础。下一步，将______基层治理，推动各项工作再上新台阶。这背后考验的正是把握分寸的智慧。填入画横线处最恰当的是：","options":["加持","赋能","助力","赋权"],"answer":1,"explanation":"「赋能」指赋予能力，是数字经济语境的规范表述；「赋权」指赋予权力；「加持」为口语化外来词；「助力」语义宽泛。故选B。","__sub":"选词填空"},{"id":"yy-16214","module":"yanyu","diff":2,"exam":"省考","prompt":"事物的发展自有其规律，顺应它才能事半功倍。实践证明，______人才流动渠道是推动高质量发展的关键一招。这样的要求，放在哪里都不过时。填入画横线处最恰当的是：","options":["开拓","畅通","打通","疏通"],"answer":1,"explanation":"「畅通」强调使通畅无阻，与「渠道」为固定搭配；「打通」侧重突破障碍；「疏通」多用于管道或疏导矛盾；「开拓」指开辟新领域。故选B。","__sub":"选词填空"},{"id":"yy-16215","module":"yanyu","diff":2,"exam":"国考","prompt":"现实中，方法与态度不同，结果往往截然不同。要坚持问题导向，______耕地保护红线，切实解决群众急难愁盼问题。看似寻常，实则是长期积累的结果。填入画横线处最恰当的是：","options":["把牢","守住","守牢","防住"],"answer":2,"explanation":"「守牢」与「底线」搭配，强调牢牢守住；「守住」程度稍弱；「把牢」多与「关口」搭配；「防住」为口语。故选C。","__sub":"选词填空"},{"id":"yy-16217","module":"yanyu","diff":2,"exam":"事业编","prompt":"事物的发展自有其规律，顺应它才能事半功倍。各级政府要持续______监督机制，不断增强群众的获得感、幸福感、安全感。这样的要求，放在哪里都不过时。填入画横线处最恰当的是：","options":["完善","构建","建立","健全"],"answer":3,"explanation":"「健全」强调使完备无缺，与「体系」搭配规范；「建立」指从无到有，「完善」指补足短板，「构建」侧重搭建框架。故选D。","__sub":"选词填空"},{"id":"yy-16218","module":"yanyu","diff":2,"exam":"省考","prompt":"事物的发展自有其规律，顺应它才能事半功倍。下一步，将______生态环保责任，推动各项工作再上新台阶。这样的要求，放在哪里都不过时。填入画横线处最恰当的是：","options":["强化","落实","压实","压紧"],"answer":2,"explanation":"「压实」与「责任」搭配，强调责任层层落实到位；「落实」为通用动词；「压紧」常作「压紧压实」；「强化」不如「压实」精准体现层级传导。故选C。","__sub":"选词填空"},{"id":"yy-16219","module":"yanyu","diff":3,"exam":"国考","prompt":"一个朴素的道理反复被验证：方向对了，努力才不会白费。新征程上，要继续______实体经济根基，以实干实绩回应人民期盼。这也正是成事的关键所在。填入画横线处最恰当的是：","options":["培植","筑牢","厚植","加深"],"answer":2,"explanation":"「厚植」指深厚培育，与「优势、底色、根基」搭配；「培植」多用于培育动植物或扶植势力；「加深」与「底色」搭配不当。故选C。","__sub":"选词填空"},{"id":"yy-16222","module":"yanyu","diff":1,"exam":"国考","prompt":"很多事看起来简单，真要做扎实并不容易。要在______科技成果转化通道上下更大功夫，让发展成果更多惠及全体人民。道理虽朴素，真正做到并不容易。填入画横线处最恰当的是：","options":["贯通","畅通","开辟","打通"],"answer":1,"explanation":"「畅通」强调使通畅无阻，与「渠道、通道」搭配；「打通」侧重突破障碍；「贯通」指连接相通；「开辟」指新开路径。故选B。","__sub":"选词填空"},{"id":"yy-16223","module":"yanyu","diff":1,"exam":"国考","prompt":"很多事看起来简单，真要做扎实并不容易。各地区各部门要拿出真招实招，______群众需求，确保各项部署落地生根。道理虽朴素，真正做到并不容易。填入画横线处最恰当的是：","options":["把持","把守","把玩","把握"],"answer":3,"explanation":"「把握」与抽象事物（特点、规律、机遇）搭配；「把守」指守卫关口，「把持」含贬义指独揽，「把玩」指赏玩物品。故选D。","__sub":"选词填空"},{"id":"yy-16225","module":"yanyu","diff":2,"exam":"省考","prompt":"无论时代如何变化，把事情做实做细始终是成事的基础。要坚持问题导向，______执法力量，切实解决群众急难愁盼问题。这背后考验的正是把握分寸的智慧。填入画横线处最恰当的是：","options":["下坠","下潜","下探","下沉"],"answer":3,"explanation":"「下沉」指治理资源向基层倾斜，是规范表述；「下潜」指潜水，「下探」多指价格或行动试探，「下坠」指物体坠落。故选D。","__sub":"选词填空"},{"id":"yy-16501","module":"yanyu","diff":1,"exam":"国考","prompt":"干事创业，思路和坚持缺一不可。新征程上，要继续______公共服务体系，以实干实绩回应人民期盼。其中的道理值得每个人细细体会。填入画横线处最恰当的是：","options":["完善","构建","健全","建立"],"answer":2,"explanation":"「健全」强调使完备无缺，与「体系」搭配规范；「建立」指从无到有，「完善」指补足短板，「构建」侧重搭建框架。故选C。","__sub":"选词填空"},{"id":"yy-16503","module":"yanyu","diff":1,"exam":"事业编","prompt":"各地区各部门要拿出真招实招，______消费市场一池春水，确保各项部署落地生根。填入画横线处最恰当的是：","options":["激活","启动","驱动","唤醒"],"answer":0,"explanation":"「激活」指刺激使之活跃，与「动力、要素」搭配；「唤醒」指使之觉醒；「启动」指开始进行；「驱动」指推动运转。故选A。","__sub":"选词填空"},{"id":"yy-16507","module":"yanyu","diff":2,"exam":"省考","prompt":"很多事看起来简单，真要做扎实并不容易。要在______人才成长环境上下更大功夫，让发展成果更多惠及全体人民。道理虽朴素，真正做到并不容易。填入画横线处最恰当的是：","options":["营造","培养","养护","涵养"],"answer":3,"explanation":"「涵养」指蓄积并养护，与「生态、水源」搭配；「培养」对象为人或能力；「营造」多与「氛围、环境」搭配；「养护」不含培育之义。故选D。","__sub":"选词填空"},{"id":"yy-16511","module":"yanyu","diff":1,"exam":"国考","prompt":"无论时代如何变化，把事情做实做细始终是成事的基础。实践证明，______腐败蔓延的态势是推动高质量发展的关键一招。这背后考验的正是把握分寸的智慧。填入画横线处最恰当的是：","options":["控制","遏止","遏制","制止"],"answer":2,"explanation":"「遏制」强调压制住势头、多与「势头/态势」搭配；「遏止」侧重使之停止，多用于具体行为；「控制」「制止」语义宽泛。故选C。","__sub":"选词填空"},{"id":"yy-16512","module":"yanyu","diff":1,"exam":"国考","prompt":"很多事看起来简单，真要做扎实并不容易。回顾这些年走过的路，______推进重点领域改革始终是我们攻坚克难的重要法宝。道理虽朴素，真正做到并不容易。填入画横线处最恰当的是：","options":["协调","统率","统筹","兼顾"],"answer":2,"explanation":"「统筹」指全面筹划、统一安排，与「推进」搭配且强调全局性；「统率」指率领；「兼顾」只强调同时照顾；「协调」侧重配合关系。故选C。","__sub":"选词填空"},{"id":"yy-16514","module":"yanyu","diff":2,"exam":"省考","prompt":"各地区各部门要拿出真招实招，______高质量发展的生态底色，确保各项部署落地生根。填入画横线处最恰当的是：","options":["厚植","筑牢","加深","培植"],"answer":0,"explanation":"「厚植」指深厚培育，与「优势、底色、根基」搭配；「培植」多用于培育动植物或扶植势力；「加深」与「底色」搭配不当。故选A。","__sub":"选词填空"},{"id":"yy-16517","module":"yanyu","diff":2,"exam":"国考","prompt":"当前正值关键时期，______安全事故多发的势头刻不容缓，必须抓紧抓实抓出成效。填入画横线处最恰当的是：","options":["制止","遏止","控制","遏制"],"answer":3,"explanation":"「遏制」强调压制住势头、多与「势头/态势」搭配；「遏止」侧重使之停止，多用于具体行为；「控制」「制止」语义宽泛。故选D。","__sub":"选词填空"},{"id":"yy-16518","module":"yanyu","diff":2,"exam":"教师编","prompt":"干事创业，思路和坚持缺一不可。回顾这些年走过的路，______东西部协作始终是我们攻坚克难的重要法宝。其中的道理值得每个人细细体会。填入画横线处最恰当的是：","options":["深化","深入","加强","推进"],"answer":0,"explanation":"「深化」指向更深阶段发展，与「改革」为固定搭配；「深入」多作形容词或「深入调查」；「加强」「推进」语义宽泛。故选A。","__sub":"选词填空"},{"id":"yy-16520","module":"yanyu","diff":3,"exam":"事业编","prompt":"很多事看起来简单，真要做扎实并不容易。要坚持问题导向，______区域协作机制，切实解决群众急难愁盼问题。道理虽朴素，真正做到并不容易。填入画横线处最恰当的是：","options":["加强","深化","推进","深入"],"answer":1,"explanation":"「深化」指向更深阶段发展，与「改革」为固定搭配；「深入」多作形容词或「深入调查」；「加强」「推进」语义宽泛。故选B。","__sub":"选词填空"},{"id":"yy-16522","module":"yanyu","diff":1,"exam":"省考","prompt":"任何工作要见成效，都离不开科学的方法和踏实的作风。当前正值关键时期，______公共卫生体系短板刻不容缓，必须抓紧抓实抓出成效。唯有如此，才能把好事办好、实事办实。填入画横线处最恰当的是：","options":["弥补","补齐","填补","补足"],"answer":1,"explanation":"「补齐」与「短板」为固定搭配，强调使达到应有水平；「补足」多与「差额」搭配；「填补」多与「空白」搭配；「弥补」多与「损失」搭配。故选B。","__sub":"选词填空"},{"id":"yy-16527","module":"yanyu","diff":2,"exam":"国考","prompt":"很多事看起来简单，真要做扎实并不容易。新征程上，要继续______生态恶化的趋势，以实干实绩回应人民期盼。道理虽朴素，真正做到并不容易。填入画横线处最恰当的是：","options":["遏制","遏止","控制","制止"],"answer":0,"explanation":"「遏制」强调压制住势头、多与「势头/态势」搭配；「遏止」侧重使之停止，多用于具体行为；「控制」「制止」语义宽泛。故选A。","__sub":"选词填空"},{"id":"yy-16528","module":"yanyu","diff":2,"exam":"医疗编","prompt":"事物的发展自有其规律，顺应它才能事半功倍。要坚持问题导向，______中小企业发展，切实解决群众急难愁盼问题。这样的要求，放在哪里都不过时。填入画横线处最恰当的是：","options":["加持","赋权","赋能","助力"],"answer":2,"explanation":"「赋能」指赋予能力，是数字经济语境的规范表述；「赋权」指赋予权力；「加持」为口语化外来词；「助力」语义宽泛。故选C。","__sub":"选词填空"},{"id":"yy-16531","module":"yanyu","diff":1,"exam":"医疗编","prompt":"无论时代如何变化，把事情做实做细始终是成事的基础。只有腐败蔓延的态势真正______到基层，才能让政策在「最后一公里」落地见效。这背后考验的正是把握分寸的智慧。填入画横线处最恰当的是：","options":["制止","控制","遏止","遏制"],"answer":3,"explanation":"「遏制」强调压制住势头、多与「势头/态势」搭配；「遏止」侧重使之停止，多用于具体行为；「控制」「制止」语义宽泛。故选D。","__sub":"选词填空"},{"id":"yy-16533","module":"yanyu","diff":1,"exam":"教师编","prompt":"无论时代如何变化，把事情做实做细始终是成事的基础。回顾这些年走过的路，______传统产业转型升级始终是我们攻坚克难的重要法宝。这背后考验的正是把握分寸的智慧。填入画横线处最恰当的是：","options":["加持","助力","赋能","赋权"],"answer":2,"explanation":"「赋能」指赋予能力，是数字经济语境的规范表述；「赋权」指赋予权力；「加持」为口语化外来词；「助力」语义宽泛。故选C。","__sub":"选词填空"},{"id":"yy-16535","module":"yanyu","diff":2,"exam":"国考","prompt":"很多事看起来简单，真要做扎实并不容易。越是任务艰巨，越要______现代化建设全局，确保方向不偏、力度不减。道理虽朴素，真正做到并不容易。填入画横线处最恰当的是：","options":["经过","贯串","贯穿","穿过"],"answer":2,"explanation":"「贯穿」指从头到尾通贯，与「全过程」搭配规范；「穿过」「经过」仅指空间或时间经过，不含通贯始终之义。故选C。","__sub":"选词填空"},{"id":"yy-16536","module":"yanyu","diff":2,"exam":"省考","prompt":"一个朴素的道理反复被验证：方向对了，努力才不会白费。要在______农产品上行通道上下更大功夫，让发展成果更多惠及全体人民。这也正是成事的关键所在。填入画横线处最恰当的是：","options":["打通","开拓","畅通","疏通"],"answer":2,"explanation":"「畅通」强调使通畅无阻，与「渠道」为固定搭配；「打通」侧重突破障碍；「疏通」多用于管道或疏导矛盾；「开拓」指开辟新领域。故选C。","__sub":"选词填空"},{"id":"yy-16537","module":"yanyu","diff":2,"exam":"事业编","prompt":"事物的发展自有其规律，顺应它才能事半功倍。面对新形势新任务，必须______创新根基，牢牢把握发展主动权。这样的要求，放在哪里都不过时。填入画横线处最恰当的是：","options":["厚植","筑牢","加深","培植"],"answer":0,"explanation":"「厚植」指深厚培育，与「优势、底色、根基」搭配；「培植」多用于培育动植物或扶植势力；「加深」与「底色」搭配不当。故选A。","__sub":"选词填空"},{"id":"yy-16538","module":"yanyu","diff":2,"exam":"国考","prompt":"无论时代如何变化，把事情做实做细始终是成事的基础。面对新形势新任务，必须______人才成长环境，牢牢把握发展主动权。这背后考验的正是把握分寸的智慧。填入画横线处最恰当的是：","options":["营造","涵养","养护","培养"],"answer":1,"explanation":"「涵养」指蓄积并养护，与「生态、水源」搭配；「培养」对象为人或能力；「营造」多与「氛围、环境」搭配；「养护」不含培育之义。故选B。","__sub":"选词填空"},{"id":"yy-16539","module":"yanyu","diff":3,"exam":"省考","prompt":"干事创业，思路和坚持缺一不可。实践证明，______消费潜力是推动高质量发展的关键一招。看似寻常，实则是长期积累的结果。填入画横线处最恰当的是：","options":["散发","发挥","释放","爆发"],"answer":2,"explanation":"「释放」与「潜力、红利、活力」搭配；「散发」指分散发出；「发挥」与「作用」搭配；「爆发」指突然发作。故选C。","__sub":"选词填空"},{"id":"yy-16543","module":"yanyu","diff":1,"exam":"省考","prompt":"观察身边的事不难发现，成败的分野常常藏在细节里。下一步，将______中小企业发展，推动各项工作再上新台阶。说到底，拼的是态度，比的是功夫。填入画横线处最恰当的是：","options":["助力","赋权","赋能","加持"],"answer":2,"explanation":"「赋能」指赋予能力，是数字经济语境的规范表述；「赋权」指赋予权力；「加持」为口语化外来词；「助力」语义宽泛。故选C。","__sub":"选词填空"},{"id":"yy-16544","module":"yanyu","diff":2,"exam":"省考","prompt":"任何工作要见成效，都离不开科学的方法和踏实的作风。实践证明，______人才结构是推动高质量发展的关键一招。唯有如此，才能把好事办好、实事办实。填入画横线处最恰当的是：","options":["优化","改进","调整","改善"],"answer":0,"explanation":"「优化」指加以改变使其优良，与「环境、结构」搭配规范；「改善」多与「条件、生活」搭配；「改进」多与「方法、工作」搭配；「调整」不含变优之义。故选A。","__sub":"选词填空"},{"id":"yy-16545","module":"yanyu","diff":2,"exam":"省考","prompt":"干事创业，思路和坚持缺一不可。新征程上，要继续______本领，以实干实绩回应人民期盼。看似寻常，实则是长期积累的结果。填入画横线处最恰当的是：","options":["砥砺","锤炼","磨砺","锻炼"],"answer":0,"explanation":"「砥砺」本义为磨刀石，引申为磨炼，与「意志」搭配且语体庄重；「磨砺」与之近义但「砥砺」更常用于「砥砺前行、砥砺意志」。故选A。","__sub":"选词填空"},{"id":"yy-16546","module":"yanyu","diff":2,"exam":"事业编","prompt":"一个朴素的道理反复被验证：方向对了，努力才不会白费。下一步，将______经营主体信心，推动各项工作再上新台阶。这也正是成事的关键所在。填入画横线处最恰当的是：","options":["引发","激发","点燃","调动"],"answer":1,"explanation":"「激发」与「活力、热情、潜能」为固定搭配；「引发」多与「关注、争议」搭配；「点燃」为比喻用法；「调动」多与「积极性」搭配。故选B。","__sub":"选词填空"},{"id":"yy-16547","module":"yanyu","diff":2,"exam":"教师编","prompt":"任何工作要见成效，都离不开科学的方法和踏实的作风。当前正值关键时期，______沉睡的资源要素刻不容缓，必须抓紧抓实抓出成效。唯有如此，才能把好事办好、实事办实。填入画横线处最恰当的是：","options":["启动","唤醒","激活","驱动"],"answer":2,"explanation":"「激活」指刺激使之活跃，与「动力、要素」搭配；「唤醒」指使之觉醒；「启动」指开始进行；「驱动」指推动运转。故选C。","__sub":"选词填空"},{"id":"yy-16548","module":"yanyu","diff":2,"exam":"教师编","prompt":"无论时代如何变化，把事情做实做细始终是成事的基础。当前正值关键时期，______监管责任刻不容缓，必须抓紧抓实抓出成效。这背后考验的正是把握分寸的智慧。填入画横线处最恰当的是：","options":["落实","强化","压实","压紧"],"answer":2,"explanation":"「压实」与「责任」搭配，强调责任层层落实到位；「落实」为通用动词；「压紧」常作「压紧压实」；「强化」不如「压实」精准体现层级传导。故选C。","__sub":"选词填空"},{"id":"yy-16549","module":"yanyu","diff":3,"exam":"国考","prompt":"现实中，方法与态度不同，结果往往截然不同。要在______资源、服务、管理上下更大功夫，让发展成果更多惠及全体人民。看似寻常，实则是长期积累的结果。填入画横线处最恰当的是：","options":["下探","下坠","下沉","下潜"],"answer":2,"explanation":"「下沉」指治理资源向基层倾斜，是规范表述；「下潜」指潜水，「下探」多指价格或行动试探，「下坠」指物体坠落。故选C。","__sub":"选词填空"},{"id":"yy-16550","module":"yanyu","diff":3,"exam":"国考","prompt":"事物的发展自有其规律，顺应它才能事半功倍。只有法治体系真正______到基层，才能让政策在「最后一公里」落地见效。这样的要求，放在哪里都不过时。填入画横线处最恰当的是：","options":["构建","建立","健全","完善"],"answer":2,"explanation":"「健全」强调使完备无缺，与「体系」搭配规范；「建立」指从无到有，「完善」指补足短板，「构建」侧重搭建框架。故选C。","__sub":"选词填空"},{"id":"yy-16551","module":"yanyu","diff":1,"exam":"教师编","prompt":"观察身边的事不难发现，成败的分野常常藏在细节里。要坚持问题导向，______本领，切实解决群众急难愁盼问题。说到底，拼的是态度，比的是功夫。填入画横线处最恰当的是：","options":["锻炼","锤炼","磨砺","砥砺"],"answer":3,"explanation":"「砥砺」本义为磨刀石，引申为磨炼，与「意志」搭配且语体庄重；「磨砺」与之近义但「砥砺」更常用于「砥砺前行、砥砺意志」。故选D。","__sub":"选词填空"},{"id":"yy-16554","module":"yanyu","diff":2,"exam":"国考","prompt":"现实中，方法与态度不同，结果往往截然不同。当前正值关键时期，______诉求表达渠道刻不容缓，必须抓紧抓实抓出成效。看似寻常，实则是长期积累的结果。填入画横线处最恰当的是：","options":["打通","疏通","开拓","畅通"],"answer":3,"explanation":"「畅通」强调使通畅无阻，与「渠道」为固定搭配；「打通」侧重突破障碍；「疏通」多用于管道或疏导矛盾；「开拓」指开辟新领域。故选D。","__sub":"选词填空"},{"id":"yy-16555","module":"yanyu","diff":2,"exam":"省考","prompt":"一个朴素的道理反复被验证：方向对了，努力才不会白费。面对新形势新任务，必须______数据要素价值，牢牢把握发展主动权。这也正是成事的关键所在。填入画横线处最恰当的是：","options":["爆发","发挥","散发","释放"],"answer":3,"explanation":"「释放」与「潜力、红利、活力」搭配；「散发」指分散发出；「发挥」与「作用」搭配；「爆发」指突然发作。故选D。","__sub":"选词填空"},{"id":"yy-16557","module":"yanyu","diff":2,"exam":"事业编","prompt":"无论时代如何变化，把事情做实做细始终是成事的基础。要在______基层基础上下更大功夫，让发展成果更多惠及全体人民。这背后考验的正是把握分寸的智慧。填入画横线处最恰当的是：","options":["夯实","打牢","筑牢","巩固"],"answer":0,"explanation":"「夯实」本义为砸实地基，引申为使稳固，与「基础、根基」搭配；「筑牢」与「防线」搭配；「打牢」语体稍口语；「巩固」侧重使已有的更牢固。故选A。","__sub":"选词填空"},{"id":"yy-16558","module":"yanyu","diff":2,"exam":"医疗编","prompt":"任何工作要见成效，都离不开科学的方法和踏实的作风。要在______城市功能品质上下更大功夫，让发展成果更多惠及全体人民。唯有如此，才能把好事办好、实事办实。填入画横线处最恰当的是：","options":["拔高","提高","提升","增强"],"answer":2,"explanation":"「提升」与「效能、水平」搭配规范；「提高」语义相近但「提升」更书面；「增强」多与「能力、意识」搭配；「拔高」含贬义。故选C。","__sub":"选词填空"},{"id":"yy-16559","module":"yanyu","diff":3,"exam":"国考","prompt":"无论时代如何变化，把事情做实做细始终是成事的基础。越是任务艰巨，越要______新时代发展的宏伟蓝图，确保方向不偏、力度不减。这背后考验的正是把握分寸的智慧。填入画横线处最恰当的是：","options":["描绘","擘画","勾画","规划"],"answer":1,"explanation":"「擘画」指筹划布置，多用于宏观蓝图，书面色彩浓；「描绘」「勾画」偏具体画面；「规划」语体色彩不足。故选B。","__sub":"选词填空"},{"id":"yy-16561","module":"yanyu","diff":1,"exam":"医疗编","prompt":"一个朴素的道理反复被验证：方向对了，努力才不会白费。要在______专精特新企业上下更大功夫，让发展成果更多惠及全体人民。这也正是成事的关键所在。填入画横线处最恰当的是：","options":["培育","培植","培养","孕育"],"answer":0,"explanation":"「培育」与「产业、企业、市场」搭配；「培养」对象为人或能力；「培植」多用于动植物或含贬义；「孕育」强调正在形成。故选A。","__sub":"选词填空"},{"id":"yy-16562","module":"yanyu","diff":1,"exam":"事业编","prompt":"任何工作要见成效，都离不开科学的方法和踏实的作风。回顾这些年走过的路，______文明乡风始终是我们攻坚克难的重要法宝。唯有如此，才能把好事办好、实事办实。填入画横线处最恰当的是：","options":["涵养","养护","培养","营造"],"answer":0,"explanation":"「涵养」指蓄积并养护，与「生态、水源」搭配；「培养」对象为人或能力；「营造」多与「氛围、环境」搭配；「养护」不含培育之义。故选A。","__sub":"选词填空"},{"id":"yy-16564","module":"yanyu","diff":2,"exam":"国考","prompt":"很多事看起来简单，真要做扎实并不容易。要坚持问题导向，______生态保护红线，切实解决群众急难愁盼问题。道理虽朴素，真正做到并不容易。填入画横线处最恰当的是：","options":["守住","把牢","防住","守牢"],"answer":3,"explanation":"「守牢」与「底线」搭配，强调牢牢守住；「守住」程度稍弱；「把牢」多与「关口」搭配；「防住」为口语。故选D。","__sub":"选词填空"},{"id":"yy-16565","module":"yanyu","diff":2,"exam":"国考","prompt":"观察身边的事不难发现，成败的分野常常藏在细节里。实践证明，______法治体系是推动高质量发展的关键一招。说到底，拼的是态度，比的是功夫。填入画横线处最恰当的是：","options":["建立","健全","完善","构建"],"answer":1,"explanation":"「健全」强调使完备无缺，与「体系」搭配规范；「建立」指从无到有，「完善」指补足短板，「构建」侧重搭建框架。故选B。","__sub":"选词填空"},{"id":"yy-16566","module":"yanyu","diff":2,"exam":"医疗编","prompt":"观察身边的事不难发现，成败的分野常常藏在细节里。各级政府要持续______时代脉搏，不断增强群众的获得感、幸福感、安全感。说到底，拼的是态度，比的是功夫。填入画横线处最恰当的是：","options":["把玩","把守","把持","把握"],"answer":3,"explanation":"「把握」与抽象事物（特点、规律、机遇）搭配；「把守」指守卫关口，「把持」含贬义指独揽，「把玩」指赏玩物品。故选D。","__sub":"选词填空"},{"id":"yy-16568","module":"yanyu","diff":2,"exam":"事业编","prompt":"任何工作要见成效，都离不开科学的方法和踏实的作风。要在______诉求表达渠道上下更大功夫，让发展成果更多惠及全体人民。唯有如此，才能把好事办好、实事办实。填入画横线处最恰当的是：","options":["开拓","畅通","疏通","打通"],"answer":1,"explanation":"「畅通」强调使通畅无阻，与「渠道」为固定搭配；「打通」侧重突破障碍；「疏通」多用于管道或疏导矛盾；「开拓」指开辟新领域。故选B。","__sub":"选词填空"},{"id":"yy-16569","module":"yanyu","diff":3,"exam":"省考","prompt":"无论时代如何变化，把事情做实做细始终是成事的基础。越是任务艰巨，越要______基层基础，确保方向不偏、力度不减。这背后考验的正是把握分寸的智慧。填入画横线处最恰当的是：","options":["夯实","巩固","筑牢","打牢"],"answer":0,"explanation":"「夯实」本义为砸实地基，引申为使稳固，与「基础、根基」搭配；「筑牢」与「防线」搭配；「打牢」语体稍口语；「巩固」侧重使已有的更牢固。故选A。","__sub":"选词填空"},{"id":"yy-16570","module":"yanyu","diff":3,"exam":"国考","prompt":"干事创业，思路和坚持缺一不可。各地区各部门要拿出真招实招，______安全生产责任，确保各项部署落地生根。其中的道理值得每个人细细体会。填入画横线处最恰当的是：","options":["强化","落实","压紧","压实"],"answer":3,"explanation":"「压实」与「责任」搭配，强调责任层层落实到位；「落实」为通用动词；「压紧」常作「压紧压实」；「强化」不如「压实」精准体现层级传导。故选D。","__sub":"选词填空"},{"id":"yy-16572","module":"yanyu","diff":1,"exam":"省考","prompt":"一个朴素的道理反复被验证：方向对了，努力才不会白费。当前正值关键时期，______社会保障网络刻不容缓，必须抓紧抓实抓出成效。这也正是成事的关键所在。填入画横线处最恰当的是：","options":["完善","构建","搭建","健全"],"answer":3,"explanation":"「健全」强调使完备无缺；「完善」指补足短板；「构建」「搭建」侧重从无到有搭建。故选D。","__sub":"选词填空"},{"id":"yy-16578","module":"yanyu","diff":2,"exam":"教师编","prompt":"很多事看起来简单，真要做扎实并不容易。只有改革开放各领域真正______到基层，才能让政策在「最后一公里」落地见效。道理虽朴素，真正做到并不容易。填入画横线处最恰当的是：","options":["贯串","穿过","贯穿","经过"],"answer":2,"explanation":"「贯穿」指从头到尾通贯，与「全过程」搭配规范；「穿过」「经过」仅指空间或时间经过，不含通贯始终之义。故选C。","__sub":"选词填空"},{"id":"yy-16579","module":"yanyu","diff":3,"exam":"教师编","prompt":"一个朴素的道理反复被验证：方向对了，努力才不会白费。越是任务艰巨，越要______乡村振兴，确保方向不偏、力度不减。这也正是成事的关键所在。填入画横线处最恰当的是：","options":["赋能","助力","赋权","加持"],"answer":0,"explanation":"「赋能」指赋予能力，是数字经济语境的规范表述；「赋权」指赋予权力；「加持」为口语化外来词；「助力」语义宽泛。故选A。","__sub":"选词填空"},{"id":"yy-16580","module":"yanyu","diff":3,"exam":"国考","prompt":"很多事看起来简单，真要做扎实并不容易。下一步，将______品格，推动各项工作再上新台阶。道理虽朴素，真正做到并不容易。填入画横线处最恰当的是：","options":["砥砺","锻炼","磨砺","锤炼"],"answer":0,"explanation":"「砥砺」本义为磨刀石，引申为磨炼，与「意志」搭配且语体庄重；「磨砺」与之近义但「砥砺」更常用于「砥砺前行、砥砺意志」。故选A。","__sub":"选词填空"},{"id":"yy-16582","module":"yanyu","diff":1,"exam":"国考","prompt":"事物的发展自有其规律，顺应它才能事半功倍。各地区各部门要拿出真招实招，______企业主体责任，确保各项部署落地生根。这样的要求，放在哪里都不过时。填入画横线处最恰当的是：","options":["压实","强化","落实","压紧"],"answer":0,"explanation":"「压实」与「责任」搭配，强调责任层层落实到位；「落实」为通用动词；「压紧」常作「压紧压实」；「强化」不如「压实」精准体现层级传导。故选A。","__sub":"选词填空"},{"id":"yy-16585","module":"yanyu","diff":2,"exam":"国考","prompt":"观察身边的事不难发现，成败的分野常常藏在细节里。只有公共服务体系真正______到基层，才能让政策在「最后一公里」落地见效。说到底，拼的是态度，比的是功夫。填入画横线处最恰当的是：","options":["建立","完善","健全","构建"],"answer":2,"explanation":"「健全」强调使完备无缺，与「体系」搭配规范；「建立」指从无到有，「完善」指补足短板，「构建」侧重搭建框架。故选C。","__sub":"选词填空"},{"id":"yy-16586","module":"yanyu","diff":2,"exam":"医疗编","prompt":"很多事看起来简单，真要做扎实并不容易。要在______城市文化气质上下更大功夫，让发展成果更多惠及全体人民。道理虽朴素，真正做到并不容易。填入画横线处最恰当的是：","options":["涵养","培养","养护","营造"],"answer":0,"explanation":"「涵养」指蓄积并养护，与「生态、水源」搭配；「培养」对象为人或能力；「营造」多与「氛围、环境」搭配；「养护」不含培育之义。故选A。","__sub":"选词填空"},{"id":"yy-16587","module":"yanyu","diff":2,"exam":"省考","prompt":"无论时代如何变化，把事情做实做细始终是成事的基础。当前正值关键时期，______优质医疗资源刻不容缓，必须抓紧抓实抓出成效。这背后考验的正是把握分寸的智慧。填入画横线处最恰当的是：","options":["下坠","下探","下潜","下沉"],"answer":3,"explanation":"「下沉」指治理资源向基层倾斜，是规范表述；「下潜」指潜水，「下探」多指价格或行动试探，「下坠」指物体坠落。故选D。","__sub":"选词填空"},{"id":"yy-16588","module":"yanyu","diff":2,"exam":"事业编","prompt":"很多事看起来简单，真要做扎实并不容易。当前正值关键时期，______企业主体责任刻不容缓，必须抓紧抓实抓出成效。道理虽朴素，真正做到并不容易。填入画横线处最恰当的是：","options":["压实","落实","压紧","强化"],"answer":0,"explanation":"「压实」与「责任」搭配，强调责任层层落实到位；「落实」为通用动词；「压紧」常作「压紧压实」；「强化」不如「压实」精准体现层级传导。故选A。","__sub":"选词填空"},{"id":"yy-16589","module":"yanyu","diff":3,"exam":"省考","prompt":"任何工作要见成效，都离不开科学的方法和踏实的作风。越是任务艰巨，越要______政企沟通机制，确保方向不偏、力度不减。唯有如此，才能把好事办好、实事办实。填入画横线处最恰当的是：","options":["疏通","畅通","打通","开拓"],"answer":1,"explanation":"「畅通」强调使通畅无阻，与「渠道」为固定搭配；「打通」侧重突破障碍；「疏通」多用于管道或疏导矛盾；「开拓」指开辟新领域。故选B。","__sub":"选词填空"},{"id":"yy-16590","module":"yanyu","diff":3,"exam":"国考","prompt":"观察身边的事不难发现，成败的分野常常藏在细节里。实践证明，______服务空白是推动高质量发展的关键一招。说到底，拼的是态度，比的是功夫。填入画横线处最恰当的是：","options":["补足","填补","补齐","弥补"],"answer":2,"explanation":"「补齐」与「短板」为固定搭配，强调使达到应有水平；「补足」多与「差额」搭配；「填补」多与「空白」搭配；「弥补」多与「损失」搭配。故选C。","__sub":"选词填空"},{"id":"yy-16592","module":"yanyu","diff":1,"exam":"国考","prompt":"现实中，方法与态度不同，结果往往截然不同。回顾这些年走过的路，______志愿服务体系始终是我们攻坚克难的重要法宝。看似寻常，实则是长期积累的结果。填入画横线处最恰当的是：","options":["搭建","健全","完善","构建"],"answer":1,"explanation":"「健全」强调使完备无缺；「完善」指补足短板；「构建」「搭建」侧重从无到有搭建。故选B。","__sub":"选词填空"},{"id":"yy-16593","module":"yanyu","diff":1,"exam":"事业编","prompt":"干事创业，思路和坚持缺一不可。各地区各部门要拿出真招实招，______责任担当，确保各项部署落地生根。其中的道理值得每个人细细体会。填入画横线处最恰当的是：","options":["强化","加强","深化","增强"],"answer":0,"explanation":"「强化」与「意识、思维」搭配，强调使之更牢固；「增强」语义相近但搭配习惯不同；「加强」为通用动词；「深化」指向深处发展。故选A。","__sub":"选词填空"},{"id":"yy-16594","module":"yanyu","diff":2,"exam":"国考","prompt":"干事创业，思路和坚持缺一不可。各地区各部门要拿出真招实招，______创新创造潜能，确保各项部署落地生根。其中的道理值得每个人细细体会。填入画横线处最恰当的是：","options":["点燃","调动","引发","激发"],"answer":3,"explanation":"「激发」与「活力、热情、潜能」为固定搭配；「引发」多与「关注、争议」搭配；「点燃」为比喻用法；「调动」多与「积极性」搭配。故选D。","__sub":"选词填空"},{"id":"yy-16595","module":"yanyu","diff":2,"exam":"国考","prompt":"各地区各部门要拿出真招实招，______新时代发展的宏伟蓝图，确保各项部署落地生根。填入画横线处最恰当的是：","options":["规划","描绘","勾画","擘画"],"answer":3,"explanation":"「擘画」指筹划布置，多用于宏观蓝图，书面色彩浓；「描绘」「勾画」偏具体画面；「规划」语体色彩不足。故选D。","__sub":"选词填空"},{"id":"yy-16601","module":"yanyu","diff":1,"exam":"国考","prompt":"无论时代如何变化，把事情做实做细始终是成事的基础。当前正值关键时期，______本领刻不容缓，必须抓紧抓实抓出成效。这背后考验的正是把握分寸的智慧。填入画横线处最恰当的是：","options":["磨砺","砥砺","锻炼","锤炼"],"answer":1,"explanation":"「砥砺」本义为磨刀石，引申为磨炼，与「意志」搭配且语体庄重；「磨砺」与之近义但「砥砺」更常用于「砥砺前行、砥砺意志」。故选B。","__sub":"选词填空"},{"id":"yy-16602","module":"yanyu","diff":1,"exam":"国考","prompt":"任何工作要见成效，都离不开科学的方法和踏实的作风。新征程上，要继续______政策导向，以实干实绩回应人民期盼。唯有如此，才能把好事办好、实事办实。填入画横线处最恰当的是：","options":["把守","把持","把握","把玩"],"answer":2,"explanation":"「把握」与抽象事物（特点、规律、机遇）搭配；「把守」指守卫关口，「把持」含贬义指独揽，「把玩」指赏玩物品。故选C。","__sub":"选词填空"},{"id":"yy-16603","module":"yanyu","diff":1,"exam":"事业编","prompt":"干事创业，思路和坚持缺一不可。各级政府要持续______生态保护红线，不断增强群众的获得感、幸福感、安全感。其中的道理值得每个人细细体会。填入画横线处最恰当的是：","options":["防住","守住","守牢","把牢"],"answer":2,"explanation":"「守牢」与「底线」搭配，强调牢牢守住；「守住」程度稍弱；「把牢」多与「关口」搭配；「防住」为口语。故选C。","__sub":"选词填空"},{"id":"yy-16605","module":"yanyu","diff":2,"exam":"教师编","prompt":"现实中，方法与态度不同，结果往往截然不同。各级政府要持续______安全生产责任，不断增强群众的获得感、幸福感、安全感。看似寻常，实则是长期积累的结果。填入画横线处最恰当的是：","options":["压实","强化","落实","压紧"],"answer":0,"explanation":"「压实」与「责任」搭配，强调责任层层落实到位；「落实」为通用动词；「压紧」常作「压紧压实」；「强化」不如「压实」精准体现层级传导。故选A。","__sub":"选词填空"},{"id":"yy-16609","module":"yanyu","diff":3,"exam":"事业编","prompt":"现实中，方法与态度不同，结果往往截然不同。新征程上，要继续______发展规律，以实干实绩回应人民期盼。看似寻常，实则是长期积累的结果。填入画横线处最恰当的是：","options":["把守","把玩","把握","把持"],"answer":2,"explanation":"「把握」与抽象事物（特点、规律、机遇）搭配；「把守」指守卫关口，「把持」含贬义指独揽，「把玩」指赏玩物品。故选C。","__sub":"选词填空"},{"id":"yy-16610","module":"yanyu","diff":3,"exam":"国考","prompt":"现实中，方法与态度不同，结果往往截然不同。各地区各部门要拿出真招实招，______底线思维，确保各项部署落地生根。看似寻常，实则是长期积累的结果。填入画横线处最恰当的是：","options":["深化","增强","加强","强化"],"answer":3,"explanation":"「强化」与「意识、思维」搭配，强调使之更牢固；「增强」语义相近但搭配习惯不同；「加强」为通用动词；「深化」指向深处发展。故选D。","__sub":"选词填空"},{"id":"yy-16613","module":"yanyu","diff":1,"exam":"教师编","prompt":"回顾这些年走过的路，______风清气正的政治生态始终是我们攻坚克难的重要法宝。填入画横线处最恰当的是：","options":["涵养","养护","营造","培养"],"answer":0,"explanation":"「涵养」指蓄积并养护，与「生态、水源」搭配；「培养」对象为人或能力；「营造」多与「氛围、环境」搭配；「养护」不含培育之义。故选A。","__sub":"选词填空"},{"id":"yy-16614","module":"yanyu","diff":2,"exam":"事业编","prompt":"任何工作要见成效，都离不开科学的方法和踏实的作风。各级政府要持续______乡村振兴始终，不断增强群众的获得感、幸福感、安全感。唯有如此，才能把好事办好、实事办实。填入画横线处最恰当的是：","options":["贯串","经过","贯穿","穿过"],"answer":2,"explanation":"「贯穿」指从头到尾通贯，与「全过程」搭配规范；「穿过」「经过」仅指空间或时间经过，不含通贯始终之义。故选C。","__sub":"选词填空"},{"id":"yy-16616","module":"yanyu","diff":2,"exam":"国考","prompt":"很多事看起来简单，真要做扎实并不容易。各地区各部门要拿出真招实招，______基层治理，确保各项部署落地生根。道理虽朴素，真正做到并不容易。填入画横线处最恰当的是：","options":["赋能","助力","赋权","加持"],"answer":0,"explanation":"「赋能」指赋予能力，是数字经济语境的规范表述；「赋权」指赋予权力；「加持」为口语化外来词；「助力」语义宽泛。故选A。","__sub":"选词填空"},{"id":"yy-16617","module":"yanyu","diff":2,"exam":"事业编","prompt":"现实中，方法与态度不同，结果往往截然不同。只有实体经济根基真正______到基层，才能让政策在「最后一公里」落地见效。看似寻常，实则是长期积累的结果。填入画横线处最恰当的是：","options":["筑牢","培植","厚植","加深"],"answer":2,"explanation":"「厚植」指深厚培育，与「优势、底色、根基」搭配；「培植」多用于培育动植物或扶植势力；「加深」与「底色」搭配不当。故选C。","__sub":"选词填空"},{"id":"yy-16618","module":"yanyu","diff":2,"exam":"省考","prompt":"很多事看起来简单，真要做扎实并不容易。各地区各部门要拿出真招实招，______发展优势，确保各项部署落地生根。道理虽朴素，真正做到并不容易。填入画横线处最恰当的是：","options":["培植","筑牢","厚植","加深"],"answer":2,"explanation":"「厚植」指深厚培育，与「优势、底色、根基」搭配；「培植」多用于培育动植物或扶植势力；「加深」与「底色」搭配不当。故选C。","__sub":"选词填空"},{"id":"yy-16620","module":"yanyu","diff":3,"exam":"省考","prompt":"观察身边的事不难发现，成败的分野常常藏在细节里。要坚持问题导向，______安全事故多发的势头，切实解决群众急难愁盼问题。说到底，拼的是态度，比的是功夫。填入画横线处最恰当的是：","options":["控制","遏制","制止","遏止"],"answer":1,"explanation":"「遏制」强调压制住势头、多与「势头/态势」搭配；「遏止」侧重使之停止，多用于具体行为；「控制」「制止」语义宽泛。故选B。","__sub":"选词填空"},{"id":"yy-16621","module":"yanyu","diff":1,"exam":"国考","prompt":"观察身边的事不难发现，成败的分野常常藏在细节里。只有执法力量真正______到基层，才能让政策在「最后一公里」落地见效。说到底，拼的是态度，比的是功夫。填入画横线处最恰当的是：","options":["下坠","下探","下潜","下沉"],"answer":3,"explanation":"「下沉」指治理资源向基层倾斜，是规范表述；「下潜」指潜水，「下探」多指价格或行动试探，「下坠」指物体坠落。故选D。","__sub":"选词填空"},{"id":"yy-16624","module":"yanyu","diff":2,"exam":"省考","prompt":"无论时代如何变化，把事情做实做细始终是成事的基础。越是任务艰巨，越要______品格，确保方向不偏、力度不减。这背后考验的正是把握分寸的智慧。填入画横线处最恰当的是：","options":["锤炼","锻炼","磨砺","砥砺"],"answer":3,"explanation":"「砥砺」本义为磨刀石，引申为磨炼，与「意志」搭配且语体庄重；「磨砺」与之近义但「砥砺」更常用于「砥砺前行、砥砺意志」。故选D。","__sub":"选词填空"},{"id":"yy-16626","module":"yanyu","diff":2,"exam":"事业编","prompt":"一个朴素的道理反复被验证：方向对了，努力才不会白费。面对新形势新任务，必须______监督机制，牢牢把握发展主动权。这也正是成事的关键所在。填入画横线处最恰当的是：","options":["完善","建立","构建","健全"],"answer":3,"explanation":"「健全」强调使完备无缺，与「体系」搭配规范；「建立」指从无到有，「完善」指补足短板，「构建」侧重搭建框架。故选D。","__sub":"选词填空"},{"id":"yy-16633","module":"yanyu","diff":1,"exam":"国考","prompt":"观察身边的事不难发现，成败的分野常常藏在细节里。实践证明，______数据要素价值是推动高质量发展的关键一招。说到底，拼的是态度，比的是功夫。填入画横线处最恰当的是：","options":["爆发","散发","释放","发挥"],"answer":2,"explanation":"「释放」与「潜力、红利、活力」搭配；「散发」指分散发出；「发挥」与「作用」搭配；「爆发」指突然发作。故选C。","__sub":"选词填空"},{"id":"yy-16636","module":"yanyu","diff":2,"exam":"医疗编","prompt":"现实中，方法与态度不同，结果往往截然不同。当前正值关键时期，______志愿服务体系刻不容缓，必须抓紧抓实抓出成效。看似寻常，实则是长期积累的结果。填入画横线处最恰当的是：","options":["健全","完善","搭建","构建"],"answer":0,"explanation":"「健全」强调使完备无缺；「完善」指补足短板；「构建」「搭建」侧重从无到有搭建。故选A。","__sub":"选词填空"},{"id":"yy-16643","module":"yanyu","diff":1,"exam":"事业编","prompt":"干事创业，思路和坚持缺一不可。当前正值关键时期，______食品安全监管刻不容缓，必须抓紧抓实抓出成效。其中的道理值得每个人细细体会。填入画横线处最恰当的是：","options":["强化","深化","增强","加强"],"answer":0,"explanation":"「强化」与「意识、思维」搭配，强调使之更牢固；「增强」语义相近但搭配习惯不同；「加强」为通用动词；「深化」指向深处发展。故选A。","__sub":"选词填空"},{"id":"yy-16645","module":"yanyu","diff":2,"exam":"省考","prompt":"很多事看起来简单，真要做扎实并不容易。越是任务艰巨，越要______新型农业经营主体，确保方向不偏、力度不减。道理虽朴素，真正做到并不容易。填入画横线处最恰当的是：","options":["培植","培育","培养","孕育"],"answer":1,"explanation":"「培育」与「产业、企业、市场」搭配；「培养」对象为人或能力；「培植」多用于动植物或含贬义；「孕育」强调正在形成。故选B。","__sub":"选词填空"},{"id":"yy-16646","module":"yanyu","diff":2,"exam":"事业编","prompt":"任何工作要见成效，都离不开科学的方法和踏实的作风。只有廉洁底线真正______到基层，才能让政策在「最后一公里」落地见效。唯有如此，才能把好事办好、实事办实。填入画横线处最恰当的是：","options":["构建","筑牢","夯实","筑造"],"answer":1,"explanation":"「筑牢」与「防线」为固定搭配，强调使牢固；「筑造」指建造实体；「构建」侧重搭建体系；「夯实」多与「基础」搭配。故选B。","__sub":"选词填空"},{"id":"yy-16647","module":"yanyu","diff":2,"exam":"省考","prompt":"观察身边的事不难发现，成败的分野常常藏在细节里。只有中小企业发展真正______到基层，才能让政策在「最后一公里」落地见效。说到底，拼的是态度，比的是功夫。填入画横线处最恰当的是：","options":["助力","赋权","赋能","加持"],"answer":2,"explanation":"「赋能」指赋予能力，是数字经济语境的规范表述；「赋权」指赋予权力；「加持」为口语化外来词；「助力」语义宽泛。故选C。","__sub":"选词填空"},{"id":"yy-16650","module":"yanyu","diff":3,"exam":"教师编","prompt":"观察身边的事不难发现，成败的分野常常藏在细节里。下一步，将______就业门路，推动各项工作再上新台阶。说到底，拼的是态度，比的是功夫。填入画横线处最恰当的是：","options":["拓宽","开拓","延伸","扩大"],"answer":0,"explanation":"「拓宽」与「渠道、门路、视野」搭配；「开拓」指开辟新领域；「扩大」多与「规模、范围」搭配；「延伸」侧重长度延长。故选A。","__sub":"选词填空"},{"id":"yy-16651","module":"yanyu","diff":1,"exam":"事业编","prompt":"一个朴素的道理反复被验证：方向对了，努力才不会白费。要在______斗争精神上下更大功夫，让发展成果更多惠及全体人民。这也正是成事的关键所在。填入画横线处最恰当的是：","options":["锻炼","磨砺","砥砺","锤炼"],"answer":2,"explanation":"「砥砺」本义为磨刀石，引申为磨炼，与「意志」搭配且语体庄重；「磨砺」与之近义但「砥砺」更常用于「砥砺前行、砥砺意志」。故选C。","__sub":"选词填空"},{"id":"yy-16659","module":"yanyu","diff":3,"exam":"省考","prompt":"一个朴素的道理反复被验证：方向对了，努力才不会白费。各级政府要持续______城乡发展布局，不断增强群众的获得感、幸福感、安全感。这也正是成事的关键所在。填入画横线处最恰当的是：","options":["统筹","兼顾","统率","协调"],"answer":0,"explanation":"「统筹」指全面筹划、统一安排，与「推进」搭配且强调全局性；「统率」指率领；「兼顾」只强调同时照顾；「协调」侧重配合关系。故选A。","__sub":"选词填空"},{"id":"yy-16661","module":"yanyu","diff":1,"exam":"国考","prompt":"任何工作要见成效，都离不开科学的方法和踏实的作风。新征程上，要继续______资源配置，以实干实绩回应人民期盼。唯有如此，才能把好事办好、实事办实。填入画横线处最恰当的是：","options":["改进","调整","改善","优化"],"answer":3,"explanation":"「优化」指加以改变使其优良，与「环境、结构」搭配规范；「改善」多与「条件、生活」搭配；「改进」多与「方法、工作」搭配；「调整」不含变优之义。故选D。","__sub":"选词填空"},{"id":"yy-16663","module":"yanyu","diff":1,"exam":"事业编","prompt":"任何工作要见成效，都离不开科学的方法和踏实的作风。要在______矛盾调解体系上下更大功夫，让发展成果更多惠及全体人民。唯有如此，才能把好事办好、实事办实。填入画横线处最恰当的是：","options":["搭建","健全","完善","构建"],"answer":1,"explanation":"「健全」强调使完备无缺；「完善」指补足短板；「构建」「搭建」侧重从无到有搭建。故选B。","__sub":"选词填空"},{"id":"yy-16665","module":"yanyu","diff":2,"exam":"事业编","prompt":"观察身边的事不难发现，成败的分野常常藏在细节里。面对新形势新任务，必须______初心，牢牢把握发展主动权。说到底，拼的是态度，比的是功夫。填入画横线处最恰当的是：","options":["锻炼","砥砺","锤炼","磨砺"],"answer":1,"explanation":"「砥砺」本义为磨刀石，引申为磨炼，与「意志」搭配且语体庄重；「磨砺」与之近义但「砥砺」更常用于「砥砺前行、砥砺意志」。故选B。","__sub":"选词填空"},{"id":"yy-16669","module":"yanyu","diff":3,"exam":"教师编","prompt":"一个朴素的道理反复被验证：方向对了，努力才不会白费。下一步，将______基础设施弱项，推动各项工作再上新台阶。这也正是成事的关键所在。填入画横线处最恰当的是：","options":["补足","补齐","弥补","填补"],"answer":1,"explanation":"「补齐」与「短板」为固定搭配，强调使达到应有水平；「补足」多与「差额」搭配；「填补」多与「空白」搭配；「弥补」多与「损失」搭配。故选B。","__sub":"选词填空"},{"id":"yy-16675","module":"yanyu","diff":2,"exam":"医疗编","prompt":"任何工作要见成效，都离不开科学的方法和踏实的作风。要在______生态环保责任上下更大功夫，让发展成果更多惠及全体人民。唯有如此，才能把好事办好、实事办实。填入画横线处最恰当的是：","options":["落实","压紧","压实","强化"],"answer":2,"explanation":"「压实」与「责任」搭配，强调责任层层落实到位；「落实」为通用动词；「压紧」常作「压紧压实」；「强化」不如「压实」精准体现层级传导。故选C。","__sub":"选词填空"},{"id":"yy-16680","module":"yanyu","diff":3,"exam":"省考","prompt":"干事创业，思路和坚持缺一不可。要坚持问题导向，______基础设施弱项，切实解决群众急难愁盼问题。其中的道理值得每个人细细体会。填入画横线处最恰当的是：","options":["补齐","弥补","补足","填补"],"answer":0,"explanation":"「补齐」与「短板」为固定搭配，强调使达到应有水平；「补足」多与「差额」搭配；「填补」多与「空白」搭配；「弥补」多与「损失」搭配。故选A。","__sub":"选词填空"},{"id":"yy-16681","module":"yanyu","diff":1,"exam":"教师编","prompt":"很多事看起来简单，真要做扎实并不容易。下一步，将______生态保护红线，推动各项工作再上新台阶。道理虽朴素，真正做到并不容易。填入画横线处最恰当的是：","options":["把牢","守牢","守住","防住"],"answer":1,"explanation":"「守牢」与「底线」搭配，强调牢牢守住；「守住」程度稍弱；「把牢」多与「关口」搭配；「防住」为口语。故选B。","__sub":"选词填空"},{"id":"yy-16682","module":"yanyu","diff":1,"exam":"省考","prompt":"任何工作要见成效，都离不开科学的方法和踏实的作风。新征程上，要继续______发展优势，以实干实绩回应人民期盼。唯有如此，才能把好事办好、实事办实。填入画横线处最恰当的是：","options":["加深","筑牢","厚植","培植"],"answer":2,"explanation":"「厚植」指深厚培育，与「优势、底色、根基」搭配；「培植」多用于培育动植物或扶植势力；「加深」与「底色」搭配不当。故选C。","__sub":"选词填空"},{"id":"yy-16685","module":"yanyu","diff":2,"exam":"国考","prompt":"任何工作要见成效，都离不开科学的方法和踏实的作风。面对新形势新任务，必须______公共服务，牢牢把握发展主动权。唯有如此，才能把好事办好、实事办实。填入画横线处最恰当的是：","options":["下沉","下探","下潜","下坠"],"answer":0,"explanation":"「下沉」指治理资源向基层倾斜，是规范表述；「下潜」指潜水，「下探」多指价格或行动试探，「下坠」指物体坠落。故选A。","__sub":"选词填空"},{"id":"yy-16686","module":"yanyu","diff":2,"exam":"国考","prompt":"无论时代如何变化，把事情做实做细始终是成事的基础。新征程上，要继续______基层基础，以实干实绩回应人民期盼。这背后考验的正是把握分寸的智慧。填入画横线处最恰当的是：","options":["打牢","夯实","筑牢","巩固"],"answer":1,"explanation":"「夯实」本义为砸实地基，引申为使稳固，与「基础、根基」搭配；「筑牢」与「防线」搭配；「打牢」语体稍口语；「巩固」侧重使已有的更牢固。故选B。","__sub":"选词填空"},{"id":"yy-16691","module":"yanyu","diff":1,"exam":"国考","prompt":"无论时代如何变化，把事情做实做细始终是成事的基础。越是任务艰巨，越要______属地管理责任，确保方向不偏、力度不减。这背后考验的正是把握分寸的智慧。填入画横线处最恰当的是：","options":["落实","压紧","压实","强化"],"answer":2,"explanation":"「压实」与「责任」搭配，强调责任层层落实到位；「落实」为通用动词；「压紧」常作「压紧压实」；「强化」不如「压实」精准体现层级传导。故选C。","__sub":"选词填空"},{"id":"yy-16694","module":"yanyu","diff":2,"exam":"省考","prompt":"事物的发展自有其规律，顺应它才能事半功倍。只有发展合力真正______到基层，才能让政策在「最后一公里」落地见效。这样的要求，放在哪里都不过时。填入画横线处最恰当的是：","options":["聚集","凝聚","集中","汇聚"],"answer":1,"explanation":"「凝聚」多与「共识、人心、力量」搭配，强调由分散到统一；「聚集」侧重物理集合；「集中」侧重把分散的集中起来。故选B。","__sub":"选词填空"},{"id":"yy-16695","module":"yanyu","diff":2,"exam":"医疗编","prompt":"现实中，方法与态度不同，结果往往截然不同。面对新形势新任务，必须______人心，牢牢把握发展主动权。看似寻常，实则是长期积累的结果。填入画横线处最恰当的是：","options":["集中","凝聚","汇聚","聚集"],"answer":1,"explanation":"「凝聚」多与「共识、人心、力量」搭配，强调由分散到统一；「聚集」侧重物理集合；「集中」侧重把分散的集中起来。故选B。","__sub":"选词填空"},{"id":"yy-16699","module":"yanyu","diff":3,"exam":"省考","prompt":"观察身边的事不难发现，成败的分野常常藏在细节里。要在______经营主体信心上下更大功夫，让发展成果更多惠及全体人民。说到底，拼的是态度，比的是功夫。填入画横线处最恰当的是：","options":["引发","调动","激发","点燃"],"answer":2,"explanation":"「激发」与「活力、热情、潜能」为固定搭配；「引发」多与「关注、争议」搭配；「点燃」为比喻用法；「调动」多与「积极性」搭配。故选C。","__sub":"选词填空"},{"id":"yy-16701","module":"yanyu","diff":1,"exam":"事业编","prompt":"干事创业，思路和坚持缺一不可。回顾这些年走过的路，______安全底线始终是我们攻坚克难的重要法宝。其中的道理值得每个人细细体会。填入画横线处最恰当的是：","options":["构建","筑牢","筑造","夯实"],"answer":1,"explanation":"「筑牢」与「防线」为固定搭配，强调使牢固；「筑造」指建造实体；「构建」侧重搭建体系；「夯实」多与「基础」搭配。故选B。","__sub":"选词填空"},{"id":"yy-16704","module":"yanyu","diff":2,"exam":"医疗编","prompt":"干事创业，思路和坚持缺一不可。越是任务艰巨，越要______碳达峰碳中和目标，确保方向不偏、力度不减。其中的道理值得每个人细细体会。填入画横线处最恰当的是：","options":["盯住","锁定","瞄准","锚定"],"answer":3,"explanation":"「锚定」比喻像锚一样固定住目标，多用于宏观战略语境；「锁定」「瞄准」「盯住」语体偏口语，庄重色彩不足。故选D。","__sub":"选词填空"},{"id":"yy-16706","module":"yanyu","diff":2,"exam":"国考","prompt":"事物的发展自有其规律，顺应它才能事半功倍。各级政府要持续______数据要素价值，不断增强群众的获得感、幸福感、安全感。这样的要求，放在哪里都不过时。填入画横线处最恰当的是：","options":["发挥","散发","爆发","释放"],"answer":3,"explanation":"「释放」与「潜力、红利、活力」搭配；「散发」指分散发出；「发挥」与「作用」搭配；「爆发」指突然发作。故选D。","__sub":"选词填空"},{"id":"yy-16707","module":"yanyu","diff":2,"exam":"国考","prompt":"很多事看起来简单，真要做扎实并不容易。回顾这些年走过的路，______责任担当始终是我们攻坚克难的重要法宝。道理虽朴素，真正做到并不容易。填入画横线处最恰当的是：","options":["深化","强化","增强","加强"],"answer":1,"explanation":"「强化」与「意识、思维」搭配，强调使之更牢固；「增强」语义相近但搭配习惯不同；「加强」为通用动词；「深化」指向深处发展。故选B。","__sub":"选词填空"},{"id":"yy-16708","module":"yanyu","diff":2,"exam":"国考","prompt":"事物的发展自有其规律，顺应它才能事半功倍。要坚持问题导向，______品格，切实解决群众急难愁盼问题。这样的要求，放在哪里都不过时。填入画横线处最恰当的是：","options":["锻炼","砥砺","磨砺","锤炼"],"answer":1,"explanation":"「砥砺」本义为磨刀石，引申为磨炼，与「意志」搭配且语体庄重；「磨砺」与之近义但「砥砺」更常用于「砥砺前行、砥砺意志」。故选B。","__sub":"选词填空"},{"id":"yy-16709","module":"yanyu","diff":3,"exam":"教师编","prompt":"事物的发展自有其规律，顺应它才能事半功倍。越是任务艰巨，越要______市场主体活力，确保方向不偏、力度不减。这样的要求，放在哪里都不过时。填入画横线处最恰当的是：","options":["调动","点燃","引发","激发"],"answer":3,"explanation":"「激发」与「活力、热情、潜能」为固定搭配；「引发」多与「关注、争议」搭配；「点燃」为比喻用法；「调动」多与「积极性」搭配。故选D。","__sub":"选词填空"},{"id":"yy-16710","module":"yanyu","diff":3,"exam":"省考","prompt":"观察身边的事不难发现，成败的分野常常藏在细节里。新征程上，要继续______专精特新企业，以实干实绩回应人民期盼。说到底，拼的是态度，比的是功夫。填入画横线处最恰当的是：","options":["培养","孕育","培育","培植"],"answer":2,"explanation":"「培育」与「产业、企业、市场」搭配；「培养」对象为人或能力；「培植」多用于动植物或含贬义；「孕育」强调正在形成。故选C。","__sub":"选词填空"},{"id":"yy-16711","module":"yanyu","diff":1,"exam":"国考","prompt":"任何工作要见成效，都离不开科学的方法和踏实的作风。面对新形势新任务，必须______营商环境，牢牢把握发展主动权。唯有如此，才能把好事办好、实事办实。填入画横线处最恰当的是：","options":["改善","优化","调整","改进"],"answer":1,"explanation":"「优化」指加以改变使其优良，与「环境、结构」搭配规范；「改善」多与「条件、生活」搭配；「改进」多与「方法、工作」搭配；「调整」不含变优之义。故选B。","__sub":"选词填空"},{"id":"yy-16713","module":"yanyu","diff":1,"exam":"国考","prompt":"现实中，方法与态度不同，结果往往截然不同。新征程上，要继续______智慧和力量，以实干实绩回应人民期盼。看似寻常，实则是长期积累的结果。填入画横线处最恰当的是：","options":["凝聚","汇聚","集中","聚集"],"answer":0,"explanation":"「凝聚」多与「共识、人心、力量」搭配，强调由分散到统一；「聚集」侧重物理集合；「集中」侧重把分散的集中起来。故选A。","__sub":"选词填空"},{"id":"yy-16717","module":"yanyu","diff":2,"exam":"省考","prompt":"现实中，方法与态度不同，结果往往截然不同。各地区各部门要拿出真招实招，______创新根基，确保各项部署落地生根。看似寻常，实则是长期积累的结果。填入画横线处最恰当的是：","options":["筑牢","培植","加深","厚植"],"answer":3,"explanation":"「厚植」指深厚培育，与「优势、底色、根基」搭配；「培植」多用于培育动植物或扶植势力；「加深」与「底色」搭配不当。故选D。","__sub":"选词填空"},{"id":"yy-16719","module":"yanyu","diff":3,"exam":"国考","prompt":"无论时代如何变化，把事情做实做细始终是成事的基础。下一步，将______乡村振兴始终，推动各项工作再上新台阶。这背后考验的正是把握分寸的智慧。填入画横线处最恰当的是：","options":["贯串","贯穿","经过","穿过"],"answer":1,"explanation":"「贯穿」指从头到尾通贯，与「全过程」搭配规范；「穿过」「经过」仅指空间或时间经过，不含通贯始终之义。故选B。","__sub":"选词填空"},{"id":"yy-16721","module":"yanyu","diff":1,"exam":"国考","prompt":"很多事看起来简单，真要做扎实并不容易。当前正值关键时期，______科技成果转化通道刻不容缓，必须抓紧抓实抓出成效。道理虽朴素，真正做到并不容易。填入画横线处最恰当的是：","options":["贯通","打通","畅通","开辟"],"answer":2,"explanation":"「畅通」强调使通畅无阻，与「渠道、通道」搭配；「打通」侧重突破障碍；「贯通」指连接相通；「开辟」指新开路径。故选C。","__sub":"选词填空"},{"id":"yy-16722","module":"yanyu","diff":1,"exam":"国考","prompt":"很多事看起来简单，真要做扎实并不容易。越是任务艰巨，越要______初心，确保方向不偏、力度不减。道理虽朴素，真正做到并不容易。填入画横线处最恰当的是：","options":["磨砺","锻炼","砥砺","锤炼"],"answer":2,"explanation":"「砥砺」本义为磨刀石，引申为磨炼，与「意志」搭配且语体庄重；「磨砺」与之近义但「砥砺」更常用于「砥砺前行、砥砺意志」。故选C。","__sub":"选词填空"},{"id":"yy-16723","module":"yanyu","diff":1,"exam":"国考","prompt":"任何工作要见成效，都离不开科学的方法和踏实的作风。回顾这些年走过的路，______新兴产业始终是我们攻坚克难的重要法宝。唯有如此，才能把好事办好、实事办实。填入画横线处最恰当的是：","options":["培养","培育","孕育","培植"],"answer":1,"explanation":"「培育」与「产业、企业、市场」搭配；「培养」对象为人或能力；「培植」多用于动植物或含贬义；「孕育」强调正在形成。故选B。","__sub":"选词填空"},{"id":"yy-16724","module":"yanyu","diff":2,"exam":"国考","prompt":"现实中，方法与态度不同，结果往往截然不同。各地区各部门要拿出真招实招，______文明乡风，确保各项部署落地生根。看似寻常，实则是长期积累的结果。填入画横线处最恰当的是：","options":["养护","涵养","培养","营造"],"answer":1,"explanation":"「涵养」指蓄积并养护，与「生态、水源」搭配；「培养」对象为人或能力；「营造」多与「氛围、环境」搭配；「养护」不含培育之义。故选B。","__sub":"选词填空"},{"id":"yy-17002","module":"yanyu","diff":1,"exam":"国考","prompt":"很多事看起来简单，真要做扎实并不容易。新征程上，要继续______文明乡风，以实干实绩回应人民期盼。道理虽朴素，真正做到并不容易。填入画横线处最恰当的是：","options":["涵养","培养","营造","养护"],"answer":0,"explanation":"「涵养」指蓄积并养护，与「生态、水源」搭配；「培养」对象为人或能力；「营造」多与「氛围、环境」搭配；「养护」不含培育之义。故选A。","__sub":"选词填空"},{"id":"yy-17003","module":"yanyu","diff":1,"exam":"事业编","prompt":"各级政府要持续______消费市场一池春水，不断增强群众的获得感、幸福感、安全感。填入画横线处最恰当的是：","options":["激活","驱动","启动","唤醒"],"answer":0,"explanation":"「激活」指刺激使之活跃，与「动力、要素」搭配；「唤醒」指使之觉醒；「启动」指开始进行；「驱动」指推动运转。故选A。","__sub":"选词填空"},{"id":"yy-17004","module":"yanyu","diff":2,"exam":"教师编","prompt":"当前正值关键时期，______农村物流最后一公里刻不容缓，必须抓紧抓实抓出成效。填入画横线处最恰当的是：","options":["贯通","打通","畅通","开辟"],"answer":2,"explanation":"「畅通」强调使通畅无阻，与「渠道、通道」搭配；「打通」侧重突破障碍；「贯通」指连接相通；「开辟」指新开路径。故选C。","__sub":"选词填空"},{"id":"yy-17006","module":"yanyu","diff":2,"exam":"事业编","prompt":"很多事看起来简单，真要做扎实并不容易。回顾这些年走过的路，______制度漏洞始终是我们攻坚克难的重要法宝。道理虽朴素，真正做到并不容易。填入画横线处最恰当的是：","options":["弥补","补足","补齐","填补"],"answer":2,"explanation":"「补齐」与「短板」为固定搭配，强调使达到应有水平；「补足」多与「差额」搭配；「填补」多与「空白」搭配；「弥补」多与「损失」搭配。故选C。","__sub":"选词填空"},{"id":"yy-17008","module":"yanyu","diff":2,"exam":"事业编","prompt":"很多事看起来简单，真要做扎实并不容易。实践证明，______新兴产业是推动高质量发展的关键一招。道理虽朴素，真正做到并不容易。填入画横线处最恰当的是：","options":["培植","培育","孕育","培养"],"answer":1,"explanation":"「培育」与「产业、企业、市场」搭配；「培养」对象为人或能力；「培植」多用于动植物或含贬义；「孕育」强调正在形成。故选B。","__sub":"选词填空"},{"id":"yy-17010","module":"yanyu","diff":3,"exam":"国考","prompt":"一个朴素的道理反复被验证：方向对了，努力才不会白费。要坚持问题导向，______群众获得感，切实解决群众急难愁盼问题。这也正是成事的关键所在。填入画横线处最恰当的是：","options":["增强","提高","拔高","提升"],"answer":3,"explanation":"「提升」与「效能、水平」搭配规范；「提高」语义相近但「提升」更书面；「增强」多与「能力、意识」搭配；「拔高」含贬义。故选D。","__sub":"选词填空"},{"id":"yy-17011","module":"yanyu","diff":1,"exam":"国考","prompt":"无论时代如何变化，把事情做实做细始终是成事的基础。面对新形势新任务，必须______人才和资金，牢牢把握发展主动权。这背后考验的正是把握分寸的智慧。填入画横线处最恰当的是：","options":["下潜","下坠","下沉","下探"],"answer":2,"explanation":"「下沉」指治理资源向基层倾斜，是规范表述；「下潜」指潜水，「下探」多指价格或行动试探，「下坠」指物体坠落。故选C。","__sub":"选词填空"},{"id":"yy-17013","module":"yanyu","diff":1,"exam":"省考","prompt":"一个朴素的道理反复被验证：方向对了，努力才不会白费。各地区各部门要拿出真招实招，______社会保障体系，确保各项部署落地生根。这也正是成事的关键所在。填入画横线处最恰当的是：","options":["构建","完善","健全","建立"],"answer":2,"explanation":"「健全」强调使完备无缺，与「体系」搭配规范；「建立」指从无到有，「完善」指补足短板，「构建」侧重搭建框架。故选C。","__sub":"选词填空"},{"id":"yy-17014","module":"yanyu","diff":2,"exam":"教师编","prompt":"各级政府要持续______生态恶化的趋势，不断增强群众的获得感、幸福感、安全感。填入画横线处最恰当的是：","options":["控制","遏止","制止","遏制"],"answer":3,"explanation":"「遏制」强调压制住势头、多与「势头/态势」搭配；「遏止」侧重使之停止，多用于具体行为；「控制」「制止」语义宽泛。故选D。","__sub":"选词填空"},{"id":"yy-17016","module":"yanyu","diff":2,"exam":"教师编","prompt":"任何工作要见成效，都离不开科学的方法和踏实的作风。只有公共服务水平真正______到基层，才能让政策在「最后一公里」落地见效。唯有如此，才能把好事办好、实事办实。填入画横线处最恰当的是：","options":["增强","拔高","提升","提高"],"answer":2,"explanation":"「提升」与「效能、水平」搭配规范；「提高」语义相近但「提升」更书面；「增强」多与「能力、意识」搭配；「拔高」含贬义。故选C。","__sub":"选词填空"},{"id":"yy-17018","module":"yanyu","diff":2,"exam":"国考","prompt":"任何工作要见成效，都离不开科学的方法和踏实的作风。各地区各部门要拿出真招实招，______风险意识，确保各项部署落地生根。唯有如此，才能把好事办好、实事办实。填入画横线处最恰当的是：","options":["增强","深化","强化","加强"],"answer":2,"explanation":"「强化」与「意识、思维」搭配，强调使之更牢固；「增强」语义相近但搭配习惯不同；「加强」为通用动词；「深化」指向深处发展。故选C。","__sub":"选词填空"},{"id":"yy-17023","module":"yanyu","diff":1,"exam":"国考","prompt":"现实中，方法与态度不同，结果往往截然不同。新征程上，要继续______科技成果转化路径，以实干实绩回应人民期盼。看似寻常，实则是长期积累的结果。填入画横线处最恰当的是：","options":["打通","疏通","畅通","开拓"],"answer":2,"explanation":"「畅通」强调使通畅无阻，与「渠道」为固定搭配；「打通」侧重突破障碍；「疏通」多用于管道或疏导矛盾；「开拓」指开辟新领域。故选C。","__sub":"选词填空"},{"id":"yy-17026","module":"yanyu","diff":2,"exam":"省考","prompt":"无论时代如何变化，把事情做实做细始终是成事的基础。回顾这些年走过的路，______安全生产责任始终是我们攻坚克难的重要法宝。这背后考验的正是把握分寸的智慧。填入画横线处最恰当的是：","options":["强化","压紧","落实","压实"],"answer":3,"explanation":"「压实」与「责任」搭配，强调责任层层落实到位；「落实」为通用动词；「压紧」常作「压紧压实」；「强化」不如「压实」精准体现层级传导。故选D。","__sub":"选词填空"},{"id":"yy-17027","module":"yanyu","diff":2,"exam":"国考","prompt":"一个朴素的道理反复被验证：方向对了，努力才不会白费。越是任务艰巨，越要______改革开放各领域，确保方向不偏、力度不减。这也正是成事的关键所在。填入画横线处最恰当的是：","options":["贯串","穿过","贯穿","经过"],"answer":2,"explanation":"「贯穿」指从头到尾通贯，与「全过程」搭配规范；「穿过」「经过」仅指空间或时间经过，不含通贯始终之义。故选C。","__sub":"选词填空"},{"id":"yy-17029","module":"yanyu","diff":3,"exam":"教师编","prompt":"观察身边的事不难发现，成败的分野常常藏在细节里。实践证明，______就业服务体系是推动高质量发展的关键一招。说到底，拼的是态度，比的是功夫。填入画横线处最恰当的是：","options":["健全","构建","完善","建立"],"answer":0,"explanation":"「健全」强调使完备无缺，与「体系」搭配规范；「建立」指从无到有，「完善」指补足短板，「构建」侧重搭建框架。故选A。","__sub":"选词填空"},{"id":"yy-17033","module":"yanyu","diff":1,"exam":"国考","prompt":"现实中，方法与态度不同，结果往往截然不同。下一步，将______生产生活生态，推动各项工作再上新台阶。看似寻常，实则是长期积累的结果。填入画横线处最恰当的是：","options":["统筹","协调","兼顾","统率"],"answer":0,"explanation":"「统筹」指全面筹划、统一安排，与「推进」搭配且强调全局性；「统率」指率领；「兼顾」只强调同时照顾；「协调」侧重配合关系。故选A。","__sub":"选词填空"},{"id":"yy-17034","module":"yanyu","diff":2,"exam":"省考","prompt":"任何工作要见成效，都离不开科学的方法和踏实的作风。新征程上，要继续______执法力量，以实干实绩回应人民期盼。唯有如此，才能把好事办好、实事办实。填入画横线处最恰当的是：","options":["下坠","下沉","下潜","下探"],"answer":1,"explanation":"「下沉」指治理资源向基层倾斜，是规范表述；「下潜」指潜水，「下探」多指价格或行动试探，「下坠」指物体坠落。故选B。","__sub":"选词填空"},{"id":"yy-17035","module":"yanyu","diff":2,"exam":"国考","prompt":"观察身边的事不难发现，成败的分野常常藏在细节里。越是任务艰巨，越要______廉洁底线，确保方向不偏、力度不减。说到底，拼的是态度，比的是功夫。填入画横线处最恰当的是：","options":["筑造","筑牢","构建","夯实"],"answer":1,"explanation":"「筑牢」与「防线」为固定搭配，强调使牢固；「筑造」指建造实体；「构建」侧重搭建体系；「夯实」多与「基础」搭配。故选B。","__sub":"选词填空"},{"id":"yy-17039","module":"yanyu","diff":3,"exam":"国考","prompt":"无论时代如何变化，把事情做实做细始终是成事的基础。实践证明，______底线思维是推动高质量发展的关键一招。这背后考验的正是把握分寸的智慧。填入画横线处最恰当的是：","options":["强化","加强","增强","深化"],"answer":0,"explanation":"「强化」与「意识、思维」搭配，强调使之更牢固；「增强」语义相近但搭配习惯不同；「加强」为通用动词；「深化」指向深处发展。故选A。","__sub":"选词填空"},{"id":"yy-17049","module":"yanyu","diff":3,"exam":"事业编","prompt":"一个朴素的道理反复被验证：方向对了，努力才不会白费。面对新形势新任务，必须______新兴产业，牢牢把握发展主动权。这也正是成事的关键所在。填入画横线处最恰当的是：","options":["孕育","培植","培育","培养"],"answer":2,"explanation":"「培育」与「产业、企业、市场」搭配；「培养」对象为人或能力；「培植」多用于动植物或含贬义；「孕育」强调正在形成。故选C。","__sub":"选词填空"},{"id":"yy-17053","module":"yanyu","diff":1,"exam":"国考","prompt":"任何工作要见成效，都离不开科学的方法和踏实的作风。要坚持问题导向，______政策效应，切实解决群众急难愁盼问题。唯有如此，才能把好事办好、实事办实。填入画横线处最恰当的是：","options":["散发","发挥","释放","爆发"],"answer":2,"explanation":"「释放」与「潜力、红利、活力」搭配；「散发」指分散发出；「发挥」与「作用」搭配；「爆发」指突然发作。故选C。","__sub":"选词填空"},{"id":"yy-17056","module":"yanyu","diff":2,"exam":"教师编","prompt":"很多事看起来简单，真要做扎实并不容易。下一步，将______人才成长环境，推动各项工作再上新台阶。道理虽朴素，真正做到并不容易。填入画横线处最恰当的是：","options":["营造","养护","培养","涵养"],"answer":3,"explanation":"「涵养」指蓄积并养护，与「生态、水源」搭配；「培养」对象为人或能力；「营造」多与「氛围、环境」搭配；「养护」不含培育之义。故选D。","__sub":"选词填空"},{"id":"yy-17057","module":"yanyu","diff":2,"exam":"国考","prompt":"干事创业，思路和坚持缺一不可。当前正值关键时期，______现代化建设全局刻不容缓，必须抓紧抓实抓出成效。其中的道理值得每个人细细体会。填入画横线处最恰当的是：","options":["贯穿","经过","贯串","穿过"],"answer":0,"explanation":"「贯穿」指从头到尾通贯，与「全过程」搭配规范；「穿过」「经过」仅指空间或时间经过，不含通贯始终之义。故选A。","__sub":"选词填空"},{"id":"yy-17058","module":"yanyu","diff":2,"exam":"事业编","prompt":"现实中，方法与态度不同，结果往往截然不同。回顾这些年走过的路，______数字化底座始终是我们攻坚克难的重要法宝。看似寻常，实则是长期积累的结果。填入画横线处最恰当的是：","options":["夯实","巩固","打牢","筑牢"],"answer":0,"explanation":"「夯实」本义为砸实地基，引申为使稳固，与「基础、根基」搭配；「筑牢」与「防线」搭配；「打牢」语体稍口语；「巩固」侧重使已有的更牢固。故选A。","__sub":"选词填空"},{"id":"yy-17060","module":"yanyu","diff":3,"exam":"事业编","prompt":"任何工作要见成效，都离不开科学的方法和踏实的作风。面对新形势新任务，必须______安全屏障，牢牢把握发展主动权。唯有如此，才能把好事办好、实事办实。填入画横线处最恰当的是：","options":["夯实","筑牢","筑造","构建"],"answer":1,"explanation":"「筑牢」与「防线」为固定搭配，强调使牢固；「筑造」指建造实体；「构建」侧重搭建体系；「夯实」多与「基础」搭配。故选B。","__sub":"选词填空"},{"id":"yy-17063","module":"yanyu","diff":1,"exam":"省考","prompt":"干事创业，思路和坚持缺一不可。只有安全底线真正______到基层，才能让政策在「最后一公里」落地见效。其中的道理值得每个人细细体会。填入画横线处最恰当的是：","options":["构建","筑牢","筑造","夯实"],"answer":1,"explanation":"「筑牢」与「防线」为固定搭配，强调使牢固；「筑造」指建造实体；「构建」侧重搭建体系；「夯实」多与「基础」搭配。故选B。","__sub":"选词填空"},{"id":"yy-17064","module":"yanyu","diff":2,"exam":"医疗编","prompt":"干事创业，思路和坚持缺一不可。下一步，将______安全生产责任，推动各项工作再上新台阶。其中的道理值得每个人细细体会。填入画横线处最恰当的是：","options":["落实","强化","压实","压紧"],"answer":2,"explanation":"「压实」与「责任」搭配，强调责任层层落实到位；「落实」为通用动词；「压紧」常作「压紧压实」；「强化」不如「压实」精准体现层级传导。故选C。","__sub":"选词填空"},{"id":"yy-17066","module":"yanyu","diff":2,"exam":"省考","prompt":"很多事看起来简单，真要做扎实并不容易。要在______社会保障网络上下更大功夫，让发展成果更多惠及全体人民。道理虽朴素，真正做到并不容易。填入画横线处最恰当的是：","options":["完善","搭建","构建","健全"],"answer":3,"explanation":"「健全」强调使完备无缺；「完善」指补足短板；「构建」「搭建」侧重从无到有搭建。故选D。","__sub":"选词填空"},{"id":"yy-17067","module":"yanyu","diff":2,"exam":"国考","prompt":"干事创业，思路和坚持缺一不可。实践证明，______发展根基是推动高质量发展的关键一招。看似寻常，实则是长期积累的结果。填入画横线处最恰当的是：","options":["夯实","筑牢","打牢","巩固"],"answer":0,"explanation":"「夯实」本义为砸实地基，引申为使稳固，与「基础、根基」搭配；「筑牢」与「防线」搭配；「打牢」语体稍口语；「巩固」侧重使已有的更牢固。故选A。","__sub":"选词填空"},{"id":"yy-17070","module":"yanyu","diff":3,"exam":"医疗编","prompt":"事物的发展自有其规律，顺应它才能事半功倍。新征程上，要继续______群众需求，以实干实绩回应人民期盼。这样的要求，放在哪里都不过时。填入画横线处最恰当的是：","options":["把握","把玩","把持","把守"],"answer":0,"explanation":"「把握」与抽象事物（特点、规律、机遇）搭配；「把守」指守卫关口，「把持」含贬义指独揽，「把玩」指赏玩物品。故选A。","__sub":"选词填空"},{"id":"yy-17072","module":"yanyu","diff":1,"exam":"事业编","prompt":"事物的发展自有其规律，顺应它才能事半功倍。实践证明，______责任担当是推动高质量发展的关键一招。这样的要求，放在哪里都不过时。填入画横线处最恰当的是：","options":["增强","强化","加强","深化"],"answer":1,"explanation":"「强化」与「意识、思维」搭配，强调使之更牢固；「增强」语义相近但搭配习惯不同；「加强」为通用动词；「深化」指向深处发展。故选B。","__sub":"选词填空"},{"id":"yy-17073","module":"yanyu","diff":1,"exam":"国考","prompt":"现实中，方法与态度不同，结果往往截然不同。当前正值关键时期，______生产生活生态刻不容缓，必须抓紧抓实抓出成效。看似寻常，实则是长期积累的结果。填入画横线处最恰当的是：","options":["统率","兼顾","统筹","协调"],"answer":2,"explanation":"「统筹」指全面筹划、统一安排，与「推进」搭配且强调全局性；「统率」指率领；「兼顾」只强调同时照顾；「协调」侧重配合关系。故选C。","__sub":"选词填空"},{"id":"yy-17075","module":"yanyu","diff":2,"exam":"教师编","prompt":"很多事看起来简单，真要做扎实并不容易。各地区各部门要拿出真招实招，______斗争精神，确保各项部署落地生根。道理虽朴素，真正做到并不容易。填入画横线处最恰当的是：","options":["砥砺","磨砺","锤炼","锻炼"],"answer":0,"explanation":"「砥砺」本义为磨刀石，引申为磨炼，与「意志」搭配且语体庄重；「磨砺」与之近义但「砥砺」更常用于「砥砺前行、砥砺意志」。故选A。","__sub":"选词填空"},{"id":"yy-17076","module":"yanyu","diff":2,"exam":"事业编","prompt":"很多事看起来简单，真要做扎实并不容易。各地区各部门要拿出真招实招，______生态恶化的趋势，确保各项部署落地生根。道理虽朴素，真正做到并不容易。填入画横线处最恰当的是：","options":["制止","遏止","遏制","控制"],"answer":2,"explanation":"「遏制」强调压制住势头、多与「势头/态势」搭配；「遏止」侧重使之停止，多用于具体行为；「控制」「制止」语义宽泛。故选C。","__sub":"选词填空"},{"id":"yy-17077","module":"yanyu","diff":2,"exam":"省考","prompt":"任何工作要见成效，都离不开科学的方法和踏实的作风。越是任务艰巨，越要______优质医疗资源，确保方向不偏、力度不减。唯有如此，才能把好事办好、实事办实。填入画横线处最恰当的是：","options":["下沉","下探","下坠","下潜"],"answer":0,"explanation":"「下沉」指治理资源向基层倾斜，是规范表述；「下潜」指潜水，「下探」多指价格或行动试探，「下坠」指物体坠落。故选A。","__sub":"选词填空"},{"id":"yy-17078","module":"yanyu","diff":2,"exam":"医疗编","prompt":"很多事看起来简单，真要做扎实并不容易。要坚持问题导向，______改革开放各领域，切实解决群众急难愁盼问题。道理虽朴素，真正做到并不容易。填入画横线处最恰当的是：","options":["穿过","贯串","经过","贯穿"],"answer":3,"explanation":"「贯穿」指从头到尾通贯，与「全过程」搭配规范；「穿过」「经过」仅指空间或时间经过，不含通贯始终之义。故选D。","__sub":"选词填空"},{"id":"yy-17082","module":"yanyu","diff":1,"exam":"国考","prompt":"事物的发展自有其规律，顺应它才能事半功倍。要在______属地管理责任上下更大功夫，让发展成果更多惠及全体人民。这样的要求，放在哪里都不过时。填入画横线处最恰当的是：","options":["强化","压紧","落实","压实"],"answer":3,"explanation":"「压实」与「责任」搭配，强调责任层层落实到位；「落实」为通用动词；「压紧」常作「压紧压实」；「强化」不如「压实」精准体现层级传导。故选D。","__sub":"选词填空"},{"id":"yy-17083","module":"yanyu","diff":1,"exam":"教师编","prompt":"无论时代如何变化，把事情做实做细始终是成事的基础。当前正值关键时期，______执法力量刻不容缓，必须抓紧抓实抓出成效。这背后考验的正是把握分寸的智慧。填入画横线处最恰当的是：","options":["下坠","下探","下沉","下潜"],"answer":2,"explanation":"「下沉」指治理资源向基层倾斜，是规范表述；「下潜」指潜水，「下探」多指价格或行动试探，「下坠」指物体坠落。故选C。","__sub":"选词填空"},{"id":"yy-17085","module":"yanyu","diff":2,"exam":"教师编","prompt":"事物的发展自有其规律，顺应它才能事半功倍。越是任务艰巨，越要______创新根基，确保方向不偏、力度不减。这样的要求，放在哪里都不过时。填入画横线处最恰当的是：","options":["厚植","培植","筑牢","加深"],"answer":0,"explanation":"「厚植」指深厚培育，与「优势、底色、根基」搭配；「培植」多用于培育动植物或扶植势力；「加深」与「底色」搭配不当。故选A。","__sub":"选词填空"},{"id":"yy-17086","module":"yanyu","diff":2,"exam":"国考","prompt":"很多事看起来简单，真要做扎实并不容易。要在______沉睡的资源要素上下更大功夫，让发展成果更多惠及全体人民。道理虽朴素，真正做到并不容易。填入画横线处最恰当的是：","options":["激活","驱动","启动","唤醒"],"answer":0,"explanation":"「激活」指刺激使之活跃，与「动力、要素」搭配；「唤醒」指使之觉醒；「启动」指开始进行；「驱动」指推动运转。故选A。","__sub":"选词填空"},{"id":"yy-17087","module":"yanyu","diff":2,"exam":"教师编","prompt":"任何工作要见成效，都离不开科学的方法和踏实的作风。面对新形势新任务，必须______群众增收渠道，牢牢把握发展主动权。唯有如此，才能把好事办好、实事办实。填入画横线处最恰当的是：","options":["开拓","延伸","拓宽","扩大"],"answer":2,"explanation":"「拓宽」与「渠道、门路、视野」搭配；「开拓」指开辟新领域；「扩大」多与「规模、范围」搭配；「延伸」侧重长度延长。故选C。","__sub":"选词填空"},{"id":"yy-17088","module":"yanyu","diff":2,"exam":"教师编","prompt":"无论时代如何变化，把事情做实做细始终是成事的基础。只有发展规律真正______到基层，才能让政策在「最后一公里」落地见效。道理虽朴素，真正做到并不容易。填入画横线处最恰当的是：","options":["把玩","把守","把持","把握"],"answer":3,"explanation":"「把握」与抽象事物（特点、规律、机遇）搭配；「把守」指守卫关口，「把持」含贬义指独揽，「把玩」指赏玩物品。故选D。","__sub":"选词填空"},{"id":"yy-17092","module":"yanyu","diff":1,"exam":"事业编","prompt":"干事创业，思路和坚持缺一不可。只有教育资源配置真正______到基层，才能让政策在「最后一公里」落地见效。其中的道理值得每个人细细体会。填入画横线处最恰当的是：","options":["下潜","下探","下沉","下坠"],"answer":2,"explanation":"「下沉」指治理资源向基层倾斜，是规范表述；「下潜」指潜水，「下探」多指价格或行动试探，「下坠」指物体坠落。故选C。","__sub":"选词填空"},{"id":"yy-17093","module":"yanyu","diff":1,"exam":"省考","prompt":"观察身边的事不难发现，成败的分野常常藏在细节里。面对新形势新任务，必须______数字化底座，牢牢把握发展主动权。说到底，拼的是态度，比的是功夫。填入画横线处最恰当的是：","options":["夯实","巩固","打牢","筑牢"],"answer":0,"explanation":"「夯实」本义为砸实地基，引申为使稳固，与「基础、根基」搭配；「筑牢」与「防线」搭配；「打牢」语体稍口语；「巩固」侧重使已有的更牢固。故选A。","__sub":"选词填空"},{"id":"yy-17099","module":"yanyu","diff":3,"exam":"国考","prompt":"无论时代如何变化，把事情做实做细始终是成事的基础。只有改革任务书真正______到基层，才能让政策在「最后一公里」落地见效。这背后考验的正是把握分寸的智慧。填入画横线处最恰当的是：","options":["锚定","锁定","瞄准","盯住"],"answer":0,"explanation":"「锚定」比喻像锚一样固定住目标，多用于宏观战略语境；「锁定」「瞄准」「盯住」语体偏口语，庄重色彩不足。故选A。","__sub":"选词填空"},{"id":"yy-17101","module":"yanyu","diff":1,"exam":"省考","prompt":"很多事看起来简单，真要做扎实并不容易。越是任务艰巨，越要______城市建设各环节，确保方向不偏、力度不减。道理虽朴素，真正做到并不容易。填入画横线处最恰当的是：","options":["贯串","贯穿","经过","穿过"],"answer":1,"explanation":"「贯穿」指从头到尾通贯，与「全过程」搭配规范；「穿过」「经过」仅指空间或时间经过，不含通贯始终之义。故选B。","__sub":"选词填空"},{"id":"yy-17109","module":"yanyu","diff":3,"exam":"国考","prompt":"观察身边的事不难发现，成败的分野常常藏在细节里。只有生产生活生态真正______到基层，才能让政策在「最后一公里」落地见效。说到底，拼的是态度，比的是功夫。填入画横线处最恰当的是：","options":["协调","统率","兼顾","统筹"],"answer":3,"explanation":"「统筹」指全面筹划、统一安排，与「推进」搭配且强调全局性；「统率」指率领；「兼顾」只强调同时照顾；「协调」侧重配合关系。故选D。","__sub":"选词填空"},{"id":"yy-17113","module":"yanyu","diff":1,"exam":"事业编","prompt":"事物的发展自有其规律，顺应它才能事半功倍。下一步，将______诉求表达渠道，推动各项工作再上新台阶。这样的要求，放在哪里都不过时。填入画横线处最恰当的是：","options":["开拓","打通","畅通","疏通"],"answer":2,"explanation":"「畅通」强调使通畅无阻，与「渠道」为固定搭配；「打通」侧重突破障碍；「疏通」多用于管道或疏导矛盾；「开拓」指开辟新领域。故选C。","__sub":"选词填空"},{"id":"yy-17114","module":"yanyu","diff":2,"exam":"省考","prompt":"任何工作要见成效，都离不开科学的方法和踏实的作风。面对新形势新任务，必须______社会保障网络，牢牢把握发展主动权。唯有如此，才能把好事办好、实事办实。填入画横线处最恰当的是：","options":["完善","搭建","健全","构建"],"answer":2,"explanation":"「健全」强调使完备无缺；「完善」指补足短板；「构建」「搭建」侧重从无到有搭建。故选C。","__sub":"选词填空"},{"id":"yy-17123","module":"yanyu","diff":1,"exam":"省考","prompt":"观察身边的事不难发现，成败的分野常常藏在细节里。只有违规行为的苗头真正______到基层，才能让政策在「最后一公里」落地见效。说到底，拼的是态度，比的是功夫。填入画横线处最恰当的是：","options":["制止","遏止","遏制","控制"],"answer":2,"explanation":"「遏制」强调压制住势头、多与「势头/态势」搭配；「遏止」侧重使之停止，多用于具体行为；「控制」「制止」语义宽泛。故选C。","__sub":"选词填空"},{"id":"yy-17124","module":"yanyu","diff":2,"exam":"省考","prompt":"很多事看起来简单，真要做扎实并不容易。实践证明，______公共服务水平是推动高质量发展的关键一招。道理虽朴素，真正做到并不容易。填入画横线处最恰当的是：","options":["提高","拔高","提升","增强"],"answer":2,"explanation":"「提升」与「效能、水平」搭配规范；「提高」语义相近但「提升」更书面；「增强」多与「能力、意识」搭配；「拔高」含贬义。故选C。","__sub":"选词填空"},{"id":"yy-17129","module":"yanyu","diff":3,"exam":"国考","prompt":"观察身边的事不难发现，成败的分野常常藏在细节里。下一步，将______群众需求，推动各项工作再上新台阶。说到底，拼的是态度，比的是功夫。填入画横线处最恰当的是：","options":["把守","把持","把玩","把握"],"answer":3,"explanation":"「把握」与抽象事物（特点、规律、机遇）搭配；「把守」指守卫关口，「把持」含贬义指独揽，「把玩」指赏玩物品。故选D。","__sub":"选词填空"},{"id":"yy-17130","module":"yanyu","diff":3,"exam":"国考","prompt":"无论时代如何变化，把事情做实做细始终是成事的基础。回顾这些年走过的路，______底线思维始终是我们攻坚克难的重要法宝。这背后考验的正是把握分寸的智慧。填入画横线处最恰当的是：","options":["加强","深化","增强","强化"],"answer":3,"explanation":"「强化」与「意识、思维」搭配，强调使之更牢固；「增强」语义相近但搭配习惯不同；「加强」为通用动词；「深化」指向深处发展。故选D。","__sub":"选词填空"},{"id":"yy-17134","module":"yanyu","diff":2,"exam":"国考","prompt":"一个朴素的道理反复被验证：方向对了，努力才不会白费。下一步，将______乡村振兴，推动各项工作再上新台阶。这也正是成事的关键所在。填入画横线处最恰当的是：","options":["赋能","赋权","助力","加持"],"answer":0,"explanation":"「赋能」指赋予能力，是数字经济语境的规范表述；「赋权」指赋予权力；「加持」为口语化外来词；「助力」语义宽泛。故选A。","__sub":"选词填空"},{"id":"yy-17138","module":"yanyu","diff":2,"exam":"事业编","prompt":"各地区各部门要拿出真招实招，______农村物流最后一公里，确保各项部署落地生根。填入画横线处最恰当的是：","options":["开辟","畅通","贯通","打通"],"answer":1,"explanation":"「畅通」强调使通畅无阻，与「渠道、通道」搭配；「打通」侧重突破障碍；「贯通」指连接相通；「开辟」指新开路径。故选B。","__sub":"选词填空"},{"id":"yy-17141","module":"yanyu","diff":1,"exam":"教师编","prompt":"很多事看起来简单，真要做扎实并不容易。下一步，将______安全屏障，推动各项工作再上新台阶。道理虽朴素，真正做到并不容易。填入画横线处最恰当的是：","options":["筑牢","构建","夯实","筑造"],"answer":0,"explanation":"「筑牢」与「防线」为固定搭配，强调使牢固；「筑造」指建造实体；「构建」侧重搭建体系；「夯实」多与「基础」搭配。故选A。","__sub":"选词填空"},{"id":"yy-17144","module":"yanyu","diff":2,"exam":"国考","prompt":"很多事看起来简单，真要做扎实并不容易。新征程上，要继续______乡村振兴，以实干实绩回应人民期盼。道理虽朴素，真正做到并不容易。填入画横线处最恰当的是：","options":["赋能","助力","赋权","加持"],"answer":0,"explanation":"「赋能」指赋予能力，是数字经济语境的规范表述；「赋权」指赋予权力；「加持」为口语化外来词；「助力」语义宽泛。故选A。","__sub":"选词填空"},{"id":"yy-17145","module":"yanyu","diff":2,"exam":"省考","prompt":"干事创业，思路和坚持缺一不可。要坚持问题导向，______区域协调发展的新格局，切实解决群众急难愁盼问题。其中的道理值得每个人细细体会。填入画横线处最恰当的是：","options":["擘画","勾画","规划","描绘"],"answer":0,"explanation":"「擘画」指筹划布置，多用于宏观蓝图，书面色彩浓；「描绘」「勾画」偏具体画面；「规划」语体色彩不足。故选A。","__sub":"选词填空"},{"id":"yy-17153","module":"yanyu","diff":1,"exam":"省考","prompt":"事物的发展自有其规律，顺应它才能事半功倍。下一步，将______矛盾调解体系，推动各项工作再上新台阶。这样的要求，放在哪里都不过时。填入画横线处最恰当的是：","options":["构建","完善","健全","搭建"],"answer":2,"explanation":"「健全」强调使完备无缺；「完善」指补足短板；「构建」「搭建」侧重从无到有搭建。故选C。","__sub":"选词填空"},{"id":"yy-17154","module":"yanyu","diff":2,"exam":"省考","prompt":"很多事看起来简单，真要做扎实并不容易。要坚持问题导向，______建设农业强国的目标，切实解决群众急难愁盼问题。道理虽朴素，真正做到并不容易。填入画横线处最恰当的是：","options":["瞄准","锁定","锚定","盯住"],"answer":2,"explanation":"「锚定」比喻像锚一样固定住目标，多用于宏观战略语境；「锁定」「瞄准」「盯住」语体偏口语，庄重色彩不足。故选C。","__sub":"选词填空"},{"id":"yy-17155","module":"yanyu","diff":2,"exam":"省考","prompt":"现实中，方法与态度不同，结果往往截然不同。当前正值关键时期，______人才成长环境刻不容缓，必须抓紧抓实抓出成效。看似寻常，实则是长期积累的结果。填入画横线处最恰当的是：","options":["营造","培养","涵养","养护"],"answer":2,"explanation":"「涵养」指蓄积并养护，与「生态、水源」搭配；「培养」对象为人或能力；「营造」多与「氛围、环境」搭配；「养护」不含培育之义。故选C。","__sub":"选词填空"},{"id":"yy-17156","module":"yanyu","diff":2,"exam":"教师编","prompt":"观察身边的事不难发现，成败的分野常常藏在细节里。当前正值关键时期，______法治体系刻不容缓，必须抓紧抓实抓出成效。说到底，拼的是态度，比的是功夫。填入画横线处最恰当的是：","options":["建立","完善","健全","构建"],"answer":2,"explanation":"「健全」强调使完备无缺，与「体系」搭配规范；「建立」指从无到有，「完善」指补足短板，「构建」侧重搭建框架。故选C。","__sub":"选词填空"},{"id":"yy-17157","module":"yanyu","diff":2,"exam":"国考","prompt":"观察身边的事不难发现，成败的分野常常藏在细节里。当前正值关键时期，______基础设施弱项刻不容缓，必须抓紧抓实抓出成效。说到底，拼的是态度，比的是功夫。填入画横线处最恰当的是：","options":["补齐","补足","弥补","填补"],"answer":0,"explanation":"「补齐」与「短板」为固定搭配，强调使达到应有水平；「补足」多与「差额」搭配；「填补」多与「空白」搭配；「弥补」多与「损失」搭配。故选A。","__sub":"选词填空"},{"id":"yy-17158","module":"yanyu","diff":2,"exam":"教师编","prompt":"现实中，方法与态度不同，结果往往截然不同。各级政府要持续______制度漏洞，不断增强群众的获得感、幸福感、安全感。看似寻常，实则是长期积累的结果。填入画横线处最恰当的是：","options":["填补","补齐","弥补","补足"],"answer":1,"explanation":"「补齐」与「短板」为固定搭配，强调使达到应有水平；「补足」多与「差额」搭配；「填补」多与「空白」搭配；「弥补」多与「损失」搭配。故选B。","__sub":"选词填空"},{"id":"yy-17162","module":"yanyu","diff":1,"exam":"教师编","prompt":"很多事看起来简单，真要做扎实并不容易。越是任务艰巨，越要______经济社会发展全过程，确保方向不偏、力度不减。道理虽朴素，真正做到并不容易。填入画横线处最恰当的是：","options":["贯串","穿过","贯穿","经过"],"answer":2,"explanation":"「贯穿」指从头到尾通贯，与「全过程」搭配规范；「穿过」「经过」仅指空间或时间经过，不含通贯始终之义。故选C。","__sub":"选词填空"},{"id":"yy-17164","module":"yanyu","diff":2,"exam":"国考","prompt":"事物的发展自有其规律，顺应它才能事半功倍。当前正值关键时期，______东西部协作刻不容缓，必须抓紧抓实抓出成效。这样的要求，放在哪里都不过时。填入画横线处最恰当的是：","options":["深化","加强","推进","深入"],"answer":0,"explanation":"「深化」指向更深阶段发展，与「改革」为固定搭配；「深入」多作形容词或「深入调查」；「加强」「推进」语义宽泛。故选A。","__sub":"选词填空"},{"id":"yy-17166","module":"yanyu","diff":2,"exam":"事业编","prompt":"现实中，方法与态度不同，结果往往截然不同。回顾这些年走过的路，______科技成果转化路径始终是我们攻坚克难的重要法宝。看似寻常，实则是长期积累的结果。填入画横线处最恰当的是：","options":["畅通","开拓","疏通","打通"],"answer":0,"explanation":"「畅通」强调使通畅无阻，与「渠道」为固定搭配；「打通」侧重突破障碍；「疏通」多用于管道或疏导矛盾；「开拓」指开辟新领域。故选A。","__sub":"选词填空"},{"id":"yy-17167","module":"yanyu","diff":2,"exam":"医疗编","prompt":"事物的发展自有其规律，顺应它才能事半功倍。要坚持问题导向，______智慧和力量，切实解决群众急难愁盼问题。这样的要求，放在哪里都不过时。填入画横线处最恰当的是：","options":["凝聚","汇聚","聚集","集中"],"answer":0,"explanation":"「凝聚」多与「共识、人心、力量」搭配，强调由分散到统一；「聚集」侧重物理集合；「集中」侧重把分散的集中起来。故选A。","__sub":"选词填空"},{"id":"yy-17170","module":"yanyu","diff":3,"exam":"省考","prompt":"事物的发展自有其规律，顺应它才能事半功倍。下一步，将______公共卫生体系短板，推动各项工作再上新台阶。这样的要求，放在哪里都不过时。填入画横线处最恰当的是：","options":["补足","填补","弥补","补齐"],"answer":3,"explanation":"「补齐」与「短板」为固定搭配，强调使达到应有水平；「补足」多与「差额」搭配；「填补」多与「空白」搭配；「弥补」多与「损失」搭配。故选D。","__sub":"选词填空"},{"id":"yy-17175","module":"yanyu","diff":2,"exam":"事业编","prompt":"现实中，方法与态度不同，结果往往截然不同。面对新形势新任务，必须______政策效应，牢牢把握发展主动权。看似寻常，实则是长期积累的结果。填入画横线处最恰当的是：","options":["爆发","发挥","释放","散发"],"answer":2,"explanation":"「释放」与「潜力、红利、活力」搭配；「散发」指分散发出；「发挥」与「作用」搭配；「爆发」指突然发作。故选C。","__sub":"选词填空"},{"id":"yy-17177","module":"yanyu","diff":2,"exam":"国考","prompt":"任何工作要见成效，都离不开科学的方法和踏实的作风。各级政府要持续______底线思维，不断增强群众的获得感、幸福感、安全感。唯有如此，才能把好事办好、实事办实。填入画横线处最恰当的是：","options":["强化","增强","加强","深化"],"answer":0,"explanation":"「强化」与「意识、思维」搭配，强调使之更牢固；「增强」语义相近但搭配习惯不同；「加强」为通用动词；「深化」指向深处发展。故选A。","__sub":"选词填空"},{"id":"yy-17179","module":"yanyu","diff":3,"exam":"国考","prompt":"现实中，方法与态度不同，结果往往截然不同。面对新形势新任务，必须______耕地保护红线，牢牢把握发展主动权。看似寻常，实则是长期积累的结果。填入画横线处最恰当的是：","options":["守牢","防住","守住","把牢"],"answer":0,"explanation":"「守牢」与「底线」搭配，强调牢牢守住；「守住」程度稍弱；「把牢」多与「关口」搭配；「防住」为口语。故选A。","__sub":"选词填空"},{"id":"yy-17180","module":"yanyu","diff":3,"exam":"国考","prompt":"一个朴素的道理反复被验证：方向对了，努力才不会白费。要在______供给侧结构性改革上下更大功夫，让发展成果更多惠及全体人民。这也正是成事的关键所在。填入画横线处最恰当的是：","options":["加强","推进","深化","深入"],"answer":2,"explanation":"「深化」指向更深阶段发展，与「改革」为固定搭配；「深入」多作形容词或「深入调查」；「加强」「推进」语义宽泛。故选C。","__sub":"选词填空"},{"id":"yy-17182","module":"yanyu","diff":1,"exam":"国考","prompt":"只有新时代发展的宏伟蓝图真正______到基层，才能让政策在「最后一公里」落地见效。填入画横线处最恰当的是：","options":["描绘","擘画","勾画","规划"],"answer":1,"explanation":"「擘画」指筹划布置，多用于宏观蓝图，书面色彩浓；「描绘」「勾画」偏具体画面；「规划」语体色彩不足。故选B。","__sub":"选词填空"},{"id":"yy-17183","module":"yanyu","diff":1,"exam":"省考","prompt":"一个朴素的道理反复被验证：方向对了，努力才不会白费。各地区各部门要拿出真招实招，______公共服务水平，确保各项部署落地生根。这也正是成事的关键所在。填入画横线处最恰当的是：","options":["增强","提升","拔高","提高"],"answer":1,"explanation":"「提升」与「效能、水平」搭配规范；「提高」语义相近但「提升」更书面；「增强」多与「能力、意识」搭配；「拔高」含贬义。故选B。","__sub":"选词填空"},{"id":"yy-17188","module":"yanyu","diff":2,"exam":"省考","prompt":"无论时代如何变化，把事情做实做细始终是成事的基础。各级政府要持续______就业促进机制，不断增强群众的获得感、幸福感、安全感。这背后考验的正是把握分寸的智慧。填入画横线处最恰当的是：","options":["健全","搭建","构建","完善"],"answer":0,"explanation":"「健全」强调使完备无缺；「完善」指补足短板；「构建」「搭建」侧重从无到有搭建。故选A。","__sub":"选词填空"},{"id":"yy-17194","module":"yanyu","diff":2,"exam":"国考","prompt":"现实中，方法与态度不同，结果往往截然不同。要坚持问题导向，______现代化建设的宏伟篇章，切实解决群众急难愁盼问题。看似寻常，实则是长期积累的结果。填入画横线处最恰当的是：","options":["规划","擘画","描绘","勾画"],"answer":1,"explanation":"「擘画」指筹划布置，多用于宏观蓝图，书面色彩浓；「描绘」「勾画」偏具体画面；「规划」语体色彩不足。故选B。","__sub":"选词填空"},{"id":"yy-17200","module":"yanyu","diff":3,"exam":"省考","prompt":"当前正值关键时期，______高质量发展的生态底色刻不容缓，必须抓紧抓实抓出成效。填入画横线处最恰当的是：","options":["加深","筑牢","厚植","培植"],"answer":2,"explanation":"「厚植」指深厚培育，与「优势、底色、根基」搭配；「培植」多用于培育动植物或扶植势力；「加深」与「底色」搭配不当。故选C。","__sub":"选词填空"},{"id":"yy-17207","module":"yanyu","diff":2,"exam":"事业编","prompt":"任何工作要见成效，都离不开科学的方法和踏实的作风。越是任务艰巨，越要______各方合力，确保方向不偏、力度不减。唯有如此，才能把好事办好、实事办实。填入画横线处最恰当的是：","options":["凝聚","集中","汇聚","聚集"],"answer":0,"explanation":"「凝聚」多与「共识、人心、力量」搭配，强调由分散到统一；「聚集」侧重物理集合；「集中」侧重把分散的集中起来。故选A。","__sub":"选词填空"},{"id":"yy-17208","module":"yanyu","diff":2,"exam":"国考","prompt":"一个朴素的道理反复被验证：方向对了，努力才不会白费。要坚持问题导向，______制造业高质量发展，切实解决群众急难愁盼问题。这也正是成事的关键所在。填入画横线处最恰当的是：","options":["赋能","助力","赋权","加持"],"answer":0,"explanation":"「赋能」指赋予能力，是数字经济语境的规范表述；「赋权」指赋予权力；「加持」为口语化外来词；「助力」语义宽泛。故选A。","__sub":"选词填空"},{"id":"yy-17209","module":"yanyu","diff":3,"exam":"省考","prompt":"一个朴素的道理反复被验证：方向对了，努力才不会白费。各级政府要持续______政策效应，不断增强群众的获得感、幸福感、安全感。这也正是成事的关键所在。填入画横线处最恰当的是：","options":["发挥","散发","释放","爆发"],"answer":2,"explanation":"「释放」与「潜力、红利、活力」搭配；「散发」指分散发出；「发挥」与「作用」搭配；「爆发」指突然发作。故选C。","__sub":"选词填空"},{"id":"yy-17211","module":"yanyu","diff":1,"exam":"省考","prompt":"现实中，方法与态度不同，结果往往截然不同。要坚持问题导向，______经济社会发展全过程，切实解决群众急难愁盼问题。看似寻常，实则是长期积累的结果。填入画横线处最恰当的是：","options":["贯穿","经过","贯串","穿过"],"answer":0,"explanation":"「贯穿」指从头到尾通贯，与「全过程」搭配规范；「穿过」「经过」仅指空间或时间经过，不含通贯始终之义。故选A。","__sub":"选词填空"},{"id":"yy-17213","module":"yanyu","diff":1,"exam":"省考","prompt":"很多事看起来简单，真要做扎实并不容易。要在______就业促进机制上下更大功夫，让发展成果更多惠及全体人民。道理虽朴素，真正做到并不容易。填入画横线处最恰当的是：","options":["构建","完善","搭建","健全"],"answer":3,"explanation":"「健全」强调使完备无缺；「完善」指补足短板；「构建」「搭建」侧重从无到有搭建。故选D。","__sub":"选词填空"},{"id":"yy-17215","module":"yanyu","diff":2,"exam":"国考","prompt":"现实中，方法与态度不同，结果往往截然不同。只有政策效应真正______到基层，才能让政策在「最后一公里」落地见效。看似寻常，实则是长期积累的结果。填入画横线处最恰当的是：","options":["爆发","释放","发挥","散发"],"answer":1,"explanation":"「释放」与「潜力、红利、活力」搭配；「散发」指分散发出；「发挥」与「作用」搭配；「爆发」指突然发作。故选B。","__sub":"选词填空"},{"id":"yy-17219","module":"yanyu","diff":3,"exam":"医疗编","prompt":"现实中，方法与态度不同，结果往往截然不同。新征程上，要继续______现代化建设全局，以实干实绩回应人民期盼。看似寻常，实则是长期积累的结果。填入画横线处最恰当的是：","options":["贯串","经过","贯穿","穿过"],"answer":2,"explanation":"「贯穿」指从头到尾通贯，与「全过程」搭配规范；「穿过」「经过」仅指空间或时间经过，不含通贯始终之义。故选C。","__sub":"选词填空"},{"id":"yy-17221","module":"yanyu","diff":1,"exam":"国考","prompt":"无论时代如何变化，把事情做实做细始终是成事的基础。新征程上，要继续______新兴产业，以实干实绩回应人民期盼。这背后考验的正是把握分寸的智慧。填入画横线处最恰当的是：","options":["培育","孕育","培植","培养"],"answer":0,"explanation":"「培育」与「产业、企业、市场」搭配；「培养」对象为人或能力；「培植」多用于动植物或含贬义；「孕育」强调正在形成。故选A。","__sub":"选词填空"},{"id":"yy-17502","module":"yanyu","diff":1,"exam":"事业编","prompt":"现实中，方法与态度不同，结果往往截然不同。各级政府要持续______矛盾调解体系，不断增强群众的获得感、幸福感、安全感。看似寻常，实则是长期积累的结果。填入画横线处最恰当的是：","options":["构建","搭建","健全","完善"],"answer":2,"explanation":"「健全」强调使完备无缺；「完善」指补足短板；「构建」「搭建」侧重从无到有搭建。故选C。","__sub":"选词填空"},{"id":"yy-17503","module":"yanyu","diff":1,"exam":"省考","prompt":"任何工作要见成效，都离不开科学的方法和踏实的作风。实践证明，______共识是推动高质量发展的关键一招。唯有如此，才能把好事办好、实事办实。填入画横线处最恰当的是：","options":["聚集","凝聚","汇聚","集中"],"answer":1,"explanation":"「凝聚」多与「共识、人心、力量」搭配，强调由分散到统一；「聚集」侧重物理集合；「集中」侧重把分散的集中起来。故选B。","__sub":"选词填空"},{"id":"yy-17506","module":"yanyu","diff":2,"exam":"省考","prompt":"现实中，方法与态度不同，结果往往截然不同。要坚持问题导向，______腐败蔓延的态势，切实解决群众急难愁盼问题。看似寻常，实则是长期积累的结果。填入画横线处最恰当的是：","options":["控制","遏止","遏制","制止"],"answer":2,"explanation":"「遏制」强调压制住势头、多与「势头/态势」搭配；「遏止」侧重使之停止，多用于具体行为；「控制」「制止」语义宽泛。故选C。","__sub":"选词填空"},{"id":"yy-17507","module":"yanyu","diff":2,"exam":"医疗编","prompt":"干事创业，思路和坚持缺一不可。面对新形势新任务，必须______东西部协作，牢牢把握发展主动权。其中的道理值得每个人细细体会。填入画横线处最恰当的是：","options":["推进","深化","深入","加强"],"answer":1,"explanation":"「深化」指向更深阶段发展，与「改革」为固定搭配；「深入」多作形容词或「深入调查」；「加强」「推进」语义宽泛。故选B。","__sub":"选词填空"},{"id":"yy-17509","module":"yanyu","diff":3,"exam":"省考","prompt":"无论时代如何变化，把事情做实做细始终是成事的基础。面对新形势新任务，必须______企业主体责任，牢牢把握发展主动权。这背后考验的正是把握分寸的智慧。填入画横线处最恰当的是：","options":["落实","压实","压紧","强化"],"answer":1,"explanation":"「压实」与「责任」搭配，强调责任层层落实到位；「落实」为通用动词；「压紧」常作「压紧压实」；「强化」不如「压实」精准体现层级传导。故选B。","__sub":"选词填空"},{"id":"yy-17510","module":"yanyu","diff":3,"exam":"国考","prompt":"任何工作要见成效，都离不开科学的方法和踏实的作风。各级政府要持续______发展优势，不断增强群众的获得感、幸福感、安全感。唯有如此，才能把好事办好、实事办实。填入画横线处最恰当的是：","options":["筑牢","厚植","加深","培植"],"answer":1,"explanation":"「厚植」指深厚培育，与「优势、底色、根基」搭配；「培植」多用于培育动植物或扶植势力；「加深」与「底色」搭配不当。故选B。","__sub":"选词填空"},{"id":"yy-17513","module":"yanyu","diff":1,"exam":"省考","prompt":"很多事看起来简单，真要做扎实并不容易。当前正值关键时期，______实体经济根基刻不容缓，必须抓紧抓实抓出成效。道理虽朴素，真正做到并不容易。填入画横线处最恰当的是：","options":["厚植","加深","筑牢","培植"],"answer":0,"explanation":"「厚植」指深厚培育，与「优势、底色、根基」搭配；「培植」多用于培育动植物或扶植势力；「加深」与「底色」搭配不当。故选A。","__sub":"选词填空"},{"id":"yy-17514","module":"yanyu","diff":2,"exam":"教师编","prompt":"无论时代如何变化，把事情做实做细始终是成事的基础。越是任务艰巨，越要______中小企业发展，确保方向不偏、力度不减。这背后考验的正是把握分寸的智慧。填入画横线处最恰当的是：","options":["助力","赋权","赋能","加持"],"answer":2,"explanation":"「赋能」指赋予能力，是数字经济语境的规范表述；「赋权」指赋予权力；「加持」为口语化外来词；「助力」语义宽泛。故选C。","__sub":"选词填空"},{"id":"yy-17515","module":"yanyu","diff":2,"exam":"国考","prompt":"观察身边的事不难发现，成败的分野常常藏在细节里。回顾这些年走过的路，______民生短板始终是我们攻坚克难的重要法宝。说到底，拼的是态度，比的是功夫。填入画横线处最恰当的是：","options":["填补","弥补","补足","补齐"],"answer":3,"explanation":"「补齐」与「短板」为固定搭配，强调使达到应有水平；「补足」多与「差额」搭配；「填补」多与「空白」搭配；「弥补」多与「损失」搭配。故选D。","__sub":"选词填空"},{"id":"yy-17518","module":"yanyu","diff":2,"exam":"省考","prompt":"很多事看起来简单，真要做扎实并不容易。要在______数字化底座上下更大功夫，让发展成果更多惠及全体人民。道理虽朴素，真正做到并不容易。填入画横线处最恰当的是：","options":["夯实","巩固","筑牢","打牢"],"answer":0,"explanation":"「夯实」本义为砸实地基，引申为使稳固，与「基础、根基」搭配；「筑牢」与「防线」搭配；「打牢」语体稍口语；「巩固」侧重使已有的更牢固。故选A。","__sub":"选词填空"},{"id":"yy-17520","module":"yanyu","diff":3,"exam":"事业编","prompt":"很多事看起来简单，真要做扎实并不容易。越是任务艰巨，越要______风险意识，确保方向不偏、力度不减。道理虽朴素，真正做到并不容易。填入画横线处最恰当的是：","options":["深化","加强","增强","强化"],"answer":3,"explanation":"「强化」与「意识、思维」搭配，强调使之更牢固；「增强」语义相近但搭配习惯不同；「加强」为通用动词；「深化」指向深处发展。故选D。","__sub":"选词填空"},{"id":"yy-17522","module":"yanyu","diff":1,"exam":"省考","prompt":"现实中，方法与态度不同，结果往往截然不同。要在______放管服改革上下更大功夫，让发展成果更多惠及全体人民。看似寻常，实则是长期积累的结果。填入画横线处最恰当的是：","options":["加强","推进","深入","深化"],"answer":3,"explanation":"「深化」指向更深阶段发展，与「改革」为固定搭配；「深入」多作形容词或「深入调查」；「加强」「推进」语义宽泛。故选D。","__sub":"选词填空"},{"id":"yy-17524","module":"yanyu","diff":2,"exam":"省考","prompt":"干事创业，思路和坚持缺一不可。实践证明，______现代化建设的宏伟篇章是推动高质量发展的关键一招。其中的道理值得每个人细细体会。填入画横线处最恰当的是：","options":["描绘","擘画","规划","勾画"],"answer":1,"explanation":"「擘画」指筹划布置，多用于宏观蓝图，书面色彩浓；「描绘」「勾画」偏具体画面；「规划」语体色彩不足。故选B。","__sub":"选词填空"},{"id":"yy-17535","module":"yanyu","diff":2,"exam":"国考","prompt":"干事创业，思路和坚持缺一不可。实践证明，______建设农业强国的目标是推动高质量发展的关键一招。其中的道理值得每个人细细体会。填入画横线处最恰当的是：","options":["瞄准","盯住","锁定","锚定"],"answer":3,"explanation":"「锚定」比喻像锚一样固定住目标，多用于宏观战略语境；「锁定」「瞄准」「盯住」语体偏口语，庄重色彩不足。故选D。","__sub":"选词填空"},{"id":"yy-17536","module":"yanyu","diff":2,"exam":"省考","prompt":"很多事看起来简单，真要做扎实并不容易。实践证明，______经营主体信心是推动高质量发展的关键一招。道理虽朴素，真正做到并不容易。填入画横线处最恰当的是：","options":["调动","引发","点燃","激发"],"answer":3,"explanation":"「激发」与「活力、热情、潜能」为固定搭配；「引发」多与「关注、争议」搭配；「点燃」为比喻用法；「调动」多与「积极性」搭配。故选D。","__sub":"选词填空"},{"id":"yy-17538","module":"yanyu","diff":2,"exam":"省考","prompt":"现实中，方法与态度不同，结果往往截然不同。新征程上，要继续______不发生系统性风险的底线，以实干实绩回应人民期盼。看似寻常，实则是长期积累的结果。填入画横线处最恰当的是：","options":["守牢","守住","把牢","防住"],"answer":0,"explanation":"「守牢」与「底线」搭配，强调牢牢守住；「守住」程度稍弱；「把牢」多与「关口」搭配；「防住」为口语。故选A。","__sub":"选词填空"},{"id":"yy-17539","module":"yanyu","diff":3,"exam":"国考","prompt":"现实中，方法与态度不同，结果往往截然不同。面对新形势新任务，必须______发展根基，牢牢把握发展主动权。看似寻常，实则是长期积累的结果。填入画横线处最恰当的是：","options":["夯实","打牢","筑牢","巩固"],"answer":0,"explanation":"「夯实」本义为砸实地基，引申为使稳固，与「基础、根基」搭配；「筑牢」与「防线」搭配；「打牢」语体稍口语；「巩固」侧重使已有的更牢固。故选A。","__sub":"选词填空"},{"id":"yy-17540","module":"yanyu","diff":3,"exam":"国考","prompt":"事物的发展自有其规律，顺应它才能事半功倍。当前正值关键时期，______耕地保护红线刻不容缓，必须抓紧抓实抓出成效。这样的要求，放在哪里都不过时。填入画横线处最恰当的是：","options":["守住","把牢","守牢","防住"],"answer":2,"explanation":"「守牢」与「底线」搭配，强调牢牢守住；「守住」程度稍弱；「把牢」多与「关口」搭配；「防住」为口语。故选C。","__sub":"选词填空"},{"id":"yy-17545","module":"yanyu","diff":2,"exam":"医疗编","prompt":"事物的发展自有其规律，顺应它才能事半功倍。各级政府要持续______安全屏障，不断增强群众的获得感、幸福感、安全感。这样的要求，放在哪里都不过时。填入画横线处最恰当的是：","options":["构建","筑造","筑牢","夯实"],"answer":2,"explanation":"「筑牢」与「防线」为固定搭配，强调使牢固；「筑造」指建造实体；「构建」侧重搭建体系；「夯实」多与「基础」搭配。故选C。","__sub":"选词填空"},{"id":"yy-17547","module":"yanyu","diff":2,"exam":"国考","prompt":"各级政府要持续______科技成果转化路径，不断增强群众的获得感、幸福感、安全感。填入画横线处最恰当的是：","options":["打通","疏通","畅通","开拓"],"answer":2,"explanation":"「畅通」强调使通畅无阻，与「渠道」为固定搭配；「打通」侧重突破障碍；「疏通」多用于管道或疏导矛盾；「开拓」指开辟新领域。故选C。","__sub":"选词填空"},{"id":"yy-17548","module":"yanyu","diff":2,"exam":"事业编","prompt":"事物的发展自有其规律，顺应它才能事半功倍。实践证明，______乡村振兴始终是推动高质量发展的关键一招。这样的要求，放在哪里都不过时。填入画横线处最恰当的是：","options":["贯穿","贯串","经过","穿过"],"answer":0,"explanation":"「贯穿」指从头到尾通贯，与「全过程」搭配规范；「穿过」「经过」仅指空间或时间经过，不含通贯始终之义。故选A。","__sub":"选词填空"},{"id":"yy-17549","module":"yanyu","diff":3,"exam":"教师编","prompt":"干事创业，思路和坚持缺一不可。面对新形势新任务，必须______发展规律，牢牢把握发展主动权。其中的道理值得每个人细细体会。填入画横线处最恰当的是：","options":["把玩","把守","把握","把持"],"answer":2,"explanation":"「把握」与抽象事物（特点、规律、机遇）搭配；「把守」指守卫关口，「把持」含贬义指独揽，「把玩」指赏玩物品。故选C。","__sub":"选词填空"},{"id":"yy-17552","module":"yanyu","diff":1,"exam":"国考","prompt":"任何工作要见成效，都离不开科学的方法和踏实的作风。当前正值关键时期，______市场变化刻不容缓，必须抓紧抓实抓出成效。唯有如此，才能把好事办好、实事办实。填入画横线处最恰当的是：","options":["把守","把握","把持","把玩"],"answer":1,"explanation":"「把握」与抽象事物（特点、规律、机遇）搭配；「把守」指守卫关口，「把持」含贬义指独揽，「把玩」指赏玩物品。故选B。","__sub":"选词填空"},{"id":"yy-17554","module":"yanyu","diff":2,"exam":"事业编","prompt":"现实中，方法与态度不同，结果往往截然不同。越是任务艰巨，越要______市场变化，确保方向不偏、力度不减。看似寻常，实则是长期积累的结果。填入画横线处最恰当的是：","options":["把握","把持","把守","把玩"],"answer":0,"explanation":"「把握」与抽象事物（特点、规律、机遇）搭配；「把守」指守卫关口，「把持」含贬义指独揽，「把玩」指赏玩物品。故选A。","__sub":"选词填空"},{"id":"yy-17558","module":"yanyu","diff":2,"exam":"省考","prompt":"很多事看起来简单，真要做扎实并不容易。当前正值关键时期，______生态恶化的趋势刻不容缓，必须抓紧抓实抓出成效。道理虽朴素，真正做到并不容易。填入画横线处最恰当的是：","options":["遏止","控制","制止","遏制"],"answer":3,"explanation":"「遏制」强调压制住势头、多与「势头/态势」搭配；「遏止」侧重使之停止，多用于具体行为；「控制」「制止」语义宽泛。故选D。","__sub":"选词填空"},{"id":"yy-17561","module":"yanyu","diff":1,"exam":"国考","prompt":"任何工作要见成效，都离不开科学的方法和踏实的作风。要在______现代化建设全局上下更大功夫，让发展成果更多惠及全体人民。唯有如此，才能把好事办好、实事办实。填入画横线处最恰当的是：","options":["贯串","经过","穿过","贯穿"],"answer":3,"explanation":"「贯穿」指从头到尾通贯，与「全过程」搭配规范；「穿过」「经过」仅指空间或时间经过，不含通贯始终之义。故选D。","__sub":"选词填空"},{"id":"yy-17566","module":"yanyu","diff":2,"exam":"医疗编","prompt":"无论时代如何变化，把事情做实做细始终是成事的基础。新征程上，要继续______政企沟通机制，以实干实绩回应人民期盼。这背后考验的正是把握分寸的智慧。填入画横线处最恰当的是：","options":["开拓","疏通","畅通","打通"],"answer":2,"explanation":"「畅通」强调使通畅无阻，与「渠道」为固定搭配；「打通」侧重突破障碍；「疏通」多用于管道或疏导矛盾；「开拓」指开辟新领域。故选C。","__sub":"选词填空"},{"id":"yy-17570","module":"yanyu","diff":3,"exam":"教师编","prompt":"一个朴素的道理反复被验证：方向对了，努力才不会白费。下一步，将______民意反映渠道，推动各项工作再上新台阶。这也正是成事的关键所在。填入画横线处最恰当的是：","options":["拓宽","延伸","扩大","开拓"],"answer":0,"explanation":"「拓宽」与「渠道、门路、视野」搭配；「开拓」指开辟新领域；「扩大」多与「规模、范围」搭配；「延伸」侧重长度延长。故选A。","__sub":"选词填空"},{"id":"yy-17572","module":"yanyu","diff":1,"exam":"省考","prompt":"一个朴素的道理反复被验证：方向对了，努力才不会白费。只有东西部协作真正______到基层，才能让政策在「最后一公里」落地见效。这也正是成事的关键所在。填入画横线处最恰当的是：","options":["加强","深入","推进","深化"],"answer":3,"explanation":"「深化」指向更深阶段发展，与「改革」为固定搭配；「深入」多作形容词或「深入调查」；「加强」「推进」语义宽泛。故选D。","__sub":"选词填空"},{"id":"yy-17575","module":"yanyu","diff":2,"exam":"国考","prompt":"一个朴素的道理反复被验证：方向对了，努力才不会白费。要坚持问题导向，______消费潜力，切实解决群众急难愁盼问题。这也正是成事的关键所在。填入画横线处最恰当的是：","options":["散发","发挥","释放","爆发"],"answer":2,"explanation":"「释放」与「潜力、红利、活力」搭配；「散发」指分散发出；「发挥」与「作用」搭配；「爆发」指突然发作。故选C。","__sub":"选词填空"},{"id":"yy-17576","module":"yanyu","diff":2,"exam":"医疗编","prompt":"观察身边的事不难发现，成败的分野常常藏在细节里。实践证明，______安全屏障是推动高质量发展的关键一招。说到底，拼的是态度，比的是功夫。填入画横线处最恰当的是：","options":["构建","筑牢","筑造","夯实"],"answer":1,"explanation":"「筑牢」与「防线」为固定搭配，强调使牢固；「筑造」指建造实体；「构建」侧重搭建体系；「夯实」多与「基础」搭配。故选B。","__sub":"选词填空"},{"id":"yy-17577","module":"yanyu","diff":2,"exam":"国考","prompt":"很多事看起来简单，真要做扎实并不容易。新征程上，要继续______群众获得感，以实干实绩回应人民期盼。道理虽朴素，真正做到并不容易。填入画横线处最恰当的是：","options":["提高","拔高","增强","提升"],"answer":3,"explanation":"「提升」与「效能、水平」搭配规范；「提高」语义相近但「提升」更书面；「增强」多与「能力、意识」搭配；「拔高」含贬义。故选D。","__sub":"选词填空"},{"id":"yy-17579","module":"yanyu","diff":3,"exam":"教师编","prompt":"很多事看起来简单，真要做扎实并不容易。要坚持问题导向，______民意直达渠道，切实解决群众急难愁盼问题。道理虽朴素，真正做到并不容易。填入画横线处最恰当的是：","options":["打通","畅通","开辟","贯通"],"answer":1,"explanation":"「畅通」强调使通畅无阻，与「渠道、通道」搭配；「打通」侧重突破障碍；「贯通」指连接相通；「开辟」指新开路径。故选B。","__sub":"选词填空"},{"id":"yy-17582","module":"yanyu","diff":1,"exam":"省考","prompt":"干事创业，思路和坚持缺一不可。实践证明，______安全稳定底线是推动高质量发展的关键一招。其中的道理值得每个人细细体会。填入画横线处最恰当的是：","options":["防住","守牢","把牢","守住"],"answer":1,"explanation":"「守牢」与「底线」搭配，强调牢牢守住；「守住」程度稍弱；「把牢」多与「关口」搭配；「防住」为口语。故选B。","__sub":"选词填空"},{"id":"yy-17587","module":"yanyu","diff":2,"exam":"国考","prompt":"现实中，方法与态度不同，结果往往截然不同。实践证明，______时代脉搏是推动高质量发展的关键一招。看似寻常，实则是长期积累的结果。填入画横线处最恰当的是：","options":["把玩","把握","把守","把持"],"answer":1,"explanation":"「把握」与抽象事物（特点、规律、机遇）搭配；「把守」指守卫关口，「把持」含贬义指独揽，「把玩」指赏玩物品。故选B。","__sub":"选词填空"},{"id":"yy-17589","module":"yanyu","diff":3,"exam":"国考","prompt":"现实中，方法与态度不同，结果往往截然不同。回顾这些年走过的路，______数据要素价值始终是我们攻坚克难的重要法宝。看似寻常，实则是长期积累的结果。填入画横线处最恰当的是：","options":["释放","发挥","爆发","散发"],"answer":0,"explanation":"「释放」与「潜力、红利、活力」搭配；「散发」指分散发出；「发挥」与「作用」搭配；「爆发」指突然发作。故选A。","__sub":"选词填空"},{"id":"yy-17590","module":"yanyu","diff":3,"exam":"国考","prompt":"回顾这些年走过的路，______经济社会发展全过程始终是我们攻坚克难的重要法宝。填入画横线处最恰当的是：","options":["贯串","经过","穿过","贯穿"],"answer":3,"explanation":"「贯穿」指从头到尾通贯，与「全过程」搭配规范；「穿过」「经过」仅指空间或时间经过，不含通贯始终之义。故选D。","__sub":"选词填空"},{"id":"yy-17595","module":"yanyu","diff":2,"exam":"国考","prompt":"无论时代如何变化，把事情做实做细始终是成事的基础。当前正值关键时期，______生态保护红线刻不容缓，必须抓紧抓实抓出成效。这背后考验的正是把握分寸的智慧。填入画横线处最恰当的是：","options":["把牢","守住","守牢","防住"],"answer":2,"explanation":"「守牢」与「底线」搭配，强调牢牢守住；「守住」程度稍弱；「把牢」多与「关口」搭配；「防住」为口语。故选C。","__sub":"选词填空"},{"id":"yy-17599","module":"yanyu","diff":3,"exam":"国考","prompt":"无论时代如何变化，把事情做实做细始终是成事的基础。面对新形势新任务，必须______思想防线，牢牢把握发展主动权。这背后考验的正是把握分寸的智慧。填入画横线处最恰当的是：","options":["构建","夯实","筑牢","筑造"],"answer":2,"explanation":"「筑牢」与「防线」为固定搭配，强调使牢固；「筑造」指建造实体；「构建」侧重搭建体系；「夯实」多与「基础」搭配。故选C。","__sub":"选词填空"},{"id":"yy-17601","module":"yanyu","diff":1,"exam":"国考","prompt":"很多事看起来简单，真要做扎实并不容易。只有安全稳定底线真正______到基层，才能让政策在「最后一公里」落地见效。道理虽朴素，真正做到并不容易。填入画横线处最恰当的是：","options":["把牢","防住","守牢","守住"],"answer":2,"explanation":"「守牢」与「底线」搭配，强调牢牢守住；「守住」程度稍弱；「把牢」多与「关口」搭配；「防住」为口语。故选C。","__sub":"选词填空"},{"id":"yy-17603","module":"yanyu","diff":1,"exam":"省考","prompt":"干事创业，思路和坚持缺一不可。越是任务艰巨，越要______民意直达渠道，确保方向不偏、力度不减。其中的道理值得每个人细细体会。填入画横线处最恰当的是：","options":["畅通","开辟","贯通","打通"],"answer":0,"explanation":"「畅通」强调使通畅无阻，与「渠道、通道」搭配；「打通」侧重突破障碍；「贯通」指连接相通；「开辟」指新开路径。故选A。","__sub":"选词填空"},{"id":"yy-17607","module":"yanyu","diff":2,"exam":"省考","prompt":"无论时代如何变化，把事情做实做细始终是成事的基础。面对新形势新任务，必须______传统产业转型升级，牢牢把握发展主动权。这背后考验的正是把握分寸的智慧。填入画横线处最恰当的是：","options":["赋权","赋能","加持","助力"],"answer":1,"explanation":"「赋能」指赋予能力，是数字经济语境的规范表述；「赋权」指赋予权力；「加持」为口语化外来词；「助力」语义宽泛。故选B。","__sub":"选词填空"},{"id":"yy-17611","module":"yanyu","diff":1,"exam":"省考","prompt":"很多事看起来简单，真要做扎实并不容易。只有矛盾调解体系真正______到基层，才能让政策在「最后一公里」落地见效。道理虽朴素，真正做到并不容易。填入画横线处最恰当的是：","options":["完善","健全","搭建","构建"],"answer":1,"explanation":"「健全」强调使完备无缺；「完善」指补足短板；「构建」「搭建」侧重从无到有搭建。故选B。","__sub":"选词填空"},{"id":"yy-17616","module":"yanyu","diff":2,"exam":"省考","prompt":"一个朴素的道理反复被验证：方向对了，努力才不会白费。下一步，将______专精特新企业，推动各项工作再上新台阶。这也正是成事的关键所在。填入画横线处最恰当的是：","options":["培植","培养","培育","孕育"],"answer":2,"explanation":"「培育」与「产业、企业、市场」搭配；「培养」对象为人或能力；「培植」多用于动植物或含贬义；「孕育」强调正在形成。故选C。","__sub":"选词填空"},{"id":"yy-17618","module":"yanyu","diff":2,"exam":"国考","prompt":"很多事看起来简单，真要做扎实并不容易。越是任务艰巨，越要______公共卫生体系短板，确保方向不偏、力度不减。道理虽朴素，真正做到并不容易。填入画横线处最恰当的是：","options":["弥补","补足","补齐","填补"],"answer":2,"explanation":"「补齐」与「短板」为固定搭配，强调使达到应有水平；「补足」多与「差额」搭配；「填补」多与「空白」搭配；「弥补」多与「损失」搭配。故选C。","__sub":"选词填空"},{"id":"yy-17623","module":"yanyu","diff":1,"exam":"省考","prompt":"事物的发展自有其规律，顺应它才能事半功倍。当前正值关键时期，______各方合力刻不容缓，必须抓紧抓实抓出成效。这样的要求，放在哪里都不过时。填入画横线处最恰当的是：","options":["汇聚","凝聚","集中","聚集"],"answer":1,"explanation":"「凝聚」多与「共识、人心、力量」搭配，强调由分散到统一；「聚集」侧重物理集合；「集中」侧重把分散的集中起来。故选B。","__sub":"选词填空"},{"id":"yy-17625","module":"yanyu","diff":2,"exam":"国考","prompt":"无论时代如何变化，把事情做实做细始终是成事的基础。当前正值关键时期，______视野和思路刻不容缓，必须抓紧抓实抓出成效。这背后考验的正是把握分寸的智慧。填入画横线处最恰当的是：","options":["扩大","拓宽","开拓","延伸"],"answer":1,"explanation":"「拓宽」与「渠道、门路、视野」搭配；「开拓」指开辟新领域；「扩大」多与「规模、范围」搭配；「延伸」侧重长度延长。故选B。","__sub":"选词填空"},{"id":"yy-17626","module":"yanyu","diff":2,"exam":"省考","prompt":"无论时代如何变化，把事情做实做细始终是成事的基础。要在______覆盖范围上下更大功夫，让发展成果更多惠及全体人民。这背后考验的正是把握分寸的智慧。填入画横线处最恰当的是：","options":["扩大","延伸","开拓","拓宽"],"answer":3,"explanation":"「拓宽」与「渠道、门路、视野」搭配；「开拓」指开辟新领域；「扩大」多与「规模、范围」搭配；「延伸」侧重长度延长。故选D。","__sub":"选词填空"},{"id":"yy-17629","module":"yanyu","diff":3,"exam":"事业编","prompt":"很多事看起来简单，真要做扎实并不容易。面对新形势新任务，必须______房价过快上涨的势头，牢牢把握发展主动权。道理虽朴素，真正做到并不容易。填入画横线处最恰当的是：","options":["遏止","控制","制止","遏制"],"answer":3,"explanation":"「遏制」强调压制住势头、多与「势头/态势」搭配；「遏止」侧重使之停止，多用于具体行为；「控制」「制止」语义宽泛。故选D。","__sub":"选词填空"},{"id":"yy-17632","module":"yanyu","diff":1,"exam":"国考","prompt":"现实中，方法与态度不同，结果往往截然不同。新征程上，要继续______服务空白，以实干实绩回应人民期盼。看似寻常，实则是长期积累的结果。填入画横线处最恰当的是：","options":["弥补","填补","补齐","补足"],"answer":2,"explanation":"「补齐」与「短板」为固定搭配，强调使达到应有水平；「补足」多与「差额」搭配；「填补」多与「空白」搭配；「弥补」多与「损失」搭配。故选C。","__sub":"选词填空"},{"id":"yy-17633","module":"yanyu","diff":1,"exam":"国考","prompt":"任何工作要见成效，都离不开科学的方法和踏实的作风。要坚持问题导向，______各类资源配置，切实解决群众急难愁盼问题。唯有如此，才能把好事办好、实事办实。填入画横线处最恰当的是：","options":["统率","统筹","兼顾","协调"],"answer":1,"explanation":"「统筹」指全面筹划、统一安排，与「推进」搭配且强调全局性；「统率」指率领；「兼顾」只强调同时照顾；「协调」侧重配合关系。故选B。","__sub":"选词填空"},{"id":"yy-17634","module":"yanyu","diff":2,"exam":"省考","prompt":"干事创业，思路和坚持缺一不可。要坚持问题导向，______营商环境，切实解决群众急难愁盼问题。其中的道理值得每个人细细体会。填入画横线处最恰当的是：","options":["优化","调整","改进","改善"],"answer":0,"explanation":"「优化」指加以改变使其优良，与「环境、结构」搭配规范；「改善」多与「条件、生活」搭配；「改进」多与「方法、工作」搭配；「调整」不含变优之义。故选A。","__sub":"选词填空"},{"id":"yy-17636","module":"yanyu","diff":2,"exam":"省考","prompt":"一个朴素的道理反复被验证：方向对了，努力才不会白费。回顾这些年走过的路，______生产生活生态始终是我们攻坚克难的重要法宝。这也正是成事的关键所在。填入画横线处最恰当的是：","options":["统筹","协调","统率","兼顾"],"answer":0,"explanation":"「统筹」指全面筹划、统一安排，与「推进」搭配且强调全局性；「统率」指率领；「兼顾」只强调同时照顾；「协调」侧重配合关系。故选A。","__sub":"选词填空"},{"id":"yy-17638","module":"yanyu","diff":2,"exam":"教师编","prompt":"任何工作要见成效，都离不开科学的方法和踏实的作风。新征程上，要继续______改革开放各领域，以实干实绩回应人民期盼。唯有如此，才能把好事办好、实事办实。填入画横线处最恰当的是：","options":["穿过","贯串","经过","贯穿"],"answer":3,"explanation":"「贯穿」指从头到尾通贯，与「全过程」搭配规范；「穿过」「经过」仅指空间或时间经过，不含通贯始终之义。故选D。","__sub":"选词填空"},{"id":"yy-17641","module":"yanyu","diff":1,"exam":"医疗编","prompt":"观察身边的事不难发现，成败的分野常常藏在细节里。要在______创新创造潜能上下更大功夫，让发展成果更多惠及全体人民。说到底，拼的是态度，比的是功夫。填入画横线处最恰当的是：","options":["引发","点燃","调动","激发"],"answer":3,"explanation":"「激发」与「活力、热情、潜能」为固定搭配；「引发」多与「关注、争议」搭配；「点燃」为比喻用法；「调动」多与「积极性」搭配。故选D。","__sub":"选词填空"},{"id":"yy-17643","module":"yanyu","diff":1,"exam":"国考","prompt":"任何工作要见成效，都离不开科学的方法和踏实的作风。回顾这些年走过的路，______资源、服务、管理始终是我们攻坚克难的重要法宝。唯有如此，才能把好事办好、实事办实。填入画横线处最恰当的是：","options":["下沉","下探","下潜","下坠"],"answer":0,"explanation":"「下沉」指治理资源向基层倾斜，是规范表述；「下潜」指潜水，「下探」多指价格或行动试探，「下坠」指物体坠落。故选A。","__sub":"选词填空"},{"id":"yy-17645","module":"yanyu","diff":2,"exam":"国考","prompt":"任何工作要见成效，都离不开科学的方法和踏实的作风。回顾这些年走过的路，______群众获得感始终是我们攻坚克难的重要法宝。唯有如此，才能把好事办好、实事办实。填入画横线处最恰当的是：","options":["增强","提升","提高","拔高"],"answer":1,"explanation":"「提升」与「效能、水平」搭配规范；「提高」语义相近但「提升」更书面；「增强」多与「能力、意识」搭配；「拔高」含贬义。故选B。","__sub":"选词填空"},{"id":"yy-17646","module":"yanyu","diff":2,"exam":"国考","prompt":"无论时代如何变化，把事情做实做细始终是成事的基础。要在______内生动力上下更大功夫，让发展成果更多惠及全体人民。这背后考验的正是把握分寸的智慧。填入画横线处最恰当的是：","options":["点燃","引发","调动","激发"],"answer":3,"explanation":"「激发」与「活力、热情、潜能」为固定搭配；「引发」多与「关注、争议」搭配；「点燃」为比喻用法；「调动」多与「积极性」搭配。故选D。","__sub":"选词填空"},{"id":"yy-17649","module":"yanyu","diff":3,"exam":"国考","prompt":"任何工作要见成效，都离不开科学的方法和踏实的作风。越是任务艰巨，越要______爱国情怀，确保方向不偏、力度不减。唯有如此，才能把好事办好、实事办实。填入画横线处最恰当的是：","options":["厚植","加深","培植","筑牢"],"answer":0,"explanation":"「厚植」指深厚培育，与「优势、底色、根基」搭配；「培植」多用于培育动植物或扶植势力；「加深」与「底色」搭配不当。故选A。","__sub":"选词填空"},{"id":"yy-17650","module":"yanyu","diff":3,"exam":"医疗编","prompt":"一个朴素的道理反复被验证：方向对了，努力才不会白费。当前正值关键时期，______意志刻不容缓，必须抓紧抓实抓出成效。这也正是成事的关键所在。填入画横线处最恰当的是：","options":["锤炼","砥砺","锻炼","磨砺"],"answer":1,"explanation":"「砥砺」本义为磨刀石，引申为磨炼，与「意志」搭配且语体庄重；「磨砺」与之近义但「砥砺」更常用于「砥砺前行、砥砺意志」。故选B。","__sub":"选词填空"},{"id":"yy-17652","module":"yanyu","diff":1,"exam":"国考","prompt":"只有科技成果转化通道真正______到基层，才能让政策在「最后一公里」落地见效。填入画横线处最恰当的是：","options":["打通","开辟","畅通","贯通"],"answer":2,"explanation":"「畅通」强调使通畅无阻，与「渠道、通道」搭配；「打通」侧重突破障碍；「贯通」指连接相通；「开辟」指新开路径。故选C。","__sub":"选词填空"},{"id":"yy-17654","module":"yanyu","diff":2,"exam":"医疗编","prompt":"观察身边的事不难发现，成败的分野常常藏在细节里。下一步，将______各方合力，推动各项工作再上新台阶。说到底，拼的是态度，比的是功夫。填入画横线处最恰当的是：","options":["汇聚","凝聚","聚集","集中"],"answer":1,"explanation":"「凝聚」多与「共识、人心、力量」搭配，强调由分散到统一；「聚集」侧重物理集合；「集中」侧重把分散的集中起来。故选B。","__sub":"选词填空"},{"id":"yy-17656","module":"yanyu","diff":2,"exam":"事业编","prompt":"观察身边的事不难发现，成败的分野常常藏在细节里。要坚持问题导向，______责任担当，切实解决群众急难愁盼问题。说到底，拼的是态度，比的是功夫。填入画横线处最恰当的是：","options":["加强","深化","强化","增强"],"answer":2,"explanation":"「强化」与「意识、思维」搭配，强调使之更牢固；「增强」语义相近但搭配习惯不同；「加强」为通用动词；「深化」指向深处发展。故选C。","__sub":"选词填空"},{"id":"yy-17657","module":"yanyu","diff":2,"exam":"事业编","prompt":"任何工作要见成效，都离不开科学的方法和踏实的作风。新征程上，要继续______制度漏洞，以实干实绩回应人民期盼。唯有如此，才能把好事办好、实事办实。填入画横线处最恰当的是：","options":["弥补","补齐","补足","填补"],"answer":1,"explanation":"「补齐」与「短板」为固定搭配，强调使达到应有水平；「补足」多与「差额」搭配；「填补」多与「空白」搭配；「弥补」多与「损失」搭配。故选B。","__sub":"选词填空"},{"id":"yy-17659","module":"yanyu","diff":3,"exam":"省考","prompt":"现实中，方法与态度不同，结果往往截然不同。面对新形势新任务，必须______优质医疗资源，牢牢把握发展主动权。看似寻常，实则是长期积累的结果。填入画横线处最恰当的是：","options":["下潜","下探","下沉","下坠"],"answer":2,"explanation":"「下沉」指治理资源向基层倾斜，是规范表述；「下潜」指潜水，「下探」多指价格或行动试探，「下坠」指物体坠落。故选C。","__sub":"选词填空"},{"id":"yy-17672","module":"yanyu","diff":1,"exam":"事业编","prompt":"很多事看起来简单，真要做扎实并不容易。各地区各部门要拿出真招实招，______消费新增长点，确保各项部署落地生根。道理虽朴素，真正做到并不容易。填入画横线处最恰当的是：","options":["培育","孕育","培植","培养"],"answer":0,"explanation":"「培育」与「产业、企业、市场」搭配；「培养」对象为人或能力；「培植」多用于动植物或含贬义；「孕育」强调正在形成。故选A。","__sub":"选词填空"},{"id":"yy-17676","module":"yanyu","diff":2,"exam":"国考","prompt":"很多事看起来简单，真要做扎实并不容易。回顾这些年走过的路，______市场主体活力始终是我们攻坚克难的重要法宝。道理虽朴素，真正做到并不容易。填入画横线处最恰当的是：","options":["引发","激发","点燃","调动"],"answer":1,"explanation":"「激发」与「活力、热情、潜能」为固定搭配；「引发」多与「关注、争议」搭配；「点燃」为比喻用法；「调动」多与「积极性」搭配。故选B。","__sub":"选词填空"},{"id":"yy-18001","module":"yanyu","diff":2,"exam":"国考","prompt":"岁末年初，营商环境就是生产力，工程师让企业成长有沃土。","options":["厚植","培养","培育","培植"],"answer":0,"explanation":"「厚植」与「沃土」搭配得当。「厚植沃土」为书面惯用搭配；「培植」多与势力搭配含贬义；「培育」多与人才、市场搭配；「培养」多与人才搭配。故选A。","__sub":"选词填空"},{"id":"yy-18002","module":"yanyu","diff":3,"exam":"省考","prompt":"近年来，数据孤岛必须连起来，调解员下决心______部门间的壁垒。","options":["砸破","击碎","打碎","打破"],"answer":3,"explanation":"「打破」与「壁垒」搭配得当。「打破壁垒」为固定搭配；「打碎」「砸破」「击碎」均为具体物理动作。故选D。","__sub":"选词填空"},{"id":"yy-18003","module":"yanyu","diff":1,"exam":"国考","prompt":"这些年，脱贫不是终点，审计人员多措并举______脱贫成果。","options":["凝固","加固","巩固","稳固"],"answer":2,"explanation":"「巩固」与「成果」搭配得当。「巩固成果」为固定搭配；「稳固」为形容词或使稳固；「加固」用于建筑堤坝；「凝固」为物理变化。故选C。","__sub":"选词填空"},{"id":"yy-18004","module":"yanyu","diff":3,"exam":"国考","prompt":"近年来，每一起案件都关乎群众对法治的信仰，图书管理员用公正裁判______正义。","options":["防御","护卫","捍卫","保卫"],"answer":2,"explanation":"「捍卫」与「公平」搭配得当。「捍卫公平」为书面惯用搭配；「保卫」多与祖国、和平搭配；「护卫」为护送守卫；「防御」用于军事、疫情。故选C。","__sub":"选词填空"},{"id":"yy-18005","module":"yanyu","diff":2,"exam":"国考","prompt":"眼下，急难险重任务面前，护林员主动______最重的责任。","options":["抬起","挑起","背起","扛起"],"answer":3,"explanation":"「扛起」与「责任」搭配得当。「扛起责任」为惯用搭配；「背起」多与行囊、伤员搭配；「挑起」多与担子、重担搭配；「抬起」为具体动作。故选D。","__sub":"选词填空"},{"id":"yy-18006","module":"yanyu","diff":1,"exam":"事业编","prompt":"眼下，一年一度的民生大考结束，广大建设者向群众______了温暖的答卷。","options":["上缴","呈报","递交","交出"],"answer":3,"explanation":"「交出」与「答卷」搭配得当。「交出答卷」为惯用搭配；「递交」多与申请、辞呈搭配；「呈报」多与公文搭配且含上下级意味；「上缴」多与款项、物品搭配。故选D。","__sub":"选词填空"},{"id":"yy-18007","module":"yanyu","diff":2,"exam":"国考","prompt":"今年以来，发展为了人民，调解员把一件件民生实事办到群众心坎上，持续______福祉。","options":["增添","增殖","增进","增加"],"answer":2,"explanation":"「增进」与「民生」搭配得当。「增进福祉」为固定搭配，题干以民生统称；「增加」多与数量搭配；「增添」多与色彩、麻烦搭配；「增殖」为生物学用语。故选C。","__sub":"选词填空"},{"id":"yy-18008","module":"yanyu","diff":3,"exam":"国考","prompt":"近期，营商环境就是生产力，基层干部让企业成长有沃土。","options":["培育","培植","厚植","培养"],"answer":2,"explanation":"「厚植」与「沃土」搭配得当。「厚植沃土」为书面惯用搭配；「培植」多与势力搭配含贬义；「培育」多与人才、市场搭配；「培养」多与人才搭配。故选C。","__sub":"选词填空"},{"id":"yy-18009","module":"yanyu","diff":2,"exam":"国考","prompt":"盛夏时节，一二三产融合发展，护林员推动产业链不断延伸。","options":["延伸","伸长","延长","拉长"],"answer":0,"explanation":"「延伸」与「链条」搭配得当。「链条延伸」为惯用搭配；「伸长」「拉长」「延长」多用于具体长度或时间。故选A。","__sub":"选词填空"},{"id":"yy-18010","module":"yanyu","diff":3,"exam":"事业编","prompt":"近期，每个孩子都有闪光点，调解员善于______学生潜能。","options":["挖掘","开采","挖出","掘取"],"answer":0,"explanation":"「挖掘」与「潜能」搭配得当。「挖掘潜能」为固定搭配；「挖出」「掘取」为具体动作；「开采」用于矿产。故选A。","__sub":"选词填空"},{"id":"yy-18011","module":"yanyu","diff":1,"exam":"国考","prompt":"近年来，一揽子政策精准落地，医护人员着力______市场信心。","options":["鼓动","提振","提起","振作"],"answer":1,"explanation":"「提振」与「信心」搭配得当。「提振信心」为固定搭配；「提起」多与精神、话题搭配；「振作」为不及物动词；「鼓动」含煽动义。故选B。","__sub":"选词填空"},{"id":"yy-18012","module":"yanyu","diff":2,"exam":"省考","prompt":"今年以来，万丈高楼平地起，渔民一锤一钎______发展基础。","options":["夯实","填实","踩实","砸实"],"answer":0,"explanation":"「夯实」与「基础」搭配得当。「夯实基础」为固定搭配；「砸实」「踩实」「填实」均为具体动作。故选A。","__sub":"选词填空"},{"id":"yy-18013","module":"yanyu","diff":2,"exam":"省考","prompt":"一段时间以来，面对转型路上的重重难关，电力工人迎难而上，把一个个难关逐一______。","options":["克服","攻克","破除","化解"],"answer":1,"explanation":"「攻克」与「难关」搭配得当。「攻克难关」为固定搭配，强调付出努力战而胜之；「克服」多与困难、缺点搭配；「破除」多与迷信、藩篱搭配；「化解」多与矛盾、风险搭配。故选B。","__sub":"选词填空"},{"id":"yy-18014","module":"yanyu","diff":2,"exam":"医疗编","prompt":"一段时间以来，一二三产融合发展，医护人员推动产业链不断延伸。","options":["伸长","拉长","延长","延伸"],"answer":3,"explanation":"「延伸」与「链条」搭配得当。「链条延伸」为惯用搭配；「伸长」「拉长」「延长」多用于具体长度或时间。故选D。","__sub":"选词填空"},{"id":"yy-18015","module":"yanyu","diff":1,"exam":"省考","prompt":"连日来，订单排到明年，果农发展的信心。","options":["倍受","倍增","加倍","倍加"],"answer":1,"explanation":"「倍增」与「信心」搭配得当。「信心倍增」为惯用搭配；「加倍」为动词或副词；「倍加」多与珍惜搭配；「倍受」多与关注搭配。故选B。","__sub":"选词填空"},{"id":"yy-18016","module":"yanyu","diff":2,"exam":"省考","prompt":"近年来，小哨兵大作用，乡村医生让基层网格______更大作用。","options":["施展","表现","发扬","发挥"],"answer":3,"explanation":"「发挥」与「作用」搭配得当。「发挥作用」为固定搭配；「发扬」多与传统搭配；「施展」多与才华、拳脚搭配。故选D。","__sub":"选词填空"},{"id":"yy-18017","module":"yanyu","diff":3,"exam":"省考","prompt":"近期，改革红利持续显现，市场活力不断，公交司机信心更足。","options":["爆发","暴发","迸发","突发"],"answer":2,"explanation":"「迸发」与「活力」搭配得当。「迸发活力」为惯用搭配；「爆发」多用于战争、疫情或力量；「突发」多与事件搭配；「暴发」多用于疫情或含贬义。故选C。","__sub":"选词填空"},{"id":"yy-18018","module":"yanyu","diff":3,"exam":"事业编","prompt":"入冬以来，向存量要效益，图书管理员为产业升级______新空间。","options":["展开","开展","拓展","拓开"],"answer":2,"explanation":"「拓展」与「空间」搭配得当。「拓展空间」为固定搭配；「拓开」非规范；「开展」多与活动搭配；「展开」多与画卷、攻势搭配。故选C。","__sub":"选词填空"},{"id":"yy-18019","module":"yanyu","diff":2,"exam":"国考","prompt":"眼下，让公共服务覆盖城乡，电力工人持续______政策体系。","options":["完善","完缮","修完","补完"],"answer":0,"explanation":"「完善」与「体系」搭配得当。「完善体系」为固定搭配；「完缮」「修完」「补完」均非规范搭配。故选A。","__sub":"选词填空"},{"id":"yy-18020","module":"yanyu","diff":1,"exam":"事业编","prompt":"眼下，内生动力从哪里来？志愿者们把功夫下在创新上。","options":["加强","增强","增添","增大"],"answer":1,"explanation":"「增强」与「动力」搭配得当。「增强动力」为固定搭配；「加强」多与领导、管理搭配；「增大」多与幅度、剂量搭配。故选B。","__sub":"选词填空"},{"id":"yy-18021","module":"yanyu","diff":3,"exam":"省考","prompt":"入冬以来，订单排到明年，社区规划师发展的信心。","options":["倍加","倍受","倍增","加倍"],"answer":2,"explanation":"「倍增」与「信心」搭配得当。「信心倍增」为惯用搭配；「加倍」为动词或副词；「倍加」多与珍惜搭配；「倍受」多与关注搭配。故选C。","__sub":"选词填空"},{"id":"yy-18022","module":"yanyu","diff":2,"exam":"教师编","prompt":"岁末年初，营商环境就是生产力，法官让企业成长有沃土。","options":["厚植","培养","培育","培植"],"answer":0,"explanation":"「厚植」与「沃土」搭配得当。「厚植沃土」为书面惯用搭配；「培植」多与势力搭配含贬义；「培育」多与人才、市场搭配；「培养」多与人才搭配。故选A。","__sub":"选词填空"},{"id":"yy-18023","module":"yanyu","diff":1,"exam":"医疗编","prompt":"眼下，向存量要效益，博物馆讲解员为产业升级______新空间。","options":["开展","拓展","展开","拓开"],"answer":1,"explanation":"「拓展」与「空间」搭配得当。「拓展空间」为固定搭配；「拓开」非规范；「开展」多与活动搭配；「展开」多与画卷、攻势搭配。故选B。","__sub":"选词填空"},{"id":"yy-18024","module":"yanyu","diff":1,"exam":"事业编","prompt":"今年以来，产业发展的根基越牢，抗风险的能力就越强，调解员深谙此理，先把根基打扎实。","options":["夯实","垒砌","铺设","敲打"],"answer":0,"explanation":"「夯实」与「根基」搭配得当。「夯实根基」为固定搭配；「敲打」为具体动作；「铺设」用于管线、路面；「垒砌」用于砖石墙体。故选A。","__sub":"选词填空"},{"id":"yy-18025","module":"yanyu","diff":2,"exam":"省考","prompt":"今年以来，向存量要效益，调解员为产业升级______新空间。","options":["开展","拓展","展开","拓开"],"answer":1,"explanation":"「拓展」与「空间」搭配得当。「拓展空间」为固定搭配；「拓开」非规范；「开展」多与活动搭配；「展开」多与画卷、攻势搭配。故选B。","__sub":"选词填空"},{"id":"yy-18026","module":"yanyu","diff":1,"exam":"省考","prompt":"今年以来，誓师大会上，农技人员精神斗志，誓言响彻训练场。","options":["高昂","昂扬","高扬","高涨"],"answer":1,"explanation":"「昂扬」与「斗志」搭配得当。「斗志昂扬」为固定成语；「高昂」多与情绪、价格搭配；「高涨」多与热情搭配；「高扬」多与旗帜搭配。故选B。","__sub":"选词填空"},{"id":"yy-18027","module":"yanyu","diff":3,"exam":"教师编","prompt":"这些年，金融活水精准滴灌，网格员为小微企业______发展动力。","options":["灌入","灌输","注入","输入"],"answer":2,"explanation":"「注入」与「动力」搭配得当。「注入动力」为惯用搭配；「灌入」用于液体；「输入」用于数据、血液；「注入」亦可用于资金，但「注入动力」最规范。故选C。","__sub":"选词填空"},{"id":"yy-18028","module":"yanyu","diff":1,"exam":"医疗编","prompt":"初秋时节，两岸同胞亲情割不断，图书管理员为青年交流______心灵心桥。","options":["铺设","垒砌","修筑","架起"],"answer":3,"explanation":"「架起」与「心桥」搭配得当。「架起心桥」为惯用比喻搭配；「修筑」用于道路工程；「垒砌」用于砖石；「铺设」用于管线轨道。故选D。","__sub":"选词填空"},{"id":"yy-18029","module":"yanyu","diff":2,"exam":"国考","prompt":"今年以来，金融活水精准滴灌，快递员为小微企业______发展动力。","options":["注入","输入","灌入","灌输"],"answer":0,"explanation":"「注入」与「动力」搭配得当。「注入动力」为惯用搭配；「灌入」用于液体；「输入」用于数据、血液；「注入」亦可用于资金，但「注入动力」最规范。故选A。","__sub":"选词填空"},{"id":"yy-18030","module":"yanyu","diff":3,"exam":"国考","prompt":"盛夏时节，城乡公共服务仍有落差，基层干部以实策逐步______差距。","options":["缩减","缩小","减小","减少"],"answer":1,"explanation":"「缩小」与「差距」搭配得当。「缩小差距」为固定搭配；「减少」多与数量搭配；「缩减」多与开支、编制搭配；「减小」多与阻力、噪音搭配。故选B。","__sub":"选词填空"},{"id":"yy-18031","module":"yanyu","diff":1,"exam":"国考","prompt":"盛夏时节，发展为了人民，快递员把一件件民生实事办到群众心坎上，持续______福祉。","options":["增添","增进","增殖","增加"],"answer":1,"explanation":"「增进」与「民生」搭配得当。「增进福祉」为固定搭配，题干以民生统称；「增加」多与数量搭配；「增添」多与色彩、麻烦搭配；「增殖」为生物学用语。故选B。","__sub":"选词填空"},{"id":"yy-18032","module":"yanyu","diff":1,"exam":"省考","prompt":"今年以来，越是众声喧哗，越需要______共识，民警把大家的心拢到一起。","options":["凝聚","冻住","凝固","凝结"],"answer":0,"explanation":"「凝聚」与「共识」搭配得当。「凝聚共识」为固定搭配；「凝固」「冻住」「凝结」均为物理状态变化，用于抽象共识不当。故选A。","__sub":"选词填空"},{"id":"yy-18033","module":"yanyu","diff":2,"exam":"事业编","prompt":"近年来，越是爬坡过坎，越要______必胜信心，手工艺人一步一个脚印向前走。","options":["坚持不懈","坚定","坚决","坚强"],"answer":1,"explanation":"「坚定」与「信心」搭配得当。「坚定信心」为固定搭配；「坚决」为副词性形容词多修饰动作；「坚强」多与性格、领导搭配；「坚持不懈」为成语作状语。故选B。","__sub":"选词填空"},{"id":"yy-18034","module":"yanyu","diff":2,"exam":"教师编","prompt":"入冬以来，把家国情怀融入课堂，民警用身边故事打动学生。","options":["厚植","浇灌","培土","施肥"],"answer":0,"explanation":"「厚植」与「情怀」搭配得当。「厚植情怀」为书面惯用搭配；「加深」多与印象、了解搭配。故选A。","__sub":"选词填空"},{"id":"yy-18035","module":"yanyu","diff":2,"exam":"事业编","prompt":"盛夏时节，纪律规矩挺在前面，广大建设者始终______纪律底线。","options":["遵守","把守","看守","严守"],"answer":3,"explanation":"「严守」与「底线」搭配得当。「严守底线」为固定搭配；「看守」「把守」为具体看护；「遵守」多与规则、法律搭配。故选D。","__sub":"选词填空"},{"id":"yy-18036","module":"yanyu","diff":2,"exam":"省考","prompt":"盛夏时节，跳出一时一地看发展，广大建设者着力______开放共赢的新格局。","options":["架造","构作","构建","搭造"],"answer":2,"explanation":"「构建」与「格局」搭配得当。「构建格局」为惯用搭配；「构作」「搭造」「架造」均非规范书面搭配。故选C。","__sub":"选词填空"},{"id":"yy-18037","module":"yanyu","diff":2,"exam":"教师编","prompt":"今年以来，内生动力从哪里来？图书管理员把功夫下在创新上。","options":["增大","加强","增强","增添"],"answer":2,"explanation":"「增强」与「动力」搭配得当。「增强动力」为固定搭配；「加强」多与领导、管理搭配；「增大」多与幅度、剂量搭配。故选C。","__sub":"选词填空"},{"id":"yy-18038","module":"yanyu","diff":2,"exam":"国考","prompt":"近年来，在广袤乡野间，医护人员用汗水______出乡村振兴的崭新篇章。","options":["描红","抄写","书写","誊写"],"answer":2,"explanation":"「书写」与「篇章」搭配得当。「书写篇章」为惯用搭配；「抄写」「誊写」「描红」均为照原样复写的具体动作，缺乏开创义。故选C。","__sub":"选词填空"},{"id":"yy-18039","module":"yanyu","diff":2,"exam":"教师编","prompt":"眼下，纪律规矩挺在前面，民警始终______纪律底线。","options":["把守","遵守","严守","看守"],"answer":2,"explanation":"「严守」与「底线」搭配得当。「严守底线」为固定搭配；「看守」「把守」为具体看护；「遵守」多与规则、法律搭配。故选C。","__sub":"选词填空"},{"id":"yy-18040","module":"yanyu","diff":2,"exam":"教师编","prompt":"入冬以来，乡情是最深的牵挂，网格员以商会为平台______情感纽带。","options":["捆牢","绑牢","织牢","系牢"],"answer":2,"explanation":"「织牢」与「纽带」搭配得当。「织牢纽带」为惯用比喻搭配；「系牢」「捆牢」「绑牢」均为具体系绑动作。故选C。","__sub":"选词填空"},{"id":"yy-18041","module":"yanyu","diff":2,"exam":"省考","prompt":"连日来，向存量要效益，图书管理员为产业升级______新空间。","options":["展开","拓开","拓展","开展"],"answer":2,"explanation":"「拓展」与「空间」搭配得当。「拓展空间」为固定搭配；「拓开」非规范；「开展」多与活动搭配；「展开」多与画卷、攻势搭配。故选C。","__sub":"选词填空"},{"id":"yy-18042","module":"yanyu","diff":1,"exam":"国考","prompt":"初秋时节，面对转型路上的重重难关，医护人员迎难而上，把一个个难关逐一______。","options":["克服","破除","攻克","化解"],"answer":2,"explanation":"「攻克」与「难关」搭配得当。「攻克难关」为固定搭配，强调付出努力战而胜之；「克服」多与困难、缺点搭配；「破除」多与迷信、藩篱搭配；「化解」多与矛盾、风险搭配。故选C。","__sub":"选词填空"},{"id":"yy-18043","module":"yanyu","diff":2,"exam":"事业编","prompt":"入冬以来，夜市灯火点亮街巷，图书管理员为城市______了烟火活力。","options":["增添","增加","追加","增补"],"answer":0,"explanation":"「增添」与「活力」搭配得当。「增添活力」为惯用搭配；「增加」多与数量搭配；「追加」多与投资搭配；「增补」多与人员、内容搭配。故选A。","__sub":"选词填空"},{"id":"yy-18044","module":"yanyu","diff":3,"exam":"事业编","prompt":"近期，从受理到反馈全流程留痕，图书管理员以数字化手段______管理闭环。","options":["构建","圈画","搭圈","构画"],"answer":0,"explanation":"「构建」与「闭环」搭配得当。「构建闭环」为惯用搭配；其余选项均非规范搭配。故选A。","__sub":"选词填空"},{"id":"yy-18045","module":"yanyu","diff":3,"exam":"事业编","prompt":"入冬以来，金融活水精准滴灌，茶农为小微企业______发展动力。","options":["注入","灌输","灌入","输入"],"answer":0,"explanation":"「注入」与「动力」搭配得当。「注入动力」为惯用搭配；「灌入」用于液体；「输入」用于数据、血液；「注入」亦可用于资金，但「注入动力」最规范。故选A。","__sub":"选词填空"},{"id":"yy-18046","module":"yanyu","diff":2,"exam":"国考","prompt":"入冬以来，传统村落保护性开发，文旅部门既富了口袋，也______了乡愁。","options":["留住","拘留","截留","扣留"],"answer":0,"explanation":"「留住」与「乡愁」搭配得当。「留住乡愁」为惯用表达；「扣留」「拘留」「截留」均为法律或强制扣押义，感情色彩不合。故选A。","__sub":"选词填空"},{"id":"yy-18047","module":"yanyu","diff":1,"exam":"国考","prompt":"一段时间以来，让要素流动更顺畅，就要______体制机制的藩篱。","options":["破除","铲平","捣毁","拆除"],"answer":0,"explanation":"「破除」与「藩篱」搭配得当。「破除藩篱」为固定搭配；「拆除」用于建筑；「铲平」用于场地；「捣毁」用于巢穴、据点且含暴力义。故选A。","__sub":"选词填空"},{"id":"yy-18048","module":"yanyu","diff":2,"exam":"国考","prompt":"眼下，一次次说到做到，驻村干部用行动______了群众的信任。","options":["获得","博得","换取","赢得"],"answer":3,"explanation":"「赢得」与「信任」搭配得当。「赢得信任」为固定搭配，强调经努力而获得；「获得」中性；「博得」多与同情、喝彩搭配；「换取」含交换义。故选D。","__sub":"选词填空"},{"id":"yy-18049","module":"yanyu","diff":2,"exam":"国考","prompt":"这些年，景区客流高峰来临，图书管理员全员上岗______游览秩序。","options":["保护","维护","维持","护卫"],"answer":1,"explanation":"「维护」与「秩序」搭配得当。「维护秩序」为固定搭配；「维持」多与生活、现状搭配；「保护」多与权益、环境搭配；「护卫」用于人员、目标。故选B。","__sub":"选词填空"},{"id":"yy-18050","module":"yanyu","diff":1,"exam":"国考","prompt":"岁末年初，齐抓共管不是一句口号，环卫工人推动齐抓共管合力。","options":["成形","形成","成型","成立"],"answer":1,"explanation":"「形成」与「合力」搭配得当。「形成合力」为固定搭配；「成形」「成型」指具形；「成立」多与组织搭配。故选B。","__sub":"选词填空"},{"id":"yy-18051","module":"yanyu","diff":2,"exam":"事业编","prompt":"一段时间以来，老旧小区加装电梯、增设车位，社区规划师尽力______居民多样需求。","options":["充足","满意","充盈","满足"],"answer":3,"explanation":"「满足」与「需求」搭配得当。「满足需求」为固定搭配；「满意」为形容词；「充足」「充盈」为形容词不能带宾语。故选D。","__sub":"选词填空"},{"id":"yy-18052","module":"yanyu","diff":1,"exam":"医疗编","prompt":"初秋时节，众人的事情由众人商量，果农把各方______到规划图上。","options":["收拢","凝聚","归拢","聚拢"],"answer":1,"explanation":"「凝聚」与「智慧」搭配得当。「凝聚智慧」为惯用搭配；「聚拢」「收拢」「归拢」均为具体收拢动作，用于抽象智慧不当。故选B。","__sub":"选词填空"},{"id":"yy-18053","module":"yanyu","diff":1,"exam":"国考","prompt":"今年以来，危难时刻冲得上去，科研人员的行动______了共产党员的担当。","options":["暴露","彰显","显露","显摆"],"answer":1,"explanation":"「彰显」与「担当」搭配得当。「彰显担当」为固定搭配，褒义；「显摆」为口语含贬义；「显露」中性；「暴露」多含贬义。故选B。","__sub":"选词填空"},{"id":"yy-18054","module":"yanyu","diff":1,"exam":"省考","prompt":"岁末年初，老工业基地涅槃重生，社区工作者加快新旧动能步伐。","options":["转换","改换","转变","变换"],"answer":0,"explanation":"「转换」与「动能」搭配得当。「动能转换」为固定搭配；「转变」多与观念、方式搭配；「改换」「变换」多与门庭、姿势搭配。故选A。","__sub":"选词填空"},{"id":"yy-18055","module":"yanyu","diff":2,"exam":"事业编","prompt":"初秋时节，面对转型路上的重重难关，社区工作者迎难而上，把一个个难关逐一______。","options":["化解","攻克","克服","破除"],"answer":1,"explanation":"「攻克」与「难关」搭配得当。「攻克难关」为固定搭配，强调付出努力战而胜之；「克服」多与困难、缺点搭配；「破除」多与迷信、藩篱搭配；「化解」多与矛盾、风险搭配。故选B。","__sub":"选词填空"},{"id":"yy-18056","module":"yanyu","diff":2,"exam":"国考","prompt":"盛夏时节，从受理到反馈全流程留痕，调解员以数字化手段______管理闭环。","options":["圈画","构建","构画","搭圈"],"answer":1,"explanation":"「构建」与「闭环」搭配得当。「构建闭环」为惯用搭配；其余选项均非规范搭配。故选B。","__sub":"选词填空"},{"id":"yy-18057","module":"yanyu","diff":2,"exam":"事业编","prompt":"连日来，从受理到反馈全流程留痕，审计人员以数字化手段______管理闭环。","options":["搭圈","圈画","构画","构建"],"answer":3,"explanation":"「构建」与「闭环」搭配得当。「构建闭环」为惯用搭配；其余选项均非规范搭配。故选D。","__sub":"选词填空"},{"id":"yy-18058","module":"yanyu","diff":2,"exam":"事业编","prompt":"这些年，放宽准入激发创业热情，青年学子让创造活力。","options":["淌出","涌出","流出","涌流"],"answer":3,"explanation":"「涌流」与「活力」搭配得当。「活力涌流」为惯用表达；「流出」「淌出」「涌出」均用于液体且为具体动作。故选D。","__sub":"选词填空"},{"id":"yy-18059","module":"yanyu","diff":2,"exam":"国考","prompt":"盛夏时节，老艺人收徒授艺，让千年技艺薪火。","options":["互传","递送","传递","相传"],"answer":3,"explanation":"「相传」与「薪火」搭配得当。「薪火相传」为固定成语；「互传」「递送」「传递」均无此搭配且丢失比喻义。故选D。","__sub":"选词填空"},{"id":"yy-18060","module":"yanyu","diff":2,"exam":"教师编","prompt":"眼下，乡情是最深的牵挂，图书管理员以商会为平台______情感纽带。","options":["捆牢","织牢","绑牢","系牢"],"answer":1,"explanation":"「织牢」与「纽带」搭配得当。「织牢纽带」为惯用比喻搭配；「系牢」「捆牢」「绑牢」均为具体系绑动作。故选B。","__sub":"选词填空"},{"id":"yy-18061","module":"yanyu","diff":1,"exam":"国考","prompt":"入冬以来，夜市灯火点亮街巷，护林员为城市______了烟火活力。","options":["追加","增补","增添","增加"],"answer":2,"explanation":"「增添」与「活力」搭配得当。「增添活力」为惯用搭配；「增加」多与数量搭配；「追加」多与投资搭配；「增补」多与人员、内容搭配。故选C。","__sub":"选词填空"},{"id":"yy-18062","module":"yanyu","diff":2,"exam":"国考","prompt":"近期，从受理到反馈全流程留痕，青年学子以数字化手段______管理闭环。","options":["构建","构画","圈画","搭圈"],"answer":0,"explanation":"「构建」与「闭环」搭配得当。「构建闭环」为惯用搭配；其余选项均非规范搭配。故选A。","__sub":"选词填空"},{"id":"yy-18063","module":"yanyu","diff":3,"exam":"教师编","prompt":"初秋时节，夜市灯火点亮街巷，社区规划师为城市______了烟火活力。","options":["增添","增补","增加","追加"],"answer":0,"explanation":"「增添」与「活力」搭配得当。「增添活力」为惯用搭配；「增加」多与数量搭配；「追加」多与投资搭配；「增补」多与人员、内容搭配。故选A。","__sub":"选词填空"},{"id":"yy-18064","module":"yanyu","diff":1,"exam":"事业编","prompt":"近期，新区建设的宏伟蓝图已经展开，渔民正把一张张蓝图变成施工图。","options":["耕耘","绘就","编织","修筑"],"answer":1,"explanation":"「绘就」与「蓝图」搭配得当。「绘就蓝图」为惯用搭配；「修筑」用于道路工事；「耕耘」用于田地或比喻辛勤付出；「编织」多与梦想、纽带搭配，与蓝图不搭。故选B。","__sub":"选词填空"},{"id":"yy-18065","module":"yanyu","diff":1,"exam":"事业编","prompt":"近年来，两岸同胞亲情割不断，教师为青年交流______心灵心桥。","options":["垒砌","铺设","架起","修筑"],"answer":2,"explanation":"「架起」与「心桥」搭配得当。「架起心桥」为惯用比喻搭配；「修筑」用于道路工程；「垒砌」用于砖石；「铺设」用于管线轨道。故选C。","__sub":"选词填空"},{"id":"yy-18066","module":"yanyu","diff":1,"exam":"国考","prompt":"近年来，减税降费政策落地，铁路养护工让企业真切感受到红利。","options":["散发","发放","发射","释放"],"answer":3,"explanation":"「释放」与「红利」搭配得当。「释放红利」为惯用搭配；「发放」多与物资、贷款搭配；「散发」多与气味搭配；「发射」用于子弹、卫星。故选D。","__sub":"选词填空"},{"id":"yy-18067","module":"yanyu","diff":2,"exam":"教师编","prompt":"眼下，每个孩子都有闪光点，志愿者们善于______学生潜能。","options":["掘取","开采","挖掘","挖出"],"answer":2,"explanation":"「挖掘」与「潜能」搭配得当。「挖掘潜能」为固定搭配；「挖出」「掘取」为具体动作；「开采」用于矿产。故选C。","__sub":"选词填空"},{"id":"yy-18068","module":"yanyu","diff":2,"exam":"国考","prompt":"近期，政府、市场、社会同向发力，公交司机让各方______成强大合力。","options":["汇聚","汇合","聚合","汇集"],"answer":0,"explanation":"「汇聚」与「合力」搭配得当。「汇聚合力」为惯用搭配；「汇合」指水流等聚集；「汇集」指集中收集；「聚合」为化学或物理过程。故选A。","__sub":"选词填空"},{"id":"yy-18069","module":"yanyu","diff":2,"exam":"省考","prompt":"近期，一揽子政策精准落地，审计人员着力______市场信心。","options":["提振","振作","鼓动","提起"],"answer":0,"explanation":"「提振」与「信心」搭配得当。「提振信心」为固定搭配；「提起」多与精神、话题搭配；「振作」为不及物动词；「鼓动」含煽动义。故选A。","__sub":"选词填空"},{"id":"yy-18070","module":"yanyu","diff":1,"exam":"事业编","prompt":"一段时间以来，让公共服务覆盖城乡，渔民持续______政策体系。","options":["完善","补完","完缮","修完"],"answer":0,"explanation":"「完善」与「体系」搭配得当。「完善体系」为固定搭配；「完缮」「修完」「补完」均非规范搭配。故选A。","__sub":"选词填空"},{"id":"yy-18071","module":"yanyu","diff":2,"exam":"事业编","prompt":"开春以来，夜市灯火点亮街巷，铁路养护工为城市______了烟火活力。","options":["增补","增加","增添","追加"],"answer":2,"explanation":"「增添」与「活力」搭配得当。「增添活力」为惯用搭配；「增加」多与数量搭配；「追加」多与投资搭配；「增补」多与人员、内容搭配。故选C。","__sub":"选词填空"},{"id":"yy-18072","module":"yanyu","diff":1,"exam":"国考","prompt":"近年来，脱贫不是终点，老党员多措并举______脱贫成果。","options":["巩固","凝固","稳固","加固"],"answer":0,"explanation":"「巩固」与「成果」搭配得当。「巩固成果」为固定搭配；「稳固」为形容词或使稳固；「加固」用于建筑堤坝；「凝固」为物理变化。故选A。","__sub":"选词填空"},{"id":"yy-18073","module":"yanyu","diff":1,"exam":"医疗编","prompt":"一段时间以来，众人的事情由众人商量，基层干部把各方______到规划图上。","options":["收拢","聚拢","归拢","凝聚"],"answer":3,"explanation":"「凝聚」与「智慧」搭配得当。「凝聚智慧」为惯用搭配；「聚拢」「收拢」「归拢」均为具体收拢动作，用于抽象智慧不当。故选D。","__sub":"选词填空"},{"id":"yy-18074","module":"yanyu","diff":1,"exam":"省考","prompt":"眼下，一年一度的民生大考结束，网格员向群众______了温暖的答卷。","options":["上缴","呈报","递交","交出"],"answer":3,"explanation":"「交出」与「答卷」搭配得当。「交出答卷」为惯用搭配；「递交」多与申请、辞呈搭配；「呈报」多与公文搭配且含上下级意味；「上缴」多与款项、物品搭配。故选D。","__sub":"选词填空"},{"id":"yy-18075","module":"yanyu","diff":3,"exam":"国考","prompt":"入冬以来，面对转型路上的重重难关，乡村医生迎难而上，把一个个难关逐一______。","options":["化解","破除","克服","攻克"],"answer":3,"explanation":"「攻克」与「难关」搭配得当。「攻克难关」为固定搭配，强调付出努力战而胜之；「克服」多与困难、缺点搭配；「破除」多与迷信、藩篱搭配；「化解」多与矛盾、风险搭配。故选D。","__sub":"选词填空"},{"id":"yy-18076","module":"yanyu","diff":2,"exam":"医疗编","prompt":"近期，两岸同胞亲情割不断，医护人员为青年交流______心灵心桥。","options":["修筑","铺设","架起","垒砌"],"answer":2,"explanation":"「架起」与「心桥」搭配得当。「架起心桥」为惯用比喻搭配；「修筑」用于道路工程；「垒砌」用于砖石；「铺设」用于管线轨道。故选C。","__sub":"选词填空"},{"id":"yy-18077","module":"yanyu","diff":3,"exam":"省考","prompt":"岁末年初，把资源优势变成产业优势，社区工作者下大气力______区域品牌。","options":["打造","打制","拍打","锻打"],"answer":0,"explanation":"「打造」与「品牌」搭配得当。「打造品牌」为固定搭配；「打制」「锻打」用于金属器物；「拍打」为具体动作。故选A。","__sub":"选词填空"},{"id":"yy-18078","module":"yanyu","diff":1,"exam":"事业编","prompt":"连日来，春潮拍岸千帆竞，快递员感受到创新活力。","options":["流出","涌出","淌动","涌动"],"answer":3,"explanation":"「涌动」与「活力」搭配得当。「活力涌动」为惯用表达；「涌出」「流出」为具体动作；「淌动」非规范。故选D。","__sub":"选词填空"},{"id":"yy-18079","module":"yanyu","diff":2,"exam":"国考","prompt":"近年来，政府、市场、社会同向发力，铁路养护工让各方______成强大合力。","options":["汇集","汇聚","汇合","聚合"],"answer":1,"explanation":"「汇聚」与「合力」搭配得当。「汇聚合力」为惯用搭配；「汇合」指水流等聚集；「汇集」指集中收集；「聚合」为化学或物理过程。故选B。","__sub":"选词填空"},{"id":"yy-18080","module":"yanyu","diff":2,"exam":"省考","prompt":"近年来，向存量要效益，程序员为产业升级______新空间。","options":["拓开","开展","拓展","展开"],"answer":2,"explanation":"「拓展」与「空间」搭配得当。「拓展空间」为固定搭配；「拓开」非规范；「开展」多与活动搭配；「展开」多与画卷、攻势搭配。故选C。","__sub":"选词填空"},{"id":"yy-18081","module":"yanyu","diff":2,"exam":"省考","prompt":"初秋时节，每一起案件都关乎群众对法治的信仰，程序员用公正裁判______正义。","options":["防御","捍卫","护卫","保卫"],"answer":1,"explanation":"「捍卫」与「公平」搭配得当。「捍卫公平」为书面惯用搭配；「保卫」多与祖国、和平搭配；「护卫」为护送守卫；「防御」用于军事、疫情。故选B。","__sub":"选词填空"},{"id":"yy-18082","module":"yanyu","diff":1,"exam":"省考","prompt":"连日来，把家国情怀融入课堂，审计人员用身边故事打动学生。","options":["施肥","浇灌","厚植","培土"],"answer":2,"explanation":"「厚植」与「情怀」搭配得当。「厚植情怀」为书面惯用搭配；「加深」多与印象、了解搭配。故选C。","__sub":"选词填空"},{"id":"yy-18083","module":"yanyu","diff":2,"exam":"医疗编","prompt":"盛夏时节，把资源优势变成产业优势，教师下大气力______区域品牌。","options":["打制","锻打","打造","拍打"],"answer":2,"explanation":"「打造」与「品牌」搭配得当。「打造品牌」为固定搭配；「打制」「锻打」用于金属器物；「拍打」为具体动作。故选C。","__sub":"选词填空"},{"id":"yy-18084","module":"yanyu","diff":2,"exam":"国考","prompt":"今年以来，减税降费政策落地，调解员让企业真切感受到红利。","options":["发射","散发","释放","发放"],"answer":2,"explanation":"「释放」与「红利」搭配得当。「释放红利」为惯用搭配；「发放」多与物资、贷款搭配；「散发」多与气味搭配；「发射」用于子弹、卫星。故选C。","__sub":"选词填空"},{"id":"yy-18085","module":"yanyu","diff":2,"exam":"省考","prompt":"入冬以来，政府、市场、社会同向发力，电力工人让各方______成强大合力。","options":["汇聚","汇集","汇合","聚合"],"answer":0,"explanation":"「汇聚」与「合力」搭配得当。「汇聚合力」为惯用搭配；「汇合」指水流等聚集；「汇集」指集中收集；「聚合」为化学或物理过程。故选A。","__sub":"选词填空"},{"id":"yy-18086","module":"yanyu","diff":2,"exam":"省考","prompt":"这些年，市场细胞活跃起来，公交司机让经济肌体活力。","options":["装满","塞满","充满","填满"],"answer":2,"explanation":"「充满」与「活力」搭配得当。「充满活力」为固定搭配；「填满」「塞满」「装满」均为具体动作，用于抽象活力不当。故选C。","__sub":"选词填空"},{"id":"yy-18087","module":"yanyu","diff":2,"exam":"教师编","prompt":"今年以来，越是爬坡过坎，越要______必胜信心，志愿者们一步一个脚印向前走。","options":["坚强","坚持不懈","坚决","坚定"],"answer":3,"explanation":"「坚定」与「信心」搭配得当。「坚定信心」为固定搭配；「坚决」为副词性形容词多修饰动作；「坚强」多与性格、领导搭配；「坚持不懈」为成语作状语。故选D。","__sub":"选词填空"},{"id":"yy-18088","module":"yanyu","diff":1,"exam":"事业编","prompt":"开春以来，在广袤乡野间，志愿者们用汗水______出乡村振兴的崭新篇章。","options":["书写","誊写","描红","抄写"],"answer":0,"explanation":"「书写」与「篇章」搭配得当。「书写篇章」为惯用搭配；「抄写」「誊写」「描红」均为照原样复写的具体动作，缺乏开创义。故选A。","__sub":"选词填空"},{"id":"yy-18089","module":"yanyu","diff":3,"exam":"医疗编","prompt":"一段时间以来，金杯银杯不如老百姓的口碑，民警把每件小事都当大事办。","options":["创立","建立","设立","树立"],"answer":3,"explanation":"「树立」与「口碑」搭配得当。「树立口碑」为惯用搭配；「建立」多与制度、关系搭配；「设立」多与机构搭配；「创立」多与学说、品牌搭配。故选D。","__sub":"选词填空"},{"id":"yy-18090","module":"yanyu","diff":2,"exam":"国考","prompt":"岁末年初，一网通办让数据多跑路，社区工作者以流程再造______政务效能。","options":["提高","拔高","抬高","提升"],"answer":3,"explanation":"「提升」与「效能」搭配得当。「提升效能」为固定搭配；「提高」多与水平、价格搭配；「拔高」含刻意抬升义；「抬高」多与价格、身价搭配。故选D。","__sub":"选词填空"},{"id":"yy-18091","module":"yanyu","diff":2,"exam":"教师编","prompt":"这些年，数据孤岛必须连起来，程序员下决心______部门间的壁垒。","options":["打破","砸破","击碎","打碎"],"answer":0,"explanation":"「打破」与「壁垒」搭配得当。「打破壁垒」为固定搭配；「打碎」「砸破」「击碎」均为具体物理动作。故选A。","__sub":"选词填空"},{"id":"yy-18092","module":"yanyu","diff":1,"exam":"省考","prompt":"今年以来，内生动力从哪里来？执法人员把功夫下在创新上。","options":["增大","加强","增添","增强"],"answer":3,"explanation":"「增强」与「动力」搭配得当。「增强动力」为固定搭配；「加强」多与领导、管理搭配；「增大」多与幅度、剂量搭配。故选D。","__sub":"选词填空"},{"id":"yy-18093","module":"yanyu","diff":1,"exam":"医疗编","prompt":"开春以来，人才是创新的第一资源，铁路养护工把发展根基越培越厚。","options":["浇灌","培土","施肥","厚植"],"answer":3,"explanation":"「厚植」与「根基」搭配得当。「厚植根基」为书面惯用搭配；「培土」「施肥」「浇灌」均为农事具体动作。故选D。","__sub":"选词填空"},{"id":"yy-18094","module":"yanyu","diff":1,"exam":"医疗编","prompt":"今年以来，让监督机制长出牙齿，快递员把制度笼子越扎越紧。","options":["修葺","修复","健全","修理"],"answer":2,"explanation":"「健全」与「机制」搭配得当。「健全机制」为固定搭配，使完善；「修理」「修复」「修葺」均指具体物件的修补，与机制不搭。故选C。","__sub":"选词填空"},{"id":"yy-18095","module":"yanyu","diff":2,"exam":"省考","prompt":"盛夏时节，市场细胞活跃起来，非遗传承人让经济肌体活力。","options":["装满","塞满","填满","充满"],"answer":3,"explanation":"「充满」与「活力」搭配得当。「充满活力」为固定搭配；「填满」「塞满」「装满」均为具体动作，用于抽象活力不当。故选D。","__sub":"选词填空"},{"id":"yy-18096","module":"yanyu","diff":1,"exam":"国考","prompt":"岁末年初，新区建设的宏伟蓝图已经展开，博物馆讲解员正把一张张蓝图变成施工图。","options":["编织","绘就","耕耘","修筑"],"answer":1,"explanation":"「绘就」与「蓝图」搭配得当。「绘就蓝图」为惯用搭配；「修筑」用于道路工事；「耕耘」用于田地或比喻辛勤付出；「编织」多与梦想、纽带搭配，与蓝图不搭。故选B。","__sub":"选词填空"},{"id":"yy-18097","module":"yanyu","diff":1,"exam":"省考","prompt":"初秋时节，纪律规矩挺在前面，茶农始终______纪律底线。","options":["遵守","严守","看守","把守"],"answer":1,"explanation":"「严守」与「底线」搭配得当。「严守底线」为固定搭配；「看守」「把守」为具体看护；「遵守」多与规则、法律搭配。故选B。","__sub":"选词填空"},{"id":"yy-18098","module":"yanyu","diff":2,"exam":"事业编","prompt":"近年来，卡脖子技术亟待攻坚，图书管理员集中力量______一个个瓶颈。","options":["捅破","撞破","冲破","突破"],"answer":3,"explanation":"「突破」与「瓶颈」搭配得当。「突破瓶颈」为固定搭配；「冲破」多与封锁、束缚搭配；「撞破」「捅破」为具体动作或与窗户纸等搭配。故选D。","__sub":"选词填空"},{"id":"yy-18099","module":"yanyu","diff":2,"exam":"国考","prompt":"近期，二十年只做一件事，广大建设者在细分领域里做到极致。","options":["深挖","深掘","深耕","深钻"],"answer":2,"explanation":"「深耕」与「领域」搭配得当。「深耕领域」为惯用比喻搭配；「深挖」多与线索搭配；「深钻」「深掘」非规范。故选C。","__sub":"选词填空"},{"id":"yy-18100","module":"yanyu","diff":2,"exam":"省考","prompt":"一段时间以来，向存量要效益，茶农为产业升级______新空间。","options":["拓展","拓开","展开","开展"],"answer":0,"explanation":"「拓展」与「空间」搭配得当。「拓展空间」为固定搭配；「拓开」非规范；「开展」多与活动搭配；「展开」多与画卷、攻势搭配。故选A。","__sub":"选词填空"},{"id":"yy-18101","module":"yanyu","diff":1,"exam":"国考","prompt":"今年以来，卡脖子技术亟待攻坚，手工艺人集中力量______一个个瓶颈。","options":["捅破","冲破","突破","撞破"],"answer":2,"explanation":"「突破」与「瓶颈」搭配得当。「突破瓶颈」为固定搭配；「冲破」多与封锁、束缚搭配；「撞破」「捅破」为具体动作或与窗户纸等搭配。故选C。","__sub":"选词填空"},{"id":"yy-18102","module":"yanyu","diff":2,"exam":"省考","prompt":"近年来，卡脖子技术亟待攻坚，执法人员集中力量______一个个瓶颈。","options":["突破","冲破","捅破","撞破"],"answer":0,"explanation":"「突破」与「瓶颈」搭配得当。「突破瓶颈」为固定搭配；「冲破」多与封锁、束缚搭配；「撞破」「捅破」为具体动作或与窗户纸等搭配。故选A。","__sub":"选词填空"},{"id":"yy-18103","module":"yanyu","diff":2,"exam":"省考","prompt":"今年以来，几十年如一日，医护人员在平凡岗位上______着为民初心。","options":["坚守","把守","守卫","保守"],"answer":0,"explanation":"「坚守」与「初心」搭配得当。「坚守初心」为固定搭配；「保守」多与秘密搭配；「守卫」用于边疆、家园；「把守」用于关口。故选A。","__sub":"选词填空"},{"id":"yy-18104","module":"yanyu","diff":1,"exam":"省考","prompt":"盛夏时节，民生领域还有欠账，老党员列出清单逐项______短板。","options":["修补","补丁","贴补","补齐"],"answer":3,"explanation":"「补齐」与「短板」搭配得当。「补齐短板」为固定搭配；「补丁」为名词；「修补」多用于衣物器物；「贴补」多与费用搭配。故选D。","__sub":"选词填空"},{"id":"yy-18105","module":"yanyu","diff":3,"exam":"教师编","prompt":"近年来，初心如磐，使命在肩，审计人员把承诺落到一件件小事上。","options":["履行","践行","执行","旅行"],"answer":1,"explanation":"「践行」与「使命」搭配得当。「践行使命」为固定搭配；「履行」多与职责、义务、合同搭配；「执行」多与命令、判决、任务搭配；「旅行」为出行义。故选B。","__sub":"选词填空"},{"id":"yy-18106","module":"yanyu","diff":2,"exam":"省考","prompt":"今年以来，一二三产融合发展，社区规划师推动产业链不断延伸。","options":["延长","延伸","拉长","伸长"],"answer":1,"explanation":"「延伸」与「链条」搭配得当。「链条延伸」为惯用搭配；「伸长」「拉长」「延长」多用于具体长度或时间。故选B。","__sub":"选词填空"},{"id":"yy-18107","module":"yanyu","diff":2,"exam":"国考","prompt":"岁末年初，人才是创新的第一资源，铁路养护工把发展根基越培越厚。","options":["施肥","浇灌","厚植","培土"],"answer":2,"explanation":"「厚植」与「根基」搭配得当。「厚植根基」为书面惯用搭配；「培土」「施肥」「浇灌」均为农事具体动作。故选C。","__sub":"选词填空"},{"id":"yy-18108","module":"yanyu","diff":1,"exam":"省考","prompt":"连日来，每一起案件都关乎群众对法治的信仰，审计人员用公正裁判______正义。","options":["防御","捍卫","护卫","保卫"],"answer":1,"explanation":"「捍卫」与「公平」搭配得当。「捍卫公平」为书面惯用搭配；「保卫」多与祖国、和平搭配；「护卫」为护送守卫；「防御」用于军事、疫情。故选B。","__sub":"选词填空"},{"id":"yy-18109","module":"yanyu","diff":2,"exam":"教师编","prompt":"近期，筑起生态安全屏障，渔民让青山常在绿水长流。","options":["砌牢","筑牢","锁牢","拴牢"],"answer":1,"explanation":"「筑牢」与「屏障」搭配得当。「筑牢屏障」为惯用搭配；「砌牢」用于砖石；「锁牢」「拴牢」用于器物。故选B。","__sub":"选词填空"},{"id":"yy-18110","module":"yanyu","diff":3,"exam":"省考","prompt":"盛夏时节，红色资源是最生动的教材，护林员让红色血脉代代相传。","options":["接续","延续","继续","赓续"],"answer":3,"explanation":"「赓续」与「血脉」搭配得当。「赓续血脉」为书面惯用搭配；「继续」为一般动词；「接续」多与手续、产业搭配；「延续」多与生命、文脉搭配。故选D。","__sub":"选词填空"},{"id":"yy-18111","module":"yanyu","diff":1,"exam":"事业编","prompt":"近年来，新区建设的宏伟蓝图已经展开，调解员正把一张张蓝图变成施工图。","options":["耕耘","绘就","修筑","编织"],"answer":1,"explanation":"「绘就」与「蓝图」搭配得当。「绘就蓝图」为惯用搭配；「修筑」用于道路工事；「耕耘」用于田地或比喻辛勤付出；「编织」多与梦想、纽带搭配，与蓝图不搭。故选B。","__sub":"选词填空"},{"id":"yy-18112","module":"yanyu","diff":2,"exam":"医疗编","prompt":"这些年，内生动力从哪里来？驻村干部把功夫下在创新上。","options":["增添","增强","增大","加强"],"answer":1,"explanation":"「增强」与「动力」搭配得当。「增强动力」为固定搭配；「加强」多与领导、管理搭配；「增大」多与幅度、剂量搭配。故选B。","__sub":"选词填空"},{"id":"yy-18113","module":"yanyu","diff":2,"exam":"事业编","prompt":"开春以来，古城修缮不搞大拆大建，市场监管部门让千年文脉在街巷间静静流淌。","options":["续接","延续","接通","连接"],"answer":1,"explanation":"「延续」与「文脉」搭配得当。「延续文脉」为惯用搭配；「连接」指具体相连；「续接」多与线路搭配；「接通」用于电话、电路。故选B。","__sub":"选词填空"},{"id":"yy-18114","module":"yanyu","diff":2,"exam":"省考","prompt":"开春以来，让监督机制长出牙齿，乡村医生把制度笼子越扎越紧。","options":["修葺","修复","修理","健全"],"answer":3,"explanation":"「健全」与「机制」搭配得当。「健全机制」为固定搭配，使完善；「修理」「修复」「修葺」均指具体物件的修补，与机制不搭。故选D。","__sub":"选词填空"},{"id":"yy-18115","module":"yanyu","diff":3,"exam":"省考","prompt":"岁末年初，营商环境就是生产力，非遗传承人让企业成长有沃土。","options":["培植","培育","培养","厚植"],"answer":3,"explanation":"「厚植」与「沃土」搭配得当。「厚植沃土」为书面惯用搭配；「培植」多与势力搭配含贬义；「培育」多与人才、市场搭配；「培养」多与人才搭配。故选D。","__sub":"选词填空"},{"id":"yy-18116","module":"yanyu","diff":1,"exam":"省考","prompt":"眼下，改革到了深水区，果农以钉钉子精神______工作局面。","options":["揭开","翻开","掀开","打开"],"answer":3,"explanation":"「打开」与「局面」搭配得当。「打开局面」为固定搭配；「翻开」用于书页；「揭开」多与谜底、序幕搭配；「掀开」用于盖子、帘子。故选D。","__sub":"选词填空"},{"id":"yy-18117","module":"yanyu","diff":1,"exam":"国考","prompt":"入冬以来，越是众声喧哗，越需要______共识，渔民把大家的心拢到一起。","options":["凝固","冻住","凝聚","凝结"],"answer":2,"explanation":"「凝聚」与「共识」搭配得当。「凝聚共识」为固定搭配；「凝固」「冻住」「凝结」均为物理状态变化，用于抽象共识不当。故选C。","__sub":"选词填空"},{"id":"yy-18118","module":"yanyu","diff":1,"exam":"国考","prompt":"今年以来，急难险重任务面前，图书管理员主动______最重的责任。","options":["抬起","背起","挑起","扛起"],"answer":3,"explanation":"「扛起」与「责任」搭配得当。「扛起责任」为惯用搭配；「背起」多与行囊、伤员搭配；「挑起」多与担子、重担搭配；「抬起」为具体动作。故选D。","__sub":"选词填空"},{"id":"yy-18119","module":"yanyu","diff":3,"exam":"国考","prompt":"近年来，市场不是法外之地，网格员以制度______交易秩序。","options":["规定","规范","规正","规整"],"answer":1,"explanation":"「规范」与「秩序」搭配得当。「规范秩序」为惯用搭配；「规定」为名词或动词制定；「规整」指整齐；「规正」指匡正。故选B。","__sub":"选词填空"},{"id":"yy-18120","module":"yanyu","diff":3,"exam":"国考","prompt":"盛夏时节，停车难是城市治理的老大难，社区工作者用共享思维______了这一难题。","options":["解释","解开","解冻","破解"],"answer":3,"explanation":"「破解」与「难题」搭配得当。「破解难题」为固定搭配；「解开」多与绳结、心结搭配；「解冻」用于资产、关系；「解释」为说明缘由。故选D。","__sub":"选词填空"},{"id":"yy-18121","module":"yanyu","diff":1,"exam":"国考","prompt":"盛夏时节，新区建设的宏伟蓝图已经展开，驻村干部正把一张张蓝图变成施工图。","options":["绘就","修筑","耕耘","编织"],"answer":0,"explanation":"「绘就」与「蓝图」搭配得当。「绘就蓝图」为惯用搭配；「修筑」用于道路工事；「耕耘」用于田地或比喻辛勤付出；「编织」多与梦想、纽带搭配，与蓝图不搭。故选A。","__sub":"选词填空"},{"id":"yy-18122","module":"yanyu","diff":1,"exam":"事业编","prompt":"盛夏时节，二十年只做一件事，科研人员在细分领域里做到极致。","options":["深挖","深耕","深掘","深钻"],"answer":1,"explanation":"「深耕」与「领域」搭配得当。「深耕领域」为惯用比喻搭配；「深挖」多与线索搭配；「深钻」「深掘」非规范。故选B。","__sub":"选词填空"},{"id":"yy-18123","module":"yanyu","diff":2,"exam":"国考","prompt":"开春以来，城乡公共服务仍有落差，公交司机以实策逐步______差距。","options":["缩减","减少","缩小","减小"],"answer":2,"explanation":"「缩小」与「差距」搭配得当。「缩小差距」为固定搭配；「减少」多与数量搭配；「缩减」多与开支、编制搭配；「减小」多与阻力、噪音搭配。故选C。","__sub":"选词填空"},{"id":"yy-18124","module":"yanyu","diff":1,"exam":"教师编","prompt":"一段时间以来，脱贫不是终点，治沙工人多措并举______脱贫成果。","options":["巩固","加固","凝固","稳固"],"answer":0,"explanation":"「巩固」与「成果」搭配得当。「巩固成果」为固定搭配；「稳固」为形容词或使稳固；「加固」用于建筑堤坝；「凝固」为物理变化。故选A。","__sub":"选词填空"},{"id":"yy-18125","module":"yanyu","diff":1,"exam":"事业编","prompt":"盛夏时节，政府、市场、社会同向发力，电力工人让各方______成强大合力。","options":["汇集","聚合","汇聚","汇合"],"answer":2,"explanation":"「汇聚」与「合力」搭配得当。「汇聚合力」为惯用搭配；「汇合」指水流等聚集；「汇集」指集中收集；「聚合」为化学或物理过程。故选C。","__sub":"选词填空"},{"id":"yy-18126","module":"yanyu","diff":2,"exam":"国考","prompt":"这些年，一次次说到做到，教师用行动______了群众的信任。","options":["获得","换取","赢得","博得"],"answer":2,"explanation":"「赢得」与「信任」搭配得当。「赢得信任」为固定搭配，强调经努力而获得；「获得」中性；「博得」多与同情、喝彩搭配；「换取」含交换义。故选C。","__sub":"选词填空"},{"id":"yy-18127","module":"yanyu","diff":3,"exam":"省考","prompt":"这些年，市场不是法外之地，青年学子以制度______交易秩序。","options":["规定","规范","规正","规整"],"answer":1,"explanation":"「规范」与「秩序」搭配得当。「规范秩序」为惯用搭配；「规定」为名词或动词制定；「规整」指整齐；「规正」指匡正。故选B。","__sub":"选词填空"},{"id":"yy-18128","module":"yanyu","diff":1,"exam":"省考","prompt":"岁末年初，让监督机制长出牙齿，快递员把制度笼子越扎越紧。","options":["修理","修复","健全","修葺"],"answer":2,"explanation":"「健全」与「机制」搭配得当。「健全机制」为固定搭配，使完善；「修理」「修复」「修葺」均指具体物件的修补，与机制不搭。故选C。","__sub":"选词填空"},{"id":"yy-18129","module":"yanyu","diff":2,"exam":"国考","prompt":"初秋时节，数据孤岛必须连起来，文旅部门下决心______部门间的壁垒。","options":["打破","打碎","砸破","击碎"],"answer":0,"explanation":"「打破」与「壁垒」搭配得当。「打破壁垒」为固定搭配；「打碎」「砸破」「击碎」均为具体物理动作。故选A。","__sub":"选词填空"},{"id":"yy-18130","module":"yanyu","diff":1,"exam":"省考","prompt":"一段时间以来，新区建设的宏伟蓝图已经展开，手工艺人正把一张张蓝图变成施工图。","options":["修筑","绘就","编织","耕耘"],"answer":1,"explanation":"「绘就」与「蓝图」搭配得当。「绘就蓝图」为惯用搭配；「修筑」用于道路工事；「耕耘」用于田地或比喻辛勤付出；「编织」多与梦想、纽带搭配，与蓝图不搭。故选B。","__sub":"选词填空"},{"id":"yy-18131","module":"yanyu","diff":3,"exam":"省考","prompt":"初秋时节，改革红利持续显现，市场活力不断，工程师信心更足。","options":["爆发","突发","迸发","暴发"],"answer":2,"explanation":"「迸发」与「活力」搭配得当。「迸发活力」为惯用搭配；「爆发」多用于战争、疫情或力量；「突发」多与事件搭配；「暴发」多用于疫情或含贬义。故选C。","__sub":"选词填空"},{"id":"yy-18132","module":"yanyu","diff":1,"exam":"国考","prompt":"盛夏时节，改革到了深水区，治沙工人以钉钉子精神______工作局面。","options":["揭开","翻开","掀开","打开"],"answer":3,"explanation":"「打开」与「局面」搭配得当。「打开局面」为固定搭配；「翻开」用于书页；「揭开」多与谜底、序幕搭配；「掀开」用于盖子、帘子。故选D。","__sub":"选词填空"},{"id":"yy-18133","module":"yanyu","diff":2,"exam":"省考","prompt":"眼下，危难时刻冲得上去，环卫工人的行动______了共产党员的担当。","options":["显露","暴露","显摆","彰显"],"answer":3,"explanation":"「彰显」与「担当」搭配得当。「彰显担当」为固定搭配，褒义；「显摆」为口语含贬义；「显露」中性；「暴露」多含贬义。故选D。","__sub":"选词填空"},{"id":"yy-18134","module":"yanyu","diff":2,"exam":"事业编","prompt":"眼下，让新业态释放新动能，法官在制度创新上先行先试。","options":["发动","激发","点燃","引爆"],"answer":1,"explanation":"「激发」与「动能」搭配得当。「激发动能」为惯用搭配；「发动」多与机器、群众搭配；「点燃」多与激情搭配；「引爆」多与话题、舆论搭配且含突然义。故选B。","__sub":"选词填空"},{"id":"yy-18135","module":"yanyu","diff":3,"exam":"省考","prompt":"连日来，让新业态释放新动能，医护人员在制度创新上先行先试。","options":["点燃","激发","引爆","发动"],"answer":1,"explanation":"「激发」与「动能」搭配得当。「激发动能」为惯用搭配；「发动」多与机器、群众搭配；「点燃」多与激情搭配；「引爆」多与话题、舆论搭配且含突然义。故选B。","__sub":"选词填空"},{"id":"yy-18136","module":"yanyu","diff":1,"exam":"国考","prompt":"连日来，危难时刻冲得上去，青年学子的行动______了共产党员的担当。","options":["彰显","显摆","显露","暴露"],"answer":0,"explanation":"「彰显」与「担当」搭配得当。「彰显担当」为固定搭配，褒义；「显摆」为口语含贬义；「显露」中性；「暴露」多含贬义。故选A。","__sub":"选词填空"},{"id":"yy-18137","module":"yanyu","diff":1,"exam":"省考","prompt":"今年以来，齐抓共管不是一句口号，环卫工人推动齐抓共管合力。","options":["形成","成型","成立","成形"],"answer":0,"explanation":"「形成」与「合力」搭配得当。「形成合力」为固定搭配；「成形」「成型」指具形；「成立」多与组织搭配。故选A。","__sub":"选词填空"},{"id":"yy-18138","module":"yanyu","diff":2,"exam":"国考","prompt":"眼下，把风险挺在前面，社区工作者织密织牢安全网。","options":["防守","防备","防范","提防"],"answer":2,"explanation":"「防范」与「风险」搭配得当。「防范风险」为固定搭配；「防备」侧重有所准备；「提防」为口语化小心在意；「防守」多用于比赛、军事。故选C。","__sub":"选词填空"},{"id":"yy-18139","module":"yanyu","diff":1,"exam":"国考","prompt":"盛夏时节，齐抓共管不是一句口号，老党员推动齐抓共管合力。","options":["成形","成立","形成","成型"],"answer":2,"explanation":"「形成」与「合力」搭配得当。「形成合力」为固定搭配；「成形」「成型」指具形；「成立」多与组织搭配。故选C。","__sub":"选词填空"},{"id":"yy-18140","module":"yanyu","diff":3,"exam":"事业编","prompt":"今年以来，二十年只做一件事，教师在细分领域里做到极致。","options":["深挖","深掘","深耕","深钻"],"answer":2,"explanation":"「深耕」与「领域」搭配得当。「深耕领域」为惯用比喻搭配；「深挖」多与线索搭配；「深钻」「深掘」非规范。故选C。","__sub":"选词填空"},{"id":"yy-18141","module":"yanyu","diff":2,"exam":"事业编","prompt":"近年来，安全底线不可逾越，治沙工人24小时轮班值守。","options":["看守","把守","镇守","坚守"],"answer":3,"explanation":"「坚守」与「底线」搭配得当。「坚守底线」为固定搭配；「看守」「把守」「镇守」均指具体看护动作，多用于人员、关口、城池。故选D。","__sub":"选词填空"},{"id":"yy-18142","module":"yanyu","diff":2,"exam":"省考","prompt":"近期，汛期将至，设计师对辖区地质灾害隐患逐点______。","options":["普查","检察","检查","排查"],"answer":3,"explanation":"「排查」与「隐患」搭配得当。「排查隐患」为固定搭配，强调逐一清查；「检查」为一般查看；「检察」为法律监督专用；「普查」为全面调查登记。故选D。","__sub":"选词填空"},{"id":"yy-18143","module":"yanyu","diff":2,"exam":"省考","prompt":"初秋时节，每一起案件都关乎群众对法治的信仰，果农用公正裁判______正义。","options":["防御","保卫","捍卫","护卫"],"answer":2,"explanation":"「捍卫」与「公平」搭配得当。「捍卫公平」为书面惯用搭配；「保卫」多与祖国、和平搭配；「护卫」为护送守卫；「防御」用于军事、疫情。故选C。","__sub":"选词填空"},{"id":"yy-18144","module":"yanyu","diff":2,"exam":"省考","prompt":"近年来，纪律规矩挺在前面，驻村干部始终______纪律底线。","options":["把守","遵守","看守","严守"],"answer":3,"explanation":"「严守」与「底线」搭配得当。「严守底线」为固定搭配；「看守」「把守」为具体看护；「遵守」多与规则、法律搭配。故选D。","__sub":"选词填空"},{"id":"yy-18145","module":"yanyu","diff":2,"exam":"国考","prompt":"岁末年初，数据孤岛必须连起来，电力工人下决心______部门间的壁垒。","options":["打碎","打破","砸破","击碎"],"answer":1,"explanation":"「打破」与「壁垒」搭配得当。「打破壁垒」为固定搭配；「打碎」「砸破」「击碎」均为具体物理动作。故选B。","__sub":"选词填空"},{"id":"yy-18146","module":"yanyu","diff":1,"exam":"教师编","prompt":"一段时间以来，发展为了人民，治沙工人把一件件民生实事办到群众心坎上，持续______福祉。","options":["增添","增殖","增加","增进"],"answer":3,"explanation":"「增进」与「民生」搭配得当。「增进福祉」为固定搭配，题干以民生统称；「增加」多与数量搭配；「增添」多与色彩、麻烦搭配；「增殖」为生物学用语。故选D。","__sub":"选词填空"},{"id":"yy-18147","module":"yanyu","diff":2,"exam":"省考","prompt":"一段时间以来，市场细胞活跃起来，果农让经济肌体活力。","options":["填满","充满","装满","塞满"],"answer":1,"explanation":"「充满」与「活力」搭配得当。「充满活力」为固定搭配；「填满」「塞满」「装满」均为具体动作，用于抽象活力不当。故选B。","__sub":"选词填空"},{"id":"yy-18148","module":"yanyu","diff":2,"exam":"省考","prompt":"盛夏时节，传统村落保护性开发，果农既富了口袋，也______了乡愁。","options":["留住","拘留","截留","扣留"],"answer":0,"explanation":"「留住」与「乡愁」搭配得当。「留住乡愁」为惯用表达；「扣留」「拘留」「截留」均为法律或强制扣押义，感情色彩不合。故选A。","__sub":"选词填空"},{"id":"yy-18149","module":"yanyu","diff":3,"exam":"国考","prompt":"连日来，让监督机制长出牙齿，驻村干部把制度笼子越扎越紧。","options":["健全","修复","修葺","修理"],"answer":0,"explanation":"「健全」与「机制」搭配得当。「健全机制」为固定搭配，使完善；「修理」「修复」「修葺」均指具体物件的修补，与机制不搭。故选A。","__sub":"选词填空"},{"id":"yy-18150","module":"yanyu","diff":1,"exam":"国考","prompt":"近年来，把监督防线扎到最基层，公交司机走村入户听民声。","options":["织补","缝密","织密","织厚"],"answer":2,"explanation":"「织密」与「防线」搭配得当。「织密防线」为惯用搭配；「织厚」「缝密」非规范搭配；「织补」指修补织物。故选C。","__sub":"选词填空"},{"id":"yy-18151","module":"yanyu","diff":2,"exam":"国考","prompt":"入冬以来，改革红利持续显现，市场活力不断，广大建设者信心更足。","options":["爆发","突发","暴发","迸发"],"answer":3,"explanation":"「迸发」与「活力」搭配得当。「迸发活力」为惯用搭配；「爆发」多用于战争、疫情或力量；「突发」多与事件搭配；「暴发」多用于疫情或含贬义。故选D。","__sub":"选词填空"},{"id":"yy-18152","module":"yanyu","diff":2,"exam":"国考","prompt":"盛夏时节，汛期将至，志愿者们对辖区地质灾害隐患逐点______。","options":["检查","普查","检察","排查"],"answer":3,"explanation":"「排查」与「隐患」搭配得当。「排查隐患」为固定搭配，强调逐一清查；「检查」为一般查看；「检察」为法律监督专用；「普查」为全面调查登记。故选D。","__sub":"选词填空"},{"id":"yy-18153","module":"yanyu","diff":1,"exam":"国考","prompt":"一段时间以来，小哨兵大作用，程序员让基层网格______更大作用。","options":["表现","发挥","施展","发扬"],"answer":1,"explanation":"「发挥」与「作用」搭配得当。「发挥作用」为固定搭配；「发扬」多与传统搭配；「施展」多与才华、拳脚搭配。故选B。","__sub":"选词填空"},{"id":"yy-18154","module":"yanyu","diff":1,"exam":"省考","prompt":"岁末年初，把消费潜力转化为增长实绩，科研人员拿出了实招硬招。","options":["发泄","喷发","散发","释放"],"answer":3,"explanation":"「释放」与「潜力」搭配得当。「释放潜力」为固定搭配；「发泄」含贬义多与情绪搭配；「散发」多与气味、气息搭配；「喷发」用于火山或比喻爆发。故选D。","__sub":"选词填空"},{"id":"yy-18155","module":"yanyu","diff":1,"exam":"国考","prompt":"这些年，危难时刻冲得上去，科研人员的行动______了共产党员的担当。","options":["显摆","暴露","彰显","显露"],"answer":2,"explanation":"「彰显」与「担当」搭配得当。「彰显担当」为固定搭配，褒义；「显摆」为口语含贬义；「显露」中性；「暴露」多含贬义。故选C。","__sub":"选词填空"},{"id":"yy-18156","module":"yanyu","diff":3,"exam":"省考","prompt":"盛夏时节，一年一度的民生大考结束，广大建设者向群众______了温暖的答卷。","options":["上缴","交出","呈报","递交"],"answer":1,"explanation":"「交出」与「答卷」搭配得当。「交出答卷」为惯用搭配；「递交」多与申请、辞呈搭配；「呈报」多与公文搭配且含上下级意味；「上缴」多与款项、物品搭配。故选B。","__sub":"选词填空"},{"id":"yy-18157","module":"yanyu","diff":2,"exam":"事业编","prompt":"入冬以来，从受理到反馈全流程留痕，医护人员以数字化手段______管理闭环。","options":["搭圈","构建","构画","圈画"],"answer":1,"explanation":"「构建」与「闭环」搭配得当。「构建闭环」为惯用搭配；其余选项均非规范搭配。故选B。","__sub":"选词填空"},{"id":"yy-18158","module":"yanyu","diff":2,"exam":"国考","prompt":"眼下，让新业态释放新动能，医护人员在制度创新上先行先试。","options":["激发","引爆","发动","点燃"],"answer":0,"explanation":"「激发」与「动能」搭配得当。「激发动能」为惯用搭配；「发动」多与机器、群众搭配；「点燃」多与激情搭配；「引爆」多与话题、舆论搭配且含突然义。故选A。","__sub":"选词填空"},{"id":"yy-18159","module":"yanyu","diff":1,"exam":"事业编","prompt":"岁末年初，初心如磐，使命在肩，手工艺人把承诺落到一件件小事上。","options":["履行","旅行","践行","执行"],"answer":2,"explanation":"「践行」与「使命」搭配得当。「践行使命」为固定搭配；「履行」多与职责、义务、合同搭配；「执行」多与命令、判决、任务搭配；「旅行」为出行义。故选C。","__sub":"选词填空"},{"id":"yy-18160","module":"yanyu","diff":3,"exam":"教师编","prompt":"今年以来，产业发展的根基越牢，抗风险的能力就越强，非遗传承人深谙此理，先把根基打扎实。","options":["敲打","铺设","垒砌","夯实"],"answer":3,"explanation":"「夯实」与「根基」搭配得当。「夯实根基」为固定搭配；「敲打」为具体动作；「铺设」用于管线、路面；「垒砌」用于砖石墙体。故选D。","__sub":"选词填空"},{"id":"yy-18161","module":"yanyu","diff":3,"exam":"国考","prompt":"开春以来，放宽准入激发创业热情，教师让创造活力。","options":["涌流","淌出","涌出","流出"],"answer":0,"explanation":"「涌流」与「活力」搭配得当。「活力涌流」为惯用表达；「流出」「淌出」「涌出」均用于液体且为具体动作。故选A。","__sub":"选词填空"},{"id":"yy-18162","module":"yanyu","diff":2,"exam":"事业编","prompt":"入冬以来，金杯银杯不如老百姓的口碑，果农把每件小事都当大事办。","options":["创立","设立","建立","树立"],"answer":3,"explanation":"「树立」与「口碑」搭配得当。「树立口碑」为惯用搭配；「建立」多与制度、关系搭配；「设立」多与机构搭配；「创立」多与学说、品牌搭配。故选D。","__sub":"选词填空"},{"id":"yy-18163","module":"yanyu","diff":1,"exam":"教师编","prompt":"今年以来，一二三产融合发展，基层干部推动产业链不断延伸。","options":["伸长","延长","拉长","延伸"],"answer":3,"explanation":"「延伸」与「链条」搭配得当。「链条延伸」为惯用搭配；「伸长」「拉长」「延长」多用于具体长度或时间。故选D。","__sub":"选词填空"},{"id":"yy-18164","module":"yanyu","diff":1,"exam":"事业编","prompt":"初秋时节，让公共服务覆盖城乡，图书管理员持续______政策体系。","options":["完缮","补完","修完","完善"],"answer":3,"explanation":"「完善」与「体系」搭配得当。「完善体系」为固定搭配；「完缮」「修完」「补完」均非规范搭配。故选D。","__sub":"选词填空"},{"id":"yy-18165","module":"yanyu","diff":2,"exam":"省考","prompt":"近期，乡情是最深的牵挂，设计师以商会为平台______情感纽带。","options":["织牢","绑牢","捆牢","系牢"],"answer":0,"explanation":"「织牢」与「纽带」搭配得当。「织牢纽带」为惯用比喻搭配；「系牢」「捆牢」「绑牢」均为具体系绑动作。故选A。","__sub":"选词填空"},{"id":"yy-18166","module":"yanyu","diff":2,"exam":"国考","prompt":"盛夏时节，城乡公共服务仍有落差，科研人员以实策逐步______差距。","options":["减少","减小","缩小","缩减"],"answer":2,"explanation":"「缩小」与「差距」搭配得当。「缩小差距」为固定搭配；「减少」多与数量搭配；「缩减」多与开支、编制搭配；「减小」多与阻力、噪音搭配。故选C。","__sub":"选词填空"},{"id":"yy-18167","module":"yanyu","diff":2,"exam":"国考","prompt":"近年来，几十年如一日，博物馆讲解员在平凡岗位上______着为民初心。","options":["保守","把守","守卫","坚守"],"answer":3,"explanation":"「坚守」与「初心」搭配得当。「坚守初心」为固定搭配；「保守」多与秘密搭配；「守卫」用于边疆、家园；「把守」用于关口。故选D。","__sub":"选词填空"},{"id":"yy-18168","module":"yanyu","diff":2,"exam":"医疗编","prompt":"一段时间以来，众人的事情由众人商量，社区规划师把各方______到规划图上。","options":["收拢","归拢","凝聚","聚拢"],"answer":2,"explanation":"「凝聚」与「智慧」搭配得当。「凝聚智慧」为惯用搭配；「聚拢」「收拢」「归拢」均为具体收拢动作，用于抽象智慧不当。故选C。","__sub":"选词填空"},{"id":"yy-18169","module":"yanyu","diff":1,"exam":"医疗编","prompt":"初秋时节，众人的事情由众人商量，工程师把各方______到规划图上。","options":["凝聚","收拢","聚拢","归拢"],"answer":0,"explanation":"「凝聚」与「智慧」搭配得当。「凝聚智慧」为惯用搭配；「聚拢」「收拢」「归拢」均为具体收拢动作，用于抽象智慧不当。故选A。","__sub":"选词填空"},{"id":"yy-18170","module":"yanyu","diff":3,"exam":"教师编","prompt":"近期，一二三产融合发展，民警推动产业链不断延伸。","options":["延长","拉长","伸长","延伸"],"answer":3,"explanation":"「延伸」与「链条」搭配得当。「链条延伸」为惯用搭配；「伸长」「拉长」「延长」多用于具体长度或时间。故选D。","__sub":"选词填空"},{"id":"yy-18171","module":"yanyu","diff":1,"exam":"事业编","prompt":"眼下，筑起生态安全屏障，茶农让青山常在绿水长流。","options":["筑牢","砌牢","拴牢","锁牢"],"answer":0,"explanation":"「筑牢」与「屏障」搭配得当。「筑牢屏障」为惯用搭配；「砌牢」用于砖石；「锁牢」「拴牢」用于器物。故选A。","__sub":"选词填空"},{"id":"yy-18172","module":"yanyu","diff":2,"exam":"事业编","prompt":"一段时间以来，民生实事清单公示上墙，博物馆讲解员一件一件______承诺。","options":["实现","达成","兑现","完成"],"answer":2,"explanation":"「兑现」与「承诺」搭配得当。「兑现承诺」为固定搭配；「实现」多与梦想、目标搭配；「完成」多与任务搭配；「达成」多与协议搭配。故选C。","__sub":"选词填空"},{"id":"yy-18173","module":"yanyu","diff":2,"exam":"国考","prompt":"近年来，景区客流高峰来临，工程师全员上岗______游览秩序。","options":["维持","维护","保护","护卫"],"answer":1,"explanation":"「维护」与「秩序」搭配得当。「维护秩序」为固定搭配；「维持」多与生活、现状搭配；「保护」多与权益、环境搭配；「护卫」用于人员、目标。故选B。","__sub":"选词填空"},{"id":"yy-18174","module":"yanyu","diff":1,"exam":"事业编","prompt":"近期，减税降费政策落地，教师让企业真切感受到红利。","options":["散发","发射","发放","释放"],"answer":3,"explanation":"「释放」与「红利」搭配得当。「释放红利」为惯用搭配；「发放」多与物资、贷款搭配；「散发」多与气味搭配；「发射」用于子弹、卫星。故选D。","__sub":"选词填空"},{"id":"yy-18175","module":"yanyu","diff":1,"exam":"省考","prompt":"岁末年初，急难险重任务面前，非遗传承人主动______最重的责任。","options":["挑起","抬起","背起","扛起"],"answer":3,"explanation":"「扛起」与「责任」搭配得当。「扛起责任」为惯用搭配；「背起」多与行囊、伤员搭配；「挑起」多与担子、重担搭配；「抬起」为具体动作。故选D。","__sub":"选词填空"},{"id":"yy-18176","module":"yanyu","diff":2,"exam":"国考","prompt":"今年以来，把风险挺在前面，茶农织密织牢安全网。","options":["提防","防守","防备","防范"],"answer":3,"explanation":"「防范」与「风险」搭配得当。「防范风险」为固定搭配；「防备」侧重有所准备；「提防」为口语化小心在意；「防守」多用于比赛、军事。故选D。","__sub":"选词填空"},{"id":"yy-18177","module":"yanyu","diff":1,"exam":"国考","prompt":"初秋时节，产业发展的根基越牢，抗风险的能力就越强，法官深谙此理，先把根基打扎实。","options":["敲打","垒砌","夯实","铺设"],"answer":2,"explanation":"「夯实」与「根基」搭配得当。「夯实根基」为固定搭配；「敲打」为具体动作；「铺设」用于管线、路面；「垒砌」用于砖石墙体。故选C。","__sub":"选词填空"},{"id":"yy-18178","module":"yanyu","diff":1,"exam":"国考","prompt":"今年以来，面对转型路上的重重难关，调解员迎难而上，把一个个难关逐一______。","options":["化解","克服","破除","攻克"],"answer":3,"explanation":"「攻克」与「难关」搭配得当。「攻克难关」为固定搭配，强调付出努力战而胜之；「克服」多与困难、缺点搭配；「破除」多与迷信、藩篱搭配；「化解」多与矛盾、风险搭配。故选D。","__sub":"选词填空"},{"id":"yy-18179","module":"yanyu","diff":1,"exam":"国考","prompt":"近期，脱贫不是终点，图书管理员多措并举______脱贫成果。","options":["稳固","巩固","凝固","加固"],"answer":1,"explanation":"「巩固」与「成果」搭配得当。「巩固成果」为固定搭配；「稳固」为形容词或使稳固；「加固」用于建筑堤坝；「凝固」为物理变化。故选B。","__sub":"选词填空"},{"id":"yy-18180","module":"yanyu","diff":3,"exam":"教师编","prompt":"岁末年初，发展为了人民，环卫工人把一件件民生实事办到群众心坎上，持续______福祉。","options":["增加","增进","增殖","增添"],"answer":1,"explanation":"「增进」与「民生」搭配得当。「增进福祉」为固定搭配，题干以民生统称；「增加」多与数量搭配；「增添」多与色彩、麻烦搭配；「增殖」为生物学用语。故选B。","__sub":"选词填空"},{"id":"yy-18181","module":"yanyu","diff":1,"exam":"国考","prompt":"岁末年初，产业发展的根基越牢，抗风险的能力就越强，社区规划师深谙此理，先把根基打扎实。","options":["夯实","垒砌","敲打","铺设"],"answer":0,"explanation":"「夯实」与「根基」搭配得当。「夯实根基」为固定搭配；「敲打」为具体动作；「铺设」用于管线、路面；「垒砌」用于砖石墙体。故选A。","__sub":"选词填空"},{"id":"yy-18182","module":"yanyu","diff":2,"exam":"国考","prompt":"入冬以来，一年一度的民生大考结束，博物馆讲解员向群众______了温暖的答卷。","options":["递交","交出","上缴","呈报"],"answer":1,"explanation":"「交出」与「答卷」搭配得当。「交出答卷」为惯用搭配；「递交」多与申请、辞呈搭配；「呈报」多与公文搭配且含上下级意味；「上缴」多与款项、物品搭配。故选B。","__sub":"选词填空"},{"id":"yy-18183","module":"yanyu","diff":2,"exam":"国考","prompt":"一段时间以来，城乡公共服务仍有落差，市场监管部门以实策逐步______差距。","options":["缩减","减少","减小","缩小"],"answer":3,"explanation":"「缩小」与「差距」搭配得当。「缩小差距」为固定搭配；「减少」多与数量搭配；「缩减」多与开支、编制搭配；「减小」多与阻力、噪音搭配。故选D。","__sub":"选词填空"},{"id":"yy-18184","module":"yanyu","diff":1,"exam":"省考","prompt":"近年来，从受理到反馈全流程留痕，审计人员以数字化手段______管理闭环。","options":["圈画","构建","构画","搭圈"],"answer":1,"explanation":"「构建」与「闭环」搭配得当。「构建闭环」为惯用搭配；其余选项均非规范搭配。故选B。","__sub":"选词填空"},{"id":"yy-18185","module":"yanyu","diff":1,"exam":"省考","prompt":"这些年，每个孩子都有闪光点，老党员善于______学生潜能。","options":["挖出","掘取","挖掘","开采"],"answer":2,"explanation":"「挖掘」与「潜能」搭配得当。「挖掘潜能」为固定搭配；「挖出」「掘取」为具体动作；「开采」用于矿产。故选C。","__sub":"选词填空"},{"id":"yy-18186","module":"yanyu","diff":1,"exam":"事业编","prompt":"近年来，市场细胞活跃起来，渔民让经济肌体活力。","options":["装满","填满","充满","塞满"],"answer":2,"explanation":"「充满」与「活力」搭配得当。「充满活力」为固定搭配；「填满」「塞满」「装满」均为具体动作，用于抽象活力不当。故选C。","__sub":"选词填空"},{"id":"yy-18187","module":"yanyu","diff":2,"exam":"国考","prompt":"眼下，筑起生态安全屏障，青年学子让青山常在绿水长流。","options":["砌牢","锁牢","筑牢","拴牢"],"answer":2,"explanation":"「筑牢」与「屏障」搭配得当。「筑牢屏障」为惯用搭配；「砌牢」用于砖石；「锁牢」「拴牢」用于器物。故选C。","__sub":"选词填空"},{"id":"yy-18188","module":"yanyu","diff":1,"exam":"国考","prompt":"入冬以来，一二三产融合发展，科研人员推动产业链不断延伸。","options":["延伸","伸长","拉长","延长"],"answer":0,"explanation":"「延伸」与「链条」搭配得当。「链条延伸」为惯用搭配；「伸长」「拉长」「延长」多用于具体长度或时间。故选A。","__sub":"选词填空"},{"id":"yy-18189","module":"yanyu","diff":2,"exam":"国考","prompt":"连日来，卡脖子技术亟待攻坚，执法人员集中力量______一个个瓶颈。","options":["突破","冲破","撞破","捅破"],"answer":0,"explanation":"「突破」与「瓶颈」搭配得当。「突破瓶颈」为固定搭配；「冲破」多与封锁、束缚搭配；「撞破」「捅破」为具体动作或与窗户纸等搭配。故选A。","__sub":"选词填空"},{"id":"yy-18190","module":"yanyu","diff":2,"exam":"国考","prompt":"今年以来，绿水青山就是金山银山，消防员代代接力______绿色生态。","options":["守护","守望","守候","看守"],"answer":0,"explanation":"「守护」与「生态」搭配得当。「守护生态」为惯用搭配，含珍视呵护义；「看守」用于财物、门户；「守候」指等待；「守望」指瞭望盼望。故选A。","__sub":"选词填空"},{"id":"yy-18191","module":"yanyu","diff":2,"exam":"国考","prompt":"初秋时节，数据孤岛必须连起来，图书管理员下决心______部门间的壁垒。","options":["砸破","打碎","打破","击碎"],"answer":2,"explanation":"「打破」与「壁垒」搭配得当。「打破壁垒」为固定搭配；「打碎」「砸破」「击碎」均为具体物理动作。故选C。","__sub":"选词填空"},{"id":"yy-18192","module":"yanyu","diff":3,"exam":"教师编","prompt":"入冬以来，两岸同胞亲情割不断，志愿者们为青年交流______心灵心桥。","options":["铺设","修筑","架起","垒砌"],"answer":2,"explanation":"「架起」与「心桥」搭配得当。「架起心桥」为惯用比喻搭配；「修筑」用于道路工程；「垒砌」用于砖石；「铺设」用于管线轨道。故选C。","__sub":"选词填空"},{"id":"yy-18193","module":"yanyu","diff":1,"exam":"国考","prompt":"近期，面对转型路上的重重难关，渔民迎难而上，把一个个难关逐一______。","options":["克服","化解","破除","攻克"],"answer":3,"explanation":"「攻克」与「难关」搭配得当。「攻克难关」为固定搭配，强调付出努力战而胜之；「克服」多与困难、缺点搭配；「破除」多与迷信、藩篱搭配；「化解」多与矛盾、风险搭配。故选D。","__sub":"选词填空"},{"id":"yy-18194","module":"yanyu","diff":1,"exam":"省考","prompt":"眼下，让新业态释放新动能，茶农在制度创新上先行先试。","options":["激发","引爆","发动","点燃"],"answer":0,"explanation":"「激发」与「动能」搭配得当。「激发动能」为惯用搭配；「发动」多与机器、群众搭配；「点燃」多与激情搭配；「引爆」多与话题、舆论搭配且含突然义。故选A。","__sub":"选词填空"},{"id":"yy-18195","module":"yanyu","diff":2,"exam":"国考","prompt":"这些年，春潮拍岸千帆竞，农技人员感受到创新活力。","options":["涌动","淌动","涌出","流出"],"answer":0,"explanation":"「涌动」与「活力」搭配得当。「活力涌动」为惯用表达；「涌出」「流出」为具体动作；「淌动」非规范。故选A。","__sub":"选词填空"},{"id":"yy-18196","module":"yanyu","diff":3,"exam":"省考","prompt":"岁末年初，把风险挺在前面，科研人员织密织牢安全网。","options":["防范","防备","防守","提防"],"answer":0,"explanation":"「防范」与「风险」搭配得当。「防范风险」为固定搭配；「防备」侧重有所准备；「提防」为口语化小心在意；「防守」多用于比赛、军事。故选A。","__sub":"选词填空"},{"id":"yy-18197","module":"yanyu","diff":3,"exam":"省考","prompt":"今年以来，一揽子政策精准落地，调解员着力______市场信心。","options":["振作","提起","提振","鼓动"],"answer":2,"explanation":"「提振」与「信心」搭配得当。「提振信心」为固定搭配；「提起」多与精神、话题搭配；「振作」为不及物动词；「鼓动」含煽动义。故选C。","__sub":"选词填空"},{"id":"yy-18198","module":"yanyu","diff":2,"exam":"国考","prompt":"盛夏时节，誓师大会上，老党员精神斗志，誓言响彻训练场。","options":["高扬","高涨","高昂","昂扬"],"answer":3,"explanation":"「昂扬」与「斗志」搭配得当。「斗志昂扬」为固定成语；「高昂」多与情绪、价格搭配；「高涨」多与热情搭配；「高扬」多与旗帜搭配。故选D。","__sub":"选词填空"},{"id":"yy-18199","module":"yanyu","diff":2,"exam":"省考","prompt":"岁末年初，一网通办让数据多跑路，执法人员以流程再造______政务效能。","options":["拔高","提升","抬高","提高"],"answer":1,"explanation":"「提升」与「效能」搭配得当。「提升效能」为固定搭配；「提高」多与水平、价格搭配；「拔高」含刻意抬升义；「抬高」多与价格、身价搭配。故选B。","__sub":"选词填空"},{"id":"yy-18200","module":"yanyu","diff":1,"exam":"事业编","prompt":"盛夏时节，市场不是法外之地，青年学子以制度______交易秩序。","options":["规范","规定","规正","规整"],"answer":0,"explanation":"「规范」与「秩序」搭配得当。「规范秩序」为惯用搭配；「规定」为名词或动词制定；「规整」指整齐；「规正」指匡正。故选A。","__sub":"选词填空"},{"id":"yy-18201","module":"yanyu","diff":2,"exam":"国考","prompt":"连日来，几十年如一日，环卫工人在平凡岗位上______着为民初心。","options":["坚守","保守","守卫","把守"],"answer":0,"explanation":"「坚守」与「初心」搭配得当。「坚守初心」为固定搭配；「保守」多与秘密搭配；「守卫」用于边疆、家园；「把守」用于关口。故选A。","__sub":"选词填空"},{"id":"yy-18202","module":"yanyu","diff":2,"exam":"国考","prompt":"近期，金杯银杯不如老百姓的口碑，图书管理员把每件小事都当大事办。","options":["创立","设立","树立","建立"],"answer":2,"explanation":"「树立」与「口碑」搭配得当。「树立口碑」为惯用搭配；「建立」多与制度、关系搭配；「设立」多与机构搭配；「创立」多与学说、品牌搭配。故选C。","__sub":"选词填空"},{"id":"yy-18203","module":"yanyu","diff":2,"exam":"国考","prompt":"初秋时节，乡情是最深的牵挂，快递员以商会为平台______情感纽带。","options":["织牢","绑牢","捆牢","系牢"],"answer":0,"explanation":"「织牢」与「纽带」搭配得当。「织牢纽带」为惯用比喻搭配；「系牢」「捆牢」「绑牢」均为具体系绑动作。故选A。","__sub":"选词填空"},{"id":"yy-18204","module":"yanyu","diff":2,"exam":"国考","prompt":"一段时间以来，跳出一时一地看发展，驻村干部着力______开放共赢的新格局。","options":["搭造","架造","构建","构作"],"answer":2,"explanation":"「构建」与「格局」搭配得当。「构建格局」为惯用搭配；「构作」「搭造」「架造」均非规范书面搭配。故选C。","__sub":"选词填空"},{"id":"yy-18205","module":"yanyu","diff":1,"exam":"省考","prompt":"这些年，在广袤乡野间，广大建设者用汗水______出乡村振兴的崭新篇章。","options":["描红","誊写","抄写","书写"],"answer":3,"explanation":"「书写」与「篇章」搭配得当。「书写篇章」为惯用搭配；「抄写」「誊写」「描红」均为照原样复写的具体动作，缺乏开创义。故选D。","__sub":"选词填空"},{"id":"yy-18206","module":"yanyu","diff":2,"exam":"教师编","prompt":"今年以来，让公共服务覆盖城乡，市场监管部门持续______政策体系。","options":["补完","修完","完善","完缮"],"answer":2,"explanation":"「完善」与「体系」搭配得当。「完善体系」为固定搭配；「完缮」「修完」「补完」均非规范搭配。故选C。","__sub":"选词填空"},{"id":"yy-18207","module":"yanyu","diff":1,"exam":"事业编","prompt":"开春以来，金杯银杯不如老百姓的口碑，老党员把每件小事都当大事办。","options":["设立","树立","创立","建立"],"answer":1,"explanation":"「树立」与「口碑」搭配得当。「树立口碑」为惯用搭配；「建立」多与制度、关系搭配；「设立」多与机构搭配；「创立」多与学说、品牌搭配。故选B。","__sub":"选词填空"},{"id":"yy-18208","module":"yanyu","diff":1,"exam":"教师编","prompt":"岁末年初，向存量要效益，铁路养护工为产业升级______新空间。","options":["拓开","开展","展开","拓展"],"answer":3,"explanation":"「拓展」与「空间」搭配得当。「拓展空间」为固定搭配；「拓开」非规范；「开展」多与活动搭配；「展开」多与画卷、攻势搭配。故选D。","__sub":"选词填空"},{"id":"yy-18209","module":"yanyu","diff":3,"exam":"国考","prompt":"一段时间以来，夜市灯火点亮街巷，手工艺人为城市______了烟火活力。","options":["增加","增补","增添","追加"],"answer":2,"explanation":"「增添」与「活力」搭配得当。「增添活力」为惯用搭配；「增加」多与数量搭配；「追加」多与投资搭配；「增补」多与人员、内容搭配。故选C。","__sub":"选词填空"},{"id":"yy-18210","module":"yanyu","diff":1,"exam":"国考","prompt":"近年来，把家国情怀融入课堂，青年学子用身边故事打动学生。","options":["浇灌","厚植","施肥","培土"],"answer":1,"explanation":"「厚植」与「情怀」搭配得当。「厚植情怀」为书面惯用搭配；「加深」多与印象、了解搭配。故选B。","__sub":"选词填空"},{"id":"yy-18211","module":"yanyu","diff":2,"exam":"省考","prompt":"盛夏时节，老旧小区加装电梯、增设车位，电力工人尽力______居民多样需求。","options":["充盈","充足","满意","满足"],"answer":3,"explanation":"「满足」与「需求」搭配得当。「满足需求」为固定搭配；「满意」为形容词；「充足」「充盈」为形容词不能带宾语。故选D。","__sub":"选词填空"},{"id":"yy-18212","module":"yanyu","diff":2,"exam":"国考","prompt":"岁末年初，产业发展的根基越牢，抗风险的能力就越强，护林员深谙此理，先把根基打扎实。","options":["垒砌","铺设","敲打","夯实"],"answer":3,"explanation":"「夯实」与「根基」搭配得当。「夯实根基」为固定搭配；「敲打」为具体动作；「铺设」用于管线、路面；「垒砌」用于砖石墙体。故选D。","__sub":"选词填空"},{"id":"yy-18213","module":"yanyu","diff":2,"exam":"事业编","prompt":"眼下，老艺人收徒授艺，让千年技艺薪火。","options":["相传","递送","传递","互传"],"answer":0,"explanation":"「相传」与「薪火」搭配得当。「薪火相传」为固定成语；「互传」「递送」「传递」均无此搭配且丢失比喻义。故选A。","__sub":"选词填空"},{"id":"yy-18214","module":"yanyu","diff":2,"exam":"国考","prompt":"眼下，金杯银杯不如老百姓的口碑，公交司机把每件小事都当大事办。","options":["创立","建立","树立","设立"],"answer":2,"explanation":"「树立」与「口碑」搭配得当。「树立口碑」为惯用搭配；「建立」多与制度、关系搭配；「设立」多与机构搭配；「创立」多与学说、品牌搭配。故选C。","__sub":"选词填空"},{"id":"yy-18215","module":"yanyu","diff":1,"exam":"省考","prompt":"近期，数据孤岛必须连起来，环卫工人下决心______部门间的壁垒。","options":["砸破","打碎","击碎","打破"],"answer":3,"explanation":"「打破」与「壁垒」搭配得当。「打破壁垒」为固定搭配；「打碎」「砸破」「击碎」均为具体物理动作。故选D。","__sub":"选词填空"},{"id":"yy-18216","module":"yanyu","diff":1,"exam":"省考","prompt":"近期，被动状态必须改变，渔民用硬措施______了不利局面。","options":["反转","倒转","扭转","回转"],"answer":2,"explanation":"「扭转」与「局面」搭配得当。「扭转局面」为固定搭配；「反转」多与剧情、行情搭配；「倒转」「回转」指方向掉转。故选C。","__sub":"选词填空"},{"id":"yy-18217","module":"yanyu","diff":2,"exam":"事业编","prompt":"今年以来，两岸同胞亲情割不断，乡村医生为青年交流______心灵心桥。","options":["铺设","修筑","垒砌","架起"],"answer":3,"explanation":"「架起」与「心桥」搭配得当。「架起心桥」为惯用比喻搭配；「修筑」用于道路工程；「垒砌」用于砖石；「铺设」用于管线轨道。故选D。","__sub":"选词填空"},{"id":"yy-18218","module":"yanyu","diff":2,"exam":"国考","prompt":"开春以来，老厂房变身文创园，乡村医生让工业遗存______新的活力。","options":["焕发","焕新","换发","更新"],"answer":0,"explanation":"「焕发」与「活力」搭配得当。「焕发活力」为固定搭配；「换发」为误写；「焕新」「更新」多用于设施、面貌且为动词直接带宾语。故选A。","__sub":"选词填空"},{"id":"yy-18219","module":"yanyu","diff":2,"exam":"省考","prompt":"入冬以来，停车难是城市治理的老大难，治沙工人用共享思维______了这一难题。","options":["解开","解释","解冻","破解"],"answer":3,"explanation":"「破解」与「难题」搭配得当。「破解难题」为固定搭配；「解开」多与绳结、心结搭配；「解冻」用于资产、关系；「解释」为说明缘由。故选D。","__sub":"选词填空"},{"id":"yy-18220","module":"yanyu","diff":2,"exam":"教师编","prompt":"入冬以来，每个孩子都有闪光点，青年学子善于______学生潜能。","options":["开采","掘取","挖出","挖掘"],"answer":3,"explanation":"「挖掘」与「潜能」搭配得当。「挖掘潜能」为固定搭配；「挖出」「掘取」为具体动作；「开采」用于矿产。故选D。","__sub":"选词填空"},{"id":"yy-18221","module":"yanyu","diff":2,"exam":"省考","prompt":"开春以来，卡脖子技术亟待攻坚，广大建设者集中力量______一个个瓶颈。","options":["撞破","捅破","冲破","突破"],"answer":3,"explanation":"「突破」与「瓶颈」搭配得当。「突破瓶颈」为固定搭配；「冲破」多与封锁、束缚搭配；「撞破」「捅破」为具体动作或与窗户纸等搭配。故选D。","__sub":"选词填空"},{"id":"yy-18222","module":"yanyu","diff":2,"exam":"国考","prompt":"初秋时节，把监督防线扎到最基层，调解员走村入户听民声。","options":["缝密","织密","织补","织厚"],"answer":1,"explanation":"「织密」与「防线」搭配得当。「织密防线」为惯用搭配；「织厚」「缝密」非规范搭配；「织补」指修补织物。故选B。","__sub":"选词填空"},{"id":"yy-18223","module":"yanyu","diff":2,"exam":"国考","prompt":"一段时间以来，营商环境就是生产力，手工艺人让企业成长有沃土。","options":["培育","培养","培植","厚植"],"answer":3,"explanation":"「厚植」与「沃土」搭配得当。「厚植沃土」为书面惯用搭配；「培植」多与势力搭配含贬义；「培育」多与人才、市场搭配；「培养」多与人才搭配。故选D。","__sub":"选词填空"},{"id":"yy-18224","module":"yanyu","diff":2,"exam":"事业编","prompt":"一段时间以来，卡脖子技术亟待攻坚，工程师集中力量______一个个瓶颈。","options":["捅破","撞破","冲破","突破"],"answer":3,"explanation":"「突破」与「瓶颈」搭配得当。「突破瓶颈」为固定搭配；「冲破」多与封锁、束缚搭配；「撞破」「捅破」为具体动作或与窗户纸等搭配。故选D。","__sub":"选词填空"},{"id":"yy-18225","module":"yanyu","diff":2,"exam":"国考","prompt":"盛夏时节，让新业态释放新动能，基层干部在制度创新上先行先试。","options":["引爆","点燃","发动","激发"],"answer":3,"explanation":"「激发」与「动能」搭配得当。「激发动能」为惯用搭配；「发动」多与机器、群众搭配；「点燃」多与激情搭配；「引爆」多与话题、舆论搭配且含突然义。故选D。","__sub":"选词填空"},{"id":"yy-18226","module":"yanyu","diff":3,"exam":"省考","prompt":"一段时间以来，数据孤岛必须连起来，护林员下决心______部门间的壁垒。","options":["打破","砸破","击碎","打碎"],"answer":0,"explanation":"「打破」与「壁垒」搭配得当。「打破壁垒」为固定搭配；「打碎」「砸破」「击碎」均为具体物理动作。故选A。","__sub":"选词填空"},{"id":"yy-18227","module":"yanyu","diff":2,"exam":"省考","prompt":"这些年，老艺人收徒授艺，让千年技艺薪火。","options":["传递","递送","互传","相传"],"answer":3,"explanation":"「相传」与「薪火」搭配得当。「薪火相传」为固定成语；「互传」「递送」「传递」均无此搭配且丢失比喻义。故选D。","__sub":"选词填空"},{"id":"yy-18228","module":"yanyu","diff":3,"exam":"国考","prompt":"一段时间以来，在广袤乡野间，市场监管部门用汗水______出乡村振兴的崭新篇章。","options":["誊写","描红","书写","抄写"],"answer":2,"explanation":"「书写」与「篇章」搭配得当。「书写篇章」为惯用搭配；「抄写」「誊写」「描红」均为照原样复写的具体动作，缺乏开创义。故选C。","__sub":"选词填空"},{"id":"yy-18229","module":"yanyu","diff":2,"exam":"事业编","prompt":"眼下，两岸同胞亲情割不断，电力工人为青年交流______心灵心桥。","options":["修筑","垒砌","铺设","架起"],"answer":3,"explanation":"「架起」与「心桥」搭配得当。「架起心桥」为惯用比喻搭配；「修筑」用于道路工程；「垒砌」用于砖石；「铺设」用于管线轨道。故选D。","__sub":"选词填空"},{"id":"yy-18230","module":"yanyu","diff":3,"exam":"省考","prompt":"初秋时节，政府、市场、社会同向发力，公交司机让各方______成强大合力。","options":["汇聚","聚合","汇合","汇集"],"answer":0,"explanation":"「汇聚」与「合力」搭配得当。「汇聚合力」为惯用搭配；「汇合」指水流等聚集；「汇集」指集中收集；「聚合」为化学或物理过程。故选A。","__sub":"选词填空"},{"id":"yy-18231","module":"yanyu","diff":1,"exam":"教师编","prompt":"入冬以来，内生动力从哪里来？医护人员把功夫下在创新上。","options":["增强","增添","加强","增大"],"answer":0,"explanation":"「增强」与「动力」搭配得当。「增强动力」为固定搭配；「加强」多与领导、管理搭配；「增大」多与幅度、剂量搭配。故选A。","__sub":"选词填空"},{"id":"yy-18232","module":"yanyu","diff":1,"exam":"国考","prompt":"近年来，老艺人收徒授艺，让千年技艺薪火。","options":["相传","传递","互传","递送"],"answer":0,"explanation":"「相传」与「薪火」搭配得当。「薪火相传」为固定成语；「互传」「递送」「传递」均无此搭配且丢失比喻义。故选A。","__sub":"选词填空"},{"id":"yy-18233","module":"yanyu","diff":2,"exam":"教师编","prompt":"今年以来，一次次说到做到，非遗传承人用行动______了群众的信任。","options":["博得","换取","获得","赢得"],"answer":3,"explanation":"「赢得」与「信任」搭配得当。「赢得信任」为固定搭配，强调经努力而获得；「获得」中性；「博得」多与同情、喝彩搭配；「换取」含交换义。故选D。","__sub":"选词填空"},{"id":"yy-18234","module":"yanyu","diff":2,"exam":"事业编","prompt":"连日来，老厂房变身文创园，茶农让工业遗存______新的活力。","options":["换发","更新","焕新","焕发"],"answer":3,"explanation":"「焕发」与「活力」搭配得当。「焕发活力」为固定搭配；「换发」为误写；「焕新」「更新」多用于设施、面貌且为动词直接带宾语。故选D。","__sub":"选词填空"},{"id":"yy-18235","module":"yanyu","diff":3,"exam":"国考","prompt":"近期，景区客流高峰来临，网格员全员上岗______游览秩序。","options":["护卫","维持","维护","保护"],"answer":2,"explanation":"「维护」与「秩序」搭配得当。「维护秩序」为固定搭配；「维持」多与生活、现状搭配；「保护」多与权益、环境搭配；「护卫」用于人员、目标。故选C。","__sub":"选词填空"},{"id":"yy-18236","module":"yanyu","diff":1,"exam":"国考","prompt":"近期，把风险挺在前面，广大建设者织密织牢安全网。","options":["防守","防备","提防","防范"],"answer":3,"explanation":"「防范」与「风险」搭配得当。「防范风险」为固定搭配；「防备」侧重有所准备；「提防」为口语化小心在意；「防守」多用于比赛、军事。故选D。","__sub":"选词填空"},{"id":"yy-18237","module":"yanyu","diff":2,"exam":"国考","prompt":"近期，减税降费政策落地，茶农让企业真切感受到红利。","options":["发射","发放","释放","散发"],"answer":2,"explanation":"「释放」与「红利」搭配得当。「释放红利」为惯用搭配；「发放」多与物资、贷款搭配；「散发」多与气味搭配；「发射」用于子弹、卫星。故选C。","__sub":"选词填空"},{"id":"yy-18238","module":"yanyu","diff":1,"exam":"教师编","prompt":"入冬以来，跳出一时一地看发展，图书管理员着力______开放共赢的新格局。","options":["构建","构作","架造","搭造"],"answer":0,"explanation":"「构建」与「格局」搭配得当。「构建格局」为惯用搭配；「构作」「搭造」「架造」均非规范书面搭配。故选A。","__sub":"选词填空"},{"id":"yy-18239","module":"yanyu","diff":1,"exam":"省考","prompt":"开春以来，手握核心技术专利，图书管理员创新的底气。","options":["更硬","更强","更足","更壮"],"answer":2,"explanation":"「更足」与「底气」搭配得当。「底气更足」为惯用搭配；「更硬」多与作风搭配；「更强」多与实力搭配；「更壮」用于体格。故选C。","__sub":"选词填空"},{"id":"yy-18240","module":"yanyu","diff":2,"exam":"医疗编","prompt":"入冬以来，民生实事清单公示上墙，志愿者们一件一件______承诺。","options":["实现","兑现","完成","达成"],"answer":1,"explanation":"「兑现」与「承诺」搭配得当。「兑现承诺」为固定搭配；「实现」多与梦想、目标搭配；「完成」多与任务搭配；「达成」多与协议搭配。故选B。","__sub":"选词填空"},{"id":"yy-18241","module":"yanyu","diff":1,"exam":"省考","prompt":"今年以来，小哨兵大作用，农技人员让基层网格______更大作用。","options":["施展","发挥","发扬","表现"],"answer":1,"explanation":"「发挥」与「作用」搭配得当。「发挥作用」为固定搭配；「发扬」多与传统搭配；「施展」多与才华、拳脚搭配。故选B。","__sub":"选词填空"},{"id":"yy-18242","module":"yanyu","diff":3,"exam":"医疗编","prompt":"入冬以来，几十年如一日，程序员在平凡岗位上______着为民初心。","options":["坚守","守卫","保守","把守"],"answer":0,"explanation":"「坚守」与「初心」搭配得当。「坚守初心」为固定搭配；「保守」多与秘密搭配；「守卫」用于边疆、家园；「把守」用于关口。故选A。","__sub":"选词填空"},{"id":"yy-18243","module":"yanyu","diff":2,"exam":"省考","prompt":"开春以来，把消费潜力转化为增长实绩，乡村医生拿出了实招硬招。","options":["释放","散发","发泄","喷发"],"answer":0,"explanation":"「释放」与「潜力」搭配得当。「释放潜力」为固定搭配；「发泄」含贬义多与情绪搭配；「散发」多与气味、气息搭配；「喷发」用于火山或比喻爆发。故选A。","__sub":"选词填空"},{"id":"yy-18244","module":"yanyu","diff":3,"exam":"国考","prompt":"盛夏时节，一年一度的民生大考结束，志愿者们向群众______了温暖的答卷。","options":["递交","上缴","交出","呈报"],"answer":2,"explanation":"「交出」与「答卷」搭配得当。「交出答卷」为惯用搭配；「递交」多与申请、辞呈搭配；「呈报」多与公文搭配且含上下级意味；「上缴」多与款项、物品搭配。故选C。","__sub":"选词填空"},{"id":"yy-18245","module":"yanyu","diff":2,"exam":"省考","prompt":"这些年，卡脖子技术亟待攻坚，手工艺人集中力量______一个个瓶颈。","options":["捅破","冲破","撞破","突破"],"answer":3,"explanation":"「突破」与「瓶颈」搭配得当。「突破瓶颈」为固定搭配；「冲破」多与封锁、束缚搭配；「撞破」「捅破」为具体动作或与窗户纸等搭配。故选D。","__sub":"选词填空"},{"id":"yy-18246","module":"yanyu","diff":1,"exam":"医疗编","prompt":"初秋时节，几十年如一日，消防员在平凡岗位上______着为民初心。","options":["把守","守卫","保守","坚守"],"answer":3,"explanation":"「坚守」与「初心」搭配得当。「坚守初心」为固定搭配；「保守」多与秘密搭配；「守卫」用于边疆、家园；「把守」用于关口。故选D。","__sub":"选词填空"},{"id":"yy-18247","module":"yanyu","diff":1,"exam":"省考","prompt":"眼下，每一起案件都关乎群众对法治的信仰，老党员用公正裁判______正义。","options":["捍卫","保卫","防御","护卫"],"answer":0,"explanation":"「捍卫」与「公平」搭配得当。「捍卫公平」为书面惯用搭配；「保卫」多与祖国、和平搭配；「护卫」为护送守卫；「防御」用于军事、疫情。故选A。","__sub":"选词填空"},{"id":"yy-18248","module":"yanyu","diff":1,"exam":"国考","prompt":"入冬以来，内生动力从哪里来？博物馆讲解员把功夫下在创新上。","options":["增添","增强","加强","增大"],"answer":1,"explanation":"「增强」与「动力」搭配得当。「增强动力」为固定搭配；「加强」多与领导、管理搭配；「增大」多与幅度、剂量搭配。故选B。","__sub":"选词填空"},{"id":"yy-18249","module":"yanyu","diff":2,"exam":"医疗编","prompt":"岁末年初，老旧小区加装电梯、增设车位，渔民尽力______居民多样需求。","options":["满足","满意","充足","充盈"],"answer":0,"explanation":"「满足」与「需求」搭配得当。「满足需求」为固定搭配；「满意」为形容词；「充足」「充盈」为形容词不能带宾语。故选A。","__sub":"选词填空"},{"id":"yy-18250","module":"yanyu","diff":2,"exam":"事业编","prompt":"开春以来，改革红利持续显现，市场活力不断，乡村医生信心更足。","options":["暴发","突发","迸发","爆发"],"answer":2,"explanation":"「迸发」与「活力」搭配得当。「迸发活力」为惯用搭配；「爆发」多用于战争、疫情或力量；「突发」多与事件搭配；「暴发」多用于疫情或含贬义。故选C。","__sub":"选词填空"},{"id":"yy-18251","module":"yanyu","diff":1,"exam":"教师编","prompt":"近期，让监督机制长出牙齿，志愿者们把制度笼子越扎越紧。","options":["修复","修葺","健全","修理"],"answer":2,"explanation":"「健全」与「机制」搭配得当。「健全机制」为固定搭配，使完善；「修理」「修复」「修葺」均指具体物件的修补，与机制不搭。故选C。","__sub":"选词填空"},{"id":"yy-18252","module":"yanyu","diff":2,"exam":"国考","prompt":"这些年，金融活水精准滴灌，驻村干部为小微企业______发展动力。","options":["输入","注入","灌输","灌入"],"answer":1,"explanation":"「注入」与「动力」搭配得当。「注入动力」为惯用搭配；「灌入」用于液体；「输入」用于数据、血液；「注入」亦可用于资金，但「注入动力」最规范。故选B。","__sub":"选词填空"},{"id":"yy-18253","module":"yanyu","diff":3,"exam":"国考","prompt":"盛夏时节，改革红利持续显现，市场活力不断，图书管理员信心更足。","options":["爆发","暴发","迸发","突发"],"answer":2,"explanation":"「迸发」与「活力」搭配得当。「迸发活力」为惯用搭配；「爆发」多用于战争、疫情或力量；「突发」多与事件搭配；「暴发」多用于疫情或含贬义。故选C。","__sub":"选词填空"},{"id":"yy-18254","module":"yanyu","diff":3,"exam":"省考","prompt":"近年来，从受理到反馈全流程留痕，调解员以数字化手段______管理闭环。","options":["构画","圈画","搭圈","构建"],"answer":3,"explanation":"「构建」与「闭环」搭配得当。「构建闭环」为惯用搭配；其余选项均非规范搭配。故选D。","__sub":"选词填空"},{"id":"yy-18255","module":"yanyu","diff":1,"exam":"教师编","prompt":"今年以来，金融活水精准滴灌，法官为小微企业______发展动力。","options":["输入","注入","灌入","灌输"],"answer":1,"explanation":"「注入」与「动力」搭配得当。「注入动力」为惯用搭配；「灌入」用于液体；「输入」用于数据、血液；「注入」亦可用于资金，但「注入动力」最规范。故选B。","__sub":"选词填空"},{"id":"yy-18256","module":"yanyu","diff":1,"exam":"教师编","prompt":"入冬以来，古城修缮不搞大拆大建，渔民让千年文脉在街巷间静静流淌。","options":["续接","连接","延续","接通"],"answer":2,"explanation":"「延续」与「文脉」搭配得当。「延续文脉」为惯用搭配；「连接」指具体相连；「续接」多与线路搭配；「接通」用于电话、电路。故选C。","__sub":"选词填空"},{"id":"yy-18257","module":"yanyu","diff":1,"exam":"医疗编","prompt":"近年来，向存量要效益，审计人员为产业升级______新空间。","options":["拓展","展开","拓开","开展"],"answer":0,"explanation":"「拓展」与「空间」搭配得当。「拓展空间」为固定搭配；「拓开」非规范；「开展」多与活动搭配；「展开」多与画卷、攻势搭配。故选A。","__sub":"选词填空"},{"id":"yy-18258","module":"yanyu","diff":2,"exam":"国考","prompt":"盛夏时节，让农产品出村进城，执法人员多方合力______销售通道。","options":["扩宽","开宽","拓宽","开辟"],"answer":2,"explanation":"「拓宽」与「通道」搭配得当。「拓宽通道」为固定搭配；「开宽」非规范；「扩宽」多用于道路；「拓宽」亦用于道路但与渠道、通道搭配最常见。故选C。","__sub":"选词填空"},{"id":"yy-18259","module":"yanyu","diff":2,"exam":"事业编","prompt":"入冬以来，金杯银杯不如老百姓的口碑，护林员把每件小事都当大事办。","options":["建立","树立","设立","创立"],"answer":1,"explanation":"「树立」与「口碑」搭配得当。「树立口碑」为惯用搭配；「建立」多与制度、关系搭配；「设立」多与机构搭配；「创立」多与学说、品牌搭配。故选B。","__sub":"选词填空"},{"id":"yy-18260","module":"yanyu","diff":2,"exam":"省考","prompt":"今年以来，数据孤岛必须连起来，程序员下决心______部门间的壁垒。","options":["击碎","砸破","打破","打碎"],"answer":2,"explanation":"「打破」与「壁垒」搭配得当。「打破壁垒」为固定搭配；「打碎」「砸破」「击碎」均为具体物理动作。故选C。","__sub":"选词填空"},{"id":"yy-18261","module":"yanyu","diff":2,"exam":"国考","prompt":"一段时间以来，老工业基地涅槃重生，当地企业加快新旧动能转换步伐。","options":["改换","转换","变换","转变"],"answer":1,"explanation":"「转换」与「动能」搭配得当。「动能转换」为固定搭配；「转变」多与观念、方式搭配；「改换」「变换」多与门庭、姿势搭配。故选B。","__sub":"选词填空"},{"id":"yy-18262","module":"yanyu","diff":3,"exam":"省考","prompt":"这些年，让要素流动更顺畅，就要______体制机制的藩篱。","options":["捣毁","铲平","拆除","破除"],"answer":3,"explanation":"「破除」与「藩篱」搭配得当。「破除藩篱」为固定搭配；「拆除」用于建筑；「铲平」用于场地；「捣毁」用于巢穴、据点且含暴力义。故选D。","__sub":"选词填空"},{"id":"yy-18263","module":"yanyu","diff":1,"exam":"国考","prompt":"连日来，减税降费政策落地，医护人员让企业真切感受到红利。","options":["发射","释放","发放","散发"],"answer":1,"explanation":"「释放」与「红利」搭配得当。「释放红利」为惯用搭配；「发放」多与物资、贷款搭配；「散发」多与气味搭配；「发射」用于子弹、卫星。故选B。","__sub":"选词填空"},{"id":"yy-18264","module":"yanyu","diff":2,"exam":"国考","prompt":"眼下，万丈高楼平地起，执法人员一锤一钎______发展基础。","options":["填实","踩实","夯实","砸实"],"answer":2,"explanation":"「夯实」与「基础」搭配得当。「夯实基础」为固定搭配；「砸实」「踩实」「填实」均为具体动作。故选C。","__sub":"选词填空"},{"id":"yy-18265","module":"yanyu","diff":3,"exam":"省考","prompt":"近年来，政府、市场、社会同向发力，税务干部让各方______成强大合力。","options":["汇聚","聚合","汇集","汇合"],"answer":0,"explanation":"「汇聚」与「合力」搭配得当。「汇聚合力」为惯用搭配；「汇合」指水流等聚集；「汇集」指集中收集；「聚合」为化学或物理过程。故选A。","__sub":"选词填空"},{"id":"yy-18266","module":"yanyu","diff":2,"exam":"国考","prompt":"盛夏时节，改革红利持续显现，市场活力不断，手工艺人信心更足。","options":["暴发","爆发","迸发","突发"],"answer":2,"explanation":"「迸发」与「活力」搭配得当。「迸发活力」为惯用搭配；「爆发」多用于战争、疫情或力量；「突发」多与事件搭配；「暴发」多用于疫情或含贬义。故选C。","__sub":"选词填空"},{"id":"yy-18267","module":"yanyu","diff":3,"exam":"国考","prompt":"今年以来，一二三产融合发展，治沙工人推动产业链不断延伸。","options":["拉长","延长","延伸","伸长"],"answer":2,"explanation":"「延伸」与「链条」搭配得当。「链条延伸」为惯用搭配；「伸长」「拉长」「延长」多用于具体长度或时间。故选C。","__sub":"选词填空"},{"id":"yy-18268","module":"yanyu","diff":3,"exam":"国考","prompt":"连日来，营商环境就是生产力，法官让企业成长有沃土。","options":["培植","厚植","培育","培养"],"answer":1,"explanation":"「厚植」与「沃土」搭配得当。「厚植沃土」为书面惯用搭配；「培植」多与势力搭配含贬义；「培育」多与人才、市场搭配；「培养」多与人才搭配。故选B。","__sub":"选词填空"},{"id":"yy-18269","module":"yanyu","diff":1,"exam":"国考","prompt":"初秋时节，人才是创新的第一资源，调解员把发展根基越培越厚。","options":["培土","浇灌","厚植","施肥"],"answer":2,"explanation":"「厚植」与「根基」搭配得当。「厚植根基」为书面惯用搭配；「培土」「施肥」「浇灌」均为农事具体动作。故选C。","__sub":"选词填空"},{"id":"yy-18270","module":"yanyu","diff":2,"exam":"国考","prompt":"近期，每个孩子都有闪光点，治沙工人善于______学生潜能。","options":["开采","掘取","挖出","挖掘"],"answer":3,"explanation":"「挖掘」与「潜能」搭配得当。「挖掘潜能」为固定搭配；「挖出」「掘取」为具体动作；「开采」用于矿产。故选D。","__sub":"选词填空"},{"id":"yy-18271","module":"yanyu","diff":2,"exam":"国考","prompt":"开春以来，从受理到反馈全流程留痕，审计人员以数字化手段______管理闭环。","options":["圈画","构建","构画","搭圈"],"answer":1,"explanation":"「构建」与「闭环」搭配得当。「构建闭环」为惯用搭配；其余选项均非规范搭配。故选B。","__sub":"选词填空"},{"id":"yy-18272","module":"yanyu","diff":2,"exam":"国考","prompt":"初秋时节，老艺人收徒授艺，让千年技艺薪火。","options":["互传","相传","递送","传递"],"answer":1,"explanation":"「相传」与「薪火」搭配得当。「薪火相传」为固定成语；「互传」「递送」「传递」均无此搭配且丢失比喻义。故选B。","__sub":"选词填空"},{"id":"yy-18273","module":"yanyu","diff":2,"exam":"国考","prompt":"一段时间以来，手握核心技术专利，执法人员创新的底气。","options":["更足","更强","更壮","更硬"],"answer":0,"explanation":"「更足」与「底气」搭配得当。「底气更足」为惯用搭配；「更硬」多与作风搭配；「更强」多与实力搭配；「更壮」用于体格。故选A。","__sub":"选词填空"},{"id":"yy-18274","module":"yanyu","diff":1,"exam":"国考","prompt":"开春以来，夜市灯火点亮街巷，渔民为城市______了烟火活力。","options":["增添","追加","增补","增加"],"answer":0,"explanation":"「增添」与「活力」搭配得当。「增添活力」为惯用搭配；「增加」多与数量搭配；「追加」多与投资搭配；「增补」多与人员、内容搭配。故选A。","__sub":"选词填空"},{"id":"yy-18275","module":"yanyu","diff":2,"exam":"省考","prompt":"这些年，停车难是城市治理的老大难，工程师用共享思维______了这一难题。","options":["解冻","解释","破解","解开"],"answer":2,"explanation":"「破解」与「难题」搭配得当。「破解难题」为固定搭配；「解开」多与绳结、心结搭配；「解冻」用于资产、关系；「解释」为说明缘由。故选C。","__sub":"选词填空"},{"id":"yy-18276","module":"yanyu","diff":2,"exam":"国考","prompt":"这些年，绿水青山就是金山银山，志愿者们代代接力______绿色生态。","options":["守望","守护","看守","守候"],"answer":1,"explanation":"「守护」与「生态」搭配得当。「守护生态」为惯用搭配，含珍视呵护义；「看守」用于财物、门户；「守候」指等待；「守望」指瞭望盼望。故选B。","__sub":"选词填空"},{"id":"yy-18277","module":"yanyu","diff":2,"exam":"教师编","prompt":"连日来，市场细胞活跃起来，手工艺人让经济肌体活力。","options":["填满","装满","充满","塞满"],"answer":2,"explanation":"「充满」与「活力」搭配得当。「充满活力」为固定搭配；「填满」「塞满」「装满」均为具体动作，用于抽象活力不当。故选C。","__sub":"选词填空"},{"id":"yy-18278","module":"yanyu","diff":3,"exam":"国考","prompt":"入冬以来，景区客流高峰来临，博物馆讲解员全员上岗______游览秩序。","options":["保护","维护","护卫","维持"],"answer":1,"explanation":"「维护」与「秩序」搭配得当。「维护秩序」为固定搭配；「维持」多与生活、现状搭配；「保护」多与权益、环境搭配；「护卫」用于人员、目标。故选B。","__sub":"选词填空"},{"id":"yy-18279","module":"yanyu","diff":2,"exam":"医疗编","prompt":"今年以来，市场不是法外之地，程序员以制度______交易秩序。","options":["规整","规正","规定","规范"],"answer":3,"explanation":"「规范」与「秩序」搭配得当。「规范秩序」为惯用搭配；「规定」为名词或动词制定；「规整」指整齐；「规正」指匡正。故选D。","__sub":"选词填空"},{"id":"yy-18280","module":"yanyu","diff":1,"exam":"国考","prompt":"一段时间以来，城乡公共服务仍有落差，博物馆讲解员以实策逐步______差距。","options":["减少","减小","缩减","缩小"],"answer":3,"explanation":"「缩小」与「差距」搭配得当。「缩小差距」为固定搭配；「减少」多与数量搭配；「缩减」多与开支、编制搭配；「减小」多与阻力、噪音搭配。故选D。","__sub":"选词填空"},{"id":"yy-18281","module":"yanyu","diff":3,"exam":"教师编","prompt":"盛夏时节，被动状态必须改变，网格员用硬措施______了不利局面。","options":["扭转","倒转","反转","回转"],"answer":0,"explanation":"「扭转」与「局面」搭配得当。「扭转局面」为固定搭配；「反转」多与剧情、行情搭配；「倒转」「回转」指方向掉转。故选A。","__sub":"选词填空"},{"id":"yy-18282","module":"yanyu","diff":2,"exam":"医疗编","prompt":"今年以来，小哨兵大作用，市场监管部门让基层网格______更大作用。","options":["发挥","施展","发扬","表现"],"answer":0,"explanation":"「发挥」与「作用」搭配得当。「发挥作用」为固定搭配；「发扬」多与传统搭配；「施展」多与才华、拳脚搭配。故选A。","__sub":"选词填空"},{"id":"yy-18283","module":"yanyu","diff":1,"exam":"国考","prompt":"今年以来，一年一度的民生大考结束，快递员向群众______了温暖的答卷。","options":["呈报","上缴","递交","交出"],"answer":3,"explanation":"「交出」与「答卷」搭配得当。「交出答卷」为惯用搭配；「递交」多与申请、辞呈搭配；「呈报」多与公文搭配且含上下级意味；「上缴」多与款项、物品搭配。故选D。","__sub":"选词填空"},{"id":"yy-18284","module":"yanyu","diff":1,"exam":"国考","prompt":"一段时间以来，民生领域还有欠账，环卫工人列出清单逐项______短板。","options":["修补","补丁","贴补","补齐"],"answer":3,"explanation":"「补齐」与「短板」搭配得当。「补齐短板」为固定搭配；「补丁」为名词；「修补」多用于衣物器物；「贴补」多与费用搭配。故选D。","__sub":"选词填空"},{"id":"yy-18285","module":"yanyu","diff":1,"exam":"省考","prompt":"初秋时节，在广袤乡野间，乡村医生用汗水______出乡村振兴的崭新篇章。","options":["誊写","描红","抄写","书写"],"answer":3,"explanation":"「书写」与「篇章」搭配得当。「书写篇章」为惯用搭配；「抄写」「誊写」「描红」均为照原样复写的具体动作，缺乏开创义。故选D。","__sub":"选词填空"},{"id":"yy-18286","module":"yanyu","diff":2,"exam":"事业编","prompt":"岁末年初，急难险重任务面前，基层干部主动______最重的责任。","options":["抬起","挑起","扛起","背起"],"answer":2,"explanation":"「扛起」与「责任」搭配得当。「扛起责任」为惯用搭配；「背起」多与行囊、伤员搭配；「挑起」多与担子、重担搭配；「抬起」为具体动作。故选C。","__sub":"选词填空"},{"id":"yy-18287","module":"yanyu","diff":2,"exam":"国考","prompt":"一段时间以来，红色资源是最生动的教材，科研人员让红色血脉代代相传。","options":["继续","延续","赓续","接续"],"answer":2,"explanation":"「赓续」与「血脉」搭配得当。「赓续血脉」为书面惯用搭配；「继续」为一般动词；「接续」多与手续、产业搭配；「延续」多与生命、文脉搭配。故选C。","__sub":"选词填空"},{"id":"yy-18288","module":"yanyu","diff":2,"exam":"省考","prompt":"入冬以来，金杯银杯不如老百姓的口碑，青年学子把每件小事都当大事办。","options":["建立","创立","树立","设立"],"answer":2,"explanation":"「树立」与「口碑」搭配得当。「树立口碑」为惯用搭配；「建立」多与制度、关系搭配；「设立」多与机构搭配；「创立」多与学说、品牌搭配。故选C。","__sub":"选词填空"},{"id":"yy-18289","module":"yanyu","diff":1,"exam":"国考","prompt":"眼下，靠山吃山靠水吃水，程序员因地制宜______资源优势。","options":["发扬","发挥","发展","施展"],"answer":1,"explanation":"「发挥」与「优势」搭配得当。「发挥优势」为固定搭配；「发扬」多与精神、作风搭配；「发展」多与经济、事业搭配。故选B。","__sub":"选词填空"},{"id":"yy-18290","module":"yanyu","diff":2,"exam":"国考","prompt":"盛夏时节，老厂房变身文创园，渔民让工业遗存______新的活力。","options":["换发","更新","焕新","焕发"],"answer":3,"explanation":"「焕发」与「活力」搭配得当。「焕发活力」为固定搭配；「换发」为误写；「焕新」「更新」多用于设施、面貌且为动词直接带宾语。故选D。","__sub":"选词填空"},{"id":"yy-18291","module":"yanyu","diff":1,"exam":"国考","prompt":"初秋时节，纪律规矩挺在前面，程序员始终______纪律底线。","options":["看守","遵守","把守","严守"],"answer":3,"explanation":"「严守」与「底线」搭配得当。「严守底线」为固定搭配；「看守」「把守」为具体看护；「遵守」多与规则、法律搭配。故选D。","__sub":"选词填空"},{"id":"yy-18292","module":"yanyu","diff":2,"exam":"国考","prompt":"岁末年初，把家国情怀融入课堂，茶农用身边故事打动学生。","options":["施肥","浇灌","培土","厚植"],"answer":3,"explanation":"「厚植」与「情怀」搭配得当。「厚植情怀」为书面惯用搭配；「加深」多与印象、了解搭配。故选D。","__sub":"选词填空"},{"id":"yy-18293","module":"yanyu","diff":1,"exam":"教师编","prompt":"盛夏时节，营商环境就是生产力，设计师让企业成长有沃土。","options":["厚植","培植","培养","培育"],"answer":0,"explanation":"「厚植」与「沃土」搭配得当。「厚植沃土」为书面惯用搭配；「培植」多与势力搭配含贬义；「培育」多与人才、市场搭配；「培养」多与人才搭配。故选A。","__sub":"选词填空"},{"id":"yy-18294","module":"yanyu","diff":1,"exam":"教师编","prompt":"一段时间以来，越是爬坡过坎，越要______必胜信心，文旅部门一步一个脚印向前走。","options":["坚决","坚定","坚持不懈","坚强"],"answer":1,"explanation":"「坚定」与「信心」搭配得当。「坚定信心」为固定搭配；「坚决」为副词性形容词多修饰动作；「坚强」多与性格、领导搭配；「坚持不懈」为成语作状语。故选B。","__sub":"选词填空"},{"id":"yy-18295","module":"yanyu","diff":2,"exam":"事业编","prompt":"一段时间以来，靠山吃山靠水吃水，审计人员因地制宜______资源优势。","options":["施展","发挥","发展","发扬"],"answer":1,"explanation":"「发挥」与「优势」搭配得当。「发挥优势」为固定搭配；「发扬」多与精神、作风搭配；「发展」多与经济、事业搭配。故选B。","__sub":"选词填空"},{"id":"yy-18296","module":"yanyu","diff":2,"exam":"省考","prompt":"入冬以来，二十年只做一件事，广大建设者在细分领域里做到极致。","options":["深掘","深钻","深挖","深耕"],"answer":3,"explanation":"「深耕」与「领域」搭配得当。「深耕领域」为惯用比喻搭配；「深挖」多与线索搭配；「深钻」「深掘」非规范。故选D。","__sub":"选词填空"},{"id":"yy-18297","module":"yanyu","diff":3,"exam":"国考","prompt":"盛夏时节，跳出一时一地看发展，图书管理员着力______开放共赢的新格局。","options":["搭造","架造","构作","构建"],"answer":3,"explanation":"「构建」与「格局」搭配得当。「构建格局」为惯用搭配；「构作」「搭造」「架造」均非规范书面搭配。故选D。","__sub":"选词填空"},{"id":"yy-18298","module":"yanyu","diff":2,"exam":"医疗编","prompt":"这些年，乡情是最深的牵挂，非遗传承人以商会为平台______情感纽带。","options":["织牢","捆牢","系牢","绑牢"],"answer":0,"explanation":"「织牢」与「纽带」搭配得当。「织牢纽带」为惯用比喻搭配；「系牢」「捆牢」「绑牢」均为具体系绑动作。故选A。","__sub":"选词填空"},{"id":"yy-18299","module":"yanyu","diff":2,"exam":"国考","prompt":"初秋时节，老厂房变身文创园，快递员让工业遗存______新的活力。","options":["更新","换发","焕新","焕发"],"answer":3,"explanation":"「焕发」与「活力」搭配得当。「焕发活力」为固定搭配；「换发」为误写；「焕新」「更新」多用于设施、面貌且为动词直接带宾语。故选D。","__sub":"选词填空"},{"id":"yy-18300","module":"yanyu","diff":3,"exam":"国考","prompt":"眼下，危难时刻冲得上去，教师的行动______了共产党员的担当。","options":["彰显","暴露","显露","显摆"],"answer":0,"explanation":"「彰显」与「担当」搭配得当。「彰显担当」为固定搭配，褒义；「显摆」为口语含贬义；「显露」中性；「暴露」多含贬义。故选A。","__sub":"选词填空"},{"id":"yy-18301","module":"yanyu","diff":2,"exam":"省考","prompt":"入冬以来，民生实事清单公示上墙，手工艺人一件一件______承诺。","options":["达成","完成","实现","兑现"],"answer":3,"explanation":"「兑现」与「承诺」搭配得当。「兑现承诺」为固定搭配；「实现」多与梦想、目标搭配；「完成」多与任务搭配；「达成」多与协议搭配。故选D。","__sub":"选词填空"},{"id":"yy-18302","module":"yanyu","diff":2,"exam":"事业编","prompt":"一段时间以来，把家国情怀融入课堂，网格员用身边故事打动学生。","options":["浇灌","培土","施肥","厚植"],"answer":3,"explanation":"「厚植」与「情怀」搭配得当。「厚植情怀」为书面惯用搭配；「加深」多与印象、了解搭配。故选D。","__sub":"选词填空"},{"id":"yy-18303","module":"yanyu","diff":1,"exam":"省考","prompt":"开春以来，靠山吃山靠水吃水，青年学子因地制宜______资源优势。","options":["发挥","发扬","发展","施展"],"answer":0,"explanation":"「发挥」与「优势」搭配得当。「发挥优势」为固定搭配；「发扬」多与精神、作风搭配；「发展」多与经济、事业搭配。故选A。","__sub":"选词填空"},{"id":"yy-18304","module":"yanyu","diff":2,"exam":"省考","prompt":"入冬以来，把消费潜力转化为增长实绩，设计师拿出了实招硬招。","options":["释放","喷发","发泄","散发"],"answer":0,"explanation":"「释放」与「潜力」搭配得当。「释放潜力」为固定搭配；「发泄」含贬义多与情绪搭配；「散发」多与气味、气息搭配；「喷发」用于火山或比喻爆发。故选A。","__sub":"选词填空"},{"id":"yy-18305","module":"yanyu","diff":2,"exam":"医疗编","prompt":"连日来，把家国情怀融入课堂，环卫工人用身边故事打动学生。","options":["浇灌","厚植","施肥","培土"],"answer":1,"explanation":"「厚植」与「情怀」搭配得当。「厚植情怀」为书面惯用搭配；「加深」多与印象、了解搭配。故选B。","__sub":"选词填空"},{"id":"yy-18306","module":"yanyu","diff":1,"exam":"国考","prompt":"岁末年初，让监督机制长出牙齿，治沙工人把制度笼子越扎越紧。","options":["修理","修复","健全","修葺"],"answer":2,"explanation":"「健全」与「机制」搭配得当。「健全机制」为固定搭配，使完善；「修理」「修复」「修葺」均指具体物件的修补，与机制不搭。故选C。","__sub":"选词填空"},{"id":"yy-18307","module":"yanyu","diff":2,"exam":"省考","prompt":"这些年，城乡公共服务仍有落差，审计人员以实策逐步______差距。","options":["缩小","减小","缩减","减少"],"answer":0,"explanation":"「缩小」与「差距」搭配得当。「缩小差距」为固定搭配；「减少」多与数量搭配；「缩减」多与开支、编制搭配；「减小」多与阻力、噪音搭配。故选A。","__sub":"选词填空"},{"id":"yy-18308","module":"yanyu","diff":3,"exam":"事业编","prompt":"入冬以来，两岸同胞亲情割不断，快递员为青年交流______心灵心桥。","options":["架起","垒砌","修筑","铺设"],"answer":0,"explanation":"「架起」与「心桥」搭配得当。「架起心桥」为惯用比喻搭配；「修筑」用于道路工程；「垒砌」用于砖石；「铺设」用于管线轨道。故选A。","__sub":"选词填空"},{"id":"yy-18309","module":"yanyu","diff":2,"exam":"国考","prompt":"近年来，一揽子政策精准落地，税务干部着力______市场信心。","options":["鼓动","提起","提振","振作"],"answer":2,"explanation":"「提振」与「信心」搭配得当。「提振信心」为固定搭配；「提起」多与精神、话题搭配；「振作」为不及物动词；「鼓动」含煽动义。故选C。","__sub":"选词填空"},{"id":"yy-18310","module":"yanyu","diff":2,"exam":"医疗编","prompt":"盛夏时节，两岸同胞亲情割不断，博物馆讲解员为青年交流______心灵心桥。","options":["修筑","架起","铺设","垒砌"],"answer":1,"explanation":"「架起」与「心桥」搭配得当。「架起心桥」为惯用比喻搭配；「修筑」用于道路工程；「垒砌」用于砖石；「铺设」用于管线轨道。故选B。","__sub":"选词填空"},{"id":"yy-18311","module":"yanyu","diff":2,"exam":"国考","prompt":"连日来，急难险重任务面前，图书管理员主动______最重的责任。","options":["抬起","挑起","背起","扛起"],"answer":3,"explanation":"「扛起」与「责任」搭配得当。「扛起责任」为惯用搭配；「背起」多与行囊、伤员搭配；「挑起」多与担子、重担搭配；「抬起」为具体动作。故选D。","__sub":"选词填空"},{"id":"yy-18312","module":"yanyu","diff":1,"exam":"事业编","prompt":"盛夏时节，老旧小区加装电梯、增设车位，税务干部尽力______居民多样需求。","options":["充足","满足","充盈","满意"],"answer":1,"explanation":"「满足」与「需求」搭配得当。「满足需求」为固定搭配；「满意」为形容词；「充足」「充盈」为形容词不能带宾语。故选B。","__sub":"选词填空"},{"id":"yy-18313","module":"yanyu","diff":2,"exam":"省考","prompt":"初秋时节，让监督机制长出牙齿，治沙工人把制度笼子越扎越紧。","options":["修葺","修复","健全","修理"],"answer":2,"explanation":"「健全」与「机制」搭配得当。「健全机制」为固定搭配，使完善；「修理」「修复」「修葺」均指具体物件的修补，与机制不搭。故选C。","__sub":"选词填空"},{"id":"yy-18314","module":"yanyu","diff":3,"exam":"省考","prompt":"这些年，城乡公共服务仍有落差，社区规划师以实策逐步______差距。","options":["减少","缩小","缩减","减小"],"answer":1,"explanation":"「缩小」与「差距」搭配得当。「缩小差距」为固定搭配；「减少」多与数量搭配；「缩减」多与开支、编制搭配；「减小」多与阻力、噪音搭配。故选B。","__sub":"选词填空"},{"id":"yy-18315","module":"yanyu","diff":1,"exam":"国考","prompt":"这些年，民生领域还有欠账，社区规划师列出清单逐项______短板。","options":["补丁","贴补","补齐","修补"],"answer":2,"explanation":"「补齐」与「短板」搭配得当。「补齐短板」为固定搭配；「补丁」为名词；「修补」多用于衣物器物；「贴补」多与费用搭配。故选C。","__sub":"选词填空"},{"id":"yy-18316","module":"yanyu","diff":3,"exam":"国考","prompt":"近期，古城修缮不搞大拆大建，调解员让千年文脉在街巷间静静流淌。","options":["续接","接通","延续","连接"],"answer":2,"explanation":"「延续」与「文脉」搭配得当。「延续文脉」为惯用搭配；「连接」指具体相连；「续接」多与线路搭配；「接通」用于电话、电路。故选C。","__sub":"选词填空"},{"id":"yy-18317","module":"yanyu","diff":3,"exam":"教师编","prompt":"这些年，改革到了深水区，广大建设者以钉钉子精神______工作局面。","options":["掀开","揭开","打开","翻开"],"answer":2,"explanation":"「打开」与「局面」搭配得当。「打开局面」为固定搭配；「翻开」用于书页；「揭开」多与谜底、序幕搭配；「掀开」用于盖子、帘子。故选C。","__sub":"选词填空"},{"id":"yy-18318","module":"yanyu","diff":1,"exam":"省考","prompt":"初秋时节，金融活水精准滴灌，治沙工人为小微企业______发展动力。","options":["灌输","注入","输入","灌入"],"answer":1,"explanation":"「注入」与「动力」搭配得当。「注入动力」为惯用搭配；「灌入」用于液体；「输入」用于数据、血液；「注入」亦可用于资金，但「注入动力」最规范。故选B。","__sub":"选词填空"},{"id":"yy-18319","module":"yanyu","diff":2,"exam":"省考","prompt":"近年来，乡情是最深的牵挂，设计师以商会为平台______情感纽带。","options":["织牢","系牢","捆牢","绑牢"],"answer":0,"explanation":"「织牢」与「纽带」搭配得当。「织牢纽带」为惯用比喻搭配；「系牢」「捆牢」「绑牢」均为具体系绑动作。故选A。","__sub":"选词填空"},{"id":"yy-18320","module":"yanyu","diff":2,"exam":"国考","prompt":"眼下，让监督机制长出牙齿，工程师把制度笼子越扎越紧。","options":["修复","健全","修理","修葺"],"answer":1,"explanation":"「健全」与「机制」搭配得当。「健全机制」为固定搭配，使完善；「修理」「修复」「修葺」均指具体物件的修补，与机制不搭。故选B。","__sub":"选词填空"},{"id":"yy-18321","module":"yanyu","diff":1,"exam":"国考","prompt":"盛夏时节，让农产品出村进城，基层干部多方合力______销售通道。","options":["扩宽","拓宽","开辟","开宽"],"answer":1,"explanation":"「拓宽」与「通道」搭配得当。「拓宽通道」为固定搭配；「开宽」非规范；「扩宽」多用于道路；「拓宽」亦用于道路但与渠道、通道搭配最常见。故选B。","__sub":"选词填空"},{"id":"yy-18322","module":"yanyu","diff":2,"exam":"省考","prompt":"岁末年初，每一起案件都关乎群众对法治的信仰，审计人员用公正裁判______正义。","options":["护卫","防御","捍卫","保卫"],"answer":2,"explanation":"「捍卫」与「公平」搭配得当。「捍卫公平」为书面惯用搭配；「保卫」多与祖国、和平搭配；「护卫」为护送守卫；「防御」用于军事、疫情。故选C。","__sub":"选词填空"},{"id":"yy-18323","module":"yanyu","diff":2,"exam":"事业编","prompt":"这些年，危难时刻冲得上去，非遗传承人的行动______了共产党员的担当。","options":["彰显","显露","显摆","暴露"],"answer":0,"explanation":"「彰显」与「担当」搭配得当。「彰显担当」为固定搭配，褒义；「显摆」为口语含贬义；「显露」中性；「暴露」多含贬义。故选A。","__sub":"选词填空"},{"id":"yy-18324","module":"yanyu","diff":1,"exam":"国考","prompt":"这些年，一年一度的民生大考结束，医护人员向群众______了温暖的答卷。","options":["递交","上缴","呈报","交出"],"answer":3,"explanation":"「交出」与「答卷」搭配得当。「交出答卷」为惯用搭配；「递交」多与申请、辞呈搭配；「呈报」多与公文搭配且含上下级意味；「上缴」多与款项、物品搭配。故选D。","__sub":"选词填空"},{"id":"yy-18325","module":"yanyu","diff":2,"exam":"事业编","prompt":"岁末年初，让公共服务覆盖城乡，设计师持续______政策体系。","options":["补完","完善","修完","完缮"],"answer":1,"explanation":"「完善」与「体系」搭配得当。「完善体系」为固定搭配；「完缮」「修完」「补完」均非规范搭配。故选B。","__sub":"选词填空"},{"id":"yy-18326","module":"yanyu","diff":2,"exam":"省考","prompt":"盛夏时节，民生领域还有欠账，青年学子列出清单逐项______短板。","options":["补丁","补齐","修补","贴补"],"answer":1,"explanation":"「补齐」与「短板」搭配得当。「补齐短板」为固定搭配；「补丁」为名词；「修补」多用于衣物器物；「贴补」多与费用搭配。故选B。","__sub":"选词填空"},{"id":"yy-18327","module":"yanyu","diff":2,"exam":"省考","prompt":"今年以来，订单排到明年，环卫工人发展的信心。","options":["倍受","倍加","倍增","加倍"],"answer":2,"explanation":"「倍增」与「信心」搭配得当。「信心倍增」为惯用搭配；「加倍」为动词或副词；「倍加」多与珍惜搭配；「倍受」多与关注搭配。故选C。","__sub":"选词填空"},{"id":"yy-18328","module":"yanyu","diff":2,"exam":"省考","prompt":"开春以来，面对转型路上的重重难关，审计人员迎难而上，把一个个难关逐一______。","options":["化解","攻克","破除","克服"],"answer":1,"explanation":"「攻克」与「难关」搭配得当。「攻克难关」为固定搭配，强调付出努力战而胜之；「克服」多与困难、缺点搭配；「破除」多与迷信、藩篱搭配；「化解」多与矛盾、风险搭配。故选B。","__sub":"选词填空"},{"id":"yy-18329","module":"yanyu","diff":1,"exam":"事业编","prompt":"一段时间以来，危难时刻冲得上去，基层干部的行动______了共产党员的担当。","options":["暴露","彰显","显摆","显露"],"answer":1,"explanation":"「彰显」与「担当」搭配得当。「彰显担当」为固定搭配，褒义；「显摆」为口语含贬义；「显露」中性；「暴露」多含贬义。故选B。","__sub":"选词填空"},{"id":"yy-18330","module":"yanyu","diff":2,"exam":"医疗编","prompt":"这些年，民生实事清单公示上墙，民警一件一件______承诺。","options":["兑现","实现","完成","达成"],"answer":0,"explanation":"「兑现」与「承诺」搭配得当。「兑现承诺」为固定搭配；「实现」多与梦想、目标搭配；「完成」多与任务搭配；「达成」多与协议搭配。故选A。","__sub":"选词填空"},{"id":"yy-18331","module":"yanyu","diff":1,"exam":"国考","prompt":"初秋时节，放宽准入激发创业热情，法官让创造活力。","options":["涌出","淌出","涌流","流出"],"answer":2,"explanation":"「涌流」与「活力」搭配得当。「活力涌流」为惯用表达；「流出」「淌出」「涌出」均用于液体且为具体动作。故选C。","__sub":"选词填空"},{"id":"yy-18332","module":"yanyu","diff":3,"exam":"事业编","prompt":"近期，新区建设的宏伟蓝图已经展开，工程师正把一张张蓝图变成施工图。","options":["编织","绘就","修筑","耕耘"],"answer":1,"explanation":"「绘就」与「蓝图」搭配得当。「绘就蓝图」为惯用搭配；「修筑」用于道路工事；「耕耘」用于田地或比喻辛勤付出；「编织」多与梦想、纽带搭配，与蓝图不搭。故选B。","__sub":"选词填空"},{"id":"yy-18333","module":"yanyu","diff":2,"exam":"国考","prompt":"近年来，老厂房变身文创园，基层干部让工业遗存______新的活力。","options":["焕发","焕新","换发","更新"],"answer":0,"explanation":"「焕发」与「活力」搭配得当。「焕发活力」为固定搭配；「换发」为误写；「焕新」「更新」多用于设施、面貌且为动词直接带宾语。故选A。","__sub":"选词填空"},{"id":"yy-18334","module":"yanyu","diff":2,"exam":"省考","prompt":"近期，把消费潜力转化为增长实绩，网格员拿出了实招硬招。","options":["发泄","释放","散发","喷发"],"answer":1,"explanation":"「释放」与「潜力」搭配得当。「释放潜力」为固定搭配；「发泄」含贬义多与情绪搭配；「散发」多与气味、气息搭配；「喷发」用于火山或比喻爆发。故选B。","__sub":"选词填空"},{"id":"yy-18335","module":"yanyu","diff":2,"exam":"国考","prompt":"开春以来，改革红利持续显现，市场活力不断，果农信心更足。","options":["爆发","突发","暴发","迸发"],"answer":3,"explanation":"「迸发」与「活力」搭配得当。「迸发活力」为惯用搭配；「爆发」多用于战争、疫情或力量；「突发」多与事件搭配；「暴发」多用于疫情或含贬义。故选D。","__sub":"选词填空"},{"id":"yy-18336","module":"yanyu","diff":1,"exam":"国考","prompt":"入冬以来，让公共服务覆盖城乡，消防员持续______政策体系。","options":["修完","补完","完善","完缮"],"answer":2,"explanation":"「完善」与「体系」搭配得当。「完善体系」为固定搭配；「完缮」「修完」「补完」均非规范搭配。故选C。","__sub":"选词填空"},{"id":"yy-18337","module":"yanyu","diff":1,"exam":"省考","prompt":"开春以来，让农产品出村进城，程序员多方合力______销售通道。","options":["开宽","开辟","扩宽","拓宽"],"answer":3,"explanation":"「拓宽」与「通道」搭配得当。「拓宽通道」为固定搭配；「开宽」非规范；「扩宽」多用于道路；「拓宽」亦用于道路但与渠道、通道搭配最常见。故选D。","__sub":"选词填空"},{"id":"yy-18338","module":"yanyu","diff":1,"exam":"医疗编","prompt":"这些年，脱贫不是终点，图书管理员多措并举______脱贫成果。","options":["凝固","加固","稳固","巩固"],"answer":3,"explanation":"「巩固」与「成果」搭配得当。「巩固成果」为固定搭配；「稳固」为形容词或使稳固；「加固」用于建筑堤坝；「凝固」为物理变化。故选D。","__sub":"选词填空"},{"id":"yy-18339","module":"yanyu","diff":1,"exam":"省考","prompt":"近期，越是众声喧哗，越需要______共识，志愿者们把大家的心拢到一起。","options":["冻住","凝固","凝结","凝聚"],"answer":3,"explanation":"「凝聚」与「共识」搭配得当。「凝聚共识」为固定搭配；「凝固」「冻住」「凝结」均为物理状态变化，用于抽象共识不当。故选D。","__sub":"选词填空"},{"id":"yy-18340","module":"yanyu","diff":2,"exam":"国考","prompt":"近年来，让公共服务覆盖城乡，环卫工人持续______政策体系。","options":["补完","完缮","完善","修完"],"answer":2,"explanation":"「完善」与「体系」搭配得当。「完善体系」为固定搭配；「完缮」「修完」「补完」均非规范搭配。故选C。","__sub":"选词填空"},{"id":"yy-18341","module":"yanyu","diff":2,"exam":"国考","prompt":"近期，每一起案件都关乎群众对法治的信仰，科研人员用公正裁判______正义。","options":["捍卫","护卫","防御","保卫"],"answer":0,"explanation":"「捍卫」与「公平」搭配得当。「捍卫公平」为书面惯用搭配；「保卫」多与祖国、和平搭配；「护卫」为护送守卫；「防御」用于军事、疫情。故选A。","__sub":"选词填空"},{"id":"yy-18342","module":"yanyu","diff":2,"exam":"国考","prompt":"开春以来，减税降费政策落地，税务干部让企业真切感受到红利。","options":["散发","发射","释放","发放"],"answer":2,"explanation":"「释放」与「红利」搭配得当。「释放红利」为惯用搭配；「发放」多与物资、贷款搭配；「散发」多与气味搭配；「发射」用于子弹、卫星。故选C。","__sub":"选词填空"},{"id":"yy-18343","module":"yanyu","diff":1,"exam":"省考","prompt":"今年以来，让监督机制长出牙齿，乡村医生把制度笼子越扎越紧。","options":["健全","修复","修理","修葺"],"answer":0,"explanation":"「健全」与「机制」搭配得当。「健全机制」为固定搭配，使完善；「修理」「修复」「修葺」均指具体物件的修补，与机制不搭。故选A。","__sub":"选词填空"},{"id":"yy-18344","module":"yanyu","diff":2,"exam":"教师编","prompt":"初秋时节，春潮拍岸千帆竞，审计人员感受到创新活力。","options":["淌动","流出","涌出","涌动"],"answer":3,"explanation":"「涌动」与「活力」搭配得当。「活力涌动」为惯用表达；「涌出」「流出」为具体动作；「淌动」非规范。故选D。","__sub":"选词填空"},{"id":"yy-18345","module":"yanyu","diff":2,"exam":"省考","prompt":"这些年，把家国情怀融入课堂，茶农用身边故事打动学生。","options":["浇灌","厚植","培土","施肥"],"answer":1,"explanation":"「厚植」与「情怀」搭配得当。「厚植情怀」为书面惯用搭配；「加深」多与印象、了解搭配。故选B。","__sub":"选词填空"},{"id":"yy-18346","module":"yanyu","diff":3,"exam":"国考","prompt":"初秋时节，市场细胞活跃起来，铁路养护工让经济肌体活力。","options":["塞满","填满","装满","充满"],"answer":3,"explanation":"「充满」与「活力」搭配得当。「充满活力」为固定搭配；「填满」「塞满」「装满」均为具体动作，用于抽象活力不当。故选D。","__sub":"选词填空"},{"id":"yy-18347","module":"yanyu","diff":2,"exam":"国考","prompt":"一段时间以来，红色资源是最生动的教材，公交司机让红色血脉代代相传。","options":["延续","接续","继续","赓续"],"answer":3,"explanation":"「赓续」与「血脉」搭配得当。「赓续血脉」为书面惯用搭配；「继续」为一般动词；「接续」多与手续、产业搭配；「延续」多与生命、文脉搭配。故选D。","__sub":"选词填空"},{"id":"yy-18348","module":"yanyu","diff":1,"exam":"国考","prompt":"近年来，把资源优势变成产业优势，税务干部下大气力______区域品牌。","options":["锻打","打造","打制","拍打"],"answer":1,"explanation":"「打造」与「品牌」搭配得当。「打造品牌」为固定搭配；「打制」「锻打」用于金属器物；「拍打」为具体动作。故选B。","__sub":"选词填空"},{"id":"yy-18349","module":"yanyu","diff":2,"exam":"事业编","prompt":"眼下，几十年如一日，驻村干部在平凡岗位上______着为民初心。","options":["保守","坚守","把守","守卫"],"answer":1,"explanation":"「坚守」与「初心」搭配得当。「坚守初心」为固定搭配；「保守」多与秘密搭配；「守卫」用于边疆、家园；「把守」用于关口。故选B。","__sub":"选词填空"},{"id":"yy-18350","module":"yanyu","diff":2,"exam":"国考","prompt":"入冬以来，把消费潜力转化为增长实绩，青年学子拿出了实招硬招。","options":["发泄","释放","散发","喷发"],"answer":1,"explanation":"「释放」与「潜力」搭配得当。「释放潜力」为固定搭配；「发泄」含贬义多与情绪搭配；「散发」多与气味、气息搭配；「喷发」用于火山或比喻爆发。故选B。","__sub":"选词填空"},{"id":"yy-18351","module":"yanyu","diff":1,"exam":"省考","prompt":"初秋时节，改革到了深水区，护林员以钉钉子精神______工作局面。","options":["打开","掀开","翻开","揭开"],"answer":0,"explanation":"「打开」与「局面」搭配得当。「打开局面」为固定搭配；「翻开」用于书页；「揭开」多与谜底、序幕搭配；「掀开」用于盖子、帘子。故选A。","__sub":"选词填空"},{"id":"yy-18352","module":"yanyu","diff":2,"exam":"国考","prompt":"开春以来，一次次说到做到，税务干部用行动______了群众的信任。","options":["换取","获得","博得","赢得"],"answer":3,"explanation":"「赢得」与「信任」搭配得当。「赢得信任」为固定搭配，强调经努力而获得；「获得」中性；「博得」多与同情、喝彩搭配；「换取」含交换义。故选D。","__sub":"选词填空"},{"id":"yy-18353","module":"yanyu","diff":2,"exam":"教师编","prompt":"近年来，卡脖子技术亟待攻坚，驻村干部集中力量______一个个瓶颈。","options":["突破","捅破","撞破","冲破"],"answer":0,"explanation":"「突破」与「瓶颈」搭配得当。「突破瓶颈」为固定搭配；「冲破」多与封锁、束缚搭配；「撞破」「捅破」为具体动作或与窗户纸等搭配。故选A。","__sub":"选词填空"},{"id":"yy-18354","module":"yanyu","diff":2,"exam":"国考","prompt":"入冬以来，改革到了深水区，调解员以钉钉子精神______工作局面。","options":["揭开","翻开","打开","掀开"],"answer":2,"explanation":"「打开」与「局面」搭配得当。「打开局面」为固定搭配；「翻开」用于书页；「揭开」多与谜底、序幕搭配；「掀开」用于盖子、帘子。故选C。","__sub":"选词填空"},{"id":"yy-18355","module":"yanyu","diff":2,"exam":"国考","prompt":"近期，脱贫不是终点，渔民多措并举______脱贫成果。","options":["巩固","加固","凝固","稳固"],"answer":0,"explanation":"「巩固」与「成果」搭配得当。「巩固成果」为固定搭配；「稳固」为形容词或使稳固；「加固」用于建筑堤坝；「凝固」为物理变化。故选A。","__sub":"选词填空"},{"id":"yy-18356","module":"yanyu","diff":1,"exam":"国考","prompt":"入冬以来，越是众声喧哗，越需要______共识，社区工作者把大家的心拢到一起。","options":["凝结","凝固","冻住","凝聚"],"answer":3,"explanation":"「凝聚」与「共识」搭配得当。「凝聚共识」为固定搭配；「凝固」「冻住」「凝结」均为物理状态变化，用于抽象共识不当。故选D。","__sub":"选词填空"},{"id":"yy-18357","module":"yanyu","diff":3,"exam":"事业编","prompt":"今年以来，卡脖子技术亟待攻坚，执法人员集中力量______一个个瓶颈。","options":["突破","冲破","撞破","捅破"],"answer":0,"explanation":"「突破」与「瓶颈」搭配得当。「突破瓶颈」为固定搭配；「冲破」多与封锁、束缚搭配；「撞破」「捅破」为具体动作或与窗户纸等搭配。故选A。","__sub":"选词填空"},{"id":"yy-18358","module":"yanyu","diff":2,"exam":"省考","prompt":"初秋时节，初心如磐，使命在肩，青年学子把承诺落到一件件小事上。","options":["践行","执行","履行","旅行"],"answer":0,"explanation":"「践行」与「使命」搭配得当。「践行使命」为固定搭配；「履行」多与职责、义务、合同搭配；「执行」多与命令、判决、任务搭配；「旅行」为出行义。故选A。","__sub":"选词填空"},{"id":"yy-18359","module":"yanyu","diff":3,"exam":"省考","prompt":"连日来，老旧小区加装电梯、增设车位，设计师尽力______居民多样需求。","options":["满意","满足","充盈","充足"],"answer":1,"explanation":"「满足」与「需求」搭配得当。「满足需求」为固定搭配；「满意」为形容词；「充足」「充盈」为形容词不能带宾语。故选B。","__sub":"选词填空"},{"id":"yy-18360","module":"yanyu","diff":1,"exam":"事业编","prompt":"岁末年初，安全底线不可逾越，驻村干部24小时轮班值守。","options":["把守","镇守","坚守","看守"],"answer":2,"explanation":"「坚守」与「底线」搭配得当。「坚守底线」为固定搭配；「看守」「把守」「镇守」均指具体看护动作，多用于人员、关口、城池。故选C。","__sub":"选词填空"},{"id":"yy-18361","module":"yanyu","diff":3,"exam":"国考","prompt":"入冬以来，从受理到反馈全流程留痕，青年学子以数字化手段______管理闭环。","options":["构建","搭圈","构画","圈画"],"answer":0,"explanation":"「构建」与「闭环」搭配得当。「构建闭环」为惯用搭配；其余选项均非规范搭配。故选A。","__sub":"选词填空"},{"id":"yy-18362","module":"yanyu","diff":3,"exam":"医疗编","prompt":"岁末年初，一揽子政策精准落地，青年学子着力______市场信心。","options":["振作","提起","鼓动","提振"],"answer":3,"explanation":"「提振」与「信心」搭配得当。「提振信心」为固定搭配；「提起」多与精神、话题搭配；「振作」为不及物动词；「鼓动」含煽动义。故选D。","__sub":"选词填空"},{"id":"yy-18363","module":"yanyu","diff":1,"exam":"省考","prompt":"连日来，放宽准入激发创业热情，乡村医生让创造活力。","options":["涌出","涌流","流出","淌出"],"answer":1,"explanation":"「涌流」与「活力」搭配得当。「活力涌流」为惯用表达；「流出」「淌出」「涌出」均用于液体且为具体动作。故选B。","__sub":"选词填空"},{"id":"yy-18364","module":"yanyu","diff":3,"exam":"事业编","prompt":"近期，众人的事情由众人商量，农技人员把各方______到规划图上。","options":["凝聚","归拢","收拢","聚拢"],"answer":0,"explanation":"「凝聚」与「智慧」搭配得当。「凝聚智慧」为惯用搭配；「聚拢」「收拢」「归拢」均为具体收拢动作，用于抽象智慧不当。故选A。","__sub":"选词填空"},{"id":"yy-18365","module":"yanyu","diff":2,"exam":"事业编","prompt":"今年以来，让要素流动更顺畅，就要______体制机制的藩篱。","options":["拆除","捣毁","铲平","破除"],"answer":3,"explanation":"「破除」与「藩篱」搭配得当。「破除藩篱」为固定搭配；「拆除」用于建筑；「铲平」用于场地；「捣毁」用于巢穴、据点且含暴力义。故选D。","__sub":"选词填空"},{"id":"yy-18366","module":"yanyu","diff":2,"exam":"国考","prompt":"岁末年初，乡情是最深的牵挂，农技人员以商会为平台______情感纽带。","options":["织牢","绑牢","系牢","捆牢"],"answer":0,"explanation":"「织牢」与「纽带」搭配得当。「织牢纽带」为惯用比喻搭配；「系牢」「捆牢」「绑牢」均为具体系绑动作。故选A。","__sub":"选词填空"},{"id":"yy-18367","module":"yanyu","diff":1,"exam":"国考","prompt":"连日来，齐抓共管不是一句口号，农技人员推动齐抓共管合力。","options":["成形","形成","成型","成立"],"answer":1,"explanation":"「形成」与「合力」搭配得当。「形成合力」为固定搭配；「成形」「成型」指具形；「成立」多与组织搭配。故选B。","__sub":"选词填空"},{"id":"yy-18368","module":"yanyu","diff":3,"exam":"事业编","prompt":"连日来，向存量要效益，广大建设者为产业升级______新空间。","options":["拓展","拓开","展开","开展"],"answer":0,"explanation":"「拓展」与「空间」搭配得当。「拓展空间」为固定搭配；「拓开」非规范；「开展」多与活动搭配；「展开」多与画卷、攻势搭配。故选A。","__sub":"选词填空"},{"id":"yy-18369","module":"yanyu","diff":2,"exam":"国考","prompt":"近年来，市场细胞活跃起来，公交司机让经济肌体活力。","options":["装满","塞满","充满","填满"],"answer":2,"explanation":"「充满」与「活力」搭配得当。「充满活力」为固定搭配；「填满」「塞满」「装满」均为具体动作，用于抽象活力不当。故选C。","__sub":"选词填空"},{"id":"yy-18370","module":"yanyu","diff":2,"exam":"国考","prompt":"近年来，筑起生态安全屏障，税务干部让青山常在绿水长流。","options":["砌牢","锁牢","拴牢","筑牢"],"answer":3,"explanation":"「筑牢」与「屏障」搭配得当。「筑牢屏障」为惯用搭配；「砌牢」用于砖石；「锁牢」「拴牢」用于器物。故选D。","__sub":"选词填空"},{"id":"yy-18371","module":"yanyu","diff":1,"exam":"国考","prompt":"这些年，民生领域还有欠账，渔民列出清单逐项______短板。","options":["贴补","补丁","补齐","修补"],"answer":2,"explanation":"「补齐」与「短板」搭配得当。「补齐短板」为固定搭配；「补丁」为名词；「修补」多用于衣物器物；「贴补」多与费用搭配。故选C。","__sub":"选词填空"},{"id":"yy-18372","module":"yanyu","diff":1,"exam":"国考","prompt":"开春以来，手握核心技术专利，手工艺人创新的底气。","options":["更足","更壮","更强","更硬"],"answer":0,"explanation":"「更足」与「底气」搭配得当。「底气更足」为惯用搭配；「更硬」多与作风搭配；「更强」多与实力搭配；「更壮」用于体格。故选A。","__sub":"选词填空"},{"id":"yy-18373","module":"yanyu","diff":2,"exam":"教师编","prompt":"盛夏时节，小哨兵大作用，电力工人让基层网格______更大作用。","options":["发挥","施展","表现","发扬"],"answer":0,"explanation":"「发挥」与「作用」搭配得当。「发挥作用」为固定搭配；「发扬」多与传统搭配；「施展」多与才华、拳脚搭配。故选A。","__sub":"选词填空"},{"id":"yy-18374","module":"yanyu","diff":2,"exam":"事业编","prompt":"盛夏时节，邻里纠纷无小事，科研人员用真心______一件件矛盾。","options":["解开","瓦解","消融","化解"],"answer":3,"explanation":"「化解」与「矛盾」搭配得当。「化解矛盾」为固定搭配；「解开」多与疙瘩、谜团搭配；「消融」用于冰雪；「瓦解」多用于组织、士气。故选D。","__sub":"选词填空"},{"id":"yy-18375","module":"yanyu","diff":1,"exam":"省考","prompt":"岁末年初，停车难是城市治理的老大难，果农用共享思维______了这一难题。","options":["解开","解冻","解释","破解"],"answer":3,"explanation":"「破解」与「难题」搭配得当。「破解难题」为固定搭配；「解开」多与绳结、心结搭配；「解冻」用于资产、关系；「解释」为说明缘由。故选D。","__sub":"选词填空"},{"id":"yy-18376","module":"yanyu","diff":3,"exam":"国考","prompt":"这些年，面对转型路上的重重难关，医护人员迎难而上，把一个个难关逐一______。","options":["破除","克服","化解","攻克"],"answer":3,"explanation":"「攻克」与「难关」搭配得当。「攻克难关」为固定搭配，强调付出努力战而胜之；「克服」多与困难、缺点搭配；「破除」多与迷信、藩篱搭配；「化解」多与矛盾、风险搭配。故选D。","__sub":"选词填空"},{"id":"yy-18377","module":"yanyu","diff":1,"exam":"事业编","prompt":"开春以来，传统村落保护性开发，消防员既富了口袋，也______了乡愁。","options":["留住","截留","拘留","扣留"],"answer":0,"explanation":"「留住」与「乡愁」搭配得当。「留住乡愁」为惯用表达；「扣留」「拘留」「截留」均为法律或强制扣押义，感情色彩不合。故选A。","__sub":"选词填空"},{"id":"yy-18378","module":"yanyu","diff":3,"exam":"国考","prompt":"近期，让公共服务覆盖城乡，设计师持续______政策体系。","options":["补完","完缮","修完","完善"],"answer":3,"explanation":"「完善」与「体系」搭配得当。「完善体系」为固定搭配；「完缮」「修完」「补完」均非规范搭配。故选D。","__sub":"选词填空"},{"id":"yy-18379","module":"yanyu","diff":1,"exam":"教师编","prompt":"初秋时节，众人的事情由众人商量，非遗传承人把各方______到规划图上。","options":["凝聚","归拢","收拢","聚拢"],"answer":0,"explanation":"「凝聚」与「智慧」搭配得当。「凝聚智慧」为惯用搭配；「聚拢」「收拢」「归拢」均为具体收拢动作，用于抽象智慧不当。故选A。","__sub":"选词填空"},{"id":"yy-18380","module":"yanyu","diff":2,"exam":"医疗编","prompt":"这些年，初心如磐，使命在肩，网格员把承诺落到一件件小事上。","options":["执行","履行","旅行","践行"],"answer":3,"explanation":"「践行」与「使命」搭配得当。「践行使命」为固定搭配；「履行」多与职责、义务、合同搭配；「执行」多与命令、判决、任务搭配；「旅行」为出行义。故选D。","__sub":"选词填空"},{"id":"yy-18381","module":"yanyu","diff":1,"exam":"省考","prompt":"岁末年初，红色资源是最生动的教材，图书管理员让红色血脉代代相传。","options":["延续","接续","赓续","继续"],"answer":2,"explanation":"「赓续」与「血脉」搭配得当。「赓续血脉」为书面惯用搭配；「继续」为一般动词；「接续」多与手续、产业搭配；「延续」多与生命、文脉搭配。故选C。","__sub":"选词填空"},{"id":"yy-18382","module":"yanyu","diff":2,"exam":"省考","prompt":"近期，卡脖子技术亟待攻坚，消防员集中力量______一个个瓶颈。","options":["捅破","突破","撞破","冲破"],"answer":1,"explanation":"「突破」与「瓶颈」搭配得当。「突破瓶颈」为固定搭配；「冲破」多与封锁、束缚搭配；「撞破」「捅破」为具体动作或与窗户纸等搭配。故选B。","__sub":"选词填空"},{"id":"yy-18383","module":"yanyu","diff":2,"exam":"医疗编","prompt":"盛夏时节，一揽子政策精准落地，工程师着力______市场信心。","options":["提振","鼓动","振作","提起"],"answer":0,"explanation":"「提振」与「信心」搭配得当。「提振信心」为固定搭配；「提起」多与精神、话题搭配；「振作」为不及物动词；「鼓动」含煽动义。故选A。","__sub":"选词填空"},{"id":"yy-18384","module":"yanyu","diff":3,"exam":"国考","prompt":"近年来，景区客流高峰来临，果农全员上岗______游览秩序。","options":["保护","护卫","维持","维护"],"answer":3,"explanation":"「维护」与「秩序」搭配得当。「维护秩序」为固定搭配；「维持」多与生活、现状搭配；「保护」多与权益、环境搭配；「护卫」用于人员、目标。故选D。","__sub":"选词填空"},{"id":"yy-18385","module":"yanyu","diff":1,"exam":"国考","prompt":"近期，新区建设的宏伟蓝图已经展开，设计师正把一张张蓝图变成施工图。","options":["绘就","编织","耕耘","修筑"],"answer":0,"explanation":"「绘就」与「蓝图」搭配得当。「绘就蓝图」为惯用搭配；「修筑」用于道路工事；「耕耘」用于田地或比喻辛勤付出；「编织」多与梦想、纽带搭配，与蓝图不搭。故选A。","__sub":"选词填空"},{"id":"yy-18386","module":"yanyu","diff":1,"exam":"事业编","prompt":"近年来，金融活水精准滴灌，非遗传承人为小微企业______发展动力。","options":["注入","灌输","输入","灌入"],"answer":0,"explanation":"「注入」与「动力」搭配得当。「注入动力」为惯用搭配；「灌入」用于液体；「输入」用于数据、血液；「注入」亦可用于资金，但「注入动力」最规范。故选A。","__sub":"选词填空"},{"id":"yy-18387","module":"yanyu","diff":2,"exam":"省考","prompt":"开春以来，让新业态释放新动能，设计师在制度创新上先行先试。","options":["引爆","激发","点燃","发动"],"answer":1,"explanation":"「激发」与「动能」搭配得当。「激发动能」为惯用搭配；「发动」多与机器、群众搭配；「点燃」多与激情搭配；「引爆」多与话题、舆论搭配且含突然义。故选B。","__sub":"选词填空"},{"id":"yy-18388","module":"yanyu","diff":2,"exam":"省考","prompt":"盛夏时节，初心如磐，使命在肩，调解员把承诺落到一件件小事上。","options":["执行","履行","践行","旅行"],"answer":2,"explanation":"「践行」与「使命」搭配得当。「践行使命」为固定搭配；「履行」多与职责、义务、合同搭配；「执行」多与命令、判决、任务搭配；「旅行」为出行义。故选C。","__sub":"选词填空"},{"id":"yy-18389","module":"yanyu","diff":2,"exam":"事业编","prompt":"岁末年初，把监督防线扎到最基层，博物馆讲解员走村入户听民声。","options":["织厚","织密","缝密","织补"],"answer":1,"explanation":"「织密」与「防线」搭配得当。「织密防线」为惯用搭配；「织厚」「缝密」非规范搭配；「织补」指修补织物。故选B。","__sub":"选词填空"},{"id":"yy-18390","module":"yanyu","diff":1,"exam":"国考","prompt":"岁末年初，让农产品出村进城，消防员多方合力______销售通道。","options":["开辟","拓宽","扩宽","开宽"],"answer":1,"explanation":"「拓宽」与「通道」搭配得当。「拓宽通道」为固定搭配；「开宽」非规范；「扩宽」多用于道路；「拓宽」亦用于道路但与渠道、通道搭配最常见。故选B。","__sub":"选词填空"},{"id":"yy-18391","module":"yanyu","diff":3,"exam":"医疗编","prompt":"近年来，新区建设的宏伟蓝图已经展开，公交司机正把一张张蓝图变成施工图。","options":["绘就","耕耘","编织","修筑"],"answer":0,"explanation":"「绘就」与「蓝图」搭配得当。「绘就蓝图」为惯用搭配；「修筑」用于道路工事；「耕耘」用于田地或比喻辛勤付出；「编织」多与梦想、纽带搭配，与蓝图不搭。故选A。","__sub":"选词填空"},{"id":"yy-18392","module":"yanyu","diff":2,"exam":"教师编","prompt":"这些年，被动状态必须改变，驻村干部用硬措施______了不利局面。","options":["回转","反转","倒转","扭转"],"answer":3,"explanation":"「扭转」与「局面」搭配得当。「扭转局面」为固定搭配；「反转」多与剧情、行情搭配；「倒转」「回转」指方向掉转。故选D。","__sub":"选词填空"},{"id":"yy-18393","module":"yanyu","diff":3,"exam":"国考","prompt":"盛夏时节，万丈高楼平地起，工程师一锤一钎______发展基础。","options":["踩实","填实","夯实","砸实"],"answer":2,"explanation":"「夯实」与「基础」搭配得当。「夯实基础」为固定搭配；「砸实」「踩实」「填实」均为具体动作。故选C。","__sub":"选词填空"},{"id":"yy-18394","module":"yanyu","diff":3,"exam":"省考","prompt":"岁末年初，老工业基地涅槃重生，手工艺人加快新旧动能步伐。","options":["转变","转换","变换","改换"],"answer":1,"explanation":"「转换」与「动能」搭配得当。「动能转换」为固定搭配；「转变」多与观念、方式搭配；「改换」「变换」多与门庭、姿势搭配。故选B。","__sub":"选词填空"},{"id":"yy-18395","module":"yanyu","diff":2,"exam":"事业编","prompt":"开春以来，营商环境就是生产力，执法人员让企业成长有沃土。","options":["培养","厚植","培育","培植"],"answer":1,"explanation":"「厚植」与「沃土」搭配得当。「厚植沃土」为书面惯用搭配；「培植」多与势力搭配含贬义；「培育」多与人才、市场搭配；「培养」多与人才搭配。故选B。","__sub":"选词填空"},{"id":"yy-18396","module":"yanyu","diff":3,"exam":"国考","prompt":"眼下，每一起案件都关乎群众对法治的信仰，环卫工人用公正裁判______正义。","options":["防御","护卫","保卫","捍卫"],"answer":3,"explanation":"「捍卫」与「公平」搭配得当。「捍卫公平」为书面惯用搭配；「保卫」多与祖国、和平搭配；「护卫」为护送守卫；「防御」用于军事、疫情。故选D。","__sub":"选词填空"},{"id":"yy-18397","module":"yanyu","diff":2,"exam":"事业编","prompt":"初秋时节，景区客流高峰来临，手工艺人全员上岗______游览秩序。","options":["护卫","保护","维护","维持"],"answer":2,"explanation":"「维护」与「秩序」搭配得当。「维护秩序」为固定搭配；「维持」多与生活、现状搭配；「保护」多与权益、环境搭配；「护卫」用于人员、目标。故选C。","__sub":"选词填空"},{"id":"yy-18398","module":"yanyu","diff":2,"exam":"国考","prompt":"今年以来，汛期将至，消防员对辖区地质灾害隐患逐点______。","options":["排查","普查","检查","检察"],"answer":0,"explanation":"「排查」与「隐患」搭配得当。「排查隐患」为固定搭配，强调逐一清查；「检查」为一般查看；「检察」为法律监督专用；「普查」为全面调查登记。故选A。","__sub":"选词填空"},{"id":"yy-18399","module":"yanyu","diff":1,"exam":"省考","prompt":"开春以来，几十年如一日，茶农在平凡岗位上______着为民初心。","options":["坚守","守卫","保守","把守"],"answer":0,"explanation":"「坚守」与「初心」搭配得当。「坚守初心」为固定搭配；「保守」多与秘密搭配；「守卫」用于边疆、家园；「把守」用于关口。故选A。","__sub":"选词填空"},{"id":"yy-18400","module":"yanyu","diff":1,"exam":"医疗编","prompt":"近期，老厂房变身文创园，快递员让工业遗存______新的活力。","options":["焕发","焕新","更新","换发"],"answer":0,"explanation":"「焕发」与「活力」搭配得当。「焕发活力」为固定搭配；「换发」为误写；「焕新」「更新」多用于设施、面貌且为动词直接带宾语。故选A。","__sub":"选词填空"},{"id":"yy-18401","module":"yanyu","diff":2,"exam":"事业编","prompt":"今年以来，放宽准入激发创业热情，果农让创造活力。","options":["涌出","流出","涌流","淌出"],"answer":2,"explanation":"「涌流」与「活力」搭配得当。「活力涌流」为惯用表达；「流出」「淌出」「涌出」均用于液体且为具体动作。故选C。","__sub":"选词填空"},{"id":"yy-18402","module":"yanyu","diff":1,"exam":"医疗编","prompt":"连日来，改革到了深水区，科研人员以钉钉子精神______工作局面。","options":["翻开","打开","揭开","掀开"],"answer":1,"explanation":"「打开」与「局面」搭配得当。「打开局面」为固定搭配；「翻开」用于书页；「揭开」多与谜底、序幕搭配；「掀开」用于盖子、帘子。故选B。","__sub":"选词填空"},{"id":"yy-18403","module":"yanyu","diff":2,"exam":"省考","prompt":"初秋时节，急难险重任务面前，社区规划师主动______最重的责任。","options":["背起","抬起","挑起","扛起"],"answer":3,"explanation":"「扛起」与「责任」搭配得当。「扛起责任」为惯用搭配；「背起」多与行囊、伤员搭配；「挑起」多与担子、重担搭配；「抬起」为具体动作。故选D。","__sub":"选词填空"},{"id":"yy-18404","module":"yanyu","diff":2,"exam":"教师编","prompt":"近期，一二三产融合发展，渔民推动产业链不断延伸。","options":["伸长","延长","拉长","延伸"],"answer":3,"explanation":"「延伸」与「链条」搭配得当。「链条延伸」为惯用搭配；「伸长」「拉长」「延长」多用于具体长度或时间。故选D。","__sub":"选词填空"},{"id":"yy-18405","module":"yanyu","diff":2,"exam":"事业编","prompt":"眼下，民生实事清单公示上墙，消防员一件一件______承诺。","options":["实现","兑现","达成","完成"],"answer":1,"explanation":"「兑现」与「承诺」搭配得当。「兑现承诺」为固定搭配；「实现」多与梦想、目标搭配；「完成」多与任务搭配；「达成」多与协议搭配。故选B。","__sub":"选词填空"},{"id":"yy-18406","module":"yanyu","diff":2,"exam":"国考","prompt":"今年以来，危难时刻冲得上去，设计师的行动______了共产党员的担当。","options":["显露","彰显","暴露","显摆"],"answer":1,"explanation":"「彰显」与「担当」搭配得当。「彰显担当」为固定搭配，褒义；「显摆」为口语含贬义；「显露」中性；「暴露」多含贬义。故选B。","__sub":"选词填空"},{"id":"yy-18407","module":"yanyu","diff":1,"exam":"国考","prompt":"开春以来，誓师大会上，乡村医生精神斗志，誓言响彻训练场。","options":["高昂","高扬","昂扬","高涨"],"answer":2,"explanation":"「昂扬」与「斗志」搭配得当。「斗志昂扬」为固定成语；「高昂」多与情绪、价格搭配；「高涨」多与热情搭配；「高扬」多与旗帜搭配。故选C。","__sub":"选词填空"},{"id":"yy-18408","module":"yanyu","diff":2,"exam":"医疗编","prompt":"这些年，让新业态释放新动能，文旅部门在制度创新上先行先试。","options":["发动","引爆","点燃","激发"],"answer":3,"explanation":"「激发」与「动能」搭配得当。「激发动能」为惯用搭配；「发动」多与机器、群众搭配；「点燃」多与激情搭配；「引爆」多与话题、舆论搭配且含突然义。故选D。","__sub":"选词填空"},{"id":"yy-18409","module":"yanyu","diff":2,"exam":"省考","prompt":"岁末年初，让监督机制长出牙齿，农技人员把制度笼子越扎越紧。","options":["健全","修葺","修理","修复"],"answer":0,"explanation":"「健全」与「机制」搭配得当。「健全机制」为固定搭配，使完善；「修理」「修复」「修葺」均指具体物件的修补，与机制不搭。故选A。","__sub":"选词填空"},{"id":"yy-18410","module":"yanyu","diff":2,"exam":"事业编","prompt":"这些年，金杯银杯不如老百姓的口碑，工程师把每件小事都当大事办。","options":["树立","建立","创立","设立"],"answer":0,"explanation":"「树立」与「口碑」搭配得当。「树立口碑」为惯用搭配；「建立」多与制度、关系搭配；「设立」多与机构搭配；「创立」多与学说、品牌搭配。故选A。","__sub":"选词填空"},{"id":"yy-18411","module":"yanyu","diff":3,"exam":"省考","prompt":"今年以来，从受理到反馈全流程留痕，医护人员以数字化手段______管理闭环。","options":["搭圈","构画","圈画","构建"],"answer":3,"explanation":"「构建」与「闭环」搭配得当。「构建闭环」为惯用搭配；其余选项均非规范搭配。故选D。","__sub":"选词填空"},{"id":"yy-18412","module":"yanyu","diff":2,"exam":"国考","prompt":"一段时间以来，一次次说到做到，快递员用行动______了群众的信任。","options":["赢得","换取","博得","获得"],"answer":0,"explanation":"「赢得」与「信任」搭配得当。「赢得信任」为固定搭配，强调经努力而获得；「获得」中性；「博得」多与同情、喝彩搭配；「换取」含交换义。故选A。","__sub":"选词填空"},{"id":"yy-18413","module":"yanyu","diff":3,"exam":"省考","prompt":"初秋时节，发展为了人民，非遗传承人把一件件民生实事办到群众心坎上，持续______福祉。","options":["增加","增进","增殖","增添"],"answer":1,"explanation":"「增进」与「民生」搭配得当。「增进福祉」为固定搭配，题干以民生统称；「增加」多与数量搭配；「增添」多与色彩、麻烦搭配；「增殖」为生物学用语。故选B。","__sub":"选词填空"},{"id":"yy-18414","module":"yanyu","diff":2,"exam":"省考","prompt":"开春以来，老旧小区加装电梯、增设车位，社区工作者尽力______居民多样需求。","options":["满足","充盈","满意","充足"],"answer":0,"explanation":"「满足」与「需求」搭配得当。「满足需求」为固定搭配；「满意」为形容词；「充足」「充盈」为形容词不能带宾语。故选A。","__sub":"选词填空"},{"id":"yy-18415","module":"yanyu","diff":2,"exam":"医疗编","prompt":"入冬以来，绿水青山就是金山银山，志愿者们代代接力______绿色生态。","options":["守望","看守","守候","守护"],"answer":3,"explanation":"「守护」与「生态」搭配得当。「守护生态」为惯用搭配，含珍视呵护义；「看守」用于财物、门户；「守候」指等待；「守望」指瞭望盼望。故选D。","__sub":"选词填空"},{"id":"yy-18416","module":"yanyu","diff":2,"exam":"事业编","prompt":"入冬以来，每一起案件都关乎群众对法治的信仰，环卫工人用公正裁判______正义。","options":["捍卫","护卫","保卫","防御"],"answer":0,"explanation":"「捍卫」与「公平」搭配得当。「捍卫公平」为书面惯用搭配；「保卫」多与祖国、和平搭配；「护卫」为护送守卫；「防御」用于军事、疫情。故选A。","__sub":"选词填空"},{"id":"yy-18417","module":"yanyu","diff":1,"exam":"事业编","prompt":"开春以来，城乡公共服务仍有落差，市场监管部门以实策逐步______差距。","options":["减少","减小","缩减","缩小"],"answer":3,"explanation":"「缩小」与「差距」搭配得当。「缩小差距」为固定搭配；「减少」多与数量搭配；「缩减」多与开支、编制搭配；「减小」多与阻力、噪音搭配。故选D。","__sub":"选词填空"},{"id":"yy-18418","module":"yanyu","diff":1,"exam":"事业编","prompt":"盛夏时节，停车难是城市治理的老大难，执法人员用共享思维______了这一难题。","options":["解释","解开","破解","解冻"],"answer":2,"explanation":"「破解」与「难题」搭配得当。「破解难题」为固定搭配；「解开」多与绳结、心结搭配；「解冻」用于资产、关系；「解释」为说明缘由。故选C。","__sub":"选词填空"},{"id":"yy-18419","module":"yanyu","diff":1,"exam":"教师编","prompt":"开春以来，誓师大会上，审计人员精神斗志，誓言响彻训练场。","options":["高昂","高扬","高涨","昂扬"],"answer":3,"explanation":"「昂扬」与「斗志」搭配得当。「斗志昂扬」为固定成语；「高昂」多与情绪、价格搭配；「高涨」多与热情搭配；「高扬」多与旗帜搭配。故选D。","__sub":"选词填空"},{"id":"yy-18420","module":"yanyu","diff":2,"exam":"事业编","prompt":"这些年，向存量要效益，非遗传承人为产业升级______新空间。","options":["展开","开展","拓展","拓开"],"answer":2,"explanation":"「拓展」与「空间」搭配得当。「拓展空间」为固定搭配；「拓开」非规范；「开展」多与活动搭配；「展开」多与画卷、攻势搭配。故选C。","__sub":"选词填空"},{"id":"yy-18421","module":"yanyu","diff":2,"exam":"事业编","prompt":"这些年，改革红利持续显现，市场活力不断，老党员信心更足。","options":["迸发","暴发","爆发","突发"],"answer":0,"explanation":"「迸发」与「活力」搭配得当。「迸发活力」为惯用搭配；「爆发」多用于战争、疫情或力量；「突发」多与事件搭配；「暴发」多用于疫情或含贬义。故选A。","__sub":"选词填空"},{"id":"yy-18422","module":"yanyu","diff":3,"exam":"国考","prompt":"今年以来，城乡公共服务仍有落差，科研人员以实策逐步______差距。","options":["减小","缩减","缩小","减少"],"answer":2,"explanation":"「缩小」与「差距」搭配得当。「缩小差距」为固定搭配；「减少」多与数量搭配；「缩减」多与开支、编制搭配；「减小」多与阻力、噪音搭配。故选C。","__sub":"选词填空"},{"id":"yy-18423","module":"yanyu","diff":1,"exam":"国考","prompt":"近期，让公共服务覆盖城乡，农技人员持续______政策体系。","options":["补完","完缮","完善","修完"],"answer":2,"explanation":"「完善」与「体系」搭配得当。「完善体系」为固定搭配；「完缮」「修完」「补完」均非规范搭配。故选C。","__sub":"选词填空"},{"id":"yy-18424","module":"yanyu","diff":2,"exam":"省考","prompt":"眼下，内生动力从哪里来？博物馆讲解员把功夫下在创新上。","options":["增强","加强","增添","增大"],"answer":0,"explanation":"「增强」与「动力」搭配得当。「增强动力」为固定搭配；「加强」多与领导、管理搭配；「增大」多与幅度、剂量搭配。故选A。","__sub":"选词填空"},{"id":"yy-18425","module":"yanyu","diff":3,"exam":"国考","prompt":"这些年，发展为了人民，工程师把一件件民生实事办到群众心坎上，持续______福祉。","options":["增添","增加","增殖","增进"],"answer":3,"explanation":"「增进」与「民生」搭配得当。「增进福祉」为固定搭配，题干以民生统称；「增加」多与数量搭配；「增添」多与色彩、麻烦搭配；「增殖」为生物学用语。故选D。","__sub":"选词填空"},{"id":"yy-18426","module":"yanyu","diff":2,"exam":"省考","prompt":"近期，老旧小区加装电梯、增设车位，乡村医生尽力______居民多样需求。","options":["充足","充盈","满意","满足"],"answer":3,"explanation":"「满足」与「需求」搭配得当。「满足需求」为固定搭配；「满意」为形容词；「充足」「充盈」为形容词不能带宾语。故选D。","__sub":"选词填空"},{"id":"yy-18427","module":"yanyu","diff":1,"exam":"国考","prompt":"今年以来，初心如磐，使命在肩，程序员把承诺落到一件件小事上。","options":["践行","旅行","执行","履行"],"answer":0,"explanation":"「践行」与「使命」搭配得当。「践行使命」为固定搭配；「履行」多与职责、义务、合同搭配；「执行」多与命令、判决、任务搭配；「旅行」为出行义。故选A。","__sub":"选词填空"},{"id":"yy-18428","module":"yanyu","diff":2,"exam":"省考","prompt":"今年以来，在广袤乡野间，铁路养护工用汗水______出乡村振兴的崭新篇章。","options":["书写","誊写","描红","抄写"],"answer":0,"explanation":"「书写」与「篇章」搭配得当。「书写篇章」为惯用搭配；「抄写」「誊写」「描红」均为照原样复写的具体动作，缺乏开创义。故选A。","__sub":"选词填空"},{"id":"yy-18429","module":"yanyu","diff":1,"exam":"省考","prompt":"今年以来，危难时刻冲得上去，广大建设者的行动______了共产党员的担当。","options":["暴露","彰显","显露","显摆"],"answer":1,"explanation":"「彰显」与「担当」搭配得当。「彰显担当」为固定搭配，褒义；「显摆」为口语含贬义；「显露」中性；「暴露」多含贬义。故选B。","__sub":"选词填空"},{"id":"yy-18430","module":"yanyu","diff":2,"exam":"医疗编","prompt":"连日来，每个孩子都有闪光点，手工艺人善于______学生潜能。","options":["掘取","开采","挖出","挖掘"],"answer":3,"explanation":"「挖掘」与「潜能」搭配得当。「挖掘潜能」为固定搭配；「挖出」「掘取」为具体动作；「开采」用于矿产。故选D。","__sub":"选词填空"},{"id":"yy-18431","module":"yanyu","diff":3,"exam":"国考","prompt":"眼下，邻里纠纷无小事，铁路养护工用真心______一件件矛盾。","options":["解开","消融","瓦解","化解"],"answer":3,"explanation":"「化解」与「矛盾」搭配得当。「化解矛盾」为固定搭配；「解开」多与疙瘩、谜团搭配；「消融」用于冰雪；「瓦解」多用于组织、士气。故选D。","__sub":"选词填空"},{"id":"yy-18432","module":"yanyu","diff":2,"exam":"国考","prompt":"今年以来，每一起案件都关乎群众对法治的信仰，医护人员用公正裁判______正义。","options":["护卫","保卫","防御","捍卫"],"answer":3,"explanation":"「捍卫」与「公平」搭配得当。「捍卫公平」为书面惯用搭配；「保卫」多与祖国、和平搭配；「护卫」为护送守卫；「防御」用于军事、疫情。故选D。","__sub":"选词填空"},{"id":"yy-18433","module":"yanyu","diff":1,"exam":"事业编","prompt":"今年以来，一网通办让数据多跑路，老党员以流程再造______政务效能。","options":["抬高","拔高","提高","提升"],"answer":3,"explanation":"「提升」与「效能」搭配得当。「提升效能」为固定搭配；「提高」多与水平、价格搭配；「拔高」含刻意抬升义；「抬高」多与价格、身价搭配。故选D。","__sub":"选词填空"},{"id":"yy-18434","module":"yanyu","diff":2,"exam":"省考","prompt":"近期，两岸同胞亲情割不断，基层干部为青年交流______心灵心桥。","options":["修筑","架起","铺设","垒砌"],"answer":1,"explanation":"「架起」与「心桥」搭配得当。「架起心桥」为惯用比喻搭配；「修筑」用于道路工程；「垒砌」用于砖石；「铺设」用于管线轨道。故选B。","__sub":"选词填空"},{"id":"yy-18435","module":"yanyu","diff":1,"exam":"省考","prompt":"开春以来，让要素流动更顺畅，就要______体制机制的藩篱。","options":["铲平","破除","捣毁","拆除"],"answer":1,"explanation":"「破除」与「藩篱」搭配得当。「破除藩篱」为固定搭配；「拆除」用于建筑；「铲平」用于场地；「捣毁」用于巢穴、据点且含暴力义。故选B。","__sub":"选词填空"},{"id":"yy-18436","module":"yanyu","diff":2,"exam":"省考","prompt":"盛夏时节，停车难是城市治理的老大难，市场监管部门用共享思维______了这一难题。","options":["解释","破解","解冻","解开"],"answer":1,"explanation":"「破解」与「难题」搭配得当。「破解难题」为固定搭配；「解开」多与绳结、心结搭配；「解冻」用于资产、关系；「解释」为说明缘由。故选B。","__sub":"选词填空"},{"id":"yy-18437","module":"yanyu","diff":1,"exam":"省考","prompt":"眼下，手握核心技术专利，志愿者们创新的底气。","options":["更强","更足","更硬","更壮"],"answer":1,"explanation":"「更足」与「底气」搭配得当。「底气更足」为惯用搭配；「更硬」多与作风搭配；「更强」多与实力搭配；「更壮」用于体格。故选B。","__sub":"选词填空"},{"id":"yy-18438","module":"yanyu","diff":1,"exam":"教师编","prompt":"这些年，让农产品出村进城，网格员多方合力______销售通道。","options":["扩宽","开辟","开宽","拓宽"],"answer":3,"explanation":"「拓宽」与「通道」搭配得当。「拓宽通道」为固定搭配；「开宽」非规范；「扩宽」多用于道路；「拓宽」亦用于道路但与渠道、通道搭配最常见。故选D。","__sub":"选词填空"},{"id":"yy-18439","module":"yanyu","diff":2,"exam":"事业编","prompt":"连日来，数据孤岛必须连起来，消防员下决心______部门间的壁垒。","options":["击碎","砸破","打碎","打破"],"answer":3,"explanation":"「打破」与「壁垒」搭配得当。「打破壁垒」为固定搭配；「打碎」「砸破」「击碎」均为具体物理动作。故选D。","__sub":"选词填空"},{"id":"yy-18440","module":"yanyu","diff":2,"exam":"国考","prompt":"近年来，众人的事情由众人商量，农技人员把各方______到规划图上。","options":["聚拢","归拢","收拢","凝聚"],"answer":3,"explanation":"「凝聚」与「智慧」搭配得当。「凝聚智慧」为惯用搭配；「聚拢」「收拢」「归拢」均为具体收拢动作，用于抽象智慧不当。故选D。","__sub":"选词填空"},{"id":"yy-18441","module":"yanyu","diff":2,"exam":"国考","prompt":"近年来，面对转型路上的重重难关，基层干部迎难而上，把一个个难关逐一______。","options":["克服","化解","破除","攻克"],"answer":3,"explanation":"「攻克」与「难关」搭配得当。「攻克难关」为固定搭配，强调付出努力战而胜之；「克服」多与困难、缺点搭配；「破除」多与迷信、藩篱搭配；「化解」多与矛盾、风险搭配。故选D。","__sub":"选词填空"},{"id":"yy-18442","module":"yanyu","diff":3,"exam":"教师编","prompt":"近期，把风险挺在前面，农技人员织密织牢安全网。","options":["防守","防备","防范","提防"],"answer":2,"explanation":"「防范」与「风险」搭配得当。「防范风险」为固定搭配；「防备」侧重有所准备；「提防」为口语化小心在意；「防守」多用于比赛、军事。故选C。","__sub":"选词填空"},{"id":"yy-18443","module":"yanyu","diff":2,"exam":"事业编","prompt":"岁末年初，筑起生态安全屏障，手工艺人让青山常在绿水长流。","options":["砌牢","锁牢","拴牢","筑牢"],"answer":3,"explanation":"「筑牢」与「屏障」搭配得当。「筑牢屏障」为惯用搭配；「砌牢」用于砖石；「锁牢」「拴牢」用于器物。故选D。","__sub":"选词填空"},{"id":"yy-18444","module":"yanyu","diff":1,"exam":"医疗编","prompt":"一段时间以来，数据孤岛必须连起来，工程师下决心______部门间的壁垒。","options":["打破","打碎","击碎","砸破"],"answer":0,"explanation":"「打破」与「壁垒」搭配得当。「打破壁垒」为固定搭配；「打碎」「砸破」「击碎」均为具体物理动作。故选A。","__sub":"选词填空"},{"id":"yy-18445","module":"yanyu","diff":2,"exam":"国考","prompt":"近期，景区客流高峰来临，公交司机全员上岗______游览秩序。","options":["护卫","保护","维持","维护"],"answer":3,"explanation":"「维护」与「秩序」搭配得当。「维护秩序」为固定搭配；「维持」多与生活、现状搭配；「保护」多与权益、环境搭配；「护卫」用于人员、目标。故选D。","__sub":"选词填空"},{"id":"yy-18446","module":"yanyu","diff":2,"exam":"国考","prompt":"这些年，手握核心技术专利，手工艺人创新的底气。","options":["更强","更足","更壮","更硬"],"answer":1,"explanation":"「更足」与「底气」搭配得当。「底气更足」为惯用搭配；「更硬」多与作风搭配；「更强」多与实力搭配；「更壮」用于体格。故选B。","__sub":"选词填空"},{"id":"yy-18447","module":"yanyu","diff":3,"exam":"省考","prompt":"开春以来，纪律规矩挺在前面，快递员始终______纪律底线。","options":["严守","遵守","把守","看守"],"answer":0,"explanation":"「严守」与「底线」搭配得当。「严守底线」为固定搭配；「看守」「把守」为具体看护；「遵守」多与规则、法律搭配。故选A。","__sub":"选词填空"},{"id":"yy-18448","module":"yanyu","diff":2,"exam":"国考","prompt":"今年以来，安全底线不可逾越，乡村医生24小时轮班值守。","options":["镇守","把守","坚守","看守"],"answer":2,"explanation":"「坚守」与「底线」搭配得当。「坚守底线」为固定搭配；「看守」「把守」「镇守」均指具体看护动作，多用于人员、关口、城池。故选C。","__sub":"选词填空"},{"id":"yy-18449","module":"yanyu","diff":2,"exam":"国考","prompt":"一段时间以来，营商环境就是生产力，基层干部让企业成长有沃土。","options":["培养","厚植","培育","培植"],"answer":1,"explanation":"「厚植」与「沃土」搭配得当。「厚植沃土」为书面惯用搭配；「培植」多与势力搭配含贬义；「培育」多与人才、市场搭配；「培养」多与人才搭配。故选B。","__sub":"选词填空"},{"id":"yy-18450","module":"yanyu","diff":2,"exam":"国考","prompt":"眼下，停车难是城市治理的老大难，社区规划师用共享思维______了这一难题。","options":["破解","解开","解释","解冻"],"answer":0,"explanation":"「破解」与「难题」搭配得当。「破解难题」为固定搭配；「解开」多与绳结、心结搭配；「解冻」用于资产、关系；「解释」为说明缘由。故选A。","__sub":"选词填空"},{"id":"yy-18451","module":"yanyu","diff":1,"exam":"省考","prompt":"近年来，一二三产融合发展，科研人员推动产业链不断延伸。","options":["延长","延伸","拉长","伸长"],"answer":1,"explanation":"「延伸」与「链条」搭配得当。「链条延伸」为惯用搭配；「伸长」「拉长」「延长」多用于具体长度或时间。故选B。","__sub":"选词填空"},{"id":"yy-18452","module":"yanyu","diff":2,"exam":"国考","prompt":"近年来，市场细胞活跃起来，程序员让经济肌体活力。","options":["塞满","充满","填满","装满"],"answer":1,"explanation":"「充满」与「活力」搭配得当。「充满活力」为固定搭配；「填满」「塞满」「装满」均为具体动作，用于抽象活力不当。故选B。","__sub":"选词填空"},{"id":"yy-18453","module":"yanyu","diff":1,"exam":"国考","prompt":"开春以来，数据孤岛必须连起来，广大建设者下决心______部门间的壁垒。","options":["砸破","打碎","击碎","打破"],"answer":3,"explanation":"「打破」与「壁垒」搭配得当。「打破壁垒」为固定搭配；「打碎」「砸破」「击碎」均为具体物理动作。故选D。","__sub":"选词填空"},{"id":"yy-18454","module":"yanyu","diff":1,"exam":"教师编","prompt":"盛夏时节，订单排到明年，工程师发展的信心。","options":["加倍","倍增","倍加","倍受"],"answer":1,"explanation":"「倍增」与「信心」搭配得当。「信心倍增」为惯用搭配；「加倍」为动词或副词；「倍加」多与珍惜搭配；「倍受」多与关注搭配。故选B。","__sub":"选词填空"},{"id":"yy-18455","module":"yanyu","diff":1,"exam":"国考","prompt":"盛夏时节，靠山吃山靠水吃水，治沙工人因地制宜______资源优势。","options":["施展","发展","发挥","发扬"],"answer":2,"explanation":"「发挥」与「优势」搭配得当。「发挥优势」为固定搭配；「发扬」多与精神、作风搭配；「发展」多与经济、事业搭配。故选C。","__sub":"选词填空"},{"id":"yy-18456","module":"yanyu","diff":2,"exam":"事业编","prompt":"盛夏时节，景区客流高峰来临，执法人员全员上岗______游览秩序。","options":["护卫","维护","保护","维持"],"answer":1,"explanation":"「维护」与「秩序」搭配得当。「维护秩序」为固定搭配；「维持」多与生活、现状搭配；「保护」多与权益、环境搭配；「护卫」用于人员、目标。故选B。","__sub":"选词填空"},{"id":"yy-18457","module":"yanyu","diff":1,"exam":"省考","prompt":"今年以来，每一起案件都关乎群众对法治的信仰，乡村医生用公正裁判______正义。","options":["捍卫","护卫","保卫","防御"],"answer":0,"explanation":"「捍卫」与「公平」搭配得当。「捍卫公平」为书面惯用搭配；「保卫」多与祖国、和平搭配；「护卫」为护送守卫；「防御」用于军事、疫情。故选A。","__sub":"选词填空"},{"id":"yy-18458","module":"yanyu","diff":1,"exam":"事业编","prompt":"开春以来，危难时刻冲得上去，青年学子的行动______了共产党员的担当。","options":["暴露","彰显","显露","显摆"],"answer":1,"explanation":"「彰显」与「担当」搭配得当。「彰显担当」为固定搭配，褒义；「显摆」为口语含贬义；「显露」中性；「暴露」多含贬义。故选B。","__sub":"选词填空"},{"id":"yy-18459","module":"yanyu","diff":3,"exam":"国考","prompt":"今年以来，春潮拍岸千帆竞，环卫工人感受到创新活力。","options":["流出","涌出","淌动","涌动"],"answer":3,"explanation":"「涌动」与「活力」搭配得当。「活力涌动」为惯用表达；「涌出」「流出」为具体动作；「淌动」非规范。故选D。","__sub":"选词填空"},{"id":"yy-18460","module":"yanyu","diff":2,"exam":"国考","prompt":"眼下，订单排到明年，市场监管部门发展的信心。","options":["倍受","加倍","倍增","倍加"],"answer":2,"explanation":"「倍增」与「信心」搭配得当。「信心倍增」为惯用搭配；「加倍」为动词或副词；「倍加」多与珍惜搭配；「倍受」多与关注搭配。故选C。","__sub":"选词填空"},{"id":"yy-18461","module":"yanyu","diff":1,"exam":"省考","prompt":"初秋时节，越是爬坡过坎，越要______必胜信心，税务干部一步一个脚印向前走。","options":["坚强","坚定","坚持不懈","坚决"],"answer":1,"explanation":"「坚定」与「信心」搭配得当。「坚定信心」为固定搭配；「坚决」为副词性形容词多修饰动作；「坚强」多与性格、领导搭配；「坚持不懈」为成语作状语。故选B。","__sub":"选词填空"},{"id":"yy-18462","module":"yanyu","diff":2,"exam":"省考","prompt":"盛夏时节，春潮拍岸千帆竞，广大建设者感受到创新活力。","options":["涌出","涌动","淌动","流出"],"answer":1,"explanation":"「涌动」与「活力」搭配得当。「活力涌动」为惯用表达；「涌出」「流出」为具体动作；「淌动」非规范。故选B。","__sub":"选词填空"},{"id":"yy-18463","module":"yanyu","diff":2,"exam":"省考","prompt":"连日来，安全底线不可逾越，社区工作者24小时轮班值守。","options":["把守","镇守","看守","坚守"],"answer":3,"explanation":"「坚守」与「底线」搭配得当。「坚守底线」为固定搭配；「看守」「把守」「镇守」均指具体看护动作，多用于人员、关口、城池。故选D。","__sub":"选词填空"},{"id":"yy-18464","module":"yanyu","diff":1,"exam":"医疗编","prompt":"近期，老旧小区加装电梯、增设车位，环卫工人尽力______居民多样需求。","options":["充盈","满足","充足","满意"],"answer":1,"explanation":"「满足」与「需求」搭配得当。「满足需求」为固定搭配；「满意」为形容词；「充足」「充盈」为形容词不能带宾语。故选B。","__sub":"选词填空"},{"id":"yy-18465","module":"yanyu","diff":3,"exam":"事业编","prompt":"连日来，被动状态必须改变，网格员用硬措施______了不利局面。","options":["倒转","扭转","反转","回转"],"answer":1,"explanation":"「扭转」与「局面」搭配得当。「扭转局面」为固定搭配；「反转」多与剧情、行情搭配；「倒转」「回转」指方向掉转。故选B。","__sub":"选词填空"},{"id":"yy-18466","module":"yanyu","diff":1,"exam":"国考","prompt":"今年以来，把消费潜力转化为增长实绩，审计人员拿出了实招硬招。","options":["发泄","散发","释放","喷发"],"answer":2,"explanation":"「释放」与「潜力」搭配得当。「释放潜力」为固定搭配；「发泄」含贬义多与情绪搭配；「散发」多与气味、气息搭配；「喷发」用于火山或比喻爆发。故选C。","__sub":"选词填空"},{"id":"yy-18467","module":"yanyu","diff":1,"exam":"国考","prompt":"盛夏时节，初心如磐，使命在肩，手工艺人把承诺落到一件件小事上。","options":["旅行","履行","执行","践行"],"answer":3,"explanation":"「践行」与「使命」搭配得当。「践行使命」为固定搭配；「履行」多与职责、义务、合同搭配；「执行」多与命令、判决、任务搭配；「旅行」为出行义。故选D。","__sub":"选词填空"},{"id":"yy-18468","module":"yanyu","diff":3,"exam":"省考","prompt":"入冬以来，把监督防线扎到最基层，农技人员走村入户听民声。","options":["织密","缝密","织厚","织补"],"answer":0,"explanation":"「织密」与「防线」搭配得当。「织密防线」为惯用搭配；「织厚」「缝密」非规范搭配；「织补」指修补织物。故选A。","__sub":"选词填空"},{"id":"yy-18469","module":"yanyu","diff":2,"exam":"国考","prompt":"连日来，每个孩子都有闪光点，民警善于______学生潜能。","options":["开采","挖出","掘取","挖掘"],"answer":3,"explanation":"「挖掘」与「潜能」搭配得当。「挖掘潜能」为固定搭配；「挖出」「掘取」为具体动作；「开采」用于矿产。故选D。","__sub":"选词填空"},{"id":"yy-18470","module":"yanyu","diff":2,"exam":"国考","prompt":"近期，产业发展的根基越牢，抗风险的能力就越强，护林员深谙此理，先把根基打扎实。","options":["夯实","铺设","垒砌","敲打"],"answer":0,"explanation":"「夯实」与「根基」搭配得当。「夯实根基」为固定搭配；「敲打」为具体动作；「铺设」用于管线、路面；「垒砌」用于砖石墙体。故选A。","__sub":"选词填空"},{"id":"yy-18471","module":"yanyu","diff":2,"exam":"国考","prompt":"一段时间以来，订单排到明年，图书管理员发展的信心。","options":["倍增","加倍","倍加","倍受"],"answer":0,"explanation":"「倍增」与「信心」搭配得当。「信心倍增」为惯用搭配；「加倍」为动词或副词；「倍加」多与珍惜搭配；「倍受」多与关注搭配。故选A。","__sub":"选词填空"},{"id":"yy-18472","module":"yanyu","diff":2,"exam":"省考","prompt":"盛夏时节，市场细胞活跃起来，青年学子让经济肌体活力。","options":["充满","塞满","填满","装满"],"answer":0,"explanation":"「充满」与「活力」搭配得当。「充满活力」为固定搭配；「填满」「塞满」「装满」均为具体动作，用于抽象活力不当。故选A。","__sub":"选词填空"},{"id":"yy-18473","module":"yanyu","diff":1,"exam":"省考","prompt":"开春以来，把风险挺在前面，治沙工人织密织牢安全网。","options":["防范","防备","防守","提防"],"answer":0,"explanation":"「防范」与「风险」搭配得当。「防范风险」为固定搭配；「防备」侧重有所准备；「提防」为口语化小心在意；「防守」多用于比赛、军事。故选A。","__sub":"选词填空"},{"id":"yy-18474","module":"yanyu","diff":3,"exam":"国考","prompt":"一段时间以来，筑起生态安全屏障，茶农让青山常在绿水长流。","options":["锁牢","拴牢","砌牢","筑牢"],"answer":3,"explanation":"「筑牢」与「屏障」搭配得当。「筑牢屏障」为惯用搭配；「砌牢」用于砖石；「锁牢」「拴牢」用于器物。故选D。","__sub":"选词填空"},{"id":"yy-18475","module":"yanyu","diff":1,"exam":"省考","prompt":"开春以来，一次次说到做到，文旅部门用行动______了群众的信任。","options":["获得","换取","博得","赢得"],"answer":3,"explanation":"「赢得」与「信任」搭配得当。「赢得信任」为固定搭配，强调经努力而获得；「获得」中性；「博得」多与同情、喝彩搭配；「换取」含交换义。故选D。","__sub":"选词填空"},{"id":"yy-18476","module":"yanyu","diff":3,"exam":"国考","prompt":"近年来，传统村落保护性开发，铁路养护工既富了口袋，也______了乡愁。","options":["留住","拘留","扣留","截留"],"answer":0,"explanation":"「留住」与「乡愁」搭配得当。「留住乡愁」为惯用表达；「扣留」「拘留」「截留」均为法律或强制扣押义，感情色彩不合。故选A。","__sub":"选词填空"},{"id":"yy-18477","module":"yanyu","diff":2,"exam":"事业编","prompt":"近期，把风险挺在前面，博物馆讲解员织密织牢安全网。","options":["防备","防范","提防","防守"],"answer":1,"explanation":"「防范」与「风险」搭配得当。「防范风险」为固定搭配；「防备」侧重有所准备；「提防」为口语化小心在意；「防守」多用于比赛、军事。故选B。","__sub":"选词填空"},{"id":"yy-18478","module":"yanyu","diff":3,"exam":"医疗编","prompt":"岁末年初，城乡公共服务仍有落差，科研人员以实策逐步______差距。","options":["减小","减少","缩小","缩减"],"answer":2,"explanation":"「缩小」与「差距」搭配得当。「缩小差距」为固定搭配；「减少」多与数量搭配；「缩减」多与开支、编制搭配；「减小」多与阻力、噪音搭配。故选C。","__sub":"选词填空"},{"id":"yy-18479","module":"yanyu","diff":2,"exam":"国考","prompt":"这些年，夜市灯火点亮街巷，护林员为城市______了烟火活力。","options":["增补","增加","追加","增添"],"answer":3,"explanation":"「增添」与「活力」搭配得当。「增添活力」为惯用搭配；「增加」多与数量搭配；「追加」多与投资搭配；「增补」多与人员、内容搭配。故选D。","__sub":"选词填空"},{"id":"yy-18480","module":"yanyu","diff":1,"exam":"国考","prompt":"岁末年初，汛期将至，工程师对辖区地质灾害隐患逐点______。","options":["检察","排查","检查","普查"],"answer":1,"explanation":"「排查」与「隐患」搭配得当。「排查隐患」为固定搭配，强调逐一清查；「检查」为一般查看；「检察」为法律监督专用；「普查」为全面调查登记。故选B。","__sub":"选词填空"},{"id":"yy-18481","module":"yanyu","diff":3,"exam":"省考","prompt":"入冬以来，在广袤乡野间，青年学子用汗水______出乡村振兴的崭新篇章。","options":["抄写","书写","描红","誊写"],"answer":1,"explanation":"「书写」与「篇章」搭配得当。「书写篇章」为惯用搭配；「抄写」「誊写」「描红」均为照原样复写的具体动作，缺乏开创义。故选B。","__sub":"选词填空"},{"id":"yy-18482","module":"yanyu","diff":3,"exam":"国考","prompt":"盛夏时节，把资源优势变成产业优势，治沙工人下大气力______区域品牌。","options":["打造","拍打","锻打","打制"],"answer":0,"explanation":"「打造」与「品牌」搭配得当。「打造品牌」为固定搭配；「打制」「锻打」用于金属器物；「拍打」为具体动作。故选A。","__sub":"选词填空"},{"id":"yy-18483","module":"yanyu","diff":1,"exam":"教师编","prompt":"开春以来，老工业基地涅槃重生，程序员加快新旧动能步伐。","options":["改换","变换","转变","转换"],"answer":3,"explanation":"「转换」与「动能」搭配得当。「动能转换」为固定搭配；「转变」多与观念、方式搭配；「改换」「变换」多与门庭、姿势搭配。故选D。","__sub":"选词填空"},{"id":"yy-18484","module":"yanyu","diff":3,"exam":"国考","prompt":"入冬以来，老旧小区加装电梯、增设车位，农技人员尽力______居民多样需求。","options":["充盈","满意","满足","充足"],"answer":2,"explanation":"「满足」与「需求」搭配得当。「满足需求」为固定搭配；「满意」为形容词；「充足」「充盈」为形容词不能带宾语。故选C。","__sub":"选词填空"},{"id":"yy-18485","module":"yanyu","diff":1,"exam":"事业编","prompt":"连日来，发展为了人民，护林员把一件件民生实事办到群众心坎上，持续______福祉。","options":["增加","增进","增添","增殖"],"answer":1,"explanation":"「增进」与「民生」搭配得当。「增进福祉」为固定搭配，题干以民生统称；「增加」多与数量搭配；「增添」多与色彩、麻烦搭配；「增殖」为生物学用语。故选B。","__sub":"选词填空"},{"id":"yy-18486","module":"yanyu","diff":2,"exam":"省考","prompt":"连日来，民生领域还有欠账，市场监管部门列出清单逐项______短板。","options":["贴补","补齐","补丁","修补"],"answer":1,"explanation":"「补齐」与「短板」搭配得当。「补齐短板」为固定搭配；「补丁」为名词；「修补」多用于衣物器物；「贴补」多与费用搭配。故选B。","__sub":"选词填空"},{"id":"yy-18487","module":"yanyu","diff":2,"exam":"省考","prompt":"盛夏时节，数据孤岛必须连起来，乡村医生下决心______部门间的壁垒。","options":["击碎","打碎","砸破","打破"],"answer":3,"explanation":"「打破」与「壁垒」搭配得当。「打破壁垒」为固定搭配；「打碎」「砸破」「击碎」均为具体物理动作。故选D。","__sub":"选词填空"},{"id":"yy-18488","module":"yanyu","diff":1,"exam":"事业编","prompt":"入冬以来，改革到了深水区，文旅部门以钉钉子精神______工作局面。","options":["打开","揭开","掀开","翻开"],"answer":0,"explanation":"「打开」与「局面」搭配得当。「打开局面」为固定搭配；「翻开」用于书页；「揭开」多与谜底、序幕搭配；「掀开」用于盖子、帘子。故选A。","__sub":"选词填空"},{"id":"yy-18489","module":"yanyu","diff":1,"exam":"事业编","prompt":"近期，面对转型路上的重重难关，青年学子迎难而上，把一个个难关逐一______。","options":["化解","攻克","克服","破除"],"answer":1,"explanation":"「攻克」与「难关」搭配得当。「攻克难关」为固定搭配，强调付出努力战而胜之；「克服」多与困难、缺点搭配；「破除」多与迷信、藩篱搭配；「化解」多与矛盾、风险搭配。故选B。","__sub":"选词填空"},{"id":"yy-18490","module":"yanyu","diff":3,"exam":"省考","prompt":"初秋时节，脱贫不是终点，网格员多措并举______脱贫成果。","options":["凝固","加固","巩固","稳固"],"answer":2,"explanation":"「巩固」与「成果」搭配得当。「巩固成果」为固定搭配；「稳固」为形容词或使稳固；「加固」用于建筑堤坝；「凝固」为物理变化。故选C。","__sub":"选词填空"},{"id":"yy-18491","module":"yanyu","diff":3,"exam":"国考","prompt":"眼下，传统村落保护性开发，快递员既富了口袋，也______了乡愁。","options":["截留","拘留","留住","扣留"],"answer":2,"explanation":"「留住」与「乡愁」搭配得当。「留住乡愁」为惯用表达；「扣留」「拘留」「截留」均为法律或强制扣押义，感情色彩不合。故选C。","__sub":"选词填空"},{"id":"yy-18492","module":"yanyu","diff":2,"exam":"国考","prompt":"这些年，一次次说到做到，社区工作者用行动______了群众的信任。","options":["赢得","获得","换取","博得"],"answer":0,"explanation":"「赢得」与「信任」搭配得当。「赢得信任」为固定搭配，强调经努力而获得；「获得」中性；「博得」多与同情、喝彩搭配；「换取」含交换义。故选A。","__sub":"选词填空"},{"id":"yy-18493","module":"yanyu","diff":2,"exam":"医疗编","prompt":"开春以来，初心如磐，使命在肩，法官把承诺落到一件件小事上。","options":["执行","旅行","践行","履行"],"answer":2,"explanation":"「践行」与「使命」搭配得当。「践行使命」为固定搭配；「履行」多与职责、义务、合同搭配；「执行」多与命令、判决、任务搭配；「旅行」为出行义。故选C。","__sub":"选词填空"},{"id":"yy-18494","module":"yanyu","diff":1,"exam":"省考","prompt":"这些年，纪律规矩挺在前面，设计师始终______纪律底线。","options":["严守","看守","遵守","把守"],"answer":0,"explanation":"「严守」与「底线」搭配得当。「严守底线」为固定搭配；「看守」「把守」为具体看护；「遵守」多与规则、法律搭配。故选A。","__sub":"选词填空"},{"id":"yy-18495","module":"yanyu","diff":1,"exam":"省考","prompt":"入冬以来，把风险挺在前面，农技人员织密织牢安全网。","options":["防备","提防","防范","防守"],"answer":2,"explanation":"「防范」与「风险」搭配得当。「防范风险」为固定搭配；「防备」侧重有所准备；「提防」为口语化小心在意；「防守」多用于比赛、军事。故选C。","__sub":"选词填空"},{"id":"yy-18496","module":"yanyu","diff":1,"exam":"国考","prompt":"眼下，一网通办让数据多跑路，基层干部以流程再造______政务效能。","options":["抬高","提高","提升","拔高"],"answer":2,"explanation":"「提升」与「效能」搭配得当。「提升效能」为固定搭配；「提高」多与水平、价格搭配；「拔高」含刻意抬升义；「抬高」多与价格、身价搭配。故选C。","__sub":"选词填空"},{"id":"yy-18497","module":"yanyu","diff":2,"exam":"国考","prompt":"盛夏时节，古城修缮不搞大拆大建，程序员让千年文脉在街巷间静静流淌。","options":["接通","延续","连接","续接"],"answer":1,"explanation":"「延续」与「文脉」搭配得当。「延续文脉」为惯用搭配；「连接」指具体相连；「续接」多与线路搭配；「接通」用于电话、电路。故选B。","__sub":"选词填空"},{"id":"yy-18498","module":"yanyu","diff":2,"exam":"医疗编","prompt":"一段时间以来，小哨兵大作用，网格员让基层网格______更大作用。","options":["发扬","表现","发挥","施展"],"answer":2,"explanation":"「发挥」与「作用」搭配得当。「发挥作用」为固定搭配；「发扬」多与传统搭配；「施展」多与才华、拳脚搭配。故选C。","__sub":"选词填空"},{"id":"yy-18499","module":"yanyu","diff":2,"exam":"国考","prompt":"盛夏时节，越是爬坡过坎，越要______必胜信心，公交司机一步一个脚印向前走。","options":["坚持不懈","坚决","坚定","坚强"],"answer":2,"explanation":"「坚定」与「信心」搭配得当。「坚定信心」为固定搭配；「坚决」为副词性形容词多修饰动作；「坚强」多与性格、领导搭配；「坚持不懈」为成语作状语。故选C。","__sub":"选词填空"},{"id":"yy-18500","module":"yanyu","diff":3,"exam":"教师编","prompt":"开春以来，初心如磐，使命在肩，社区规划师把承诺落到一件件小事上。","options":["践行","旅行","执行","履行"],"answer":0,"explanation":"「践行」与「使命」搭配得当。「践行使命」为固定搭配；「履行」多与职责、义务、合同搭配；「执行」多与命令、判决、任务搭配；「旅行」为出行义。故选A。","__sub":"选词填空"},{"id":"yy-18501","module":"yanyu","diff":1,"exam":"国考","prompt":"一段时间以来，一年一度的民生大考结束，渔民向群众______了温暖的答卷。","options":["交出","上缴","递交","呈报"],"answer":0,"explanation":"「交出」与「答卷」搭配得当。「交出答卷」为惯用搭配；「递交」多与申请、辞呈搭配；「呈报」多与公文搭配且含上下级意味；「上缴」多与款项、物品搭配。故选A。","__sub":"选词填空"},{"id":"yy-18502","module":"yanyu","diff":2,"exam":"事业编","prompt":"入冬以来，订单排到明年，图书管理员发展的信心。","options":["倍受","倍加","倍增","加倍"],"answer":2,"explanation":"「倍增」与「信心」搭配得当。「信心倍增」为惯用搭配；「加倍」为动词或副词；「倍加」多与珍惜搭配；「倍受」多与关注搭配。故选C。","__sub":"选词填空"},{"id":"yy-18503","module":"yanyu","diff":2,"exam":"事业编","prompt":"入冬以来，一年一度的民生大考结束，执法人员向群众______了温暖的答卷。","options":["递交","交出","呈报","上缴"],"answer":1,"explanation":"「交出」与「答卷」搭配得当。「交出答卷」为惯用搭配；「递交」多与申请、辞呈搭配；「呈报」多与公文搭配且含上下级意味；「上缴」多与款项、物品搭配。故选B。","__sub":"选词填空"},{"id":"yy-18504","module":"yanyu","diff":2,"exam":"省考","prompt":"开春以来，乡情是最深的牵挂，青年学子以商会为平台______情感纽带。","options":["织牢","系牢","捆牢","绑牢"],"answer":0,"explanation":"「织牢」与「纽带」搭配得当。「织牢纽带」为惯用比喻搭配；「系牢」「捆牢」「绑牢」均为具体系绑动作。故选A。","__sub":"选词填空"},{"id":"yy-18505","module":"yanyu","diff":2,"exam":"省考","prompt":"开春以来，把资源优势变成产业优势，治沙工人下大气力______区域品牌。","options":["锻打","打制","打造","拍打"],"answer":2,"explanation":"「打造」与「品牌」搭配得当。「打造品牌」为固定搭配；「打制」「锻打」用于金属器物；「拍打」为具体动作。故选C。","__sub":"选词填空"},{"id":"yy-18506","module":"yanyu","diff":2,"exam":"国考","prompt":"今年以来，几十年如一日，非遗传承人在平凡岗位上______着为民初心。","options":["守卫","把守","保守","坚守"],"answer":3,"explanation":"「坚守」与「初心」搭配得当。「坚守初心」为固定搭配；「保守」多与秘密搭配；「守卫」用于边疆、家园；「把守」用于关口。故选D。","__sub":"选词填空"},{"id":"yy-18507","module":"yanyu","diff":2,"exam":"国考","prompt":"初秋时节，一网通办让数据多跑路，铁路养护工以流程再造______政务效能。","options":["提升","拔高","抬高","提高"],"answer":0,"explanation":"「提升」与「效能」搭配得当。「提升效能」为固定搭配；「提高」多与水平、价格搭配；「拔高」含刻意抬升义；「抬高」多与价格、身价搭配。故选A。","__sub":"选词填空"},{"id":"yy-18508","module":"yanyu","diff":2,"exam":"国考","prompt":"近期，誓师大会上，手工艺人精神斗志，誓言响彻训练场。","options":["昂扬","高扬","高涨","高昂"],"answer":0,"explanation":"「昂扬」与「斗志」搭配得当。「斗志昂扬」为固定成语；「高昂」多与情绪、价格搭配；「高涨」多与热情搭配；「高扬」多与旗帜搭配。故选A。","__sub":"选词填空"},{"id":"yy-18509","module":"yanyu","diff":1,"exam":"教师编","prompt":"眼下，急难险重任务面前，驻村干部主动______最重的责任。","options":["背起","扛起","抬起","挑起"],"answer":1,"explanation":"「扛起」与「责任」搭配得当。「扛起责任」为惯用搭配；「背起」多与行囊、伤员搭配；「挑起」多与担子、重担搭配；「抬起」为具体动作。故选B。","__sub":"选词填空"},{"id":"yy-18510","module":"yanyu","diff":2,"exam":"省考","prompt":"入冬以来，内生动力从哪里来？民警把功夫下在创新上。","options":["加强","增添","增大","增强"],"answer":3,"explanation":"「增强」与「动力」搭配得当。「增强动力」为固定搭配；「加强」多与领导、管理搭配；「增大」多与幅度、剂量搭配。故选D。","__sub":"选词填空"},{"id":"yy-18511","module":"yanyu","diff":2,"exam":"国考","prompt":"眼下，卡脖子技术亟待攻坚，市场监管部门集中力量______一个个瓶颈。","options":["撞破","突破","冲破","捅破"],"answer":1,"explanation":"「突破」与「瓶颈」搭配得当。「突破瓶颈」为固定搭配；「冲破」多与封锁、束缚搭配；「撞破」「捅破」为具体动作或与窗户纸等搭配。故选B。","__sub":"选词填空"},{"id":"yy-18512","module":"yanyu","diff":2,"exam":"国考","prompt":"盛夏时节，订单排到明年，护林员发展的信心。","options":["加倍","倍加","倍增","倍受"],"answer":2,"explanation":"「倍增」与「信心」搭配得当。「信心倍增」为惯用搭配；「加倍」为动词或副词；「倍加」多与珍惜搭配；「倍受」多与关注搭配。故选C。","__sub":"选词填空"},{"id":"yy-18513","module":"yanyu","diff":1,"exam":"事业编","prompt":"入冬以来，从受理到反馈全流程留痕，农技人员以数字化手段______管理闭环。","options":["搭圈","构画","构建","圈画"],"answer":2,"explanation":"「构建」与「闭环」搭配得当。「构建闭环」为惯用搭配；其余选项均非规范搭配。故选C。","__sub":"选词填空"},{"id":"yy-18514","module":"yanyu","diff":3,"exam":"事业编","prompt":"入冬以来，二十年只做一件事，消防员在细分领域里做到极致。","options":["深钻","深掘","深挖","深耕"],"answer":3,"explanation":"「深耕」与「领域」搭配得当。「深耕领域」为惯用比喻搭配；「深挖」多与线索搭配；「深钻」「深掘」非规范。故选D。","__sub":"选词填空"},{"id":"yy-18515","module":"yanyu","diff":1,"exam":"国考","prompt":"这些年，内生动力从哪里来？基层干部把功夫下在创新上。","options":["增大","加强","增强","增添"],"answer":2,"explanation":"「增强」与「动力」搭配得当。「增强动力」为固定搭配；「加强」多与领导、管理搭配；「增大」多与幅度、剂量搭配。故选C。","__sub":"选词填空"},{"id":"yy-18516","module":"yanyu","diff":1,"exam":"事业编","prompt":"连日来，老工业基地涅槃重生，设计师加快新旧动能步伐。","options":["改换","转变","变换","转换"],"answer":3,"explanation":"「转换」与「动能」搭配得当。「动能转换」为固定搭配；「转变」多与观念、方式搭配；「改换」「变换」多与门庭、姿势搭配。故选D。","__sub":"选词填空"},{"id":"yy-18517","module":"yanyu","diff":1,"exam":"省考","prompt":"今年以来，几十年如一日，乡村医生在平凡岗位上______着为民初心。","options":["保守","守卫","把守","坚守"],"answer":3,"explanation":"「坚守」与「初心」搭配得当。「坚守初心」为固定搭配；「保守」多与秘密搭配；「守卫」用于边疆、家园；「把守」用于关口。故选D。","__sub":"选词填空"},{"id":"yy-18518","module":"yanyu","diff":2,"exam":"事业编","prompt":"眼下，面对转型路上的重重难关，博物馆讲解员迎难而上，把一个个难关逐一______。","options":["克服","破除","化解","攻克"],"answer":3,"explanation":"「攻克」与「难关」搭配得当。「攻克难关」为固定搭配，强调付出努力战而胜之；「克服」多与困难、缺点搭配；「破除」多与迷信、藩篱搭配；「化解」多与矛盾、风险搭配。故选D。","__sub":"选词填空"},{"id":"yy-18519","module":"yanyu","diff":1,"exam":"教师编","prompt":"初秋时节，卡脖子技术亟待攻坚，科研人员集中力量______一个个瓶颈。","options":["撞破","冲破","捅破","突破"],"answer":3,"explanation":"「突破」与「瓶颈」搭配得当。「突破瓶颈」为固定搭配；「冲破」多与封锁、束缚搭配；「撞破」「捅破」为具体动作或与窗户纸等搭配。故选D。","__sub":"选词填空"},{"id":"yy-18520","module":"yanyu","diff":2,"exam":"省考","prompt":"一段时间以来，红色资源是最生动的教材，基层干部让红色血脉代代相传。","options":["赓续","延续","继续","接续"],"answer":0,"explanation":"「赓续」与「血脉」搭配得当。「赓续血脉」为书面惯用搭配；「继续」为一般动词；「接续」多与手续、产业搭配；「延续」多与生命、文脉搭配。故选A。","__sub":"选词填空"},{"id":"yy-18521","module":"yanyu","diff":1,"exam":"国考","prompt":"今年以来，一次次说到做到，法官用行动______了群众的信任。","options":["换取","赢得","获得","博得"],"answer":1,"explanation":"「赢得」与「信任」搭配得当。「赢得信任」为固定搭配，强调经努力而获得；「获得」中性；「博得」多与同情、喝彩搭配；「换取」含交换义。故选B。","__sub":"选词填空"},{"id":"yy-18522","module":"yanyu","diff":1,"exam":"国考","prompt":"近期，一年一度的民生大考结束，志愿者们向群众______了温暖的答卷。","options":["交出","上缴","呈报","递交"],"answer":0,"explanation":"「交出」与「答卷」搭配得当。「交出答卷」为惯用搭配；「递交」多与申请、辞呈搭配；「呈报」多与公文搭配且含上下级意味；「上缴」多与款项、物品搭配。故选A。","__sub":"选词填空"},{"id":"yy-18523","module":"yanyu","diff":1,"exam":"省考","prompt":"连日来，汛期将至，调解员对辖区地质灾害隐患逐点______。","options":["排查","普查","检查","检察"],"answer":0,"explanation":"「排查」与「隐患」搭配得当。「排查隐患」为固定搭配，强调逐一清查；「检查」为一般查看；「检察」为法律监督专用；「普查」为全面调查登记。故选A。","__sub":"选词填空"},{"id":"yy-18524","module":"yanyu","diff":3,"exam":"省考","prompt":"盛夏时节，让要素流动更顺畅，就要______体制机制的藩篱。","options":["拆除","铲平","捣毁","破除"],"answer":3,"explanation":"「破除」与「藩篱」搭配得当。「破除藩篱」为固定搭配；「拆除」用于建筑；「铲平」用于场地；「捣毁」用于巢穴、据点且含暴力义。故选D。","__sub":"选词填空"},{"id":"yy-18525","module":"yanyu","diff":2,"exam":"国考","prompt":"盛夏时节，每一起案件都关乎群众对法治的信仰，铁路养护工用公正裁判______正义。","options":["防御","保卫","护卫","捍卫"],"answer":3,"explanation":"「捍卫」与「公平」搭配得当。「捍卫公平」为书面惯用搭配；「保卫」多与祖国、和平搭配；「护卫」为护送守卫；「防御」用于军事、疫情。故选D。","__sub":"选词填空"},{"id":"yy-18526","module":"yanyu","diff":2,"exam":"省考","prompt":"这些年，被动状态必须改变，电力工人用硬措施______了不利局面。","options":["倒转","反转","回转","扭转"],"answer":3,"explanation":"「扭转」与「局面」搭配得当。「扭转局面」为固定搭配；「反转」多与剧情、行情搭配；「倒转」「回转」指方向掉转。故选D。","__sub":"选词填空"},{"id":"yy-18527","module":"yanyu","diff":2,"exam":"省考","prompt":"一段时间以来，老艺人收徒授艺，让千年技艺薪火。","options":["递送","传递","互传","相传"],"answer":3,"explanation":"「相传」与「薪火」搭配得当。「薪火相传」为固定成语；「互传」「递送」「传递」均无此搭配且丢失比喻义。故选D。","__sub":"选词填空"},{"id":"yy-18528","module":"yanyu","diff":3,"exam":"省考","prompt":"眼下，一二三产融合发展，文旅部门推动产业链不断延伸。","options":["拉长","延伸","伸长","延长"],"answer":1,"explanation":"「延伸」与「链条」搭配得当。「链条延伸」为惯用搭配；「伸长」「拉长」「延长」多用于具体长度或时间。故选B。","__sub":"选词填空"},{"id":"yy-18529","module":"yanyu","diff":1,"exam":"国考","prompt":"这些年，跳出一时一地看发展，农技人员着力______开放共赢的新格局。","options":["架造","构建","构作","搭造"],"answer":1,"explanation":"「构建」与「格局」搭配得当。「构建格局」为惯用搭配；「构作」「搭造」「架造」均非规范书面搭配。故选B。","__sub":"选词填空"},{"id":"yy-18530","module":"yanyu","diff":1,"exam":"省考","prompt":"入冬以来，急难险重任务面前，志愿者们主动______最重的责任。","options":["挑起","背起","抬起","扛起"],"answer":3,"explanation":"「扛起」与「责任」搭配得当。「扛起责任」为惯用搭配；「背起」多与行囊、伤员搭配；「挑起」多与担子、重担搭配；「抬起」为具体动作。故选D。","__sub":"选词填空"},{"id":"yy-18531","module":"yanyu","diff":2,"exam":"事业编","prompt":"盛夏时节，一二三产融合发展，博物馆讲解员推动产业链不断延伸。","options":["延长","伸长","延伸","拉长"],"answer":2,"explanation":"「延伸」与「链条」搭配得当。「链条延伸」为惯用搭配；「伸长」「拉长」「延长」多用于具体长度或时间。故选C。","__sub":"选词填空"},{"id":"yy-18532","module":"yanyu","diff":2,"exam":"省考","prompt":"一段时间以来，城乡公共服务仍有落差，驻村干部以实策逐步______差距。","options":["减小","减少","缩减","缩小"],"answer":3,"explanation":"「缩小」与「差距」搭配得当。「缩小差距」为固定搭配；「减少」多与数量搭配；「缩减」多与开支、编制搭配；「减小」多与阻力、噪音搭配。故选D。","__sub":"选词填空"},{"id":"yy-18533","module":"yanyu","diff":2,"exam":"省考","prompt":"今年以来，每个孩子都有闪光点，博物馆讲解员善于______学生潜能。","options":["挖掘","掘取","开采","挖出"],"answer":0,"explanation":"「挖掘」与「潜能」搭配得当。「挖掘潜能」为固定搭配；「挖出」「掘取」为具体动作；「开采」用于矿产。故选A。","__sub":"选词填空"},{"id":"yy-18534","module":"yanyu","diff":1,"exam":"事业编","prompt":"连日来，把资源优势变成产业优势，社区规划师下大气力______区域品牌。","options":["拍打","打制","锻打","打造"],"answer":3,"explanation":"「打造」与「品牌」搭配得当。「打造品牌」为固定搭配；「打制」「锻打」用于金属器物；「拍打」为具体动作。故选D。","__sub":"选词填空"},{"id":"yy-18535","module":"yanyu","diff":2,"exam":"教师编","prompt":"一段时间以来，靠山吃山靠水吃水，驻村干部因地制宜______资源优势。","options":["发扬","发挥","施展","发展"],"answer":1,"explanation":"「发挥」与「优势」搭配得当。「发挥优势」为固定搭配；「发扬」多与精神、作风搭配；「发展」多与经济、事业搭配。故选B。","__sub":"选词填空"},{"id":"yy-18536","module":"yanyu","diff":3,"exam":"国考","prompt":"开春以来，让新业态释放新动能，乡村医生在制度创新上先行先试。","options":["发动","点燃","激发","引爆"],"answer":2,"explanation":"「激发」与「动能」搭配得当。「激发动能」为惯用搭配；「发动」多与机器、群众搭配；「点燃」多与激情搭配；「引爆」多与话题、舆论搭配且含突然义。故选C。","__sub":"选词填空"},{"id":"yy-18537","module":"yanyu","diff":2,"exam":"医疗编","prompt":"眼下，二十年只做一件事，民警在细分领域里做到极致。","options":["深钻","深耕","深挖","深掘"],"answer":1,"explanation":"「深耕」与「领域」搭配得当。「深耕领域」为惯用比喻搭配；「深挖」多与线索搭配；「深钻」「深掘」非规范。故选B。","__sub":"选词填空"},{"id":"yy-18538","module":"yanyu","diff":1,"exam":"教师编","prompt":"开春以来，在广袤乡野间，驻村干部用汗水______出乡村振兴的崭新篇章。","options":["描红","书写","誊写","抄写"],"answer":1,"explanation":"「书写」与「篇章」搭配得当。「书写篇章」为惯用搭配；「抄写」「誊写」「描红」均为照原样复写的具体动作，缺乏开创义。故选B。","__sub":"选词填空"},{"id":"yy-18539","module":"yanyu","diff":3,"exam":"省考","prompt":"眼下，每一起案件都关乎群众对法治的信仰，法官用公正裁判______正义。","options":["防御","捍卫","保卫","护卫"],"answer":1,"explanation":"「捍卫」与「公平」搭配得当。「捍卫公平」为书面惯用搭配；「保卫」多与祖国、和平搭配；「护卫」为护送守卫；「防御」用于军事、疫情。故选B。","__sub":"选词填空"},{"id":"yy-18540","module":"yanyu","diff":2,"exam":"国考","prompt":"近期，把消费潜力转化为增长实绩，果农拿出了实招硬招。","options":["释放","散发","发泄","喷发"],"answer":0,"explanation":"「释放」与「潜力」搭配得当。「释放潜力」为固定搭配；「发泄」含贬义多与情绪搭配；「散发」多与气味、气息搭配；「喷发」用于火山或比喻爆发。故选A。","__sub":"选词填空"},{"id":"yy-18541","module":"yanyu","diff":2,"exam":"医疗编","prompt":"一段时间以来，邻里纠纷无小事，执法人员用真心______一件件矛盾。","options":["消融","瓦解","化解","解开"],"answer":2,"explanation":"「化解」与「矛盾」搭配得当。「化解矛盾」为固定搭配；「解开」多与疙瘩、谜团搭配；「消融」用于冰雪；「瓦解」多用于组织、士气。故选C。","__sub":"选词填空"},{"id":"yy-18542","module":"yanyu","diff":1,"exam":"教师编","prompt":"开春以来，把监督防线扎到最基层，手工艺人走村入户听民声。","options":["织密","缝密","织补","织厚"],"answer":0,"explanation":"「织密」与「防线」搭配得当。「织密防线」为惯用搭配；「织厚」「缝密」非规范搭配；「织补」指修补织物。故选A。","__sub":"选词填空"},{"id":"yy-18543","module":"yanyu","diff":3,"exam":"事业编","prompt":"入冬以来，每一起案件都关乎群众对法治的信仰，医护人员用公正裁判______正义。","options":["保卫","捍卫","防御","护卫"],"answer":1,"explanation":"「捍卫」与「公平」搭配得当。「捍卫公平」为书面惯用搭配；「保卫」多与祖国、和平搭配；「护卫」为护送守卫；「防御」用于军事、疫情。故选B。","__sub":"选词填空"},{"id":"yy-18544","module":"yanyu","diff":1,"exam":"事业编","prompt":"岁末年初，把家国情怀融入课堂，图书管理员用身边故事打动学生。","options":["培土","施肥","厚植","浇灌"],"answer":2,"explanation":"「厚植」与「情怀」搭配得当。「厚植情怀」为书面惯用搭配；「加深」多与印象、了解搭配。故选C。","__sub":"选词填空"},{"id":"yy-18545","module":"yanyu","diff":1,"exam":"省考","prompt":"盛夏时节，政府、市场、社会同向发力，工程师让各方______成强大合力。","options":["汇集","汇合","汇聚","聚合"],"answer":2,"explanation":"「汇聚」与「合力」搭配得当。「汇聚合力」为惯用搭配；「汇合」指水流等聚集；「汇集」指集中收集；「聚合」为化学或物理过程。故选C。","__sub":"选词填空"},{"id":"yy-18546","module":"yanyu","diff":3,"exam":"国考","prompt":"入冬以来，一网通办让数据多跑路，茶农以流程再造______政务效能。","options":["拔高","提高","提升","抬高"],"answer":2,"explanation":"「提升」与「效能」搭配得当。「提升效能」为固定搭配；「提高」多与水平、价格搭配；「拔高」含刻意抬升义；「抬高」多与价格、身价搭配。故选C。","__sub":"选词填空"},{"id":"yy-18547","module":"yanyu","diff":3,"exam":"医疗编","prompt":"近年来，面对转型路上的重重难关，农技人员迎难而上，把一个个难关逐一______。","options":["克服","化解","破除","攻克"],"answer":3,"explanation":"「攻克」与「难关」搭配得当。「攻克难关」为固定搭配，强调付出努力战而胜之；「克服」多与困难、缺点搭配；「破除」多与迷信、藩篱搭配；「化解」多与矛盾、风险搭配。故选D。","__sub":"选词填空"},{"id":"yy-18548","module":"yanyu","diff":2,"exam":"国考","prompt":"连日来，在广袤乡野间，电力工人用汗水______出乡村振兴的崭新篇章。","options":["描红","抄写","书写","誊写"],"answer":2,"explanation":"「书写」与「篇章」搭配得当。「书写篇章」为惯用搭配；「抄写」「誊写」「描红」均为照原样复写的具体动作，缺乏开创义。故选C。","__sub":"选词填空"},{"id":"yy-18549","module":"yanyu","diff":2,"exam":"事业编","prompt":"这些年，春潮拍岸千帆竞，消防员感受到创新活力。","options":["涌动","流出","淌动","涌出"],"answer":0,"explanation":"「涌动」与「活力」搭配得当。「活力涌动」为惯用表达；「涌出」「流出」为具体动作；「淌动」非规范。故选A。","__sub":"选词填空"},{"id":"yy-18550","module":"yanyu","diff":2,"exam":"国考","prompt":"入冬以来，初心如磐，使命在肩，社区工作者把承诺落到一件件小事上。","options":["旅行","践行","履行","执行"],"answer":1,"explanation":"「践行」与「使命」搭配得当。「践行使命」为固定搭配；「履行」多与职责、义务、合同搭配；「执行」多与命令、判决、任务搭配；「旅行」为出行义。故选B。","__sub":"选词填空"},{"id":"yy-18551","module":"yanyu","diff":2,"exam":"国考","prompt":"近期，誓师大会上，审计人员精神斗志，誓言响彻训练场。","options":["高涨","高昂","高扬","昂扬"],"answer":3,"explanation":"「昂扬」与「斗志」搭配得当。「斗志昂扬」为固定成语；「高昂」多与情绪、价格搭配；「高涨」多与热情搭配；「高扬」多与旗帜搭配。故选D。","__sub":"选词填空"},{"id":"yy-18552","module":"yanyu","diff":2,"exam":"国考","prompt":"近年来，被动状态必须改变，审计人员用硬措施______了不利局面。","options":["扭转","回转","倒转","反转"],"answer":0,"explanation":"「扭转」与「局面」搭配得当。「扭转局面」为固定搭配；「反转」多与剧情、行情搭配；「倒转」「回转」指方向掉转。故选A。","__sub":"选词填空"},{"id":"yy-18553","module":"yanyu","diff":2,"exam":"事业编","prompt":"连日来，脱贫不是终点，志愿者们多措并举______脱贫成果。","options":["巩固","稳固","加固","凝固"],"answer":0,"explanation":"「巩固」与「成果」搭配得当。「巩固成果」为固定搭配；「稳固」为形容词或使稳固；「加固」用于建筑堤坝；「凝固」为物理变化。故选A。","__sub":"选词填空"},{"id":"yy-18554","module":"yanyu","diff":3,"exam":"国考","prompt":"入冬以来，卡脖子技术亟待攻坚，基层干部集中力量______一个个瓶颈。","options":["突破","冲破","捅破","撞破"],"answer":0,"explanation":"「突破」与「瓶颈」搭配得当。「突破瓶颈」为固定搭配；「冲破」多与封锁、束缚搭配；「撞破」「捅破」为具体动作或与窗户纸等搭配。故选A。","__sub":"选词填空"},{"id":"yy-18555","module":"yanyu","diff":2,"exam":"国考","prompt":"岁末年初，急难险重任务面前，茶农主动______最重的责任。","options":["扛起","挑起","背起","抬起"],"answer":0,"explanation":"「扛起」与「责任」搭配得当。「扛起责任」为惯用搭配；「背起」多与行囊、伤员搭配；「挑起」多与担子、重担搭配；「抬起」为具体动作。故选A。","__sub":"选词填空"},{"id":"yy-18556","module":"yanyu","diff":1,"exam":"国考","prompt":"盛夏时节，减税降费政策落地，志愿者们让企业真切感受到红利。","options":["发放","发射","释放","散发"],"answer":2,"explanation":"「释放」与「红利」搭配得当。「释放红利」为惯用搭配；「发放」多与物资、贷款搭配；「散发」多与气味搭配；「发射」用于子弹、卫星。故选C。","__sub":"选词填空"},{"id":"yy-18557","module":"yanyu","diff":3,"exam":"教师编","prompt":"岁末年初，市场细胞活跃起来，农技人员让经济肌体活力。","options":["填满","装满","塞满","充满"],"answer":3,"explanation":"「充满」与「活力」搭配得当。「充满活力」为固定搭配；「填满」「塞满」「装满」均为具体动作，用于抽象活力不当。故选D。","__sub":"选词填空"},{"id":"yy-18558","module":"yanyu","diff":2,"exam":"国考","prompt":"近年来，让要素流动更顺畅，就要______体制机制的藩篱。","options":["破除","拆除","捣毁","铲平"],"answer":0,"explanation":"「破除」与「藩篱」搭配得当。「破除藩篱」为固定搭配；「拆除」用于建筑；「铲平」用于场地；「捣毁」用于巢穴、据点且含暴力义。故选A。","__sub":"选词填空"},{"id":"yy-18559","module":"yanyu","diff":1,"exam":"教师编","prompt":"连日来，金杯银杯不如老百姓的口碑，护林员把每件小事都当大事办。","options":["创立","设立","建立","树立"],"answer":3,"explanation":"「树立」与「口碑」搭配得当。「树立口碑」为惯用搭配；「建立」多与制度、关系搭配；「设立」多与机构搭配；「创立」多与学说、品牌搭配。故选D。","__sub":"选词填空"},{"id":"yy-18560","module":"yanyu","diff":1,"exam":"国考","prompt":"开春以来，危难时刻冲得上去，社区规划师的行动______了共产党员的担当。","options":["显露","显摆","彰显","暴露"],"answer":2,"explanation":"「彰显」与「担当」搭配得当。「彰显担当」为固定搭配，褒义；「显摆」为口语含贬义；「显露」中性；「暴露」多含贬义。故选C。","__sub":"选词填空"},{"id":"yy-18561","module":"yanyu","diff":2,"exam":"国考","prompt":"这些年，两岸同胞亲情割不断，执法人员为青年交流______心灵心桥。","options":["垒砌","铺设","架起","修筑"],"answer":2,"explanation":"「架起」与「心桥」搭配得当。「架起心桥」为惯用比喻搭配；「修筑」用于道路工程；「垒砌」用于砖石；「铺设」用于管线轨道。故选C。","__sub":"选词填空"},{"id":"yy-18562","module":"yanyu","diff":2,"exam":"教师编","prompt":"今年以来，两岸同胞亲情割不断，驻村干部为青年交流______心灵心桥。","options":["铺设","架起","修筑","垒砌"],"answer":1,"explanation":"「架起」与「心桥」搭配得当。「架起心桥」为惯用比喻搭配；「修筑」用于道路工程；「垒砌」用于砖石；「铺设」用于管线轨道。故选B。","__sub":"选词填空"},{"id":"yy-18563","module":"yanyu","diff":2,"exam":"国考","prompt":"这些年，放宽准入激发创业热情，公交司机让创造活力。","options":["涌流","涌出","淌出","流出"],"answer":0,"explanation":"「涌流」与「活力」搭配得当。「活力涌流」为惯用表达；「流出」「淌出」「涌出」均用于液体且为具体动作。故选A。","__sub":"选词填空"},{"id":"yy-18564","module":"yanyu","diff":1,"exam":"国考","prompt":"连日来，面对转型路上的重重难关，程序员迎难而上，把一个个难关逐一______。","options":["化解","克服","攻克","破除"],"answer":2,"explanation":"「攻克」与「难关」搭配得当。「攻克难关」为固定搭配，强调付出努力战而胜之；「克服」多与困难、缺点搭配；「破除」多与迷信、藩篱搭配；「化解」多与矛盾、风险搭配。故选C。","__sub":"选词填空"},{"id":"yy-18565","module":"yanyu","diff":2,"exam":"省考","prompt":"近期，发展为了人民，社区规划师把一件件民生实事办到群众心坎上，持续______福祉。","options":["增添","增殖","增进","增加"],"answer":2,"explanation":"「增进」与「民生」搭配得当。「增进福祉」为固定搭配，题干以民生统称；「增加」多与数量搭配；「增添」多与色彩、麻烦搭配；「增殖」为生物学用语。故选C。","__sub":"选词填空"},{"id":"yy-18566","module":"yanyu","diff":1,"exam":"省考","prompt":"连日来，新区建设的宏伟蓝图已经展开，医护人员正把一张张蓝图变成施工图。","options":["绘就","修筑","耕耘","编织"],"answer":0,"explanation":"「绘就」与「蓝图」搭配得当。「绘就蓝图」为惯用搭配；「修筑」用于道路工事；「耕耘」用于田地或比喻辛勤付出；「编织」多与梦想、纽带搭配，与蓝图不搭。故选A。","__sub":"选词填空"},{"id":"yy-18567","module":"yanyu","diff":2,"exam":"国考","prompt":"连日来，发展为了人民，基层干部把一件件民生实事办到群众心坎上，持续______福祉。","options":["增进","增加","增殖","增添"],"answer":0,"explanation":"「增进」与「民生」搭配得当。「增进福祉」为固定搭配，题干以民生统称；「增加」多与数量搭配；「增添」多与色彩、麻烦搭配；「增殖」为生物学用语。故选A。","__sub":"选词填空"},{"id":"yy-18568","module":"yanyu","diff":1,"exam":"省考","prompt":"今年以来，一揽子政策精准落地，环卫工人着力______市场信心。","options":["提起","振作","提振","鼓动"],"answer":2,"explanation":"「提振」与「信心」搭配得当。「提振信心」为固定搭配；「提起」多与精神、话题搭配；「振作」为不及物动词；「鼓动」含煽动义。故选C。","__sub":"选词填空"},{"id":"yy-18569","module":"yanyu","diff":2,"exam":"国考","prompt":"近年来，市场不是法外之地，环卫工人以制度______交易秩序。","options":["规正","规范","规定","规整"],"answer":1,"explanation":"「规范」与「秩序」搭配得当。「规范秩序」为惯用搭配；「规定」为名词或动词制定；「规整」指整齐；「规正」指匡正。故选B。","__sub":"选词填空"},{"id":"yy-18570","module":"yanyu","diff":2,"exam":"事业编","prompt":"眼下，安全底线不可逾越，审计人员24小时轮班值守。","options":["看守","镇守","把守","坚守"],"answer":3,"explanation":"「坚守」与「底线」搭配得当。「坚守底线」为固定搭配；「看守」「把守」「镇守」均指具体看护动作，多用于人员、关口、城池。故选D。","__sub":"选词填空"},{"id":"yy-18571","module":"yanyu","diff":1,"exam":"国考","prompt":"入冬以来，一次次说到做到，文旅部门用行动______了群众的信任。","options":["博得","换取","赢得","获得"],"answer":2,"explanation":"「赢得」与「信任」搭配得当。「赢得信任」为固定搭配，强调经努力而获得；「获得」中性；「博得」多与同情、喝彩搭配；「换取」含交换义。故选C。","__sub":"选词填空"},{"id":"yy-18572","module":"yanyu","diff":2,"exam":"国考","prompt":"眼下，数据孤岛必须连起来，教师下决心______部门间的壁垒。","options":["砸破","打破","击碎","打碎"],"answer":1,"explanation":"「打破」与「壁垒」搭配得当。「打破壁垒」为固定搭配；「打碎」「砸破」「击碎」均为具体物理动作。故选B。","__sub":"选词填空"},{"id":"yy-18573","module":"yanyu","diff":2,"exam":"医疗编","prompt":"一段时间以来，一网通办让数据多跑路，铁路养护工以流程再造______政务效能。","options":["抬高","拔高","提升","提高"],"answer":2,"explanation":"「提升」与「效能」搭配得当。「提升效能」为固定搭配；「提高」多与水平、价格搭配；「拔高」含刻意抬升义；「抬高」多与价格、身价搭配。故选C。","__sub":"选词填空"},{"id":"yy-18574","module":"yanyu","diff":1,"exam":"教师编","prompt":"盛夏时节，绿水青山就是金山银山，老党员代代接力______绿色生态。","options":["守望","守护","守候","看守"],"answer":1,"explanation":"「守护」与「生态」搭配得当。「守护生态」为惯用搭配，含珍视呵护义；「看守」用于财物、门户；「守候」指等待；「守望」指瞭望盼望。故选B。","__sub":"选词填空"},{"id":"yy-18575","module":"yanyu","diff":2,"exam":"教师编","prompt":"初秋时节，市场不是法外之地，社区工作者以制度______交易秩序。","options":["规范","规定","规整","规正"],"answer":0,"explanation":"「规范」与「秩序」搭配得当。「规范秩序」为惯用搭配；「规定」为名词或动词制定；「规整」指整齐；「规正」指匡正。故选A。","__sub":"选词填空"},{"id":"yy-18576","module":"yanyu","diff":2,"exam":"省考","prompt":"近年来，产业发展的根基越牢，抗风险的能力就越强，驻村干部深谙此理，先把根基打扎实。","options":["垒砌","铺设","敲打","夯实"],"answer":3,"explanation":"「夯实」与「根基」搭配得当。「夯实根基」为固定搭配；「敲打」为具体动作；「铺设」用于管线、路面；「垒砌」用于砖石墙体。故选D。","__sub":"选词填空"},{"id":"yy-18577","module":"yanyu","diff":2,"exam":"国考","prompt":"近年来，乡情是最深的牵挂，法官以商会为平台______情感纽带。","options":["织牢","捆牢","系牢","绑牢"],"answer":0,"explanation":"「织牢」与「纽带」搭配得当。「织牢纽带」为惯用比喻搭配；「系牢」「捆牢」「绑牢」均为具体系绑动作。故选A。","__sub":"选词填空"},{"id":"yy-18578","module":"yanyu","diff":2,"exam":"国考","prompt":"近期，每一起案件都关乎群众对法治的信仰，执法人员用公正裁判______正义。","options":["护卫","捍卫","保卫","防御"],"answer":1,"explanation":"「捍卫」与「公平」搭配得当。「捍卫公平」为书面惯用搭配；「保卫」多与祖国、和平搭配；「护卫」为护送守卫；「防御」用于军事、疫情。故选B。","__sub":"选词填空"},{"id":"yy-18579","module":"yanyu","diff":2,"exam":"国考","prompt":"入冬以来，把资源优势变成产业优势，果农下大气力______区域品牌。","options":["拍打","打造","打制","锻打"],"answer":1,"explanation":"「打造」与「品牌」搭配得当。「打造品牌」为固定搭配；「打制」「锻打」用于金属器物；「拍打」为具体动作。故选B。","__sub":"选词填空"},{"id":"yy-18580","module":"yanyu","diff":2,"exam":"国考","prompt":"近期，民生实事清单公示上墙，乡村医生一件一件______承诺。","options":["达成","实现","兑现","完成"],"answer":2,"explanation":"「兑现」与「承诺」搭配得当。「兑现承诺」为固定搭配；「实现」多与梦想、目标搭配；「完成」多与任务搭配；「达成」多与协议搭配。故选C。","__sub":"选词填空"},{"id":"yy-18581","module":"yanyu","diff":2,"exam":"国考","prompt":"盛夏时节，一二三产融合发展，网格员推动产业链不断延伸。","options":["拉长","伸长","延伸","延长"],"answer":2,"explanation":"「延伸」与「链条」搭配得当。「链条延伸」为惯用搭配；「伸长」「拉长」「延长」多用于具体长度或时间。故选C。","__sub":"选词填空"},{"id":"yy-18582","module":"yanyu","diff":2,"exam":"国考","prompt":"近期，让要素流动更顺畅，就要______体制机制的藩篱。","options":["破除","铲平","拆除","捣毁"],"answer":0,"explanation":"「破除」与「藩篱」搭配得当。「破除藩篱」为固定搭配；「拆除」用于建筑；「铲平」用于场地；「捣毁」用于巢穴、据点且含暴力义。故选A。","__sub":"选词填空"},{"id":"yy-18583","module":"yanyu","diff":2,"exam":"省考","prompt":"入冬以来，一二三产融合发展，公交司机推动产业链不断延伸。","options":["伸长","延长","拉长","延伸"],"answer":3,"explanation":"「延伸」与「链条」搭配得当。「链条延伸」为惯用搭配；「伸长」「拉长」「延长」多用于具体长度或时间。故选D。","__sub":"选词填空"},{"id":"yy-18584","module":"yanyu","diff":2,"exam":"国考","prompt":"岁末年初，两岸同胞亲情割不断，广大建设者为青年交流______心灵心桥。","options":["架起","垒砌","修筑","铺设"],"answer":0,"explanation":"「架起」与「心桥」搭配得当。「架起心桥」为惯用比喻搭配；「修筑」用于道路工程；「垒砌」用于砖石；「铺设」用于管线轨道。故选A。","__sub":"选词填空"},{"id":"yy-18585","module":"yanyu","diff":3,"exam":"国考","prompt":"岁末年初，老厂房变身文创园，治沙工人让工业遗存______新的活力。","options":["更新","换发","焕新","焕发"],"answer":3,"explanation":"「焕发」与「活力」搭配得当。「焕发活力」为固定搭配；「换发」为误写；「焕新」「更新」多用于设施、面貌且为动词直接带宾语。故选D。","__sub":"选词填空"},{"id":"yy-18586","module":"yanyu","diff":2,"exam":"教师编","prompt":"入冬以来，小哨兵大作用，果农让基层网格______更大作用。","options":["发扬","施展","表现","发挥"],"answer":3,"explanation":"「发挥」与「作用」搭配得当。「发挥作用」为固定搭配；「发扬」多与传统搭配；「施展」多与才华、拳脚搭配。故选D。","__sub":"选词填空"},{"id":"yy-18587","module":"yanyu","diff":1,"exam":"事业编","prompt":"盛夏时节，每一起案件都关乎群众对法治的信仰，治沙工人用公正裁判______正义。","options":["防御","保卫","护卫","捍卫"],"answer":3,"explanation":"「捍卫」与「公平」搭配得当。「捍卫公平」为书面惯用搭配；「保卫」多与祖国、和平搭配；「护卫」为护送守卫；「防御」用于军事、疫情。故选D。","__sub":"选词填空"},{"id":"yy-18588","module":"yanyu","diff":3,"exam":"国考","prompt":"入冬以来，民生领域还有欠账，基层干部列出清单逐项______短板。","options":["补丁","修补","贴补","补齐"],"answer":3,"explanation":"「补齐」与「短板」搭配得当。「补齐短板」为固定搭配；「补丁」为名词；「修补」多用于衣物器物；「贴补」多与费用搭配。故选D。","__sub":"选词填空"},{"id":"yy-18589","module":"yanyu","diff":2,"exam":"省考","prompt":"入冬以来，几十年如一日，农技人员在平凡岗位上______着为民初心。","options":["把守","守卫","保守","坚守"],"answer":3,"explanation":"「坚守」与「初心」搭配得当。「坚守初心」为固定搭配；「保守」多与秘密搭配；「守卫」用于边疆、家园；「把守」用于关口。故选D。","__sub":"选词填空"},{"id":"yy-18590","module":"yanyu","diff":1,"exam":"国考","prompt":"连日来，内生动力从哪里来？民警把功夫下在创新上。","options":["增强","增添","增大","加强"],"answer":0,"explanation":"「增强」与「动力」搭配得当。「增强动力」为固定搭配；「加强」多与领导、管理搭配；「增大」多与幅度、剂量搭配。故选A。","__sub":"选词填空"},{"id":"yy-18591","module":"yanyu","diff":2,"exam":"国考","prompt":"这些年，初心如磐，使命在肩，市场监管部门把承诺落到一件件小事上。","options":["执行","旅行","履行","践行"],"answer":3,"explanation":"「践行」与「使命」搭配得当。「践行使命」为固定搭配；「履行」多与职责、义务、合同搭配；「执行」多与命令、判决、任务搭配；「旅行」为出行义。故选D。","__sub":"选词填空"},{"id":"yy-18592","module":"yanyu","diff":2,"exam":"国考","prompt":"这些年，民生领域还有欠账，非遗传承人列出清单逐项______短板。","options":["补丁","补齐","贴补","修补"],"answer":1,"explanation":"「补齐」与「短板」搭配得当。「补齐短板」为固定搭配；「补丁」为名词；「修补」多用于衣物器物；「贴补」多与费用搭配。故选B。","__sub":"选词填空"},{"id":"yy-18593","module":"yanyu","diff":3,"exam":"教师编","prompt":"眼下，汛期将至，护林员对辖区地质灾害隐患逐点______。","options":["检查","排查","普查","检察"],"answer":1,"explanation":"「排查」与「隐患」搭配得当。「排查隐患」为固定搭配，强调逐一清查；「检查」为一般查看；「检察」为法律监督专用；「普查」为全面调查登记。故选B。","__sub":"选词填空"},{"id":"yy-18594","module":"yanyu","diff":3,"exam":"国考","prompt":"这些年，老工业基地涅槃重生，教师加快新旧动能步伐。","options":["改换","转变","变换","转换"],"answer":3,"explanation":"「转换」与「动能」搭配得当。「动能转换」为固定搭配；「转变」多与观念、方式搭配；「改换」「变换」多与门庭、姿势搭配。故选D。","__sub":"选词填空"},{"id":"yy-18595","module":"yanyu","diff":2,"exam":"省考","prompt":"开春以来，让公共服务覆盖城乡，铁路养护工持续______政策体系。","options":["修完","完善","完缮","补完"],"answer":1,"explanation":"「完善」与「体系」搭配得当。「完善体系」为固定搭配；「完缮」「修完」「补完」均非规范搭配。故选B。","__sub":"选词填空"},{"id":"yy-18596","module":"yanyu","diff":2,"exam":"事业编","prompt":"近期，内生动力从哪里来？果农把功夫下在创新上。","options":["增添","增强","增大","加强"],"answer":1,"explanation":"「增强」与「动力」搭配得当。「增强动力」为固定搭配；「加强」多与领导、管理搭配；「增大」多与幅度、剂量搭配。故选B。","__sub":"选词填空"},{"id":"yy-18597","module":"yanyu","diff":3,"exam":"省考","prompt":"入冬以来，停车难是城市治理的老大难，茶农用共享思维______了这一难题。","options":["解开","解冻","解释","破解"],"answer":3,"explanation":"「破解」与「难题」搭配得当。「破解难题」为固定搭配；「解开」多与绳结、心结搭配；「解冻」用于资产、关系；「解释」为说明缘由。故选D。","__sub":"选词填空"},{"id":"yy-18598","module":"yanyu","diff":1,"exam":"事业编","prompt":"连日来，纪律规矩挺在前面，渔民始终______纪律底线。","options":["把守","看守","遵守","严守"],"answer":3,"explanation":"「严守」与「底线」搭配得当。「严守底线」为固定搭配；「看守」「把守」为具体看护；「遵守」多与规则、法律搭配。故选D。","__sub":"选词填空"},{"id":"yy-18599","module":"yanyu","diff":2,"exam":"国考","prompt":"近期，汛期将至，环卫工人对辖区地质灾害隐患逐点______。","options":["检察","检查","排查","普查"],"answer":2,"explanation":"「排查」与「隐患」搭配得当。「排查隐患」为固定搭配，强调逐一清查；「检查」为一般查看；「检察」为法律监督专用；「普查」为全面调查登记。故选C。","__sub":"选词填空"},{"id":"yy-18600","module":"yanyu","diff":2,"exam":"事业编","prompt":"今年以来，一次次说到做到，渔民用行动______了群众的信任。","options":["博得","赢得","获得","换取"],"answer":1,"explanation":"「赢得」与「信任」搭配得当。「赢得信任」为固定搭配，强调经努力而获得；「获得」中性；「博得」多与同情、喝彩搭配；「换取」含交换义。故选B。","__sub":"选词填空"},{"id":"yy-18601","module":"yanyu","diff":2,"exam":"事业编","prompt":"初秋时节，红色资源是最生动的教材，农技人员让红色血脉代代相传。","options":["接续","继续","延续","赓续"],"answer":3,"explanation":"「赓续」与「血脉」搭配得当。「赓续血脉」为书面惯用搭配；「继续」为一般动词；「接续」多与手续、产业搭配；「延续」多与生命、文脉搭配。故选D。","__sub":"选词填空"},{"id":"yy-18602","module":"yanyu","diff":2,"exam":"省考","prompt":"眼下，放宽准入激发创业热情，市场监管部门让创造活力。","options":["淌出","涌出","涌流","流出"],"answer":2,"explanation":"「涌流」与「活力」搭配得当。「活力涌流」为惯用表达；「流出」「淌出」「涌出」均用于液体且为具体动作。故选C。","__sub":"选词填空"},{"id":"yy-18603","module":"yanyu","diff":2,"exam":"事业编","prompt":"入冬以来，停车难是城市治理的老大难，志愿者们用共享思维______了这一难题。","options":["解释","破解","解开","解冻"],"answer":1,"explanation":"「破解」与「难题」搭配得当。「破解难题」为固定搭配；「解开」多与绳结、心结搭配；「解冻」用于资产、关系；「解释」为说明缘由。故选B。","__sub":"选词填空"},{"id":"yy-18604","module":"yanyu","diff":1,"exam":"省考","prompt":"盛夏时节，放宽准入激发创业热情，医护人员让创造活力。","options":["淌出","涌流","流出","涌出"],"answer":1,"explanation":"「涌流」与「活力」搭配得当。「活力涌流」为惯用表达；「流出」「淌出」「涌出」均用于液体且为具体动作。故选B。","__sub":"选词填空"},{"id":"yy-18605","module":"yanyu","diff":2,"exam":"国考","prompt":"一段时间以来，市场细胞活跃起来，乡村医生让经济肌体活力。","options":["填满","充满","塞满","装满"],"answer":1,"explanation":"「充满」与「活力」搭配得当。「充满活力」为固定搭配；「填满」「塞满」「装满」均为具体动作，用于抽象活力不当。故选B。","__sub":"选词填空"},{"id":"yy-18606","module":"yanyu","diff":1,"exam":"国考","prompt":"一段时间以来，每个孩子都有闪光点，青年学子善于______学生潜能。","options":["开采","掘取","挖出","挖掘"],"answer":3,"explanation":"「挖掘」与「潜能」搭配得当。「挖掘潜能」为固定搭配；「挖出」「掘取」为具体动作；「开采」用于矿产。故选D。","__sub":"选词填空"},{"id":"yy-18607","module":"yanyu","diff":3,"exam":"事业编","prompt":"初秋时节，每个孩子都有闪光点，法官善于______学生潜能。","options":["开采","掘取","挖出","挖掘"],"answer":3,"explanation":"「挖掘」与「潜能」搭配得当。「挖掘潜能」为固定搭配；「挖出」「掘取」为具体动作；「开采」用于矿产。故选D。","__sub":"选词填空"},{"id":"yy-18608","module":"yanyu","diff":1,"exam":"医疗编","prompt":"入冬以来，放宽准入激发创业热情，果农让创造活力。","options":["淌出","流出","涌流","涌出"],"answer":2,"explanation":"「涌流」与「活力」搭配得当。「活力涌流」为惯用表达；「流出」「淌出」「涌出」均用于液体且为具体动作。故选C。","__sub":"选词填空"},{"id":"yy-18609","module":"yanyu","diff":3,"exam":"国考","prompt":"近年来，古城修缮不搞大拆大建，果农让千年文脉在街巷间静静流淌。","options":["接通","延续","连接","续接"],"answer":1,"explanation":"「延续」与「文脉」搭配得当。「延续文脉」为惯用搭配；「连接」指具体相连；「续接」多与线路搭配；「接通」用于电话、电路。故选B。","__sub":"选词填空"},{"id":"yy-18610","module":"yanyu","diff":1,"exam":"省考","prompt":"岁末年初，老厂房变身文创园，公交司机让工业遗存______新的活力。","options":["焕发","更新","焕新","换发"],"answer":0,"explanation":"「焕发」与「活力」搭配得当。「焕发活力」为固定搭配；「换发」为误写；「焕新」「更新」多用于设施、面貌且为动词直接带宾语。故选A。","__sub":"选词填空"},{"id":"yy-18611","module":"yanyu","diff":2,"exam":"国考","prompt":"盛夏时节，一年一度的民生大考结束，社区规划师向群众______了温暖的答卷。","options":["呈报","上缴","递交","交出"],"answer":3,"explanation":"「交出」与「答卷」搭配得当。「交出答卷」为惯用搭配；「递交」多与申请、辞呈搭配；「呈报」多与公文搭配且含上下级意味；「上缴」多与款项、物品搭配。故选D。","__sub":"选词填空"},{"id":"yy-18612","module":"yanyu","diff":2,"exam":"国考","prompt":"今年以来，手握核心技术专利，网格员创新的底气。","options":["更壮","更足","更强","更硬"],"answer":1,"explanation":"「更足」与「底气」搭配得当。「底气更足」为惯用搭配；「更硬」多与作风搭配；「更强」多与实力搭配；「更壮」用于体格。故选B。","__sub":"选词填空"},{"id":"yy-18613","module":"yanyu","diff":1,"exam":"省考","prompt":"眼下，订单排到明年，果农发展的信心。","options":["加倍","倍增","倍加","倍受"],"answer":1,"explanation":"「倍增」与「信心」搭配得当。「信心倍增」为惯用搭配；「加倍」为动词或副词；「倍加」多与珍惜搭配；「倍受」多与关注搭配。故选B。","__sub":"选词填空"},{"id":"yy-18614","module":"yanyu","diff":2,"exam":"省考","prompt":"今年以来，金杯银杯不如老百姓的口碑，驻村干部把每件小事都当大事办。","options":["树立","设立","创立","建立"],"answer":0,"explanation":"「树立」与「口碑」搭配得当。「树立口碑」为惯用搭配；「建立」多与制度、关系搭配；「设立」多与机构搭配；「创立」多与学说、品牌搭配。故选A。","__sub":"选词填空"},{"id":"yy-18615","module":"yanyu","diff":2,"exam":"国考","prompt":"这些年，在广袤乡野间，医护人员用汗水______出乡村振兴的崭新篇章。","options":["描红","誊写","书写","抄写"],"answer":2,"explanation":"「书写」与「篇章」搭配得当。「书写篇章」为惯用搭配；「抄写」「誊写」「描红」均为照原样复写的具体动作，缺乏开创义。故选C。","__sub":"选词填空"},{"id":"yy-18616","module":"yanyu","diff":2,"exam":"事业编","prompt":"眼下，数据孤岛必须连起来，护林员下决心______部门间的壁垒。","options":["砸破","打碎","打破","击碎"],"answer":2,"explanation":"「打破」与「壁垒」搭配得当。「打破壁垒」为固定搭配；「打碎」「砸破」「击碎」均为具体物理动作。故选C。","__sub":"选词填空"},{"id":"yy-18617","module":"yanyu","diff":1,"exam":"国考","prompt":"近期，让公共服务覆盖城乡，环卫工人持续______政策体系。","options":["完善","补完","完缮","修完"],"answer":0,"explanation":"「完善」与「体系」搭配得当。「完善体系」为固定搭配；「完缮」「修完」「补完」均非规范搭配。故选A。","__sub":"选词填空"},{"id":"yy-18618","module":"yanyu","diff":1,"exam":"国考","prompt":"入冬以来，邻里纠纷无小事，教师用真心______一件件矛盾。","options":["消融","解开","化解","瓦解"],"answer":2,"explanation":"「化解」与「矛盾」搭配得当。「化解矛盾」为固定搭配；「解开」多与疙瘩、谜团搭配；「消融」用于冰雪；「瓦解」多用于组织、士气。故选C。","__sub":"选词填空"},{"id":"yy-18619","module":"yanyu","diff":3,"exam":"国考","prompt":"一段时间以来，放宽准入激发创业热情，手工艺人让创造活力。","options":["流出","涌流","淌出","涌出"],"answer":1,"explanation":"「涌流」与「活力」搭配得当。「活力涌流」为惯用表达；「流出」「淌出」「涌出」均用于液体且为具体动作。故选B。","__sub":"选词填空"}]);